# ═══════════════════════════════════════════════════════════════════════

import hashlib
import hmac
import datetime as _security_datetime
from collections import defaultdict, deque

BOT_OWNER_ID = int(os.getenv("BOT_OWNER_ID", "0"))  # ← set this in .env
SECURITY_LOG_CHANNEL_ID = int(os.getenv("SECURITY_LOG_CHANNEL_ID", "0"))  # 0 = disabled

# Hash the PIN at startup so it's not sitting around as plaintext
def _hash_pin(pin_value: str) -> str:
    return hashlib.sha256(pin_value.encode("utf-8")).hexdigest()

_PIN_HASH = _hash_pin(ADMIN_PIN)

# Rate limiter — track failed attempts per user
_failed_attempts = defaultdict(lambda: deque(maxlen=10))  # uid -> deque of failure timestamps
_lockouts = {}  # uid -> unlock_timestamp
LOCKOUT_THRESHOLD = 3            # 3 failures...
LOCKOUT_WINDOW = 600             # ...within 10 minutes...
LOCKOUT_DURATION = 1800          # ...= 30 min lockout

async def verify_admin_pin(interaction: discord.Interaction, supplied_pin: str, action_label: str) -> bool:
    """Centralized PIN verification. Hashes the input, checks rate limits,
    DMs the bot owner, and logs to the security channel. Returns True only
    if the PIN matches AND the user isn't locked out.

    Usage: `if not await verify_admin_pin(interaction, pin, "awardvc"): return`
    """
    uid = str(interaction.user.id)
    now = time.time()

    # Check lockout status
    if uid in _lockouts and now < _lockouts[uid]:
        mins_left = int((_lockouts[uid] - now) / 60) + 1
        try:
            await interaction.response.send_message(
                f"🔒 **You are locked out for {mins_left} more minutes** due to repeated failed PIN attempts.",
                ephemeral=True
            )
        except Exception:
            try:
                await interaction.followup.send(
                    f"🔒 **You are locked out for {mins_left} more minutes** due to repeated failed PIN attempts.",
                    ephemeral=True
                )
            except Exception:
                pass
        await _alert_owner(interaction, action_label, success=False, reason=f"locked out, {mins_left}m remaining")
        return False

    # Constant-time hash comparison
    supplied_hash = _hash_pin(str(supplied_pin or ""))
    is_valid = hmac.compare_digest(supplied_hash, _PIN_HASH)

    if is_valid:
        # Reset failures on success
        if uid in _failed_attempts:
            _failed_attempts[uid].clear()
        await _alert_owner(interaction, action_label, success=True)
        return True

    # ===== FAILED PIN =====
    _failed_attempts[uid].append(now)
    # Trim attempts outside the window
    while _failed_attempts[uid] and (now - _failed_attempts[uid][0]) > LOCKOUT_WINDOW:
        _failed_attempts[uid].popleft()

    recent_failures = len(_failed_attempts[uid])

    # Lock them out if they hit the threshold
    if recent_failures >= LOCKOUT_THRESHOLD:
        _lockouts[uid] = now + LOCKOUT_DURATION
        _failed_attempts[uid].clear()
        await _alert_owner(interaction, action_label, success=False, reason=f"🚨 LOCKED OUT after {recent_failures} failed attempts")
    else:
        await _alert_owner(interaction, action_label, success=False, reason=f"wrong PIN ({recent_failures}/{LOCKOUT_THRESHOLD} strikes)")

    return False


async def _alert_owner(interaction: discord.Interaction, action_label: str, success: bool, reason: str = ""):
    """DM the bot owner and post to the security log channel."""
    user = interaction.user
    guild = interaction.guild.name if interaction.guild else "DM"
    channel_name = interaction.channel.name if hasattr(interaction.channel, 'name') else "?"
    status_emoji = "✅" if success else "🚨"
    color = 0x00cc44 if success else 0xff0000

    embed = discord.Embed(
        title=f"{status_emoji} Admin PIN — {'Success' if success else 'Failure'}",
        color=color,
        timestamp=_security_datetime.datetime.utcnow()
    )
    embed.add_field(name="👤 User", value=f"{user.mention}\n`{user}` ({user.id})", inline=True)
    embed.add_field(name="🎯 Action", value=f"`{action_label}`", inline=True)
    embed.add_field(name="📍 Location", value=f"{guild} → #{channel_name}", inline=False)
    if not success and reason:
        embed.add_field(name="⚠️ Detail", value=reason, inline=False)

    # DM the owner
    if BOT_OWNER_ID:
        try:
            owner = await bot.fetch_user(BOT_OWNER_ID)
            await owner.send(embed=embed)
        except Exception as e:
            print(f"[Security] Could not DM owner: {e}")

    # Post to security log channel if configured
    if SECURITY_LOG_CHANNEL_ID:
        try:
            channel = bot.get_channel(SECURITY_LOG_CHANNEL_ID)
            if channel:
                await channel.send(embed=embed)
        except Exception as e:
            print(f"[Security] Could not post to log channel: {e}")

    # Always log to terminal
    print(f"[Security] {status_emoji} {action_label} by {user} ({user.id}) — {'OK' if success else reason}")


def admin_pin_matches(supplied_pin: str, interaction: discord.Interaction = None, action_label: str = None) -> bool:
    """Hashed PIN check + automatic owner alerts.

    If interaction is provided, schedules a background alert to the bot owner
    (and security log channel) showing the attempt outcome. This makes every
    PIN check across the bot consistently audited without rewriting each
    command handler.
    """
    valid = hmac.compare_digest(_hash_pin(str(supplied_pin or "")), _PIN_HASH)

    # Fire-and-forget security alert if we have context to log
    if interaction is not None:
        label = action_label or (interaction.command.qualified_name if interaction.command else "unknown")
        uid = str(interaction.user.id)
        now = time.time()

        if valid:
            # Reset failure counter on a clean entry
            if uid in _failed_attempts:
                _failed_attempts[uid].clear()
            reason = ""
        else:
            # Track failure
            _failed_attempts[uid].append(now)
            while _failed_attempts[uid] and (now - _failed_attempts[uid][0]) > LOCKOUT_WINDOW:
                _failed_attempts[uid].popleft()
            recent = len(_failed_attempts[uid])

            if recent >= LOCKOUT_THRESHOLD:
                _lockouts[uid] = now + LOCKOUT_DURATION
                _failed_attempts[uid].clear()
                reason = f"🚨 LOCKED OUT after {recent} failed attempts"
            else:
                reason = f"wrong PIN ({recent}/{LOCKOUT_THRESHOLD} strikes)"

        # Block locked-out users from succeeding even with a valid PIN
        if uid in _lockouts and now < _lockouts[uid]:
            valid = False
            mins_left = int((_lockouts[uid] - now) / 60) + 1
            reason = f"locked out, {mins_left}m remaining"

        try:
            asyncio.create_task(_alert_owner(interaction, label, valid, reason if not valid else ""))
        except Exception as e:
            print(f"[Security] Could not schedule alert: {e}")

    return valid


