def _ollama_available():
    """True if a local model is configured (assumes Ollama is running)."""
    return bool(OLLAMA_MODEL)


def _ollama_generate(system_prompt, user_prompt, max_tokens=800):
    """Blocking call to the local Ollama server. Returns text or None.
    Raises on connection/HTTP errors so callers can fall through."""
    payload = {
        "model": OLLAMA_MODEL,
        "prompt": user_prompt,
        "system": system_prompt or "",
        "stream": False,
        "think": False,
        "options": {"num_predict": int(max_tokens), "num_ctx": 12288},
    }
    r = requests.post(f"{OLLAMA_URL.rstrip('/')}/api/generate", json=payload, timeout=OLLAMA_TIMEOUT)
    r.raise_for_status()
    data = r.json()
    text = (data.get("response") or "").strip()
    text = re.sub(r"<think>.*?</think>", "", text, flags=re.DOTALL).strip()
    return text or None


def _ai_label(src):
    """Friendly label for which brain answered."""
    return {
        "claude": "Claude",
        "gemini": "Gemini (fallback)",
        "local": f"Local model · {OLLAMA_MODEL} · 0 credits",
    }.get(src, "AI")


async def ask_ai(system_prompt, user_prompt, max_tokens=800,
                 claude_model="claude-sonnet-4-6", gemini_model="gemini-3.6-flash"):
    """Unified text LLM call for the whole bot.

    Tries the LOCAL Ollama model first (zero credits); on ANY failure — or if
    no local model is configured — it falls back to CLAUDE, then to GEMINI.
    Returns (text, source) where source is 'local', 'claude', or 'gemini'.
    Raises RuntimeError only if ALL configured providers are unavailable/failed."""
    # 1) Local Ollama model first — zero credits, fully offline
    if _ollama_available():
        try:
            def _o():
                return _ollama_generate(system_prompt, user_prompt, max_tokens)
            txt = await asyncio.to_thread(_o)
            if txt:
                return txt, "local"
            print("[ask_ai] Local model returned no text — falling back to Claude")
        except Exception as e:
            print(f"[ask_ai] Local model failed ({type(e).__name__}: {str(e)[:200]}) — falling back to Claude")

    # 2) Claude fallback
    if claude_client is not None:
        try:
            def _c():
                kwargs = {"model": claude_model, "max_tokens": max_tokens,
                          "messages": [{"role": "user", "content": user_prompt}]}
                if system_prompt:
                    kwargs["system"] = system_prompt
                return claude_client.messages.create(**kwargs)
            resp = await asyncio.to_thread(_c)
            txt = resp.content[0].text if getattr(resp, "content", None) else None
            if txt:
                return txt, "claude"
            print("[ask_ai] Claude returned empty text — falling back to Gemini")
        except Exception as e:
            print(f"[ask_ai] Claude failed ({type(e).__name__}: {str(e)[:200]}) — falling back to Gemini")

    # 3) Gemini fallback (deep net)
    if ai_client is not None:
        try:
            # This Gemini SDK call has no separate system role — prepend it.
            contents = (system_prompt + "\n\n" + user_prompt) if system_prompt else user_prompt
            def _g():
                return ai_client.models.generate_content(model=gemini_model, contents=contents)
            resp = await asyncio.to_thread(_g)
            txt = getattr(resp, "text", None)
            if not txt:
                try:
                    parts = resp.candidates[0].content.parts
                    txt = "".join(getattr(p, "text", "") for p in parts).strip() or None
                except Exception:
                    txt = None
            if txt:
                return txt, "gemini"
            print("[ask_ai] Gemini returned no text")
        except Exception as e:
            print(f"[ask_ai] Gemini failed ({type(e).__name__}: {str(e)[:200]})")

    raise RuntimeError("No AI available (local Ollama, Claude, and Gemini all unavailable).")

