# --- 4. 1287 MONTE CARLO & BETTING ENGINE ---

# --- ADVANCED MATCHUP MODIFIERS ---
MATCHUP_MODIFIERS = {
    "Slasher": {"RimProtector": 0.85, "PerimeterLock": 1.05, "DropCoverage": 1.10},
    "Sharpshooter": {"RimProtector": 1.10, "PerimeterLock": 0.80, "DropCoverage": 1.15},
    "Playmaker": {"RimProtector": 1.0, "PerimeterLock": 0.90, "DropCoverage": 1.05},
    "PostScorer": {"RimProtector": 0.80, "PerimeterLock": 1.15, "DropCoverage": 1.0},
    "TwoWay": {"RimProtector": 0.95, "PerimeterLock": 0.95, "DropCoverage": 1.0}
}

def determine_team_defense(team_name, df):
    p_df = df[(df['Type'].str.lower() == 'player') & (df['Team Name'].str.lower() == team_name.lower())]
    if p_df.empty: return "DropCoverage"
    avg_blk = p_df.groupby('Player/Team')['BLK'].mean().sum()
    avg_stl = p_df.groupby('Player/Team')['STL'].mean().sum()
    if avg_blk >= 4.5: return "RimProtector"
    if avg_stl >= 7.0: return "PerimeterLock"
    return "DropCoverage"

def build_roster_profiles(team_name, df):
    p_df = df[(df['Type'].str.lower() == 'player') & (df['Team Name'].str.lower() == team_name.lower())].copy()
    if p_df.empty: return []
    current_szn = p_df['Season'].max()
    roster = []
    for player in p_df['Player/Team'].unique():
        pdf = p_df[p_df['Player/Team'] == player]
        curr_df = pdf[pdf['Season'] == current_szn]
        hist_df = pdf[pdf['Season'] < current_szn]
        if curr_df.empty: continue
        
        p_avg = curr_df.mean(numeric_only=True)
        if p_avg.get('3PA', 0) > 4.5: arch = "Sharpshooter"
        elif p_avg.get('AST', 0) > 5.0: arch = "Playmaker"
        elif p_avg.get('REB', 0) > 8.0: arch = "PostScorer"
        elif (p_avg.get('STL', 0) + p_avg.get('BLK', 0)) > 3.0: arch = "TwoWay"
        else: arch = "Slasher"
        
        roster.append({
            "name": player,
            "type": arch,
            "pts_20": curr_df['PTS'].mean(),
            "hist_pts_20": hist_df['PTS'].mean() if not hist_df.empty else curr_df['PTS'].mean(),
            "fouls_20": curr_df['FOULS'].mean(),
            "hist_fouls_20": hist_df['FOULS'].mean() if not hist_df.empty else curr_df['FOULS'].mean()
        })
    return roster

def calculate_player_projection(player, opp_defense_type, mins_to_play=20):
    blended_pts = (player['pts_20'] * 0.7) + (player['hist_pts_20'] * 0.3)
    blended_fouls = (player['fouls_20'] * 0.7) + (player['hist_fouls_20'] * 0.3)
    modifier = MATCHUP_MODIFIERS.get(player['type'], {}).get(opp_defense_type, 1.0)
    adjusted_pts = blended_pts * modifier
    scale_factor = mins_to_play / 20.0
    return adjusted_pts * scale_factor, blended_fouls * scale_factor, (adjusted_pts * scale_factor) * 0.25

def calculate_rivalry_index(team1, team2, df):
    t1, t2 = team1.title(), team2.title()
    matchups = df[(df['Type'].str.lower() == 'team') & (df['Team Name'] == t1) & (df['Opp_Name'] == t2)]
    games_played = len(matchups)
    playoff_games = len(matchups[matchups['Game_ID'] >= 9000])
    
    if playoff_games > 0 and games_played >= 2: return "🩸 Blood Feud (Deep Playoff History)"
    elif games_played >= 4: return "⚔️ Bitter Rivals (Extensive History)"
    elif games_played >= 2: return "🤝 Familiar Foes"
    return "🆕 First Encounters"

def simulate_granular_matchup(team1, team2, df, is_playoffs=False, is_tournament=False, iterations=2500):
    t1_def = determine_team_defense(team1, df)
    t2_def = determine_team_defense(team2, df)
    t1_roster = build_roster_profiles(team1, df)
    t2_roster = build_roster_profiles(team2, df)
    
    pressure_multiplier = 1.15 if is_playoffs else (1.08 if is_tournament else 1.0)
    t1_wins, total_pts_sim = 0, 0
    t1_sim_pts, t2_sim_pts = [], []
    
    for _ in range(iterations):
        t1_score, t2_score = 0, 0
        for p in t1_roster:
            proj_pts, proj_fouls, var = calculate_player_projection(p, t2_def)
            sim_fouls = max(0, int(random.gauss(proj_fouls, 1.5)))
            sim_pts = max(0, random.gauss(proj_pts, var * pressure_multiplier))
            if sim_fouls >= 6: sim_pts *= 0.75 
            t1_score += sim_pts
            
        for p in t2_roster:
            proj_pts, proj_fouls, var = calculate_player_projection(p, t1_def)
            sim_fouls = max(0, int(random.gauss(proj_fouls, 1.5)))
            sim_pts = max(0, random.gauss(proj_pts, var * pressure_multiplier))
            if sim_fouls >= 6: sim_pts *= 0.75
            t2_score += sim_pts
            
        if t1_score > t2_score: t1_wins += 1
        total_pts_sim += (t1_score + t2_score)
        t1_sim_pts.append(t1_score)
        t2_sim_pts.append(t2_score)
        
    rivalry_status = calculate_rivalry_index(team1, team2, df)
        
    return {
        "Matchup_Context": {"Rivalry_Level": rivalry_status, "Is_Playoffs": is_playoffs, "Is_Tournament": is_tournament},
        "Team1": {"Name": team1, "Def_Scheme": t1_def, "Roster": t1_roster, "Proj_Pts": round(np.median(t1_sim_pts), 1) if t1_sim_pts else 0},
        "Team2": {"Name": team2, "Def_Scheme": t2_def, "Roster": t2_roster, "Proj_Pts": round(np.median(t2_sim_pts), 1) if t2_sim_pts else 0},
        "Win_Prob": {"Team1": round((t1_wins/iterations)*100, 1), "Team2": round((1 - (t1_wins/iterations))*100, 1)},
        "Proj_Total": round(total_pts_sim/iterations, 1)
    }

def run_1287_monte_carlo(team1, team2, is_series=True):
    p_df, t_df = load_data()
    if p_df is None: return [], "Stat engine warming up."

    state = load_state()

    _pnorm = lambda s: re.sub(r'[^a-z0-9]', '', str(s).lower())
    _name_map = {}
    try:
        for _nm in p_df['PlayerName'].dropna().unique():
            _name_map.setdefault(_pnorm(_nm), str(_nm))
    except Exception:
        pass

    def _official_page_names(team_name):
        """Player names for a team from the OFFICIAL roster snapshot."""
        try:
            roster = json.load(open(os.path.join(_BASE_DIR, "roster.json"), encoding="utf-8"))
        except Exception:
            return []
        tn = _pnorm(team_name)
        members = roster.get('members') or {}
        for page_team, page in (roster.get('team_pages') or {}).items():
            pt = _pnorm(page_team)
            if pt and tn and (pt == tn or pt in tn or tn in pt):
                out = []
                for entry in page.get('combined', []):
                    rec = members.get(entry.get('uid'), {})
                    nm = rec.get('matched_player') or rec.get('display_name')
                    if nm:
                        out.append(str(nm))
                return out
        return []

    def get_top_players(team_name):
        # ROSTER-SCOPED PLAYER POOL (bugfix): props for a matchup may ONLY come
        # from THIS team's own roster. resolve_team_roster() is the same source
        # of truth the rest of the bot uses (coach roster > live role > legacy >
        # users map), so a player from a team that isn't in the matchup can no
        # longer leak onto the board. Names are matched to stat history by EXACT
        # normalized key only — no substring guessing that cross-wired teams.
        try:
            members, _meta = resolve_team_roster(team_name, state)
        except Exception:
            members = []
        roster_names = []
        for m in members:
            nm = (m or {}).get('name')
            if nm and nm != '(unknown)' and nm not in roster_names:
                roster_names.append(nm)

        if roster_names:
            hits = []
            for nm in roster_names:
                hit = _name_map.get(_pnorm(nm))   # exact normalized match only
                if hit and hit not in hits:
                    hits.append(hit)
            if hits:
                team_p_df = p_df[p_df['PlayerName'].isin(hits)]
                if not team_p_df.empty:
                    return team_p_df.groupby('PlayerName').sum().nlargest(5, 'Impact').index.tolist()
            # Roster is real but nobody has stat history yet (new players):
            # return [] so the engine opens even lines instead of borrowing
            # another team's players.
            return []

        # No resolvable roster at all — last-resort legacy JSON, still scoped.
        active_roster = state.get('rosters', {}).get(team_name, {}).get('active', [])
        if active_roster:
            active_lower = [p.lower() for p in active_roster]
            team_p_df = p_df[p_df['PlayerName'].str.lower().isin(active_lower)]
            if not team_p_df.empty:
                return team_p_df.groupby('PlayerName').sum().nlargest(5, 'Impact').index.tolist()
        return []

    t1_p = get_top_players(team1)
    t2_p = get_top_players(team2)
    
    # Both teams completely new: SEASON OPENING LINES — even board, league baseline
    if not t1_p and not t2_p:
        bets = [
            f"{team1} Moneyline (-105)", f"{team2} Moneyline (-105)",
            f"{team1} +0.5 Spread (-110)", f"{team2} +0.5 Spread (-110)",
            "Game O/U 148.5 Total Points (-110)",
            f"{team1} Team Total O/U 74.5 (-110)", f"{team2} Team Total O/U 74.5 (-110)",
            f"Race to 20 Points: {team1} (-110)", f"Race to 20 Points: {team2} (-110)",
            "Any Player to record a Double-Double (+150)",
            "Any Player to record a Triple-Double (+450)",
            "Either team wins by 15+ (+240)",
            "Game to go to Overtime (+850)",
            "Both Teams to Score 60+ Points (+140)",
            f"Lead at Halftime: {team1} (-110)", f"Lead at Halftime: {team2} (-110)",
            "Any Player 5+ Steals (+350)", "Any Player to score 30+ PTS (+200)",
            "Any Player 15+ AST (+320)", "Any Player 15+ REB (+300)",
        ]
        readout = (f"\U0001F305 **SEASON OPENING LINES** \u2014 {team1} vs {team2}\n"
                   "Both squads are debuting, so the book opens **dead even** at the league baseline "
                   "(74 PPG). Player props unlock automatically once each side logs a game.")
        return bets, readout

    def get_opp_ppg(t_name):
        team_games = t_df[t_df['TeamName'].str.lower() == t_name.lower()]
        if not team_games.empty and 'PTS_Opp' in team_games.columns:
            val = team_games['PTS_Opp'].mean()
            if pd.notna(val) and val > 0: return val
        return 74.0 # Baseline QCL Opponent PPG if missing

    bets = []
    t1_proj_score = np.zeros(1287)
    t2_proj_score = np.zeros(1287)
    
    # Process Team 1
    if t1_p:
        for p in t1_p:
            logs = p_df[p_df['PlayerName'] == p].sort_values('Game_ID', ascending=False)
            if logs.empty: continue
            l5 = logs.head(5)
            pts_mean = (l5['PTS'].mean() * 0.6) + (logs['PTS'].mean() * 0.4)
            reb_mean = (l5['REB'].mean() * 0.6) + (logs['REB'].mean() * 0.4)
            ast_mean = (l5['AST'].mean() * 0.6) + (logs['AST'].mean() * 0.4)
            pts_std = logs['PTS'].std() if len(logs) > 2 else 3.0
            
            sim_pts = np.maximum(0, np.random.normal(pts_mean, pts_std, 1287))
            sim_reb = np.maximum(0, np.random.normal(reb_mean, logs['REB'].std() if len(logs)>2 else 2.0, 1287))
            sim_ast = np.maximum(0, np.random.normal(ast_mean, logs['AST'].std() if len(logs)>2 else 2.0, 1287))
            
            t1_proj_score += sim_pts
            
            if len(bets) < 20:
                pts_line = math.ceil(np.median(sim_pts) * 2) / 2
                reb_line = math.ceil(np.median(sim_reb) * 2) / 2
                ast_line = math.ceil(np.median(sim_ast) * 2) / 2
                if pts_line > 2: bets.append(f"{p} O/U {pts_line} PTS (-110)")
                if reb_line > 1: bets.append(f"{p} O/U {reb_line} REB (-110)")
                if ast_line > 1: bets.append(f"{p} O/U {ast_line} AST (-110)")
    else:
        # Team 1 is new. Base score off Team 2's average points allowed minus a 2.5-point buffer
        t2_allowed = get_opp_ppg(team2)
        t1_proj_score = np.maximum(0, np.random.normal(t2_allowed - 2.5, 5.0, 1287))

    # Process Team 2
    if t2_p:
        for p in t2_p:
            logs = p_df[p_df['PlayerName'] == p].sort_values('Game_ID', ascending=False)
            if logs.empty: continue
            l5 = logs.head(5)
            pts_mean = (l5['PTS'].mean() * 0.6) + (logs['PTS'].mean() * 0.4)
            reb_mean = (l5['REB'].mean() * 0.6) + (logs['REB'].mean() * 0.4)
            ast_mean = (l5['AST'].mean() * 0.6) + (logs['AST'].mean() * 0.4)
            pts_std = logs['PTS'].std() if len(logs) > 2 else 3.0
            
            sim_pts = np.maximum(0, np.random.normal(pts_mean, pts_std, 1287))
            sim_reb = np.maximum(0, np.random.normal(reb_mean, logs['REB'].std() if len(logs)>2 else 2.0, 1287))
            sim_ast = np.maximum(0, np.random.normal(ast_mean, logs['AST'].std() if len(logs)>2 else 2.0, 1287))
            
            t2_proj_score += sim_pts
            
            if len(bets) < 40:
                pts_line = math.ceil(np.median(sim_pts) * 2) / 2
                reb_line = math.ceil(np.median(sim_reb) * 2) / 2
                ast_line = math.ceil(np.median(sim_ast) * 2) / 2
                if pts_line > 2: bets.append(f"{p} O/U {pts_line} PTS (-110)")
                if reb_line > 1: bets.append(f"{p} O/U {reb_line} REB (-110)")
                if ast_line > 1: bets.append(f"{p} O/U {ast_line} AST (-110)")
    else:
        # Team 2 is new. Base score off Team 1's average points allowed minus a 2.5-point buffer
        t1_allowed = get_opp_ppg(team1)
        t2_proj_score = np.maximum(0, np.random.normal(t1_allowed - 2.5, 5.0, 1287))

    median_t1 = np.median(t1_proj_score)
    median_t2 = np.median(t2_proj_score)
    
    spread = math.ceil(abs(median_t1 - median_t2) * 2) / 2
    if spread == 0: spread = 1.5
    fav, dog = (team1, team2) if median_t1 > median_t2 else (team2, team1)
    
    t1_prob = np.sum(t1_proj_score > t2_proj_score) / 1287
    juice = 1.08 
    
    def ml_odds(prob):
        p = max(0.05, min(0.95, prob))
        return f"-{int(100 * (p / (1 - p)) * juice)}" if p >= 0.5 else f"+{int(100 * ((1 - p) / p) / juice)}"

    bets.insert(0, f"{team1} Moneyline ({ml_odds(t1_prob)})")
    bets.insert(1, f"{team2} Moneyline ({ml_odds(1 - t1_prob)})")
    bets.insert(2, f"{fav} -{spread} Spread (-110)")
    bets.insert(3, f"{dog} +{spread} Spread (-110)")
    
    total_line = math.ceil((median_t1 + median_t2) * 2) / 2
    bets.insert(4, f"Game O/U {total_line} Total Points (-110)")
    bets.insert(5, f"{team1} Team Total O/U {math.ceil(median_t1*2)/2} (-110)")
    bets.insert(6, f"{team2} Team Total O/U {math.ceil(median_t2*2)/2} (-110)")
    
    generic_props = [
        f"Race to 20 Points: {fav} (-130)", f"Race to 20 Points: {dog} (+110)",
        "Any Player to record a Double-Double (+150)", "Any Player to record a Triple-Double (+450)",
        f"The Blowout: {fav} wins by 15+ (+280)", "Game to go to Overtime (+850)",
        "Both Teams to Score 60+ Points (+140)", "First Team to Call a Timeout (-115)",
        f"Lead at Halftime: {fav} (-140)", "Any Player 5+ Steals (+350)"
    ]
    bets.extend(generic_props)

    # --- SERIES MARKETS (every QCL matchup is 2 games back-to-back) ---
    if is_series:
        combo_total = math.ceil((median_t1 + median_t2) * 2) * 2 / 2   # combined 2-game total
        series_spread = math.ceil(abs(median_t1 - median_t2) * 1.5 * 2) / 2
        if series_spread == 0:
            series_spread = 2.5
        p_sweep_fav = max(0.05, min(0.95, t1_prob if fav == team1 else 1 - t1_prob)) ** 2
        p_sweep_dog = max(0.05, min(0.95, 1 - (t1_prob if fav == team1 else 1 - t1_prob))) ** 2
        p_split = max(0.02, 1 - p_sweep_fav - p_sweep_dog)
        series_bets = [
            f"📅 SERIES: {fav} sweeps 2-0 ({ml_odds(p_sweep_fav)})",
            f"📅 SERIES: {dog} sweeps 2-0 ({ml_odds(p_sweep_dog)})",
            f"📅 SERIES: Split 1-1 ({ml_odds(p_split)})",
            f"📅 SERIES: {fav} -{series_spread} combined pts (Game 1+2) (-110)",
            f"📅 SERIES: {dog} +{series_spread} combined pts (Game 1+2) (-110)",
            f"📅 SERIES: {fav} to win at least 1 game (-320)",
            f"📅 SERIES: {dog} to win at least 1 game (-200)",
            f"📅 SERIES: Combined O/U {combo_total} pts (both games) (-110)",
            "📅 SERIES: Both games decided by 10+ (+240)",
            "📅 SERIES: At least one OT in the set (+300)",
            f"📅 SERIES: {fav} wins Game 1, loses Game 2 (+450)",
            f"📅 SERIES: Same team wins both by 8+ (+380)",
        ]
        bets.extend(series_bets)

    # Stable de-dupe (preserve insertion order) — set() was silently reshuffling
    # and dropping legs, which is how off-board props slipped through.
    seen, ordered = set(), []
    for b in bets:
        if b not in seen:
            seen.add(b)
            ordered.append(b)

    readout = f"🧠 **Monte Carlo Oracle Engine**\nRan `1,287` simulations utilizing rolling 5-game matrices for the top 5 rotational players.\n**Projected Sharp Score:** {team1} {int(median_t1)} - {team2} {int(median_t2)}"
    if is_series:
        readout += "\n📅 **2-Game Series** — series markets are live on this board."
    return ordered[:80], readout 

def draw_tictactoe_board(user_name, events, t1, t2):
    board = events.copy()
    board.insert(4, f"FREE SPACE\n{t1[:10]}\nvs\n{t2[:10]}")
    fig, ax = plt.subplots(figsize=(6, 6)); ax.set_facecolor('#0f172a')
    ax.set_xticks([0.33, 0.66]); ax.set_yticks([0.33, 0.66])
    ax.grid(color='#00ff00', linestyle='-', linewidth=4)
    ax.set_xticklabels([]); ax.set_yticklabels([]); ax.set_xlim(0, 1); ax.set_ylim(0, 1)
    for i in range(3):
        for j in range(3):
            text = board[i*3+j].replace(' ', '\n')
            color = '#d4af37' if i*3+j == 4 else 'white'
            ax.text(j/3 + 0.165, 0.83 - i/3, text, color=color, ha='center', va='center', fontweight='bold', fontsize=8)
    ax.set_title(f"QCL Tic-Tac-Toe: {user_name}", color='#00a2ff', pad=15, fontsize=16, fontweight='bold')
    buf = BytesIO(); plt.savefig(buf, format='png', bbox_inches='tight', transparent=True); buf.seek(0); plt.close(fig); return buf


# --- 5. GRAPHICS ENGINE ---
def draw_basketball_court(ax):
    ax.set_facecolor('#d2ab71') 
    ax.plot([-250, 250], [-47.5, -47.5], color='white', lw=2) 
    ax.plot([-250, -250], [-47.5, 422.5], color='white', lw=2)
    ax.plot([250, 250], [-47.5, 422.5], color='white', lw=2)
    ax.plot([-80, -80], [-47.5, 143.5], color='white', lw=2)
    ax.plot([80, 80], [-47.5, 143.5], color='white', lw=2)
    ax.plot([-80, 80], [143.5, 143.5], color='white', lw=2)
    ax.plot([-220, -220], [-47.5, 92.5], color='white', lw=2)
    ax.plot([220, 220], [-47.5, 92.5], color='white', lw=2)
    arc = Arc((0, 0), 475, 475, theta1=22, theta2=158, color='white', lw=2); ax.add_patch(arc)
    ax.add_patch(Circle((0, 0), 7.5, color='#ff3333', fill=False, lw=2))
    ax.plot([-30, 30], [-7.5, -7.5], color='black', lw=2)

def draw_radar_chart(player_name, p_stats, lg_avg, era_title, p2_name=None, p2_stats=None):
    cats = ['Scoring', 'Playmaking', 'Rebounding', 'Defense', 'Efficiency']
    N = len(cats)
    def norm(val, mx): return min(100, (max(0, val) / mx) * 100) if mx > 0 else 0
    mx = {'PTS': 40, 'AST': 15, 'REB': 25, 'DEF': 10, 'TS%': 100} 
    p_vals = [norm(p_stats['PTS'], mx['PTS']), norm(p_stats['AST'], mx['AST']), norm(p_stats['REB'], mx['REB']), norm(p_stats['DEF'], mx['DEF']), norm(p_stats['TS%'], mx['TS%'])]; p_vals += p_vals[:1]
    
    if p2_stats:
        l_vals = [norm(p2_stats['PTS'], mx['PTS']), norm(p2_stats['AST'], mx['AST']), norm(p2_stats['REB'], mx['REB']), norm(p2_stats['DEF'], mx['DEF']), norm(p2_stats['TS%'], mx['TS%'])]; l_vals += l_vals[:1]
        l_label, l_color, l_style = p2_name, '#cc0000', 'solid'
    else:
        l_vals = [norm(lg_avg['PTS'], mx['PTS']), norm(lg_avg['AST'], mx['AST']), norm(lg_avg['REB'], mx['REB']), norm(lg_avg['DEF'], mx['DEF']), norm(lg_avg['TS%'], mx['TS%'])]; l_vals += l_vals[:1]
        l_label, l_color, l_style = 'League Avg', '#888888', 'dashed'
    
    angles = [n / float(N) * 2 * math.pi for n in range(N)]; angles += angles[:1]
    plt.style.use('dark_background'); fig, ax = plt.subplots(figsize=(6, 6), subplot_kw=dict(polar=True))
    fig.patch.set_facecolor('#121212'); ax.set_facecolor('#121212')
    ax.plot(angles, p_vals, linewidth=2, linestyle='solid', label=f"{player_name} ({era_title})" if not p2_stats else player_name, color='#d4af37')
    ax.fill(angles, p_vals, alpha=0.4, color='#d4af37')
    ax.plot(angles, l_vals, linewidth=2, linestyle=l_style, label=l_label, color=l_color)
    if p2_stats: ax.fill(angles, l_vals, alpha=0.4, color=l_color)
    plt.xticks(angles[:-1], cats, color='white', size=12); ax.set_yticklabels([]); ax.spines['polar'].set_color('#444444')
    plt.legend(loc='upper right', bbox_to_anchor=(1.2, 1.1))
    buf = BytesIO(); plt.savefig(buf, format='png', bbox_inches='tight', transparent=True); buf.seek(0); plt.close(); return buf

def draw_shot_chart(player_name, stats):
    fig, ax = plt.subplots(figsize=(5, 4.5)); draw_basketball_court(ax)
    np.random.seed(hash(player_name) % (2**32))
    fgm = int(stats.get('FGM', 0)); tpm = int(stats.get('3PM', 0)); paint_shots = max(0, fgm - tpm)
    for _ in range(tpm):
        angle = np.random.uniform(np.pi/8, 7*np.pi/8); dist = np.random.uniform(240, 280)
        ax.scatter(dist*np.cos(angle), dist*np.sin(angle), color='#00ff00', s=60, edgecolors='black', zorder=5, marker='X')
    for _ in range(paint_shots):
        angle = np.random.uniform(0, np.pi); dist = np.random.uniform(10, 140)
        ax.scatter(dist*np.cos(angle), dist*np.sin(angle), color='#00a2ff', s=45, alpha=0.9, edgecolors='white', zorder=4)
    ax.set_title(f"Shot Chart: {player_name}", color='white', pad=10, fontweight='bold', bbox=dict(facecolor='#0f172a'))
    ax.set_xlim(-260, 260); ax.set_ylim(-60, 400); ax.axis('off')
    buf = BytesIO(); plt.savefig(buf, format='png', bbox_inches='tight', transparent=True); buf.seek(0); plt.close(fig); return buf

def draw_ultimate_player_card(player_name, stats):
    plt.style.use('dark_background')
    fig, (ax_attr, ax_radar, ax_spray) = plt.subplots(1, 3, figsize=(15, 5), gridspec_kw={'width_ratios': [1.2, 1, 1]})
    fig.patch.set_facecolor('#0f172a'); ax_attr.axis('off')
    pts, ast, reb, stl, blk, ts, gp = stats.get('PTS',0), stats.get('AST',0), stats.get('REB',0), stats.get('STL',0), stats.get('BLK',0), stats.get('TS%',0), max(1, stats.get('GP', 1))
    fin = min(99, max(40, int(((stats.get('FGM',0)-stats.get('3PM',0)) / gp) * 15)))
    sht = min(99, max(30, int((stats.get('3PM',0) / gp) * 20 + (stats.get('3P%',0)*100))))
    ply = min(99, max(35, int((ast / gp) * 12))); dfn = min(99, max(35, int(((stl + blk) / gp) * 15)))
    rbd = min(99, max(35, int((reb / gp) * 10))); ath = min(99, max(60, int(fin*0.6 + dfn*0.4)))
    ovr = int((fin + sht + ply + dfn + rbd + ath) / 6)
    ax_attr.text(0.1, 0.85, str(ovr), color='#d4af37', fontsize=45, fontweight='bold', ha='left')
    ax_attr.text(0.35, 0.85, "OVR", color='white', fontsize=20, ha='left')
    ax_attr.text(0.1, 0.70, player_name.upper(), color='white', fontsize=18, fontweight='bold')
    attrs = [("FIN", fin), ("SHT", sht), ("PLY", ply), ("DEF", dfn), ("REB", rbd), ("ATH", ath), ("IQ", int(ts*100)), ("HUST", 85)]
    y_pos = 0.55
    for i in range(0, len(attrs), 2):
        ax_attr.text(0.1, y_pos, f"{attrs[i][0]}: {attrs[i][1]}", color='#00a2ff', fontsize=13, fontweight='bold')
        if i+1 < len(attrs): ax_attr.text(0.55, y_pos, f"{attrs[i+1][0]}: {attrs[i+1][1]}", color='#00a2ff', fontsize=13, fontweight='bold')
        y_pos -= 0.15
    categories = ['Scoring', 'Playmaking', 'Rebounding', 'Defense', 'Efficiency']
    vals = [min(100, (pts/gp)*3), ply, rbd, dfn, min(100, ts*120)]; vals += vals[:1]
    angles = [n / 5 * 2 * math.pi for n in range(5)]; angles += angles[:1]
    ax_radar.remove(); ax_radar = fig.add_subplot(1, 3, 2, polar=True); ax_radar.set_facecolor('#0f172a')
    ax_radar.fill(angles, vals, color='#ff003c', alpha=0.3); ax_radar.plot(angles, vals, color='#ff003c', linewidth=2)
    ax_radar.set_yticklabels([]); plt.xticks(angles[:-1], categories, color='white', size=10)
    ax_radar.set_title("Player Archetype", color='white', pad=10)
    ax_spray.axis('off'); ax_spray.text(0.5, 0.5, "Shot Chart Handled Separately", color='gray', ha='center', va='center')
    plt.tight_layout(); buf = BytesIO(); plt.savefig(buf, format='png', bbox_inches='tight', transparent=True); buf.seek(0); plt.close(); return buf

def draw_ultimate_team_card(team_name, t_roster, t_sum):
    plt.style.use('dark_background')
    fig, (ax_attr, ax_radar, ax_mvp) = plt.subplots(1, 3, figsize=(15, 5), gridspec_kw={'width_ratios': [1.2, 1, 1.2]})
    fig.patch.set_facecolor('#0f172a'); ax_attr.axis('off')
    wins = int(t_sum['Win'].sum()) if 'Win' in t_sum.columns else 0
    r_g = t_sum['PTS'].mean() if not t_sum.empty else 0
    team_3pm = int(t_sum['3PM'].sum()) if not t_sum.empty else 0
    off = min(99, max(40, int((r_g / 80) * 99))); def_ = min(99, max(40, int((t_roster['STL'].sum() + t_roster['BLK'].sum()) / 2)))
    chem = min(99, max(50, int((t_roster['AST'].sum() / max(1, t_roster['FGM'].sum())) * 100)))
    ovr = int((off + def_ + chem + 85) / 4)
    ax_attr.text(0.05, 0.85, str(ovr), color='#d4af37', fontsize=45, fontweight='bold', ha='left')
    ax_attr.text(0.35, 0.85, "OVR", color='white', fontsize=20, ha='left')
    ax_attr.text(0.05, 0.65, str(team_name).upper(), color='white', fontsize=20, fontweight='bold')
    ax_attr.text(0.05, 0.50, f"RECORD: {wins} Wins", color='#00ff00', fontsize=14, fontweight='bold')
    ax_attr.text(0.05, 0.35, f"PTS/GAME: {r_g:.1f}", color='#00a2ff', fontsize=14, fontweight='bold')
    ax_attr.text(0.05, 0.20, f"TOTAL 3PM: {team_3pm}", color='#ff003c', fontsize=14, fontweight='bold')
    categories = ['Offense', 'Defense', 'Chemistry', 'Pace', 'Rebounding']
    vals = [off, def_, chem, 80, min(99, int(t_roster['REB'].sum() / 3))]; vals += vals[:1]
    angles = [n / 5 * 2 * math.pi for n in range(5)]; angles += angles[:1]
    ax_radar.remove(); ax_radar = fig.add_subplot(1, 3, 2, polar=True); ax_radar.set_facecolor('#0f172a')
    ax_radar.fill(angles, vals, color='#00ff00', alpha=0.3); ax_radar.plot(angles, vals, color='#00ff00', linewidth=2)
    ax_radar.set_yticklabels([]); plt.xticks(angles[:-1], categories, color='white', size=10); ax_radar.set_title("Franchise Ratings", color='white', pad=10)
    ax_mvp.set_facecolor('#0f172a'); top_mvps = t_roster.groupby('PlayerName')['Impact'].sum().sort_values(ascending=False).head(5)
    if not top_mvps.empty:
        bars = ax_mvp.barh(top_mvps.index.str[:10][::-1], top_mvps.values[::-1], color='#00a2ff')
        ax_mvp.set_title("Top 5 Impact Players", color='white', pad=10); ax_mvp.spines['top'].set_visible(False); ax_mvp.spines['right'].set_visible(False)
        for bar in bars: ax_mvp.text(bar.get_width(), bar.get_y() + bar.get_height()/2, f' {int(bar.get_width())}', va='center', color='white', fontweight='bold')
    else: ax_mvp.text(0.5, 0.5, "No Data", color='white', ha='center', va='center')
    plt.tight_layout(); buf = BytesIO(); plt.savefig(buf, format='png', bbox_inches='tight', transparent=True); buf.seek(0); plt.close(); return buf

def draw_bar_chart(title, names, values):
    plt.style.use('dark_background'); fig, ax = plt.subplots(figsize=(6, 4))
    bars = ax.barh(names[::-1], values[::-1], color='#00a2ff')
    ax.set_title(title, color='white', pad=20); ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False)
    for bar in bars:
        width = bar.get_width()
        v_str = f"{width:.3f}" if width < 1 and width > 0 else f"{int(width)}"
        ax.text(width, bar.get_y() + bar.get_height()/2, f' {v_str}', va='center', color='white')
    buf = BytesIO(); plt.savefig(buf, format='png', bbox_inches='tight', transparent=True); buf.seek(0); plt.close(); return buf

def draw_statcast_scatter(t_df):
    plt.style.use('dark_background'); fig, ax = plt.subplots(figsize=(7, 5))
    t_stats = t_df.groupby('Team Name').agg({'3PM':'sum', 'PTS':'sum'}).reset_index()
    ax.scatter(t_stats['3PM'], t_stats['PTS'], color='#00ff00', s=100, alpha=0.7)
    for i, row in t_stats.iterrows(): ax.annotate(str(row['Team Name'])[:3].upper(), (row['3PM'], row['PTS']), xytext=(5,5), textcoords='offset points', color='white', fontsize=8)
    ax.set_title('QSPN Analytics: 3PT Volume vs Point Production', color='white')
    ax.set_xlabel('Total 3-Pointers Made', color='white'); ax.set_ylabel('Total Points Scored', color='white')
    ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False)
    buf = BytesIO(); plt.savefig(buf, format='png', bbox_inches='tight', transparent=True); buf.seek(0); plt.close(); return buf

def draw_extracted_table(data_json, title="Extracted Box Score"):
    plt.style.use('dark_background')
    fig, ax = plt.subplots(figsize=(16, max(3, len(data_json) * 0.5 + 1)))
    fig.patch.set_facecolor('#0f172a')
    ax.axis('off')
    
    if not data_json: return BytesIO()
    
    # ADDED "Team Name" to the UI readout
    cols = ["Player/Team", "Team Name", "Type", "GRD", "MIN", "PTS", "REB", "OREB", "DREB", "AST", "STL", "BLK", "TO", "FGM", "FGA", "3PM", "3PA", "FTM", "FTA", "FOULS"]

    cell_text = []
    for r in data_json:
        cell_text.append([str(r.get(c, "")) for c in cols])
        
    table = ax.table(cellText=cell_text, colLabels=cols, loc='center', cellLoc='center')
    table.auto_set_font_size(False)
    table.set_fontsize(11) # Bigger font for readability
    table.scale(1.2, 1.8) # Stretched out horizontally and vertically to stop jumbling
    
    for (row, col), cell in table.get_celld().items():
        cell.set_edgecolor('#334155')
        if row == 0:
            cell.set_facecolor('#1e293b')
            cell.set_text_props(color='white', weight='bold')
        else:
            cell.set_facecolor('#0f172a' if row % 2 == 0 else '#1e293b')
            cell.set_text_props(color='#e2e8f0')
            
    ax.set_title(title, color='white', pad=20, fontweight='bold', fontsize=16)
    buf = BytesIO()
    plt.savefig(buf, format='png', bbox_inches='tight', facecolor=fig.get_facecolor())
    buf.seek(0)
    plt.close(fig)
    return buf

# --- 6. UI VIEWS & BUILDERS ---
_ERA_BTN_LABELS = {"QCL": "🟢 QCL (Live)", "SPAM": "🗄️ SPAM", "ALL": "🏆 All-Time"}

class ScopeButtonView(discord.ui.View):
    def __init__(self, command_type, target1=None, target2=None, extra=None, era=None):
        super().__init__(timeout=None)
        self.command_type, self.target1, self.target2, self.extra = command_type, target1, target2, extra
        # Default to the era the live sheet is sourcing; users flip it below.
        self.era = era or _active_era()

        # Era switch — one button per era, the active one highlighted.
        for k in ("QCL", "SPAM", "ALL"):
            style = discord.ButtonStyle.primary if k == self.era else discord.ButtonStyle.secondary
            eb = discord.ui.Button(label=_ERA_BTN_LABELS[k], style=style)
            eb.callback = self._era_cb(k)
            self.add_item(eb)

        # Scope buttons. Seasons shown are scoped to the ACTIVE era so the splits
        # match what's on screen. Career = that era's full record.
        self.add_item(self._mk_btn("Career", "Eternal Record", discord.ButtonStyle.success))
        self.add_item(self._mk_btn("Current", "Latest Season", discord.ButtonStyle.secondary))
        # Recent-form windows — leaderboards only.
        if command_type == "leaderboard":
            for _n in (5, 10, 20):
                self.add_item(self._mk_btn(f"L{_n}", f"Last {_n}", discord.ButtonStyle.primary))
        try:
            df = _cached_df
            if df is not None and 'Season' in df.columns:
                _sdf = df
                if self.era in ('QCL', 'SPAM') and 'Era' in df.columns:
                    _sdf = df[df['Era'] == self.era]
                all_seasons = sorted([int(s) for s in _sdf['Season'].dropna().unique()], reverse=True)
                current = all_seasons[0] if all_seasons else None
                shown = 0
                for szn in all_seasons:
                    if szn == current:
                        continue
                    if shown >= 15:  # keep total components within Discord's 25-button cap
                        break
                    self.add_item(self._mk_btn(str(szn), f"Season {szn}", discord.ButtonStyle.secondary))
                    shown += 1
        except Exception as e:
            print(f"[ScopeView] Could not build dynamic season buttons: {e}")

    def _mk_btn(self, val, label, style):
        btn = discord.ui.Button(label=label, style=style)
        btn.callback = self.create_callback(val)
        return btn

    def create_callback(self, scope_val):
        async def callback(interaction: discord.Interaction):
            await interaction.response.defer()
            await self._dispatch(interaction, scope_val, self.era)
        return callback

    def _era_cb(self, era_val):
        async def callback(interaction: discord.Interaction):
            await interaction.response.defer()
            # Switching era resets to that era's base (Career) view.
            await self._dispatch(interaction, "Career", era_val)
        return callback

    async def _dispatch(self, interaction, scope_val, era):
        ct = self.command_type
        if ct == "scout":
            await build_scout_card(interaction, self.target1, scope_val, self.extra, is_edit=True, era=era)
        elif ct == "leaderboard":
            await build_leaderboard(interaction, self.target1, scope_val, self.target2, is_edit=True, era=era)
        elif ct == "teamreport":
            await build_teamreport(interaction, self.target1, scope_val, is_edit=True, era=era)
        elif ct == "analytics":
            await build_analytics(interaction, scope_val, is_edit=True, era=era)
        elif ct == "vegas":
            await build_vegas(interaction, self.target1, self.target2, scope_val, is_edit=True, era=era)

async def build_scout_card(interaction, search_name, scope, discord_id=None, is_edit=False, era=None):
    df_full = _cached_df
    if df_full is None: 
        msg = "⚠️ Stat Engine is still warming up! Please try again in 10 seconds."
        if is_edit: return await interaction.edit_original_response(content=msg, embed=None, attachments=[], view=None) 
        else: return await interaction.followup.send(msg)

    df = df_full.copy()
    if era is None:
        era = _active_era()
    # Legacy safety: if a named player has nothing in the chosen live era, fall
    # back to All-Time so SPAM-era players still resolve on a direct /scout.
    if era in ('SPAM', 'QCL') and search_name and 'Era' in df.columns:
        _probe = df[(df['Type'].astype(str).str.lower() == 'player')
                    & (df['Player/Team'].astype(str).str.lower() == str(search_name).lower())
                    & (df['Era'] == era)]
        if _probe.empty:
            era = 'ALL'
    if era in ('SPAM', 'QCL') and 'Era' in df.columns:
        df = df[df['Era'] == era]
    base_label = {"SPAM": "SPAM Era", "QCL": "QCL Era"}.get(era, "Eternal Record")
    era_title = base_label
    if scope != "Career":
        target_szn = _current_season(df) if scope == "Current" else int(scope)
        df = df[df['Season'] == target_szn]
        era_title = (f"{base_label} · Season {target_szn}" if era in ('SPAM', 'QCL') else f"Season {target_szn}")
        if df.empty: 
            msg = f"⚠️ No data found for {search_name} in {era_title}."
            if is_edit: return await interaction.edit_original_response(content=msg, embed=None, attachments=[]) 
            else: return await interaction.followup.send(msg)

    p_df = df[df['Type'].str.lower() == 'player']
    p_data = p_df[p_df['Player/Team'].str.lower() == search_name.lower()]
    if p_data.empty: 
        msg = f"⚠️ Could not find '{search_name}' in {era_title}."
        if is_edit: return await interaction.edit_original_response(content=msg, embed=None, attachments=[]) 
        else: return await interaction.followup.send(msg)
        
    actual_name = p_data['Player/Team'].iloc[0]; team_name = p_data['Team Name'].iloc[-1]
    pts, reb, ast = p_data['PTS'].mean(), p_data['REB'].mean(), p_data['AST'].mean()
    stl, blk, pie = p_data['STL'].mean(), p_data['BLK'].mean(), p_data['PIE_Raw'].mean()
    # --- FULL STATLINE: every box-score stat + real shooting splits ---
    def _savg(c): return p_data[c].mean() if c in p_data.columns and len(p_data) else 0.0
    def _ssum(c): return p_data[c].sum() if c in p_data.columns and len(p_data) else 0.0
    spg, bpg, topg, pfpg = stl, blk, _savg('TO'), _savg('FOULS')
    fppg = _savg('FP')
    _fga, _fta, _tpa = _ssum('FGA'), _ssum('FTA'), _ssum('3PA')
    fg_pct = (_ssum('FGM') / _fga * 100) if _fga > 0 else 0.0
    tp_pct = (_ssum('3PM') / _tpa * 100) if _tpa > 0 else 0.0
    ft_pct = (_ssum('FTM') / _fta * 100) if _fta > 0 else 0.0
    ts = (_ssum('PTS') / (2 * (_fga + 0.44 * _fta)) * 100) if (_fga + 0.44 * _fta) > 0 else 0.0
    gp_count = len(p_data)
    p_stats = {'PTS': pts, 'AST': ast, 'REB': reb, 'DEF': stl+blk, 'TS%': ts}
    
    lg_df = p_df.groupby('Player/Team').mean(numeric_only=True)
    lg_avg = {'PTS': lg_df['PTS'].mean(), 'AST': lg_df['AST'].mean(), 'REB': lg_df['REB'].mean(), 'DEF': lg_df['STL'].mean()+lg_df['BLK'].mean(), 'TS%': 55.0}

    era_high_pts, era_high_reb, era_high_ast = p_data['PTS'].max(), p_data['REB'].max(), p_data['AST'].max()
    p_full_data = df_full[(df_full['Type'].str.lower() == 'player') & (df_full['Player/Team'].str.lower() == search_name.lower())]
    at_high_pts, at_high_reb, at_high_ast = p_full_data['PTS'].max(), p_full_data['REB'].max(), p_full_data['AST'].max()

    img_buf = draw_radar_chart(actual_name, p_stats, lg_avg, era_title)
    file = discord.File(img_buf, filename="radar.png")

    _om = get_onboarded_map()
    _uid_onb = _om.get(_id_key(actual_name))
    if _uid_onb:
        identity = f"<@{_uid_onb}> (`{_uid_onb}`)"        # QCL law: onboarded -> ping + ID
    elif discord_id:
        identity = f"<@{discord_id}>"
    else:
        identity = get_tag(actual_name) or "Unlinked"
    # `tag` = the raw registry ping (or None) used below for roles/awards lookup.
    tag = (f"<@{_uid_onb}>" if _uid_onb else (f"<@{discord_id}>" if discord_id else get_tag(actual_name)))
    team_tag = get_tag(team_name)
    desc = f"**Team:** {team_name} {team_tag if team_tag else ''}\n**Era:** {era_title}\n**Registry:** {identity}"
    
    embed = discord.Embed(title=f"🏀 SCOUTING REPORT: {actual_name}", description=desc, color=0xFFD60A)
    embed.add_field(name="Impact (PIE)", value=f"{pie:.1f}", inline=True)
    embed.add_field(name="Scoring", value=f"{pts:.1f} PPG", inline=True)
    embed.add_field(name="Playmaking", value=f"{ast:.1f} APG", inline=True)
    embed.add_field(name="📊 Per-Game (full statline)", value=(
        f"`PTS` {pts:.1f}   `REB` {reb:.1f}   `AST` {ast:.1f}\n"
        f"`STL` {spg:.1f}   `BLK` {bpg:.1f}   `TO` {topg:.1f}   `PF` {pfpg:.1f}"
    ), inline=False)
    embed.add_field(name="🎯 Shooting Splits", value=(
        f"`FG` {fg_pct:.1f}%   `3P` {tp_pct:.1f}%   `FT` {ft_pct:.1f}%   `TS` {ts:.1f}%"
    ), inline=False)
    embed.add_field(name="🎮 Games", value=f"{gp_count}", inline=True)
    embed.add_field(name="🃏 Fantasy", value=f"{fppg:.1f} FP", inline=True)
    embed.add_field(name="Milestones & Highs", value=f"**{era_title} Highs:** {int(era_high_pts)}P | {int(era_high_reb)}R | {int(era_high_ast)}A\n**All-Time Highs:** {int(at_high_pts)}P | {int(at_high_reb)}R | {int(at_high_ast)}A", inline=False)
    embed.add_field(name="Est. Tipped Passes", value=f"{int(p_data['Tipped_Passes'].sum())}", inline=True)
    embed.add_field(name="Est. Shots Affected", value=f"{int(p_data['Shots_Affected'].sum())}", inline=True)

    clubs_df = get_player_clubs(df_full)
    club_list = clubs_df[clubs_df['Player/Team'] == actual_name]['Clubs'].iloc[0] if not clubs_df[clubs_df['Player/Team'] == actual_name].empty else []
    
    state = load_state()
    did_clean = tag.replace("<@", "").replace(">", "").replace("!", "").replace("&", "") if tag else None
    
    all_awards = []
    roles = get_user_roles(tag) if tag else []
    if roles: all_awards.extend([f"🏅 {r}" for r in roles])
    custom_awards = state['awards'].get(did_clean, []) if did_clean else state['awards'].get(actual_name.lower(), [])
    all_awards.extend(club_list)
    all_awards.extend(custom_awards)

    if all_awards: embed.add_field(name="🏆 Honors & Memberships", value="\n".join(list(set(all_awards))), inline=False)
    embed.set_image(url="attachment://radar.png")
    
    view = ScoutCardView(actual_name, era or "ALL", discord_id)
    if is_edit: await interaction.edit_original_response(content="", embed=embed, attachments=[file], view=view)
    else: await interaction.followup.send(embed=embed, file=file, view=view)


# ════════════════════════════════════════════════════════════════════
#  SCOUT BROWSER — cascading Era -> Player -> Season dropdowns.
#  Pick an era (All-Time / SPAM / QCL), jump to a first letter, pick a
#  player, then flip seasons on the rendered card.
# ════════════════════════════════════════════════════════════════════

_ERA_LABELS = {"ALL": "🏆 All-Time (Eternal)", "SPAM": "🗄️ SPAM (Legacy S1-6)", "QCL": "🏆 QCL (Current)"}

def _era_player_frame(era):
    df = _cached_df
    if df is None:
        return None
    p = df[df['Type'].astype(str).str.lower() == 'player']
    if era in ('SPAM', 'QCL') and 'Era' in p.columns:
        p = p[p['Era'] == era]
    return p

def _first_letter(name):
    s = str(name).strip()
    if not s:
        return '#'
    c = s[0].upper()
    return c if c.isalpha() else '#'

def scout_era_players(era):
    """Sorted unique player names available in an era."""
    p = _era_player_frame(era)
    if p is None or p.empty:
        return []
    return sorted(p['Player/Team'].dropna().astype(str).unique(), key=lambda s: s.lower())

def scout_era_letters(era):
    """First-letter buckets that actually have players in this era."""
    return sorted({_first_letter(n) for n in scout_era_players(era)})

def scout_ranked_players(era):
    """All players in an era, MOST-ACTIVE (games played) first — so the names
    people recognize surface on page 1 instead of being buried alphabetically."""
    p = _era_player_frame(era)
    if p is None or p.empty:
        return []
    gp = p.groupby('Player/Team')['Game_ID'].nunique().sort_values(ascending=False)
    return [str(x) for x in gp.index.tolist()]

def scout_player_seasons(player, era):
    """Seasons a player appears in within an era (ints, ascending)."""
    p = _era_player_frame(era)
    if p is None or p.empty:
        return []
    pp = p[p['Player/Team'].astype(str).str.lower() == str(player).lower()]
    return sorted({int(s) for s in pd.to_numeric(pp['Season'], errors='coerce').dropna().unique()})


class ScoutBrowserView(discord.ui.View):
    """Era -> Player picker. Opens straight into a most-active-first player list
    (recognizable names on page 1), paged 25 at a time. No letter step — for a
    specific name, /scout <name> autocompletes."""
    PER = 25

    def __init__(self, era=None, page=0):
        super().__init__(timeout=300)
        self.era = era or _active_era()
        names = scout_ranked_players(self.era)
        self.total = len(names)
        self._pages = max(1, (self.total + self.PER - 1) // self.PER)
        self.page = max(0, min(page, self._pages - 1))

        # Row 0 — Era
        era_opts = [discord.SelectOption(label=_ERA_LABELS[k], value=k, default=(k == self.era))
                    for k in ("ALL", "SPAM", "QCL")]
        era_sel = discord.ui.Select(placeholder="Choose an era…", options=era_opts, row=0)
        era_sel.callback = self._era_cb
        self.add_item(era_sel)

        # Row 1 — Player (most active first, paged)
        chunk = names[self.page * self.PER:(self.page + 1) * self.PER]
        if chunk:
            p_opts = [discord.SelectOption(label=n[:100], value=n[:100]) for n in chunk]
            ph = "Pick a player…" + (f"  (page {self.page+1}/{self._pages})" if self._pages > 1 else "")
            p_sel = discord.ui.Select(placeholder=ph[:150], options=p_opts, row=1)
            p_sel.callback = self._player_cb
            self.add_item(p_sel)

        # Row 2 — pager
        if self._pages > 1:
            prev_b = discord.ui.Button(label="◀ Prev", style=discord.ButtonStyle.secondary,
                                       row=2, disabled=(self.page == 0))
            nxt_b = discord.ui.Button(label="Next ▶", style=discord.ButtonStyle.secondary,
                                      row=2, disabled=(self.page >= self._pages - 1))
            prev_b.callback = self._prev_cb
            nxt_b.callback = self._nxt_cb
            self.add_item(prev_b)
            self.add_item(nxt_b)

    def _embed(self):
        pg = f" · page {self.page+1}/{self._pages}" if self._pages > 1 else ""
        if self.total == 0:
            desc = (f"**{_ERA_LABELS.get(self.era, self.era)}** has no games logged yet.\n"
                    "Try another era above.")
        else:
            desc = (f"**{_ERA_LABELS.get(self.era, self.era)}** — {self.total} players, most active first{pg}.\n"
                    "Pick a player below to see their card.\n\n"
                    "*Know the name already? Type* `/scout <name>` *and it'll autocomplete.*")
        return discord.Embed(title="🔎 Scout Browser", description=desc, color=0xFFD60A)

    async def _era_cb(self, interaction: discord.Interaction):
        v = ScoutBrowserView(interaction.data['values'][0], 0)
        await interaction.response.edit_message(embed=v._embed(), attachments=[], view=v)

    async def _prev_cb(self, interaction: discord.Interaction):
        v = ScoutBrowserView(self.era, self.page - 1)
        await interaction.response.edit_message(embed=v._embed(), attachments=[], view=v)

    async def _nxt_cb(self, interaction: discord.Interaction):
        v = ScoutBrowserView(self.era, self.page + 1)
        await interaction.response.edit_message(embed=v._embed(), attachments=[], view=v)

    async def _player_cb(self, interaction: discord.Interaction):
        player = interaction.data['values'][0]
        await interaction.response.defer()
        await build_scout_card(interaction, player, "Career", is_edit=True, era=self.era)


class ScoutCardView(discord.ui.View):
    """Attached to a rendered scout card: flip era, flip season, or go back to
    the player list at the exact page the player was on."""
    def __init__(self, player, era="ALL", discord_id=None):
        super().__init__(timeout=300)
        self.player = player
        self.era = era or "ALL"
        self.discord_id = discord_id

        # Row 0 — Era swap
        era_opts = [discord.SelectOption(label=_ERA_LABELS[k], value=k, default=(k == self.era))
                    for k in ("ALL", "SPAM", "QCL")]
        era_sel = discord.ui.Select(placeholder="Switch era…", options=era_opts, row=0)
        era_sel.callback = self._era_cb
        self.add_item(era_sel)

        # Row 1 — Season swap (this player's seasons within the era)
        seasons = scout_player_seasons(player, self.era)
        s_opts = [discord.SelectOption(label="Career (all seasons)", value="Career")]
        for s in seasons[:24]:
            s_opts.append(discord.SelectOption(label=f"Season {s}", value=str(s)))
        s_sel = discord.ui.Select(placeholder="Switch season…", options=s_opts, row=1)
        s_sel.callback = self._season_cb
        self.add_item(s_sel)

    @discord.ui.button(label="🔙 Back to player list", style=discord.ButtonStyle.secondary, row=2)
    async def back(self, interaction: discord.Interaction, button: discord.ui.Button):
        ranked = scout_ranked_players(self.era)
        try:
            page = ranked.index(self.player) // ScoutBrowserView.PER
        except ValueError:
            page = 0
        view = ScoutBrowserView(self.era, page)
        await interaction.response.edit_message(embed=view._embed(), attachments=[], view=view)

    async def _era_cb(self, interaction: discord.Interaction):
        self.era = interaction.data['values'][0]
        await interaction.response.defer()
        await build_scout_card(interaction, self.player, "Career", self.discord_id, is_edit=True, era=self.era)

    async def _season_cb(self, interaction: discord.Interaction):
        scope = interaction.data['values'][0]
        await interaction.response.defer()
        await build_scout_card(interaction, self.player, scope, self.discord_id, is_edit=True, era=self.era)


async def build_leaderboard(interaction, stat_value, scope, stat_name, is_edit=False, era=None):
    df = _cached_df
    if df is None: return await interaction.followup.send("⚠️ Stat Engine is still warming up! Please try again in 10 seconds.")
    if era is None: era = _active_era()
    if era in ('SPAM', 'QCL') and 'Era' in df.columns:
        df = df[df['Era'] == era]
    _elabel = {"SPAM": "SPAM", "QCL": "QCL"}.get(era, "All-Time")
    era_title = f"{_elabel} · Career"
    last_n = None
    if isinstance(scope, str) and scope.startswith("L") and scope[1:].isdigit():
        last_n = int(scope[1:])
    elif scope != "Career":
        target_szn = _current_season(df) if scope == "Current" else int(scope)
        df = df[df['Season'] == target_szn]
        era_title = f"{_elabel} · Season {target_szn}"

    p_df = df[df['Type'].str.lower() == 'player']
    if p_df.empty:
        msg = "⚠️ No data found for this scope."
        if is_edit: return await interaction.edit_original_response(content=msg, embed=None, attachments=[], view=ScopeButtonView("leaderboard", stat_value, stat_name, era=era))
        else: return await interaction.followup.send(msg)

    if last_n:
        # Recent form: each player's most recent N games (by Game_ID), with a
        # minimum-sample floor so a 1-game cameo can't top the board.
        min_games = max(3, last_n // 2)
        p_df = p_df.sort_values('Game_ID', ascending=False)
        p_df = p_df.groupby('Player/Team', group_keys=False).head(last_n)
        _gp = p_df.groupby('Player/Team')['Game_ID'].nunique()
        p_df = p_df[p_df['Player/Team'].isin(_gp[_gp >= min_games].index)]
        era_title = f"{_elabel} · Last {last_n} Games (min {min_games} GP)"
        if p_df.empty:
            msg = f"⚠️ Nobody has {min_games}+ games yet for a Last-{last_n} board."
            if is_edit: return await interaction.edit_original_response(content=msg, embed=None, attachments=[], view=ScopeButtonView("leaderboard", stat_value, stat_name, era=era))
            else: return await interaction.followup.send(msg)

    leaders = p_df.groupby('Player/Team').mean(numeric_only=True).reset_index()
    leaders = leaders.sort_values(stat_value, ascending=False).head(5)

    _om = get_onboarded_map()
    medals = ["🥇", "🥈", "🥉", "🔥", "🔥"]
    lines = []
    for rank, (_, r) in enumerate(leaders.iterrows()):
        who = resolve_stat_identity(r['Player/Team'], onboarded_map=_om)
        lines.append(f"{medals[min(rank, 4)]} {who} — **{r[stat_value]:.1f}** avg")
    embed = discord.Embed(title=f"🏆 {stat_name} Leaders ({era_title})",
                          description="\n".join(lines) or "*No data.*", color=0xFFD60A)
    
    view = ScopeButtonView("leaderboard", stat_value, target2=stat_name, era=era)
    if is_edit: await interaction.edit_original_response(content="", embed=embed, view=view, attachments=[])
    else: await interaction.followup.send(embed=embed, view=view)

async def build_analytics(interaction, scope, is_edit=False, era=None):
    df = _cached_df
    if df is None: return await interaction.followup.send("⚠️ Stat Engine is still warming up! Please try again in 10 seconds.")
    if era is None: era = _active_era()
    if era in ('SPAM', 'QCL') and 'Era' in df.columns:
        df = df[df['Era'] == era]
    _elabel = {"SPAM": "SPAM", "QCL": "QCL"}.get(era, "All-Time")
    era_title = _elabel
    if scope != "Career":
        target_szn = _current_season(df) if scope == "Current" else int(scope)
        df = df[df['Season'] == target_szn]
        era_title = f"{_elabel} · Season {target_szn}"

    t_df = df[df['Type'].str.lower() == 'team']
    if t_df.empty:
        msg = "⚠️ No analytics data available for this scope."
        if is_edit: return await interaction.edit_original_response(content=msg, embed=None, attachments=[], view=ScopeButtonView("analytics", era=era))
        else: return await interaction.followup.send(msg)

    t_stats = t_df.groupby('Team Name').agg(**{
        'GP': ('Game_ID', 'nunique'), 'PTS': ('PTS', 'sum'), 'TO': ('TO', 'sum'),
        'FGA': ('FGA', 'sum'), 'FGM': ('FGM', 'sum'), '3PM': ('3PM', 'sum'), 'Opp_PPP': ('Opp_PPP', 'mean')
    }).reset_index()
    
    desc = "```text\nTeam             | eFG%  | TO/G | Opp PPP\n-----------------------------------------\n"
    for _, r in t_stats.sort_values('Opp_PPP', ascending=True).iterrows():
        efg = ((r['FGM'] + 0.5 * r['3PM']) / r['FGA'] * 100) if r['FGA'] > 0 else 0
        to_g = r['TO'] / r['GP'] if r['GP'] > 0 else 0
        desc += f"{str(r['Team Name'])[:16].ljust(16)} | {efg:5.1f}% | {to_g:4.1f} | {r['Opp_PPP']:.2f}\n"
    desc += "```"
    
    embed = discord.Embed(title=f"🔬 Team Analytics Lab ({era_title})", description=desc, color=0x0A84FF)
    
    buf = draw_statcast_scatter(t_df)
    file = discord.File(buf, filename="scatter.png")
    embed.set_image(url="attachment://scatter.png")
    
    view = ScopeButtonView("analytics", era=era)
    if is_edit: await interaction.edit_original_response(content="", embed=embed, view=view, attachments=[file])
    else: await interaction.followup.send(embed=embed, view=view, file=file)

def _team_logo(team_name, state=None):
    """Case-insensitive lookup of a team's stored logo image URL (or None)."""
    if not team_name:
        return None
    logos = (state or load_state()).get('team_logos', {})
    if team_name in logos and logos[team_name]:
        return logos[team_name]
    tl = str(team_name).lower()
    for k, v in logos.items():
        if str(k).lower() == tl and v:
            return v
    return None


async def build_teamreport(interaction, team_name, scope, is_edit=False, era=None):
    df = _cached_df
    if df is None: return await interaction.followup.send("⚠️ Stat Engine is still warming up! Please try again in 10 seconds.")
    if era is None: era = _active_era()
    if era in ('SPAM', 'QCL') and 'Era' in df.columns:
        df = df[df['Era'] == era]
    _elabel = {"SPAM": "SPAM", "QCL": "QCL"}.get(era, "All-Time")
    target_szn = _current_season(df) if scope == "Current" else (int(scope) if scope != "Career" else None)

    if target_szn:
        t_df = df[(df['Type'].str.lower() == 'team') & (df['Season'] == target_szn)]
        era_title = f"{_elabel} · Season {target_szn}"
    else:
        t_df = df[df['Type'].str.lower() == 'team']
        era_title = _elabel

    t_data = t_df[t_df['Team Name'].str.lower() == team_name.lower()]
    if t_data.empty:
        msg = f"⚠️ Team data not found for {era_title}."
        if is_edit: return await interaction.edit_original_response(content=msg, embed=None, attachments=[], view=ScopeButtonView("teamreport", team_name, era=era))
        else: return await interaction.followup.send(msg)

    # ── helpers ──
    def _col(frame, c, default=0.0):
        try:
            if c in frame.columns:
                v = pd.to_numeric(frame[c], errors='coerce').mean()
                return default if pd.isna(v) else float(v)
        except Exception:
            pass
        return default

    def _sum(frame, c):
        try:
            return float(pd.to_numeric(frame[c], errors='coerce').fillna(0).sum()) if c in frame.columns else 0.0
        except Exception:
            return 0.0

    def _scale(v, lo, hi):
        """Map v in [lo,hi] to 0..100 (clamped). lo>hi allowed (reversed: lower is better)."""
        if hi == lo:
            return 50.0
        return max(0.0, min(100.0, (v - lo) / (hi - lo) * 100.0))

    def _grade(s):
        table = [(93,"A+"),(88,"A"),(83,"A-"),(78,"B+"),(73,"B"),(68,"B-"),
                 (63,"C+"),(58,"C"),(53,"C-"),(48,"D+"),(43,"D"),(0,"F")]
        for cut, g in table:
            if s >= cut:
                return g
        return "F"

    def _wavg(pairs):
        """pairs = [(score, weight), ...] — ignores None scores."""
        num = sum(s * w for s, w in pairs if s is not None)
        den = sum(w for s, w in pairs if s is not None)
        return (num / den) if den else 50.0

    # ── raw stats ──
    gp = int(t_data['Game_ID'].nunique()) if 'Game_ID' in t_data.columns else len(t_data)
    wins = int(_sum(t_data, 'Win'))
    losses = max(0, gp - wins)
    win_pct = wins / gp if gp > 0 else 0.0

    ppg = _col(t_data, 'PTS')
    opp_ppg = _col(t_data, 'PTS_Opp', None)
    if opp_ppg is None:
        opp_ppg = ppg - _col(t_data, 'Point_Diff')
    margin = _col(t_data, 'Point_Diff', ppg - opp_ppg)

    fga, fgm, tpm = _sum(t_data, 'FGA'), _sum(t_data, 'FGM'), _sum(t_data, '3PM')
    tpa, fta, ftm = _sum(t_data, '3PA'), _sum(t_data, 'FTA'), _sum(t_data, 'FTM')
    pts_tot = _sum(t_data, 'PTS')
    fg_pct = (fgm / fga * 100) if fga else 0.0
    tp_pct = (tpm / tpa * 100) if tpa else 0.0
    ft_pct = (ftm / fta * 100) if fta else 0.0
    efg = ((fgm + 0.5 * tpm) / fga * 100) if fga else 0.0
    ts = (pts_tot / (2 * (fga + 0.44 * fta)) * 100) if (fga + 0.44 * fta) else 0.0

    apg, tpg = _col(t_data, 'AST'), _col(t_data, 'TO')
    ast_tot, to_tot = _sum(t_data, 'AST'), _sum(t_data, 'TO')
    ast_to = (ast_tot / to_tot) if to_tot else ast_tot
    rpg = _col(t_data, 'REB')
    orpg, drpg = _col(t_data, 'OREB'), _col(t_data, 'DREB')
    spg, bpg = _col(t_data, 'STL'), _col(t_data, 'BLK')

    opp_ppp = _col(t_data, 'Opp_PPP', None)
    ortg = _col(t_data, 'ORtg', None)
    drtg = _col(t_data, 'DRtg', None)
    netrtg = _col(t_data, 'NetRtg', None) if 'NetRtg' in t_data.columns else (
        (ortg - drtg) if (ortg and drtg) else None)
    pace = _col(t_data, 'Pace', None)

    # ── weighted sub-scores (each 0..100, weighted across ALL stats) ──
    off_score = _wavg([
        (_scale(ppg, 55, 90), 0.28),
        (_scale(efg, 40, 60), 0.24),
        (_scale(ts, 45, 65), 0.16),
        (_scale(ast_to, 0.8, 2.2), 0.14),
        (_scale(ortg, 90, 125) if ortg else None, 0.18),
    ])
    def_score = _wavg([
        (_scale(opp_ppg, 90, 55), 0.26),                 # reversed: fewer allowed = better
        (_scale(opp_ppp, 1.9, 1.0) if opp_ppp else None, 0.18),
        (_scale(drtg, 125, 90) if drtg else None, 0.18),
        (_scale(spg + bpg, 4, 14), 0.14),
        (_scale(margin, -20, 20), 0.24),                 # getting outscored tanks the D grade
    ])
    ovr_score = _wavg([
        (win_pct * 100, 0.60),
        (_scale(netrtg, -20, 20) if netrtg is not None else None, 0.20),
        (_scale(margin, -20, 20), 0.20),
    ])

    # ── record cap: a losing team CANNOT post inflated grades ──
    if win_pct >= 0.60:   cap = 100
    elif win_pct >= 0.50: cap = 92
    elif win_pct >= 0.35: cap = 80
    elif win_pct >= 0.20: cap = 70
    elif win_pct > 0.0:   cap = 62
    else:                 cap = 55     # winless → C- ceiling on defense & overall
    _curve = 6.0                        # gentle curve so an average team reads ~C, not D
    off_cap = min(100, cap + 18)        # offense (scoring ability) is gated a touch softer
    off_score = min(off_score + _curve, off_cap)
    def_score = min(def_score + _curve, cap)
    ovr_score = min(ovr_score + _curve, cap)

    off_grade, def_grade, ovr_grade = _grade(off_score), _grade(def_score), _grade(ovr_score)

    # ── build the detailed report ──
    embed = discord.Embed(title=f"📋 {era_title} Franchise Report Card: {team_name.title()}", color=0xFFD60A)
    _lg = _team_logo(team_name)
    if _lg: embed.set_thumbnail(url=_lg)

    _rec_line = f"**{ovr_grade}**  ·  {wins}-{losses} ({win_pct*100:.0f}%)  ·  Net {margin:+.1f}"
    if netrtg is not None:
        _rec_line += f"  ·  NetRtg {netrtg:+.1f}"
    embed.add_field(name="🏆 Overall", value=_rec_line, inline=False)

    _off_val = (f"**{off_grade}**  ·  {ppg:.1f} PPG\n"
                f"FG {fg_pct:.1f}% · 3P {tp_pct:.1f}% · FT {ft_pct:.1f}%\n"
                f"eFG {efg:.1f}% · TS {ts:.1f}%"
                + (f" · ORtg {ortg:.1f}" if ortg else ""))
    embed.add_field(name="🔥 Offense", value=_off_val, inline=True)

    _def_val = (f"**{def_grade}**  ·  {opp_ppg:.1f} Opp PPG\n"
                + (f"Opp PPP {opp_ppp:.2f}" if opp_ppp else "")
                + (f" · DRtg {drtg:.1f}" if drtg else "")
                + f"\n{spg:.1f} STL · {bpg:.1f} BLK/gm")
    embed.add_field(name="🛡️ Defense", value=_def_val, inline=True)

    embed.add_field(
        name="🎯 Playmaking & Care",
        value=f"{apg:.1f} AST · {tpg:.1f} TO · {ast_to:.2f} AST/TO",
        inline=False)
    embed.add_field(
        name="🪵 Glass & Tempo",
        value=(f"{rpg:.1f} REB ({orpg:.1f} O / {drpg:.1f} D)"
               + (f" · {pace:.1f} Pace" if pace else "")),
        inline=False)

    # honesty note when the grades are capped by a losing record
    if win_pct < 0.35 and gp >= 2:
        embed.add_field(
            name="⚖️ Note",
            value=f"Grades are capped by a {wins}-{losses} record — production without wins doesn't earn top marks.",
            inline=False)

    state = load_state()
    tag = get_tag(team_name)
    key = tag.replace("<@", "").replace(">", "").replace("!", "").replace("&", "") if tag else team_name.lower()
    custom_awards = state['awards'].get(key, [])
    if custom_awards:
        embed.add_field(name="🏆 Franchise Banners", value="\n".join(custom_awards)[:1024], inline=False)

    embed.set_footer(text=f"{gp} games · grades weighted across scoring, efficiency, defense, margin & record")

    view = ScopeButtonView("teamreport", team_name, era=era)
    ping_msg = f"📢 New Report Card Alert: {tag}!" if tag and not is_edit else ""

    if is_edit: await interaction.edit_original_response(content="", embed=embed, view=view, attachments=[])
    else: await interaction.followup.send(content=ping_msg, embed=embed, view=view)

async def build_vegas(interaction, team1, team2, scope, is_edit=False, era=None):
    df = _cached_df
    if df is None: return await interaction.followup.send("⚠️ Stat Engine is still warming up! Please try again in 10 seconds.")
    if era is None: era = _active_era()
    if era in ('SPAM', 'QCL') and 'Era' in df.columns:
        df = df[df['Era'] == era]
    _elabel = {"SPAM": "SPAM", "QCL": "QCL"}.get(era, "All-Time")
    era_title = _elabel
    if scope != "Career":
        target_szn = _current_season(df) if scope == "Current" else int(scope)
        df = df[df['Season'] == target_szn]
        era_title = f"{_elabel} · Season {target_szn}"

    t_df = df[df['Type'] == 'Team']
    t_stats = t_df.groupby('Team Name').agg(PPG=('PTS', 'mean'), FGA=('FGA', 'mean')).reset_index()
    
    if team1 not in t_stats['Team Name'].values or team2 not in t_stats['Team Name'].values:
        msg = f"⚠️ Teams not found in {era_title}."
        if is_edit: return await interaction.edit_original_response(content=msg, embed=None, attachments=[])
        else: return await interaction.followup.send(msg)
        
    d1, d2 = t_stats[t_stats['Team Name'] == team1].iloc[0], t_stats[t_stats['Team Name'] == team2].iloc[0]
    spread = max(1.5, round(abs(d1['PPG'] - d2['PPG']) * 2) / 2)
    fav = team1 if d1['PPG'] > d2['PPG'] else team2
    dog = team2 if d1['PPG'] > d2['PPG'] else team1
    ou = round((d1['PPG'] + d2['PPG']) * 2) / 2

    p_df = df[(df['Type'] == 'Player') & (df['Team Name'].isin([team1, team2]))]
    props = ""
    if not p_df.empty:
        top_p = p_df.groupby('Player/Team').mean(numeric_only=True).sort_values('PTS', ascending=False).head(2)
        for name, row in top_p.iterrows():
            props += f"**{name}** Total Points: O/U {round(row['PTS'] * 2) / 2}\n"

    embed = discord.Embed(title=f"🎰 QCL SPORTSBOOK ({era_title})", color=0x32D74B)
    embed.add_field(name="Matchup Spread", value=f"**{fav}** -{spread}\n**{dog}** +{spread}", inline=False)
    embed.add_field(name="Game Over/Under", value=f"**O/U:** {ou} Points", inline=False)
    if props: embed.add_field(name="🔥 Exotic Player Props", value=props, inline=False)
    
    view = ScopeButtonView("vegas", team1, team2, era=era)
    if is_edit: await interaction.edit_original_response(content="", embed=embed, view=view, attachments=[])
    else: await interaction.followup.send(embed=embed, view=view)


# --- 7. UI ADMIN DESK & GAMBLING SHACK ---
class AdminResolveView(discord.ui.View):
    def __init__(self, bet_id, uid, payout):
        super().__init__(timeout=None); self.bet_id, self.uid, self.payout = bet_id, uid, payout
        
    @discord.ui.button(label="Mark Won (To Cashier)", style=discord.ButtonStyle.success)
    async def won(self, interaction, button):
        state = load_state()
        if state['bets'].get(self.bet_id, {}).get('status') != 'Pending_Review': return await interaction.response.send_message("Bet already processed.", ephemeral=True)
        state['bets'][self.bet_id]['status'] = 'Won_Pending_Payout'
        save_state(state)
        log_admin_action(interaction.user.display_name, "Vegas", f"Verified Ticket #{self.bet_id} as WON")
        await interaction.response.edit_message(content=f"✅ Bet **{self.bet_id}** marked WON. Sent to Cashier Desk.", view=None)
        
    @discord.ui.button(label="Mark Lost", style=discord.ButtonStyle.danger)
    async def lost(self, interaction, button):
        state = load_state()
        if state['bets'].get(self.bet_id, {}).get('status') != 'Pending_Review': return await interaction.response.send_message("Bet already processed.", ephemeral=True)
        state['bets'][self.bet_id]['status'] = 'Lost'
        save_state(state)
        log_admin_action(interaction.user.display_name, "Vegas", f"Verified Ticket #{self.bet_id} as LOST")
        await interaction.response.edit_message(content=f"❌ Bet **{self.bet_id}** marked LOST.", view=None)
        
    @discord.ui.button(label="Nullify (Refund)", style=discord.ButtonStyle.secondary)
    async def nullify(self, interaction, button):
        state = load_state()
        if state['bets'].get(self.bet_id, {}).get('status') != 'Pending_Review': return await interaction.response.send_message("Bet already processed.", ephemeral=True)
        state['bets'][self.bet_id]['status'] = 'Nullified'
        refund_amt = state['bets'][self.bet_id]['amt']
        state['balances'][self.uid] = state['balances'].get(self.uid, 0) + refund_amt
        save_state(state)
        log_admin_action(interaction.user.display_name, "Vegas", f"Nullified Ticket #{self.bet_id} (Refunded {refund_amt})")
        await interaction.response.edit_message(content=f"🔄 Bet **{self.bet_id}** Nullified. VC Refunded.", view=None)

