class AddRegistryModal(discord.ui.Modal, title='Add User to Registry'):
    discord_id = discord.ui.TextInput(label='Player Discord ID', placeholder='1234567890')
    gamertag = discord.ui.TextInput(label='Gamertag', placeholder='Xbox/PSN Name')
    team_name = discord.ui.TextInput(label='Team Name', placeholder='Assigned Team')

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        
        state = load_state()
        uid = self.discord_id.value.strip()
        gt = self.gamertag.value.strip()
        team = self.team_name.value.strip()
        
        # 1. Initialize their profiles & Add to Master User Dict (Fixes the CSV!)
        state = init_rpg_profile(uid, state) 
        state.setdefault('users', {})[uid] = {
            "gamertag": gt, "team": team, "quote": "I let my game speak for itself.",
            "pin": "1234", "pin_changed": False
        }
        
        # 2. Add to Team Roster
        roster_data = state.setdefault('rosters', {}).setdefault(team, {'active': [], 'inactive': []})
        if len(roster_data['active']) < 10 and gt not in roster_data['active']:
            roster_data['active'].append(gt)
            
        save_state(state)
        
        # 3. Push EXACTLY 6 columns to Google Sheets
        vc = state.get('balances', {}).get(uid, 0)
        sb = state.get('rpg', {}).get(uid, {}).get('cupbucks', 0)
        
        try:
            payload = {
                "secret": "SPAM_BOT_SECRET_123",
                "sheet": "SPAM_Registry",
                "action": "append_multiple",
                "data": [[uid, gt, team, "I let my game speak for itself.", vc, sb]]
            }
            def _post(): return requests.post(APPS_SCRIPT_URL, json=payload)
            await asyncio.to_thread(_post)
            log_admin_action(interaction.user.display_name, "System", f"Registered {gt} to {team}")
            await interaction.followup.send(f"✅ User `{gt}` registered! Ready for CSV Export.", ephemeral=True)
        except Exception as e:
            await interaction.followup.send(f"⚠️ Saved to bot, but pushing to Sheets failed. `{str(e)[:900]}`", ephemeral=True)

class ApproveRosterMovesSelect(discord.ui.Select):
    def __init__(self, pending_moves):
        self.pending_moves = pending_moves
        options = [discord.SelectOption(label=f"[{m['type'].upper()}] {m['gamertag']} ({m['team']})", value=str(i)) for i, m in enumerate(pending_moves[:25])]
        super().__init__(placeholder="Select a move to approve...", min_values=1, max_values=1, options=options)

    async def callback(self, interaction: discord.Interaction):
        move_idx = int(self.values[0])
        move = self.pending_moves[move_idx]
        
        state = load_state()
        team = move['team']
        gt = move['gamertag']
        
        roster_data = state.setdefault('rosters', {}).setdefault(team, {'active': [], 'inactive': []})
        
        if move['type'] == 'add':
            if len(roster_data['active']) >= 10:
                return await interaction.response.send_message("🚫 **Team active roster is full (10/10).**", ephemeral=True)
            roster_data['active'].append(gt)
            # Push to Google Sheets registry
            if 'discord_id' in move and move['discord_id']:
                try:
                    payload = {"secret": "SPAM_BOT_SECRET_123", "sheet": "SPAM_Registry", "action": "append_multiple", "data": [[gt, move['discord_id'], team]]}
                    def _post(): return requests.post(APPS_SCRIPT_URL, json=payload)
                    await asyncio.to_thread(_post)
                except: pass
                
        elif move['type'] == 'drop':
            if gt in roster_data['active']: roster_data['active'].remove(gt)
            if gt not in roster_data['inactive']: roster_data['inactive'].append(gt)

        state['pending_roster_moves'].pop(move_idx)
        save_state(state)
        
        log_admin_action(interaction.user.display_name, "System", f"Approved Roster {move['type'].title()}: {gt} for {team}")
        await interaction.response.edit_message(content=f"✅ Move Approved: **{gt}** ({move['type'].title()}) for **{team}**.", view=None)

