        if action == "Global VC Stimulus (+1000)":
            state = load_state()
            for uid in state['balances']: state['balances'][uid] += 1000
            save_state(state)
            log_admin_action(interaction.user.display_name, "Economy", "Triggered a Global 1,000 VC Stimulus.")
