            if not pending: return await interaction.response.send_message("🛡️ **Vault Empty.** No pending bets.", ephemeral=True)
            
            await interaction.response.send_message("🛡️ **Vegas Vault Opened.** Select a bet to resolve:", ephemeral=True)
            for bid, data in list(pending.items())[:5]: # Show 5 at a time
                embed = discord.Embed(title=f"🎫 Ticket #{bid} ({data.get('type', 'Unknown')})", color=0xFF9F0A)
