class FlashBetWagerModal(discord.ui.Modal, title='FLASH BET: 50% OFF WAGER'):
    wager = discord.ui.TextInput(label='Wager Amount (We will charge HALF)', placeholder='e.g., 500 (Costs 250)', max_length=4)
    def __init__(self, legs):
        super().__init__()
        self.legs = legs
        
    async def on_submit(self, interaction: discord.Interaction):
        state = load_state()
        uid = str(interaction.user.id)
        
        try: original_amt = int(self.wager.value)
        except: return await interaction.response.send_message("❌ Invalid amount.", ephemeral=True)
        
        discounted_amt = int(original_amt * 0.5) 
        
        if discounted_amt > 750: return await interaction.response.send_message("🚫 **House Limit Exceeded.**", ephemeral=True)
        if state['balances'].get(uid, 0) < discounted_amt: return await interaction.response.send_message("🚫 **Insufficient Funds.**", ephemeral=True)
        
        odds_mult = len(self.legs) * 1.9 
        payout = int(original_amt * odds_mult)
        
        state['balances'][uid] -= discounted_amt
        bid = str(random.randint(100000, 999999))
        
        state.setdefault('bets', {})[bid] = {
            'uid': uid, 'type': 'Flash_Bet',
            'desc': " | ".join(self.legs), 'amt': discounted_amt, 'payout': payout, 
            'status': 'Pending_Review'
        }
        save_state(state)
        
        embed = discord.Embed(title=f"⚡ FLASH TICKET #{bid} PRINTED", description=f"You paid {discounted_amt} VC for a {original_amt} VC bet!", color=0x32D74B)
        embed.add_field(name="Discounted Wager", value=f"{discounted_amt} VC", inline=True)
        embed.add_field(name="Est. Payout", value=f"{payout} VC", inline=True)
        embed.add_field(name="Legs", value="\n".join(self.legs), inline=False)
        await interaction.response.send_message(embed=embed)

class FlashBetView(discord.ui.View):
    def __init__(self, bets, creation_time):
        super().__init__(timeout=120) 
        self.bets = bets
        self.creation_time = creation_time

    @discord.ui.button(label="⚡ PLACE FLASH BET (50% OFF)", style=discord.ButtonStyle.success, emoji="⏳")
    async def flash_bet(self, interaction: discord.Interaction, button: discord.ui.Button):
        if time.time() - self.creation_time > 120:
            return await interaction.response.send_message("❌ **Too late!** The 2-minute Flash Bet window has closed. Go to the /gamblingshack for regular odds.", ephemeral=True)
        
        await interaction.response.send_message(f"⚡ **FLASH WINDOW OPEN!** Select your props:", view=ParlayBuilderView(str(interaction.user.id), self.bets, is_flash=True), ephemeral=True)
        
    async def on_timeout(self):
        for child in self.children: 
            child.disabled = True
            child.label = "Flash Window Closed"
            child.style = discord.ButtonStyle.secondary

def _categorize_bet(b):
    """Bucket a bet string so a >25-item board can be browsed by category
    inside Discord's 25-option select limit."""
    s = str(b)
    if s.startswith("📅 SERIES"):
        return "📅 Series (2-Game Set)"
    low = s.lower()
    if "moneyline" in low or "spread" in low:
        return "💰 Moneyline & Spread"
    if "team total" in low or ("game o/u" in low) or "total points" in low:
        return "📊 Totals"
    # Named-player prop lines look like "<name> O/U <n> PTS/REB/AST (-110)"
    if re.search(r'\bO/U\b.*\b(PTS|REB|AST|STL|BLK|3PM|TO|PF)\b', s) and "any player" not in low:
        return "🎯 Player Props"
    if "any player" in low or "double-double" in low or "triple-double" in low:
        return "🃏 Exotics / Anytime"
    return "🃏 Exotics / Anytime"


class ParlayBuilderView(discord.ui.View):
    CATEGORY_ORDER = ["💰 Moneyline & Spread", "📊 Totals", "🎯 Player Props",
                      "📅 Series (2-Game Set)", "🃏 Exotics / Anytime"]

    def __init__(self, uid, available_bets, is_flash=False, team1=None, team2=None):
        super().__init__(timeout=300)
        self.uid, self.available_bets = uid, list(available_bets or [])
        self.is_flash = is_flash
        self.team1, self.team2 = team1, team2
        self.legs = []
        # Group bets into categories so nothing gets truncated by the 25 cap.
        self.categories = {}
        for b in self.available_bets:
            self.categories.setdefault(_categorize_bet(b), []).append(b)
        ordered = [c for c in self.CATEGORY_ORDER if c in self.categories]
        ordered += [c for c in self.categories if c not in ordered]
        self.category_names = ordered
        self.active_category = ordered[0] if ordered else None
        if len(self.category_names) > 1:
            self.add_item(BetCategoryDropdown(self))
        self.bet_dropdown = BetSelectDropdown(self)
        self.add_item(self.bet_dropdown)

    def refresh_bet_dropdown(self):
        self.remove_item(self.bet_dropdown)
        self.bet_dropdown = BetSelectDropdown(self)
        self.add_item(self.bet_dropdown)

    def slip_text(self):
        if not self.legs:
            return "*(empty)*"
        return "\n".join([f"Leg {i+1}: {leg}" for i, leg in enumerate(self.legs)])

    @discord.ui.button(label="Submit Slip (Max 750 VC)", style=discord.ButtonStyle.success, row=4)
    async def submit_parlay(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not self.legs: return await interaction.response.send_message("❌ You haven't added any legs!", ephemeral=True)
        if self.is_flash:
            await interaction.response.send_modal(FlashBetWagerModal(self.legs))
        else:
            await interaction.response.send_modal(ShackWagerModal(self.legs))

    @discord.ui.button(label="🎯 Add Custom / Player Prop", style=discord.ButtonStyle.primary, row=4)
    async def add_custom(self, interaction: discord.Interaction, button: discord.ui.Button):
        # Let a bettor build their own leg mid-slip (player picker + Bovada builder).
        await interaction.response.send_message(
            "Build your own leg:",
            view=PropStudioView(self.uid, self.team1, self.team2, attach_to=self),
            ephemeral=True)


class BetCategoryDropdown(discord.ui.Select):
    def __init__(self, parent_view):
        self.parent_view = parent_view
        opts = []
        for c in parent_view.category_names:
            n = len(parent_view.categories.get(c, []))
            opts.append(discord.SelectOption(
                label=f"{c} ({n})", value=c,
                default=(c == parent_view.active_category)))
        super().__init__(placeholder="📂 Pick a market category...",
                         min_values=1, max_values=1, options=opts[:25], row=0)

    async def callback(self, interaction: discord.Interaction):
        self.parent_view.active_category = self.values[0]
        self.parent_view.refresh_bet_dropdown()
        await interaction.response.edit_message(
            content=f"📝 **Current Slip:**\n{self.parent_view.slip_text()}\n\n"
                    f"Category: **{self.parent_view.active_category}** — pick a leg.",
            view=self.parent_view)


class BetSelectDropdown(discord.ui.Select):
    def __init__(self, parent_view):
        self.parent_view = parent_view
        cat = parent_view.active_category
        bets = parent_view.categories.get(cat, []) if cat else parent_view.available_bets
        self._bets = bets[:25]
        options = [discord.SelectOption(label=b[:100], value=str(i))
                   for i, b in enumerate(self._bets)] or [
                   discord.SelectOption(label="(no bets in this category)", value="__none__")]
        super().__init__(placeholder="Select a bet to add to slip...",
                         min_values=1, max_values=1, options=options, row=1)

    async def callback(self, interaction: discord.Interaction):
        if self.values[0] == "__none__":
            return await interaction.response.defer()
        selected_bet = self._bets[int(self.values[0])]
        self.parent_view.legs.append(selected_bet)
        await interaction.response.edit_message(
            content=f"📝 **Current Slip:**\n{self.parent_view.slip_text()}\n\nAdd another or click Submit.",
            view=self.parent_view)

