# ============================================================
#  PROP STUDIO — pick any player from the two matchup rosters,
#  or build a fully custom "Bovada-style" prop. Every built leg
#  drops onto the bettor's slip and flows to the admin desk for
#  grading (same Pending_Review pipeline as the sharp board).
# ============================================================

PROP_STATS = ["PTS", "REB", "AST", "STL", "BLK", "3PM", "TO"]

def _prop_pnorm(s):
    return re.sub(r'[^a-z0-9]', '', str(s).lower())

def matchup_player_pool(team1, team2, state=None):
    """{team_name: [display names]} strictly from each team's OWN roster —
    the same guard used on the sharp board, exposed for the picker UI."""
    state = state or load_state()
    pool = {}
    for t in (team1, team2):
        if not t:
            continue
        try:
            members, _meta = resolve_team_roster(t, state)
        except Exception:
            members = []
        names = []
        for m in members:
            nm = (m or {}).get('name')
            if nm and nm != '(unknown)' and nm not in names:
                names.append(nm)
        pool[t] = names
    return pool

def suggest_prop_line(player_name, stat):
    """rolling(5)*0.6 + career*0.4 line for a player+stat, or None if no history."""
    try:
        p_df, _ = load_data()
    except Exception:
        p_df = None
    if p_df is None or p_df.empty:
        return None
    name_map = {}
    for nm in p_df['PlayerName'].dropna().unique():
        name_map.setdefault(_prop_pnorm(nm), str(nm))
    canon = name_map.get(_prop_pnorm(player_name))
    if not canon or stat not in p_df.columns:
        return None
    logs = p_df[p_df['PlayerName'] == canon].sort_values('Game_ID', ascending=False)
    if logs.empty:
        return None
    l5 = logs.head(5)
    mean = (l5[stat].mean() * 0.6) + (logs[stat].mean() * 0.4)
    if pd.isna(mean):
        return None
    return max(0.5, math.ceil(float(mean) * 2) / 2)

def _clamp_american_odds(raw, lo=-400, hi=600):
    """Parse & clamp user odds into a sane house range. Returns '(+xxx)'/'(-xxx)'."""
    try:
        o = int(re.sub(r'[^0-9\-+]', '', str(raw)))
    except Exception:
        o = -110
    if o == 0:
        o = -110
    if -99 < o < 100:            # illegal american odds gap
        o = 100 if o >= 0 else -110
    o = max(lo, min(hi, o))
    return f"(+{o})" if o > 0 else f"({o})"


class PropStudioView(discord.ui.View):
    """Entry hub: choose a player prop from rosters, or build a custom prop."""
    def __init__(self, uid, team1=None, team2=None, attach_to=None):
        super().__init__(timeout=300)
