class PropTeamSelectView(discord.ui.View):
    def __init__(self, uid, team1, team2, attach_to):
        super().__init__(timeout=300)
        self.uid, self.team1, self.team2, self.attach_to = str(uid), team1, team2, attach_to
        pool = matchup_player_pool(team1, team2)
        opts = []
        for t in (team1, team2):
            n = len(pool.get(t, []))
            opts.append(discord.SelectOption(label=f"{t} ({n} players)"[:100], value=t[:100]))
        sel = discord.ui.Select(placeholder="Pick the team...", options=opts)
        async def cb(i: discord.Interaction):
            team = sel.values[0]
            names = pool.get(team, []) or matchup_player_pool(team, None).get(team, [])
            if not names:
                return await i.response.edit_message(
                    content=f"⚠️ No roster found for **{team}**. Make sure the team is spelled exactly as it appears in the OFFICIAL roster channel.",
                    view=None)
            await i.response.edit_message(
                content=f"**{team}** — pick a player:",
                view=PropPlayerSelectView(self.uid, team, names, self.attach_to))
        sel.callback = cb
        self.add_item(sel)


