class PropLineModal(discord.ui.Modal):
    def __init__(self, uid, player, stat, attach_to):
        super().__init__(title=f"{player[:20]} — {stat} O/U")
        self.uid, self.player, self.stat, self.attach_to = str(uid), player, stat, attach_to
        suggested = suggest_prop_line(player, stat)
        self.line = discord.ui.TextInput(
            label=f"{stat} line",
            placeholder="e.g., 12.5",
            default=(str(suggested) if suggested is not None else ""),
            required=True, max_length=6)
        self.direction = discord.ui.TextInput(
            label="Over or Under?",
            placeholder="over  /  under",
            default="over", required=True, max_length=5)
        self.add_item(self.line)
        self.add_item(self.direction)

    async def on_submit(self, interaction: discord.Interaction):
        try:
            line = float(re.sub(r'[^0-9.]', '', self.line.value))
        except Exception:
            return await interaction.response.send_message("❌ Invalid line.", ephemeral=True)
        direction = "Over" if self.direction.value.strip().lower().startswith("o") else "Under"
        line_str = (f"{line:.1f}" if line % 1 else f"{line:.0f}")
        leg = f"🎯 {self.player} {direction} {line_str} {self.stat} (-110)"
        await _finish_prop(interaction, self.uid, leg, self.attach_to)


class CustomPropModal(discord.ui.Modal, title="Custom Prop (Bovada-style)"):
    prop = discord.ui.TextInput(
        label="Prop wording",
        placeholder="e.g., Krashout wins Game 1 by 20+",
        required=True, max_length=120)
    line = discord.ui.TextInput(
        label="O/U line (optional)",
        placeholder="Leave blank for a Yes/No prop",
        required=False, max_length=8)
    odds = discord.ui.TextInput(
        label="Your odds (American, house-clamped)",
        placeholder="-110, +150, +300 …",
        default="-110", required=True, max_length=7)
    direction = discord.ui.TextInput(
        label="Side (over/under/yes/no)",
        placeholder="over / under / yes / no",
        default="yes", required=False, max_length=6)

    def __init__(self, uid, attach_to):
        super().__init__()
        self.uid, self.attach_to = str(uid), attach_to

    async def on_submit(self, interaction: discord.Interaction):
        desc = self.prop.value.strip()
        odds = _clamp_american_odds(self.odds.value)
        side = (self.direction.value or "").strip().lower()
        parts = [f"✍️ {desc}"]
        if self.line.value.strip():
            try:
                ln = float(re.sub(r'[^0-9.]', '', self.line.value))
                d = "Over" if side.startswith("o") else ("Under" if side.startswith("u") else "Over")
                parts.append(f"— {d} {ln:g}")
            except Exception:
                pass
        elif side in ("yes", "no"):
            parts.append(f"— {side.title()}")
        leg = " ".join(parts) + f" {odds}"
        await _finish_prop(interaction, self.uid, leg, self.attach_to, custom=True)


async def _finish_prop(interaction, uid, leg, attach_to, custom=False):
    """Attach the built leg to an open slip, or open a fresh one-leg slip."""
    tag = "Custom prop" if custom else "Player prop"
    if attach_to is not None:
        attach_to.legs.append(leg)
        return await interaction.response.send_message(
            f"✅ **{tag} added to your slip:**\n`{leg}`\n\n"
            f"Go back to the slip and pick another leg or hit **Submit**. "
            f"Current legs: {len(attach_to.legs)}",
            ephemeral=True)
    view = ParlayBuilderView(str(uid), [leg])
    view.legs.append(leg)  # pre-load the built leg
    await interaction.response.send_message(
        f"✅ **{tag} built:**\n`{leg}`\n\nAdd more from the board or hit **Submit**.",
        view=view, ephemeral=True)


