async def sync_knowledge_vault():
    print(f"Scanning for Knowledge Files in {KNOWLEDGE_VAULT_PATH}...")
    
    # Auto-create the folder if you haven't made it yet
    if not os.path.exists(KNOWLEDGE_VAULT_PATH):
        os.makedirs(KNOWLEDGE_VAULT_PATH)
        print("📁 Created new Knowledge folder. Drop your files in there!")
        
    # Gemini's supported file types (Docs, Spreadsheets, Images, Audio, Video)
    valid_extensions = (
        '.pdf', '.txt', '.csv', '.md', '.json', '.docx', '.rtf',
        '.png', '.jpg', '.jpeg', '.webp',
        '.mp3', '.wav', '.mp4', '.mov'
    )
        
    # Find EVERY file that matches the valid extensions
    vault_files = [f for f in os.listdir(KNOWLEDGE_VAULT_PATH) if f.lower().endswith(valid_extensions)]
    
    if not vault_files:
        print("⚠️ No valid files found in the Knowledge Vault.")
        return

    # Upload them all dynamically
    for file_name in vault_files:
        full_path = os.path.join(KNOWLEDGE_VAULT_PATH, file_name)
        def _upload():
            return ai_client.files.upload(file=full_path)
        try:
            uploaded_file = await asyncio.to_thread(_upload)
            uploaded_gemini_files[file_name] = uploaded_file
            print(f"✅ Uploaded {file_name} to Gemini's Brain as {uploaded_file.name}")
        except Exception as e:
            print(f"❌ Error uploading {file_name}: {e}")

_last_refresh = 0.0
REFRESH_COOLDOWN = 300  # seconds — re-pull sheet at most once every 5 minutes

async def refresh_stats_and_vault(force: bool = False):
    """Re-fetches live stats from Google Sheets and re-scans the KnowledgeVault folder.
    Called automatically every time /ask_qcl or /ask_claude is invoked.
    Skips the network hit if data was refreshed within the last 5 minutes.
    Pass force=True to bypass the cooldown (used by commands like /writeup that
    must see a box score the moment it lands in the sheet)."""
    global _last_refresh
    now = time.time()
    if not force and now - _last_refresh < REFRESH_COOLDOWN:
        return  # Data is fresh enough — skip the network round-trip
    _last_refresh = now
    # 1. Refresh the live stat cache from the Google Sheet
    try:
        await asyncio.to_thread(load_and_process_stats)
    except Exception as e:
        print(f"[refresh] Stat Engine Error: {e}")

    # 2. Re-scan the KnowledgeVault folder for any new or changed files
    if not os.path.exists(KNOWLEDGE_VAULT_PATH):
        os.makedirs(KNOWLEDGE_VAULT_PATH)
        return

    valid_extensions = (
        '.pdf', '.txt', '.csv', '.md', '.json', '.docx', '.rtf',
        '.png', '.jpg', '.jpeg', '.webp',
        '.mp3', '.wav', '.mp4', '.mov'
    )
    vault_files = [f for f in os.listdir(KNOWLEDGE_VAULT_PATH) if f.lower().endswith(valid_extensions)]

    for file_name in vault_files:
        if file_name not in uploaded_gemini_files:
            full_path = os.path.join(KNOWLEDGE_VAULT_PATH, file_name)
            def _upload(fp=full_path):
                return ai_client.files.upload(file=fp)
            try:
                uploaded_file = await asyncio.to_thread(_upload)
                uploaded_gemini_files[file_name] = uploaded_file
                print(f"[refresh] Auto-uploaded new vault file: {file_name}")
            except Exception as e:
                print(f"[refresh] Could not upload {file_name}: {e}")


def read_vault_as_text(max_chars_per_file: int = 8000) -> str:
    """Reads every text-readable file in the KnowledgeVault and returns them
    as a single concatenated string — used to feed the Anthropic (Claude) API,
    which cannot consume Gemini file objects."""
    if not os.path.exists(KNOWLEDGE_VAULT_PATH):
        return ""
    text_extensions = ('.txt', '.md', '.csv', '.json', '.rtf')
    chunks = []
    for file_name in sorted(os.listdir(KNOWLEDGE_VAULT_PATH)):
        if not file_name.lower().endswith(text_extensions):
            continue
        full_path = os.path.join(KNOWLEDGE_VAULT_PATH, file_name)
        try:
            with open(full_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read(max_chars_per_file)
            chunks.append(f"--- KNOWLEDGE VAULT FILE: {file_name} ---\n{content}\n")
        except Exception as e:
            print(f"[vault_text] Could not read {file_name}: {e}")
    return "\n".join(chunks)


