# ============================================================
# --- END-OF-DAY SYNC (Tier 5) ---
# Reconciles the whole league once a day (and on demand via /admin sync_now):
#   1. Re-pulls the Google Sheet so records/standings are current.
#   2. Reads Discord roles to mark teams Active/Inactive and snapshot each
#      active team's current members (strips role IDs -> who is actually here),
#      keeping the users map's team tags from going stale.
#   3. Rebuilds the AI brain (roster.json + the vault .md).
# Non-destructive: legacy teams plus balances/RPG/hunt/fines are untouched.
# ============================================================
EOD_SYNC_UTC_HOUR = int(os.getenv("EOD_SYNC_UTC_HOUR", "7"))      # ~1-2 AM US Central
SYNC_LOG_CHANNEL_ID = int(os.getenv("SYNC_LOG_CHANNEL_ID", "0"))  # 0 = don't post to a channel


async def run_full_sync(reason: str = "scheduled"):
    """End-of-day reconciliation. Returns a summary dict (also used by /admin sync_now)."""
    summary = {"reason": reason, "stat_engine": False, "teams_active": 0,
               "teams_inactive": 0, "members_synced": 0, "users_retagged": 0,
               "brain": False, "errors": []}

    # 1) Records — re-pull the Sheet
    try:
        await asyncio.to_thread(load_and_process_stats)
        summary["stat_engine"] = True
    except Exception as e:
        summary["errors"].append(f"stat engine: {str(e)[:200]}")

    # 2) Discord roles -> team activity + live member snapshot
    try:
        state = load_state()
        teams_reg = state.setdefault('teams', {})
        users = state.setdefault('users', {})
        guilds = [g for g in bot.guilds if g.id in ALLOWED_GUILD_IDS] or list(bot.guilds)
        now_iso = _security_datetime.datetime.utcnow().isoformat() + "Z"
        for name, data in teams_reg.items():
            if not isinstance(data, dict):
                continue
            rid = data.get('role_id')
            role = None
            for g in guilds:
                if rid:
                    try:
                        role = g.get_role(int(rid))
                    except Exception:
                        role = None
                if role:
                    break
            if role:
                members = [{'uid': str(m.id),
                            'name': (users.get(str(m.id), {}) or {}).get('gamertag') or m.display_name}
                           for m in role.members if not m.bot]
                data['status'] = 'active'
                data['last_active'] = now_iso
                data['roster'] = members
                summary["teams_active"] += 1
                summary["members_synced"] += len(members)
                for mem in members:
                    u = users.get(mem['uid'], {}) or {}
                    if u.get('team') != name:
                        users[mem['uid']] = {**u, 'team': name,
                                             'gamertag': u.get('gamertag') or mem['name']}
                        summary["users_retagged"] += 1
            else:
                data['status'] = 'inactive'
                summary["teams_inactive"] += 1
        save_state(state)
    except Exception as e:
        summary["errors"].append(f"role sync: {str(e)[:200]}")

    # 3) Rebuild the AI brain (roster.json + vault .md)
    try:
        roster = await build_discord_roster()
        write_roster_to_disk(roster)
        summary["brain"] = True
    except Exception as e:
        summary["errors"].append(f"brain: {str(e)[:200]}")

    return summary


def _sync_summary_embed(summary):
    ok = not summary["errors"]
    e = discord.Embed(title=("\u2705 End-of-Day Sync" if ok else "\u26a0\ufe0f End-of-Day Sync (with warnings)"),
                      color=(0x32D74B if ok else 0xFF9F0A),
                      description=f"Trigger: **{summary['reason']}**")
    e.add_field(name="Records", value=("Refreshed from Sheet" if summary["stat_engine"] else "Failed"), inline=True)
    e.add_field(name="Active teams", value=str(summary["teams_active"]), inline=True)
    e.add_field(name="Inactive teams", value=str(summary["teams_inactive"]), inline=True)
    e.add_field(name="Members synced", value=str(summary["members_synced"]), inline=True)
    e.add_field(name="Users re-tagged", value=str(summary["users_retagged"]), inline=True)
    e.add_field(name="AI brain", value=("Rebuilt" if summary["brain"] else "Failed"), inline=True)
    if summary["errors"]:
        e.add_field(name="Warnings", value="\n".join(f"\u2022 {x}" for x in summary["errors"])[:1024], inline=False)
    e.set_footer(text="Runs daily \u00b7 or on demand with /admin sync_now")
    return e


@tasks.loop(time=_security_datetime.time(hour=EOD_SYNC_UTC_HOUR, minute=0))
async def end_of_day_sync():
    try:
        summary = await run_full_sync(reason="scheduled (end of day)")
        print(f"[EOD SYNC] {summary}")
        if SYNC_LOG_CHANNEL_ID:
            ch = bot.get_channel(SYNC_LOG_CHANNEL_ID)
            if ch:
                try:
                    await ch.send(embed=_sync_summary_embed(summary))
                except Exception as e:
                    print(f"[EOD SYNC] channel post failed: {e}")
    except Exception as e:
        print(f"[EOD SYNC] fatal: {e}")


@end_of_day_sync.before_loop
async def _before_end_of_day_sync():
    await bot.wait_until_ready()


def _parse_urg_registration_links(raw_links):
    """Parse one registration link per line: Label | https://example.com."""
    links = []
    for line in str(raw_links or "").splitlines():
        line = line.strip()
        if not line:
            continue
        if "|" in line:
            label, url = (part.strip() for part in line.split("|", 1))
        else:
            label, url = f"Registration {len(links) + 1}", line
        if url.startswith(("https://", "http://")):
            links.append((label[:80] or f"Registration {len(links) + 1}", url))
    return links[:5]


def _parse_urg_event_details(raw_details):
    """Support `32 | Double elimination` while keeping both fields visible."""
    parts = [part.strip() for part in str(raw_details or "").split("|", 1)]
    return (parts[0] or "TBA", parts[1] if len(parts) > 1 and parts[1] else "TBA")


def _urg_progress_embed(
    flyer_name,
    total_recipients,
    attempted,
    sent_count,
    skipped_count,
    status,
):
    remaining = max(total_recipients - attempted, 0)
    estimated_minutes = (remaining * 1.5) / 60
    embed = discord.Embed(
        title="📣 URG MASS DM PROGRESS",
        color=0x32D74B if status == "Complete" else 0xFF9F0A,
        description=f"Flyer: **{flyer_name}**\nStatus: **{status}**",
    )
    embed.add_field(
        name="Recipients",
        value=f"{total_recipients:,}",
        inline=True,
    )
    embed.add_field(
        name="Attempted",
        value=f"{attempted:,} / {total_recipients:,}",
        inline=True,
    )
    embed.add_field(name="Sent", value=f"{sent_count:,}", inline=True)
    embed.add_field(name="Failed / Skipped", value=f"{skipped_count:,}", inline=True)
    embed.add_field(name="Remaining", value=f"{remaining:,}", inline=True)
    embed.add_field(
        name="Estimated Time Left",
        value=(
            "Complete"
            if status == "Complete"
            else f"~{estimated_minutes:.1f} minutes"
        ),
        inline=True,
    )
    return embed


