class URGOptInButton(discord.ui.Button):
    def __init__(self, bot, campaign_id, registration_links):
        self.bot = bot
        self.campaign_id = campaign_id
        self.registration_links = registration_links
        super().__init__(
            label="I'm Interested",
            style=discord.ButtonStyle.success,
            emoji="✅",
            custom_id=f"urg:opt_in:{campaign_id}",
        )

    async def callback(self, interaction: discord.Interaction):
        state = load_state()
        campaign = state.get("urg_registration_stats", {}).get(self.campaign_id)
        if campaign is None:
            await interaction.response.send_message(
                "⚠️ This opt-in campaign is no longer available.",
                ephemeral=True,
            )
            return

        users = campaign.setdefault("interested_users", [])
        user_id = str(interaction.user.id)
        if user_id not in {str(user.get("id")) for user in users}:
            users.append({
                "id": user_id,
                "name": str(getattr(interaction.user, "display_name", interaction.user)),
            })
            save_state(state)

        await interaction.response.send_message(
            "✅ You’re marked as interested. Choose a registration option below:",
            view=URGRegistrationView(
                self.bot,
                self.campaign_id,
                self.registration_links,
            ),
            ephemeral=True,
        )


