class URGEventSelect(discord.ui.Select):
    """Select the flyer to use for a mass DM campaign."""

    def __init__(self, event_files, owner_id):
        self.event_files = event_files
        self.owner_id = owner_id
        options = [
            discord.SelectOption(
                label=os.path.basename(event_path)[:100],
                value=str(index),
                description="Use this flyer for mass DMs.",
            )
            for index, event_path in enumerate(event_files[:25])
        ]
        super().__init__(
            placeholder="Select a flyer for mass DMs...",
            min_values=1,
            max_values=1,
            options=options,
            row=0,
        )

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message(
                "🚫 Only the admin who opened this Command Center can use it.",
                ephemeral=True,
            )
            return
        if not getattr(interaction.user.guild_permissions, "administrator", False):
            await interaction.response.send_message(
                "🚫 Administrator permission is required.",
                ephemeral=True,
            )
            return

        try:
            selected_path = self.event_files[int(self.values[0])]
        except (IndexError, ValueError):
            await interaction.response.send_message(
                "⚠️ That flyer is no longer available. Run `!commandcenter` again.",
                ephemeral=True,
            )
            return

        if self.view is not None:
            self.view.selected_event_path = selected_path
        await interaction.response.send_message(
            f"✅ Flyer selected: **{os.path.basename(selected_path)}**. "
            "Click **Send Mass DMs** when ready.",
            ephemeral=True,
        )


