class URGStatsButton(discord.ui.Button):
    def __init__(self, owner_id):
        self.owner_id = owner_id
        super().__init__(
            label="Registration Stats",
            style=discord.ButtonStyle.secondary,
            emoji="📊",
            custom_id=f"urg:registration_stats:{owner_id}",
            row=1,
        )

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message(
                "🚫 Only the admin who opened this Command Center can use it.",
                ephemeral=True,
            )
            return
        if not getattr(interaction.user.guild_permissions, "administrator", False):
            await interaction.response.send_message(
                "🚫 Administrator permission is required.",
                ephemeral=True,
            )
            return

        campaigns = load_state().get("urg_registration_stats", {})
        embed = discord.Embed(
            title="📊 URG Registration Stats",
            color=0x32D74B,
        )
        if not campaigns:
            embed.description = "No URG registration campaigns have been recorded yet."
        else:
            for campaign_id, campaign in list(campaigns.items())[-10:]:
                delivery_mode = str(campaign.get("delivery_mode", "mass_dm"))
                mode_label = (
                    "Announcement"
                    if delivery_mode == "announcement"
                    else "Mass DMs"
                )
                interested_users = campaign.get("interested_users", [])
                interested_names = ", ".join(
                    f"<@{user.get('id')}>"
                    for user in interested_users[:15]
                    if user.get("id")
                )
                if len(interested_users) > 15:
                    interested_names += f" (+{len(interested_users) - 15} more)"
                lines = [
                    f"Flyer: **{campaign.get('event', 'Unknown')}**",
                    f"Delivery: **{mode_label}**",
                    f"Opted in: **{len(interested_users)}**"
                    + (f"\nInterested: {interested_names}" if interested_names else ""),
                ]
                for url, link in campaign.get("links", {}).items():
                    users = link.get("users", [])
                    names = ", ".join(
                        f"<@{user.get('id')}>"
                        for user in users[:15]
                    )
                    if len(users) > 15:
                        names += f" (+{len(users) - 15} more)"
                    lines.append(
                        f"**{link.get('label', 'Registration')}** — "
                        f"{link.get('clicks', 0)} clicks"
                        + (f"\nInterested: {names}" if names else "")
                    )
                embed.add_field(
                    name=f"Campaign {campaign_id[-6:]}",
                    value="\n".join(lines)[:1024],
                    inline=False,
                )
        await interaction.response.send_message(embed=embed, ephemeral=True)


