class QSPNBot(commands.Bot):
    def __init__(self):
        # Keep QCL's ! commands and Federal Reserve's legacy .fast5 commands.
        super().__init__(
            command_prefix=commands.when_mentioned_or("!", "."),
            intents=discord.Intents.all(),
        )
        # --- NEW: The toggle switch (defaults to Off) and allowed channels ---
        self.auto_download_enabled = False 
        self.target_channels = [
            1406062299671691364, 
            1406062329958760488, 
            1406062352511799408, 
            1406062383151190068
        ]
        self.last_message_times = {} # <--- ADD THIS LINE HERE
        self.urg_lockdown_active = False
        self.urg_broadcast_link = ""

    async def _send_urg_broadcast(
        self,
        guild,
        embed,
        event_path,
        campaign_id,
        registration_links,
        status_message,
        total_recipients,
    ):
        """DM a registration flyer without changing chat lockdown."""
        sent_count = 0
        skipped_count = 0

        async def publish_progress(status):
            attempted = sent_count + skipped_count
            progress_embed = _urg_progress_embed(
                os.path.basename(event_path),
                total_recipients,
                attempted,
                sent_count,
                skipped_count,
                status,
            )
            try:
                state = load_state()
                campaign = state.get("urg_registration_stats", {}).get(campaign_id)
                if campaign is not None:
                    campaign["dm_progress"] = {
                        "total": total_recipients,
                        "attempted": attempted,
                        "sent": sent_count,
                        "failed": skipped_count,
                        "status": status,
                    }
                    save_state(state)
            except Exception as exc:
                print(f"[URG] Could not save DM progress: {exc}")

            if status_message is not None:
                try:
                    await status_message.edit(embed=progress_embed)
                except (discord.Forbidden, discord.HTTPException, discord.NotFound):
                    pass

        await publish_progress("Running")
        for member in guild.members:
            if member.bot:
                continue

            quarantine_detected = False
            try:
                # Discord consumes the file stream, so create a fresh File
                # object for each DM.
                await member.send(
                    embed=embed,
                    file=discord.File(
                        event_path,
                        filename=os.path.basename(event_path),
                    ),
                    view=URGRegistrationView(
                        self,
                        campaign_id,
                        registration_links,
                    ),
                )
                sent_count += 1
            except (discord.Forbidden, discord.HTTPException, OSError) as exc:
                skipped_count += 1
                if (
                    isinstance(exc, discord.HTTPException)
                    and getattr(exc, "code", None) == 20026
                ):
                    quarantine_detected = True
                    print(
                        "[URG] Discord anti-spam quarantine detected. "
                        "Stopping the mass DM campaign immediately."
                    )
                else:
                    print(f"[URG] Could not DM {member} ({member.id}): {exc}")

            if quarantine_detected:
                await publish_progress("ABORTED — DISCORD QUARANTINE")
                return

            # Required safety delay between every DM attempt.
            await asyncio.sleep(1.5)
            attempted = sent_count + skipped_count
            if attempted % 25 == 0 or attempted == total_recipients:
                await publish_progress("Running")

        await publish_progress("Complete")
        print(
            f"[URG] Broadcast finished for {guild.name}: "
            f"{sent_count} sent, {skipped_count} skipped."
        )

    async def setup_hook(self):
        await federal_reserve.start_services(self)
        print("Warming up the Stat Engine... (This takes a few seconds)")
        await asyncio.to_thread(load_and_process_stats)
        stat_engine_loop.start()
        underground_jackpot.start()
        backup_database.start()  # <--- STARTS THE 2-HOUR BACKUPS
        end_of_day_sync.start()  # Tier 5: daily end-of-day reconciliation
        schedule_reveal_loop.start()  # Season scheduler: morning-of matchup drops (ET)
        roster_sweep_loop.start()  # 9AM ET: sweep official + community roster channels
        try:
            _now_et = _eastern_now()
            print(f"[Clock] League clock reads {_now_et.strftime('%A %m/%d %I:%M %p')} ET "
                  f"(zoneinfo={'OK' if _EASTERN_TZ_OK else 'FALLBACK'}) \u2014 "
                  f"reveals fire at 9 AM on this clock.")
        except Exception as _e:
            print(f"[Clock] check failed: {_e}")
        awards_watch_loop.start()  # Award polls: auto-close + results
        pots_watch_loop.start()  # Player of the Series: auto-close + results
        fantasy_lot_loop.start()  # Fantasy auction: lot hammer
        fantasy_contest_loop.start()  # Fantasy contests: daily/weekly scoring
        # Draft-server clock. The function is defined later in this file, but
        # all module definitions exist by the time discord.py calls setup_hook.
        try:
            draft_clock_loop.start()
        except RuntimeError:
            # Safe on a reconnect/reload where the loop is already running.
            pass
        try:
            for _pid, _p in _awards_state(load_state()).items():
                if _p.get('status') == 'open' and _p.get('message_id'):
                    bot.add_view(AwardVoteView(_pid, _p), message_id=int(_p['message_id']))
        except Exception as _e:
            print(f"[Awards] View re-register failed: {_e}")
        try:
            for _pid, _p in _pots_state(load_state()).items():
                if _p.get('status') == 'open' and _p.get('message_id'):
                    bot.add_view(PlayerOfSeriesView(_pid, _p), message_id=int(_p['message_id']))
        except Exception as _e:
            print(f"[POTS] View re-register failed: {_e}")
        try:
            _urg_campaigns = load_state().get("urg_registration_stats", {})
            for _campaign_id, _campaign in _urg_campaigns.items():
                _links = [
                    (
                        str(_link_data.get("label", "Registration")),
                        str(_url),
                    )
                    for _url, _link_data in _campaign.get("links", {}).items()
                    if str(_url).startswith(("https://", "http://"))
                ][:5]
                if _links:
                    self.add_view(
                        URGOptInView(self, str(_campaign_id), _links)
                    )
                    self.add_view(
                        URGRegistrationView(self, str(_campaign_id), _links)
                    )
        except Exception as _e:
            print(f"[URG] Registration view re-register failed: {_e}")
        await sync_knowledge_vault()

        # 🛡️ Global slash command guard: refuse all commands from non-whitelisted guilds
        async def _whitelist_check(interaction: discord.Interaction) -> bool:
            # Allow DMs only if they come from a user who shares an allowed guild (configurable)
            if interaction.guild is None:
                # Block all DM commands by default (safest)
                try:
                    await interaction.response.send_message(
                        "🚫 This bot only responds inside its home server.",
                        ephemeral=True
                    )
                except Exception:
                    pass
                return False

            if interaction.guild.id not in ALLOWED_GUILD_IDS:
                try:
                    await interaction.response.send_message(
                        "🚫 **Access Denied.** This bot is private to a specific server.\n"
                        "If you think this is a mistake, contact the bot owner.",
                        ephemeral=True
                    )
                except Exception:
                    pass
                print(f"[Security] BLOCKED command from unauthorized guild: {interaction.guild.name} ({interaction.guild.id}) — user: {interaction.user} ({interaction.user.id})")
                return False
            return True

        self.tree.interaction_check = _whitelist_check

        # Sync only to whitelisted guilds to avoid wiping the global Activity Entry Point
        for guild_id in ALLOWED_GUILD_IDS:
            guild = discord.Object(id=guild_id)
            self.tree.copy_global_to(guild=guild)
            await self.tree.sync(guild=guild)
            
        print(f"Synced slash commands to whitelisted guilds for {self.user}")



    async def on_ready(self):
        print(f"✅ Logged in as {self.user}!")

        # 🛡️ Audit guild list on startup — leave any server not on the whitelist
        if ALLOWED_GUILD_IDS:
            for guild in list(self.guilds):
                if guild.id not in ALLOWED_GUILD_IDS:
                    print(f"[Security] ⚠️ Bot is in unauthorized guild '{guild.name}' ({guild.id}) — leaving now.")
                    try:
                        await guild.leave()
                    except Exception as e:
                        print(f"[Security] Failed to leave {guild.name}: {e}")
        else:
            print("[Security] ⚠️ ALLOWED_GUILD_IDS is empty. Bot will refuse all commands and leave every server!")

        # --- NEW: REBOOT CONFIRMATION ---
        state = load_state()
        if 'pending_reboot_channel' in state:
            channel_id = state['pending_reboot_channel']
            channel = self.get_channel(channel_id)
            if channel:
                embed = discord.Embed(title="🟢 SYSTEM ONLINE", description="Reboot sequence complete. All systems nominal.", color=0x32D74B)
                await channel.send(embed=embed)

            # Throw the sticky note away so it doesn't send this every time you turn your PC on
            del state['pending_reboot_channel']
            save_state(state)

    # 🛡️ Auto-leave handler — fires the instant the bot is added to a new server
    async def on_guild_join(self, guild):
        if guild.id not in ALLOWED_GUILD_IDS:
            print(f"[Security] 🚨 Bot was added to UNAUTHORIZED guild: '{guild.name}' ({guild.id}) by inviter — leaving immediately.")
            # Try to find a channel to post a quick notice before leaving
            try:
                for ch in guild.text_channels:
                    if ch.permissions_for(guild.me).send_messages:
                        await ch.send("🚫 This bot is private and not available for general use. Goodbye.")
                        break
            except Exception:
                pass
            try:
                await guild.leave()
            except Exception as e:
                print(f"[Security] Could not leave {guild.name}: {e}")
        else:
            print(f"[Security] ✅ Joined whitelisted guild: {guild.name} ({guild.id})")


    # --- 📸 UPDATED AUTO-DOWNLOADER & WIRETAP FEATURE ---
    async def on_message(self, message):
        # Streamlit registrations arrive through one explicitly configured
        # Discord webhook. Import them before the normal bot-message guard.
        if await _qcl_reg_import_streamlit_webhook(message):
            return
        if message.author == self.user or message.author.bot:
            return

        # Capture registration uploads before the normal attachment downloader.
        # Only an explicit, private registration upload mode can trigger this.
        if await _qcl_reg_capture_attachments(message):
            return

        if (
            self.urg_lockdown_active
            and isinstance(message.channel, discord.TextChannel)
            and not getattr(
                getattr(message.author, "guild_permissions", None),
                "administrator",
                False,
            )
        ):
            try:
                await message.delete()
            except (discord.Forbidden, discord.HTTPException, discord.NotFound):
                pass
            try:
                await message.channel.send(
                    "🚨 Chat is locked! All URG activities and events are live on "
                    f"the broadcast right now. Tune in here: {self.urg_broadcast_link}",
                    delete_after=7,
                )
            except (discord.Forbidden, discord.HTTPException):
                pass
            return

        uid = str(message.author.id)
        current_time = time.time()
        
        # --- TALK YO SHIT WIRETAP ---
        # If they are in the main channel and tag someone else
        if message.channel.id == 1406064345502187530 and message.mentions:
            state = load_state()
            for target in message.mentions:
                if not target.bot and target.id != message.author.id:
                    state.setdefault('trash_talk', []).append({
                        "from_uid": uid,
                        "to_uid": str(target.id),
                        "message": message.clean_content,
                        "timestamp": time.time()
                    })
            save_state(state)

        # --- CHAT ACTIVITY BONUS & SCORE ---
        # 60-second cooldown per user
        if uid not in getattr(self, 'last_message_times', {}) or (current_time - self.last_message_times.get(uid, 0)) > 60:
            if len(message.content) > 10: 
                self.last_message_times[uid] = current_time
                state = load_state()
                if 'rpg' in state and uid in state['rpg']:
                    # Give them 1 Activity Point for the weekly check
                    state['rpg'][uid]['activity_score'] = state['rpg'][uid].get('activity_score', 0) + 1
                    _rpg_award(state, uid, rep=2, reason="Active in chat")
                    
                    # 90% chance for VC, 10% chance for rare CUPBUCKS
                    if random.random() > 0.10:
                        reward = random.randint(10, 35)
                        state['balances'][uid] = state.get('balances', {}).get(uid, 0) + reward
                    else:
                        reward = random.randint(5, 15)
                        state['rpg'][uid]['cupbucks'] = state['rpg'][uid].get('cupbucks', 0) + reward
                    save_state(state)

        # Check if the feature is ON, if it's the right channel, and if there are attachments
        if self.auto_download_enabled and message.channel.id in self.target_channels and message.attachments:
            save_folder = DOWNLOADS_PATH
            
            if not os.path.exists(save_folder):
                os.makedirs(save_folder)

            downloaded_count = 0
            for attachment in message.attachments:
                valid_extensions = ('.png', '.jpg', '.jpeg', '.gif', '.webp')
                if attachment.filename.lower().endswith(valid_extensions):
                    save_path = os.path.join(save_folder, attachment.filename)
                    try:
                        await attachment.save(save_path)
                        downloaded_count += 1
                        print(f"📸 Auto-saved image: {attachment.filename}")
                    except Exception as e:
                        print(f"❌ Failed to save {attachment.filename}: {e}")
            
            # Send the completion message if we actually grabbed anything
            if downloaded_count > 0:
                await message.reply(f"✅ Done grabbing all the files! ({downloaded_count} image(s) saved to the Downloads folder)")

        # CRITICAL: This ensures all your other commands keep working!
        await self.process_commands(message)

import FEDERAL_RESERVE_BOT as federal_reserve

