# ═══════════════════════════════════════════════════════════════════════════
#  HYBRID LEAGUE REGISTRATION
#
#  !QCLReg or /qclreg opens a private in-server thread wizard for:
#    • BYOT GM       — team, GM identity, logo, and every roster member
#    • Draft GM      — team, GM identity, logo, and social proof
#    • Draft Player  — position, availability, identity, and social proof
#
#  Proof is attachment-based rather than a fixed screenshot count.  Applicants
#  can send several screenshots in one message and several messages afterward.
#  Every file, target person, platform label, and Discord message URL is saved
#  in qcl_state.json for review, stats, and later roster tooling. The launcher
#  is ephemeral for slash-command users; uploads happen in a private thread
#  because Discord ephemeral messages cannot receive file attachments.
#
#  Admin review:
#    • !QCLRegDesk — folder-style review queue with clickable proof screenshots
#      before approve, request-info, or reject actions.
#  Player-facing directory:
#    • !QCLGMDesk — active teams and players with BYOT/Draft side labels and
#      uploaded team-logo links.
# ═══════════════════════════════════════════════════════════════════════════

QCL_REGISTRATION_SOCIALS = [
    item.strip()
    for item in os.getenv(
        "QCL_REGISTRATION_SOCIALS",
        "Instagram,TikTok,YouTube,X/Twitter",
    ).split(",")
    if item.strip()
]


def _qcl_reg_now():
    return int(time.time())


def _qcl_reg_new_id(uid):
    return f"QCL-{_qcl_reg_now()}-{str(uid)[-5:]}-{random.randint(100, 999)}"


def _qcl_reg_user_id(raw):
    """Extract a Discord ID from a mention or a numeric ID."""
    value = str(raw or "").strip()
    match = re.fullmatch(r"<@!?(\d+)>", value) or re.fullmatch(r"(\d{5,25})", value)
    return match.group(1) if match else ""


def _qcl_reg_label(person):
    return (
        person.get("display_name")
        or person.get("discord_tag")
        or person.get("discord_id")
        or person.get("gamertag")
        or "Unnamed player"
    )


def _qcl_reg_person(
    user_id,
    display_name,
    gamertag,
    platform,
    position="",
    availability="",
):
    return {
        "discord_id": str(user_id or ""),
        "discord_tag": str(display_name or ""),
        "display_name": str(display_name or ""),
        "gamertag_or_psn": str(gamertag or "").strip(),
        "platform": str(platform or "").strip(),
        "position": str(position or "").strip(),
        "availability": str(availability or "").strip(),
        "social_proof": [],
        "proof_platforms": [],
        "added_at": _qcl_reg_now(),
    }


def _qcl_reg_rebuild_people_index(state):
    index = {}
    for registration in state.get("qcl_registrations", {}).values():
        rid = registration.get("registration_id", "")
        for person in registration.get("people", []):
            uid = str(person.get("discord_id") or "")
            if not uid:
                continue
            index.setdefault(uid, []).append(
                {
                    "registration_id": rid,
                    "role": registration.get("role", ""),
                    "status": registration.get("status", ""),
                    "team_name": registration.get("team_name", ""),
                    "display_name": _qcl_reg_label(person),
                    "gamertag_or_psn": person.get("gamertag_or_psn", ""),
                    "position": person.get("position", ""),
                }
            )
    state["qcl_registration_people"] = index


def _qcl_reg_sync_session(state, session):
    registration = state.setdefault("qcl_registrations", {}).setdefault(
        session["registration_id"],
        {
            "registration_id": session["registration_id"],
            "created_at": session["created_at"],
            "history": [],
        },
    )
    registration.update(
        {
            "registration_id": session["registration_id"],
            "role": session["role"],
            "status": session.get("status", "draft"),
            "owner_id": session["owner_id"],
            "owner_tag": session.get("owner_tag", ""),
            "source_guild_id": session.get("source_guild_id"),
            "team_name": session.get("team_name", ""),
            "team_logo": session.get("team_logo"),
            "socials_required": list(session.get("socials_required", [])),
            "people": list(session.get("people", {}).values()),
            "updated_at": _qcl_reg_now(),
        }
    )
    _qcl_reg_rebuild_people_index(state)


def _qcl_reg_missing(session):
    missing = []
    role = session.get("role")
    people = list(session.get("people", {}).values())

    if role in {"byot_gm", "draft_gm"} and not session.get("team_name"):
        missing.append("team name")
    if role in {"byot_gm", "draft_gm"} and not session.get("team_logo"):
        missing.append("team logo upload")
    if role == "byot_gm" and len(people) < 2:
        missing.append("at least one BYOT roster player besides the GM")
    if role == "draft_player":
        owner = session.get("people", {}).get(str(session.get("owner_id")), {})
        if not owner.get("position"):
            missing.append("position")
        if not owner.get("availability"):
            missing.append("availability")

    for person in people:
        if not person.get("social_proof"):
            missing.append(f"social proof for {_qcl_reg_label(person)}")
    return missing


def _qcl_reg_attachment(attachment, message, target_id="", target_name=""):
    guild_id = getattr(getattr(message, "guild", None), "id", None)
    message_url = (
        f"https://discord.com/channels/{guild_id}/{message.channel.id}/{message.id}"
        if guild_id
        else f"https://discord.com/channels/@me/{message.channel.id}/{message.id}"
    )
    return {
        "attachment_id": str(getattr(attachment, "id", "")),
        "filename": str(getattr(attachment, "filename", "")),
        "url": str(getattr(attachment, "url", "")),
        "content_type": str(getattr(attachment, "content_type", "") or ""),
        "size": int(getattr(attachment, "size", 0) or 0),
        "message_id": str(getattr(message, "id", "")),
        "message_url": message_url,
        "target_id": str(target_id or ""),
        "target_name": str(target_name or ""),
        "note": str(getattr(message, "content", "") or "")[:500],
        "uploaded_at": _qcl_reg_now(),
    }


async def _qcl_reg_import_streamlit_webhook(message):
    """Import a signed-in Streamlit form from the private intake webhook."""
    expected = str(os.getenv("QCL_STREAMLIT_WEBHOOK_ID") or "").strip()
    webhook_id = str(getattr(message, "webhook_id", "") or "")
    if not expected or webhook_id != expected:
        return False
    content = str(getattr(message, "content", "") or "")
    if not content.startswith("QCL_STREAMLIT_REGISTRATION\n```json\n"):
        return False
    try:
        raw = content.split("```json\n", 1)[1].rsplit("\n```", 1)[0]
        payload = json.loads(raw)
    except (IndexError, ValueError, TypeError) as exc:
        print(f"[QCLReg] Rejected malformed Streamlit intake: {exc}")
        return True
    role = str(payload.get("role") or "")
    owner_id = str(payload.get("owner_id") or "")
    if (
        payload.get("version") != 1
        or role not in {"draft_player", "byot_gm"}
        or not owner_id.isdigit()
    ):
        print("[QCLReg] Rejected Streamlit intake with invalid role or owner.")
        return True

    attachments = list(getattr(message, "attachments", []) or [])
    owner_name = str(payload.get("owner_name") or owner_id)[:100]
    owner = _qcl_reg_person(
        owner_id,
        owner_name,
        str(payload.get("gamertag") or "")[:80],
        str(payload.get("platform") or "")[:30],
        str(payload.get("position") or "")[:30],
        str(payload.get("availability") or "")[:500],
    )
    owner["proof_platforms"] = [
        str(item)[:40] for item in payload.get("socials", [])
        if isinstance(item, str)
    ]
    for attachment in attachments:
        if str(getattr(attachment, "filename", "")).startswith("owner-proof-"):
            owner["social_proof"].append(
                _qcl_reg_attachment(attachment, message, owner_id, owner_name)
            )

    people = {owner_id: owner}
    for index, item in enumerate(payload.get("roster", []) or [], 1):
        if not isinstance(item, dict):
            continue
        player_id = str(item.get("discord_id") or "")
        if not player_id.isdigit() or player_id in people:
            continue
        member = message.guild.get_member(int(player_id)) if message.guild else None
        display_name = getattr(member, "display_name", None) or player_id
        person = _qcl_reg_person(
            player_id,
            display_name,
            str(item.get("gamertag") or "")[:80],
            str(item.get("platform") or "")[:30],
            str(item.get("position") or "")[:30],
        )
        proof_prefix = f"player{index}-proof-"
        for attachment in attachments:
            if str(getattr(attachment, "filename", "")).startswith(proof_prefix):
                person["social_proof"].append(
                    _qcl_reg_attachment(
                        attachment, message, player_id, display_name
                    )
                )
        people[player_id] = person

    team_logo = None
    for attachment in attachments:
        if str(getattr(attachment, "filename", "")).startswith("team-logo-"):
            team_logo = _qcl_reg_attachment(
                attachment, message, owner_id, owner_name
            )
            break
    now = _qcl_reg_now()
    registration_id = _qcl_reg_new_id(owner_id)
    session = {
        "registration_id": registration_id,
        "role": role,
        "owner_id": owner_id,
        "owner_tag": owner_name,
        "source_guild_id": getattr(getattr(message, "guild", None), "id", None),
        "source_channel_id": getattr(getattr(message, "channel", None), "id", None),
        "thread_id": None,
        "created_at": now,
        "updated_at": now,
        "status": "review",
        "team_name": str(payload.get("team_name") or "")[:80],
        "team_logo": team_logo,
        "socials_required": list(QCL_REGISTRATION_SOCIALS),
        "people": people,
        "upload_mode": None,
        "upload_target_id": "",
        "upload_platforms": "",
    }
    missing = _qcl_reg_missing(session)
    if missing:
        session["status"] = "needs_info"
    state = load_state()
    _qcl_reg_sync_session(state, session)
    record = state["qcl_registrations"][registration_id]
    record.setdefault("history", []).append({
        "at": now,
        "action": "submitted_from_streamlit",
        "by": owner_id,
        "missing": missing,
        "message_id": str(getattr(message, "id", "")),
    })
    save_state(state)
    try:
        status_text = (
            "needs information: " + ", ".join(missing)
            if missing else "is ready for review"
        )
        await message.reply(
            f"✅ Imported `{registration_id}` from Streamlit; {status_text}.",
            mention_author=False,
        )
    except (discord.Forbidden, discord.HTTPException):
        pass
    return True


def _qcl_reg_summary(session, status=None):
    people = list(session.get("people", {}).values())
    proof_count = sum(len(person.get("social_proof", [])) for person in people)
    missing = _qcl_reg_missing(session)
    role_label = {
        "byot_gm": "BYOT GM",
        "draft_gm": "Draft GM",
        "draft_player": "Draft Player",
    }.get(session.get("role"), session.get("role", "Unknown"))
    state_label = status or session.get("status", "draft")
    lines = [
        f"**{role_label} registration** · `{session['registration_id']}`",
        f"**Status:** `{state_label}`",
    ]
    if session.get("team_name"):
        lines.append(f"**Team:** {session['team_name']}")
    lines.append(f"**People tracked:** {len(people)} · **Proof files:** {proof_count}")
    if missing:
        lines.append("**Still needed:** " + ", ".join(missing[:8]))
    else:
        lines.append("**Checklist:** complete and ready for admin review.")
    return "\n".join(lines)


def _qcl_reg_session_for(state, registration_id):
    for session in state.get("qcl_registration_sessions", {}).values():
        if session.get("registration_id") == registration_id:
            return session
    return None


async def _qcl_reg_capture_attachments(message):
    """Record files sent in the applicant's private registration thread."""
    if not message.attachments or getattr(message, "guild", None) is None:
        return False

    state = load_state()
    uid = str(message.author.id)
    session = state.get("qcl_registration_sessions", {}).get(uid)
    if not session or session.get("thread_id") != message.channel.id:
        return False

    mode = session.get("upload_mode")
    if mode == "logo":
        session["team_logo"] = _qcl_reg_attachment(message.attachments[0], message)
        session["upload_mode"] = None
        session["updated_at"] = _qcl_reg_now()
        _qcl_reg_sync_session(state, session)
        save_state(state)
        extra = len(message.attachments) - 1
        suffix = f" Ignored {extra} extra file(s); send one logo at a time." if extra else ""
        await message.channel.send(
            f"Logo recorded: **{message.attachments[0].filename}**.{suffix}\n"
            "Use the buttons above to continue."
        )
        return True

    if mode == "social_proof":
        target_id = str(session.get("upload_target_id") or session.get("owner_id"))
        person = session.get("people", {}).get(target_id)
        if not person:
            session["upload_mode"] = None
            save_state(state)
            await message.channel.send(
                "I could not find that proof target. Use **Upload social proof** again."
            )
            return True

        target_name = _qcl_reg_label(person)
        person.setdefault("social_proof", []).extend(
            _qcl_reg_attachment(
                attachment,
                message,
                target_id=target_id,
                target_name=target_name,
            )
            for attachment in message.attachments
        )
        labels = [
            item.strip()
            for item in str(session.get("upload_platforms", "")).split(",")
            if item.strip()
        ]
        person["proof_platforms"] = sorted(
            set(person.get("proof_platforms", []) + labels)
        )
        session["upload_mode"] = None
        session["upload_target_id"] = ""
        session["upload_platforms"] = ""
        session["updated_at"] = _qcl_reg_now()
        _qcl_reg_sync_session(state, session)
        save_state(state)
        await message.channel.send(
            f"Recorded **{len(message.attachments)}** proof file(s) for **{target_name}**. "
            "The running count is saved. Use **Upload social proof** again for another person."
        )
        return True

    return False


async def _qcl_reg_open_private_thread(channel, user, topic="registration"):
    """Return an existing private thread or create one for this registration."""
    if isinstance(channel, discord.Thread):
        if channel.type != discord.ChannelType.private_thread:
            return None
        try:
            await channel.add_user(user)
        except (discord.Forbidden, discord.HTTPException):
            pass
        return channel

    if not isinstance(channel, discord.TextChannel):
        return None

    clean_topic = re.sub(r"[^a-zA-Z0-9 _-]+", "", str(topic or "registration"))
    clean_topic = re.sub(r"\s+", " ", clean_topic).strip()[:45] or "registration"
    thread = await channel.create_thread(
        name=f"QCL {clean_topic}",
        type=discord.ChannelType.private_thread,
        invitable=False,
        auto_archive_duration=1440,
        reason="QCL private registration wizard",
    )
    await thread.add_user(user)
    return thread


