class QCLRegistrationStartModal(discord.ui.Modal):
    def __init__(self, role, owner_id):
        self.role = role
        self.owner_id = int(owner_id)
        title = {
            "byot_gm": "BYOT GM registration",
            "draft_gm": "Draft GM registration",
            "draft_player": "Draft player registration",
        }[role]
        super().__init__(title=title)

        self.team_name = discord.ui.TextInput(
            label="Team name",
            placeholder="Required for BYOT GM and Draft GM",
            required=role != "draft_player",
            max_length=80,
        )
        self.gamertag = discord.ui.TextInput(
            label="Gamertag or PSN",
            placeholder="Your in-game name",
            required=True,
            max_length=80,
        )
        self.platform = discord.ui.TextInput(
            label="Platform",
            placeholder="PSN, Xbox, PC, etc.",
            required=True,
            max_length=30,
        )
        self.position = discord.ui.TextInput(
            label="Position",
            placeholder="Required for Draft Player (PG, SG, SF, PF, C...)",
            required=role == "draft_player",
            max_length=30,
        )
        self.availability = discord.ui.TextInput(
            label="Availability",
            placeholder="Required for Draft Player (days/times/time zone)",
            required=role == "draft_player",
            style=discord.TextStyle.paragraph,
            max_length=500,
        )
        for field in (
            self.team_name,
            self.gamertag,
            self.platform,
            self.position,
            self.availability,
        ):
            self.add_item(field)

    async def on_submit(self, interaction):
        await interaction.response.defer(ephemeral=True)
        state = load_state()
        uid = str(interaction.user.id)
        registration_id = _qcl_reg_new_id(uid)
        owner_name = getattr(interaction.user, "display_name", None) or str(
            interaction.user
        )
        person = _qcl_reg_person(
            uid,
            owner_name,
            self.gamertag.value,
            self.platform.value,
            self.position.value,
            self.availability.value,
        )
        try:
            thread = await _qcl_reg_open_private_thread(
                interaction.channel,
                interaction.user,
                topic=f"{owner_name} registration",
            )
        except (discord.Forbidden, discord.HTTPException) as exc:
            print(f"[QCLReg] Could not create private thread: {exc}")
            return await interaction.followup.send(
                "I could not create the private registration thread. "
                "Ask an admin to allow the bot to create and manage private threads.",
                ephemeral=True,
            )
        if thread is None:
            return await interaction.followup.send(
                "Start QCL registration from a normal server text channel, not a public thread.",
                ephemeral=True,
            )
        session = {
            "registration_id": registration_id,
            "role": self.role,
            "owner_id": uid,
            "owner_tag": str(interaction.user),
            "source_guild_id": interaction.guild.id if interaction.guild else None,
            "source_channel_id": interaction.channel.id if interaction.channel else None,
            "thread_id": thread.id,
            "created_at": _qcl_reg_now(),
            "updated_at": _qcl_reg_now(),
            "status": "draft",
            "team_name": self.team_name.value.strip(),
            "team_logo": None,
            "socials_required": list(QCL_REGISTRATION_SOCIALS),
            "people": {uid: person},
            "upload_mode": None,
            "upload_target_id": "",
            "upload_platforms": "",
        }
        state.setdefault("qcl_registration_sessions", {})[uid] = session
        _qcl_reg_sync_session(state, session)
        save_state(state)
        thread_message = (
            _qcl_reg_summary(session)
            + "\n\n"
            + (
                "For a BYOT team, paste the Discord roster message with "
                "**Import BYOT roster**. The bot will create one verification "
                "entry per mentioned member. You can still use **Add BYOT player** "
                "for one-off additions. "
                if self.role == "byot_gm"
                else ""
            )
            + "Use **Upload social proof** to choose who the files belong to, "
            "then send one or more screenshots in this private thread. "
            + (
                "Use **Upload team logo** to send the logo as an attachment. "
                if self.role in {"byot_gm", "draft_gm"}
                else ""
            )
            + "When ready, press **Submit / update registration**.",
        )
        await thread.send(
            thread_message,
            view=QCLRegistrationWorkflowView(uid, registration_id),
        )
        await interaction.followup.send(
            f"Your private QCL registration thread is ready: {thread.mention}\n"
            "Complete the remaining steps there. Only you and server moderators can access it.",
            ephemeral=True,
        )


