def _qcl_reg_roster_tokens(raw):
    """Return unique Discord mention IDs and readable fallback names.

    BYOT GMs usually paste the same mention list they post in Discord.  Discord
    sends real mentions as <@123>, so those can be resolved safely to guild
    members.  Plain @names are retained as unresolved entries and reported
    back instead of being silently added as the wrong person.
    """
    tokens = []
    for line in str(raw or "").splitlines():
        line = re.sub(r"^\s*[-•*]\s*", "", line).strip()
        if not line:
            continue
        mentions = re.findall(r"<@!?(\d+)>", line)
        if mentions:
            tokens.extend(("id", item) for item in mentions)
            continue
        for item in re.findall(r"@[^\s,]+", line):
            tokens.append(("name", item.lstrip("@").strip()))
    return list(dict.fromkeys(tokens))


class QCLRegistrationRosterImportModal(discord.ui.Modal):
    """Turn a pasted Discord roster message into people on a BYOT record."""

    def __init__(self, owner_id, registration_id):
        self.owner_id = str(owner_id)
        self.registration_id = registration_id
        super().__init__(title="Import BYOT roster")
        self.roster = discord.ui.TextInput(
            label="Paste the Discord roster mentions",
            placeholder="@PlayerOne\n@PlayerTwo\n@PlayerThree",
            style=discord.TextStyle.paragraph,
            required=True,
            max_length=4000,
        )
        self.add_item(self.roster)

    async def on_submit(self, interaction):
        state = load_state()
        session = _qcl_reg_session_for(state, self.registration_id)
        if (
            not session
            or str(interaction.user.id) != self.owner_id
            or session.get("role") != "byot_gm"
        ):
            return await interaction.response.send_message(
                "That BYOT registration is no longer active.",
                ephemeral=True,
            )

        tokens = _qcl_reg_roster_tokens(self.roster.value)
        if not tokens:
            return await interaction.response.send_message(
                "Paste one or more Discord mentions, one per line.",
                ephemeral=True,
            )

        guild = interaction.guild
        added = []
        unresolved = []
        for token_type, token in tokens:
            member = None
            if token_type == "id":
                member = guild.get_member(int(token)) if guild else None
                if not member and guild:
                    try:
                        member = await guild.fetch_member(int(token))
                    except (
                        discord.NotFound,
                        discord.Forbidden,
                        discord.HTTPException,
                    ):
                        member = None
            elif guild:
                needle = token.casefold()
                member = discord.utils.find(
                    lambda candidate: (
                        str(getattr(candidate, "name", "")).casefold() == needle
                        or str(getattr(candidate, "display_name", "")).casefold() == needle
                    ),
                    getattr(guild, "members", []),
                )

            if not member:
                unresolved.append(token)
                continue

            member_id = str(member.id)
            if member_id in session.setdefault("people", {}):
                continue
            display_name = getattr(member, "display_name", None) or str(member)
            session["people"][member_id] = _qcl_reg_person(
                member_id,
                display_name,
                "",
                "",
            )
            added.append(display_name)

        if not added and unresolved:
            return await interaction.response.send_message(
                "I could not match those names to members in this server. "
                "Paste actual Discord mentions by selecting the users in Discord, "
                "then try again.",
                ephemeral=True,
            )

        session["updated_at"] = _qcl_reg_now()
        _qcl_reg_sync_session(state, session)
        save_state(state)
        message = (
            f"**BYOT roster updated:** added {len(added)} new player(s). "
            f"The registration now has {len(session.get('people', {}))} people."
        )
        if unresolved:
            message += (
                "\nCould not match: "
                + ", ".join(f"`@{item}`" for item in unresolved[:12])
                + ". Paste those as real Discord mentions."
            )
        await interaction.response.send_message(message, ephemeral=True)


class QCLRegistrationProofModal(discord.ui.Modal):
    def __init__(self, owner_id, registration_id):
        self.owner_id = str(owner_id)
        self.registration_id = registration_id
        super().__init__(title="Set social-proof upload target")
        self.target = discord.ui.TextInput(
            label="Who is this proof for?",
            placeholder="Use `me` or a roster member's Discord mention/ID",
            default="me",
            required=True,
            max_length=80,
        )
        self.platforms = discord.ui.TextInput(
            label="Platforms shown in these screenshots",
            placeholder="Instagram, TikTok, YouTube, X/Twitter",
            style=discord.TextStyle.paragraph,
            required=False,
            max_length=300,
        )
        self.add_item(self.target)
        self.add_item(self.platforms)

    async def on_submit(self, interaction):
        state = load_state()
        session = _qcl_reg_session_for(state, self.registration_id)
        if not session or str(interaction.user.id) != self.owner_id:
            return await interaction.response.send_message(
                "That registration is no longer active.", ephemeral=True
            )
        raw_target = self.target.value.strip().lower()
        target_id = str(session["owner_id"]) if raw_target in {"me", "self", "myself"} else _qcl_reg_user_id(raw_target)
        if target_id not in session.get("people", {}):
            return await interaction.response.send_message(
                "That person is not on this registration. Add them first, or use `me`.",
                ephemeral=True,
            )
        session["upload_mode"] = "social_proof"
        session["upload_target_id"] = target_id
        session["upload_platforms"] = self.platforms.value.strip()
        state["qcl_registration_sessions"][self.owner_id] = session
        save_state(state)
        person = session["people"][target_id]
        await interaction.response.send_message(
            f"Now send the proof screenshots in this private thread for **{_qcl_reg_label(person)}**. "
            "You can attach multiple files in one message or send several messages. "
            "The bot will count every file."
        )


