def _qcl_reg_find(state, registration_id):
    return state.get("qcl_registrations", {}).get(str(registration_id).strip())


def _qcl_reg_people_list(record):
    people = record.get("people", [])
    if isinstance(people, dict):
        return list(people.values())
    return list(people or [])


def _qcl_reg_role_label(role):
    return {
        "byot_gm": "BYOT GM",
        "draft_gm": "Draft GM",
        "draft_player": "Draft Player",
    }.get(str(role or ""), str(role or "Unknown"))


def _qcl_reg_subject(record):
    people = _qcl_reg_people_list(record)
    return (
        record.get("team_name")
        or (_qcl_reg_label(people[0]) if people else "Unnamed registration")
    )


def _qcl_reg_proof_count(record):
    return sum(len(person.get("social_proof", []) or []) for person in _qcl_reg_people_list(record))


def _qcl_reg_missing_record(record):
    """Run the existing checklist against a stored registration list."""
    normalized = dict(record)
    normalized["people"] = {
        str(person.get("discord_id") or index): person
        for index, person in enumerate(_qcl_reg_people_list(record))
    }
    return _qcl_reg_missing(normalized)


def _qcl_reg_proof_field_values(record):
    """Build clickable proof-file fields for an admin review embed."""
    fields = []
    for person in _qcl_reg_people_list(record):
        proof_files = person.get("social_proof", []) or []
        if not proof_files:
            continue
        lines = []
        platforms = ", ".join(person.get("proof_platforms", []) or [])
        if platforms:
            lines.append(f"Platforms labeled: **{platforms}**")
        for proof in proof_files[:12]:
            filename = str(proof.get("filename") or "proof screenshot")[:90]
            url = str(proof.get("url") or proof.get("message_url") or "").strip()
            if url:
                lines.append(f"• [{filename}]({url})")
            else:
                lines.append(f"• `{filename}` (file URL unavailable)")
        if len(proof_files) > 12:
            lines.append(f"…and {len(proof_files) - 12} more file(s).")
        fields.append(
            (
                f"Proof · {_qcl_reg_label(person)}",
                "\n".join(lines)[:1024],
            )
        )
    return fields


def _qcl_reg_folder_records(state, folder="all"):
    records = list(state.get("qcl_registrations", {}).values())
    folder = str(folder or "all").lower()
    if folder == "byot":
        records = [item for item in records if item.get("role") == "byot_gm"]
    elif folder == "draft":
        records = [
            item
            for item in records
            if item.get("role") in {"draft_gm", "draft_player"}
        ]
    elif folder == "review":
        records = [
            item
            for item in records
            if item.get("status") in {"submitted", "needs_review"}
        ]
    elif folder == "needs_info":
        records = [
            item
            for item in records
            if item.get("status") in {"needs_info", "incomplete"}
        ]
    elif folder == "approved":
        records = [item for item in records if item.get("status") == "approved"]
    return sorted(records, key=lambda item: item.get("updated_at", 0), reverse=True)


def _qcl_reg_desk_embed(state, folder="all"):
    records = _qcl_reg_folder_records(state, folder)
    all_records = list(state.get("qcl_registrations", {}).values())
    byot_count = sum(item.get("role") == "byot_gm" for item in all_records)
    draft_count = sum(
        item.get("role") in {"draft_gm", "draft_player"} for item in all_records
    )
    review_count = sum(
        item.get("status") in {"submitted", "needs_review"} for item in all_records
    )
    approved_count = sum(item.get("status") == "approved" for item in all_records)
    needs_info_count = sum(
        item.get("status") in {"needs_info", "incomplete"} for item in all_records
    )
    folder_label = {
        "all": "All registrations",
        "byot": "BYOT teams",
        "draft": "Draft pool",
        "review": "Needs review",
        "needs_info": "Needs info",
        "approved": "Approved",
    }.get(folder, "All registrations")
    lines = [
        f"**{folder_label}** · {len(records)} record(s)",
        "Choose a folder, then choose a registration to open its roster and proof checklist.",
        "",
    ]
    if records:
        for item in records[:12]:
            people = _qcl_reg_people_list(item)
            lines.append(
                f"• **{_qcl_reg_subject(item)}** · "
                f"`{_qcl_reg_role_label(item.get('role'))}` · "
                f"`{item.get('status', 'draft')}` · "
                f"{len(people)} people / {_qcl_reg_proof_count(item)} proof files"
            )
        if len(records) > 12:
            lines.append(f"\n…and {len(records) - 12} more in the dropdown.")
    else:
        lines.append("No registrations are in this folder yet.")

    embed = discord.Embed(
        title="QCL Master Desk",
        description="\n".join(lines),
        color=0x9678FF,
    )
    embed.add_field(
        name="Folders",
        value=(
            f"📁 **All** `{len(all_records)}`   ·   "
            f"🟦 **BYOT** `{byot_count}`   ·   "
            f"🟩 **Draft** `{draft_count}`"
        ),
        inline=False,
    )
    embed.add_field(
        name="Queue",
        value=(
            f"🟡 **Review** `{review_count}`   ·   "
            f"✅ **Approved** `{approved_count}`   ·   "
            f"🟠 **Needs info** `{needs_info_count}`"
        ),
        inline=False,
    )
    embed.set_footer(text="QCL registration desk · use !QCLRegView <ID> for a direct lookup")
    return embed


def _qcl_reg_detail_embed(record):
    status = str(record.get("status", "draft"))
    color = {
        "approved": 0x65D9A0,
        "rejected": 0xFF7B8B,
        "needs_info": 0xF5A36A,
        "needs_review": 0xF5C96A,
        "submitted": 0xF5C96A,
    }.get(status, 0x9678FF)
    people = _qcl_reg_people_list(record)
    proof_count = _qcl_reg_proof_count(record)
    missing = _qcl_reg_missing_record(record)
    roster_lines = []
    for person in people[:18]:
        platforms = ", ".join(person.get("proof_platforms", []) or [])
        proof = len(person.get("social_proof", []) or [])
        marker = "✅" if proof else "⏳"
        roster_lines.append(
            f"{marker} **{_qcl_reg_label(person)}** · "
            f"`{person.get('gamertag_or_psn') or 'gamertag pending'}` · "
            f"{person.get('position') or 'position pending'} · "
            f"`{proof} proof`"
            + (f" · {platforms}" if platforms else "")
        )
    if len(people) > 18:
        roster_lines.append(f"…and {len(people) - 18} more people.")
    if not roster_lines:
        roster_lines.append("No people have been added yet.")

    embed = discord.Embed(
        title=_qcl_reg_subject(record),
        description=(
            f"`{record.get('registration_id')}`\n"
            f"**{_qcl_reg_role_label(record.get('role'))}** · "
            f"**{status.replace('_', ' ').title()}**"
        ),
        color=color,
    )
    embed.add_field(
        name="Registration",
        value=(
            f"Owner: **{record.get('owner_tag') or 'unknown'}**\n"
            f"People: **{len(people)}**\n"
            f"Proof files: **{proof_count}**\n"
            f"Logo: **{'uploaded' if record.get('team_logo') else 'not uploaded'}**"
        ),
        inline=True,
    )
    embed.add_field(
        name="Verification",
        value=(
            f"Social checklist: {', '.join(record.get('socials_required', []) or ['not configured'])}\n"
            + (
                "Missing: " + ", ".join(missing[:6])
                if missing
                else "Checklist complete."
            )
        ),
        inline=True,
    )
    embed.add_field(
        name=f"Roster folders · {len(people)}",
        value="\n".join(roster_lines)[:1024],
        inline=False,
    )
    proof_fields = _qcl_reg_proof_field_values(record)
    if proof_fields:
        embed.add_field(
            name=f"Proof screenshots · {proof_count}",
            value=(
                "Click each filename to open the submitted screenshot. "
                "These links are visible in the admin review card."
            ),
            inline=False,
        )
        for field_name, field_value in proof_fields[:18]:
            embed.add_field(name=field_name, value=field_value, inline=True)
    else:
        embed.add_field(
            name="Proof screenshots",
            value="No proof screenshots have been uploaded yet.",
            inline=False,
        )
    thread_id = record.get("thread_id")
    guild_id = record.get("source_guild_id")
    if thread_id and guild_id:
        embed.add_field(
            name="Private registration thread",
            value=f"https://discord.com/channels/{guild_id}/{thread_id}",
            inline=False,
        )
    embed.set_footer(text="Approve only after every roster folder has the proof you require.")
    return embed


def _qcl_reg_logo_url(record):
    logo = record.get("team_logo") or {}
    if not isinstance(logo, dict):
        return ""
    return str(logo.get("url") or "").strip()


def _qcl_gm_records(state):
    """Return active registrations safe to show on the player-facing GM desk."""
    hidden_statuses = {"cancelled", "rejected"}
    return [
        record
        for record in state.get("qcl_registrations", {}).values()
        if record.get("status", "draft") not in hidden_statuses
    ]


def _qcl_gm_side(record):
    return "BYOT" if record.get("role") == "byot_gm" else "Draft"


def _qcl_gmdesk_team_records(state):
    return sorted(
        [
            record
            for record in _qcl_gm_records(state)
            if record.get("role") in {"byot_gm", "draft_gm"}
            and record.get("team_name")
        ],
        key=lambda record: str(record.get("team_name", "")).casefold(),
    )


def _qcl_gmdesk_player_rows(state):
    rows = []
    for record in _qcl_gm_records(state):
        side = _qcl_gm_side(record)
        team_name = record.get("team_name") or "Draft pool"
        logo_url = _qcl_reg_logo_url(record)
        for person in _qcl_reg_people_list(record):
            rows.append(
                {
                    "name": _qcl_reg_label(person),
                    "side": side,
                    "team": team_name,
                    "logo_url": logo_url,
                    "role": _qcl_reg_role_label(record.get("role")),
                    "status": record.get("status", "draft"),
                    "position": person.get("position") or "",
                }
            )
    return sorted(rows, key=lambda row: (row["side"], row["name"].casefold()))


def _qcl_gmdesk_overview_embed(state, mode="teams"):
    teams = _qcl_gmdesk_team_records(state)
    players = _qcl_gmdesk_player_rows(state)
    if mode == "players":
        lines = [
            f"**All registered players** · {len(players)} player(s)",
            "Active registrations only. Rejected and cancelled records are hidden.",
            "",
        ]
        for row in players[:65]:
            logo = f"[🖼️]({row['logo_url']})" if row["logo_url"] else "▫️"
            position = f" · {row['position']}" if row["position"] else ""
            lines.append(
                f"{logo} **{row['name']}** · `{row['side']}` · "
                f"{row['team']}{position} · `{row['status']}`"
            )
        if len(players) > 65:
            lines.append(f"\n…and {len(players) - 65} more players.")
        title = "QCL GM Desk · Player directory"
        footer = "Select a team above to see its logo and roster."
    else:
        lines = [
            f"**All registered teams** · {len(teams)} team(s)",
            "Select a team below for its logo, GM, and current registered roster.",
            "",
        ]
        if teams:
            for record in teams:
                logo = (
                    f"[🖼️]({_qcl_reg_logo_url(record)})"
                    if _qcl_reg_logo_url(record)
                    else "▫️"
                )
                people = _qcl_reg_people_list(record)
                lines.append(
                    f"{logo} **{record.get('team_name')}** · "
                    f"`{_qcl_gm_side(record)}` · "
                    f"{len(people)} player(s) · `{record.get('status', 'draft')}`"
                )
        else:
            lines.append("No team registrations have been submitted yet.")
        title = "QCL GM Desk · Team directory"
        footer = "Logos open from the 🖼️ link; use the dropdown for a full team card."
    embed = discord.Embed(
        title=title,
        description="\n".join(lines)[:4096],
        color=0x60D9EA if mode == "teams" else 0x65D9A0,
    )
    embed.add_field(
        name="Directory totals",
        value=(
            f"Teams: **{len(teams)}**\n"
            f"Players: **{len(players)}**\n"
            f"BYOT players: **{sum(row['side'] == 'BYOT' for row in players)}**\n"
            f"Draft players: **{sum(row['side'] == 'Draft' for row in players)}**"
        ),
        inline=True,
    )
    embed.add_field(
        name="What players can see",
        value=(
            "Team name, side, player name, position when supplied, status, "
            "and the team logo link when one was uploaded."
        ),
        inline=True,
    )
    embed.set_footer(text=footer)
    return embed


def _qcl_gmdesk_team_embed(record):
    people = _qcl_reg_people_list(record)
    logo_url = _qcl_reg_logo_url(record)
    roster_lines = []
    for person in people[:24]:
        position = f" · {person['position']}" if person.get("position") else ""
        roster_lines.append(
            f"**{_qcl_reg_label(person)}**{position} · "
            f"`{_qcl_gm_side(record)}`"
        )
    if len(people) > 24:
        roster_lines.append(f"…and {len(people) - 24} more player(s).")
    embed = discord.Embed(
        title=str(record.get("team_name") or "Unnamed team"),
        description=(
            f"**{_qcl_gm_side(record)} side** · "
            f"**{record.get('status', 'draft').replace('_', ' ').title()}**\n"
            f"GM: **{record.get('owner_tag') or 'unknown'}**"
        ),
        color=0x60D9EA if _qcl_gm_side(record) == "BYOT" else 0x65D9A0,
    )
    if logo_url:
        embed.set_thumbnail(url=logo_url)
    embed.add_field(
        name=f"Registered roster · {len(people)}",
        value="\n".join(roster_lines)[:1024] or "No players registered yet.",
        inline=False,
    )
    embed.add_field(
        name="Registration",
        value=(
            f"ID: `{record.get('registration_id')}`\n"
            f"Proof files recorded: **{_qcl_reg_proof_count(record)}**\n"
            f"Logo: **{'uploaded' if logo_url else 'not uploaded'}**"
        ),
        inline=True,
    )
    embed.set_footer(text="QCL GM Desk · public roster view")
    return embed


class QCLGMDeskSelect(discord.ui.Select):
    def __init__(self, mode="teams"):
        state = load_state()
        teams = _qcl_gmdesk_team_records(state)
        options = [
            discord.SelectOption(
                label="All registered teams",
                value="teams",
                emoji="🏀",
                default=mode == "teams",
            ),
            discord.SelectOption(
                label="All registered players",
                value="players",
                emoji="👥",
                default=mode == "players",
            ),
        ]
        for record in teams[:23]:
            options.append(
                discord.SelectOption(
                    label=str(record.get("team_name") or "Unnamed team")[:100],
                    value=f"team:{record.get('registration_id')}"[:100],
                    description=(
                        f"{_qcl_gm_side(record)} · "
                        f"{len(_qcl_reg_people_list(record))} player(s)"
                    )[:100],
                )
            )
        super().__init__(
            placeholder="Browse teams and players…",
            min_values=1,
            max_values=1,
            options=options,
            row=0,
        )

    async def callback(self, interaction):
        state = load_state()
        value = self.values[0]
        if value == "teams":
            await interaction.response.edit_message(
                embed=_qcl_gmdesk_overview_embed(state, "teams"),
                view=QCLGMDeskView("teams"),
            )
        elif value == "players":
            await interaction.response.edit_message(
                embed=_qcl_gmdesk_overview_embed(state, "players"),
                view=QCLGMDeskView("players"),
            )
        else:
            record = _qcl_reg_find(state, value.removeprefix("team:"))
            if not record:
                return await interaction.response.send_message(
                    "That team registration is no longer available.",
                    ephemeral=True,
                )
            await interaction.response.edit_message(
                embed=_qcl_gmdesk_team_embed(record),
                view=QCLGMDeskView(value),
            )


class QCLGMDeskView(discord.ui.View):
    def __init__(self, mode="teams"):
        super().__init__(timeout=1800)
        self.add_item(QCLGMDeskSelect(mode))

    @discord.ui.button(label="Refresh GM desk", style=discord.ButtonStyle.secondary, row=1)
    async def refresh(self, interaction, button):
        state = load_state()
        mode = "players" if "players" in str(self.children[0].values or []) else "teams"
        await interaction.response.edit_message(
            embed=_qcl_gmdesk_overview_embed(state, mode),
            view=QCLGMDeskView(mode),
        )


