class QCLRegistrationRecordSelect(discord.ui.Select):
    def __init__(self, folder):
        records = _qcl_reg_folder_records(load_state(), folder)
        if records:
            options = []
            for record in records[:25]:
                subject = _qcl_reg_subject(record)
                options.append(
                    discord.SelectOption(
                        label=subject[:100],
                        value=str(record.get("registration_id", ""))[:100],
                        description=(
                            f"{_qcl_reg_role_label(record.get('role'))} · "
                            f"{record.get('status', 'draft')} · "
                            f"{len(_qcl_reg_people_list(record))} people / "
                            f"{_qcl_reg_proof_count(record)} proof"
                        )[:100],
                    )
                )
        else:
            options = [
                discord.SelectOption(
                    label="No registrations in this folder",
                    value="__none__",
                    description="Choose another folder above.",
                )
            ]
        super().__init__(
            placeholder="Open a registration record…",
            min_values=1,
            max_values=1,
            options=options,
            row=1,
        )
        self.folder = folder

    async def callback(self, interaction):
        if self.values[0] == "__none__":
            return await interaction.response.send_message(
                "There are no registrations in this folder yet.",
                ephemeral=True,
            )
        if not interaction.user.guild_permissions.administrator:
            return await interaction.response.send_message(
                "Only administrators can open registration records.",
                ephemeral=True,
            )
        state = load_state()
        record = _qcl_reg_find(state, self.values[0])
        if not record:
            return await interaction.response.send_message(
                "That registration was removed or could not be found.",
                ephemeral=True,
            )
        await interaction.response.edit_message(
            embed=_qcl_reg_detail_embed(record),
            view=QCLRegistrationDetailView(record.get("registration_id"), self.folder),
        )


class QCLRegistrationDeskView(discord.ui.View):
    def __init__(self, folder="all"):
        super().__init__(timeout=1800)
        self.folder = folder
        self.add_item(QCLRegistrationFolderSelect(folder))
        self.add_item(QCLRegistrationRecordSelect(folder))

    async def interaction_check(self, interaction):
        if not interaction.user.guild_permissions.administrator:
            await interaction.response.send_message(
                "Only administrators can use the QCL Master Desk.",
                ephemeral=True,
            )
            return False
        return True

    @discord.ui.button(label="Refresh desk", style=discord.ButtonStyle.secondary, row=2)
    async def refresh(self, interaction, button):
        state = load_state()
        await interaction.response.edit_message(
            embed=_qcl_reg_desk_embed(state, self.folder),
            view=QCLRegistrationDeskView(self.folder),
        )


class QCLRegistrationDecisionModal(discord.ui.Modal):
    def __init__(self, registration_id, action):
        self.registration_id = registration_id
        self.action = action
        title = "Request missing information" if action == "needs_info" else "Reject registration"
        super().__init__(title=title)
        self.reason = discord.ui.TextInput(
            label="Message for the applicant",
            placeholder=(
                "Tell them exactly which roster member or proof file is missing."
            ),
            style=discord.TextStyle.paragraph,
            required=False,
            max_length=800,
        )
        self.add_item(self.reason)

    async def on_submit(self, interaction):
        if not interaction.user.guild_permissions.administrator:
            return await interaction.response.send_message(
                "Only administrators can change registration status.",
                ephemeral=True,
            )
        state = load_state()
        record = _qcl_reg_find(state, self.registration_id)
        if not record:
            return await interaction.response.send_message(
                "Registration not found.",
                ephemeral=True,
            )
        reason = self.reason.value.strip() or (
            "Please complete the missing registration checklist items."
        )
        now = _qcl_reg_now()
        record["status"] = self.action
        record["admin_note"] = reason
        record.setdefault("history", []).append(
            {
                "at": now,
                "action": self.action,
                "by": str(interaction.user.id),
                "reason": reason,
            }
        )
        if self.action == "rejected":
            record["rejection_reason"] = reason
            record["rejected_by"] = str(interaction.user.id)
            record["rejected_at"] = now
        _qcl_reg_rebuild_people_index(state)
        save_state(state)
        await interaction.response.send_message(
            f"Saved `{self.action.replace('_', ' ')}` for `{self.registration_id}`.",
            ephemeral=True,
        )


class QCLRegistrationDetailView(discord.ui.View):
    def __init__(self, registration_id, folder="all"):
        super().__init__(timeout=1800)
        self.registration_id = registration_id
        self.folder = folder

    async def interaction_check(self, interaction):
        if not interaction.user.guild_permissions.administrator:
            await interaction.response.send_message(
                "Only administrators can review QCL registrations.",
                ephemeral=True,
            )
            return False
        return True

    @discord.ui.button(label="Approve", style=discord.ButtonStyle.success, row=0)
    async def approve(self, interaction, button):
        state = load_state()
        record = _qcl_reg_find(state, self.registration_id)
        if not record:
            return await interaction.response.send_message(
                "Registration not found.",
                ephemeral=True,
            )
        now = _qcl_reg_now()
        record["status"] = "approved"
        record["approved_by"] = str(interaction.user.id)
        record["approved_at"] = now
        record.setdefault("history", []).append(
            {"at": now, "action": "approved", "by": str(interaction.user.id)}
        )
        _qcl_reg_rebuild_people_index(state)
        save_state(state)
        await interaction.response.edit_message(
            embed=_qcl_reg_detail_embed(record),
            view=self,
        )

    @discord.ui.button(label="Request info", style=discord.ButtonStyle.primary, row=0)
    async def request_info(self, interaction, button):
        await interaction.response.send_modal(
            QCLRegistrationDecisionModal(self.registration_id, "needs_info")
        )

    @discord.ui.button(label="Reject", style=discord.ButtonStyle.danger, row=0)
    async def reject(self, interaction, button):
        await interaction.response.send_modal(
            QCLRegistrationDecisionModal(self.registration_id, "rejected")
        )

    @discord.ui.button(label="Back to folders", style=discord.ButtonStyle.secondary, row=1)
    async def back(self, interaction, button):
        state = load_state()
        await interaction.response.edit_message(
            embed=_qcl_reg_desk_embed(state, self.folder),
            view=QCLRegistrationDeskView(self.folder),
        )


