@bot.command(name="QCLRegList", aliases=["qclreglist"])
@commands.has_permissions(administrator=True)
async def qcl_registration_list(ctx, status=""):
    """Backward-compatible compact list with a link to the interactive desk."""
    state = load_state()
    wanted = str(status or "").strip().lower()
    records = _qcl_reg_folder_records(state, wanted if wanted else "all")
    if wanted and wanted not in {"all", "byot", "draft", "review", "needs_info", "approved"}:
        records = [
            item for item in records if item.get("status", "").lower() == wanted
        ]
    if not records:
        return await ctx.send(
            "No registrations found"
            + (f" with status `{wanted}`." if wanted else ".")
            + "\nUse `!QCLRegDesk` to open the master desk."
        )
    lines = [
        f"**QCL registration list**{f' · `{wanted}`' if wanted else ''}",
        "Use `!QCLRegDesk` for folders or `!QCLRegView <ID>` for a detail card.",
        "",
    ]
    for item in records:
        people = _qcl_reg_people_list(item)
        lines.append(
            f"`{item.get('registration_id')}` · **{item.get('status', 'draft')}** · "
            f"{_qcl_reg_role_label(item.get('role'))} · {_qcl_reg_subject(item)} · "
            f"{len(people)} people / {_qcl_reg_proof_count(item)} proof files"
        )
    text = "\n".join(lines)
    for start in range(0, len(text), 1900):
        await ctx.send(text[start : start + 1900])


