@bot.command(name="QCLRegApprove", aliases=["qclregapprove"])
@commands.has_permissions(administrator=True)
async def qcl_registration_approve(ctx, registration_id=""):
    """Admin approval step; keeps the audit trail for later roster changes."""
    state = load_state()
    record = _qcl_reg_find(state, registration_id)
    if not record:
        return await ctx.send("Registration not found.")
    now = _qcl_reg_now()
    record["status"] = "approved"
    record["approved_by"] = str(ctx.author.id)
    record["approved_at"] = now
    record.setdefault("history", []).append(
        {"at": now, "action": "approved", "by": str(ctx.author.id)}
    )
    _qcl_reg_rebuild_people_index(state)
    save_state(state)
    await ctx.send(f"Approved `{registration_id}`. The people index is updated.")


@bot.command(name="QCLRegReject", aliases=["qclregreject"])
@commands.has_permissions(administrator=True)
async def qcl_registration_reject(ctx, registration_id="", *, reason=""):
    """Admin rejection step with a reason stored in the registration history."""
    state = load_state()
    record = _qcl_reg_find(state, registration_id)
    if not record:
        return await ctx.send("Registration not found.")
    reason = reason.strip() or "No reason supplied."
    now = _qcl_reg_now()
    record["status"] = "rejected"
    record["rejection_reason"] = reason
    record["rejected_by"] = str(ctx.author.id)
    record["rejected_at"] = now
    record.setdefault("history", []).append(
        {
            "at": now,
            "action": "rejected",
            "by": str(ctx.author.id),
            "reason": reason,
        }
    )
    save_state(state)
    await ctx.send(f"Rejected `{registration_id}` and saved the reason.")


@bot.command(name="commandcenter")
@commands.has_permissions(administrator=True)
async def commandcenter(ctx):
    """Open the admin-only URG control center."""
    events_folder = os.path.join(
        os.path.dirname(os.path.abspath(__file__)),
        "urg_events",
    )
    if not os.path.isdir(events_folder):
        await ctx.send(
            "⚠️ The `urg_events` folder does not exist yet. Add the event flyer "
            "files there and run `!commandcenter` again."
        )
        return

    event_files = sorted(
        os.path.join(events_folder, filename)
        for filename in os.listdir(events_folder)
        if os.path.isfile(os.path.join(events_folder, filename))
    )
    if not event_files:
        await ctx.send(
            "⚠️ No event flyers were found in the `urg_events` folder."
        )
        return

    visible_files = event_files[:25]
    description = (
        "Independent URG controls:\n"
        "• **Lock Chat** — hide Discord chat while the stream is live.\n"
        "• **Send Mass DMs** — send a flyer with registration buttons.\n"
        "• **Post Announcement** — choose channels and collect opt-ins.\n"
        "• **Registration Stats** — view clicks and interested members.\n\n"
        "Select a flyer before using **Send Mass DMs** or **Post Announcement**."
    )
    if len(event_files) > 25:
        description += (
            f"\n\n⚠️ Discord allows 25 dropdown options, so only the first "
            f"25 of {len(event_files)} files are shown."
        )

    await ctx.send(
        embed=discord.Embed(
            title="🚨 URG COMMAND CENTER",
            description=description,
            color=0xFF2D55,
        ),
        view=URGEventView(visible_files, ctx.author.id, bot),
    )


