TVT_COST = {"Legendary": 5, "Epic": 4, "Rare": 3, "Uncommon": 2, "Common": 1}
TVT_COLOR = {"Common": 0x8a929c, "Uncommon": 0x2ecc71, "Rare": 0x3498db,
             "Epic": 0x9b59b6, "Legendary": 0xf1c40f}
TVT_ODDS = [("Common", 0.50), ("Uncommon", 0.30), ("Rare", 0.15), ("Epic", 0.04), ("Legendary", 0.01)]
TVT_ORDER = ["Common", "Uncommon", "Rare", "Epic", "Legendary"]
TVT_PRINT_RUN = {"Legendary": 3, "Epic": 10, "Rare": 25, "Uncommon": 60, "Common": 0}  # 0 = unlimited
