TVT_NONANTE_CAP = 500                  # non-anted lineups capped at $5.00 (coins)
TVT_BASE_PRICE = {"Legendary": 200, "Epic": 160, "Rare": 120, "Uncommon": 80, "Common": 50}
TVT_PRICE_MIN, TVT_PRICE_MAX = 25, 300
TVT_ADMIN_IDS = set(x.strip() for x in _tvt_os.environ.get("FANTASY_ADMIN_IDS", "").split(",") if x.strip())
TVT_CASHOUT_FP = int(_tvt_os.environ.get("FANTASY_CASHOUT_FP", "1000"))  # cumulative FP to unlock cash-out
TVT_CASHAPP = _tvt_os.environ.get("FANTASY_CASHAPP", "")                 # e.g. $QwikCupLeague
TVT_ARCH_SIG = {"Microwave Chucker": "TPM", "Glass Cleaner": "REB", "Pocket Picker": "STL",
                "Rim Protector": "BLK", "Corner Specialist": "TP%", "Dime Dropper": "AST",
                "Combo Guard": "PTS", "Lockdown Wing": "DEF", "Iron Man Grind": "GP"}

_tvt_lock = _tvt_threading.Lock()
_tvt_pool = {"t": 0.0, "names": [], "rarity": {}, "arch": {}, "stats": {}, "buckets": {}, "trend": {}, "position": {}}


def _tvt_load_save():
    if _tvt_os.path.exists(TVT_SAVE_PATH):
        try:
            with open(TVT_SAVE_PATH, "r", encoding="utf-8") as f:
                d = _tvt_json.load(f)
            if isinstance(d, dict) and "users" in d:
                return d
        except Exception:
            pass
    return {"users": {}}


def _tvt_write_save(d):
    with _tvt_lock:
        tmp = TVT_SAVE_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _tvt_json.dump(d, f, indent=2)
        _tvt_os.replace(tmp, TVT_SAVE_PATH)


def _tvt_get_user(save, uid, name=""):
    u = save["users"].get(str(uid))
    if not u:
        u = {"name": name, "coins": TVT_START_COINS, "cards": [],
             "roster": {"G": None, "F": None, "C": None, "B1": None, "B2": None},
             "serials": {}, "cumulative_fp": 0.0, "history": []}
        save["users"][str(uid)] = u
    u.setdefault("serials", {})
    u.setdefault("cumulative_fp", 0.0)
    u.setdefault("roster", {"G": None, "F": None, "C": None, "B1": None, "B2": None})
    if set(u["roster"].keys()) != {"G", "F", "C", "B1", "B2"}:
        u["roster"] = {k: u["roster"].get(k) for k in ["G", "F", "C", "B1", "B2"]}
    if name:
        u["name"] = name
    return u


def _tvt_log(u, action, **kw):
    e = {"action": action, "ts": int(_tvt_time.time())}
    e.update(kw)
    u.setdefault("history", []).append(e)
    u["history"] = u["history"][-200:]


def _tvt_mint(save, player, tier):
    """Assign the next serial for a limited card, or None if unlimited / sold out."""
    run = TVT_PRINT_RUN.get(tier, 0)
    if tier not in TVT_SERIAL_TIERS or run <= 0:
        return None
    mint = save.setdefault("mint", {})
    minted = int(mint.get(player, 0))
    if minted >= run:
        return None  # print run exhausted -> unnumbered copy
    global _tvt_market_dirty
    serial = minted + 1
    mint[player] = serial
    _tvt_market_dirty = True
    return serial


def _tvt_update_catalog(save, names):
    """Track which players have been seen; return those added within the last week."""
    cat = save.setdefault("catalog", {"seen": {}, "init": False})
    seen = cat.setdefault("seen", {})
    now = int(_tvt_time.time())
    if not cat.get("init"):
        for n in names:
            seen.setdefault(n, 0)   # seed existing pool as "old"
        cat["init"] = True
        return []
    for n in names:
        if n not in seen:
            seen[n] = now
    week = 7 * 86400
    return [n for n in names if seen.get(n, 0) and now - seen[n] <= week]


# ---- currency hooks: swap these two for your CUPBUCKS system ----
def _tvt_spend(u, amount):
    if u["coins"] < amount:
        return False
    u["coins"] -= amount
    return True


def _tvt_earn(u, amount):
    u["coins"] += amount


def _tvt_compute_pool():
    df = _tvt_pd.read_csv(TVT_SHEET_CSV)
    df.columns = df.columns.str.strip()
    for c in ["PTS", "REB", "AST", "STL", "BLK", "TO", "FGA", "FGM", "3PM", "3PA",
              "FTA", "FTM", "Game_ID", "Season"]:
        if c in df.columns:
            df[c] = _tvt_pd.to_numeric(df[c], errors="coerce").fillna(0)
    nc = "Player/Team"
    is_team = (df.get("Type", _tvt_pd.Series([""] * len(df))).astype(str).str.lower()
               .isin(["team", "total", "totals", "team total"])
               | df[nc].astype(str).str.upper().str.endswith("TOTALS"))
    p = df[~is_team].copy()
    p = p[p[nc].astype(str).str.strip().ne("") & p[nc].astype(str).ne("0")]
    if p.empty:
        return {"t": _tvt_time.time(), "names": [], "rarity": {}, "arch": {}, "stats": {}, "buckets": {}, "trend": {}, "position": {}}
    p["poss"] = p["FGA"] + 0.44 * p["FTA"] + p["TO"]
    if {"Team Name", "Game_ID", "Season"}.issubset(p.columns):
        tp = p.groupby(["Season", "Game_ID", "Team Name"])["poss"].transform("sum")
        p["usg"] = _tvt_np.where(tp > 0, p["poss"] / tp * 100, 0)
    else:
        p["usg"] = 0.0
    p["PIE"] = (p["PTS"] + p["REB"] + p["AST"] + p["STL"] + p["BLK"]) - 0.5 * p["FGA"] - p["TO"]
    g = p.groupby(nc).agg(
        PTS=("PTS", "mean"), REB=("REB", "mean"), AST=("AST", "mean"),
        STL=("STL", "mean"), BLK=("BLK", "mean"), TO=("TO", "mean"),
        FGA=("FGA", "mean"), FGM=("FGM", "mean"), TPM=("3PM", "mean"), TPA=("3PA", "mean"),
        FTA=("FTA", "mean"), USG=("usg", "mean"), PIEm=("PIE", "mean"),
        GP=("Game_ID", "nunique")).reset_index()
    g["pct"] = g["PIEm"].rank(pct=True)
    tsden = 2 * (g["FGA"] + 0.44 * g["FTA"])
    g["TS"] = _tvt_np.where(tsden > 0, g["PTS"] / tsden * 100, 0)
    g["DEF"] = g["STL"] + g["BLK"]
    g["TP%"] = _tvt_np.where(g["TPA"] >= 1.0, g["TPM"] / g["TPA"].replace(0, 1) * 100, 0)
    ar = {a: g[col].rank(pct=True) for a, col in TVT_ARCH_SIG.items()}

    def tier_of(pct):
        for th, nm in TVT_THRESH:
            if pct >= th:
                return nm
        return "Common"

    names, rarity, arch, stats, buckets = [], {}, {}, {}, {}
    for i in range(len(g)):
        nm = g.iloc[i][nc]
        tier = tier_of(g.iloc[i]["pct"])
        a = max(TVT_ARCH_SIG.keys(), key=lambda k: ar[k].iloc[i])
        names.append(nm)
        rarity[nm] = tier
        arch[nm] = a
        stats[nm] = {"PTS": g.iloc[i]["PTS"], "REB": g.iloc[i]["REB"], "AST": g.iloc[i]["AST"],
                     "STL": g.iloc[i]["STL"], "BLK": g.iloc[i]["BLK"], "TO": g.iloc[i]["TO"],
                     "FGA": g.iloc[i]["FGA"], "FGM": g.iloc[i]["FGM"], "3PM": g.iloc[i]["TPM"],
                     "USG": g.iloc[i]["USG"], "TS%": g.iloc[i]["TS"]}
        buckets.setdefault(tier, []).append(nm)
    p_sorted = p.sort_values(["Season", "Game_ID"]) if {"Season", "Game_ID"}.issubset(p.columns) else p
    _recent = p_sorted.groupby(nc).tail(3).groupby(nc)["PIE"].mean()
    _overall = p.groupby(nc)["PIE"].mean()
    trend = {}
    for nm in names:
        trend[nm] = round(float(_recent.get(nm, _overall.get(nm, 0.0)) - _overall.get(nm, 0.0)), 1)

    # position from the sheet's row order within each team-game:
    #   rows 1-2 = Guards, 3-4 = Forwards, 5 (above TOTAL) = Big
    position = {}
    if {"Season", "Game_ID", "Team Name"}.issubset(p.columns):
        _pn = p.groupby(["Season", "Game_ID", "Team Name"]).cumcount() + 1
        _prole = _pn.map(lambda n: "Guard" if n <= 2 else ("Forward" if n <= 4 else "Big"))
        _pr = _prole.groupby(p[nc]).agg(lambda s: s.mode().iloc[0] if not s.mode().empty else "Forward")
        position = _pr.to_dict()
    for nm in names:
        position.setdefault(nm, "Forward")

    return {"t": _tvt_time.time(), "names": names, "rarity": rarity, "arch": arch, "stats": stats,
            "buckets": buckets, "trend": trend, "position": position}


async def _tvt_ensure_pool():
    if _tvt_pool["names"] and (_tvt_time.time() - _tvt_pool["t"] < TVT_POOL_TTL):
        return
    loop = _tvt_asyncio.get_event_loop()
    fresh = await loop.run_in_executor(None, _tvt_compute_pool)
    _tvt_pool.update(fresh)


def _tvt_fp(s, role):
    def gv(k):
        return float(s.get(k, 0) or 0)
    pts, tpm, ast = gv("PTS"), gv("3PM"), gv("AST")
    reb, stl, blk, to = gv("REB"), gv("STL"), gv("BLK"), gv("TO")
    miss = max(gv("FGA") - gv("FGM"), 0)
    usg, ts = gv("USG"), gv("TS%")
    three = tpm * 2.0
    neg = to * -1.5 + miss * -0.5
    role = (role or "").lower()
    if role.startswith("g"):
        return round(pts * (0.75 if usg > 30 else 1.0) + three + ast * 1.5 + reb * 2.0 + (stl + blk) * 4.0 + neg, 1)
    if role.startswith("f"):
        fp = pts * 1.5 + three + ast * 1.5 + reb * 1.0 + (stl + blk) * 5.0 + neg
        return round(fp + (3.0 if ts >= 60 else 0.0), 1)
    fp = pts * 1.5 + three + ast * 1.5 + reb * 0.75 + stl * 3.0 + blk * 1.5 + neg
    return round(fp + (5.0 if (usg < 15 and ts > 65) else 0.0), 1)


def _tvt_now_est():
    return _tvt_dt.datetime.now(_TVT_TZ)


def _tvt_roster_locked():
    n = _tvt_now_est()
    return (n.hour > TVT_LOCK_HOUR) or (n.hour == TVT_LOCK_HOUR and n.minute >= TVT_LOCK_MIN)


def _tvt_role(s):
    """Natural position from a player's stat profile (drives the FP multipliers)."""
    reb, blk = float(s.get("REB", 0)), float(s.get("BLK", 0))
    ast, stl, tpm = float(s.get("AST", 0)), float(s.get("STL", 0)), float(s.get("3PM", 0))
    big = reb + blk * 2
    guard = ast * 1.5 + stl + tpm
    if big >= guard * 1.15:
        return "Big"
    if guard >= big * 1.15:
        return "Guard"
    return "Forward"


# ---- SYNERGY ENGINE (procedural 1000-combo blueprint) --------------------
# Common/Uncommon archetype pairs unlock scaling multipliers. 9 archetypes ->
# 45 base pairs, each with a flavor name + scale factor (~1.25x-1.31x), mirroring
# the blueprint. Stacking multiple pairs in one roster escalates the bonus.
_TVT_ARCH_ORDER = ["Microwave Chucker", "Glass Cleaner", "Pocket Picker", "Rim Protector",
                   "Corner Specialist", "Dime Dropper", "Combo Guard", "Lockdown Wing", "Iron Man Grind"]
_TVT_PREFIX = ["Southside", "Asphalt", "Park After Dark", "QCL Twin", "Midnight", "Velocity",
               "Concrete", "Rucker", "Neon", "Hardwood", "Iron", "The Underground"]
_TVT_SUFFIX = ["Syndicate", "Duo", "Alliance", "Link", "Protocol", "Circuit",
               "Engine", "Network", "Clique", "Unit", "Frontline", "Connection"]
_TVT_PAIR_INDEX = {}
for _i in range(len(_TVT_ARCH_ORDER)):
    for _j in range(_i, len(_TVT_ARCH_ORDER)):
        _TVT_PAIR_INDEX[tuple(sorted((_TVT_ARCH_ORDER[_i], _TVT_ARCH_ORDER[_j])))] = len(_TVT_PAIR_INDEX)
_TVT_PAIR_N = max(len(_TVT_PAIR_INDEX) - 1, 1)


def _tvt_combo(a, b):
    pair = tuple(sorted((a, b)))
    idx = _TVT_PAIR_INDEX.get(pair, 0)
    factor = round(1.25 + (idx / _TVT_PAIR_N) * 0.06, 3)          # 1.25x .. 1.31x
    name = f"{_TVT_PREFIX[idx % len(_TVT_PREFIX)]} {a} & {b} {_TVT_SUFFIX[idx % len(_TVT_SUFFIX)]}"
    return name, factor


def _tvt_synergy(players):
    """players: entries with 'tier' and 'arch'. Returns (multiplier, [(name, factor)...])."""
    cu = [p for p in players if p.get("tier") in ("Common", "Uncommon") and p.get("arch")]
    combos, bonus = [], 0.0
    for i in range(len(cu)):
        for j in range(i + 1, len(cu)):
            name, factor = _tvt_combo(cu[i]["arch"], cu[j]["arch"])
            combos.append((name, factor))
            bonus += (factor - 1.0) * 0.15        # translate the pair's scale into a team bonus
    bonus = min(bonus, 0.30)                       # cap the stack at +30%
    return round(1.0 + bonus, 3), combos


# ---- ECONOMY -------------------------------------------------------------
def _tvt_usd(coins):
    return f"${int(coins) * TVT_COIN_USD:.2f}"


def _tvt_today():
    return _tvt_now_est().strftime("%Y-%m-%d")


def _tvt_week():
    return _tvt_now_est().strftime("%G-W%V")


def _tvt_rollover(e):
    if e["pot"].get("date") != _tvt_today():
        carry = int(e["pot"].get("coins", 0)) + int(e["pot"].get("rollover", 0))
        e["pot"] = {"date": _tvt_today(), "coins": 0, "rollover": carry}


def _tvt_econ(save):
    e = save.setdefault("economy",
                        {"treasury": 0, "pot": {"date": _tvt_today(), "coins": 0, "rollover": 0}, "ledger": []})
    e.setdefault("treasury", 0)
    e.setdefault("pot", {"date": _tvt_today(), "coins": 0, "rollover": 0})
    e.setdefault("ledger", [])
    _tvt_rollover(e)
    return e


def _tvt_ledger(e, kind, amount, note=""):
    e["ledger"].append({"ts": int(_tvt_time.time()), "date": _tvt_today(),
                        "type": kind, "amount": int(amount), "note": note})
    e["ledger"] = e["ledger"][-500:]


def _tvt_split_fee(e, coins, note):
    """Route a purchase fee: 60% to the daily pot, 40% to the treasury."""
    pot_share = int(round(coins * TVT_SIGN_POT_PCT))
    treasury_share = int(coins) - pot_share
    e["pot"]["coins"] += pot_share
    e["treasury"] += treasury_share
    _tvt_ledger(e, "fee", coins, f"{note} | pot+{pot_share} treasury+{treasury_share}")
    return pot_share, treasury_share


def _tvt_prices(save):
    """Weekly-indexed dynamic prices: base tier value x popularity x scarcity."""
    pr = save.setdefault("prices", {"week": "", "map": {}})
    if pr.get("week") == _tvt_week() and pr.get("map"):
        return pr["map"]
    mint = save.get("mint", {})
    users = save.get("users", {})
    total_users = max(len(users), 1)
    owners = {}
    for _uid, uu in users.items():
        for c in set(uu.get("cards", [])):
            owners[c] = owners.get(c, 0) + 1
    m = {}
    for nm in _tvt_pool["names"]:
        tier = _tvt_pool["rarity"].get(nm, "Common")
        base = TVT_BASE_PRICE.get(tier, 50)
        pop_rate = owners.get(nm, 0) / total_users
        run = TVT_PRINT_RUN.get(tier, 0)
        minted = int(mint.get(nm, 0))
        scarcity = 1 + 0.5 * (minted / run) if run > 0 else 1.0
        price = base * (1 + 0.5 * pop_rate) * scarcity
        m[nm] = int(min(max(round(price), TVT_PRICE_MIN), TVT_PRICE_MAX))
    pr["week"] = _tvt_week()
    pr["map"] = m
    return m


def _tvt_price(save, player):
    return _tvt_prices(save).get(player, 50)


def _tvt_eval_roster(roster):
    """Score a roster the same way everywhere: best-3 weighted x synergy.
    Returns entries, base, synergy, final, top-3 slots, and bench raw FP (tiebreaker)."""
    pos = _tvt_pool.get("position", {})
    entries = []
    for slot, is_start, label in [("G", True, "Guard"), ("F", True, "Forward"), ("C", True, "Big"),
                                  ("B1", False, "Bench"), ("B2", False, "Bench")]:
        nm = roster.get(slot)
        if nm and nm in _tvt_pool["stats"]:
            role = pos.get(nm) or _tvt_role(_tvt_pool["stats"][nm])
            fp = _tvt_fp(_tvt_pool["stats"][nm], role)
            weighted = round(fp * (1.0 if is_start else TVT_BENCH_MULT), 1)
            entries.append({"slot": slot, "label": label, "name": nm, "start": is_start, "role": role,
                            "fp": fp, "weighted": weighted, "tier": _tvt_pool["rarity"].get(nm, "Common"),
                            "arch": _tvt_pool["arch"].get(nm, "—")})
        else:
            entries.append({"slot": slot, "label": label, "name": None, "start": is_start})
    scored = [e for e in entries if e.get("weighted") is not None]
    top3 = sorted(scored, key=lambda e: e["weighted"], reverse=True)[:3]
    base = round(sum(e["weighted"] for e in top3), 1)
    syn_mult, combos = _tvt_synergy([e for e in entries if e.get("name")])
    final = round(base * syn_mult, 1)
    bench_raw = round(sum(e["fp"] for e in entries if e.get("name") and not e["start"]), 1)
    return {"entries": entries, "base": base, "syn_mult": syn_mult, "combos": combos,
            "final": final, "top_slots": {e["slot"] for e in top3}, "bench_raw": bench_raw}


# ---- VISUAL CARD BINDER (PIL) --------------------------------------------
def _tvt_font(size, bold=False):
    from PIL import ImageFont
    cands = (["C:/Windows/Fonts/arialbd.ttf", "arialbd.ttf",
              "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", "DejaVuSans-Bold.ttf"] if bold else
             ["C:/Windows/Fonts/arial.ttf", "arial.ttf",
              "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", "DejaVuSans.ttf"])
    for c in cands:
        try:
            return ImageFont.truetype(c, size)
        except Exception:
            pass
    try:
        return ImageFont.load_default(size)
    except Exception:
        return ImageFont.load_default()


def _tvt_hex(intcolor):
    return ((intcolor >> 16) & 255, (intcolor >> 8) & 255, intcolor & 255)


def _tvt_card_img(c):
    from PIL import Image, ImageDraw
    W, H = 260, 360
    tier = c["tier"]
    rgb = _tvt_hex(TVT_COLOR.get(tier, 0x8a929c))
    img = Image.new("RGB", (W, H), (16, 18, 22))
    d = ImageDraw.Draw(img)

    art = c.get("img")
    if art:
        try:
            src = Image.open(_tvt_io.BytesIO(art)).convert("RGB")
            iw, ih = src.size
            scale = min((W - 14) / iw, (H - 14) / ih)
            nw, nh = max(int(iw * scale), 1), max(int(ih * scale), 1)
            src = src.resize((nw, nh))
            img.paste(src, ((W - nw) // 2, (H - nh) // 2))
            d.rounded_rectangle([3, 3, W - 4, H - 4], radius=16, outline=rgb, width=6)
            if c.get("serials"):
                txt = f"#{min(c['serials'])}/{c.get('run', 0)}"
                bw = len(txt) * 9 + 16
                d.rounded_rectangle([W - bw - 10, H - 36, W - 10, H - 10], radius=8, fill=rgb)
                d.text((W - bw / 2 - 10, H - 23), txt, fill=(0, 0, 0), font=_tvt_font(13, True), anchor="mm")
            return img
        except Exception:
            img = Image.new("RGB", (W, H), (16, 18, 22))
            d = ImageDraw.Draw(img)

    # generated placeholder card (until the player has real art on GitHub)
    nm = c["name"]
    d.rounded_rectangle([3, 3, W - 4, H - 4], radius=16, outline=rgb, width=6)
    d.rounded_rectangle([16, 16, W - 16, 46], radius=8, fill=rgb)
    d.text((W / 2, 31), tier.upper(), fill=(0, 0, 0), font=_tvt_font(16, True), anchor="mm")
    cx, cy, r = W // 2, 138, 52
    d.ellipse([cx - r, cy - r, cx + r, cy + r], fill=(30, 30, 36), outline=rgb, width=4)
    parts = [p for p in nm.replace("_", " ").split() if p]
    initials = ("".join(p[0] for p in parts[:2]) or nm[:2]).upper()
    d.text((cx, cy), initials, fill=(255, 255, 255), font=_tvt_font(42, True), anchor="mm")
    d.text((W / 2, 214), nm[:16], fill=(255, 255, 255), font=_tvt_font(20, True), anchor="mm")
    d.text((W / 2, 240), c["arch"][:24], fill=(0, 191, 255), font=_tvt_font(13), anchor="mm")
    stats = c["stats"]
    d.text((W / 2, 284), f"{stats.get('PTS', 0):.1f} PPG", fill=(225, 225, 225),
           font=_tvt_font(16, True), anchor="mm")
    d.text((W / 2, 307), f"{stats.get('REB', 0):.1f} REB   {stats.get('AST', 0):.1f} AST",
           fill=(165, 165, 165), font=_tvt_font(13), anchor="mm")
    if c.get("serials"):
        d.text((W / 2, 336), f"#{min(c['serials'])}/{c.get('run', 0)}", fill=rgb,
               font=_tvt_font(15, True), anchor="mm")
    return img


def _tvt_render_binder_bytes(cards):
    """cards: list of dicts -> PNG bytes of a grid, or None if PIL is missing."""
    try:
        from PIL import Image
    except Exception:
        return None
    cols, pad, CW, CH = 4, 12, 260, 360
    n = len(cards)
    rows = max((n + cols - 1) // cols, 1)
    W = cols * CW + (cols + 1) * pad
    H = rows * CH + (rows + 1) * pad
    canvas = Image.new("RGB", (W, H), (10, 10, 12))
    for i, c in enumerate(cards):
        cimg = _tvt_card_img(c)
        rr, cc = divmod(i, cols)
        canvas.paste(cimg, (pad + cc * (CW + pad), pad + rr * (CH + pad)))
    buf = _tvt_io.BytesIO()
    canvas.save(buf, "PNG")
    return buf.getvalue()


# ---- real card art from GitHub (the same image on the repo) --------------
_TVT_CARDCAT = {"t": 0.0, "by_player": {}, "stems": []}
_TVT_IMGCACHE = {}


def _tvt_slug(s):
    return _tvt_re.sub(r"[^a-z0-9]+", "", str(s or "").lower())


async def _tvt_card_catalog():
    now = _tvt_time.time()
    if _TVT_CARDCAT["by_player"] and (now - _TVT_CARDCAT["t"] < 300):
        return _TVT_CARDCAT
    by_player, stems = {}, []
    hdr = {"User-Agent": "QSPN-QTCG", "Accept": "application/vnd.github+json"}
    if TVT_GH_TOKEN:
        hdr["Authorization"] = f"Bearer {TVT_GH_TOKEN}"
    try:
        async with _tvt_aiohttp.ClientSession() as s:
            meta = {}
            async with s.get(f"https://api.github.com/repos/{TVT_GH_REPO}/contents/cards/meta.json",
                             params={"ref": TVT_GH_BRANCH}, headers=hdr) as r:
                if r.status == 200:
                    j = await r.json()
                    try:
                        meta = _tvt_json.loads(_tvt_base64.b64decode(j["content"]).decode("utf-8"))
                    except Exception:
                        meta = {}
            async with s.get(f"https://api.github.com/repos/{TVT_GH_REPO}/contents/cards",
                             params={"ref": TVT_GH_BRANCH}, headers=hdr) as r:
                if r.status == 200:
                    for it in await r.json():
                        nm = it.get("name", "")
                        if not nm.lower().endswith((".png", ".jpg", ".jpeg", ".webp", ".gif")):
                            continue
                        stem = _tvt_os.path.splitext(nm)[0]
                        raw = f"https://raw.githubusercontent.com/{TVT_GH_REPO}/{TVT_GH_BRANCH}/cards/{nm}"
                        pslug = _tvt_slug(meta.get(stem, {}).get("player", ""))
                        if pslug:
                            by_player.setdefault(pslug, raw)
                        stems.append((_tvt_slug(stem), raw))
    except Exception as ex:
        print(f"[QTCG] card catalog failed: {ex}")
    _TVT_CARDCAT.update({"t": now, "by_player": by_player, "stems": stems})
    return _TVT_CARDCAT


_TVT_ALIASES = {"t": 0.0, "map": {}}

def _tvt_load_aliases():
    """Loads the variant-to-canonical aliases.json map from the data directory."""
    now = _tvt_time.time()
    if now - _TVT_ALIASES["t"] < 300:
        return _TVT_ALIASES["map"]
    amap = {}
    try:
        path = _tvt_os.path.join(TVT_DATA_DIR, "aliases.json")
        if _tvt_os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                amap = _tvt_json.load(f)
    except Exception:
        pass
    _TVT_ALIASES.update({"t": now, "map": amap})
    return amap

def _tvt_slug(s):
    return _tvt_re.sub(r"[^a-z0-9]+", "", str(s or "").lower())

def _tvt_card_url(player, cat):
    # 1) Collapse variant spellings to canonical names using the alias map
    amap = _tvt_load_aliases()
    canon_player = amap.get(player, player)
    
    # 2) Slugify for the lookup
    want = _tvt_slug(canon_player)
    if not want:
        return None
        
    for stem_slug, url in cat["stems"]:      # 1) exact base card (filename == player)
        if stem_slug == want:
            return url
    if want in cat["by_player"]:             # 2) card whose meta names this player
        return cat["by_player"][want]
    for stem_slug, url in cat["stems"]:      # 3) award card containing the name
        if want in stem_slug:
            return url
    return None


async def _tvt_fetch_img(url):
    if not url:
        return None
    if url in _TVT_IMGCACHE:
        return _TVT_IMGCACHE[url]
    try:
        async with _tvt_aiohttp.ClientSession() as s:
            async with s.get(url) as r:
                if r.status == 200:
                    data = await r.read()
                    if len(_TVT_IMGCACHE) > 250:
                        _TVT_IMGCACHE.clear()
                    _TVT_IMGCACHE[url] = data
                    return data
    except Exception:
        pass
    return None


def _tvt_draw_pack():
    out = []
    for _ in range(TVT_PACK_SIZE):
        roll = _tvt_random.random()
        cum, chosen = 0.0, "Common"
        for tier, odds in TVT_ODDS:
            cum += odds
            if roll <= cum:
                chosen = tier
                break
        bucket = _tvt_pool["buckets"].get(chosen) or _tvt_pool["names"]
        if bucket:
            out.append(_tvt_random.choice(bucket))
    return out


async def _tvt_owned_ac(interaction: _tvt_discord.Interaction, current: str):
    save = _tvt_load_save()
    u = save["users"].get(str(interaction.user.id), {})
    owned = sorted(set(u.get("cards", [])))
    cur = (current or "").lower()
    return [_tvt_ac.Choice(name=n[:100], value=n[:100]) for n in owned if cur in n.lower()][:25]


async def _tvt_all_ac(interaction: _tvt_discord.Interaction, current: str):
    await _tvt_ensure_pool()
    cur = (current or "").lower()
    return [_tvt_ac.Choice(name=n[:100], value=n[:100]) for n in _tvt_pool["names"] if cur in n.lower()][:25]


tvt_group = _tvt_ac.Group(name="qtcg", description="Qwiks Trading Card Game — packs, collection, roster")


@tvt_group.command(name="pack", description="Buy and open a card pack")
async def tvt_pack(interaction: _tvt_discord.Interaction):
    await interaction.response.defer(thinking=True)
    await _tvt_ensure_pool()
    if not _tvt_pool["names"]:
        return await interaction.followup.send("⚠️ No player data available right now.")
    save = _tvt_load_save()
    u = _tvt_get_user(save, interaction.user.id, str(interaction.user))
    if not _tvt_spend(u, TVT_PACK_COST):
        return await interaction.followup.send(
            f"❌ You need {TVT_PACK_COST} coins — you have {u['coins']}.")
    _tvt_split_fee(_tvt_econ(save), TVT_PACK_COST, f"{interaction.user} opened a pack")
    pulls = _tvt_draw_pack()
    pull_info = []
    for c in pulls:
        tier = _tvt_pool["rarity"].get(c, "Common")
        serial = _tvt_mint(save, c, tier)
        u["cards"].append(c)
        if serial is not None:
            u["serials"].setdefault(c, []).append(serial)
        pull_info.append((c, tier, serial))
    _tvt_log(u, "pack", cards=pulls, cost=TVT_PACK_COST)
    _tvt_write_save(save)
    best = max((t for _c, t, _s in pull_info), key=lambda t: TVT_ORDER.index(t) if t in TVT_ORDER else 0)
    emb = _tvt_discord.Embed(title="📦 Pack opened!",
                             description=f"{interaction.user.mention} spent **{TVT_PACK_COST}** coins "
                                         f"(balance: {u['coins']})",
                             color=TVT_COLOR.get(best, 0x8a929c))
    for c, tier, serial in pull_info:
        run = TVT_PRINT_RUN.get(tier, 0)
        tag = f"  ·  #{serial}/{run}" if serial else ""
        emb.add_field(name=f"{c}{tag}",
                      value=f"{tier} · {TVT_COST.get(tier,1)}pt\n🧬 {_tvt_pool['arch'].get(c,'—')}",
                      inline=True)
    await interaction.followup.send(embed=emb)


@tvt_group.command(name="collection", description="See your cards as a visual binder")
async def tvt_collection(interaction: _tvt_discord.Interaction):
    await interaction.response.defer(thinking=True)
    await _tvt_ensure_pool()
    save = _tvt_load_save()
    u = _tvt_get_user(save, interaction.user.id, str(interaction.user))
    _tvt_write_save(save)
    if not u["cards"]:
        return await interaction.followup.send("You don't own any cards yet — try `/qtcg pack`.")

    order = {"Legendary": 0, "Epic": 1, "Rare": 2, "Uncommon": 3, "Common": 4}
    counts = _TVT_Counter(u["cards"])
    uniques = sorted(counts.keys(),
                     key=lambda n: (order.get(_tvt_pool["rarity"].get(n, "Common"), 9), n.lower()))
    CAP = 24
    shown = uniques[:CAP]
    cards = []
    for nm in shown:
        tier = _tvt_pool["rarity"].get(nm, "Common")
        cards.append({"name": nm, "tier": tier, "arch": _tvt_pool["arch"].get(nm, "—"),
                      "stats": _tvt_pool["stats"].get(nm, {}),
                      "serials": u["serials"].get(nm, []), "run": TVT_PRINT_RUN.get(tier, 0)})

    cat = await _tvt_card_catalog()
    for c in cards:
        c["img"] = await _tvt_fetch_img(_tvt_card_url(c["name"], cat))

    loop = _tvt_asyncio.get_event_loop()
    png = await loop.run_in_executor(None, _tvt_render_binder_bytes, cards)

    by_tier = _TVT_Counter(_tvt_pool["rarity"].get(c, "Common") for c in u["cards"])
    summary = " · ".join(f"{t} {by_tier[t]}" for t in ["Legendary", "Epic", "Rare", "Uncommon", "Common"]
                         if by_tier.get(t))
    emb = _tvt_discord.Embed(
        title=f"🃏 {interaction.user.display_name}'s Collection",
        description=f"Coins: **{u['coins']}** ({_tvt_usd(u['coins'])})  ·  {len(u['cards'])} cards\n{summary}",
        color=0xD4AF37)
    if len(uniques) > CAP:
        emb.set_footer(text=f"Showing {CAP} of {len(uniques)} unique cards.")

    if png:
        file = _tvt_discord.File(_tvt_io.BytesIO(png), filename="binder.png")
        emb.set_image(url="attachment://binder.png")
        await interaction.followup.send(embed=emb, file=file)
    else:
        # PIL not installed -> fall back to a text list
        for tier in ["Legendary", "Epic", "Rare", "Uncommon", "Common"]:
            names = [n for n in uniques if _tvt_pool["rarity"].get(n, "Common") == tier]
            if names:
                emb.add_field(name=f"{tier} ({len(names)})",
                              value="\n".join(f"{n}{f' ×{counts[n]}' if counts[n] > 1 else ''}"
                                              for n in names)[:1024], inline=False)
        await interaction.followup.send(embed=emb)


@tvt_group.command(name="balance", description="Check your coin balance")
async def tvt_balance(interaction: _tvt_discord.Interaction):
    save = _tvt_load_save()
    u = _tvt_get_user(save, interaction.user.id, str(interaction.user))
    _tvt_write_save(save)
