@tvt_group.command(name="drop", description="Release a card from your collection")
@_tvt_ac.describe(player="Card to drop")
@_tvt_ac.autocomplete(player=_tvt_owned_ac)
async def tvt_drop(interaction: _tvt_discord.Interaction, player: str):
    await interaction.response.defer(thinking=True)
    save = _tvt_load_save()
    u = _tvt_get_user(save, interaction.user.id, str(interaction.user))
    if player not in u["cards"]:
        return await interaction.followup.send("❌ You don't own that card.")
    u["cards"].remove(player)
    if u["serials"].get(player):
        u["serials"][player].pop()
        if not u["serials"][player]:
            u["serials"].pop(player, None)
    for k, val in list(u.get("roster", {}).items()):
        if val == player:
            u["roster"][k] = None
    _tvt_log(u, "drop", card=player)
    _tvt_write_save(save)
    await interaction.followup.send(f"🗑️ Dropped **{player}**.")


@tvt_group.command(name="roster", description="Set / view your roster — 1 Guard, 1 Forward, 1 Big + 2 bench")
@_tvt_ac.describe(guard="Starting Guard", forward="Starting Forward", big="Starting Big",
                  bench1="Bench 1 (any position)", bench2="Bench 2 (any position)")
@_tvt_ac.autocomplete(guard=_tvt_owned_ac, forward=_tvt_owned_ac, big=_tvt_owned_ac,
                      bench1=_tvt_owned_ac, bench2=_tvt_owned_ac)
async def tvt_roster(interaction: _tvt_discord.Interaction,
                     guard: str = None, forward: str = None, big: str = None,
                     bench1: str = None, bench2: str = None):
    await interaction.response.defer(thinking=True)
    await _tvt_ensure_pool()
    save = _tvt_load_save()
    u = _tvt_get_user(save, interaction.user.id, str(interaction.user))
    pos = _tvt_pool.get("position", {})

    reqs = {"G": (guard, "Guard"), "F": (forward, "Forward"), "C": (big, "Big"),
            "B1": (bench1, None), "B2": (bench2, None)}
    if any(v for v, _n in reqs.values()):
        if _tvt_roster_locked():
            _tvt_write_save(save)
            return await interaction.followup.send(
                "🔒 Rosters lock at **6:30 PM EST**. Changes reopen tomorrow.")
        new = dict(u["roster"])
        for k, (v, need) in reqs.items():
            if v:
                if v not in u["cards"]:
                    _tvt_write_save(save)
                    return await interaction.followup.send(
                        f"❌ You don't own **{v}** — pull or sign it first.")
                if need and pos.get(v, "Forward") != need:
                    _tvt_write_save(save)
                    return await interaction.followup.send(
                        f"❌ **{v}** is a **{pos.get(v,'Forward')}** — the {need} slot needs a {need}.")
                new[k] = v
        filled = [x for x in new.values() if x]
        if len(set(filled)) != len(filled):
            _tvt_write_save(save)
            return await interaction.followup.send(
                "❌ A player can only hold one slot. Pick distinct players.")
        u["roster"] = new
        _tvt_log(u, "roster", roster=new)
    _tvt_write_save(save)

    roster = u["roster"]
    ev = _tvt_eval_roster(roster)
    entries, top_slots = ev["entries"], ev["top_slots"]
    base, syn_mult, combos, final = ev["base"], ev["syn_mult"], ev["combos"], ev["final"]
    locked = _tvt_roster_locked()

    emb = _tvt_discord.Embed(
        title=f"🏀 {interaction.user.display_name}'s Roster",
        description=(f"**Daily Score: {final} FP**\n"
                     f"Best-3 {base} × Synergy {syn_mult:.2f}\n"
                     + ("🔒 Locked for today — reopens tomorrow" if locked
                        else "🟢 Open — locks 6:30 PM EST")),
        color=0xD4AF37)

    def _line(e):
        if not e["name"]:
            return f"*(empty {e['label']})*"
        star = "⭐" if e["slot"] in top_slots else "▫️"
        w = "1.0" if e["start"] else "0.8"
        return (f"{star} **{e['name']}** ({e['tier']}, {e['role']}) — "
                f"{e['fp']:.1f} × {w} = **{e['weighted']:.1f}**")

    emb.add_field(name="Starters — 100% (1G / 1F / 1Big)",
                  value="\n".join(_line(e) for e in entries if e["start"]) or "—", inline=False)
    emb.add_field(name="Bench — 80%",
                  value="\n".join(_line(e) for e in entries if not e["start"]) or "—", inline=False)
    if combos:
        top_combos = sorted(combos, key=lambda c: c[1], reverse=True)[:5]
        emb.add_field(name=f"⚡ Synergies ({len(combos)} active)",
                      value="\n".join(f"{n}  ×{f:.3f}" for n, f in top_combos)[:1024], inline=False)
    emb.set_footer(text="⭐ = counts toward Best-3. Synergy from Common/Uncommon archetype pairs. Locks 6:30 PM EST.")
    await interaction.followup.send(embed=emb)


@tvt_group.command(name="library", description="Browse the whole library — new, trending, and what's left")
@_tvt_ac.describe(tier="Optionally list every card of one tier")
@_tvt_ac.choices(tier=[_tvt_ac.Choice(name=t, value=t) for t in
                       ["Legendary", "Epic", "Rare", "Uncommon", "Common"]])
async def tvt_library(interaction: _tvt_discord.Interaction, tier: _tvt_ac.Choice[str] = None):
    await interaction.response.defer(thinking=True)
    await _tvt_ensure_pool()
    if not _tvt_pool["names"]:
        return await interaction.followup.send("\u26a0\ufe0f No player data available right now.")
    save = _tvt_load_save()
    new_players = _tvt_update_catalog(save, _tvt_pool["names"])
    _tvt_write_save(save)
    mint = save.get("mint", {})

    def _left(nm, t):
        run = TVT_PRINT_RUN.get(t, 0)
        if t not in TVT_SERIAL_TIERS or run <= 0:
            return None
        return max(run - int(mint.get(nm, 0)), 0)

    # ---- single-tier full listing ----
    if tier is not None:
        tname = tier.value
        players = sorted(_tvt_pool["buckets"].get(tname, []))
        if not players:
            return await interaction.followup.send(f"No {tname} cards yet.")
        lines = []
        for nm in players:
            rem = _left(nm, tname)
            rtag = f"  \u00b7  {rem}/{TVT_PRINT_RUN[tname]} left" if rem is not None else ""
            lines.append(f"\u2022 **{nm}** \u2014 {_tvt_pool['arch'].get(nm,'\u2014')}{rtag}")
        chunks, buf = [], ""
        for ln in lines:
            if len(buf) + len(ln) + 1 > 3800:
                chunks.append(buf); buf = ""
            buf += ln + "\n"
        if buf:
            chunks.append(buf)
        for i, ch in enumerate(chunks):
            emb = _tvt_discord.Embed(title=(f"{tname} cards \u2014 {len(players)}" if i == 0 else "\u2026continued"),
                                     description=ch, color=TVT_COLOR.get(tname, 0x8a929c))
            await interaction.followup.send(embed=emb)
        return

    # ---- overview ----
    counts = {t: len(_tvt_pool["buckets"].get(t, [])) for t in TVT_ORDER}
    emb = _tvt_discord.Embed(
        title=f"\U0001f0cf QTCG Card Library \u2014 {len(_tvt_pool['names'])} cards",
        description=" \u00b7 ".join(f"**{t}** {counts[t]}"
                                    for t in ["Legendary", "Epic", "Rare", "Uncommon", "Common"]),
        color=0xD4AF37)
    if new_players:
        nl = [f"{n} ({_tvt_pool['rarity'].get(n,'Common')})" for n in sorted(new_players)][:12]
        emb.add_field(name="\U0001f195 New this week", value="\n".join(nl)[:1024], inline=False)
    trend = _tvt_pool.get("trend", {})
    up = sorted(((n, trend.get(n, 0)) for n in _tvt_pool["names"]), key=lambda x: x[1], reverse=True)
    up = [f"\U0001f4c8 {n}  +{v:.1f}" for n, v in up if v > 0][:8]
    if up:
        emb.add_field(name="\U0001f525 Trending Up", value="\n".join(up)[:1024], inline=True)
    stock = []
    for t in ["Legendary", "Epic", "Rare"]:
        for nm in _tvt_pool["buckets"].get(t, []):
            rem = _left(nm, t)
            if rem is not None:
                stock.append((nm, t, rem, TVT_PRINT_RUN[t]))
    stock.sort(key=lambda x: (x[2], x[3]))
    sl = [f"{nm} ({t}) \u2014 {rem}/{run} left" for nm, t, rem, run in stock[:8]]
    if sl:
        emb.add_field(name="\u23f3 Limited Stock", value="\n".join(sl)[:1024], inline=True)
    emb.set_footer(text="Use /qtcg library tier:<Rarity> to see every card of a tier.")
    await interaction.followup.send(embed=emb)


def _tvt_build_market(save):
    """Serialized-card counts to publish so the Hub matches Discord exactly."""
    mint = save.get("mint", {})
    cards = {}
    for nm in _tvt_pool["names"]:
        t = _tvt_pool["rarity"].get(nm, "Common")
        run = TVT_PRINT_RUN.get(t, 0)
        if t in TVT_SERIAL_TIERS and run > 0:
            cards[nm] = {"tier": t, "minted": int(mint.get(nm, 0)), "run": run}
    return {"updated": int(_tvt_time.time()), "cards": cards}


async def _tvt_gh_put_json(path, obj, message):
    if not TVT_GH_TOKEN:
        return False
    hdr = {"Authorization": f"Bearer {TVT_GH_TOKEN}", "Accept": "application/vnd.github+json",
           "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "QSPN-QTCG"}
    url = f"https://api.github.com/repos/{TVT_GH_REPO}/contents/{path}"
    try:
        async with _tvt_aiohttp.ClientSession() as s:
            sha = None
            async with s.get(url, params={"ref": TVT_GH_BRANCH}, headers=hdr) as r:
                if r.status == 200:
                    sha = (await r.json()).get("sha")
            body = _tvt_json.dumps(obj, indent=2).encode("utf-8")
            data = {"message": message, "content": _tvt_base64.b64encode(body).decode("utf-8"),
                    "branch": TVT_GH_BRANCH}
            if sha:
                data["sha"] = sha
            async with s.put(url, json=data, headers=hdr) as r2:
                return r2.status in (200, 201)
    except Exception as e:
        print(f"[QTCG] market push failed: {e}")
        return False


@_tvt_tasks.loop(minutes=5)
async def _tvt_market_flush():
    global _tvt_market_dirty
    if not TVT_GH_TOKEN or not _tvt_market_dirty:
        return
    await _tvt_ensure_pool()
    if not _tvt_pool["names"]:
        return
    save = _tvt_load_save()
    ok = await _tvt_gh_put_json(TVT_MARKET_PATH, _tvt_build_market(save), "QTCG: market counts")
    if ok:
        _tvt_market_dirty = False


@_tvt_market_flush.before_loop
async def _tvt_market_wait():
    await bot.wait_until_ready()


_tvt_synced_guilds = set()


@bot.listen("on_ready")
async def _tvt_market_on_ready():
    # start the market-counts flush loop
    if not _tvt_market_flush.is_running():
        _tvt_market_flush.start()

    # instant command sync to a test guild (guild sync is immediate; global takes ~1h)
    _gid = _tvt_os.environ.get("GUILD_ID", "1406018430607298693")
    try:
        _gid = int(_gid)
    except (TypeError, ValueError):
        _gid = 0
    if _gid and _gid not in _tvt_synced_guilds:
        try:
            _guild = _tvt_discord.Object(id=_gid)
            bot.tree.copy_global_to(guild=_guild)
            await bot.tree.sync(guild=_guild)
            _tvt_synced_guilds.add(_gid)
            print(f"[QTCG] Instantly synced commands to guild {_gid}")
        except Exception as _ex:
            print(f"[QTCG] guild sync failed: {_ex}")


@tvt_group.command(name="ante", description="Ante up for today's prize pot (before 6:30 PM EST)")
async def tvt_ante(interaction: _tvt_discord.Interaction):
    await interaction.response.defer(thinking=True)
    save = _tvt_load_save()
    u = _tvt_get_user(save, interaction.user.id, str(interaction.user))
    e = _tvt_econ(save)
    today = _tvt_today()
    if u.get("ante", {}).get("date") == today and u["ante"].get("amount", 0) > 0:
        _tvt_write_save(save)
        return await interaction.followup.send("✅ You've already anted today — you're in for the full pot.")
    if _tvt_roster_locked():
        _tvt_write_save(save)
        return await interaction.followup.send("🔒 Antes close at **6:30 PM EST**. Catch tomorrow's pot.")
    if not _tvt_spend(u, TVT_ANTE_COST):
        _tvt_write_save(save)
        return await interaction.followup.send(
            f"❌ The ante is {TVT_ANTE_COST} coins ({_tvt_usd(TVT_ANTE_COST)}) — you have {u['coins']}.")
    e["pot"]["coins"] += TVT_ANTE_COST
    _tvt_ledger(e, "ante", TVT_ANTE_COST, str(interaction.user))
    u["ante"] = {"date": today, "amount": TVT_ANTE_COST}
    _tvt_log(u, "ante", amount=TVT_ANTE_COST)
    _tvt_write_save(save)
    total = e["pot"]["coins"] + e["pot"]["rollover"]
    emb = _tvt_discord.Embed(
        title="🎟️ You're anted in!",
        description=(f"Paid **{TVT_ANTE_COST}** coins ({_tvt_usd(TVT_ANTE_COST)}).\n"
                     f"Eligible for the **full** pot: {total} coins ({_tvt_usd(total)})."),
        color=0x2ecc71)
