@tvt_group.command(name="dnp", description="Declare a player DNP — refund antes of users who rostered them (admin)")
@_tvt_ac.describe(player="Player who did not play")
@_tvt_ac.autocomplete(player=_tvt_all_ac)
async def tvt_dnp(interaction: _tvt_discord.Interaction, player: str):
    if TVT_ADMIN_IDS and str(interaction.user.id) not in TVT_ADMIN_IDS:
        return await interaction.response.send_message("Admins only.", ephemeral=True)
    await interaction.response.defer(thinking=True)
    save = _tvt_load_save()
    e = _tvt_econ(save)
    today = _tvt_today()
    refunded = 0
    for uid, uu in save.get("users", {}).items():
        if uu.get("ante", {}).get("date") != today or uu["ante"].get("amount", 0) <= 0:
            continue
        if player in [v for v in uu.get("roster", {}).values() if v]:
            amt = int(uu["ante"].get("amount", 0))
            uu["coins"] = uu.get("coins", 0) + amt
            e["pot"]["coins"] = max(e["pot"]["coins"] - amt, 0)
            uu["ante"] = {"date": today, "amount": 0, "refunded": True}
            _tvt_ledger(e, "dnp_refund", amt, f"{player} DNP -> refund {uid}")
            refunded += 1
    _tvt_write_save(save)
    await interaction.followup.send(
        f"🩹 **{player}** marked DNP for {today}. Refunded antes to **{refunded}** user(s).")


@tvt_group.command(name="leaderboard", description="Today's daily standings (live)")
async def tvt_leaderboard(interaction: _tvt_discord.Interaction):
    await interaction.response.defer(thinking=True)
    await _tvt_ensure_pool()
