    lines = []
    for i, b in enumerate(board[:15]):
        elig = "🔓 eligible" if b["cum"] >= TVT_CASHOUT_FP else f"{b['cum']:.0f}/{TVT_CASHOUT_FP} FP"
        lines.append(f"**{i+1}.** {b['name']} — **{b['daily']:.1f}** FP"
                     + (" 🎟️" if b["anted"] else "") + f"  ·  {elig}")
    emb = _tvt_discord.Embed(title="🏆 Daily Leaderboard", description="\n".join(lines)[:4000],
                             color=0xD4AF37)
