@tvt_group.command(name="settle", description="Settle today's pot and pay the #1 winner (admin)")
async def tvt_settle(interaction: _tvt_discord.Interaction):
    if TVT_ADMIN_IDS and str(interaction.user.id) not in TVT_ADMIN_IDS:
        return await interaction.response.send_message("Admins only.", ephemeral=True)
    await interaction.response.defer(thinking=True)
    await _tvt_ensure_pool()
    save = _tvt_load_save()
    e = _tvt_econ(save)
    today = _tvt_today()
    if e.get("settled_date") == today:
        return await interaction.followup.send("✅ Today's pot has already been settled.")

    board = []
    for uid, uu in save.get("users", {}).items():
        roster = uu.get("roster", {})
        if not any(roster.values()):
            continue
        ev = _tvt_eval_roster(roster)
        uu["cumulative_fp"] = round(uu.get("cumulative_fp", 0.0) + ev["final"], 1)  # bank the day
        board.append({"uid": uid, "name": uu.get("name", uid), "daily": ev["final"],
                      "bench": ev["bench_raw"], "cum": uu["cumulative_fp"],
                      "anted": uu.get("ante", {}).get("date") == today and uu["ante"].get("amount", 0) > 0})
    board.sort(key=lambda x: (x["daily"], x["bench"]), reverse=True)   # tiebreak: bench FP

    pot_total = e["pot"]["coins"] + e["pot"]["rollover"]
    e["settled_date"] = today

    if not board:
        _tvt_write_save(save)
        return await interaction.followup.send(
            f"No participants today — **{pot_total} coins ({_tvt_usd(pot_total)})** rolls into tomorrow.")

    win = board[0]
    if win["cum"] < TVT_CASHOUT_FP:
        _tvt_write_save(save)
        return await interaction.followup.send(
            f"🥇 **{win['name']}** led with {win['daily']:.1f} FP, but is at "
            f"{win['cum']:.0f}/{TVT_CASHOUT_FP} cumulative — **not cash-out eligible**. "
            f"Pot **{pot_total} coins ({_tvt_usd(pot_total)})** rolls over.")

    payout = pot_total if win["anted"] else min(pot_total, TVT_NONANTE_CAP)
    excess = pot_total - payout
    save["users"][win["uid"]]["coins"] = save["users"][win["uid"]].get("coins", 0) + payout
    _tvt_ledger(e, "payout", payout,
                f"{win['name']} #1 ({'ante' if win['anted'] else 'non-ante $5 cap'})")
    e["pot"] = {"date": today, "coins": 0, "rollover": excess}  # excess compounds tomorrow
    _tvt_write_save(save)

    emb = _tvt_discord.Embed(title="💵 Pot Settled", color=0x2ecc71,
                             description=f"🥇 **{win['name']}** — {win['daily']:.1f} FP")
    emb.add_field(name="Payout", value=f"**{payout} coins ({_tvt_usd(payout)})**", inline=True)
    emb.add_field(name="Entry", value=("🎟️ Anted (full pot)" if win["anted"]
                                       else f"No ante — capped at {_tvt_usd(TVT_NONANTE_CAP)}"), inline=True)
    if excess > 0:
        emb.add_field(name="Rolled over", value=f"{excess} coins ({_tvt_usd(excess)})", inline=True)
    if TVT_CASHAPP:
        emb.add_field(name="Cash App", value=f"Send {_tvt_usd(payout)} to **{TVT_CASHAPP}**", inline=False)
    emb.set_footer(text="Cumulative FP banked for all participants. Tie #1 broken by combined bench FP.")
    await interaction.followup.send(embed=emb)


@tvt_group.command(name="grant", description="Credit coins to a user, e.g. after a Cash App buy-in (admin)")
@_tvt_ac.describe(user="Who to credit", amount="Coins to add (500 = $5.00)",
                  note="Optional reference (Cash App tag / receipt)")
async def tvt_grant(interaction: _tvt_discord.Interaction, user: _tvt_discord.User,
                    amount: int, note: str = None):
    if TVT_ADMIN_IDS and str(interaction.user.id) not in TVT_ADMIN_IDS:
        return await interaction.response.send_message("Admins only.", ephemeral=True)
    await interaction.response.defer(thinking=True)
    if amount <= 0:
        return await interaction.followup.send("❌ Amount must be a positive number of coins.")
    save = _tvt_load_save()
    e = _tvt_econ(save)
    target = _tvt_get_user(save, user.id, str(user))
    _tvt_earn(target, amount)
    _tvt_ledger(e, "grant", amount,
                f"grant to {user} by {interaction.user}" + (f" | {note}" if note else ""))
    _tvt_log(target, "grant", amount=amount, by=str(interaction.user))
    _tvt_write_save(save)
    emb = _tvt_discord.Embed(
        title="🪙 Coins granted", color=0x2ecc71,
        description=(f"Credited **{amount} coins ({_tvt_usd(amount)})** to {user.mention}.\n"
                     f"New balance: **{target['coins']} coins** ({_tvt_usd(target['coins'])})"))
    if note:
        emb.add_field(name="Reference", value=note[:1024], inline=False)
    emb.set_footer(text="Logged to the treasury ledger. Coins are backed by the real buy-in you received.")
    await interaction.followup.send(embed=emb)




# ═══════════════════════════════════════════════════════════════════════════
#  QTCG RANKING — card power, republish rules, power-up qualification
#
#  PASTE: anywhere AFTER the card studio block and AFTER the /qtcg fantasy
#  block (it reads _tvt_pool for player tiers). Everything is _qcr_ prefixed.
#
#  ── THE PROBLEM THIS SOLVES ────────────────────────────────────────────────
#  You already run TWO rarity systems and they measure different things:
#
#    PLAYER TIER   /qtcg fantasy, from PIE percentile (TVT_THRESH).
#                  "How good is this player right now." Moves with the stats.
#    CARD TIER     the studio, from how the card was obtained.
#                  "What did it take to get this." Fixed forever.
#
#  Collapsing them into one number would mean a superstar's free entry card
#  outranks a role player's earned MVP card -- which destroys the award
#  prestige you deliberately built. So they stay separate axes and combine
#  into a single CARD POWER SCORE for sorting, pricing and power-up slots.
#
#  ── THE FOUR AXES ──────────────────────────────────────────────────────────
#    performance  player tier from live stats          0-5
#    provenance   how the card was earned or bought    0-6   <- award tops out here
#    prestige     roles held (Top 50, HOF, ...)        0-5
#    scarcity     serial number vs print run          0-3
#    freshness    stale cards bleed rank until refreshed  -2
# ═══════════════════════════════════════════════════════════════════════════

_QCR_PERF = {"Common": 1, "Uncommon": 2, "Rare": 3, "Epic": 4, "Legendary": 5}

# Provenance is the ONLY axis where an award can beat everything money buys.
_QCR_PROV = {
    "entry":     0,    # free card that comes with league entry
    "core":      1,    # a free/core template
    "premium":   2,    # paid premium template
    "two_image": 2,
    "hero_paid": 3,    # bought the 3-image Hero
    "vault":     4,    # limited seasonal drop
    "hero_earned": 6,  # WON an individual award -- unpurchasable
}

_QCR_PRESTIGE = {
    "HALL OF FAME": 5, "TOP 10 ALL-TIME": 4, "TOP 25 ALL-TIME": 3,
    "TOP 50 ALL-TIME": 2, "TOP 75 ALL-TIME": 1,
    "CHAMPION": 3, "FINALS MVP": 3, "MVP": 3,
    "ALL-QCL": 2, "ALL-DEFENSIVE": 2, "DIRTY 30 CLUB": 1, "CAPTAIN": 1,
}

QCR_RANKS = [(20, "MYTHIC", 0xff4fd8), (16, "LEGENDARY", 0xf1c40f), (12, "EPIC", 0x9b59b6),
             (8, "RARE", 0x3498db), (5, "UNCOMMON", 0x2ecc71), (0, "COMMON", 0x8a929c)]


def _qcr_player_tier(player):
    """Live player tier from the fantasy pool. Falls back to Common."""
    try:
        return _tvt_pool["rarity"].get(player, "Common")
    except Exception:
        return "Common"


def _qcr_provenance(card):
    if card.get("award"):
        return "hero_earned"
    src = (card.get("source") or "").lower()
    if src in _QCR_PROV:
        return src
    tier = (card.get("template_tier") or "core").lower()
    n = len(card.get("images", []) or [])
    if tier == "vault":
        return "vault"
    if n >= 3:
        return "hero_paid"
    if tier == "premium":
        return "premium"
    if n == 2:
        return "two_image"
    return "entry"


def _qcr_scarcity(card):
    """Low serials in a short run are worth the most. 0-3."""
    serial, run = card.get("serial"), int(card.get("print_run", 0) or 0)
    if not serial or run <= 0:
        return 0.0
    rarity_of_run = max(0.0, 1.0 - (run / 100.0))          # short runs matter more
    position = (run - int(serial) + 1) / run                # #1 of 10 > #10 of 10
    return round(min(3.0, (rarity_of_run * 1.5) + (position * 1.5)), 2)


def _qcr_card_power(card, accolades=None, live_stats=None):
    """The single sortable number. Returns a dict so the UI can show the breakdown."""
    perf = _QCR_PERF.get(_qcr_player_tier(card.get("player", "")), 1)
    prov_key = _qcr_provenance(card)
    prov = _QCR_PROV.get(prov_key, 0)
    pres = 0
    for a in (accolades or card.get("accolades") or [])[:3]:
        pres += _QCR_PRESTIGE.get(str(a).upper().strip(), 0)
    pres = min(pres, 5)
    scar = _qcr_scarcity(card)
    stale = 0.0
    try:
        if _qc_card_state(card, live_stats or {}) == "stale":
            stale = -2.0
    except Exception:
        pass
    total = round(perf + prov + pres + scar + stale, 2)
    label, color = "COMMON", 0x8a929c
    for th, nm, col in QCR_RANKS:
        if total >= th:
            label, color = nm, col
            break
    return {"score": total, "label": label, "color": color,
            "performance": perf, "provenance": prov, "provenance_key": prov_key,
            "prestige": pres, "scarcity": scar, "freshness": stale}


def _qcr_rank_cards(cards, accolades=None, live_stats=None):
    """Sort a player's cards best-first. Award cards break ties upward."""
    scored = []
    for cid, c in (cards or {}).items():
        p = _qcr_card_power(c, accolades, live_stats)
        scored.append((cid, c, p))
    scored.sort(key=lambda t: (t[2]["score"], t[2]["provenance"], t[2]["scarcity"]), reverse=True)
    return scored


# ═══════════════════════════  REPUBLISH RULES  ═══════════════════════════
#  A republish REFRESHES the derived layer and PRESERVES identity.
#  Getting this wrong is how you accidentally re-mint serials and wreck scarcity.
_QCR_IMMUTABLE = ("card_id", "serial", "print_run", "created", "award",
                  "source", "template_tier", "cutout_v")


def _qcr_republish(old_card, new_card):
    """Merge a rebuild onto an existing card. Identity survives, everything
    derived refreshes. NEVER re-mints a serial."""
    merged = dict(new_card)
    for k in _QCR_IMMUTABLE:
        if old_card.get(k) is not None:
            merged[k] = old_card[k]
    merged["republished"] = int(old_card.get("republished", 0)) + 1
    merged["updated"] = _qc_dt.datetime.now(_qc_dt.timezone.utc).isoformat(timespec="seconds")
    merged["history"] = (old_card.get("history") or [])[-9:] + [{
        "at": merged["updated"],
        "template": old_card.get("template_id"),
        "layout": old_card.get("layout_id"),
        "colorway": old_card.get("colorway"),
    }]
    return merged


def _qcr_can_republish(card, ent, published=False):
    """Award cards are frozen -- that's the point of commemorating a season.
    Everything else follows the normal paywall."""
    if card.get("award"):
        return False, "Award cards are frozen forever \u2014 that's what makes them worth winning."
    if not published:
        return True, "Not published yet \u2014 rebuild freely."
    if int(ent.get("credits", {}).get("change_layout", 0)) > 0:
        return True, "You have a layout-change credit \u2014 this one's covered."
    return True, f"Published card \u2014 rebuilding costs ${QTCG_PRICES['change_layout']}."


# ═══════════════════════  POWER-UP QUALIFICATION  ═══════════════════════
#  Slots scale with CARD POWER. Power-ups themselves are EARNED, never sold --
#  if they were buyable, a paid Hero would beat an earned one in Fantasy and
#  the competitive side rots. Rarity gates the slots; it never boosts output.
QCR_SLOT_TIERS = [(16, 3), (11, 2), (7, 1), (0, 0)]

POWERUPS = {
    "overclock_core":    {"name": "Overclock Core",    "effect": "+12% PTS",  "min_power": 7,  "dur": 1},
    "adrenaline_inject": {"name": "Adrenaline Injector", "effect": "+15% REB/AST", "min_power": 7, "dur": 1},
    "mystic_catalyst":   {"name": "Mystic Catalyst",   "effect": "+20% synergy", "min_power": 11, "dur": 1},
    "iron_will":         {"name": "Iron Will",         "effect": "TO penalty halved", "min_power": 7, "dur": 3},
    "hot_hand":          {"name": "Hot Hand",          "effect": "+25% 3PM", "min_power": 11, "dur": 1},
    "lockdown_protocol": {"name": "Lockdown Protocol", "effect": "+30% STL/BLK", "min_power": 11, "dur": 1},
    "second_wind":       {"name": "Second Wind",       "effect": "bench mult 0.8 -> 1.0", "min_power": 16, "dur": 1},
    "prime_time":        {"name": "Prime Time",        "effect": "double best-3 slot", "min_power": 16, "dur": 1},
}


def _qcr_slots(power):
    for th, n in QCR_SLOT_TIERS:
        if power >= th:
            return n
    return 0


def _qcr_can_equip(card_power, powerup_key, equipped=None):
    """Gate a power-up onto a card. Returns (ok, reason)."""
    pu = POWERUPS.get(powerup_key)
    if not pu:
        return False, "Unknown power-up."
    slots = _qcr_slots(card_power["score"])
    if slots <= 0:
        return False, (f"This card is **{card_power['label']}** ({card_power['score']}) \u2014 "
                       f"needs **7.0+** power for its first slot. Win an award, add accolades, "
                       f"or refresh stale stats.")
    if len(equipped or []) >= slots:
        return False, f"All {slots} slot(s) full on this card."
    if card_power["score"] < pu["min_power"]:
        return False, (f"**{pu['name']}** needs **{pu['min_power']}+** power. "
                       f"This card is at {card_power['score']}.")
    if powerup_key in (equipped or []):
        return False, f"**{pu['name']}** is already equipped here."
    return True, f"**{pu['name']}** equipped \u2014 {pu['effect']} for {pu['dur']} game(s)."


def _qcr_power_bar(p):
    """Readable breakdown for an embed."""
    rows = [
        f"\u2003\U0001f3c0 Performance  **+{p['performance']}**  _(player tier)_",
        f"\u2003\U0001f396\ufe0f Provenance   **+{p['provenance']}**  _({p['provenance_key'].replace('_',' ')})_",
        f"\u2003\U0001f451 Prestige     **+{p['prestige']}**  _(roles)_",
    ]
    if p["scarcity"]:
        rows.append(f"\u2003\U0001f48e Scarcity     **+{p['scarcity']}**  _(serial)_")
    if p["freshness"]:
        rows.append(f"\u2003\u26a0\ufe0f Stale        **{p['freshness']}**  _(refresh to recover)_")
    return (f"**{p['label']}**  \u00b7  power **{p['score']}**\n" + "\n".join(rows)
            + f"\n\u2003\U0001f50c Power-up slots: **{_qcr_slots(p['score'])}**")

# ═══════════════════════════════════════════════════════════════════════════
#  QTCG SUPREME MARKET — supply, listings, auctions, price discovery, drops
#
#  PASTE: after the /qtcg fantasy block (needs _tvt_pool, _tvt_load_save,
#  _tvt_econ, _tvt_split_fee, _tvt_mint). All _mkt_ / MKT_ prefixed.
#
#  ── SETTLEMENT IS IN COINS, ON PURPOSE ─────────────────────────────────────
#  Auctions + speculation + player-to-player sales settled in real cash would
#  make you a marketplace operator: disputes, refunds, chargebacks, and a
#  2K Pro-Am roster that likely includes minors trading for money. Everything
#  here settles in COINS. Your existing cash-out gate (TVT_CASHOUT_FP) stays
#  the only bridge to real money. The 20% league fee, the auctions and the
#  price swings all work identically -- they just never touch cash directly.
#
#  ── FIVE SYSTEMS ───────────────────────────────────────────────────────────
#   1. SUPPLY      print run derived from STATS, not a flat tier table
#   2. LISTINGS    fixed-price sales, 20% league fee, escrowed cards
#   3. AUCTIONS    timed, anti-snipe extension, escrowed bids
#   4. INDEX       price discovery from REAL trades, not a formula
#   5. DROPS       statistical events mint limited Moment cards
# ═══════════════════════════════════════════════════════════════════════════

import time as _mkt_time
import random as _mkt_random

MKT_FEE_PCT = 0.20                 # league cut on every completed sale
MKT_FEE_POT_SHARE = 0.60           # of that cut: 60% prize pot, 40% treasury
MKT_MIN_PRICE = 10
MKT_MAX_PRICE = 100000
MKT_AUCTION_MIN_HOURS = 1
MKT_AUCTION_MAX_HOURS = 72
MKT_ANTISNIPE_SEC = 300            # a late bid pushes the close out by 5 min
MKT_BID_INCREMENT = 0.05           # each bid must beat the last by 5%
MKT_INDEX_WINDOW = 20              # trades kept per player for price discovery
MKT_LIST_CAP = 5                   # simultaneous listings per user

# ── 1. SUPPLY: print run comes from performance, not a flat tier table ──────
#  A Legendary who plays 40 games is not as scarce as one who played 6. Supply
#  scales with games played so grinders are attainable and short-run stars
#  stay genuinely rare.
MKT_BASE_RUN = {"Legendary": 3, "Epic": 10, "Rare": 25, "Uncommon": 60, "Common": 0}


def _mkt_supply(player):
    """(print_run, why). 0 = unlimited."""
    tier = _tvt_pool["rarity"].get(player, "Common")
    base = MKT_BASE_RUN.get(tier, 0)
    if base <= 0:
        return 0, "unlimited"
    st = _tvt_pool["stats"].get(player, {})
    gp = float(st.get("GP", 0) or 0)
    if gp <= 0:
        gp = float(_tvt_pool.get("gp", {}).get(player, 0) or 0)
    # more games -> more copies exist, up to 2.5x the base run
    mult = 1.0 + min(1.5, gp / 20.0)
    trend = float(_tvt_pool.get("trend", {}).get(player, 0) or 0)
    if trend > 0:
        mult *= 0.9                                  # hot players get scarcer
    run = max(1, int(round(base * mult)))
    return run, f"{tier} base {base} x{mult:.2f} (GP {gp:.0f}, trend {trend:+.1f})"


def _mkt_remaining(save, player):
    run, _why = _mkt_supply(player)
    if run <= 0:
        return None                                   # unlimited
    return max(run - int(save.get("mint", {}).get(player, 0)), 0)


# ── 2/3. STORAGE ───────────────────────────────────────────────────────────
def _mkt_store(save):
    m = save.setdefault("market", {"listings": {}, "auctions": {}, "trades": {},
                                   "index": {}, "moments": {}, "seq": 0})
    for k, d in (("listings", {}), ("auctions", {}), ("trades", {}),
                 ("index", {}), ("moments", {}), ("seq", 0)):
        m.setdefault(k, d)
    return m


def _mkt_id(save, prefix):
    m = _mkt_store(save)
    m["seq"] = int(m.get("seq", 0)) + 1
    return f"{prefix}{m['seq']:05d}"


def _mkt_owns(u, player, serial=None):
    if player not in u.get("cards", []):
        return False
    if serial is not None:
        return int(serial) in [int(s) for s in u.get("serials", {}).get(player, [])]
    return True


def _mkt_take(u, player, serial=None):
    """Remove one copy from a user (escrow). Returns the serial pulled, if any."""
    if player not in u.get("cards", []):
        return False, None
    u["cards"].remove(player)
    got = None
    ser = u.get("serials", {}).get(player, [])
    if ser:
        if serial is not None and int(serial) in [int(s) for s in ser]:
            ser.remove(int(serial))
            got = int(serial)
        else:
            got = int(ser.pop(0))
        if not ser:
            u["serials"].pop(player, None)
    for slot, val in list(u.get("roster", {}).items()):
        if val == player and player not in u["cards"]:
            u["roster"][slot] = None                  # can't start a card you sold
    return True, got


def _mkt_give(u, player, serial=None):
    u.setdefault("cards", []).append(player)
    if serial is not None:
        u.setdefault("serials", {}).setdefault(player, []).append(int(serial))


# ── 4. PRICE INDEX: discovery from real trades ─────────────────────────────
def _mkt_fair_value(save, player):
    """Formula price — the anchor before any trades exist."""
    return int(_tvt_price(save, player))


def _mkt_record_trade(save, player, price):
    m = _mkt_store(save)
    hist = m["trades"].setdefault(player, [])
    hist.append({"t": int(_mkt_time.time()), "p": int(price)})
    del hist[:-MKT_INDEX_WINDOW]
    prices = [h["p"] for h in hist]
    fair = _mkt_fair_value(save, player)
    last = prices[-1]
    avg = sum(prices) / len(prices)
    m["index"][player] = {
        "last": last,
        "avg": round(avg, 1),
        "n": len(prices),
        "fair": fair,
        # >1 means the room pays a premium over the formula. That IS the market.
        "heat": round(avg / fair, 3) if fair > 0 else 1.0,
    }
    return m["index"][player]


def _mkt_quote(save, player):
    """What a card is actually worth right now: formula, blended with trades."""
    m = _mkt_store(save)
    fair = _mkt_fair_value(save, player)
    idx = m["index"].get(player)
    if not idx or idx["n"] < 2:
        return {"price": fair, "fair": fair, "last": None, "heat": 1.0,
                "n": (idx or {}).get("n", 0), "source": "formula"}
    # more trades -> trust the market more, up to 70%
    w = min(0.70, 0.15 * idx["n"])
    price = int(round(fair * (1 - w) + idx["avg"] * w))
    price = max(MKT_MIN_PRICE, min(MKT_MAX_PRICE, price))
    return {"price": price, "fair": fair, "last": idx["last"], "heat": idx["heat"],
            "n": idx["n"], "source": "market"}


def _mkt_fee(price):
    fee = int(round(int(price) * MKT_FEE_PCT))
    return fee, int(price) - fee


def _mkt_route_fee(save, fee, note):
    e = _tvt_econ(save)
    pot = int(round(fee * MKT_FEE_POT_SHARE))
    tre = int(fee) - pot
    e["pot"]["coins"] += pot
    e["treasury"] += tre
    _tvt_ledger(e, "market_fee", fee, f"{note} | pot+{pot} treasury+{tre}")
    return pot, tre


# ── LISTINGS ───────────────────────────────────────────────────────────────
def _mkt_list_card(save, uid, player, price, serial=None):
    u = _tvt_get_user(save, uid)
    m = _mkt_store(save)
    price = int(price)
    if price < MKT_MIN_PRICE or price > MKT_MAX_PRICE:
        return None, f"Price must be {MKT_MIN_PRICE}-{MKT_MAX_PRICE:,} coins."
    mine = [l for l in m["listings"].values() if l["seller"] == str(uid) and l["open"]]
    if len(mine) >= MKT_LIST_CAP:
        return None, f"You already have {MKT_LIST_CAP} active listings."
    if not _mkt_owns(u, player, serial):
        return None, f"You don't own **{player}**" + (f" #{serial}" if serial else "") + "."
    ok, got = _mkt_take(u, player, serial)
    if not ok:
        return None, "Couldn't escrow that card."
    lid = _mkt_id(save, "L")
    m["listings"][lid] = {"id": lid, "seller": str(uid), "player": player,
                          "serial": got, "price": price, "open": True,
                          "listed": int(_mkt_time.time())}
    return m["listings"][lid], None


def _mkt_buy(save, uid, lid):
    m = _mkt_store(save)
    l = m["listings"].get(lid)
    if not l or not l["open"]:
        return None, "That listing is gone."
    if l["seller"] == str(uid):
        return None, "You can't buy your own listing."
    buyer = _tvt_get_user(save, uid)
    if buyer["coins"] < l["price"]:
        return None, f"Costs {l['price']:,} coins — you have {buyer['coins']:,}."
    seller = _tvt_get_user(save, l["seller"])
    buyer["coins"] -= l["price"]
    fee, net = _mkt_fee(l["price"])
    seller["coins"] += net
    _mkt_route_fee(save, fee, f"sale {l['player']} {l['price']}c")
    _mkt_give(buyer, l["player"], l.get("serial"))
    l["open"] = False
    l["buyer"] = str(uid)
    l["sold"] = int(_mkt_time.time())
    idx = _mkt_record_trade(save, l["player"], l["price"])
    _tvt_log(buyer, "buy", card=l["player"], price=l["price"])
    _tvt_log(seller, "sell", card=l["player"], price=l["price"], net=net, fee=fee)
    return {"listing": l, "fee": fee, "net": net, "index": idx}, None


def _mkt_cancel(save, uid, lid):
    m = _mkt_store(save)
    l = m["listings"].get(lid)
    if not l or not l["open"]:
        return None, "That listing is gone."
    if l["seller"] != str(uid):
        return None, "That isn't your listing."
    _mkt_give(_tvt_get_user(save, uid), l["player"], l.get("serial"))
    l["open"] = False
    l["cancelled"] = int(_mkt_time.time())
    return l, None


# ── AUCTIONS ───────────────────────────────────────────────────────────────
def _mkt_auction_start(save, uid, player, start_price, hours, serial=None):
    u = _tvt_get_user(save, uid)
    m = _mkt_store(save)
    hours = max(MKT_AUCTION_MIN_HOURS, min(MKT_AUCTION_MAX_HOURS, int(hours)))
    start_price = max(MKT_MIN_PRICE, int(start_price))
    if not _mkt_owns(u, player, serial):
        return None, f"You don't own **{player}**."
    ok, got = _mkt_take(u, player, serial)
    if not ok:
        return None, "Couldn't escrow that card."
    aid = _mkt_id(save, "A")
    m["auctions"][aid] = {"id": aid, "seller": str(uid), "player": player, "serial": got,
                          "start": start_price, "bid": 0, "bidder": None,
                          "ends": int(_mkt_time.time()) + hours * 3600,
                          "open": True, "history": []}
    return m["auctions"][aid], None


def _mkt_bid(save, uid, aid, amount):
    m = _mkt_store(save)
    a = m["auctions"].get(aid)
    now = int(_mkt_time.time())
    if not a or not a["open"]:
        return None, "That auction is closed."
    if now >= a["ends"]:
        return None, "That auction has ended."
    if a["seller"] == str(uid):
        return None, "You can't bid on your own auction."
    amount = int(amount)
    floor = a["start"] if not a["bid"] else int(a["bid"] * (1 + MKT_BID_INCREMENT)) + 1
    if amount < floor:
        return None, f"Minimum bid is **{floor:,}** coins."
    bidder = _tvt_get_user(save, uid)
    if bidder["coins"] < amount:
        return None, f"You have {bidder['coins']:,} coins."
    # refund the previous bidder — bids are escrowed, so nobody double-spends
    if a["bidder"]:
        prev = _tvt_get_user(save, a["bidder"])
        prev["coins"] += int(a["bid"])
    bidder["coins"] -= amount
    a["bid"] = amount
    a["bidder"] = str(uid)
    a["history"].append({"u": str(uid), "a": amount, "t": now})
    a["history"] = a["history"][-25:]
    # anti-snipe: a late bid extends the close
    extended = False
    if a["ends"] - now < MKT_ANTISNIPE_SEC:
        a["ends"] = now + MKT_ANTISNIPE_SEC
        extended = True
    return {"auction": a, "extended": extended}, None


def _mkt_auction_close(save, aid=None):
    """Settle one auction, or every expired one. Returns settled records."""
    m = _mkt_store(save)
    now = int(_mkt_time.time())
    todo = [m["auctions"][aid]] if aid and aid in m["auctions"] else \
        [a for a in m["auctions"].values() if a["open"] and now >= a["ends"]]
    out = []
    for a in todo:
        if not a["open"]:
            continue
        a["open"] = False
        a["closed"] = now
        if not a["bidder"]:
            _mkt_give(_tvt_get_user(save, a["seller"]), a["player"], a.get("serial"))
            out.append({"auction": a, "result": "no_bids"})
            continue
        seller = _tvt_get_user(save, a["seller"])
        winner = _tvt_get_user(save, a["bidder"])
        fee, net = _mkt_fee(a["bid"])          # winner's coins already escrowed
        seller["coins"] += net
        _mkt_route_fee(save, fee, f"auction {a['player']} {a['bid']}c")
        _mkt_give(winner, a["player"], a.get("serial"))
        idx = _mkt_record_trade(save, a["player"], a["bid"])
        _tvt_log(winner, "auction_win", card=a["player"], price=a["bid"])
        _tvt_log(seller, "auction_sell", card=a["player"], price=a["bid"], net=net, fee=fee)
        out.append({"auction": a, "result": "sold", "fee": fee, "net": net, "index": idx})
    return out


# ── 5. MOMENT DROPS: statistical events mint limited cards ─────────────────
#  A card that only exists because of one real performance. Scarce by nature,
#  can never be reprinted, and the trigger is public so nobody can be accused
#  of getting a handout.
MOMENT_TRIGGERS = {
    "FIFTY":   {"name": "50-Piece",        "run": 5,  "test": lambda r: r.get("PTS", 0) >= 50},
    "FORTY":   {"name": "40 Bomb",         "run": 10, "test": lambda r: 40 <= r.get("PTS", 0) < 50},
    "TRIPDUB": {"name": "Triple-Double",   "run": 10,
                "test": lambda r: sum(1 for k in ("PTS", "REB", "AST", "STL", "BLK")
                                      if r.get(k, 0) >= 10) >= 3},
    "QUADDUB": {"name": "Quadruple-Double", "run": 3,
                "test": lambda r: sum(1 for k in ("PTS", "REB", "AST", "STL", "BLK")
                                      if r.get(k, 0) >= 10) >= 4},
    "SWAT":    {"name": "Rejection Notice", "run": 8,  "test": lambda r: r.get("BLK", 0) >= 8},
    "PICKPKT": {"name": "Pickpocket",       "run": 8,  "test": lambda r: r.get("STL", 0) >= 8},
    "SNIPER":  {"name": "Sniper",           "run": 8,  "test": lambda r: r.get("3PM", 0) >= 10},
    "GLASS":   {"name": "Glass Eater",      "run": 8,  "test": lambda r: r.get("REB", 0) >= 20},
}


def _mkt_scan_moments(save, rows, season=None):
    """rows: dicts with Player/Team, Game_ID, Season and stat keys.
    Mints one Moment card per (player, game, trigger). Idempotent."""
    m = _mkt_store(save)
    minted = []
    for r in rows:
        player = str(r.get("Player/Team") or "").strip()
        if not player or player.upper().endswith("TOTALS"):
            continue
        gid = r.get("Game_ID")
        sea = r.get("Season", season)
        for key, cfg in MOMENT_TRIGGERS.items():
            try:
                if not cfg["test"](r):
                    continue
            except Exception:
                continue
            mid = f"{key}_{_tvt_slug(player)}_s{sea}_g{gid}"
            if mid in m["moments"]:
                continue                              # already minted -> idempotent
            m["moments"][mid] = {
                "id": mid, "trigger": key, "name": cfg["name"], "player": player,
                "season": sea, "game": gid, "run": cfg["run"], "minted": 0,
                "created": int(_mkt_time.time()),
                "stat_line": {k: r.get(k, 0) for k in ("PTS", "REB", "AST", "STL", "BLK", "3PM")},
            }
            minted.append(m["moments"][mid])
    return minted


def _mkt_claim_moment(save, uid, mid):
    m = _mkt_store(save)
    mo = m["moments"].get(mid)
    if not mo:
        return None, "No such moment."
    if int(mo["minted"]) >= int(mo["run"]):
        return None, f"**{mo['name']}** is sold out ({mo['run']}/{mo['run']})."
    u = _tvt_get_user(save, uid)
    price = int(_mkt_quote(save, mo["player"])["price"] * 1.5)   # moments carry a premium
    if u["coins"] < price:
        return None, f"Costs {price:,} coins — you have {u['coins']:,}."
    u["coins"] -= price
    fee, _net = _mkt_fee(price)
    _mkt_route_fee(save, fee, f"moment {mo['name']} {mo['player']}")
    mo["minted"] = int(mo["minted"]) + 1
    label = f"{mo['player']} \u2014 {mo['name']}"
    _mkt_give(u, label, mo["minted"])
    _tvt_log(u, "moment", card=label, price=price, serial=mo["minted"])
    return {"moment": mo, "price": price, "serial": mo["minted"], "label": label}, None


# ═══════════════════════════════════════════════════════════════════════════
#  QTCG MARKET — Discord commands  (/qtcg market ...)
#
#  THIS PAIRS WITH THE OLD /qtcg CODE. It supersedes nothing. It reuses
#  _tvt_pool, _tvt_load_save, _tvt_get_user, _tvt_econ, _tvt_price, _tvt_log.
#
#  PASTE ORDER, all in QCL2K.py:
#      1. the existing /qtcg fantasy block          (unchanged)
#      2. qtcg_market.py                            (the engine)
#      3. THIS FILE                                 (commands + bridges)
#  It must come BEFORE  bot.tree.add_command(tvt_group)  — or just move that
#  line to the very bottom of this file. It's included at the end already.
#
#  ── THE TWO BRIDGES (read these) ───────────────────────────────────────────
#  Without them the old and new systems disagree and players will arbitrage it:
#
#   SUPPLY  /qtcg pack + /qtcg add mint against flat TVT_PRINT_RUN, while the
#           market advertises stat-driven _mkt_supply(). A Legendary with 8 GP
#           is 3 copies to the minter and 4 to the market. Bridge 1 makes
#           _mkt_supply the single source of truth.
#
#   PRICE   /qtcg add sells at the weekly formula while the market quotes
#           formula-blended-with-trades. Buy cheap from /qtcg add, flip on the
#           market. Bridge 2 makes /qtcg add pay the live market quote.
# ═══════════════════════════════════════════════════════════════════════════

# ── BRIDGE 1: one supply source ────────────────────────────────────────────
def _tvt_mint(save, player, tier):
    """OVERRIDES the original. Same signature, but the print run now comes
    from _mkt_supply() so minting and the market can never disagree."""
    run, _why = _mkt_supply(player)
    if run <= 0:
        return None                                   # unlimited -> no serial
    mint = save.setdefault("mint", {})
    minted = int(mint.get(player, 0))
    if minted >= run:
        return None                                   # sold out -> unnumbered
    global _tvt_market_dirty
    serial = minted + 1
    mint[player] = serial
    _tvt_market_dirty = True
    return serial


# ── BRIDGE 2: one price source ─────────────────────────────────────────────
def _tvt_price(save, player):
    """OVERRIDES the original. /qtcg add now pays the live market quote, so
    there's no gap to arbitrage between signing and flipping."""
    try:
        return int(_mkt_quote(save, player)["price"])
    except Exception:
        return int(_tvt_prices(save).get(player, 50))


# ── BRIDGE 3: the Hub sees the same numbers ────────────────────────────────
def _tvt_build_market(save):
    """OVERRIDES the original so fantasy_market.json matches the real supply."""
    mint = save.get("mint", {})
    m = _mkt_store(save)
    cards = {}
    for nm in _tvt_pool["names"]:
        run, _why = _mkt_supply(nm)
        if run <= 0:
            continue
        q = _mkt_quote(save, nm)
        cards[nm] = {"tier": _tvt_pool["rarity"].get(nm, "Common"),
                     "minted": int(mint.get(nm, 0)), "run": run,
                     "price": q["price"], "heat": q["heat"], "trades": q["n"]}
    return {"updated": int(_tvt_time.time()), "cards": cards,
            "moments": {k: {"name": v["name"], "player": v["player"],
                            "minted": v["minted"], "run": v["run"]}
                        for k, v in m["moments"].items()}}

# ═══════════════════════════════════════════════════════════════════════════
#  QTCG LEGACY / ACTIVE SPLIT  +  the BURN sink
#
#  PASTE: after qtcg_market.py, before the market commands. All _lgc_ / LGC_
#  prefixed, plus three deliberate overrides of existing functions.
#
#  ── THE TWO PROBLEMS THIS FIXES ────────────────────────────────────────────
#  1. DEAD POOL. /qtcg pack draws from every name in the sheet. Point the bot
#     at merged data and 352 retired players flood the pack pool — new users
#     open three guys who quit years ago.
#  2. NO SINK. Commons are unlimited and nothing ever leaves circulation.
#     ~18,700 cards/year in, zero out. Common prices go to the floor.
#
#  ── HOW ────────────────────────────────────────────────────────────────────
#  ACTIVE   played within the last LGC_ACTIVE_WINDOW seasons.
#           In the pack pool. Signable. Price tracks live stats.
#  LEGACY   hasn't. NOT printed anymore — supply is closed at whatever exists.
#           Market-only, and BURNABLE for power-up charges.
#
#  Nothing is ever auto-deleted. Burning is voluntary and explicit.
#  A retired player who comes back flips to ACTIVE again on the next refresh.
# ═══════════════════════════════════════════════════════════════════════════

LGC_ACTIVE_WINDOW = 2          # played within the last N seasons = active
LGC_SCARCITY_MAX = 2.5         # legacy price ceiling multiple vs formula

# How many LEGACY cards of a tier burn into ONE power-up charge.
LGC_BURN_COST = {"Common": 5, "Uncommon": 3, "Rare": 2, "Epic": 1, "Legendary": 1}


# ── OVERRIDE 1: teach the pool who's still playing ─────────────────────────
_lgc_orig_compute_pool = _tvt_compute_pool


def _tvt_compute_pool():
    """OVERRIDE. Same output plus 'last_season', 'gp' and 'era' per player."""
    pool = _lgc_orig_compute_pool()
    try:
        df = _tvt_pd.read_csv(TVT_SHEET_CSV)
        df.columns = df.columns.str.strip()
        nc = "Player/Team"
        t = df.get("Type", _tvt_pd.Series([""] * len(df))).astype(str).str.lower()
        p = df[~t.isin(["team", "total", "totals", "team total"])]
        p = p[~p[nc].astype(str).str.upper().str.endswith(("TOTAL", "TOTALS"))]
        p["Season"] = _tvt_pd.to_numeric(p.get("Season"), errors="coerce")
        p = p[p["Season"].notna()]
        last = p.groupby(nc)["Season"].max().to_dict()
        gp = p.groupby(nc)["Game_ID"].nunique().to_dict() if "Game_ID" in p.columns else {}
        pool["last_season"] = {str(k): float(v) for k, v in last.items()}
        pool["gp"] = {str(k): int(v) for k, v in gp.items()}
        pool["cur_season"] = float(max(last.values())) if last else 0.0
    except Exception as e:
        print(f"[QTCG legacy] activity scan failed ({e}) — everyone stays active")
        pool.setdefault("last_season", {})
        pool.setdefault("gp", {})
        pool.setdefault("cur_season", 0.0)
    return pool


def _lgc_class(player):
    """'active' | 'legacy'. Unknown players default to active, never legacy —
    guessing wrong here would silently delist someone from packs."""
    last = _tvt_pool.get("last_season", {}).get(str(player))
    cur = float(_tvt_pool.get("cur_season", 0) or 0)
    if last is None or cur <= 0:
        return "active"
    return "active" if (cur - float(last)) < LGC_ACTIVE_WINDOW else "legacy"


def _lgc_is_legacy(player):
    return _lgc_class(player) == "legacy"


def _lgc_active_names():
    return [n for n in _tvt_pool.get("names", []) if not _lgc_is_legacy(n)]


# ── OVERRIDE 2: packs only print ACTIVE players ────────────────────────────
def _tvt_draw_pack():
    """OVERRIDE. Legacy players are never printed again — that's what makes
    their supply closed and their price real."""
    live = _lgc_active_names()
    if not live:
        live = _tvt_pool.get("names", [])          # never hand back an empty pack
    buckets = {}
    for n in live:
        buckets.setdefault(_tvt_pool["rarity"].get(n, "Common"), []).append(n)
    out = []
    for _ in range(TVT_PACK_SIZE):
        roll = _mkt_random.random()
        cum, chosen = 0.0, "Common"
        for tier, odds in TVT_ODDS:
            cum += odds
            if roll <= cum:
                chosen = tier
                break
        bucket = buckets.get(chosen) or live
        if bucket:
            out.append(_mkt_random.choice(bucket))
    return out


# ── OVERRIDE 3: legacy supply is CLOSED, and priced on scarcity ────────────
_lgc_orig_supply = _mkt_supply


def _mkt_supply(player):
    """OVERRIDE. Legacy print runs freeze at whatever was already minted, so
    no new copies can ever enter circulation."""
    if not _lgc_is_legacy(player):
        return _lgc_orig_supply(player)
    save = _tvt_load_save()
    minted = int(save.get("mint", {}).get(player, 0))
    if minted <= 0:
        base = MKT_BASE_RUN.get(_tvt_pool["rarity"].get(player, "Common"), 0)
        return (0, "legacy \u00b7 unlimited tier, no serials") if base <= 0 \
            else (0, "legacy \u00b7 never printed")
    return minted, f"legacy \u00b7 supply closed at {minted}"


_lgc_orig_quote = _mkt_quote


def _mkt_quote(save, player):
    """OVERRIDE. Legacy cards get a scarcity premium — closed supply plus
    ongoing demand is the only thing holding them up."""
    q = _lgc_orig_quote(save, player)
    q["class"] = _lgc_class(player)
    if q["class"] != "legacy":
        return q
    minted = int(save.get("mint", {}).get(player, 0))
    if minted > 0:
        # 1 copy in existence -> 2.5x. 25 copies -> ~1.1x.
        mult = 1.0 + min(LGC_SCARCITY_MAX - 1.0, 6.0 / max(minted, 1))
    else:
        mult = 1.0
    burn = _lgc_burn_floor(player)
    q["legacy_mult"] = round(mult, 2)
    q["price"] = max(burn, int(round(q["price"] * mult)))
    q["floor"] = burn
    return q


def _lgc_burn_floor(player):
    """A legacy card can never be worth less than its share of a power-up
    charge, because somebody will always burn it instead of selling cheap."""
    tier = _tvt_pool["rarity"].get(player, "Common")
    n = LGC_BURN_COST.get(tier, 5)
    charge_value = int(TVT_PACK_COST * 1.5)        # a charge ~ 1.5 packs of value
    return max(MKT_MIN_PRICE, int(charge_value / max(n, 1)))


# ── THE BURN SINK ──────────────────────────────────────────────────────────
def _lgc_charges(u):
    return int(u.get("charges", 0))


def _lgc_burnable(u):
    """{tier: [player, ...]} of the legacy cards this user could burn."""
    out = {}
    for c in u.get("cards", []):
        if " \u2014 " in str(c):                  # Moment cards are never burnable
            continue
        if not _lgc_is_legacy(c):
            continue
        out.setdefault(_tvt_pool["rarity"].get(c, "Common"), []).append(c)
    return out


def _lgc_burn(save, uid, tier, charges=1):
    """Burn LGC_BURN_COST[tier] x `charges` legacy cards into power-up charges."""
    u = _tvt_get_user(save, uid)
    charges = max(1, int(charges))
    need = LGC_BURN_COST.get(tier)
    if need is None:
        return None, f"Unknown tier `{tier}`."
    total = need * charges
    have = _lgc_burnable(u).get(tier, [])
    if len(have) < total:
        return None, (f"Need **{total}** legacy {tier} card(s) for {charges} charge(s) "
                      f"\u2014 you have **{len(have)}**.")
    burned = []
    for name in have[:total]:
        ok, ser = _mkt_take(u, name)
        if ok:
            burned.append(name if ser is None else f"{name} #{ser}")
    u["charges"] = _lgc_charges(u) + charges
    _tvt_log(u, "burn", tier=tier, cards=burned, charges=charges)
    return {"burned": burned, "charges": charges, "total": u["charges"]}, None


def _lgc_spend_charge(save, uid, n=1):
    """Consume charges to actually equip a power-up. Charges are the FUEL;
    card power is the CAPACITY. You need both."""
    u = _tvt_get_user(save, uid)
    if _lgc_charges(u) < n:
        return False, (f"You need **{n}** power-up charge(s) \u2014 you have "
                       f"**{_lgc_charges(u)}**. Burn legacy cards with "
                       f"`/qtcg market burn`.")
    u["charges"] = _lgc_charges(u) - n
    return True, None


# ── OVERRIDE 4: legacy players can't be signed as free agents ──────────────
_lgc_orig_all_ac = _tvt_all_ac


async def _tvt_all_ac(interaction, current: str):
    """OVERRIDE. Autocomplete for /qtcg add only offers ACTIVE players —
    signing a legacy player would print a new copy and break closed supply."""
    await _tvt_ensure_pool()
    cur = (current or "").lower()
    return [_tvt_ac.Choice(name=n[:100], value=n[:100])
            for n in _lgc_active_names() if cur in n.lower()][:25]


# ── reporting ──────────────────────────────────────────────────────────────
def _lgc_split_summary():
    names = _tvt_pool.get("names", [])
    act = _lgc_active_names()
    leg = [n for n in names if n not in set(act)]
    by_tier = {}
    for n in leg:
        t = _tvt_pool["rarity"].get(n, "Common")
        by_tier[t] = by_tier.get(t, 0) + 1
    return {"total": len(names), "active": len(act), "legacy": len(leg),
            "legacy_by_tier": by_tier, "cur_season": _tvt_pool.get("cur_season", 0)}


# ═══════════════════════════════════════════════════════════════════════════
#  QTCG LEGEND SCORE — hardware beats hot streaks
#
#  PASTE: after qtcg_legacy.py, before the market commands. _lgd_ / LGD_ prefixed.
#
#  ── WHAT IT FIXES ──────────────────────────────────────────────────────────
#  1. TREND HAD NO TIME DECAY. "last 3 games" meant last 3 ROWS, whenever they
#     happened. A player whose last game was 8 days ago still showed +7.7 hot.
#  2. RARITY WAS 100% PIE. Championships, MVPs, All-League and roles carried
#     ZERO weight. A hot 3-game stretch moved your tier; three rings did not.
#  3. MOMENTS STOOD ALONE. A 50-Piece minted as its own card, competing with
#     player cards instead of attaching to one.
#
#  ── THE MODEL ──────────────────────────────────────────────────────────────
#     LEGEND = 40% peak performance + 20% longevity + 40% hardware
#
#  Hardware is the half that was missing. Three championships now outweigh any
#  three-game heater, which is the whole point.
#
#  Titles live in qtcg/titles.json so you edit a file, not code.
# ═══════════════════════════════════════════════════════════════════════════

LGD_TITLES_PATH = "qtcg/titles.json"
_LGD_CACHE = {"titles": None, "t": 0.0}

# What each piece of hardware is worth. A ring is the heaviest single item.
LGD_HARDWARE = {
    "championship":  10.0,
    "finals_mvp":     8.0,
    "mvp":            8.0,
    "opoy":           5.0,
    "dpoy":           5.0,
    "bpoy":           4.0,
    "6moy":           3.0,
    "breakout":       3.0,
    "mip":            3.0,
    "all_league_1st": 4.0,
    "all_league_2nd": 3.0,
    "all_league_3rd": 2.0,
    "all_defensive":  2.5,
    "hall_of_fame":  12.0,
    "top_10":         6.0,
    "top_25":         4.0,
    "top_50":         2.0,
    "top_75":         1.0,
}

LGD_W_PERF = 0.40      # peak play
LGD_W_LONG = 0.20      # longevity
LGD_W_HARD = 0.40      # trophy cabinet

# Trend halves every N "league games since you last played".
LGD_TREND_HALFLIFE = 6


def _lgd_titles():
    """qtcg/titles.json -> {player: {championship: 3, mvp: 1, top_50: 1, ...}}

    Local file first so it works offline; the bot can also commit it to GitHub.
    """
    now = _mkt_time.time()
    if _LGD_CACHE["titles"] is not None and now - _LGD_CACHE["t"] < 300:
        return _LGD_CACHE["titles"]
    data = {}
    try:
        path = _tvt_os.path.join(TVT_DATA_DIR, "titles.json")
        if _tvt_os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                data = _tvt_json.load(f) or {}
    except Exception as e:
        print(f"[QTCG legend] titles.json unreadable ({e})")
    _LGD_CACHE.update({"titles": data, "t": now})
    return data


def _lgd_hardware_points(player):
    """Raw trophy points for one player. Case/spacing tolerant."""
    t = _lgd_titles()
    rec = t.get(player)
    if rec is None:
        want = _tvt_slug(player)
        rec = next((v for k, v in t.items() if _tvt_slug(k) == want), None)
    if not isinstance(rec, dict):
        return 0.0, {}
    pts, detail = 0.0, {}
    for key, count in rec.items():
        k = str(key).strip().lower().replace(" ", "_").replace("-", "_")
        w = LGD_HARDWARE.get(k)
        if w is None:
            continue
        try:
            n = int(count)
        except (TypeError, ValueError):
            n = 1 if count else 0
        if n > 0:
            pts += w * n
            detail[k] = n
    return pts, detail


def _lgd_scores():
    """{player: {...}} for everyone in the pool. Cached with the pool refresh."""
    names = _tvt_pool.get("names", [])
    if not names:
        return {}
    stats = _tvt_pool.get("stats", {})
    gpmap = _tvt_pool.get("gp", {})

    perf_raw, long_raw, hard_raw = {}, {}, {}
    for n in names:
        st = stats.get(n, {})
        perf_raw[n] = float(st.get("PIE", st.get("PTS", 0)) or 0)
        long_raw[n] = float(gpmap.get(n, st.get("GP", 0)) or 0)
        hard_raw[n] = _lgd_hardware_points(n)[0]

    def pct(d):
        vals = sorted(d.values())
        m = len(vals)
        if m <= 1:
            return {k: 1.0 for k in d}
        out = {}
        for k, v in d.items():
            lo = sum(1 for x in vals if x < v)
            eq = sum(1 for x in vals if x == v)
            out[k] = (lo + eq / 2.0) / m
        return out

    # PIE percentile already exists in the pool; fall back to our own if not
    p_perf = {n: float(_tvt_pool.get("pct", {}).get(n, 0)) for n in names}
    if not any(p_perf.values()):
        p_perf = pct(perf_raw)
    p_long = pct(long_raw)

    # Hardware is NOT percentiled -- with few winners a percentile would crush
    # them toward the middle. Scale against the biggest cabinet in the league.
    top_hw = max(hard_raw.values()) if hard_raw else 0.0
    p_hard = {n: (hard_raw[n] / top_hw if top_hw > 0 else 0.0) for n in names}

    out = {}
    for n in names:
        score = (LGD_W_PERF * p_perf.get(n, 0)
                 + LGD_W_LONG * p_long.get(n, 0)
                 + LGD_W_HARD * p_hard.get(n, 0))
        out[n] = {"legend": round(score, 4), "perf": round(p_perf.get(n, 0), 3),
                  "long": round(p_long.get(n, 0), 3), "hard": round(p_hard.get(n, 0), 3),
                  "hw_points": hard_raw[n], "hw": _lgd_hardware_points(n)[1]}
    return out


# ── OVERRIDE: tier comes from LEGEND, not raw PIE ──────────────────────────
_lgd_orig_compute_pool = _tvt_compute_pool


def _tvt_compute_pool():
    """OVERRIDE. Re-tiers everyone on legend score and decays the trend."""
    pool = _lgd_orig_compute_pool()
    globals()["_tvt_pool"] = {**_tvt_pool, **pool}      # _lgd_scores reads the pool

    try:
        sc = _lgd_scores()
        if sc:
            ranked = sorted(sc.items(), key=lambda kv: kv[1]["legend"], reverse=True)
            m = len(ranked)
            buckets, rarity = {}, {}
            for i, (name, _v) in enumerate(ranked):
                p = 1.0 - (i / max(m - 1, 1))           # 1.0 = best
                for th, nm in TVT_THRESH:
                    if p >= th:
                        rarity[name] = nm
                        break
                else:
                    rarity[name] = "Common"
                buckets.setdefault(rarity[name], []).append(name)
            pool["rarity"] = rarity
            pool["buckets"] = buckets
            pool["legend"] = {k: v["legend"] for k, v in sc.items()}
            pool["legend_detail"] = sc
    except Exception as e:
        print(f"[QTCG legend] re-tier failed ({e}) — keeping PIE tiers")

    # ---- trend decay: cold players stop showing as hot ----
    try:
        gid = pool.get("last_game_id", {})
        cur_gid = max(gid.values()) if gid else 0
        for n, v in list(pool.get("trend", {}).items()):
            gap = max(0.0, float(cur_gid) - float(gid.get(n, cur_gid)))
            decay = 0.5 ** (gap / LGD_TREND_HALFLIFE)
            pool["trend"][n] = round(float(v) * decay, 2)
        pool["trend_decay_applied"] = True
    except Exception as e:
        print(f"[QTCG legend] trend decay failed ({e})")
    return pool


# ── OVERRIDE: record last game id so decay has something to measure ────────
_lgd_prev_pool_fn = _tvt_compute_pool


def _tvt_compute_pool():
    pool = _lgd_prev_pool_fn()
    try:
        df = _tvt_pd.read_csv(TVT_SHEET_CSV)
        df.columns = df.columns.str.strip()
        nc = "Player/Team"
        t = df.get("Type", _tvt_pd.Series([""] * len(df))).astype(str).str.lower()
        p = df[~t.isin(["team", "total", "totals", "team total"])]
        p = p[~p[nc].astype(str).str.upper().str.endswith(("TOTAL", "TOTALS"))]
        for c in ("Season", "Game_ID"):
            p[c] = _tvt_pd.to_numeric(p.get(c), errors="coerce")
        p = p[p["Game_ID"].notna()]
        # a single increasing number across seasons
        p["_ord"] = p["Season"].fillna(0) * 100000 + p["Game_ID"]
        pool["last_game_id"] = p.groupby(nc)["_ord"].max().to_dict()
    except Exception as e:
        print(f"[QTCG legend] last-game scan failed ({e})")
        pool.setdefault("last_game_id", {})
    return pool


# ── MOMENTS BECOME TICKETS, NOT CARDS ──────────────────────────────────────
#  A Moment no longer mints a standalone card that competes with player cards.
#  It attaches to that player's base card as a permanent boost + a power-up
#  charge. Two big nights should decorate a card, not outrank a 3-time champ.
LGD_MOMENT_BOOST = 0.5          # legend-equivalent bump a moment adds to a card
LGD_MOMENT_CHARGE = 1           # power-up charges granted on claim


def _lgd_moment_tickets(u):
    return u.setdefault("tickets", {})


def _mkt_claim_moment(save, uid, mid):
    """OVERRIDE. Claiming a Moment now grants a TICKET on the player's base
    card plus a power-up charge -- it does not mint a rival card."""
    m = _mkt_store(save)
    mo = m["moments"].get(mid)
    if not mo:
        return None, "No such moment."
    if int(mo["minted"]) >= int(mo["run"]):
        return None, f"**{mo['name']}** is sold out ({mo['run']}/{mo['run']})."
    u = _tvt_get_user(save, uid)

    if mo["player"] not in u.get("cards", []):
        return None, (f"You need **{mo['player']}**'s card first \u2014 a Moment "
                      f"attaches to the player you already own.")

    price = int(_mkt_quote(save, mo["player"])["price"] * 1.5)
    if u["coins"] < price:
        return None, f"Costs {price:,} coins \u2014 you have {u['coins']:,}."

    u["coins"] -= price
    fee, _net = _mkt_fee(price)
    _mkt_route_fee(save, fee, f"moment {mo['name']} {mo['player']}")
    mo["minted"] = int(mo["minted"]) + 1

    tickets = _lgd_moment_tickets(u)
    lst = tickets.setdefault(mo["player"], [])
    lst.append({"id": mid, "name": mo["name"], "serial": mo["minted"],
                "run": mo["run"], "season": mo["season"], "game": mo["game"],
                "boost": LGD_MOMENT_BOOST})
    u["charges"] = int(u.get("charges", 0)) + LGD_MOMENT_CHARGE
    _tvt_log(u, "moment_ticket", player=mo["player"], moment=mo["name"],
             serial=mo["minted"], price=price)
    return {"moment": mo, "price": price, "serial": mo["minted"],
            "attached_to": mo["player"], "charges": u["charges"],
            "tickets": len(lst)}, None


def _lgd_card_bonus(u, player):
    """Total moment boost riding on a player's card for this user."""
    return round(sum(t.get("boost", 0) for t in _lgd_moment_tickets(u).get(player, [])), 2)


# ── reporting ──────────────────────────────────────────────────────────────
def _lgd_explain(player):
    d = _tvt_pool.get("legend_detail", {}).get(player)
    if not d:
        return f"No legend data for **{player}** yet."
    hw = ", ".join(f"{k.replace('_',' ')} x{v}" for k, v in d["hw"].items()) or "none"
    return (f"**{player}** \u2014 legend **{d['legend']:.3f}** "
            f"({_tvt_pool['rarity'].get(player,'Common')})\n"
            f"\u2003\U0001f3c0 performance {d['perf']:.2f}  (x{LGD_W_PERF})\n"
            f"\u2003\u23f3 longevity   {d['long']:.2f}  (x{LGD_W_LONG})\n"
            f"\u2003\U0001f3c6 hardware    {d['hard']:.2f}  (x{LGD_W_HARD})  "
            f"\u2014 {d['hw_points']:.0f} pts: {hw}")

# ═══════════════════════════  COMMANDS  ═══════════════════════════
mkt_group = _tvt_ac.Group(name="market", description="Buy, sell and auction cards",
                          parent=tvt_group)


def _mkt_fmt(c):
    return f"{int(c):,}"


async def _mkt_my_cards_ac(interaction: _tvt_discord.Interaction, current: str):
    save = _tvt_load_save()
    u = save["users"].get(str(interaction.user.id), {})
    cur = (current or "").lower()
    seen = sorted(set(u.get("cards", [])))
    return [_tvt_ac.Choice(name=n[:100], value=n[:100]) for n in seen if cur in n.lower()][:25]


async def _mkt_listing_ac(interaction: _tvt_discord.Interaction, current: str):
    save = _tvt_load_save()
    m = _mkt_store(save)
    cur = (current or "").lower()
    out = []
    for l in m["listings"].values():
        if not l["open"]:
            continue
        lbl = f"{l['id']} \u00b7 {l['player']} \u00b7 {_mkt_fmt(l['price'])}c"
        if cur in lbl.lower():
            out.append(_tvt_ac.Choice(name=lbl[:100], value=l["id"]))
    return out[:25]


async def _mkt_auction_ac(interaction: _tvt_discord.Interaction, current: str):
    save = _tvt_load_save()
    m = _mkt_store(save)
    now = int(_mkt_time.time())
    cur = (current or "").lower()
    out = []
    for a in m["auctions"].values():
        if not a["open"] or now >= a["ends"]:
            continue
        cur_bid = a["bid"] or a["start"]
        lbl = f"{a['id']} \u00b7 {a['player']} \u00b7 {_mkt_fmt(cur_bid)}c"
        if cur in lbl.lower():
            out.append(_tvt_ac.Choice(name=lbl[:100], value=a["id"]))
    return out[:25]


async def _mkt_moment_ac(interaction: _tvt_discord.Interaction, current: str):
    save = _tvt_load_save()
    m = _mkt_store(save)
    cur = (current or "").lower()
    out = []
    for mo in m["moments"].values():
        left = int(mo["run"]) - int(mo["minted"])
        if left <= 0:
            continue
        lbl = f"{mo['player']} \u2014 {mo['name']} ({left} left)"
        if cur in lbl.lower():
            out.append(_tvt_ac.Choice(name=lbl[:100], value=mo["id"][:100]))
    return out[:25]


@mkt_group.command(name="browse", description="See what's for sale and what's up for auction")
async def mkt_browse(interaction: _tvt_discord.Interaction):
    await interaction.response.defer(thinking=True)
    await _tvt_ensure_pool()
    save = _tvt_load_save()
    _mkt_auction_close(save)                          # settle anything expired
    _tvt_write_save(save)
    m = _mkt_store(save)
    now = int(_mkt_time.time())

    listings = sorted([l for l in m["listings"].values() if l["open"]],
                      key=lambda x: x["price"])[:12]
    auctions = sorted([a for a in m["auctions"].values() if a["open"] and now < a["ends"]],
                      key=lambda x: x["ends"])[:8]

    emb = _tvt_discord.Embed(title="\U0001f3ea QTCG Market", color=0xD4AF37,
                             description=f"League fee **{int(MKT_FEE_PCT*100)}%** on every sale.")
    if listings:
        lines = []
        for l in listings:
            q = _mkt_quote(save, l["player"])
            tag = "\U0001f7e2" if l["price"] <= q["price"] else "\U0001f534"
            ser = f" #{l['serial']}" if l.get("serial") else ""
            lines.append(f"{tag} `{l['id']}` **{l['player']}**{ser} \u2014 "
                         f"**{_mkt_fmt(l['price'])}**c _(quote {_mkt_fmt(q['price'])})_")
        emb.add_field(name="\U0001f4b0 For sale", value="\n".join(lines)[:1024], inline=False)
    else:
        emb.add_field(name="\U0001f4b0 For sale", value="_nothing listed_", inline=False)

    if auctions:
        lines = []
        for a in auctions:
            mins = max(0, (a["ends"] - now) // 60)
            cur_bid = a["bid"] or a["start"]
            who = " (no bids)" if not a["bid"] else ""
            lines.append(f"\u23f1\ufe0f `{a['id']}` **{a['player']}** \u2014 "
                         f"**{_mkt_fmt(cur_bid)}**c{who} \u00b7 {mins}m left")
        emb.add_field(name="\U0001f528 Auctions", value="\n".join(lines)[:1024], inline=False)

    live = [mo for mo in m["moments"].values() if int(mo["minted"]) < int(mo["run"])]
    if live:
        lines = [f"\u2728 **{mo['player']} \u2014 {mo['name']}** "
                 f"({int(mo['run'])-int(mo['minted'])}/{mo['run']} left)"
                 for mo in sorted(live, key=lambda x: -x["created"])[:5]]
        emb.add_field(name="\U0001f4a5 Moment drops", value="\n".join(lines)[:1024], inline=False)

    emb.set_footer(text="\U0001f7e2 under quote \u00b7 \U0001f534 over quote. "
                        "/qtcg market buy \u00b7 sell \u00b7 bid \u00b7 claim")
    await interaction.followup.send(embed=emb)

# ═══════════════════════════════════════════════════════════════════════════
#  QTCG ADMIN — live tuning, titles, rankings, manual overrides
#
#  PASTE: after qtcg_legend.py. All _adm_ / ADM_ prefixed.
#
#  ── WHY ────────────────────────────────────────────────────────────────────
#  Every ranking knob is currently a code constant: LGD_W_HARD, TVT_THRESH,
#  MKT_BASE_RUN, LGC_ACTIVE_WINDOW... Tuning them means editing Python and
#  restarting the bot, on a 23k-line file, live, with players mid-season.
#
#  This moves them all into fantasy_data/tuning.json, loaded on every pool
#  refresh. Code constants stay as defaults. Nothing to restart.
#
#  ── THE RULE ───────────────────────────────────────────────────────────────
#  Every change PREVIEWS before it commits. You see the new top 10 and exactly
#  who moved, then decide. Never re-rank a live league blind.
# ═══════════════════════════════════════════════════════════════════════════

ADM_TUNING_PATH = _tvt_os.path.join(TVT_DATA_DIR, "tuning.json")
ADM_TITLES_PATH = _tvt_os.path.join(TVT_DATA_DIR, "titles.json")

# Everything adjustable, with the code constant as the default.
ADM_DEFAULTS = {
    "w_perf": LGD_W_PERF,             # weight: peak performance
    "w_long": LGD_W_LONG,             # weight: longevity
    "w_hard": LGD_W_HARD,             # weight: trophy cabinet
    "trend_halflife": LGD_TREND_HALFLIFE,
    "active_window": LGC_ACTIVE_WINDOW,
    "legendary_pct": 0.95,            # tier cutoffs on the legend curve
    "epic_pct": 0.85,
    "rare_pct": 0.65,
    "uncommon_pct": 0.35,
    "moment_boost": LGD_MOMENT_BOOST,
    "fee_pct": MKT_FEE_PCT,
}

_ADM_CACHE = {"cfg": None, "t": 0.0}


def _adm_cfg(force=False):
    now = _mkt_time.time()
    if _ADM_CACHE["cfg"] is not None and not force and now - _ADM_CACHE["t"] < 30:
        return _ADM_CACHE["cfg"]
    cfg = dict(ADM_DEFAULTS)
    try:
        if _tvt_os.path.exists(ADM_TUNING_PATH):
            with open(ADM_TUNING_PATH, "r", encoding="utf-8") as f:
                cfg.update({k: v for k, v in (_tvt_json.load(f) or {}).items()
                            if k in ADM_DEFAULTS})
    except Exception as e:
        print(f"[QTCG admin] tuning.json unreadable ({e}) — using defaults")
    _ADM_CACHE.update({"cfg": cfg, "t": now})
    return cfg


def _adm_cfg_save(cfg):
    tmp = ADM_TUNING_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        _tvt_json.dump(cfg, f, indent=2)
    _tvt_os.replace(tmp, ADM_TUNING_PATH)
    _ADM_CACHE.update({"cfg": cfg, "t": _mkt_time.time()})


def _adm_titles_save(t):
    tmp = ADM_TITLES_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        _tvt_json.dump(t, f, indent=2)
    _tvt_os.replace(tmp, ADM_TITLES_PATH)
    _LGD_CACHE.update({"titles": t, "t": _mkt_time.time()})


# ── the board, computed from any weight set (used for BOTH live and preview) ──
def _adm_board(w_perf=None, w_long=None, w_hard=None, titles=None, limit=None):
    """Rank everyone under a given weight set. Never mutates anything."""
    cfg = _adm_cfg()
    w_perf = cfg["w_perf"] if w_perf is None else w_perf
    w_long = cfg["w_long"] if w_long is None else w_long
    w_hard = cfg["w_hard"] if w_hard is None else w_hard

    names = _tvt_pool.get("names", [])
    if not names:
        return []
    stats = _tvt_pool.get("stats", {})
    gpmap = _tvt_pool.get("gp", {})
    saved = None
    if titles is not None:                      # preview a titles edit safely
        saved = _LGD_CACHE.get("titles")
        _LGD_CACHE["titles"] = titles

    try:
        perf = {n: float(_tvt_pool.get("pct", {}).get(n, 0) or 0) for n in names}
        if not any(perf.values()):
            raw = {n: float(stats.get(n, {}).get("PIE", 0) or 0) for n in names}
            vals = sorted(raw.values())
            perf = {n: (sum(1 for x in vals if x < v) + 0.5) / max(len(vals), 1)
                    for n, v in raw.items()}
        lraw = {n: float(gpmap.get(n, stats.get(n, {}).get("GP", 0)) or 0) for n in names}
        lv = sorted(lraw.values())
        longv = {n: (sum(1 for x in lv if x < v) + 0.5) / max(len(lv), 1)
                 for n, v in lraw.items()}
        hraw = {n: _lgd_hardware_points(n)[0] for n in names}
        top = max(hraw.values()) if hraw else 0
        hard = {n: (hraw[n] / top if top > 0 else 0.0) for n in names}

        rows = []
        for n in names:
            L = w_perf * perf[n] + w_long * longv[n] + w_hard * hard[n]
            rows.append({"name": n, "legend": round(L, 4), "perf": round(perf[n], 3),
                         "long": round(longv[n], 3), "hard": round(hard[n], 3),
                         "hw_pts": hraw[n], "hw": _lgd_hardware_points(n)[1]})
    finally:
        if saved is not None:
            _LGD_CACHE["titles"] = saved

    rows.sort(key=lambda r: -r["legend"])
    m = len(rows)
    cuts = [(cfg["legendary_pct"], "Legendary"), (cfg["epic_pct"], "Epic"),
            (cfg["rare_pct"], "Rare"), (cfg["uncommon_pct"], "Uncommon"), (0.0, "Common")]
    for i, r in enumerate(rows):
        p = 1.0 - (i / max(m - 1, 1))
        r["rank"] = i + 1
        r["tier"] = next(nm for th, nm in cuts if p >= th)
    return rows[:limit] if limit else rows


def _adm_diff(before, after, top=12):
    """Who moved, and by how much. This is what you look at before committing."""
    b = {r["name"]: r for r in before}
    moves = []
    for r in after:
        old = b.get(r["name"])
        if not old:
            continue
        d = old["rank"] - r["rank"]
        if d or old["tier"] != r["tier"]:
            moves.append((abs(d), d, r["name"], old["rank"], r["rank"],
                          old["tier"], r["tier"]))
    moves.sort(reverse=True)
    return moves[:top]


def _adm_fmt_moves(moves):
    if not moves:
        return "_nobody moved._"
    out = []
    for _mag, d, name, r0, r1, t0, t1 in moves:
        arrow = "\u2191" if d > 0 else "\u2193" if d < 0 else "\u2192"
        tier = f"  {t0}\u2192**{t1}**" if t0 != t1 else ""
        out.append(f"{arrow} **{name}** #{r0}\u2192#{r1}{tier}")
    return "\n".join(out)


# ═══════════════════════════  COMMANDS  ═══════════════════════════
adm_group = _tvt_ac.Group(name="admin", description="Tune rankings and adjust cards",
                          parent=tvt_group)


def _adm_ok(interaction):
    if TVT_ADMIN_IDS and str(interaction.user.id) not in TVT_ADMIN_IDS:
        return False
    return True


@adm_group.command(name="rankings", description="The legend board with full breakdown")
@_tvt_ac.describe(top="How many to show", player="Or explain one player")
@_tvt_ac.autocomplete(player=_tvt_all_ac)
async def adm_rankings(interaction: _tvt_discord.Interaction, top: int = 15,
                       player: str = None):
    await interaction.response.defer(thinking=True)
    await _tvt_ensure_pool()
    if player:
        rows = _adm_board()
        r = next((x for x in rows if x["name"] == player), None)
        if not r:
            return await interaction.followup.send(f"\u274c No data for **{player}**.")
        cfg = _adm_cfg()
        hw = ", ".join(f"{k.replace('_',' ')} x{v}" for k, v in r["hw"].items()) or "none"
        emb = _tvt_discord.Embed(
            title=f"\U0001f4d0 {player}", color=TVT_COLOR.get(r["tier"], 0x8a929c),
            description=f"**#{r['rank']}** of {len(rows)}  \u00b7  **{r['tier']}**  "
                        f"\u00b7  legend **{r['legend']:.3f}**")
        emb.add_field(name=f"\U0001f3c0 Performance (x{cfg['w_perf']})",
                      value=f"{r['perf']:.3f}", inline=True)
        emb.add_field(name=f"\u23f3 Longevity (x{cfg['w_long']})",
                      value=f"{r['long']:.3f}", inline=True)
        emb.add_field(name=f"\U0001f3c6 Hardware (x{cfg['w_hard']})",
                      value=f"{r['hard']:.3f} \u2014 {r['hw_pts']:.0f} pts", inline=True)
        emb.add_field(name="Cabinet", value=hw, inline=False)
        return await interaction.followup.send(embed=emb)

    rows = _adm_board(limit=max(3, min(30, top)))
    cfg = _adm_cfg()
    lines = []
    for r in rows:
        hw = f" \U0001f3c6{r['hw_pts']:.0f}" if r["hw_pts"] else ""
        lines.append(f"`{r['rank']:2d}` **{r['name']}** \u2014 {r['legend']:.3f} "
                     f"\u00b7 {r['tier']}{hw}")
    emb = _tvt_discord.Embed(title="\U0001f4d0 Legend Board", color=0xD4AF37,
                             description="\n".join(lines)[:4000])
    emb.set_footer(text=f"perf {cfg['w_perf']} \u00b7 longevity {cfg['w_long']} \u00b7 "
                        f"hardware {cfg['w_hard']}  \u2014  /qtcg admin tune to change")
    await interaction.followup.send(embed=emb)


@adm_group.command(name="tune", description="Change a ranking weight — previews before it commits")
@_tvt_ac.describe(setting="Which knob", value="New value", apply="Commit it (default: preview only)")
@_tvt_ac.choices(setting=[_tvt_ac.Choice(name=k, value=k) for k in ADM_DEFAULTS])
async def adm_tune(interaction: _tvt_discord.Interaction,
                   setting: _tvt_ac.Choice[str] = None,
                   value: float = None, apply: bool = False):
    if not _adm_ok(interaction):
        return await interaction.response.send_message("Admins only.", ephemeral=True)
    await interaction.response.defer(thinking=True)
    await _tvt_ensure_pool()
    cfg = _adm_cfg(force=True)

    if setting is None or value is None:
        lines = [f"`{k}` = **{cfg[k]}**" + (f"  _(default {ADM_DEFAULTS[k]})_"
                 if cfg[k] != ADM_DEFAULTS[k] else "") for k in ADM_DEFAULTS]
        emb = _tvt_discord.Embed(title="\u2699\ufe0f Tuning", color=0xD4AF37,
                                 description="\n".join(lines))
        emb.set_footer(text="/qtcg admin tune setting:<knob> value:<n>  \u2014 previews first")
        return await interaction.followup.send(embed=emb)

    key = setting.value
    before = _adm_board()
    new = dict(cfg)
    new[key] = value
    after = _adm_board(w_perf=new["w_perf"], w_long=new["w_long"], w_hard=new["w_hard"]) \
        if key.startswith("w_") else None

    if after is None:
        # non-weight knobs don't reshuffle the board; just confirm and store
        if apply:
            _adm_cfg_save(new)
            return await interaction.followup.send(
                f"\u2705 `{key}` **{cfg[key]}** \u2192 **{value}**. Takes effect on the "
                f"next pool refresh (\u2264{TVT_POOL_TTL//60} min).")
        return await interaction.followup.send(
            f"`{key}` would go **{cfg[key]}** \u2192 **{value}**.\n"
            f"Re-run with `apply: True` to commit.")

    moves = _adm_diff(before, after)
    tot = sum(1 for a, b in zip(before, after) if a["name"] != b["name"])
    emb = _tvt_discord.Embed(
        title=("\u2705 Applied" if apply else "\U0001f441\ufe0f Preview"),
        color=(0x2ecc71 if apply else 0xffcc00),
        description=f"`{key}`  **{cfg[key]}** \u2192 **{value}**\n"
                    f"{tot} position(s) change.")
    emb.add_field(name="Biggest moves", value=_adm_fmt_moves(moves)[:1024], inline=False)
    emb.add_field(name="New top 5",
                  value="\n".join(f"`{r['rank']}` **{r['name']}** {r['legend']:.3f} "
                                  f"\u00b7 {r['tier']}" for r in after[:5]), inline=False)
    if apply:
        _adm_cfg_save(new)
        emb.set_footer(text=f"Live within {TVT_POOL_TTL//60} min.")
    else:
        emb.set_footer(text="Nothing changed. Re-run with apply: True to commit.")
    await interaction.followup.send(embed=emb)


@adm_group.command(name="title", description="Add or remove hardware for a player")
@_tvt_ac.describe(player="Who", award="What", count="How many (0 removes it)",
                  apply="Commit it (default: preview only)")
@_tvt_ac.autocomplete(player=_tvt_all_ac)
@_tvt_ac.choices(award=[_tvt_ac.Choice(name=k.replace("_", " ").title(), value=k)
                        for k in list(LGD_HARDWARE)[:25]])
async def adm_title(interaction: _tvt_discord.Interaction, player: str,
                    award: _tvt_ac.Choice[str], count: int = 1, apply: bool = False):
    if not _adm_ok(interaction):
        return await interaction.response.send_message("Admins only.", ephemeral=True)
    await interaction.response.defer(thinking=True)
    await _tvt_ensure_pool()

    titles = dict(_lgd_titles())
    rec = dict(titles.get(player, {}))
    old = int(rec.get(award.value, 0))
    if count <= 0:
        rec.pop(award.value, None)
    else:
        rec[award.value] = int(count)
    new_titles = dict(titles)
    if rec:
        new_titles[player] = rec
    else:
        new_titles.pop(player, None)

    before = _adm_board()
    after = _adm_board(titles=new_titles)
    b = next((r for r in before if r["name"] == player), None)
    a = next((r for r in after if r["name"] == player), None)

    emb = _tvt_discord.Embed(
        title=("\u2705 Cabinet updated" if apply else "\U0001f441\ufe0f Preview"),
        color=(0x2ecc71 if apply else 0xffcc00),
        description=f"**{player}** \u2014 {award.name}: **{old}** \u2192 **{max(count,0)}**")
    if b and a:
        tier = f"  {b['tier']}\u2192**{a['tier']}**" if b["tier"] != a["tier"] else ""
        emb.add_field(name="Effect on this player",
                      value=f"#{b['rank']} \u2192 **#{a['rank']}**{tier}\n"
                            f"hardware {b['hw_pts']:.0f} \u2192 **{a['hw_pts']:.0f}** pts\n"
                            f"legend {b['legend']:.3f} \u2192 **{a['legend']:.3f}**",
                      inline=False)
    moves = [m for m in _adm_diff(before, after) if m[2] != player]
    if moves:
        emb.add_field(name="Knock-on effects", value=_adm_fmt_moves(moves[:6])[:1024],
                      inline=False)
    if apply:
        _adm_titles_save(new_titles)
        emb.set_footer(text=f"Saved. Live within {TVT_POOL_TTL//60} min.")
    else:
        emb.set_footer(text="Nothing saved. Re-run with apply: True to commit.")
    await interaction.followup.send(embed=emb)


