    emb.add_field(name="Tier", value=(r["tier"] if r else "?"), inline=True)
    emb.add_field(name="Rank", value=(f"#{r['rank']}" if r else "?"), inline=True)
    emb.add_field(name="Price", value=f"{q['price']:,}c", inline=True)
    emb.add_field(name="Formula", value=f"{q['fair']:,}c", inline=True)
    emb.add_field(name="Heat", value=f"{q['heat']}x ({q['n']} trades)", inline=True)
