@mkt_group.command(name="scan", description="Scan the sheet for new Moment drops (admin)")
async def mkt_scan_cmd(interaction: _tvt_discord.Interaction):
    if TVT_ADMIN_IDS and str(interaction.user.id) not in TVT_ADMIN_IDS:
        return await interaction.response.send_message("Admins only.", ephemeral=True)
    await interaction.response.defer(thinking=True)

    def _pull():
        df = _tvt_pd.read_csv(TVT_SHEET_CSV)
        df.columns = df.columns.str.strip()
        t = df.get("Type", _tvt_pd.Series([""] * len(df))).astype(str).str.lower()
        df = df[~t.isin(["team", "total", "totals", "team total"])]
        for c in ("PTS", "REB", "AST", "STL", "BLK", "3PM", "Game_ID", "Season"):
            if c in df.columns:
                df[c] = _tvt_pd.to_numeric(df[c], errors="coerce").fillna(0)
        return df.to_dict("records")

    rows = await _tvt_asyncio.get_event_loop().run_in_executor(None, _pull)
    save = _tvt_load_save()
    minted = _mkt_scan_moments(save, rows)
    _tvt_write_save(save)
    if not minted:
        return await interaction.followup.send("No new moments \u2014 every qualifying game is already minted.")
    emb = _tvt_discord.Embed(title=f"\U0001f4a5 {len(minted)} new Moment drop(s)", color=0xf1c40f)
    for mo in minted[:15]:
        sl = mo["stat_line"]
        emb.add_field(name=f"{mo['player']} \u2014 {mo['name']}",
                      value=f"S{mo['season']} G{mo['game']} \u00b7 "
                            f"{int(sl.get('PTS',0))}p/{int(sl.get('REB',0))}r/"
                            f"{int(sl.get('AST',0))}a \u00b7 run of {mo['run']}",
                      inline=True)
    if len(minted) > 15:
        emb.set_footer(text=f"\u2026and {len(minted)-15} more")
    await interaction.followup.send(embed=emb)


