@_tvt_tasks.loop(minutes=2)
async def _mkt_auction_loop():
    try:
        save = _tvt_load_save()
        done = _mkt_auction_close(save)
        if done:
            _tvt_write_save(save)
            for d in done:
                a = d["auction"]
                print(f"[QTCG market] auction {a['id']} {d['result']} "
                      f"{a['player']} @ {a.get('bid', 0)}c")
    except Exception as e:
        print(f"[QTCG market] auction loop: {e}")


