# ═══════════════════════════════════════════════════════════════════════════
#  /award card  —  post a player card; the bot pulls the winner's stats,
#  commits the image to SPAM_HUB/cards/, and records the stat line.
#
#  Reads names straight from the RAW stat sheet (the exact "Player/Team" values
#  the Hub shows, e.g. "II WHEEL II") — NOT your scrubbed load_data names — so
#  the dropdown always matches the site.
#
#  - Player dropdown = exact raw sheet names only.
#  - "award" is OPTIONAL. Blank = a BASE card for that player (the card the
#    QTCG binder shows). Fill it in for an award card (MVP, OPOY, ...).
#
#  WHERE TO PASTE: after your groups are added. Needs: bot, award_group,
#  aiohttp, pandas (pd). Defines the shared GitHub helpers (_gh_*) used by the
#  other /award, /addlogo, /teamset, /allleague blocks — keep it FIRST.
#  ONE-TIME SETUP: .env -> GITHUB_TOKEN=github_pat_xxxxxxxx  (and SHEET_ID if
#  yours differs from the default).
# ═══════════════════════════════════════════════════════════════════════════

import base64      # noqa: E402
import asyncio     # noqa: E402
import time as _award_time  # noqa: E402

GH_TOKEN  = os.environ.get("GITHUB_TOKEN", "")
GH_REPO   = os.environ.get("GITHUB_REPO", "jburnett1291-dot/SPAM_HUB")
GH_BRANCH = os.environ.get("GITHUB_BRANCH", "main")
GH_CARDS  = os.environ.get("CARDS_PATH", "cards")
GH_API    = "https://api.github.com"
_GH_OK_EXT = (".png", ".jpg", ".jpeg", ".webp", ".gif")

_AWARD_SHEET_ID = os.environ.get("SHEET_ID", "1rksLYUcXQJ03uTacfIBD6SRsvtH-IE6djqT-LINwcH4")
_AWARD_SHEET_CSV = os.environ.get(
    "QCL_CSV_URL", f"https://docs.google.com/spreadsheets/d/{_AWARD_SHEET_ID}/export?format=csv")


def _gh_headers():
    return {"Authorization": f"Bearer {GH_TOKEN}", "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "QSPN-award-card"}


def _gh_slug(s):
    return re.sub(r"[^A-Za-z0-9]+", "_", str(s or "")).strip("_") or "card"


async def _gh_fetch(session, path):
    url = f"{GH_API}/repos/{GH_REPO}/contents/{path}"
    async with session.get(url, params={"ref": GH_BRANCH}, headers=_gh_headers()) as r:
        if r.status == 200:
            d = await r.json()
            txt = None
            if isinstance(d, dict) and d.get("content"):
                try:
                    txt = base64.b64decode(d["content"]).decode("utf-8")
                except Exception:
                    txt = None
            return (d.get("sha") if isinstance(d, dict) else None), txt
        return None, None


async def _gh_put(session, path, content_b64, message, sha=None):
    url = f"{GH_API}/repos/{GH_REPO}/contents/{path}"
    payload = {"message": message, "content": content_b64, "branch": GH_BRANCH}
    if sha:
        payload["sha"] = sha
    async with session.put(url, json=payload, headers=_gh_headers()) as r:
        try:
            body = await r.json()
        except Exception:
            body = {}
        return r.status, body


async def _gh_list_dir(session, path):
    url = f"{GH_API}/repos/{GH_REPO}/contents/{path}"
    async with session.get(url, params={"ref": GH_BRANCH}, headers=_gh_headers()) as r:
        if r.status == 200:
            j = await r.json()
            if isinstance(j, list):
                return [{"name": it.get("name"), "sha": it.get("sha")}
                        for it in j if isinstance(it, dict)]
        return []


async def _gh_delete(session, path, sha, message):
    url = f"{GH_API}/repos/{GH_REPO}/contents/{path}"
    payload = {"message": message, "sha": sha, "branch": GH_BRANCH}
    async with session.delete(url, json=payload, headers=_gh_headers()) as r:
        return r.status


# ---- RAW sheet reader (exact names, same source as the Hub) ----
_AWARD_SHEET = {"t": 0.0, "df": None}
_AWARD_NAMES = {"t": 0.0, "names": []}


def _award_sheet_df():
    now = _award_time.time()
    if _AWARD_SHEET["df"] is not None and (now - _AWARD_SHEET["t"] < 300):
        return _AWARD_SHEET["df"]
    try:
        df = pd.read_csv(_AWARD_SHEET_CSV)
        df.columns = df.columns.str.strip()
        _AWARD_SHEET.update({"t": now, "df": df})
    except Exception:
        pass
    return _AWARD_SHEET["df"]


def _award_names(df):
    col = df["Player/Team"]
    if hasattr(col, "columns"):        # guard against duplicate header
        col = col.iloc[:, 0]
    col = col.astype(str)
    typ = df.get("Type", pd.Series([""] * len(df))).astype(str).str.lower()
    is_team = typ.isin(["team", "total", "totals", "team total"]) | col.str.upper().str.endswith("TOTALS")
    out = set()
    for v in col[~is_team].tolist():
        s = str(v).strip()
        if s and s not in ("0", "Player/Team", "nan"):
            out.add(s)
    return sorted(out)


async def _award_player_ac(interaction: discord.Interaction, current: str):
    now = _award_time.time()
    if not _AWARD_NAMES["names"] or (now - _AWARD_NAMES["t"] > 300):
        try:
            loop = asyncio.get_event_loop()
            df = await loop.run_in_executor(None, _award_sheet_df)
            if df is not None:
                _AWARD_NAMES.update({"t": now, "names": _award_names(df)})
        except Exception:
            pass
    cur = (current or "").lower()
    return [app_commands.Choice(name=n[:100], value=n[:100])
            for n in _AWARD_NAMES["names"] if cur in n.lower()][:25]


def _award_player_line(player, season=None):
    """Averages off the RAW sheet, matched on the exact 'Player/Team' name."""
    df = _award_sheet_df()
    if df is None or getattr(df, "empty", True):
        return None
    col = df["Player/Team"]
    if hasattr(col, "columns"):
        col = col.iloc[:, 0]
    pp = df[col.astype(str) == str(player)]
    if season and "Season" in pp.columns:
        pp = pp[pd.to_numeric(pp["Season"], errors="coerce") == int(season)]
    if pp.empty:
        return None

    def m(c):
        return float(pd.to_numeric(pp[c], errors="coerce").mean()) if c in pp.columns else 0.0

    gp = int(pp["Game_ID"].nunique()) if "Game_ID" in pp.columns else len(pp)
    pts, reb, ast = m("PTS"), m("REB"), m("AST")
    stl, blk, tpm = m("STL"), m("BLK"), m("3PM")
    team = ""
    if "Team Name" in pp.columns and pp["Team Name"].notna().any():
        team = str(pp["Team Name"].dropna().iloc[-1])
    ext = (f"{pts:.1f} PPG \u2022 {reb:.1f} RPG \u2022 {ast:.1f} APG "
           f"\u2022 {(stl + blk):.1f} STK \u2022 {tpm:.1f} 3PM")
    return {"gp": gp, "team": team, "pts": pts, "reb": reb, "ast": ast,
            "stl": stl, "blk": blk, "tpm": tpm, "stats": ext}


@award_group.command(name="card",
                     description="Post a player card (leave award blank for a base card)")
@app_commands.describe(
    image="The card image (PNG / JPG / WEBP)",
    player="Player \u2014 pick an exact name from the sheet",
    award="Award or label (OPTIONAL) \u2014 blank = a plain base card",
    season="Season number (optional)",
    overwrite="Replace this player's existing card for this award/season",
)
@app_commands.autocomplete(player=_award_player_ac)
async def award_card(interaction: discord.Interaction,
                     image: discord.Attachment,
                     player: str,
                     award: str = None,
                     season: int = None,
                     overwrite: bool = False):
    await interaction.response.defer(thinking=True)

    if not GH_TOKEN:
        return await interaction.followup.send("\u274c No `GITHUB_TOKEN` in the bot's .env.")
    if not (image.content_type or "").startswith("image/"):
        return await interaction.followup.send("\u274c That attachment isn't an image.")

    line = _award_player_line(player, season)
    if line is None:
        return await interaction.followup.send(
            f"\u26a0\ufe0f **{player}** isn't on the stat sheet"
            + (f" for Season {season}" if season else "")
            + ". Pick the exact name from the dropdown.")

    ext = os.path.splitext(image.filename)[1].lower()
    if ext not in _GH_OK_EXT:
        ext = ".png"
    if award:
        stem = f"{_gh_slug(award)}_{_gh_slug(player)}" + (f"_s{season}" if season else "")
    else:
        stem = f"{_gh_slug(player)}" + (f"_s{season}" if season else "")
    new_name = f"{stem}{ext}"
    new_path = f"{GH_CARDS}/{new_name}"

    raw = await image.read()
    content_b64 = base64.b64encode(raw).decode("utf-8")

    async with aiohttp.ClientSession() as session:
        existing = None
        for it in await _gh_list_dir(session, GH_CARDS):
            nm = it.get("name") or ""
            if nm.lower().endswith(_GH_OK_EXT) and os.path.splitext(nm)[0] == stem:
                existing = it
                break
        if existing and not overwrite:
            return await interaction.followup.send(
                f"\u26a0\ufe0f A card already exists for this (`{existing['name']}`). "
                "Re-run with **overwrite: True** to update it.")

        put_sha = existing["sha"] if (existing and existing["name"] == new_name) else None
        status, body = await _gh_put(session, new_path, content_b64,
                                     f"{'Update' if existing else 'Add'} card: {award or 'base'} - {player}",
                                     sha=put_sha)
        if status not in (200, 201):
            detail = body.get("message", body) if isinstance(body, dict) else body
            return await interaction.followup.send(f"\u274c GitHub rejected the image ({status}): {detail}")

        replaced_note = ""
        if existing and existing["name"] != new_name:
            try:
                await _gh_delete(session, f"{GH_CARDS}/{existing['name']}",
                                 existing["sha"], f"remove old card: {player}")
                replaced_note = f" (replaced `{existing['name']}`)"
            except Exception:
                pass

        try:
            meta_path = f"{GH_CARDS}/meta.json"
            msha, mtext = await _gh_fetch(session, meta_path)
            meta = {}
            if mtext:
                try:
                    meta = json.loads(mtext)
                except Exception:
                    meta = {}
            entry = meta.get(stem, {})
            entry["award"] = award or ""
            entry["player"] = player
            entry["team"] = line["team"]
            entry["season"] = season
            entry["stats"] = line["stats"]
            meta[stem] = entry
            mb64 = base64.b64encode(json.dumps(meta, indent=2).encode("utf-8")).decode("utf-8")
            await _gh_put(session, meta_path, mb64, f"meta: {award or 'base'} - {player}", sha=msha)
        except Exception:
            pass

    raw_url = f"https://raw.githubusercontent.com/{GH_REPO}/{GH_BRANCH}/{new_path}"
    title = ("\U0001f504 Card updated" if existing else
             ("\U0001f3c5 Award card added" if award else "\U0001f0cf Base card added"))
    head = (f"**{award} \u2014 {player}**" if award else f"**{player}** (base card)")
    emb = discord.Embed(
        title=title + replaced_note,
        description=(head + (f"  \u2022  S{season}" if season else "")
                     + (f"\n{line['team']}" if line["team"] else "") + f"\n`{new_path}`"),
        color=0xD4AF37)
    emb.add_field(name="Matched stats", value=line["stats"], inline=False)
    emb.add_field(name="Games", value=str(line["gp"]), inline=True)
    emb.add_field(name="Direct link", value=f"[raw]({raw_url})", inline=True)
    emb.set_image(url=image.url)
    emb.set_footer(text="Live on the Hub + QTCG within ~1 min.")
    await interaction.followup.send(embed=emb)


# ═══════════════════════════════════════════════════════════════════════════
#  /addlogo  —  add a team badge to the Hub's logos/ folder.
#
#  WHERE TO PASTE: right AFTER your /award card block. It reuses the helpers
#  defined there (GH_TOKEN, _GH_OK_EXT, _gh_slug, _gh_fetch, _gh_put), plus
#  team_autocomplete which already exists in your bot. Nothing new to set up —
#  the same GITHUB_TOKEN in your .env covers it.
#
#  The filename is built from the team name so it lines up with how the Hub
#  matches logos to teams (spaces/caps/punctuation ignored).
