# Prices. Single card is automatic/free; everything else is a purchase.
QTCG_PRICES = {"hero_unlock": 10, "change_images": 5, "change_layout": 5, "extra_image": 4}
TIER_RULES = {                    # images, layout_free
    "auto":           (1, False),
    "hero_earned":    (3, True),
    "hero_paid":      (3, True),
    "two_image_paid": (2, True),
}

# Stat types the player can choose. "custom" = they type label + value.
STAT_KEYS = {
    "pts": ("PPG", "pts"),   "reb": ("RPG", "reb"),   "ast": ("APG", "ast"),
    "stl": ("SPG", "stl"),   "blk": ("BPG", "blk"),   "3pm": ("3PM", "3pm"),
    "fg_pct": ("FG%", "fg_pct"), "3p_pct": ("3P%", "3p_pct"), "ft_pct": ("FT%", "ft_pct"),
    "usg": ("USG%", "usg"),  "ts_pct": ("TS%", "ts_pct"), "efg": ("eFG%", "efg"),
    "ortg": ("ORTG", "ortg"), "drtg": ("DRTG", "drtg"), "pie": ("PIE", "pie"),
    "dd": ("DOUBLE-DBLS", "dd"), "td": ("TRIPLE-DBLS", "td"), "gp": ("GAMES", "gp"),
    "mpg": ("MPG", "mpg"),   "stk": ("STKS", "stk"),  "tov": ("TOV", "tov"),
    "custom": ("CUSTOM", None),
}

_Z_ORDER   = {"back": 0, "mid": 1, "front": 2}
_Z_OPACITY = {"back": 0.55, "mid": 1.0, "front": 1.0}


# ─────────────────────────────  FONTS + TEXT  ─────────────────────────────
_FONT_CACHE = {}


def _qc_font(size, bold=True):
    key = (size, bold)
    if key in _FONT_CACHE:
        return _FONT_CACHE[key]
    names = (["impact.ttf", "arialbd.ttf", "seguisb.ttf"] if bold
             else ["arial.ttf", "segoeui.ttf", "arialbd.ttf"])
    f = None
    for n in names:
        for p in (n, f"C:\\Windows\\Fonts\\{n}"):
            try:
                f = ImageFont.truetype(p, size)
                break
            except Exception:
                continue
        if f:
            break
    _FONT_CACHE[key] = f or ImageFont.load_default()
    return _FONT_CACHE[key]


def _qc_glow_text(size, text, fill, glow=(255, 255, 255), glow_r=10,
                  outline=(0, 0, 0), ow=3, skew=0.0, bold=True):
    """Text on its own tile: soft glow + hard outline + fill. skew = italic shear."""
    font = _qc_font(size, bold)
    tmp = ImageDraw.Draw(Image.new("RGBA", (8, 8)))
    tw = int(tmp.textlength(str(text), font=font))
    th = int(size * 1.38)
    pad = glow_r * 3 + ow * 2 + 4
    tile = Image.new("RGBA", (max(2, tw + pad * 2), max(2, th + pad * 2)), (0, 0, 0, 0))
    if glow_r:
        g = Image.new("RGBA", tile.size, (0, 0, 0, 0))
        ImageDraw.Draw(g).text((pad, pad), str(text), font=font, fill=tuple(glow) + (190,))
        tile = Image.alpha_composite(tile, g.filter(ImageFilter.GaussianBlur(glow_r)))
    d = ImageDraw.Draw(tile)
    for dx in range(-ow, ow + 1):
        for dy in range(-ow, ow + 1):
            if (dx or dy) and dx * dx + dy * dy <= ow * ow:
                d.text((pad + dx, pad + dy), str(text), font=font, fill=tuple(outline) + (255,))
    d.text((pad, pad), str(text), font=font, fill=tuple(fill) + (255,))
    if skew:
        w, h = tile.size
        tile = tile.transform((w + int(h * abs(skew)), h), Image.AFFINE,
                              (1, skew, -skew * h if skew > 0 else 0, 0, 1, 0),
                              resample=Image.BICUBIC)
    return tile


def _qc_paste(card, tile, x, y, rot=0, anchor="mm"):
    if rot:
        tile = tile.rotate(rot, expand=True, resample=Image.BICUBIC)
    ax = {"m": tile.width // 2, "l": 0, "r": tile.width}[anchor[0]]
    ay = {"m": tile.height // 2, "t": 0, "b": tile.height}[anchor[1]]
    layer = Image.new("RGBA", card.size, (0, 0, 0, 0))
    layer.alpha_composite(tile, (int(x - ax), int(y - ay)))
    return Image.alpha_composite(card, layer)


# ═══════════════════  GITHUB LIBRARY (templates + cutouts)  ═══════════════════
_QC_LIB = {"manifest": None, "t": 0.0, "img": {}, "cut": {}}


async def _qc_gh_bytes(session, path):
    """Binary fetch. _gh_fetch decodes utf-8 and dies on PNGs, so this is separate."""
    url = f"{GH_API}/repos/{GH_REPO}/contents/{path}"
    try:
        async with session.get(url, params={"ref": GH_BRANCH}, headers=_gh_headers()) as r:
            if r.status != 200:
                return None
            d = await r.json()
            if isinstance(d, dict) and d.get("content"):
                return base64.b64decode(d["content"])
            if isinstance(d, dict) and d.get("download_url"):
                async with session.get(d["download_url"]) as r2:
                    if r2.status == 200:
                        return await r2.read()
    except Exception as e:
        print(f"[QTCG lib] fetch failed {path}: {e}")
    return None


async def _qc_gh_scaffold(session):
    """Create templates/ and cutouts/ on the repo if they aren't there yet.
    GitHub makes folders implicitly, so we just PUT a seed file."""
    made = []
    sha, txt = await _gh_fetch(session, _QC_MANIFEST)
    if txt is None:
        b64 = base64.b64encode(json.dumps({}, indent=1).encode()).decode()
        st, _b = await _gh_put(session, _QC_MANIFEST, b64, "QTCG: create template manifest")
        if st in (200, 201):
            made.append(_QC_MANIFEST)
    items = await _gh_list_dir(session, GH_CUTOUTS)
    if not items:
        b64 = base64.b64encode(b"QTCG cutouts\n").decode()
        st, _b = await _gh_put(session, f"{GH_CUTOUTS}/README.md", b64, "QTCG: create cutouts folder")
        if st in (200, 201):
            made.append(f"{GH_CUTOUTS}/")
    return made


async def _qc_manifest(session, force=False):
    now = _qc_time.time()
    if _QC_LIB["manifest"] is not None and not force and (now - _QC_LIB["t"] < _QC_CACHE_TTL):
        return _QC_LIB["manifest"]
    _sha, txt = await _gh_fetch(session, _QC_MANIFEST)
    if txt is None:
        await _qc_gh_scaffold(session)
        _QC_LIB.update({"manifest": {}, "t": now})
        return {}
    try:
        m = json.loads(txt)
    except Exception as e:
        print(f"[QTCG lib] manifest is not valid JSON ({e})")
        m = {}
    _QC_LIB.update({"manifest": m, "t": now})
    return m


async def _qc_manifest_save(session, manifest, msg):
    sha, _t = await _gh_fetch(session, _QC_MANIFEST)
    b64 = base64.b64encode(json.dumps(manifest, indent=1).encode()).decode()
    st, _b = await _gh_put(session, _QC_MANIFEST, b64, msg, sha=sha)
    _QC_LIB.update({"manifest": manifest, "t": _qc_time.time()})
    return st in (200, 201)


async def _qc_template_png(session, tpl_id, colorway=None):
    """Template art. A colorway may point at its own file; otherwise one file
    is reused and only the accent color changes."""
    m = await _qc_manifest(session)
    t = m.get(tpl_id) or {}
    fn = (t.get("files") or {}).get(colorway or "") or t.get("file") or f"{tpl_id}.png"
    key = f"{tpl_id}:{fn}"
    if key in _QC_LIB["img"]:
        return _QC_LIB["img"][key]
    data = await _qc_gh_bytes(session, f"{GH_TEMPLATES}/{fn}")
    _QC_LIB["img"][key] = data
    return data


async def _qc_cutout_png(session, rel):
    if not rel:
        return None
    if rel in _QC_LIB["cut"]:
        return _QC_LIB["cut"][rel]
    p = rel if "/" in rel else f"{GH_CUTOUTS}/{rel}"
    data = await _qc_gh_bytes(session, p)
    _QC_LIB["cut"][rel] = data
    return data


async def _qc_list_cutouts(session, player=None):
    items = await _gh_list_dir(session, GH_CUTOUTS)
    out = [i["name"] for i in items
           if str(i.get("name", "")).lower().endswith((".png", ".webp"))]
    if player:
        s = _gh_slug(player).lower()
        pref = [n for n in out if n.lower().startswith(s)]
        return pref or out
    return out


# ═══════════════════════════  COMPOSITOR  ═══════════════════════════
def _qc_resolve(spec, W, H, default=(0.5, 0.5)):
    nx, ny = default
    if spec.get("x") is not None:
        nx = float(spec["x"])
    if spec.get("y") is not None:
        ny = float(spec["y"])
    return int(nx * W) + int(spec.get("x_off", 0)), int(ny * H) + int(spec.get("y_off", 0)), \
        float(spec.get("rot", 0) or 0)


def _qc_place_figure(card, cut_bytes, spec):
    """Drop a cutout into one of YOUR placeholder slots."""
    try:
        fig = Image.open(_qc_io.BytesIO(cut_bytes)).convert("RGBA")
    except Exception as e:
        print(f"[QTCG] cutout unreadable ({e})")
        return card
    W, H = card.size
    if spec.get("flip"):
        fig = fig.transpose(Image.FLIP_LEFT_RIGHT)
    scale = max(0.15, min(1.25, float(spec.get("scale", 0.80))))
    th = max(1, int(H * scale))
    fig = fig.resize((max(1, int(fig.width * th / max(1, fig.height))), th), Image.LANCZOS)
    op = _Z_OPACITY.get(spec.get("z", "front"), 1.0) if spec.get("opacity") is None \
        else float(spec["opacity"])
    if op < 1.0:
        fig.putalpha(fig.split()[-1].point(lambda p: int(p * op)))
    x, y, rot = _qc_resolve(spec, W, H, (0.5, 0.52))
    if rot:
        fig = fig.rotate(rot, expand=True, resample=Image.BICUBIC)
    px, py = int(x - fig.width / 2), int(y - fig.height / 2)
    if spec.get("shadow", True) and op >= 0.9:
        sh = Image.new("RGBA", card.size, (0, 0, 0, 0))
        blob = Image.new("RGBA", fig.size, (0, 0, 0, 0))
        blob.putalpha(fig.split()[-1].point(lambda p: int(p * 0.45)))
        sh.alpha_composite(blob, (px + 8, py + 10))
        card = Image.alpha_composite(card, sh.filter(ImageFilter.GaussianBlur(14)))
    layer = Image.new("RGBA", card.size, (0, 0, 0, 0))
    layer.alpha_composite(fig, (px, py))
    return Image.alpha_composite(card, layer)


def _qc_stat_boxed(card, spec, label, value, accent):
    W, H = card.size
    vpx = int(H * float(spec.get("size_n", 0.048)))
    lpx = max(14, int(vpx * 0.34))
    vf, lf = _qc_font(vpx), _qc_font(lpx)
    tmp = ImageDraw.Draw(Image.new("RGBA", (8, 8)))
    vw, lw = tmp.textlength(str(value), font=vf), tmp.textlength(str(label), font=lf)
    px_, py_ = int(vpx * 0.55), int(vpx * 0.34)
    w = int(max(vw, lw) + px_ * 2)
    h = int(vpx + lpx + py_ * 2 + vpx * 0.16)
    tile = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    d = ImageDraw.Draw(tile)
    d.rounded_rectangle([0, 0, w - 1, h - 1], radius=int(h * 0.16), fill=(8, 8, 12, 216))
    d.rounded_rectangle([0, 0, w - 1, h - 1], radius=int(h * 0.16),
                        outline=tuple(accent) + (235,), width=4)
    d.text((w // 2, py_ + lpx // 2), str(label), font=lf,
           fill=tuple(min(255, c + 55) for c in accent), anchor="mm")
    d.text((w // 2, h - py_ - vpx // 2), str(value), font=vf, fill=(255, 255, 255), anchor="mm")
    x, y, rot = _qc_resolve(spec, W, H, (0.5, 0.85))
    return _qc_paste(card, tile, x, y, rot, "mm")


def _qc_stat_float(card, spec, label, value, accent):
    W, H = card.size
    vpx = int(H * float(spec.get("size_n", 0.046)))
    lpx = max(15, int(vpx * 0.52))
    sk = float(spec.get("italic", 0.0) or 0.0)
    glow = tuple(spec.get("glow") or accent)
    x, y, rot = _qc_resolve(spec, W, H, (0.5, 0.85))
    vt = _qc_glow_text(vpx, value, (255, 255, 255), glow, int(spec.get("glow_r", 12)), (0, 0, 0), 3, sk)
    lt = _qc_glow_text(lpx, label, tuple(accent), glow, 6, (0, 0, 0), 3, sk)
    style = spec.get("stack", "under")
    if style == "inline":
        card = _qc_paste(card, vt, x - int(vpx * 0.18), y, rot, "rm")
        card = _qc_paste(card, lt, x + int(vpx * 0.18), y + int(vpx * 0.10), rot, "lm")
    elif style == "over":
        card = _qc_paste(card, lt, x, y - int(vpx * 0.50), rot, "mm")
        card = _qc_paste(card, vt, x, y + int(lpx * 0.55), rot, "mm")
    else:
        card = _qc_paste(card, vt, x, y - int(lpx * 0.42), rot, "mm")
        card = _qc_paste(card, lt, x, y + int(vpx * 0.46), rot, "mm")
    return card


def _qc_identity(card, spec, name, team="", stat_line=None, subtitle=None, accent=(255, 205, 70)):
    W, H = card.size
    x, y, rot = _qc_resolve(spec, W, H, (0.5, 0.945))
    npx = int(H * float(spec.get("size_n", 0.028)))
    rows = []
    head = " - ".join([p for p in (name, team) if p])
    if head:
        rows.append((head, npx, (255, 255, 255), 0.0))
    if stat_line:
        rows.append((stat_line, int(npx * 0.95), (255, 255, 255), 0.0))
    if subtitle:
        rows.append((subtitle, int(npx * 0.86), tuple(min(255, c + 40) for c in accent), 0.20))
    if not rows:
        return card
    total = sum(int(px * 1.42) for _t, px, _c, _s in rows)
    if spec.get("band", True):
        pad = int(H * 0.012)
        ov = Image.new("RGBA", card.size, (0, 0, 0, 0))
        od = ImageDraw.Draw(ov)
        od.rectangle([0, y - total // 2 - pad, W, y + total // 2 + pad], fill=(6, 6, 10, 232))
        od.rectangle([0, y - total // 2 - pad, W, y - total // 2 - pad + 4], fill=tuple(accent) + (255,))
        card = Image.alpha_composite(card, ov)
    cy = y - total // 2
    for txt, px, col, sk in rows:
        card = _qc_paste(card, _qc_glow_text(px, txt, col, accent, 7, (0, 0, 0), 2, sk),
                         x, cy + int(px * 0.71), rot, "mm")
        cy += int(px * 1.42)
    return card


def _qc_watermark(card, text, mode, accent, opacity=0.30):
    if not text or not mode:
        return card
    W, H = card.size
    if mode == "top":
        t = _qc_glow_text(int(H * 0.075), str(text).upper(), tuple(accent), accent, 22, (0, 0, 0), 2)
        t.putalpha(t.split()[-1].point(lambda p: int(p * opacity)))
        return _qc_paste(card, t, W // 2, int(H * 0.055), 0, "mm")
    size = int(H * 0.105)
    x = int(W * (0.88 if mode == "right" else 0.12))
    for i, ch in enumerate(str(text).upper()[:5]):
        t = _qc_glow_text(size, ch, tuple(accent), accent, 18, (0, 0, 0), 2)
        t.putalpha(t.split()[-1].point(lambda p: int(p * opacity)))
        card = _qc_paste(card, t, x, int(H * 0.42) + i * int(size * 0.92), 0, "mm")
    return card


def _qc_accolades(card, lines, spec, accent):
    if not lines:
        return card
    W, H = card.size
    x, y, rot = _qc_resolve(spec, W, H, (0.70, 0.72))
    size = int(H * float(spec.get("size_n", 0.030)))
    gap = int(H * float(spec.get("gap_n", 0.044)))
    taper = float(spec.get("taper", 0.86))
    anchor = {"left": "lm", "right": "rm", "center": "mm"}[spec.get("align", "center")]
    for i, ln in enumerate(list(lines)[:6]):
        card = _qc_paste(card, _qc_glow_text(max(12, size), ln, tuple(accent),
                                             (255, 255, 255), 8, (0, 0, 0), 3, 0.22),
                         x, y + i * gap, rot, anchor)
        size = int(size * taper)
        gap = int(gap * taper)
    return card


# ── logos ──
_QCL_LOGO_CACHE = {"loaded": False, "img": None}


def _qc_load_qcl_logo():
    if not _QCL_LOGO_CACHE["loaded"]:
        _QCL_LOGO_CACHE["loaded"] = True
        try:
            _QCL_LOGO_CACHE["img"] = Image.open(_QCL_LOGO_PATH).convert("RGBA")
        except Exception as e:
            print(f"[QTCG] QCL logo not found at {_QCL_LOGO_PATH} ({e})")
    return _QCL_LOGO_CACHE["img"]


def _qc_paste_logo(card, logo, corner, accent):
    W, H = card.size
    logo = logo.convert("RGBA")
    lw0 = int(W * _LOGO_SCALE)
    logo = logo.resize((lw0, max(1, int(logo.height * lw0 / max(1, logo.width)))), Image.LANCZOS)
    lw, lh = logo.size
    pad = int(W * _LOGO_PAD)
    pos = {"tl": (pad, pad), "tr": (W - lw - pad, pad),
           "bl": (pad, H - lh - pad), "br": (W - lw - pad, H - lh - pad)}
    x, y = pos.get(corner, pos["br"])
    disc = Image.new("RGBA", card.size, (0, 0, 0, 0))
    dd = ImageDraw.Draw(disc)
    cx, cy = x + lw // 2, y + lh // 2
    r = int(max(lw, lh) * 0.62)
    dd.ellipse([cx - r, cy - r, cx + r, cy + r], fill=(10, 10, 14, 150))
    dd.ellipse([cx - r, cy - r, cx + r, cy + r], outline=tuple(accent) + (200,), width=max(2, W // 300))
    card = Image.alpha_composite(card, disc)
    card.alpha_composite(logo, (x, y))
    return card


def _qc_is_admin(interaction):
    m = getattr(interaction, "user", None)
    if isinstance(m, discord.Member):
        return m.guild_permissions.administrator or \
            any(r.name.lower() == _QCL_ADMIN_ROLE.lower() for r in m.roles)
    return False


# ═══════════════════════════  THE BUILD  ═══════════════════════════
def _qc_build_card(tpl_png, layout, cutouts, stats_data, accent, identity,
                   accolades=None, watermark=None, stat_style="boxed",
                   team_logo=None, show_qcl=True):
    """Composite one card from YOUR template + YOUR placeholders."""
    try:
        card = Image.open(_qc_io.BytesIO(tpl_png)).convert("RGBA")
    except Exception as e:
        print(f"[QTCG] template unreadable ({e})")
        return None
    acc = tuple(accent or (255, 205, 70))

    card = _qc_watermark(card, watermark, (layout.get("watermark") or None), acc)

    for im in sorted(layout.get("images", []), key=lambda i: _Z_ORDER.get(i.get("z", "front"), 2)):
        data = cutouts.get(im.get("cutout")) or cutouts.get("__default__")
        if not data:
            continue
        card = _qc_place_figure(card, data, im)

    render = _qc_stat_boxed if stat_style == "boxed" else _qc_stat_float
    for st in layout.get("stats", []):
        key = st.get("key")
        if st.get("mode") == "manual" or not key or key == "custom":
            val = str(st.get("value", "--"))
        else:
            raw = (stats_data or {}).get(STAT_KEYS.get(key, (None, key))[1] or key)
            val = "--" if raw is None else (f"{float(raw):.1f}" if isinstance(raw, (int, float)) else str(raw))
        card = render(card, st, str(st.get("label", key or "")).upper(), val, acc)

    card = _qc_accolades(card, accolades or [], layout.get("accolades") or {}, acc)

    idn = dict(layout.get("identity") or {})
    card = _qc_identity(card, idn, identity.get("name", ""), identity.get("team", ""),
                        identity.get("stat_line"), identity.get("subtitle"), acc)

    if team_logo:
        try:
            card = _qc_paste_logo(card, Image.open(_qc_io.BytesIO(team_logo)), "tl", acc)
        except Exception as e:
            print(f"[QTCG] team logo failed ({e})")
    if show_qcl:
        q = _qc_load_qcl_logo()
        if q is not None:
            card = _qc_paste_logo(card, q, "br", acc)

    out = _qc_io.BytesIO()
    card.convert("RGB").save(out, "PNG")
    return out.getvalue()


# ═══════════════════════════  ENTITLEMENTS  ═══════════════════════════
def _qc_entitlement(award_won=False, purchased=None):
    p = set(purchased or [])
    tier = ("hero_earned" if (award_won or "hero_earned" in p)
            else "hero_paid" if "hero_paid" in p
            else "two_image_paid" if "two_image_paid" in p else "auto")
    imgs, free = TIER_RULES[tier]
    return {"tier": tier, "max_images": imgs, "layout_free": free}


def _qc_price(existing, proposed, ent, published=False):
    """Single card = free. Extra images, art swaps and layout changes cost."""
    items = []
    n_new = len(proposed.get("images", []))
    n_old = len(existing.get("images", [])) if existing else 0
    if n_new > ent["max_images"]:
        if n_new >= 3 and ent["tier"] == "auto":
            items.append(("Unlock Hero card (3 images)", QTCG_PRICES["hero_unlock"]))
        elif n_new == 2 and ent["tier"] == "auto":
            items.append(("Add a 2nd player image", QTCG_PRICES["extra_image"]))
        else:
            items.append((f"Unlock {n_new} images", QTCG_PRICES["hero_unlock"]))
    if existing:
        oc = [i.get("cutout") for i in existing.get("images", [])]
        nc = [i.get("cutout") for i in proposed.get("images", [])]
        if oc and nc and oc != nc and n_new == n_old:
            items.append(("Change player image(s)", QTCG_PRICES["change_images"]))
        def sig(sm):
            return (sm.get("template_id"), sm.get("layout_id"), sm.get("colorway"),
                    [(i.get("x"), i.get("y"), i.get("z"), i.get("scale")) for i in sm.get("images", [])])
        if sig(existing) != sig(proposed) and (published or not ent["layout_free"]):
            items.append(("Change layout", QTCG_PRICES["change_layout"]))
    total = sum(v for _n, v in items)
    return (total == 0), total, items


def _qc_paywall_text(ent, cost, items):
    if not items:
        return f"\u2705 **Included** \u2014 tier `{ent['tier']}`, {ent['max_images']} image(s)."
    body = "\n".join(f"\u2003\u2022 {n} \u2014 **${v}**" for n, v in items)
    return (f"\U0001f512 **This costs ${cost}**\n{body}\n"
            f"_Tier `{ent['tier']}` includes {ent['max_images']} image(s). "
            f"An admin will confirm payment before it's built._")


# ═══════════════════════════  SUBMISSION  ═══════════════════════════
def _qc_validate_shot(img_bytes):
    warn = []
    try:
        im = Image.open(_qc_io.BytesIO(img_bytes))
        w, h = im.size
        if w < _QTCG_MIN_W or h < _QTCG_MIN_H:
            warn.append(f"Low resolution ({w}x{h}) \u2014 needs {_QTCG_MIN_W}x{_QTCG_MIN_H}+")
        if h < w:
            warn.append("Landscape \u2014 full-body cards need a tall screenshot")
        elif h / max(1, w) < 1.15:
            warn.append("Nearly square \u2014 likely cropped; need head to shoes")
        try:
            from PIL import ImageStat
            if ImageStat.Stat(im.convert("L").resize((64, 64))).mean[0] < 42:
                warn.append("Very dark \u2014 face/jersey detail may be lost")
        except Exception:
            pass
        return (not warn), warn, f"{w}x{h}"
    except Exception as e:
        return False, [f"Unreadable image ({e})"], "?"


class _QCSubmitModal(discord.ui.Modal, title="\U0001f3b4 QTCG Card Submission"):
    f_player = discord.ui.TextInput(label="Player name (as it should print)", max_length=40)
    f_team = discord.ui.TextInput(label="Team & jersey number",
                                  placeholder="Al Ghul Academy | 31", max_length=60)
    f_stats = discord.ui.TextInput(label="Stats you want on it",
                                   placeholder="PPG, RPG, SPG", max_length=80)
    f_sub = discord.ui.TextInput(label="Achievement line (optional)", required=False, max_length=90)
    f_acc = discord.ui.TextInput(label="Accolades (optional, separate with | )", required=False,
                                 style=discord.TextStyle.paragraph, max_length=200)

    def __init__(self, attachment, vibe, award):
        super().__init__()
        self.attachment, self.vibe, self.award = attachment, vibe, award

    async def on_submit(self, i: discord.Interaction):
        await i.response.defer(thinking=True, ephemeral=True)
        try:
            shot = await self.attachment.read()
        except Exception as e:
            return await i.followup.send(f"\u274c Couldn't read your screenshot ({e}).", ephemeral=True)
        ok, warn, size = _qc_validate_shot(shot)
        acc = [a.strip() for a in str(self.f_acc.value or "").split("|") if a.strip()][:3]
        e = discord.Embed(
            title=f"\U0001f3b4 Card order \u2014 {self.f_player.value}",
            description=(f"**From** {i.user.mention} (`{i.user}`)\n"
                         f"**Vibe** {self.vibe or '_none picked_'}"
                         + (f"\n**Award** {self.award}" if self.award else "")),
            color=0xffcc00 if ok else 0xe67e22)
        e.add_field(name="Team / number", value=self.f_team.value, inline=True)
        e.add_field(name="Screenshot", value=size + ("  \u2705" if ok else "  \u26a0\ufe0f"), inline=True)
        e.add_field(name="Stats wanted", value=self.f_stats.value, inline=False)
        if self.f_sub.value:
            e.add_field(name="Achievement", value=self.f_sub.value, inline=False)
        if acc:
            e.add_field(name="Accolades", value="\n".join("\u2022 " + a for a in acc), inline=False)
        if warn:
            e.add_field(name="\u26a0\ufe0f Auto-check", value="\n".join("\u2022 " + w for w in warn), inline=False)
        e.set_image(url="attachment://submission.png")
        e.set_footer(text="\U0001f7e1 Unclaimed \u2014 make the cutout, then upload with /createacard mode:Admin")
        ch = bot.get_channel(_QTCG_QUEUE_CH) if _QTCG_QUEUE_CH else None
        if ch is None:
            return await i.followup.send("\u26a0\ufe0f Submissions aren't wired up \u2014 "
                                         "`QTCG_QUEUE_CHANNEL` isn't set. Ping an admin.", ephemeral=True)
        await ch.send(embed=e, file=discord.File(_qc_io.BytesIO(shot), "submission.png"),
                      view=_QCJobView())
        note = ("\n\n\u26a0\ufe0f Your shot tripped:\n" + "\n".join("\u2022 " + w for w in warn)
                + "\nStill queued, but we may ask for a better one.") if warn else ""
        await i.followup.send("\u2705 **Submitted!** You'll get a preview before anything is "
                              "finalized.\n_Your first single-image card is free._" + note, ephemeral=True)


