class _QCTemplateSel(Select):
    def __init__(self, v):
        opts = []
        for tid, t in list(v.manifest.items())[:25]:
            opts.append(discord.SelectOption(
                label=(t.get("name") or tid)[:100],
                value=tid,
                description=f"{t.get('tier','core')} \u00b7 {len(t.get('layouts',{}))} layouts"[:100],
                default=(tid == v.tpl_id)))
        if not opts:
            opts = [discord.SelectOption(label="(no templates uploaded yet)", value="__none__")]
        super().__init__(placeholder="1\ufe0f\u20e3 Pick a card design\u2026", options=opts, row=0)

    async def callback(self, i: discord.Interaction):
        if self.values[0] == "__none__":
            return await i.response.defer()
        self.view.set_template(self.values[0])
        await self.view.refresh(i)


