class QCBuilder(View):
    """The whole player-facing surface: design, layout, colorway. Nothing else."""
    def __init__(self, session, manifest, player, team, stats_data, cutout_name,
                 award=None, ent=None, accolades=None, subtitle=None, stat_line=None):
        super().__init__(timeout=900)
        self.session, self.manifest = session, manifest
        self.player, self.team, self.stats_data = player, team, stats_data
        self.cutout_name, self.award = cutout_name, award
        self.ent = ent or _qc_entitlement()
        self.accolades, self.subtitle, self.stat_line = accolades or [], subtitle, stat_line
        self.tpl_id = next(iter(manifest), None)
        self.tpl = manifest.get(self.tpl_id) or {}
        self.layout_id = next(iter(self.tpl.get("layouts", {})), None)
        self.colorway = next(iter(self.tpl.get("colorways", {"Default": None})), "Default")
        self._build()

    def set_template(self, tid):
        self.tpl_id = tid
        self.tpl = self.manifest.get(tid) or {}
        self.layout_id = next(iter(self.tpl.get("layouts", {})), None)
        self.colorway = next(iter(self.tpl.get("colorways", {"Default": None})), "Default")

    def layout(self):
        return (self.tpl.get("layouts") or {}).get(self.layout_id) or {}

    def accent(self):
        return (self.tpl.get("colorways") or {}).get(self.colorway) or [255, 205, 70]

    def _build(self):
        self.clear_items()
        for c in (_QCTemplateSel(self), _QCLayoutSel(self), _QCColorSel(self),
                  _QCPreviewBtn(self), _QCSendBtn(self)):
            self.add_item(c)

    def price(self):
        return _qc_price(None, dict(self.layout(), template_id=self.tpl_id,
                                    layout_id=self.layout_id, colorway=self.colorway), self.ent)

    async def render(self):
        lay = self.layout()
        if not lay:
            return None, "that design has no layouts yet."
        n = len(lay.get("images", []))
        if n > self.ent["max_images"]:
            pass                       # allowed to preview; the paywall prices it
        tpl_png = await _qc_template_png(self.session, self.tpl_id, self.colorway)
        if not tpl_png:
            return None, f"template art missing on GitHub (`{GH_TEMPLATES}/`)."
        cut = await _qc_cutout_png(self.session, self.cutout_name)
        if not cut:
            return None, (f"no cutout for you yet (`{GH_CUTOUTS}/`). "
                          f"Submit a screenshot with `/createacard mode:Submit` first.")
        png = await asyncio.get_event_loop().run_in_executor(
            None, _qc_build_card, tpl_png, lay, {"__default__": cut}, self.stats_data,
            self.accent(), {"name": self.player, "team": self.team,
                            "stat_line": self.stat_line, "subtitle": self.subtitle},
            self.accolades, self.award, self.tpl.get("stat_style", "boxed"), None, True)
        return (png, None) if png else (None, "render failed \u2014 check the console.")

    def summary(self):
        lay = self.layout()
        free, cost, items = self.price()
        return (f"\U0001f3b4 **Card studio \u2014 {self.player}**\n"
                f"\u2003\U0001f5bc\ufe0f Design: **{self.tpl.get('name', self.tpl_id) or '_none_'}**"
                f"  ({self.tpl.get('tier', 'core')})\n"
                f"\u2003\U0001f4d0 Layout: **{self.layout_id or '_none_'}**"
                f"  \u00b7  {len(lay.get('images', []))} image(s)\n"
                f"\u2003\U0001f3a8 Colorway: **{self.colorway}**\n"
                f"\u2003\U0001f39f\ufe0f Tier: `{self.ent['tier']}` "
                f"({self.ent['max_images']} image(s) included)\n"
                + ("\u2003\u2705 No charge" if free else f"\u2003\U0001f512 **${cost}**"))

    async def refresh(self, interaction):
        self._build()
        await interaction.response.edit_message(content=self.summary(), view=self)

    async def on_timeout(self):
        try:
            await self.session.close()
        except Exception:
            pass


# ═══════════════════════════════════════════════════════════════════════════
#  QTCG STUDIO — PART 2: Library, Adjust flow, QwikCodes
#
#  PASTE INSTRUCTIONS:
#    In createacard_studio.py, DELETE everything from the line
#        # ═══ THE COMMAND ═══
#    down to the end of the file, then paste THIS in its place.
#    Everything above that line stays exactly as it is.
#
#  WHAT THIS ADDS
#    LIBRARY   Players browse every design, every layout, every colorway, and
#              every pose you've made for them -- with real preview images --
#              before they commit to anything.
#    ADJUST    First question is always "do you already have a card?" If yes,
#              they tweak it. Free while it's unpublished; costs once it's live.
#    QWIKCODE  When someone pays, you generate a code. They redeem it, and that
#              unlocks self-publishing + adjustments with no admin in the loop.
#
#  STORAGE (GitHub, same repo the bot already uses)
#    qtcg/entitlements.json   who owns what
#    qtcg/codes.json          issued QwikCodes
#    qtcg/cards.json          each player's saved card + its slot map
# ═══════════════════════════════════════════════════════════════════════════

import secrets
import datetime as _qc_dt

GH_STATE = os.environ.get("QTCG_STATE_PATH", "qtcg")
_QC_ENT_PATH = f"{GH_STATE}/entitlements.json"
_QC_CODE_PATH = f"{GH_STATE}/codes.json"
_QC_CARDS_PATH = f"{GH_STATE}/cards.json"

_QC_STATE = {"ent": None, "codes": None, "cards": None, "t": 0.0}


# ─────────────────────────────  STATE ON GITHUB  ─────────────────────────────
async def _qc_state_load(session, force=False):
    now = _qc_time.time()
    if _QC_STATE["ent"] is not None and not force and (now - _QC_STATE["t"] < _QC_CACHE_TTL):
        return _QC_STATE
    for key, path in (("ent", _QC_ENT_PATH), ("codes", _QC_CODE_PATH), ("cards", _QC_CARDS_PATH)):
        _sha, txt = await _gh_fetch(session, path)
        try:
            _QC_STATE[key] = json.loads(txt) if txt else {}
        except Exception:
            _QC_STATE[key] = {}
    _QC_STATE["t"] = now
    return _QC_STATE


async def _qc_state_save(session, key, msg):
    path = {"ent": _QC_ENT_PATH, "codes": _QC_CODE_PATH, "cards": _QC_CARDS_PATH}[key]
    sha, _t = await _gh_fetch(session, path)
    b64 = base64.b64encode(json.dumps(_QC_STATE[key], indent=1).encode()).decode()
    st, _b = await _gh_put(session, path, b64, msg, sha=sha)
    return st in (200, 201)


async def _qc_user_ent(session, user_id, award_won=False):
    """Entitlement from stored purchases + award status."""
    s = await _qc_state_load(session)
    rec = (s["ent"] or {}).get(str(user_id), {})
    ent = _qc_entitlement(award_won=award_won or rec.get("award_won", False),
                          purchased=rec.get("purchased", []))
    ent["credits"] = rec.get("credits", {})
    ent["self_publish"] = bool(rec.get("self_publish", False))
    return ent


async def _qc_user_card(session, user_id):
    s = await _qc_state_load(session)
    return (s["cards"] or {}).get(str(user_id))


async def _qc_save_card(session, user_id, card):
    s = await _qc_state_load(session)
    s["cards"].setdefault(str(user_id), {})
    s["cards"][str(user_id)] = card
    return await _qc_state_save(session, "cards", f"QTCG: save card for {user_id}")


# ─────────────────────────────  QWIKCODES  ─────────────────────────────
def _qc_new_code():
    a = secrets.token_hex(2).upper()
    b = secrets.token_hex(2).upper()
    return f"QWK-{a}-{b}"


async def _qc_issue_code(session, grants, note="", uses=1):
    """grants e.g. {"purchased":["hero_paid"], "self_publish":true,
                    "credits":{"change_layout":2}}"""
    s = await _qc_state_load(session, force=True)
    code = _qc_new_code()
    while code in (s["codes"] or {}):
        code = _qc_new_code()
    s["codes"][code] = {"grants": grants, "uses": int(uses), "used_by": [],
                        "note": note, "created": _qc_dt.datetime.now(_qc_dt.timezone.utc).isoformat(timespec="seconds")}
    ok = await _qc_state_save(session, "codes", f"QTCG: issue {code}")
    return (code if ok else None)


async def _qc_redeem_code(session, code, user_id):
    s = await _qc_state_load(session, force=True)
    code = str(code or "").strip().upper()
    rec = (s["codes"] or {}).get(code)
    if not rec:
        return False, "That code doesn't exist. Check for typos."
    if str(user_id) in rec.get("used_by", []):
        return False, "You've already redeemed this code."
    if len(rec.get("used_by", [])) >= int(rec.get("uses", 1)):
        return False, "That code has already been used up."

    g = rec.get("grants") or {}
    u = s["ent"].setdefault(str(user_id), {})
    if g.get("purchased"):
        u["purchased"] = sorted(set(u.get("purchased", [])) | set(g["purchased"]))
    if g.get("self_publish"):
        u["self_publish"] = True
    if g.get("award_won"):
        u["award_won"] = True
    for k, v in (g.get("credits") or {}).items():
        u.setdefault("credits", {})
        u["credits"][k] = int(u["credits"].get(k, 0)) + int(v)

    rec.setdefault("used_by", []).append(str(user_id))
    await _qc_state_save(session, "codes", f"QTCG: redeem {code}")
    await _qc_state_save(session, "ent", f"QTCG: entitlements for {user_id}")

    bits = []
    if g.get("purchased"):
        bits.append(", ".join(g["purchased"]))
    if g.get("self_publish"):
        bits.append("self-publishing")
    for k, v in (g.get("credits") or {}).items():
        bits.append(f"{v}x {k.replace('_', ' ')}")
    return True, " + ".join(bits) or "unlocked"


async def _qc_spend_credit(session, user_id, kind):
    s = await _qc_state_load(session)
    u = (s["ent"] or {}).get(str(user_id), {})
    c = u.get("credits", {})
    if int(c.get(kind, 0)) <= 0:
        return False
    c[kind] = int(c[kind]) - 1
    await _qc_state_save(session, "ent", f"QTCG: spend {kind} for {user_id}")
    return True


# ─────────────────────────────  LIBRARY BROWSER  ─────────────────────────────
class _QCLibSel(Select):
    def __init__(self, v):
        opts = [discord.SelectOption(
            label=(t.get("name") or tid)[:100], value=tid,
            description=(f"{t.get('tier','core')} \u00b7 "
                         f"{len(t.get('layouts',{}))} layouts \u00b7 "
                         f"{len(t.get('colorways',{}))} colors")[:100],
            default=(tid == v.tpl_id))
            for tid, t in list(v.manifest.items())[:25]]
        super().__init__(placeholder="Browse designs\u2026", options=opts or
                         [discord.SelectOption(label="(empty)", value="__none__")], row=0)

    async def callback(self, i: discord.Interaction):
        if self.values[0] != "__none__":
            self.view.tpl_id = self.values[0]
            self.view.tpl = self.view.manifest[self.values[0]]
        await self.view.show(i)


class _QCLibPose(Select):
    def __init__(self, v):
        opts = [discord.SelectOption(label=p[:100], value=p, default=(p == v.pose))
                for p in v.poses[:25]]
        super().__init__(placeholder="Your poses\u2026" if opts else "No poses yet",
                         options=opts or [discord.SelectOption(label="(none yet)", value="__none__")],
                         row=1, disabled=not opts)

    async def callback(self, i: discord.Interaction):
        if self.values[0] != "__none__":
            self.view.pose = self.values[0]
        await self.view.show(i)


class _QCLibUse(Button):
    def __init__(self, v):
        super().__init__(label="Use this design", emoji="\u2705",
                         style=discord.ButtonStyle.success, row=2, disabled=not v.tpl_id)

    async def callback(self, i: discord.Interaction):
        v = self.view
        b = QCBuilder(v.session, v.manifest, v.player, v.team, v.stats_data, v.pose,
                      v.award, v.ent, v.accolades, v.subtitle, v.stat_line)
        b.set_template(v.tpl_id)
        await i.response.edit_message(content=b.summary(), view=b, attachments=[])


class QCLibrary(View):
    """Everything on offer: your designs, their layouts, their colorways,
    and every pose you've cut for this player -- with real previews."""
    def __init__(self, session, manifest, poses, player, team, stats_data,
                 award=None, ent=None, accolades=None, subtitle=None, stat_line=None):
        super().__init__(timeout=900)
        self.session, self.manifest, self.poses = session, manifest, poses
        self.player, self.team, self.stats_data = player, team, stats_data
        self.award, self.ent = award, ent or _qc_entitlement()
        self.accolades, self.subtitle, self.stat_line = accolades or [], subtitle, stat_line
        self.tpl_id = next(iter(manifest), None)
        self.tpl = manifest.get(self.tpl_id) or {}
        self.pose = poses[0] if poses else None
        for c in (_QCLibSel(self), _QCLibPose(self), _QCLibUse(self)):
            self.add_item(c)

    def text(self):
        t = self.tpl or {}
        lays = t.get("layouts", {})
        cw = t.get("colorways", {})
        lay_txt = "\n".join(
            f"\u2003\u2003\u2022 **{k}** \u2014 {len(l.get('images', []))} image(s)"
            + ("  \U0001f512 needs Hero" if len(l.get("images", [])) > self.ent["max_images"] else "")
            for k, l in lays.items()) or "\u2003\u2003_no layouts set up yet_"
        pose_txt = "\n".join(f"\u2003\u2003\u2022 `{p}`" + ("  \u25c0 selected" if p == self.pose else "")
                             for p in self.poses[:8]) or \
            "\u2003\u2003_none yet \u2014 submit a screenshot with_ `/createacard mode:Submit`"
        return (f"\U0001f4da **Card library** \u2014 {len(self.manifest)} design(s)\n\n"
                f"\U0001f5bc\ufe0f **{t.get('name', self.tpl_id)}**  ({t.get('tier','core')} "
                f"\u00b7 {t.get('rarity','common')})\n"
                f"\u2003**Layouts**\n{lay_txt}\n"
                f"\u2003**Colorways**  {', '.join(cw) or '_default_'}\n"
                f"\u2003**Stat style**  {t.get('stat_style','boxed')}\n\n"
                f"\U0001f9cd **Your poses**\n{pose_txt}\n\n"
                f"\u2003\U0001f39f\ufe0f Your tier: `{self.ent['tier']}` "
                f"\u2014 {self.ent['max_images']} image(s) included")

    async def show(self, interaction):
        """Called from BOTH a fresh button click and the already-deferred command,
        so it has to branch. Deferring twice raises InteractionResponded."""
        already = interaction.response.is_done()
        if not already:
            await interaction.response.defer()
        png = await _qc_template_png(self.session, self.tpl_id,
                                     next(iter(self.tpl.get("colorways", {})), None))
        files = [discord.File(_qc_io.BytesIO(png), "design.png")] if png else []
        e = discord.Embed(title="\U0001f4da QTCG Library", description=self.text(), color=0x5865F2)
        if png:
            e.set_image(url="attachment://design.png")
        if already:
            await interaction.followup.send(embed=e, view=self, files=files, ephemeral=True)
        else:
            await interaction.edit_original_response(content=None, embed=e, view=self,
                                                     attachments=files)

    async def on_timeout(self):
        try:
            await self.session.close()
        except Exception:
            pass


# ─────────────────────────────  ADJUST FLOW  ─────────────────────────────
class QCHasCard(View):
    """First question, always: do you already have a card?"""
    def __init__(self, session, manifest, poses, player, team, stats, existing, ent,
                 award, accolades, subtitle, stat_line):
        super().__init__(timeout=600)
        self.ctx = (session, manifest, poses, player, team, stats, ent,
                    award, accolades, subtitle, stat_line)
        self.existing = existing
        self.session = session
        if not existing:
            self.remove_item(self.adjust)

    async def on_timeout(self):
        try:
            await self.session.close()
        except Exception:
            pass

    @discord.ui.button(label="Adjust my card", emoji="\U0001f527", style=discord.ButtonStyle.primary)
    async def adjust(self, i: discord.Interaction, b: Button):
        (session, manifest, poses, player, team, stats, ent,
         award, accolades, subtitle, stat_line) = self.ctx
        v = QCBuilder(session, manifest, player, team, stats,
                      self.existing.get("cutout"), award, ent, accolades, subtitle, stat_line)
        v.existing = self.existing
        v.published = bool(self.existing.get("published"))
        if self.existing.get("template_id") in manifest:
            v.set_template(self.existing["template_id"])
            v.layout_id = self.existing.get("layout_id") or v.layout_id
            v.colorway = self.existing.get("colorway") or v.colorway
        note = ("\u26a0\ufe0f This card is **published**, so any change is chargeable."
                if v.published else "\u2705 Not published yet \u2014 adjust freely.")
        await i.response.edit_message(content=note + "\n\n" + v.summary(), view=v, embed=None)

    @discord.ui.button(label="Start a new card", emoji="\u2728", style=discord.ButtonStyle.success)
    async def fresh(self, i: discord.Interaction, b: Button):
        (session, manifest, poses, player, team, stats, ent,
         award, accolades, subtitle, stat_line) = self.ctx
        v = QCBuilder(session, manifest, player, team, stats,
                      poses[0] if poses else None, award, ent, accolades, subtitle, stat_line)
        await i.response.edit_message(content=v.summary(), view=v, embed=None)

    @discord.ui.button(label="Browse the library", emoji="\U0001f4da", style=discord.ButtonStyle.secondary)
    async def browse(self, i: discord.Interaction, b: Button):
        (session, manifest, poses, player, team, stats, ent,
         award, accolades, subtitle, stat_line) = self.ctx
        v = QCLibrary(session, manifest, poses, player, team, stats, award, ent,
                      accolades, subtitle, stat_line)
        await v.show(i)


# ═══════════════════════════════════════════════════════════════════════════
#  QTCG STUDIO — PART 3: card lifecycle, roles-as-accolades, trophy room
#
#  PASTE INSTRUCTIONS (same cut as last time):
#    In your QCL2K.py, find the line
#        # ═══...═══  THE COMMAND  ═══...═══
#    inside the QTCG block, DELETE from there to the end of the QTCG block,
#    and paste THIS in its place.
#
#  ── CARD STATES ────────────────────────────────────────────────────────────
#    live    stats come from the sheet. Re-renders on demand, always current.
#    frozen  a snapshot. Award/Hero cards and historical season cards. Never
#            changes -- that's the whole point of commemorating a season.
#    stale   a LIVE card whose stamped numbers no longer match the sheet.
#            Detected automatically; one click re-renders it.
#
#  ── WHICH CARD SHOWS ───────────────────────────────────────────────────────
#    A player accumulates many cards. Exactly one is ACTIVE -- the most recent
#    one built -- and that's what the Hub, /playercard and their profile show.
#    Award cards are ALSO filed in the trophy room permanently, so winning one
#    never gets buried by the next card they make.
#
#  ── ROLES ARE ACCOLADES ────────────────────────────────────────────────────
#    Discord roles feed the accolade stack automatically. Two classes:
#      persistent  "Top 50", "Hall of Fame" -- stand until you re-rank, and
#                  apply to every card built while the player holds the role.
#      seasonal    "S1 Champion" -- only applied to cards from that season.
#    Editable live at qtcg/roles.json, no code change needed.
# ═══════════════════════════════════════════════════════════════════════════

_QC_ROLES_PATH = f"{GH_STATE}/roles.json"

# Fallback map, used until qtcg/roles.json exists. Keys are matched as
# case-insensitive SUBSTRINGS of the role name, so "QCL Top 50" hits "top 50".
DEFAULT_ROLE_ACCOLADES = {
    "top 10":        {"text": "TOP 10 ALL-TIME",   "class": "persistent", "priority": 100},
    "top 25":        {"text": "TOP 25 ALL-TIME",   "class": "persistent", "priority": 90},
    "top 50":        {"text": "TOP 50 ALL-TIME",   "class": "persistent", "priority": 80},
    "top 75":        {"text": "TOP 75 ALL-TIME",   "class": "persistent", "priority": 70},
    "hall of fame":  {"text": "HALL OF FAME",      "class": "persistent", "priority": 110},
    "dirty 30":      {"text": "DIRTY 30 CLUB",     "class": "persistent", "priority": 55},
    "champion":      {"text": "CHAMPION",          "class": "seasonal",   "priority": 95},
    "finals mvp":    {"text": "FINALS MVP",        "class": "seasonal",   "priority": 96},
    "mvp":           {"text": "MVP",               "class": "seasonal",   "priority": 94},
    "all-qcl":       {"text": "ALL-QCL",           "class": "seasonal",   "priority": 60},
    "all-defensive": {"text": "ALL-DEFENSIVE",     "class": "seasonal",   "priority": 58},
    "captain":       {"text": "CAPTAIN",           "class": "persistent", "priority": 40},
    "veteran":       {"text": "VETERAN",           "class": "persistent", "priority": 30},
}

_QC_ROLES_CACHE = {"map": None, "t": 0.0}


async def _qc_role_map(session, force=False):
    now = _qc_time.time()
    if _QC_ROLES_CACHE["map"] is not None and not force and (now - _QC_ROLES_CACHE["t"] < _QC_CACHE_TTL):
        return _QC_ROLES_CACHE["map"]
    _sha, txt = await _gh_fetch(session, _QC_ROLES_PATH)
    if txt is None:
        b64 = base64.b64encode(json.dumps(DEFAULT_ROLE_ACCOLADES, indent=1).encode()).decode()
        await _gh_put(session, _QC_ROLES_PATH, b64, "QTCG: seed role accolade map")
        m = dict(DEFAULT_ROLE_ACCOLADES)
    else:
        try:
            m = json.loads(txt) or dict(DEFAULT_ROLE_ACCOLADES)
        except Exception:
            m = dict(DEFAULT_ROLE_ACCOLADES)
    _QC_ROLES_CACHE.update({"map": m, "t": now})
    return m


def _qc_accolades_from_roles(member, role_map, season=None, limit=3):
    """Turn a member's Discord roles into accolade lines.

    Persistent accolades (Top 50, Hall of Fame) apply to every card while the
    player holds the role. Seasonal ones only apply when the card's season
    matches -- or when the card has no season set.
    """
    if not isinstance(member, discord.Member):
        return []
    hits = {}
    for r in getattr(member, "roles", []):
        rn = str(getattr(r, "name", "")).lower()
        for key, cfg in (role_map or {}).items():
            if key.lower() in rn:
                cls = cfg.get("class", "persistent")
                if cls == "seasonal" and season is not None:
                    # "S1 Champion" only rides on a season-1 card
                    import re as _re
                    m = _re.search(r"s(?:eason)?\s*([0-9]+)", rn)
                    if m and int(m.group(1)) != int(season):
                        continue
                txt = cfg.get("text", key.upper())
                pr = int(cfg.get("priority", 50))
                if txt not in hits or pr > hits[txt][0]:
                    hits[txt] = (pr, cls)
    ordered = sorted(hits.items(), key=lambda kv: -kv[1][0])
    return [t for t, _v in ordered][:limit]


def _qc_merge_accolades(manual, from_roles, limit=3):
    """Typed accolades win the top slots; roles fill whatever's left."""
    out = []
    for a in list(manual or []) + list(from_roles or []):
        a = str(a).strip()
        if a and a.upper() not in [o.upper() for o in out]:
            out.append(a)
        if len(out) >= limit:
            break
    return out


# ═══════════════════════════  CARD REGISTRY  ═══════════════════════════
#  qtcg/cards.json
#    { "<user_id>": { "active": "<card_id>", "all": { "<card_id>": {...} } } }
def _qc_card_id(player, award=None, season=None):
    stem = f"{_gh_slug(award)}_{_gh_slug(player)}" if award else _gh_slug(player)
    return stem + (f"_s{season}" if season else "")


async def _qc_cards_for(session, user_id):
    s = await _qc_state_load(session)
    rec = (s["cards"] or {}).get(str(user_id))
    if rec is None:
        return {"active": None, "all": {}}
    if "all" not in rec:                       # migrate the old single-card shape
        cid = _qc_card_id(rec.get("player", "card"), rec.get("award"), rec.get("season"))
        rec = {"active": cid, "all": {cid: rec}}
    return rec


async def _qc_register_card(session, user_id, card, make_active=True):
    s = await _qc_state_load(session, force=True)
    rec = await _qc_cards_for(session, user_id)
    cid = card.get("card_id") or _qc_card_id(card.get("player", "card"),
                                             card.get("award"), card.get("season"))
    card["card_id"] = cid
    card.setdefault("created", _qc_dt.datetime.now(_qc_dt.timezone.utc).isoformat(timespec="seconds"))
    card["updated"] = _qc_dt.datetime.now(_qc_dt.timezone.utc).isoformat(timespec="seconds")
    rec["all"][cid] = card
    if make_active:
        rec["active"] = cid
    s["cards"][str(user_id)] = rec
    await _qc_state_save(session, "cards", f"QTCG: register card {cid}")
    return cid


async def _qc_set_active(session, user_id, card_id):
    s = await _qc_state_load(session, force=True)
    rec = await _qc_cards_for(session, user_id)
    if card_id not in rec["all"]:
        return False
    rec["active"] = card_id
    s["cards"][str(user_id)] = rec
    return await _qc_state_save(session, "cards", f"QTCG: active card -> {card_id}")


# ── STATE ──
def _qc_card_state(card, live_stats, tol=0.05):
    """live | frozen | stale. Frozen cards are never stale -- by design."""
    if card.get("stats_mode") == "snapshot" or card.get("frozen") or card.get("award"):
        return "frozen"
    snap = card.get("stats_at_render") or {}
    if not snap or not live_stats:
        return "live"
    for k, old in snap.items():
        new = live_stats.get(k)
        if new is None:
            continue
        try:
            if abs(float(new) - float(old)) > tol:
                return "stale"
        except (TypeError, ValueError):
            if str(new) != str(old):
                return "stale"
    return "live"


def _qc_state_badge(st):
    return {"live": "\U0001f7e2 live", "frozen": "\U0001f3c6 frozen",
            "stale": "\U0001f7e0 stale"}.get(st, st)


def _qc_stats_snapshot(layout, live_stats):
    """Only record the stats this layout actually prints."""
    out = {}
    for stt in (layout or {}).get("stats", []):
        k = stt.get("key")
        if k and k != "custom":
            col = STAT_KEYS.get(k, (None, k))[1] or k
            v = (live_stats or {}).get(col)
            if v is not None:
                out[col] = v
    return out


# ═══════════════════════════  MY CARDS VIEW  ═══════════════════════════
class _QCCardSel(Select):
    def __init__(self, v):
        opts = []
        for cid, c in list(v.cards["all"].items())[:25]:
            st = _qc_card_state(c, v.live_stats)
            opts.append(discord.SelectOption(
                label=(c.get("award") or c.get("template_id") or cid)[:100],
                value=cid,
                description=f"{_qc_state_badge(st)} \u00b7 {c.get('layout_id','')} \u00b7 "
                            f"S{c.get('season','-')}"[:100],
                default=(cid == v.sel)))
        super().__init__(placeholder="Your cards\u2026", row=0,
                         options=opts or [discord.SelectOption(label="(none yet)", value="__none__")])

    async def callback(self, i: discord.Interaction):
        if self.values[0] != "__none__":
            self.view.sel = self.values[0]
        await self.view.show(i)


class _QCSetActiveBtn(Button):
    def __init__(self, v):
        cur = v.cards.get("active")
        super().__init__(label="Make this my main card", emoji="\u2b50",
                         style=discord.ButtonStyle.primary, row=1,
                         disabled=(not v.sel or v.sel == cur))

    async def callback(self, i: discord.Interaction):
        v = self.view
        await i.response.defer(ephemeral=True)
        ok = await _qc_set_active(v.session, i.user.id, v.sel)
        v.cards = await _qc_cards_for(v.session, i.user.id)
        await i.followup.send("\u2b50 That's your main card now \u2014 it's what shows "
                              "on the Hub and your profile." if ok else
                              "\u274c Couldn't update.", ephemeral=True)


class _QCRefreshBtn(Button):
    def __init__(self, v):
        c = v.cards["all"].get(v.sel) or {}
        st = _qc_card_state(c, v.live_stats)
        super().__init__(label="Refresh stats", emoji="\U0001f504",
                         style=discord.ButtonStyle.success, row=1,
                         disabled=(st != "stale"))

    async def callback(self, i: discord.Interaction):
        v = self.view
        await i.response.defer(thinking=True, ephemeral=True)
        c = dict(v.cards["all"].get(v.sel) or {})
        tpl = v.manifest.get(c.get("template_id"))
        if not tpl:
            return await i.followup.send("\u274c That design isn't in the library anymore.",
                                         ephemeral=True)
        lay = (tpl.get("layouts") or {}).get(c.get("layout_id")) or {}
        tpl_png = await _qc_template_png(v.session, c["template_id"], c.get("colorway"))
        cut = await _qc_cutout_png(v.session, c.get("cutout"))
        if not (tpl_png and cut):
            return await i.followup.send("\u274c Template art or cutout is missing.", ephemeral=True)
        acc = (tpl.get("colorways") or {}).get(c.get("colorway")) or [255, 205, 70]
        png = await asyncio.get_event_loop().run_in_executor(
            None, _qc_build_card, tpl_png, lay, {"__default__": cut}, v.live_stats, acc,
            {"name": c.get("player", ""), "team": c.get("team", ""),
             "stat_line": c.get("stat_line"), "subtitle": c.get("subtitle")},
            c.get("accolades") or [], c.get("award"), tpl.get("stat_style", "boxed"), None, True)
        if not png:
            return await i.followup.send("\u274c Re-render failed.", ephemeral=True)
        c["stats_at_render"] = _qc_stats_snapshot(lay, v.live_stats)
        await _qc_register_card(v.session, i.user.id, c, make_active=False)
        v.cards = await _qc_cards_for(v.session, i.user.id)
        e = discord.Embed(title="\U0001f504 Stats refreshed",
                          description="Numbers are current again. Free \u2014 refreshing a live "
                                      "card is never a charge.", color=0x2ecc71)
        e.set_image(url="attachment://card.png")
        await i.followup.send(embed=e, file=discord.File(_qc_io.BytesIO(png), "card.png"),
                              ephemeral=True)


class QCMyCards(View):
    """Every card the player owns: which is active, which are trophies,
    which have gone stale."""
    def __init__(self, session, manifest, cards, live_stats, member=None):
        super().__init__(timeout=900)
        self.session, self.manifest = session, manifest
        self.cards, self.live_stats, self.member = cards, live_stats, member
        self.sel = cards.get("active") or next(iter(cards.get("all", {})), None)
        self._build()

    def _build(self):
        self.clear_items()
        for c in (_QCCardSel(self), _QCSetActiveBtn(self), _QCRefreshBtn(self)):
            self.add_item(c)

    def text(self):
        allc = self.cards.get("all", {})
        act = self.cards.get("active")
        if not allc:
            return ("\U0001f5c2\ufe0f **No cards yet.**\nYour first single-image card is free "
                    "\u2014 run `/createacard` to build it.")
        trophies, regular, stale_n = [], [], 0
        for cid, c in allc.items():
            st = _qc_card_state(c, self.live_stats)
            if st == "stale":
                stale_n += 1
            row = (f"\u2003{'\u2b50 ' if cid == act else '\u2003'}"
                   f"**{c.get('award') or c.get('template_id')}** "
                   f"\u00b7 {c.get('layout_id','')} \u00b7 {_qc_state_badge(st)}")
            (trophies if c.get("award") else regular).append(row)
        out = [f"\U0001f5c2\ufe0f **Your cards** \u2014 {len(allc)} total"]
        if act:
            out.append(f"\u2003\u2b50 Main card: **{allc[act].get('award') or allc[act].get('template_id')}** "
                       f"\u2014 this is what shows on the Hub")
        if trophies:
            out.append("\n\U0001f3c6 **Trophy room** _(frozen forever)_\n" + "\n".join(trophies))
        if regular:
            out.append("\n\U0001f3b4 **Cards**\n" + "\n".join(regular))
        if stale_n:
            out.append(f"\n\U0001f7e0 **{stale_n} card(s) out of date** \u2014 pick one and hit "
                       f"**Refresh stats**. Free, always.")
        return "\n".join(out)

    async def show(self, interaction):
        already = interaction.response.is_done()
        if not already:
            await interaction.response.defer()
        self._build()
        e = discord.Embed(title="\U0001f5c2\ufe0f My QTCG cards", description=self.text(),
                          color=0x5865F2)
        if already:
            await interaction.followup.send(embed=e, view=self, ephemeral=True)
        else:
            await interaction.edit_original_response(content=None, embed=e, view=self)

    async def on_timeout(self):
        try:
            await self.session.close()
        except Exception:
            pass


# ═══════════════════  PUBLISH + BULK SYNC  ═══════════════════
#  Finished cards go to cards/ + cards/meta.json -- the SAME place the Hub and
#  /award cardinfo already read from. This is what the old _qc_commit_card did;
#  losing it would have meant cards never reached the Hub.
async def _qc_publish_card(session, png_bytes, player, award=None, season=None,
                           team="", stats="", accolades=None, subtitle=None):
    stem = _qc_card_id(player, award, season)
    path = f"{GH_CARDS}/{stem}.png"
    old_sha = None
    for it in await _gh_list_dir(session, GH_CARDS):
        if it.get("name") == f"{stem}.png":
            old_sha = it.get("sha")
            break
    st, _b = await _gh_put(session, path, base64.b64encode(png_bytes).decode(),
                           f"QTCG card: {award or 'base'} - {player}", sha=old_sha)
    if st not in (200, 201):
        return None, f"GitHub {st}"
    # meta.json in the shape /award cardinfo and the Hub already expect
    try:
        meta_path = f"{GH_CARDS}/meta.json"
        msha, mtext = await _gh_fetch(session, meta_path)
        meta = json.loads(mtext) if mtext else {}
        entry = meta.get(stem, {})
        entry.update({"award": award or entry.get("award", ""), "player": player,
                      "team": team or entry.get("team", ""), "season": season,
                      "stats": stats or entry.get("stats", "")})
        if accolades:
            entry["highlights"] = list(accolades)
        if subtitle:
            entry.setdefault("blurb", subtitle)
        meta[stem] = entry
        await _gh_put(session, meta_path,
                      base64.b64encode(json.dumps(meta, indent=2).encode()).decode(),
                      f"meta: {award or 'base'} - {player}", sha=msha)
    except Exception as e:
        print(f"[QTCG] meta.json update failed: {e}")
    try:
        _CI_CACHE["t"] = 0.0        # bust the /award cardinfo picker cache
    except Exception:
        pass
    return path, None


async def _qc_sync_library(session):
    """BULK TEMPLATE IMPORT.

    Drag as many PNGs as you like into templates/ using GitHub's web uploader,
    then run this. Every PNG that isn't in manifest.json gets registered with
    its real canvas size and an empty layouts block, ready for coordinates.
    """
    await _qc_gh_scaffold(session)
    man = await _qc_manifest(session, force=True)
    items = await _gh_list_dir(session, GH_TEMPLATES)
    added, skipped, failed = [], [], []
    known_files = {t.get("file") for t in man.values()}
    known_files |= {f for t in man.values() for f in (t.get("files") or {}).values()}
    for it in items:
        n = str(it.get("name") or "")
        if not n.lower().endswith((".png", ".webp")):
            continue
        if n in known_files:
            skipped.append(n)
            continue
        stem = _gh_slug(os.path.splitext(n)[0])
        if stem in man:
            skipped.append(n)
            continue
        data = await _qc_gh_bytes(session, f"{GH_TEMPLATES}/{n}")
        if not data:
            failed.append(n)
            continue
        try:
            w, h = Image.open(_qc_io.BytesIO(data)).size
        except Exception:
            failed.append(n)
            continue
        man[stem] = {"name": os.path.splitext(n)[0].replace("_", " ").title(),
                     "tier": "core", "rarity": "common", "file": n,
                     "canvas": [w, h], "stat_style": "boxed",
                     "colorways": {"Default": [255, 205, 70]}, "layouts": {}}
        added.append(f"{stem} ({w}x{h})")
    if added:
        await _qc_manifest_save(session, man, f"QTCG: sync {len(added)} template(s)")
        _QC_LIB["img"].clear()
    return added, skipped, failed


class _QCJobView(View):
    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(label="\U0001f3af Claim", style=discord.ButtonStyle.primary,
                       custom_id="qtcg_claim")
    async def claim(self, i: discord.Interaction, b: Button):
        if not _qc_is_admin(i):
            return await i.response.send_message("Admins only.", ephemeral=True)
        e = i.message.embeds[0]
        e.color = 0x3498db
        e.set_footer(text=f"\U0001f3af Claimed by {i.user.display_name}")
        b.disabled = True
        await i.response.edit_message(embed=e, view=self)

    @discord.ui.button(label="\u2705 Publish", style=discord.ButtonStyle.success,
                       custom_id="qtcg_done")
    async def done(self, i: discord.Interaction, b: Button):
        """Pushes the attached card to cards/ so the Hub, /qtcg and
        /award cardinfo all pick it up."""
        if not _qc_is_admin(i):
            return await i.response.send_message("Admins only.", ephemeral=True)
        await i.response.defer()
        e = i.message.embeds[0]
        atts = [a for a in i.message.attachments
                if str(a.filename).lower().endswith((".png", ".jpg", ".webp"))]
        note = ""
        if atts:
            try:
                png = await atts[0].read()
                title = (e.title or "").split("\u2014")[-1].strip() or "card"
                async with aiohttp.ClientSession() as s:
                    path, err = await _qc_publish_card(s, png, title)
                note = (f"\n\u2705 Live at `{path}`" if path
                        else f"\n\u26a0\ufe0f Couldn't publish ({err})")
            except Exception as ex:
                note = f"\n\u26a0\ufe0f Publish failed ({type(ex).__name__})"
        else:
            note = "\n\u26a0\ufe0f No image attached \u2014 nothing published"
        e.color = 0x2ecc71
        e.set_footer(text=f"\u2705 Published by {i.user.display_name}")
        e.description = (e.description or "") + note
        await i.edit_original_response(embed=e, view=None)

    @discord.ui.button(label="\u274c Reject", style=discord.ButtonStyle.danger,
                       custom_id="qtcg_rej")
    async def rej(self, i: discord.Interaction, b: Button):
        if not _qc_is_admin(i):
            return await i.response.send_message("Admins only.", ephemeral=True)
        e = i.message.embeds[0]
        e.color = 0xcc0000
        e.set_footer(text=f"\u274c Rejected by {i.user.display_name} \u2014 DM them why")
        await i.response.edit_message(embed=e, view=None)


# ═══════════════════════════  THE COMMAND  ═══════════════════════════
@bot.tree.command(name="createacard", description="Build, adjust or browse your QCL card")
@app_commands.describe(
    mode="What you want to do",
    player="Player from the sheet \u2014 pulls live stats",
    reference_photo="Submit mode: your 2K screenshot",
    vibe="Submit mode: the look you're after",
    award="Award label (unlocks the free Hero card if you won one)",
    season="Season number",
    accolades="Pipe-separated. Leave blank to use your Discord roles",
    subtitle="Achievement line under the stats",
    code="Redeem mode: your QwikCode",
    upload="Admin: PNG to upload",
    upload_kind="Admin: what you're uploading",
    upload_name="Admin: file/template id",
    grant_user="Admin: who the QwikCode is for",
    grant_what="Admin: what the code unlocks")
@app_commands.choices(mode=[
    app_commands.Choice(name="\U0001f3b4 Build / adjust my card", value="build"),
    app_commands.Choice(name="\U0001f5c2\ufe0f My cards \u2014 main, trophies, stale", value="mycards"),
    app_commands.Choice(name="\U0001f4da Library \u2014 see every option", value="library"),
    app_commands.Choice(name="\U0001f4e5 Submit \u2014 send a screenshot", value="submit"),
    app_commands.Choice(name="\U0001f39f\ufe0f Redeem a QwikCode", value="redeem"),
    app_commands.Choice(name="\U0001f6e0\ufe0f Admin \u2014 upload art", value="admin"),
    app_commands.Choice(name="\U0001f511 Admin \u2014 issue a QwikCode", value="grant"),
])
@app_commands.choices(upload_kind=[
    app_commands.Choice(name="Template art (templates/)", value="template"),
    app_commands.Choice(name="Player cutout / pose (cutouts/)", value="cutout"),
])
@app_commands.choices(grant_what=[
    app_commands.Choice(name="Hero unlock (3 images) + self-publish", value="hero"),
    app_commands.Choice(name="Layout change x1", value="layout"),
    app_commands.Choice(name="Image swap x1", value="images"),
    app_commands.Choice(name="Self-publish only", value="publish"),
])
@app_commands.autocomplete(player=_award_player_ac)
async def createacard(interaction: discord.Interaction,
                      mode: app_commands.Choice[str] = None,
                      player: str = None,
                      reference_photo: discord.Attachment = None,
                      vibe: str = None, award: str = None, season: int = None,
                      accolades: str = None, subtitle: str = None,
                      code: str = None,
                      upload: discord.Attachment = None,
                      upload_kind: app_commands.Choice[str] = None,
                      upload_name: str = None,
                      grant_user: discord.Member = None,
                      grant_what: app_commands.Choice[str] = None):
    m = mode.value if mode else "build"

    # ---------- SUBMIT ----------
    if m == "submit":
        if reference_photo is None:
            return await interaction.response.send_message(
                "\U0001f4f8 **Attach your screenshot** in `reference_photo`.\n\n"
                "Full body head-to-shoes, standing straight facing the camera, arms down "
                "and away from your body, plain background, no HUD, bright and clear.",
                ephemeral=True)
        if not str(reference_photo.content_type or "").startswith("image/"):
            return await interaction.response.send_message("\u274c That's not an image.", ephemeral=True)
        return await interaction.response.send_modal(_QCSubmitModal(reference_photo, vibe, award))

    # ---------- REDEEM ----------
    if m == "redeem":
        if not code:
            return await interaction.response.send_message(
                "Enter your code in `code`, e.g. `QWK-7F3A-2B91`.", ephemeral=True)
        await interaction.response.defer(thinking=True, ephemeral=True)
        async with aiohttp.ClientSession() as s:
            ok, msg = await _qc_redeem_code(s, code, interaction.user.id)
        return await interaction.followup.send(
            (f"\u2705 **Redeemed** \u2014 unlocked: {msg}\n"
             "Run `/createacard` and your new options are live.") if ok else f"\u274c {msg}",
            ephemeral=True)

    # ---------- ADMIN: issue a QwikCode ----------
    if m == "grant":
        if not _qc_is_admin(interaction):
            return await interaction.response.send_message("Admins only.", ephemeral=True)
        if not grant_what:
            return await interaction.response.send_message(
                "Pick `grant_what`. `grant_user` is optional \u2014 it's only a note.", ephemeral=True)
        await interaction.response.defer(thinking=True, ephemeral=True)
        grants = {
            "hero":    {"purchased": ["hero_paid"], "self_publish": True},
            "layout":  {"credits": {"change_layout": 1}},
            "images":  {"credits": {"change_images": 1}},
            "publish": {"self_publish": True},
        }[grant_what.value]
        note = f"for {grant_user}" if grant_user else "open"
        async with aiohttp.ClientSession() as s:
            c = await _qc_issue_code(s, grants, note)
        if not c:
            return await interaction.followup.send("\u274c Couldn't write to GitHub.", ephemeral=True)
        return await interaction.followup.send(
            f"\U0001f511 **QwikCode issued**\n```\n{c}\n```\n"
            f"Unlocks: **{grant_what.name}**  \u00b7  single use  \u00b7  {note}\n"
            f"DM it to them \u2014 they redeem with `/createacard mode:Redeem`.", ephemeral=True)

    # ---------- ADMIN: upload art ----------
    if m == "admin":
        if not _qc_is_admin(interaction):
            return await interaction.response.send_message("Admins only.", ephemeral=True)
        if upload is None or upload_kind is None:
            # No file attached -> treat it as a BULK SYNC of whatever you dragged
            # into templates/ on GitHub. This is how you add many at once.
            await interaction.response.defer(thinking=True, ephemeral=True)
            async with aiohttp.ClientSession() as s:
                added, skipped, failed = await _qc_sync_library(s)
            msg = ["\U0001f504 **Library sync**"]
            if added:
                msg.append(f"\u2705 Registered **{len(added)}** new design(s):\n"
                           + "\n".join("\u2003\u2022 " + a for a in added[:20]))
                msg.append("\u26a0\ufe0f Each has **no layouts** yet \u2014 add coordinates to "
                           "`layouts` in `templates/manifest.json` before players can use them.")
            if skipped:
                msg.append(f"\u23ed\ufe0f Already registered: {len(skipped)}")
            if failed:
                msg.append(f"\u274c Unreadable: {', '.join(failed[:8])}")
            if not (added or skipped or failed):
                msg.append("Nothing found in `templates/`. Drag your PNGs in on GitHub "
                           "(Add file \u2192 Upload files \u2192 select many), then run this again.")
            msg.append("\n_To upload one file straight from Discord instead, attach it in "
                       "`upload` and set `upload_kind`._")
            return await interaction.followup.send("\n".join(msg)[:1900], ephemeral=True)
        await interaction.response.defer(thinking=True, ephemeral=True)
        data = await upload.read()
        stem = _gh_slug(upload_name or os.path.splitext(upload.filename)[0])
        folder = GH_TEMPLATES if upload_kind.value == "template" else GH_CUTOUTS
        path = f"{folder}/{stem}.png"
        extra = ""
        async with aiohttp.ClientSession() as s:
            await _qc_gh_scaffold(s)
            sha, _t = await _gh_fetch(s, path)
            st, _b = await _gh_put(s, path, base64.b64encode(data).decode(),
                                   f"QTCG: upload {upload_kind.value} {stem}", sha=sha)
            if st not in (200, 201):
                return await interaction.followup.send(f"\u274c GitHub said {st}.", ephemeral=True)
            if upload_kind.value == "template":
                man = await _qc_manifest(s, force=True)
                if stem not in man:
                    im = Image.open(_qc_io.BytesIO(data))
                    man[stem] = {"name": upload_name or stem, "tier": "core", "rarity": "common",
                                 "file": f"{stem}.png", "canvas": list(im.size),
                                 "stat_style": "boxed",
                                 "colorways": {"Default": [255, 205, 70]}, "layouts": {}}
                    await _qc_manifest_save(s, man, f"QTCG: register template {stem}")
                    extra = ("\n\u26a0\ufe0f Registered with **no layouts**. Add placeholder "
                             "coordinates to `layouts` in `templates/manifest.json` before "
                             "players can use it.")
        _QC_LIB["img"].clear()
        _QC_LIB["cut"].clear()
        return await interaction.followup.send(f"\u2705 Uploaded to `{path}`.{extra}", ephemeral=True)

    # ---------- BUILD / LIBRARY / MY CARDS ----------
    await interaction.response.defer(thinking=True, ephemeral=True)
    line = _award_player_line(player, season) if player else None
    line = dict(line) if line else {"team": "", "pts": 0.0, "reb": 0.0, "ast": 0.0}
    name = player or interaction.user.display_name
    stat_line = " - ".join(f"{float(line[k]):.1f} {lbl}" for k, lbl in
                           (("pts", "PPG"), ("reb", "RPG"), ("ast", "APG"))
                           if float(line.get(k, 0) or 0))

    session = aiohttp.ClientSession()
    try:
        man = await _qc_manifest(session)

        if m == "mycards":
            cards = await _qc_cards_for(session, interaction.user.id)
            v = QCMyCards(session, man, cards, line, interaction.user)
            return await v.show(interaction)

        if not man:
            await session.close()
            return await interaction.followup.send(
                "\U0001f5bc\ufe0f **No card designs yet.** An admin needs to upload one with "
                "`/createacard mode:Admin`.", ephemeral=True)

        # Discord roles become accolades. Typed ones take the top slots.
        rmap = await _qc_role_map(session)
        role_acc = _qc_accolades_from_roles(interaction.user, rmap, season)
        typed = [a.strip() for a in (accolades or "").split("|") if a.strip()]
        accs = _qc_merge_accolades(typed, role_acc)

        poses = await _qc_list_cutouts(session, name)
        ent = await _qc_user_ent(session, interaction.user.id, award_won=bool(award))

        if m == "library":
            v = QCLibrary(session, man, poses, name, line.get("team", ""), line,
                          award, ent, accs, subtitle, stat_line)
            return await v.show(interaction)

        cards = await _qc_cards_for(session, interaction.user.id)
        active = cards["all"].get(cards.get("active")) if cards.get("active") else None
        v = QCHasCard(session, man, poses, name, line.get("team", ""), line, active, ent,
                      award, accs, subtitle, stat_line)
        if active:
            st = _qc_card_state(active, line)
            head = (f"\U0001f3b4 **{name}** \u2014 your main card is "
                    f"**{active.get('award') or active.get('template_id')}** "
                    f"({active.get('layout_id')}) \u00b7 {_qc_state_badge(st)}\n"
                    + ("\n\U0001f7e0 Its numbers are out of date \u2014 `mode:My cards` "
                       "\u2192 **Refresh stats** fixes it free.\n" if st == "stale" else "")
                    + f"\nYou own **{len(cards['all'])}** card(s). Adjust this one, start "
                      f"fresh, or browse the library?")
        else:
            head = (f"\U0001f3b4 **{name}** \u2014 no card on file yet.\n\n"
                    f"Your first single-image card is **free**. Start building, or browse "
                    f"the library first?")
        if role_acc:
            head += f"\n\n\U0001f396\ufe0f From your roles: _{' \u00b7 '.join(role_acc)}_"
        await interaction.followup.send(head, view=v, ephemeral=True)
    except Exception:
        await session.close()
        raise

# ═══════════════════════════════════════════════════════════════════════════
#  QSPN SOCIAL — Twitter/X + YouTube, with Discord channel routing
#
#  PASTE: after the /qtcg market commands block. All _soc_ / SOC_ prefixed.
#
#  ── .env ───────────────────────────────────────────────────────────────────
#   # Twitter/X  — OAuth 1.0a user context (needed to POST). Free tier allows
#   # ~500 posts/month. Get these at developer.x.com -> your app -> Keys.
#   TWITTER_API_KEY=
#   TWITTER_API_SECRET=
#   TWITTER_ACCESS_TOKEN=
#   TWITTER_ACCESS_SECRET=
#
#   # YouTube — OAuth 2.0. See the one-time setup at the bottom of this file.
#   YOUTUBE_CLIENT_ID=
#   YOUTUBE_CLIENT_SECRET=
#   YOUTUBE_REFRESH_TOKEN=
#   YOUTUBE_CHANNEL_ID=           # optional; auto-detected on first call
#
#  ── pip ────────────────────────────────────────────────────────────────────
#   pip install requests-oauthlib
#   (YouTube uses plain aiohttp — no google client library needed)
#
#  ── ROUTING ────────────────────────────────────────────────────────────────
#  /qspn social channels  opens real Discord channel dropdowns and stores which
#  channel receives which feed. Saved to fantasy_data/social.json.
# ═══════════════════════════════════════════════════════════════════════════

import os as _soc_os
import json as _soc_json
import time as _soc_time
import asyncio as _soc_asyncio
import aiohttp as _soc_aiohttp
import discord as _soc_discord
from discord import app_commands as _soc_ac
from discord.ext import tasks as _soc_tasks

SOC_PATH = _soc_os.path.join(TVT_DATA_DIR, "social.json")

TW_KEY = _soc_os.environ.get("TWITTER_API_KEY", "")
TW_SECRET = _soc_os.environ.get("TWITTER_API_SECRET", "")
TW_TOKEN = _soc_os.environ.get("TWITTER_ACCESS_TOKEN", "")
TW_TOKEN_SECRET = _soc_os.environ.get("TWITTER_ACCESS_SECRET", "")

YT_CLIENT_ID = _soc_os.environ.get("YOUTUBE_CLIENT_ID", "")
YT_CLIENT_SECRET = _soc_os.environ.get("YOUTUBE_CLIENT_SECRET", "")
YT_REFRESH = _soc_os.environ.get("YOUTUBE_REFRESH_TOKEN", "")
YT_CHANNEL_ID = _soc_os.environ.get("YOUTUBE_CHANNEL_ID", "")

# Every feed the bot can route. Add here and it shows up in the dropdown.
SOC_FEEDS = {
    "moments":    "\U0001f4a5 Moment drops",
    "market":     "\U0001f3ea Market sales & auctions",
    "awards":     "\U0001f3c6 Award cards",
    "youtube":    "\U0001f4fa New YouTube uploads",
    "highlights": "\U0001f525 Game highlights",
    "results":    "\U0001f4ca Game results",
}


def _soc_load():
    if _soc_os.path.exists(SOC_PATH):
        try:
            with open(SOC_PATH, "r", encoding="utf-8") as f:
                d = _soc_json.load(f)
            if isinstance(d, dict):
                d.setdefault("channels", {})
                d.setdefault("twitter", {})
                d.setdefault("youtube", {"seen": []})
                return d
        except Exception:
            pass
    return {"channels": {}, "twitter": {}, "youtube": {"seen": []}}


def _soc_save(d):
    tmp = SOC_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        _soc_json.dump(d, f, indent=2)
    _soc_os.replace(tmp, SOC_PATH)


def _soc_channel(feed):
    """Discord channel object for a feed, or None if unrouted."""
    cid = _soc_load()["channels"].get(feed)
    return bot.get_channel(int(cid)) if cid else None


async def _soc_post(feed, content=None, embed=None, file=None):
    """Send to whatever channel this feed is routed to. Silent if unrouted."""
    ch = _soc_channel(feed)
    if ch is None:
        return False
    try:
        await ch.send(content=content, embed=embed, file=file)
        return True
    except Exception as e:
        print(f"[QSPN social] post to {feed} failed: {e}")
        return False


# ═══════════════════════════  TWITTER / X  ═══════════════════════════
def _tw_ready():
    return all((TW_KEY, TW_SECRET, TW_TOKEN, TW_TOKEN_SECRET))


def _tw_post_sync(text, media_path=None):
    """POST /2/tweets with OAuth 1.0a user context. Blocking -> run in executor."""
    if not _tw_ready():
        return None, "Twitter keys missing from .env"
    try:
        from requests_oauthlib import OAuth1Session
    except ImportError:
        return None, "pip install requests-oauthlib"
    try:
        oauth = OAuth1Session(TW_KEY, client_secret=TW_SECRET,
                              resource_owner_key=TW_TOKEN,
                              resource_owner_secret=TW_TOKEN_SECRET)
        media_ids = []
        if media_path and _soc_os.path.exists(media_path):
            # v1.1 is still the upload endpoint; v2 has no media upload yet
            with open(media_path, "rb") as fh:
                r = oauth.post("https://upload.twitter.com/1.1/media/upload.json",
                               files={"media": fh}, timeout=45)
            if r.status_code in (200, 201):
                media_ids.append(str(r.json()["media_id_string"]))
            else:
                print(f"[QSPN tw] media upload {r.status_code}: {r.text[:200]}")
        payload = {"text": text[:280]}
        if media_ids:
            payload["media"] = {"media_ids": media_ids}
        r = oauth.post("https://api.x.com/2/tweets", json=payload, timeout=30)
        if r.status_code in (200, 201):
            d = r.json().get("data", {})
            return d.get("id"), None
        return None, f"X API {r.status_code}: {r.text[:220]}"
    except Exception as e:
        return None, f"{type(e).__name__}: {e}"


async def _tw_post(text, media_path=None):
    loop = _soc_asyncio.get_event_loop()
    return await loop.run_in_executor(None, _tw_post_sync, text, media_path)


# ═══════════════════════════  YOUTUBE  ═══════════════════════════
_YT_TOKEN = {"access": None, "exp": 0.0}


def _yt_ready():
    return all((YT_CLIENT_ID, YT_CLIENT_SECRET, YT_REFRESH))


async def _yt_access_token(session):
    """Refresh-token -> short-lived access token. Cached until ~1 min before expiry."""
    if _YT_TOKEN["access"] and _soc_time.time() < _YT_TOKEN["exp"]:
        return _YT_TOKEN["access"], None
    if not _yt_ready():
        return None, "YouTube OAuth env vars missing"
    try:
        async with session.post("https://oauth2.googleapis.com/token", data={
            "client_id": YT_CLIENT_ID, "client_secret": YT_CLIENT_SECRET,
            "refresh_token": YT_REFRESH, "grant_type": "refresh_token",
        }, timeout=_soc_aiohttp.ClientTimeout(total=20)) as r:
            d = await r.json()
            if r.status != 200:
                return None, f"token {r.status}: {str(d)[:200]}"
            _YT_TOKEN["access"] = d["access_token"]
            _YT_TOKEN["exp"] = _soc_time.time() + int(d.get("expires_in", 3600)) - 60
            return _YT_TOKEN["access"], None
    except Exception as e:
        return None, f"{type(e).__name__}: {e}"


async def _yt_uploads_playlist(session, token):
    """The channel's 'uploads' playlist — cheapest way to list every video (1 unit)."""
    params = {"part": "contentDetails"}
    if YT_CHANNEL_ID:
        params["id"] = YT_CHANNEL_ID
    else:
        params["mine"] = "true"
    async with session.get("https://www.googleapis.com/youtube/v3/channels",
                           params=params, headers={"Authorization": f"Bearer {token}"},
                           timeout=_soc_aiohttp.ClientTimeout(total=20)) as r:
        d = await r.json()
        if r.status != 200:
            return None, f"channels {r.status}: {str(d)[:200]}"
        items = d.get("items") or []
        if not items:
            return None, "no channel found for these credentials"
        return items[0]["contentDetails"]["relatedPlaylists"]["uploads"], None


async def _yt_recent(limit=10):
    """Most recent uploads. Costs ~2 quota units total — cheap enough to poll."""
    async with _soc_aiohttp.ClientSession() as s:
        token, err = await _yt_access_token(s)
        if err:
            return None, err
        pl, err = await _yt_uploads_playlist(s, token)
        if err:
            return None, err
        async with s.get("https://www.googleapis.com/youtube/v3/playlistItems",
                         params={"part": "snippet,contentDetails", "playlistId": pl,
                                 "maxResults": str(min(50, limit))},
                         headers={"Authorization": f"Bearer {token}"},
                         timeout=_soc_aiohttp.ClientTimeout(total=25)) as r:
            d = await r.json()
            if r.status != 200:
                return None, f"playlistItems {r.status}: {str(d)[:200]}"
    out = []
    for it in d.get("items", []):
        sn = it.get("snippet", {})
        vid = it.get("contentDetails", {}).get("videoId")
        if not vid:
            continue
        thumbs = sn.get("thumbnails", {})
        out.append({
            "id": vid, "title": sn.get("title", ""),
            "published": it.get("contentDetails", {}).get("videoPublishedAt", ""),
            "url": f"https://youtu.be/{vid}",
            "thumb": (thumbs.get("high") or thumbs.get("default") or {}).get("url", ""),
            "desc": (sn.get("description") or "")[:300],
        })
    return out, None


# ═════════════════  CHANNEL ROUTING UI (real dropdowns)  ═════════════════
class _SocFeedSelect(_soc_discord.ui.Select):
    def __init__(self, view):
        cur = _soc_load()["channels"]
        opts = []
        for key, label in SOC_FEEDS.items():
            ch = bot.get_channel(int(cur[key])) if cur.get(key) else None
            opts.append(_soc_discord.SelectOption(
                label=label[:100], value=key,
                description=(f"#{ch.name}" if ch else "not routed")[:100],
                default=(key == view.feed)))
        super().__init__(placeholder="1\ufe0f\u20e3 Which feed?", options=opts, row=0)

    async def callback(self, i: _soc_discord.Interaction):
        self.view.feed = self.values[0]
        await self.view.refresh(i)


class _SocChannelSelect(_soc_discord.ui.ChannelSelect):
    """Discord's native channel picker — real channels, no IDs to copy."""
    def __init__(self, view):
        super().__init__(placeholder="2\ufe0f\u20e3 Send it to\u2026", row=1,
                         channel_types=[_soc_discord.ChannelType.text,
                                        _soc_discord.ChannelType.news],
                         min_values=1, max_values=1)

    async def callback(self, i: _soc_discord.Interaction):
        v = self.view
        d = _soc_load()
        d["channels"][v.feed] = str(self.values[0].id)
        _soc_save(d)
        await v.refresh(i, note=f"\u2705 **{SOC_FEEDS[v.feed]}** \u2192 {self.values[0].mention}")


class _SocClearBtn(_soc_discord.ui.Button):
    def __init__(self, view):
        super().__init__(label="Unroute this feed", emoji="\U0001f6ab",
                         style=_soc_discord.ButtonStyle.danger, row=2)

    async def callback(self, i: _soc_discord.Interaction):
        v = self.view
        d = _soc_load()
        d["channels"].pop(v.feed, None)
        _soc_save(d)
        await v.refresh(i, note=f"\U0001f6ab **{SOC_FEEDS[v.feed]}** unrouted.")


class SocialChannels(_soc_discord.ui.View):
    def __init__(self):
        super().__init__(timeout=600)
        self.feed = next(iter(SOC_FEEDS))
        self._build()

    def _build(self):
        self.clear_items()
        for c in (_SocFeedSelect(self), _SocChannelSelect(self), _SocClearBtn(self)):
            self.add_item(c)

    def text(self, note=None):
        cur = _soc_load()["channels"]
        rows = []
        for key, label in SOC_FEEDS.items():
            ch = bot.get_channel(int(cur[key])) if cur.get(key) else None
            mark = "\u25c0" if key == self.feed else "\u2003"
            rows.append(f"{mark} {label} \u2014 " + (ch.mention if ch else "_not routed_"))
        head = (note + "\n\n") if note else ""
        return (head + "\U0001f4e1 **Feed routing**\n" + "\n".join(rows)
                + "\n\n_Pick a feed, then pick its channel._")

    async def refresh(self, interaction, note=None):
        self._build()
        await interaction.response.edit_message(content=self.text(note), view=self)


