@soc_group.command(name="youtube", description="Pull recent uploads and announce them")
@_soc_ac.describe(count="How many to fetch", announce="Post them to the routed channel")
async def soc_youtube(interaction: _soc_discord.Interaction, count: int = 5,
                      announce: bool = False):
    await interaction.response.defer(thinking=True)
    vids, err = await _yt_recent(max(1, min(25, count)))
    if err:
        return await interaction.followup.send(f"\u274c {err}")
    if not vids:
        return await interaction.followup.send("No uploads found on that channel.")
    emb = _soc_discord.Embed(title="\U0001f4fa Recent uploads", color=0xFF0000)
    for v in vids[:10]:
        emb.add_field(name=v["title"][:100],
                      value=f"[watch]({v['url']}) \u00b7 {v['published'][:10]}", inline=False)
    if vids[0].get("thumb"):
        emb.set_thumbnail(url=vids[0]["thumb"])
    await interaction.followup.send(embed=emb)

    if announce:
        d = _soc_load()
        seen = set(d["youtube"].get("seen", []))
        fresh = [v for v in vids if v["id"] not in seen]
        for v in reversed(fresh):
            e = _soc_discord.Embed(title=v["title"][:250], url=v["url"], color=0xFF0000,
                                   description=v["desc"][:300])
            if v.get("thumb"):
                e.set_image(url=v["thumb"])
            e.set_footer(text="QSPN \u00b7 new on YouTube")
            await _soc_post("youtube", embed=e)
        d["youtube"]["seen"] = list(seen | {v["id"] for v in vids})[-300:]
        _soc_save(d)
        await interaction.followup.send(
            f"\U0001f4e3 Announced **{len(fresh)}** new video(s)." if fresh
            else "Nothing new to announce.", ephemeral=True)


# ── auto-announce new uploads ──────────────────────────────────────────────
@_soc_tasks.loop(minutes=15)
async def _soc_yt_watch():
    if not _yt_ready() or _soc_channel("youtube") is None:
        return
    try:
        vids, err = await _yt_recent(10)
        if err or not vids:
            return
        d = _soc_load()
        seen = set(d["youtube"].get("seen", []))
        if not seen:                       # first run: mark everything seen, don't spam
            d["youtube"]["seen"] = [v["id"] for v in vids]
            _soc_save(d)
            return
        fresh = [v for v in vids if v["id"] not in seen]
        for v in reversed(fresh):
            e = _soc_discord.Embed(title=v["title"][:250], url=v["url"], color=0xFF0000,
                                   description=v["desc"][:300])
            if v.get("thumb"):
                e.set_image(url=v["thumb"])
            e.set_footer(text="QSPN \u00b7 new on YouTube")
            await _soc_post("youtube", embed=e)
            if _tw_ready():
                await _tw_post(f"\U0001f3c0 New QCL game up now\n{v['title'][:180]}\n{v['url']}")
        d["youtube"]["seen"] = list(seen | {v["id"] for v in vids})[-300:]
        _soc_save(d)
    except Exception as e:
        print(f"[QSPN social] yt watch: {e}")


@_soc_yt_watch.before_loop
async def _soc_yt_wait():
    await bot.wait_until_ready()


@bot.listen("on_ready")
async def _soc_on_ready():
    if not _soc_yt_watch.is_running():
        _soc_yt_watch.start()


