# ═══════════════════════════════════════════════════════════════════════════
#  /award cardinfo  (v2)  —  now with an EXISTING-CARD picker.
#  Pick a card from a live dropdown (reads cards/ + meta.json), then add a
#  blurb, key-game highlights, or AI-written text. Writes cards/meta.json;
#  the Hub shows it on the flip side within ~1 min.
#
#  WHERE TO PASTE: right AFTER your /award card block. Reuses its helpers
#  (GH_TOKEN, GH_REPO, GH_BRANCH, GH_CARDS, GH_API, _gh_headers, _gh_slug,
#  _gh_fetch, _gh_put, _award_player_line) plus player_autocomplete + ask_ai.
#
#  If you already pasted the v1 cardinfo, DELETE that block and use this one.
# ═══════════════════════════════════════════════════════════════════════════

import time as _ci_time

_AWARD_TYPES = ["MVP", "OPOY", "DPOY", "Sixth Man", "Most Improved", "Rookie of the Year",
                "Champion", "Finals MVP", "All-League 1st", "Defensive POY", "Hustle Award",
                "Sportsmanship", "Clutch Player"]

_CI_CACHE = {"t": 0.0, "cards": []}


async def _ci_list_cards():
    """Cached list of existing cards: [{stem, label, player, season}]. ~45s TTL."""
    now = _ci_time.time()
    if _CI_CACHE["cards"] and (now - _CI_CACHE["t"] < 45):
        return _CI_CACHE["cards"]
    cards, seen = [], set()
    try:
        async with aiohttp.ClientSession() as session:
            _, mtext = await _gh_fetch(session, f"{GH_CARDS}/meta.json")
            meta = {}
            if mtext:
                try:
                    meta = json.loads(mtext)
                except Exception:
                    meta = {}

            names = []
            url = f"{GH_API}/repos/{GH_REPO}/contents/{GH_CARDS}"
            async with session.get(url, params={"ref": GH_BRANCH}, headers=_gh_headers()) as r:
                if r.status == 200:
                    for it in await r.json():
                        n = (it.get("name") or "")
                        if n.lower().endswith((".png", ".jpg", ".jpeg", ".webp", ".gif")):
                            names.append(os.path.splitext(n)[0])

            def _season(stem, m):
                if m.get("season") is not None:
                    return m.get("season")
                mt = re.search(r"_s(\d+)$", stem)
                return int(mt.group(1)) if mt else None

            def _entry(stem):
                m = meta.get(stem, {})
                award = m.get("award", "")
                player = m.get("player", "")
                label = (f"{award} — {player}".strip(" —")) or stem.replace("_", " ")
                seas = _season(stem, m)
                if seas:
                    label += f" (S{seas})"
                return {"stem": stem, "label": label, "player": player, "season": seas}

            for stem in names:
                cards.append(_entry(stem)); seen.add(stem)
            for stem in meta.keys():
                if stem not in seen:
                    cards.append(_entry(stem))
    except Exception:
        pass
    cards.sort(key=lambda c: c["label"].lower())
    _CI_CACHE["t"] = now
    _CI_CACHE["cards"] = cards
    return cards


async def existing_card_autocomplete(interaction: discord.Interaction, current: str):
    cur = (current or "").lower()
    out = []
    for c in await _ci_list_cards():
        if cur in c["label"].lower() or cur in c["stem"].lower():
            out.append(app_commands.Choice(name=c["label"][:100], value=c["stem"][:100]))
        if len(out) >= 25:
            break
    return out


async def award_type_autocomplete(interaction: discord.Interaction, current: str):
    cur = (current or "").lower()
    seen, out = set(), []
    for a in _AWARD_TYPES:
        if a not in seen and cur in a.lower():
            seen.add(a); out.append(app_commands.Choice(name=a, value=a))
    return out[:25]


def _cardinfo_stat_ctx(player, season=None):
    line = _award_player_line(player, season)
    if not line:
        return "", None
    ctx = (f"{player} averaged {line['pts']:.1f} PPG, {line['reb']:.1f} RPG, "
           f"{line['ast']:.1f} APG, {(line['stl'] + line['blk']):.1f} stocks and "
           f"{line['tpm']:.1f} threes over {line['gp']} games"
           + (f" for {line['team']}" if line['team'] else "") + ".")
    return ctx, line


@award_group.command(name="cardinfo",
                     description="Set a card's flip-side text & highlights (pick a card, freestyle or AI)")
@app_commands.describe(
    card="Pick an existing card from the list",
    blurb="A line or two for the back of the card (or a seed/direction for the AI)",
    highlight="A key game or feat to list, e.g. '52 PTS vs Krashout (G3)'",
    ai="Let the AI write the blurb from the player's stats (+ your text as direction)",
    replace_highlights="Wipe existing highlights before adding this one",
    player="(only if the card isn't in the list yet) winner name",
    award="(only if not in the list yet) award label",
    season="(only if not in the list yet) season number",
)
@app_commands.autocomplete(card=existing_card_autocomplete,
                           player=player_autocomplete,
                           award=award_type_autocomplete)
async def award_cardinfo(interaction: discord.Interaction,
                         card: str = None,
                         blurb: str = None,
                         highlight: str = None,
                         ai: bool = False,
                         replace_highlights: bool = False,
                         player: str = None,
                         award: str = None,
                         season: int = None):
    await interaction.response.defer(thinking=True)

    if not GH_TOKEN:
        return await interaction.followup.send(
            "❌ No `GITHUB_TOKEN` in the bot's .env. Add it and restart.")

    # Resolve which card we're editing.
    if card:
        stem = card
        info = next((c for c in await _ci_list_cards() if c["stem"] == stem), None)
        if info:
            player = player or info.get("player")
            season = season if season is not None else info.get("season")
        if not award:
            award = (stem.split("_", 1)[0] if "_" in stem else stem)
    elif player and award:
        stem = f"{_gh_slug(award)}_{_gh_slug(player)}" + (f"_s{season}" if season else "")
    else:
        return await interaction.followup.send(
            "❌ Pick a **card** from the list, or (for a card not made yet) give **player** + **award**.")

    ctx, line = _cardinfo_stat_ctx(player, season) if player else ("", None)

    # --- optional AI blurb ---
    ai_note = ""
    final_blurb = blurb
    if ai:
        try:
            sysp = ("You are a hype broadcaster for QSPN, an NBA 2K Pro-Am league. Write ONE "
                    "punchy caption (1-2 sentences, under 240 characters) for an award card. "
                    "Be specific and confident. No hashtags, no quotes, no emojis.")
            usr = f"Award: {award}. Player: {player}. Stats: {ctx or 'not available'}. "
            if blurb:
                usr += f"Producer's direction: {blurb}. "
            usr += "Return only the caption text."
            text, src = await ask_ai(sysp, usr, max_tokens=160)
            cleaned = (text or "").strip().strip('"').strip()
            if cleaned:
                final_blurb = cleaned[:300]
                ai_note = f" (AI via {src})"
            else:
                ai_note = " (AI returned nothing; kept your text)"
        except Exception as e:
            ai_note = f" (AI failed: {type(e).__name__}; kept your text)"

    # --- update cards/meta.json ---
    async with aiohttp.ClientSession() as session:
        meta_path = f"{GH_CARDS}/meta.json"
        msha, mtext = await _gh_fetch(session, meta_path)
        meta = {}
        if mtext:
            try:
                meta = json.loads(mtext)
            except Exception:
                meta = {}

        entry = meta.get(stem, {})
        if award:
            entry.setdefault("award", award)
        if player:
            entry["player"] = entry.get("player") or player
        if line:
            entry.setdefault("team", line["team"])
            entry.setdefault("stats", line["stats"])
        if final_blurb is not None:
            entry["blurb"] = final_blurb

        hl = entry.get("highlights", [])
        if not isinstance(hl, list):
            hl = []
        if replace_highlights:
            hl = []
        if highlight:
            hl.append(highlight)
        entry["highlights"] = hl

        meta[stem] = entry
        mb64 = base64.b64encode(json.dumps(meta, indent=2).encode("utf-8")).decode("utf-8")
        status, body = await _gh_put(session, meta_path, mb64,
                                     f"cardinfo: {entry.get('award', '')} - {entry.get('player', '')}",
                                     sha=msha)

    _CI_CACHE["t"] = 0.0  # bust the picker cache so the change shows next time

    if status in (200, 201):
        emb = discord.Embed(
            title="📝 Card info updated" + ai_note, color=0xD4AF37,
            description=f"**{entry.get('award', '')} — {entry.get('player', '')}**"
                        + (f"  •  S{season}" if season else "") + f"\n`{stem}`")
        if entry.get("blurb"):
            emb.add_field(name="Blurb", value=entry["blurb"][:1024], inline=False)
        if entry.get("highlights"):
            emb.add_field(name="Highlights",
                          value=("\n".join("• " + h for h in entry["highlights"]))[:1024],
                          inline=False)
        emb.set_footer(text="Flip the card on the Hub to see it — live within ~1 min.")
        await interaction.followup.send(embed=emb)
    else:
        detail = body.get("message", body) if isinstance(body, dict) else body
        await interaction.followup.send(f"❌ GitHub rejected it ({status}): {detail}")

# ═══════════════════════════════════════════════════════════════════════════
#  COMMUNITY MENTIONS  ->  popularity.json   (integrated into the bot)
#  Counts how often each player's name comes up in chat and writes a rolling,
#  decaying tally to popularity.json in the repo. The Hub folds it into card
#  prices. Uses @bot.listen so it does NOT replace your existing on_message.
#
#  WHERE TO PASTE: anywhere AFTER your /award card block (for GH_TOKEN /
#  _gh_fetch / _gh_put) and after bot = QSPNBot() and load_data() are defined.
#  Needs the message-content intent, which your box-score parser already uses.
# ═══════════════════════════════════════════════════════════════════════════

import asyncio  # noqa: E402 (safe if already imported at the top)

POP_PATH = os.environ.get("POPULARITY_PATH", "popularity.json")
_MENTION_DECAY = 0.97           # each flush, old mentions fade ~3% -> "trending"
_MENTION_MINLEN = 3
_mention_counts = {}
_mention_pattern = None
_mention_lower = {}


def _build_mention_pattern(names):
    global _mention_pattern, _mention_lower
    names = sorted({n.strip() for n in names
                    if isinstance(n, str) and len(n.strip()) >= _MENTION_MINLEN},
                   key=len, reverse=True)
    if not names:
        _mention_pattern, _mention_lower = None, {}
        return
    esc = "|".join(re.escape(n) for n in names)
    _mention_pattern = re.compile(r"(?<![A-Za-z0-9])(" + esc + r")(?![A-Za-z0-9])", re.IGNORECASE)
    _mention_lower = {n.lower(): n for n in names}


@tasks.loop(hours=1)
async def refresh_mention_names():
    try:
        loop = asyncio.get_event_loop()
        p_df, _t = await loop.run_in_executor(None, load_data)
        names = [str(x).strip() for x in p_df["PlayerName"].dropna().unique()
                 if str(x).strip() and str(x).strip() != "0"]
        _build_mention_pattern(names)
    except Exception as e:
        print(f"[mentions] name refresh failed: {e}")


@tasks.loop(minutes=10)
async def flush_mentions():
    global _mention_counts
    if not GH_TOKEN or not _mention_counts:
        return
    local = _mention_counts
    _mention_counts = {}
    try:
        async with aiohttp.ClientSession() as session:
            sha, text = await _gh_fetch(session, POP_PATH)
            data = {}
            if text:
                try:
                    data = json.loads(text)
                except Exception:
                    data = {}
            if not isinstance(data, dict):
                data = {}
            mentions = data.get("mentions", {}) if isinstance(data.get("mentions"), dict) else {}

            for k in list(mentions.keys()):
                mentions[k] = round(float(mentions[k]) * _MENTION_DECAY, 2)
                if mentions[k] < 0.1:
                    del mentions[k]
            for k, v in local.items():
                mentions[k] = round(mentions.get(k, 0) + v, 2)

            data["mentions"] = mentions
            b64 = base64.b64encode(json.dumps(data, indent=2).encode("utf-8")).decode("utf-8")
            status, _b = await _gh_put(session, POP_PATH, b64, "popularity: mentions update", sha=sha)
            if status not in (200, 201):
                raise RuntimeError(f"GitHub {status}")
    except Exception as e:
        # don't lose counts on a failed flush
        for k, v in local.items():
            _mention_counts[k] = _mention_counts.get(k, 0) + v
        print(f"[mentions] flush failed: {e}")


@bot.listen("on_message")
async def _mentions_on_message(message):
    if message.author.bot or not _mention_pattern:
        return
    try:
        for m in _mention_pattern.findall(message.content or ""):
            canon = _mention_lower.get(m.lower(), m)
            _mention_counts[canon] = _mention_counts.get(canon, 0) + 1
    except Exception:
        pass


@bot.listen("on_ready")
async def _mentions_on_ready():
    if not refresh_mention_names.is_running():
        refresh_mention_names.start()
    if not flush_mentions.is_running():
        flush_mentions.start()

# ═══════════════════════════════════════════════════════════════════════
# 🏆 QCL TOURNAMENT SYSTEM — COMPLETE
# ═══════════════════════════════════════════════════════════════════════
#
# THREE PHASES:
#
# 1. PRE-SEASON SWISS (Any # of teams)
#    - Swiss system tournament
#    - Winner gets AUTO BID TO FINAL FOUR
#
# 2. REGULAR SEASON (All teams)
#    - Group play stages
#    - Knockout stages within groups
#    - Top 9 teams advance to playoffs
#
# 3. PLAYOFFS (9-Team Format)
#    - FINAL FOUR SPOTS (automatic):
#      • Seeds #1, #2, #3 from season
#      • PLUS Pre-Season Winner (if not already #1-3, bumps down someone)
#    
#    - ROUND 1 (BO1): Seeds #4-9 play
#      • Single elimination (best of 1)
#      • 3 matches → 3 winners → 1 final winner
#      • Winner joins Final Four
#    
#    - FINAL FOUR SEMIS (BO3):
#      • Match 1: Seed #1 vs Round 1 Winner
#      • Match 2: Seed #2 vs Seed #3
#      • Both BO3
#    
#    - CHAMPIONSHIP (BO5):
#      • Winners of two semifinals
#      • Best of 5
#
# ═══════════════════════════════════════════════════════════════════════

from itertools import combinations
import random

# ═══════════════════════════════════════════════════════════════════════
# SWISS PRE-SEASON
# ═══════════════════════════════════════════════════════════════════════

def generate_swiss_round(teams: list, round_num: int, prev_standings: dict = None) -> list:
    """Generate Swiss round (winners vs winners, losers vs losers)."""
    if prev_standings is None:
        prev_standings = {team: {'wins': 0, 'losses': 0} for team in teams}
    
    sorted_teams = sorted(
        teams,
        key=lambda t: (-prev_standings[t]['wins'], t)
    )
    
    matchups = []
    used = set()
    
    for i in range(0, len(sorted_teams), 2):
        if sorted_teams[i] not in used and i + 1 < len(sorted_teams):
            if sorted_teams[i + 1] not in used:
                matchups.append((sorted_teams[i], sorted_teams[i + 1]))
                used.add(sorted_teams[i])
                used.add(sorted_teams[i + 1])
    
    remaining = [t for t in sorted_teams if t not in used]
    if remaining:
        matchups.append((remaining[0], "BYE"))
    
    random.shuffle(matchups)
    return matchups


def format_swiss_embeds(teams: list, num_rounds: int, matchups_by_round: dict = None) -> list:
    """Format Swiss tournament."""
    embeds = []
    
    overview = discord.Embed(
        title=f"🏆 Pre-Season Swiss ({len(teams)} Teams, {num_rounds} Rounds)",
        description="Determine seeding\nWinner → AUTO BID TO FINAL FOUR",
        color=discord.Color.blue()
    )
    overview.add_field(name="Teams", value=str(len(teams)), inline=True)
    overview.add_field(name="Rounds", value=str(num_rounds), inline=True)
    overview.add_field(
        name="Winner's Prize",
        value="👑 Automatic Final Four spot (guaranteed seed #1, #2, or #3)",
        inline=False
    )
    embeds.append(overview)
    
    if matchups_by_round:
        for rnd in sorted(matchups_by_round.keys()):
            matchups = matchups_by_round[rnd]
            round_embed = discord.Embed(
                title=f"📅 Round {rnd}",
                color=discord.Color.blurple()
            )
            
            for idx, (team1, team2) in enumerate(matchups, 1):
                if team2 == "BYE":
                    round_embed.add_field(name=f"Match {idx}", value=f"🎮 **{team1}** — BYE", inline=False)
                else:
                    round_embed.add_field(name=f"Match {idx}", value=f"🎮 **{team1}** vs **{team2}**", inline=False)
            
            embeds.append(round_embed)
    
    return embeds


# ═══════════════════════════════════════════════════════════════════════
# REGULAR SEASON (Groups + Knockout)
# ═══════════════════════════════════════════════════════════════════════

def distribute_teams_into_groups(team_names: list, num_groups: int) -> dict:
    """Distribute teams into groups (by Swiss ranking)."""
    groups = {g: [] for g in range(1, num_groups + 1)}
    for idx, team in enumerate(team_names):
        group_id = (idx % num_groups) + 1
        groups[group_id].append(team)
    return groups


def format_season_embeds(groups: dict) -> list:
    """Format season groups."""
    embeds = []
    
    summary = discord.Embed(
        title="🏆 Regular Season",
        description="Group play + Knockout stages\nTop 9 teams → Playoffs",
        color=discord.Color.green()
    )
    embeds.append(summary)
    
    groups_embed = discord.Embed(
        title="📊 Groups",
        description="Distributed by Pre-Season Swiss ranking",
        color=discord.Color.gold()
    )
    
    for gid in sorted(groups.keys()):
        teams_str = ", ".join(groups[gid])
        groups_embed.add_field(name=f"Group {gid}", value=teams_str, inline=False)
    
    embeds.append(groups_embed)
    return embeds


