# 9-TEAM PLAYOFF BRACKET WITH FINAL FOUR
# ═══════════════════════════════════════════════════════════════════════

def generate_9team_bracket(seeds_list: list, preseason_winner: str = None) -> dict:
    """
    Generate 9-team bracket with Final Four structure.
    
    Seeds 1-9 from regular season.
    Pre-season winner: Guaranteed Final Four (bumps down if not already 1-3).
    Seeds 4-9 (or 4-8 if PS winner is there): Play Round 1 (BO1).
    
    Final Four:
    - Seed #1 vs Round 1 Winner (BO3)
    - Seed #2 vs Seed #3 (BO3)
    - Winners → Championship (BO5)
    """
    if len(seeds_list) != 9:
        return None
    
    bracket = {
        'seeds': {i+1: seeds_list[i] for i in range(9)},
        'preseason_winner': preseason_winner,
        'preseason_seed': None,
        'final_four_teams': [],
        'round1_seeds': [],
        'round1_matches': [],
        'semis': {},
        'championship': {}
    }
    
    # Find Pre-Season Winner's seed
    if preseason_winner:
        for seed, team in bracket['seeds'].items():
            if team == preseason_winner:
                bracket['preseason_seed'] = seed
                break
    
    # Build Final Four teams
    ff_seeds = [1, 2, 3]
    
    # If PS winner is in top 3, they're already guaranteed
    # If PS winner is 4-9, they get the 4th spot, bumping the #4-9 group
    if bracket['preseason_seed'] and bracket['preseason_seed'] > 3:
        ff_seeds.append(bracket['preseason_seed'])
    
    bracket['final_four_teams'] = [bracket['seeds'][s] for s in ff_seeds]
    
    # Round 1: Seeds 4-9 (minus Pre-Season Winner if they're there)
    round1_seeds = list(range(4, 10))
    if bracket['preseason_seed'] and bracket['preseason_seed'] > 3:
        round1_seeds.remove(bracket['preseason_seed'])
    
    bracket['round1_seeds'] = round1_seeds
    
    # Build Round 1 matches (BO1, single elimination)
    # 6 seeds → 3 matches (or 5 seeds → 2 matches + 1 bye)
    if len(round1_seeds) == 6:
        bracket['round1_matches'] = [
            {
                'seeds': f"#{round1_seeds[0]} vs #{round1_seeds[1]}",
                'teams': (bracket['seeds'][round1_seeds[0]], bracket['seeds'][round1_seeds[1]])
            },
            {
                'seeds': f"#{round1_seeds[2]} vs #{round1_seeds[3]}",
                'teams': (bracket['seeds'][round1_seeds[2]], bracket['seeds'][round1_seeds[3]])
            },
            {
                'seeds': f"#{round1_seeds[4]} vs #{round1_seeds[5]}",
                'teams': (bracket['seeds'][round1_seeds[4]], bracket['seeds'][round1_seeds[5]])
            }
        ]
    
    # Final Four Semifinals
    bracket['semis'] = {
        'sf1': {
            'name': 'Semifinal 1',
            'team1': bracket['seeds'][1],
            'team2': 'Round 1 Winner',
            'series': 'Best of 3'
        },
        'sf2': {
            'name': 'Semifinal 2',
            'team1': bracket['seeds'][2],
            'team2': bracket['seeds'][3],
            'series': 'Best of 3'
        }
    }
    
    # Championship
    bracket['championship'] = {
        'name': 'Championship',
        'team1': 'Winner(SF1)',
        'team2': 'Winner(SF2)',
        'series': 'Best of 5'
    }
    
    return bracket


def format_bracket_embeds(bracket: dict) -> list:
    """Format 9-team bracket into Discord embeds."""
    embeds = []
    
    if not bracket:
        return embeds
    
    # Seeding
    seeds_embed = discord.Embed(
        title="🏀 Playoff Bracket — 9 Seeds",
        description="Final Four format with Round 1",
        color=discord.Color.purple()
    )
    
    for seed in range(1, 10):
        team = bracket['seeds'][seed]
        
        if seed <= 3:
            status = "✅ AUTOMATIC FINAL FOUR"
        elif bracket['preseason_seed'] == seed:
            status = f"👑 AUTO BID TO FF (Pre-Season Winner)"
        else:
            status = "🎯 Round 1 (BO1)"
        
        seeds_embed.add_field(
            name=f"#{seed}",
            value=f"{team}\n*{status}*",
            inline=True
        )
    
    embeds.append(seeds_embed)
    
    # Round 1 (Best of 1)
    if bracket['round1_matches']:
        r1_embed = discord.Embed(
            title="🎯 Round 1 (Best of 1)",
            description="Single elimination — 3 matches → 1 winner to Final Four",
            color=discord.Color.orange()
        )
        
        for i, match in enumerate(bracket['round1_matches'], 1):
            r1_embed.add_field(
                name=f"Match {i}: {match['seeds']}",
                value=f"🎮 **{match['teams'][0]}** vs **{match['teams'][1]}**",
                inline=False
            )
        
        embeds.append(r1_embed)
    
    # Final Four Semis (Best of 3)
    ff_embed = discord.Embed(
        title="🏅 Final Four — Semifinals (Best of 3)",
        description="Top 3 seeds + Round 1 winner",
        color=discord.Color.gold()
    )
    
    sf1 = bracket['semis']['sf1']
    ff_embed.add_field(
        name=sf1['name'],
        value=f"🎮 **{sf1['team1']}** vs **{sf1['team2']}**\n{sf1['series']}",
        inline=False
    )
    
    sf2 = bracket['semis']['sf2']
    ff_embed.add_field(
        name=sf2['name'],
        value=f"🎮 **{sf2['team1']}** vs **{sf2['team2']}**\n{sf2['series']}",
        inline=False
    )
    
    embeds.append(ff_embed)
    
    # Championship (Best of 5)
    champ_embed = discord.Embed(
        title="👑 Championship (Best of 5)",
        description="QCL Season Champion",
        color=discord.Color.red()
    )
    
    champ = bracket['championship']
    champ_embed.add_field(
        name=champ['name'],
        value=f"🎮 **{champ['team1']}** vs **{champ['team2']}**\n{champ['series']}\nFirst to 3 wins",
        inline=False
    )
    
    embeds.append(champ_embed)
    
    return embeds


