class SwissTeamSelectionView(discord.ui.View):
    def __init__(self, num_rounds: int):
        super().__init__(timeout=300)
        self.num_rounds = num_rounds
    
    @discord.ui.button(label="📚 Use Teams from Brain", style=discord.ButtonStyle.success)
    async def use_brain(self, interaction: discord.Interaction, button: discord.ui.Button):
        state = load_state()
        available = get_available_teams(state)
        
        if len(available) < 2:
            await interaction.response.send_message(f"❌ Need ≥2 teams ({len(available)} found)", ephemeral=True)
            return
        
        await interaction.response.defer()
        await self.confirm(interaction, available)
    
    @discord.ui.button(label="✏️ Enter Manually", style=discord.ButtonStyle.primary)
    async def enter_manual(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(SwissTeamEntryModal(self.num_rounds))
    
    async def confirm(self, interaction: discord.Interaction, teams: list):
        view = SwissConfirmationView(teams, self.num_rounds)
        teams_txt = ", ".join(teams[:5]) + ("..." if len(teams) > 5 else "")
        embed = discord.Embed(
            title=f"🏆 Pre-Season Swiss ({len(teams)} Teams)",
            description=f"{self.num_rounds} rounds\nWinner → Final Four auto-bid",
            color=discord.Color.blue()
        )
        embed.add_field(name=f"Teams (first 5 of {len(teams)})", value=teams_txt, inline=False)
        await interaction.followup.send(embed=embed, view=view)


