class SwissConfirmationView(discord.ui.View):
    def __init__(self, teams: list, num_rounds: int):
        super().__init__(timeout=300)
        self.teams = teams
        self.num_rounds = num_rounds
    
    @discord.ui.button(label="✅ Start", style=discord.ButtonStyle.success)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        
        matchups = {}
        standings = {t: {'wins': 0, 'losses': 0} for t in self.teams}
        
        for rnd in range(1, self.num_rounds + 1):
            matchups[rnd] = generate_swiss_round(self.teams, rnd, standings)
        
        embeds = format_swiss_embeds(self.teams, self.num_rounds, matchups)
        
        for i in range(0, len(embeds), 10):
            await interaction.followup.send(embeds=embeds[i:i+10])
    
