class RosterSheetManager:
    """Manage rosters in your existing Google Sheet."""
    
    def __init__(self, sheet_id: str = SHEET_ID):
        self.sheet_id = sheet_id
        self.gc = None
        self.sheet = None
    
    def authenticate(self) -> bool:
        """Authenticate with Google Sheets API."""
        try:
            scope = [
                'https://www.googleapis.com/auth/spreadsheets',
                'https://www.googleapis.com/auth/drive'
            ]
            creds = Credentials.from_service_account_file(
                "credentials.json",
                scopes=scope
            )
            self.gc = gspread.authorize(creds)
            self.sheet = self.gc.open_by_key(self.sheet_id)
            return True
        except Exception as e:
            print(f"❌ Google Sheets auth failed: {e}")
            return False
    
    def add_or_update_season(self, season: str, rosters: dict) -> tuple:
        """
        Add/update season rosters as a new worksheet.
        
        Returns: (success, sheet_url or error_message)
        """
        try:
            if not self.gc:
                self.authenticate()
            
            sheet_name = f"S{season}"
            
            # Try to get existing worksheet
            try:
                ws = self.sheet.worksheet(sheet_name)
                ws.clear()
            except gspread.WorksheetNotFound:
                # Create new worksheet
                ws = self.sheet.add_worksheet(title=sheet_name, rows=500, cols=10)
            
            # Prepare header and data rows
            rows = [['Discord_ID', 'Username', 'Team', 'Status', 'Joined_Date', 'Notes']]
            
            for team, players in rosters.items():
                for player in players:
                    rows.append([
                        player.get('discord_id', ''),
                        player.get('username', ''),
                        team,
                        'Active',
                        '',
                        ''
                    ])
            
            # Write to sheet
            ws.append_rows(rows, value_input_option='USER_ENTERED')
            
            # Format header
            ws.format('A1:F1', {
                'textFormat': {'bold': True},
                'backgroundColor': {'red': 0.2, 'green': 0.2, 'blue': 0.2}
            })
            
            return True, self.sheet.url
        
        except Exception as e:
            return False, str(e)


# ═══════════════════════════════════════════════════════════════════════
# ROSTER FILE PARSER (Handles messy formats)
# ═══════════════════════════════════════════════════════════════════════

def extract_discord_id(mention: str) -> str:
    """Extract Discord ID from mention (<@id> or <@&id>)."""
    match = re.search(r'<@&?(\d+)>', mention)
    return match.group(1) if match else None


def parse_roster_file(file_content: str) -> tuple:
    """
    Parse roster file (handles Discord mentions + usernames).
    
    Supported formats:
    1. Discord ID | Username | Team
    2. Team headers with Discord IDs, then usernames
    3. Mixed Discord mentions and usernames
    
    Returns: (season, {team: [{'discord_id', 'username'}, ...]})
    """
    rosters = {}
    season = None
    current_team = None
    current_discord_ids = {}
    current_usernames = {}
    
    lines = file_content.strip().split('\n')
    
    for line in lines:
        line = line.strip()
        
        if not line or line.startswith('#'):
            continue
        
        # Detect season (S1, S2, S7, etc.)
        season_match = re.match(r'^S(\d+)', line, re.IGNORECASE)
        if season_match:
            season = season_match.group(1)
            continue
        
        # Detect team name
        if any(x in line.lower() for x in ['team organization', 'lost generation', 'team obsidian', 'capitol city']):
            # Save previous team
            if current_team and (current_discord_ids or current_usernames):
                rosters[current_team] = combine_roster_data(current_discord_ids, current_usernames)
            
            # Extract team name
            if 'capitol city' in line.lower():
                current_team = 'Capitol City Cats'
            elif 'team obsidian' in line.lower():
                current_team = 'Team Obsidian'
            elif 'lost generation' in line.lower():
                current_team = 'Lost Generation'
            else:
                # Try to extract from role mention
                role_match = re.search(r'<@&(\d+)>', line)
                if role_match:
                    current_team = f"Team_{role_match.group(1)}"
                else:
                    current_team = f"Team_Unknown"
            
            current_discord_ids = {}
            current_usernames = {}
            continue
        
        # Parse lines with Discord mentions
        if '<@' in line:
            parts = line.split()
            if parts and parts[0].isdigit():
                number = parts[0]
                for mention in line.split():
                    discord_id = extract_discord_id(mention)
                    if discord_id:
                        current_discord_ids[number] = discord_id
                        break
        
        # Parse username lines
        elif line[0].isdigit() and '@' in line:
            parts = line.split(maxsplit=1)
            if parts:
                number = parts[0]
                username = parts[1].replace('@', '').strip() if len(parts) > 1 else ''
                if username:
                    current_usernames[number] = username
        
        elif line.startswith('@'):
            username = line.replace('@', '').strip()
            if username:
                # Auto-number
                next_num = str(len(current_usernames) + 1)
                current_usernames[next_num] = username
    
    # Save last team
    if current_team and (current_discord_ids or current_usernames):
        rosters[current_team] = combine_roster_data(current_discord_ids, current_usernames)
    
    return season, rosters


def combine_roster_data(discord_ids: dict, usernames: dict) -> list:
    """Combine Discord IDs and usernames."""
    roster = []
    all_numbers = set(discord_ids.keys()) | set(usernames.keys())
    
    for num in sorted(all_numbers, key=lambda x: int(x) if x.isdigit() else 999):
        discord_id = discord_ids.get(num)
        username = usernames.get(num, f'Unknown_{num}')
        
        if discord_id:  # Only add if we have Discord ID
            roster.append({
                'discord_id': discord_id,
                'username': username
            })
    
    return roster


def validate_rosters(rosters: dict) -> tuple:
    """Validate roster data."""
    if not rosters:
        return False, "No roster data found"
    
    total_players = sum(len(players) for players in rosters.values())
    if total_players == 0:
        return False, "No players found"
    
    for team, players in rosters.items():
        for player in players:
            discord_id = player.get('discord_id', '')
            if not re.match(r'^\d{17,19}$', discord_id):
                return False, f"Invalid Discord ID in {team}: {discord_id}"
            
            username = player.get('username', '').strip()
            if not username:
                return False, f"Missing username in {team}"
    
    return True, None


