class RosterApprovalView(discord.ui.View):
    """Approve roster upload."""
    
    def __init__(self, season: str, rosters: dict, team_count: int, player_count: int, filename: str):
        super().__init__(timeout=600)
        self.season = season
        self.rosters = rosters
        self.team_count = team_count
        self.player_count = player_count
        self.filename = filename
    
    @discord.ui.button(label="✅ Approve & Upload", style=discord.ButtonStyle.success)
    async def approve(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        
        # Save to state
        state = load_state()
        if 'rosters_by_season' not in state:
            state['rosters_by_season'] = {}
        state['rosters_by_season'][f'S{self.season}'] = self.rosters
        write_state(state)
        
        # Upload to Google Sheet
        manager = RosterSheetManager()
        if manager.authenticate():
            success, result = manager.add_or_update_season(self.season, self.rosters)
            
            if success:
                embed = discord.Embed(
                    title=f"✅ S{self.season} Roster Uploaded",
                    description=f"Teams: {self.team_count} | Players: {self.player_count}",
                    color=discord.Color.green()
                )
                embed.add_field(
                    name="Google Sheet",
                    value=f"[View S{self.season} Tab]({result}#gid=0)",
                    inline=False
                )
                embed.add_field(name="File", value=self.filename, inline=False)
                await interaction.followup.send(embed=embed)
            else:
                embed = discord.Embed(
                    title=f"⚠️ S{self.season} Saved Locally",
                    description=f"Error: {result}",
                    color=discord.Color.yellow()
                )
                await interaction.followup.send(embed=embed)
        else:
            embed = discord.Embed(
                title=f"⚠️ S{self.season} Rosters Saved (Local Only)",
                description="Google Sheets auth failed — rosters saved locally",
                color=discord.Color.yellow()
            )
            await interaction.followup.send(embed=embed)
    
    @discord.ui.button(label="❌ Reject", style=discord.ButtonStyle.danger)
    async def reject(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        await interaction.followup.send(f"❌ Rejected: {self.filename}", ephemeral=True)


