# ═══════════════════════════════════════════════════════════════════════

@admin_group.command(
    name="load_rosters",
    description="Upload rosters from file → Google Sheet"
)
@app_commands.describe(
    file="Roster file (.txt)",
    pin="Admin PIN"
)
async def load_rosters_command(interaction: discord.Interaction, file: discord.Attachment, pin: str):
    """Upload roster file and add to Google Sheet by season."""
    
    if not await verify_admin_pin(interaction, pin, "load_rosters"):
        return
    
    if not file.filename.lower().endswith('.txt'):
        await interaction.response.send_message("❌ File must be .txt format", ephemeral=True)
        return
    
    if file.size > 1024 * 100:
        await interaction.response.send_message("❌ File too large (max 100 KB)", ephemeral=True)
        return
    
    await interaction.response.defer()
    
    try:
        file_content = await file.read()
        file_text = file_content.decode('utf-8')
        
        # Parse roster
        season, rosters = parse_roster_file(file_text)
        
        if not season:
            await interaction.followup.send(
                "❌ Could not detect season (use S1, S2, S7, etc. in file)",
                ephemeral=True
            )
            return
        
        # Validate
        is_valid, error_msg = validate_rosters(rosters)
        if not is_valid:
            await interaction.followup.send(
                f"❌ Validation failed: {error_msg}",
                ephemeral=True
            )
            return
        
        team_count = len(rosters)
        player_count = sum(len(players) for players in rosters.values())
        
        # Show approval
        view = RosterApprovalView(season, rosters, team_count, player_count, file.filename)
        
        embed = discord.Embed(
            title=f"📋 S{season} Roster Upload",
            description="Review and approve",
            color=discord.Color.blue()
        )
        embed.add_field(name="File", value=file.filename, inline=False)
        embed.add_field(name="Teams", value=str(team_count), inline=True)
        embed.add_field(name="Players", value=str(player_count), inline=True)
        
        team_list = "\n".join([f"  • {team} ({len(players)})" for team, players in rosters.items()])
        embed.add_field(name="Breakdown", value=team_list, inline=False)
        
        await interaction.followup.send(embed=embed, view=view)
    
    except UnicodeDecodeError:
        await interaction.followup.send("❌ File encoding error (use UTF-8)", ephemeral=True)
    except Exception as e:
        await interaction.followup.send(f"❌ Error: {str(e)}", ephemeral=True)


@admin_group.command(
    name="rosters_status",
    description="[Admin] Check roster status"
)
@app_commands.describe(
    season="Season number (optional)",
    pin="Admin PIN"
)
async def rosters_status_command(interaction: discord.Interaction, season: int = None, pin: str = None):
    """Check roster status."""
    
    if not pin or not await verify_admin_pin(interaction, pin, "rosters_status"):
        return
    
    state = load_state()
    rosters_by_season = state.get('rosters_by_season', {})
    
    if not rosters_by_season:
        await interaction.response.send_message("❌ No rosters loaded", ephemeral=True)
        return
    
    if season:
        season_key = f'S{season}'
        if season_key not in rosters_by_season:
            await interaction.response.send_message(f"❌ No rosters for S{season}", ephemeral=True)
            return
        
        rosters = rosters_by_season[season_key]
        embed = discord.Embed(title=f"📋 S{season} Rosters", color=discord.Color.green())
        
        for team, players in rosters.items():
            player_list = "\n".join([f"  {p['username']}" for p in players[:5]])
            if len(players) > 5:
                player_list += f"\n  ... +{len(players)-5}"
            embed.add_field(name=f"{team} ({len(players)})", value=player_list, inline=False)
        
        await interaction.response.send_message(embed=embed, ephemeral=True)
    else:
        embed = discord.Embed(title="📋 All Rosters", color=discord.Color.blue())
        for season_key in sorted(rosters_by_season.keys()):
            rosters = rosters_by_season[season_key]
            total = sum(len(p) for p in rosters.values())
            embed.add_field(
                name=season_key,
                value=f"{len(rosters)} teams • {total} players",
                inline=True
            )
        await interaction.response.send_message(embed=embed, ephemeral=True)


