import re
import gspread
from google.oauth2.service_account import Credentials

# Your existing Google Sheet
SHEET_ID = "1rksLYUcXQJ03uTacfIBD6SRsvtH-IE6djqT-LINwcH4"
CREDENTIALS_FILE = "credentials.json"

# ═══════════════════════════════════════════════════════════════════════
# PARSER
# ═══════════════════════════════════════════════════════════════════════

def extract_discord_id(mention: str) -> str:
    """Extract Discord ID from mention format <@id> or <@&id>"""
    match = re.search(r'<@&?(\d+)>', mention)
    return match.group(1) if match else None


def parse_season7_roster(file_path: str) -> dict:
    """
    Parse Season 7 roster file.
    
    Returns: {team_name: [{'discord_id': str, 'username': str}, ...], ...}
    """
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()
    
    rosters = {}
    current_team = None
    current_discord_ids = {}
    current_usernames = {}
    
    lines = content.split('\n')
    i = 0
    
    while i < len(lines):
        line = lines[i].strip()
        i += 1
        
        # Skip empty lines
        if not line:
            continue
        
        # Detect team name
        if 'Team Organization' in line or 'Lost Generation' in line or 'Team Obsidian' in line or 'Capitol City' in line:
            # Save previous team if exists
            if current_team and (current_discord_ids or current_usernames):
                rosters[current_team] = combine_roster_data(current_discord_ids, current_usernames)
            
            # Determine team name
            if 'Capitol City' in line:
                current_team = 'Capitol City Cats'
            elif 'Team Obsidian' in line:
                current_team = 'Team Obsidian'
            elif 'Lost Generation' in line:
                current_team = 'Lost Generation'
            else:
                # Extract role name from Team Organization line
                role_match = re.search(r'<@&(\d+)>', line)
                if role_match:
                    current_team = f"Team_{role_match.group(1)}"
                else:
                    current_team = f"Team_Unknown_{i}"
            
            current_discord_ids = {}
            current_usernames = {}
            continue
        
        # Parse Discord mentions (roster phase)
        if '<@' in line and not line.startswith('@'):
            # Lines like: "1 <@1291561129780449394>"
            parts = line.split()
            if parts and parts[0].isdigit():
                number = parts[0]
                for mention in line.split():
                    discord_id = extract_discord_id(mention)
                    if discord_id:
                        current_discord_ids[number] = discord_id
                        break
        
        # Parse usernames (roster phase)
        elif line.startswith('@') or (line[0].isdigit() and '@' in line):
            # Lines like: "1 @Manu" or "@Manu"
            parts = line.split()
            if parts and parts[0].isdigit():
                number = parts[0]
                username = ' '.join(parts[1:]).replace('@', '').strip()
                if username:
                    current_usernames[number] = username
            elif line.startswith('@'):
                # Username without number (just add in order)
                username = line.replace('@', '').strip()
                if username:
                    next_number = str(len(current_usernames) + 1)
                    current_usernames[next_number] = username
    
    # Don't forget last team
    if current_team and (current_discord_ids or current_usernames):
        rosters[current_team] = combine_roster_data(current_discord_ids, current_usernames)
    
    return rosters


def validate_rosters(rosters: dict) -> tuple:
    """Validate parsed rosters."""
    if not rosters:
        return False, "No rosters parsed"
    
    total = sum(len(players) for players in rosters.values())
    if total == 0:
        return False, "No players found"
    
    # Check Discord ID validity
    for team, players in rosters.items():
        for player in players:
            if not re.match(r'^\d{17,19}$', player['discord_id']):
                return False, f"Invalid Discord ID in {team}: {player['discord_id']}"
    
    return True, None


