def upload_to_google_sheet(rosters: dict, sheet_id: str, season: str = "7"):
    """Upload rosters to existing Google Sheet."""
    
    try:
        # Authenticate
        scope = [
            'https://www.googleapis.com/auth/spreadsheets',
            'https://www.googleapis.com/auth/drive'
        ]
        creds = Credentials.from_service_account_file(CREDENTIALS_FILE, scopes=scope)
        gc = gspread.authorize(creds)
        
        # Open sheet
        sheet = gc.open_by_key(sheet_id)
        
        # Try to get S7 worksheet, create if not exists
        try:
            ws = sheet.worksheet(f'S{season}')
            ws.clear()
        except gspread.WorksheetNotFound:
            ws = sheet.add_worksheet(title=f'S{season}', rows=1000, cols=10)
        
        # Prepare rows
        rows = [['Discord_ID', 'Username', 'Team', 'Status', 'Joined', 'Notes']]
        
        for team, players in rosters.items():
            for player in players:
                rows.append([
                    player['discord_id'],
                    player['username'],
                    team,
                    'Active',
                    '',
                    ''
                ])
        
        # Write to sheet
        ws.append_rows(rows, value_input_option='USER_ENTERED')
        
        # Format header (bold)
        ws.format('A1:F1', {
            'textFormat': {'bold': True},
            'backgroundColor': {'red': 0.2, 'green': 0.2, 'blue': 0.2}
        })
        
        print(f"✅ Uploaded {len(rows)-1} rows to {sheet.url}")
        return True
    
    except Exception as e:
        print(f"❌ Error: {e}")
        return False


