class AddPlayerModal(discord.ui.Modal, title='Request Player Addition'):
    player_name = discord.ui.TextInput(label='Player Gamertag / Name', placeholder='Enter name...')
    discord_id = discord.ui.TextInput(label='Player Discord ID', placeholder='1234567890', required=True)
    
    def __init__(self, team_name):
        super().__init__()
        self.team_name = team_name
        
    async def on_submit(self, interaction: discord.Interaction):
        state = load_state()
        roster_data = state.setdefault('rosters', {}).setdefault(self.team_name, {'active': [], 'inactive': []})
        
        if len(roster_data['active']) >= 10:
            return await interaction.response.send_message("🚫 **Active Roster Limit Reached!** Max 10 players. Drop a player first.", ephemeral=True)
        
        # Send to Admin queue
        state.setdefault('pending_roster_moves', []).append({
            'type': 'add', 'team': self.team_name, 
            'gamertag': self.player_name.value, 'discord_id': self.discord_id.value
        })
        save_state(state)
        await interaction.response.send_message(f"⏳ **Request Sent:** Addition of **{self.player_name.value}** sent to Admin Hub for approval.", ephemeral=True)

class DropPlayerSelect(discord.ui.Select):
    def __init__(self, team_name, active_roster):
        self.team_name = team_name
        if not active_roster:
            options = [discord.SelectOption(label="No active players on roster", value="NONE")]
        else:
            options = [discord.SelectOption(label=p, value=p) for p in active_roster]
        super().__init__(placeholder="Select an active player to drop...", min_values=1, max_values=1, options=options)
        self.disabled = not active_roster

    async def callback(self, interaction: discord.Interaction):
        player = self.values[0]
        if player == "NONE": return
        state = load_state()
        
        # Send drop request to admin queue
        state.setdefault('pending_roster_moves', []).append({
            'type': 'drop', 'team': self.team_name, 'gamertag': player
        })
        save_state(state)
        await interaction.response.send_message(f"⏳ **Request Sent:** Dropping **{player}** from active roster sent to Admin Hub for approval.", ephemeral=True)

