class TrapOverrideModal(discord.ui.Modal, title='Emergency System Override'):
    admin_pin = discord.ui.TextInput(label='Enter Master Admin PIN', placeholder='4-digit code', min_length=4, max_length=4)

    def __init__(self, parent_view):
        super().__init__()
        self.parent_view = parent_view

    async def on_submit(self, interaction: discord.Interaction):
        if not admin_pin_matches(self.admin_pin.value):
            # If someone tries to guess the override and fails, they still blow up.
            return await interaction.response.send_message("❌ **INVALID OVERRIDE CODE.** The timer is still ticking!", ephemeral=True)
            
        # If YOU put in the right Admin PIN, defuse the bomb instantly
        self.parent_view.defused = True
        for child in self.parent_view.children: child.disabled = True
        
        embed = discord.Embed(title="🛡️ SYSTEM OVERRIDE ACCEPTED", description="Bomb deactivated. Welcome back, Mr. Mayor. (Run the command again with the right PIN).", color=0x32D74B)
        await interaction.response.edit_message(embed=embed, view=self.parent_view)
        self.parent_view.stop()

class SecurityTrapView(discord.ui.View):
    def __init__(self, user_id):
        super().__init__(timeout=10.0) # They have exactly 10 seconds to guess
        self.user_id = str(user_id)
        self.safe_wire = random.choice(["red", "blue", "green"])
        self.defused = False

    async def on_timeout(self):
        if not self.defused:
            # Time ran out! Send them to jail.
            state = load_state()
            state = init_rpg_profile(self.user_id, state)
            state['rpg'][self.user_id]['jail_time'] = 24
            state['rpg'][self.user_id]['rep'] = "Busted (Mayor's Office)"
            save_state(state)
            
            for child in self.children: child.disabled = True
            embed = discord.Embed(title="💥 BOOM! TIME RAN OUT!", description=f"The security system deployed the gas. You woke up in the Penitentiary with a 24-hour sentence.", color=0xFF453A)
            
            # Since timeouts don't have interactions, the original command loop handles the message edit
            pass

    async def handle_cut(self, interaction: discord.Interaction, wire_color: str):
        if str(interaction.user.id) != self.user_id:
            return await interaction.response.send_message("Back up, this isn't your trap!", ephemeral=True)
            
        self.defused = True
        for child in self.children: child.disabled = True
        
        if wire_color == self.safe_wire:
            embed = discord.Embed(title="😅 WIRE CUT!", description="You cut the right wire... The alarm deactivated. Run before the cops get here!", color=0x32D74B)
            await interaction.response.edit_message(embed=embed, view=self)
        else:
            state = load_state()
            state = init_rpg_profile(self.user_id, state)
            state['rpg'][self.user_id]['jail_time'] = 24
            state['rpg'][self.user_id]['rep'] = "Busted (Mayor's Office)"
            save_state(state)
            
            embed = discord.Embed(title="💥 WRONG WIRE!", description=f"The security system went off. You were arrested and sentenced to **24 hours in the Penitentiary**.", color=0xFF453A)
            await interaction.response.edit_message(embed=embed, view=self)
            
        self.stop()

    @discord.ui.button(label="Cut Red Wire", style=discord.ButtonStyle.danger, emoji="🔴")
    async def cut_red(self, interaction, button): await self.handle_cut(interaction, "red")

    @discord.ui.button(label="Cut Blue Wire", style=discord.ButtonStyle.primary, emoji="🔵")
    async def cut_blue(self, interaction, button): await self.handle_cut(interaction, "blue")

    @discord.ui.button(label="Cut Green Wire", style=discord.ButtonStyle.success, emoji="🟢")
    async def cut_green(self, interaction, button): await self.handle_cut(interaction, "green")
    
    # --- NEW: THE MAYOR'S BACKDOOR ---
    @discord.ui.button(label="System Override", style=discord.ButtonStyle.secondary, emoji="🛑")
    async def emergency_override(self, interaction, button):
        if str(interaction.user.id) != self.user_id:
            return await interaction.response.send_message("You don't have clearance for this.", ephemeral=True)
        await interaction.response.send_modal(TrapOverrideModal(self))

