class PinSetupModal(discord.ui.Modal, title='Security: Setup Your PIN'):
    new_pin = discord.ui.TextInput(label='Enter New 4-Digit PIN', placeholder='e.g. 9999', min_length=4, max_length=4)
    quote = discord.ui.TextInput(label='Player Quote (Talk your trash)', style=discord.TextStyle.short, placeholder='"Best PG in the league."', required=False, max_length=100)

    def __init__(self, team_name, gamertag, pending_coach_team=None):
        super().__init__()
        self.team_name = team_name
        self.gamertag = gamertag
        self.pending_coach_team = pending_coach_team

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        state = load_state()
        uid = str(interaction.user.id)
        
        state = init_rpg_profile(uid, state)
        user_data = state.setdefault('users', {}).setdefault(uid, {})
        user_data['pin'] = self.new_pin.value
        user_data['pin_changed'] = True
        user_data['team'] = self.team_name
        user_data['gamertag'] = self.gamertag
        user_data['quote'] = self.quote.value.strip() if self.quote.value.strip() else "I let my game speak for itself."
        
        vc = state.get('balances', {}).get(uid, 0)
        sb = state.get('rpg', {}).get(uid, {}).get('cupbucks', 0)
        # If they onboarded as a Coach, queue an admin-approval request now.
        coach_note = ""
        if self.pending_coach_team:
            file_role_request(state, uid, interaction.user.display_name, "to_coach", team=self.pending_coach_team)
            coach_note = (f"\n\n👔 Your **Coach** request for **{self.pending_coach_team}** was submitted — "
                          f"once an admin approves it, the Coach Desk and all `/coach` commands unlock. "
                          f"Run `/coach help` to preview them.")
        save_state(state)
        
        try:
            payload = {
                "secret": "SPAM_BOT_SECRET_123",
                "sheet": "SPAM_Registry",
                "action": "append_multiple",
                "data": [[uid, self.gamertag, self.team_name, user_data['quote'], vc, sb]]
            }
            def _post(): return requests.post(APPS_SCRIPT_URL, json=payload)
            await asyncio.to_thread(_post)
        except Exception as e:
            print(f"Error appending onboarding to sheets: {e}")

        await interaction.followup.send(f"✅ **PIN Saved securely!** Welcome to the QCL.{coach_note}", ephemeral=True)
        
        # Send the @everyone ping with the embed
        embed = discord.Embed(title=f"🚨 NEW QCL MEMBER: {self.gamertag}", description=f"*{user_data['quote']}*", color=0xFFD60A)
        embed.add_field(name="Requested Franchise", value=f"🏢 {self.team_name}", inline=True)
        embed.add_field(name="Player", value=interaction.user.mention, inline=True)
        if interaction.user.display_avatar:
            embed.set_thumbnail(url=interaction.user.display_avatar.url)
        embed.set_footer(text="Use /my_life to view your full live ID card.")
        
        await interaction.channel.send(content="@everyone 🚨 **A new player has entered the QCL!**", embed=embed)

@bot.tree.command(name="onboard", description="Register your Gamertag and Team for the Qwik's Cup League.")
@app_commands.autocomplete(team=team_autocomplete)
@app_commands.describe(team="Your franchise", gamertag="Your in-game name", role="Join as a Player, or request Coach access (admin-approved)")
@app_commands.choices(role=[
    app_commands.Choice(name="Player", value="player"),
    app_commands.Choice(name="Coach (needs admin approval)", value="coach"),
])
async def onboard(interaction: discord.Interaction, team: str, gamertag: str, role: app_commands.Choice[str] = None):
    state = load_state()
    uid = str(interaction.user.id)
    wants_coach = role is not None and role.value == "coach"
    # ── Registration payment (charged once; posts to payments channel) ──
    try:
        await _maybe_invoice_registration(interaction)
    except Exception as _re:
        print(f"[REG] invoice error: {_re}")
    
    # Safely grab or create the user profile
    if 'users' not in state: state['users'] = {}
    if uid not in state['users']: state['users'][uid] = {}
    user_data = state['users'][uid]
    
    # Use .get() so it defaults to False if the key doesn't exist in older profiles
    if not user_data.get('pin_changed', False):
        await interaction.response.send_modal(PinSetupModal(team, gamertag, pending_coach_team=(team if wants_coach else None)))
    else:
        user_data['team'] = team
        user_data['gamertag'] = gamertag
        coach_note = ""
        if wants_coach and not user_is_coach(uid, state):
            file_role_request(state, uid, interaction.user.display_name, "to_coach", team=team)
            coach_note = (f"\n\n👔 **Coach request submitted** for **{team}** — an admin approves it, "
                          f"then the Coach Desk and all `/coach` commands unlock. Preview with `/coach help`.")
            try:
                if BOT_OWNER_ID:
                    owner = await bot.fetch_user(BOT_OWNER_ID)
                    await owner.send(f"👔 Coach request (via onboard): {interaction.user} wants to coach **{team}**. Review in `/admin_hub`.")
            except Exception:
                pass
        save_state(state)
        
        try:
            vc = state.get('balances', {}).get(uid, 0)
            sb = state.get('rpg', {}).get(uid, {}).get('cupbucks', 0)
            payload = {
                "secret": "SPAM_BOT_SECRET_123",
                "sheet": "SPAM_Registry",
                "action": "append_multiple",
                "data": [[uid, gamertag, team, user_data.get('quote', 'I let my game speak for itself.'), vc, sb]]
            }
            def _post(): return requests.post(APPS_SCRIPT_URL, json=payload)
            await asyncio.to_thread(_post)
        except: pass
        await interaction.response.send_message(f"✅ **Onboarding Updated!**\nGamertag: `{gamertag}`\nTeam: `{team}`\n*Sent to the Admin desk.*{coach_note}", ephemeral=True)

# --- UPDATED BOXSCORE SUBMISSION LOGIC ---

class BoxscoreAdminAuthModal(discord.ui.Modal, title='Admin Authorization'):
    pin = discord.ui.TextInput(label='Enter Admin PIN to Push', min_length=4, max_length=4)
    def __init__(self, parent_view):
        super().__init__()
        self.parent_view = parent_view
        
    async def on_submit(self, interaction: discord.Interaction):
        if not admin_pin_matches(self.pin.value):
            return await interaction.response.send_message("❌ **Invalid PIN.** Push cancelled.", ephemeral=True)

        # Never allow an edited or stale admin-review view to bypass the
        # parser contract. Validation is repeated because the admin message
        # can remain open while another editor changes the table.
        validation_errors = _bx_validate_boxscore(
            self.parent_view.data_json,
            self.parent_view.your_team,
            self.parent_view.opponent,
        )
        if validation_errors:
            preview = "\n".join(f"• {item}" for item in validation_errors[:8])
            return await interaction.response.send_message(
                "❌ **Push blocked — the box score is not valid.**\n"
                f"{preview}\n\n"
                "Return to the editor, correct the highlighted data, and send it "
                "to Admin again.",
                ephemeral=True,
            )

        await interaction.response.send_message("🔐 PIN Accepted. Pushing data to Google Sheets...", ephemeral=True)
        rows_to_push = []
        for r in self.parent_view.data_json:
            
            # The validator has already required an exact match to one of the
            # two submitted teams.
            team_name = str(r.get("Team Name", self.parent_view.your_team))
            
            # Ensure the win/loss binary is assigned correctly to the right team
            is_submitter_team = (team_name.lower() == self.parent_view.your_team.lower())
            row_win_val = int(self.parent_view.win_val) if is_submitter_team else (1 - int(self.parent_view.win_val))
            # ---------------

            row = [
                str(r.get("Player/Team", "Unknown")),
                str(r.get("Type", "Player")),
                str(r.get("GRD", "N/A")),
                int(safe_int(r.get("PTS", 0))),
                int(safe_int(r.get("REB", 0))),
                int(safe_int(r.get("AST", 0))), 
                int(safe_int(r.get("STL", 0))),
                int(safe_int(r.get("BLK", 0))),
                int(safe_int(r.get("FOULS", 0))), 
                int(safe_int(r.get("TO", 0))),
                int(safe_int(r.get("FGM", 0))),
                int(safe_int(r.get("FGA", 0))), 
                int(safe_int(r.get("3PM", 0))),
                int(safe_int(r.get("3PA", 0))),
                int(safe_int(r.get("FTM", 0))), 
                int(safe_int(r.get("FTA", 0))), 
                int(self.parent_view.game_id),
                team_name,    # Replaced self.parent_view.opponent
                row_win_val,  # Replaced self.parent_view.win_val
                int(self.parent_view.season),
                int(safe_int(r.get("OREB", 0))),
                int(safe_int(r.get("DREB", 0))),
                int(safe_int(r.get("MIN", 0))),
                int(safe_int(r.get("Q1", 0))),
                int(safe_int(r.get("Q2", 0))),
                int(safe_int(r.get("Q3", 0))),
                int(safe_int(r.get("Q4", 0)))
            ]
            rows_to_push.append(row)

        payload = {
            "secret": "SPAM_BOT_SECRET_123",
            "sheet": "Raw Data",
            "action": "append_multiple",
            "data": rows_to_push
        }

        try:
            def _post_boxscore(): 
                headers = {'Content-Type': 'application/json'}
                return requests.post(APPS_SCRIPT_URL, data=json.dumps(payload), headers=headers, allow_redirects=True)
                
            response = await asyncio.to_thread(_post_boxscore)

            # Guard: detect Google's HTML 404 page (dead Apps Script deployment)
            content_start = response.text[:300].lstrip().lower()
            if content_start.startswith("<!doctype") or "<html" in content_start:
                embed = discord.Embed(
                    title="❌ Apps Script URL Problem",
                    description=(
                        "Google returned a **Page Not Found** page instead of running your script.\n\n"
                        "Your `APPS_SCRIPT_URL` deployment is dead or wrong. To fix:\n"
                        "**Extensions → Apps Script → Deploy → New deployment → Web app → "
                        "Execute as: Me → Access: Anyone**, then copy the new `/exec` URL "
                        "into your `.env` and restart the bot."
                    ),
                    color=0xFF453A
                )
                await interaction.followup.send(embed=embed)
                return

            if response.status_code == 200 and "Error" not in response.text:
                result_preview = str(response.text)[:900]
                embed = discord.Embed(title="✅ Pushed to Sheets", description=f"```{result_preview}```", color=0x30D158)
                await interaction.followup.send(embed=embed)
            else:
                error_preview = str(response.text)[:900]
                embed = discord.Embed(title="⚠️ AppScript Error", description=f"```{error_preview}```", color=0xFF9F0A)
                await interaction.followup.send(embed=embed)

            self.parent_view.stop()
        except Exception as e:
            error_str = str(e)[:900]
            embed = discord.Embed(title="❌ Failed to Push to Sheets", description=f"**Python Request Error:**\n```{error_str}```", color=0xFF453A)
            await interaction.followup.send(embed=embed)

class AdminPushBoxscoreView(discord.ui.View):
    def __init__(self, data_json, your_team, opponent, win_val, image_url, submitter_name, season, game_type, game_id, notes="None"):
        super().__init__(timeout=None)
        self.data_json = data_json
