@admin_group.command(name="lockgame", description="[Admin] Lock a matchup and generate 50 Sharp Bets for the board.")
@app_commands.autocomplete(team1=roster_team_autocomplete, team2=roster_team_autocomplete)
async def admin_lockgame(interaction: discord.Interaction, team1: str, team2: str):
    await interaction.response.defer(ephemeral=True)
    bets, readout = run_1287_monte_carlo(team1, team2)
    if not bets: return await interaction.followup.send(readout)
    
    state = load_state()
    game_key = f"{team1} vs {team2}"

    # Generate + save the QSPN preview article (same Monte Carlo + Gemini engine
    # as the slate-approval lock) so /previews always has a readable breakdown
    # for an admin-locked game. A preview/AI failure never blocks the lock.
    preview_text = None
    _pv_err = None

    # 1) Build the sim context. Prefer the granular sim; if it throws, fall back
    #    to the Monte Carlo readout we already have from run_1287_monte_carlo.
    _sim_context = None
    try:
        sim_data = simulate_granular_matchup(team1, team2, _cached_df, is_playoffs=False, is_tournament=False)
        _sim_context = json.dumps(sim_data, default=str)  # default=str: numpy/other types can't crash it
    except Exception as _se:
        print(f"[LockGame] granular sim failed, using readout: {_se}")
        _sim_context = str(readout)[:3500] if readout else f"{team1} vs {team2} — neutral-court matchup."

    # 2) Generate the article, guarding the AI call and the .text access.
    if ai_client is None:
        _pv_err = "Gemini not configured (no GEMINI_API_KEY)"
    else:
        _pv_prompt = f"""You are the lead QSPN analyst. The Commissioner just locked the betting slate for {team1} vs {team2}.
Here is the matchup simulation data (Neutral Court 2K Matchmaking):
{_sim_context}

INSTRUCTIONS:
1. HYPE THE MATCHUP: if it reads like a rivalry or a playoff clash, amplify the pressure.
2. Break down the clash of defensive schemes and which archetypes thrive or choke.
3. Give your official Oracle prediction based on the numbers.
4. Keep it under 1500 characters."""
        try:
            def _fetch_lock_preview():
                return ai_client.models.generate_content(model='gemini-3.6-flash', contents=_pv_prompt)
            _ai_resp = await asyncio.to_thread(_fetch_lock_preview)
            preview_text = getattr(_ai_resp, "text", None)
            if not preview_text:
                # blocked / empty candidates — dig out any text parts if present
                try:
                    _parts = _ai_resp.candidates[0].content.parts
                    preview_text = "".join(getattr(p, "text", "") for p in _parts).strip() or None
                except Exception:
                    preview_text = None
                if not preview_text:
                    _pv_err = "Gemini returned no text (possibly safety-blocked)"
        except Exception as _ae:
            _pv_err = f"{type(_ae).__name__}: {_ae}"
            print(f"[LockGame] AI preview failed: {_ae}")

    _game_rec = {"bets": bets, "timestamp": time.time()}
    if preview_text:
        _game_rec["preview"] = preview_text
    state.setdefault('locked_games', {})[game_key] = _game_rec
    save_state(state)

    log_admin_action(interaction.user.display_name, "Vegas", f"Locked Game Board: {game_key}")
    if preview_text:
        _pv_note = "📰 QSPN preview saved — read it in `/office previews`"
    else:
        _pv_note = f"⚠️ preview unavailable — game still locked\n`{str(_pv_err)[:280]}`"
    await interaction.followup.send(f"✅ **Game Locked:** {game_key}. 50 Sharp Props posted to the Shack.\n{_pv_note}")

