@bot.tree.command(name="bringmemymoney", description="Cash out your verified winning tickets from the Cashier Desk.")
async def bringmemymoney(interaction: discord.Interaction):
    state = load_state()
    uid = str(interaction.user.id)
    
    winnings = 0
    cashed_slips = []
    for bid, data in state.get('bets', {}).items():
        if data['uid'] == uid and data['status'] == 'Won_Pending_Payout':
            winnings += data['payout']
            cashed_slips.append(bid)
            state['bets'][bid]['status'] = 'Cashed_Out'
            
    if winnings == 0: return await interaction.response.send_message("🚫 You have no verified winning slips at the cashier desk.")
    
    state['balances'][uid] = state['balances'].get(uid, 0) + winnings
    save_state(state)
    await interaction.response.send_message(f"💰 **CASH OUT SUCCESSFUL!**\nTickets `{', '.join(cashed_slips)}` cleared.\n**{winnings:,} VC** has been added to your bank.")

