@admin_group.command(name="edit", description="[Admin] Directly edit a user's VC Balance, Franchise, or PIN.")
@app_commands.describe(
    pin="Your Master Admin PIN",
    target_user="Select the Discord User you want to edit",
    setting="What do you want to change for this user?",
    new_value="Type the new amount, new team name, or new PIN"
)
@app_commands.choices(setting=[
    app_commands.Choice(name="💰 Bank Balance (VC)", value="balance"),
    app_commands.Choice(name="🏢 Assigned Franchise", value="team"),
    app_commands.Choice(name="🔐 Franchise PIN", value="pin")
])
async def admin_edit(interaction: discord.Interaction, pin: str, target_user: discord.Member, setting: app_commands.Choice[str], new_value: str):
    if not admin_pin_matches(pin, interaction): return await interaction.response.send_message("🚫 **Access Denied.**", ephemeral=True)
    
    state = load_state()
    uid = str(target_user.id)
    old_value = "NONE"
    
    try:
        if setting.value == "balance":
            old_value = state.setdefault('balances', {}).get(uid, 0)
            new_val_parsed = int(new_value)
            state['balances'][uid] = new_val_parsed
            
        elif setting.value == "team":
            old_value = state.setdefault('team_claims', {}).get(uid, {}).get('team', "No Team")
            if uid not in state['team_claims']: state['team_claims'][uid] = {'pin': '0000'}
            state['team_claims'][uid]['team'] = new_value
            new_val_parsed = new_value
            
        elif setting.value == "pin":
            old_value = state.setdefault('team_claims', {}).get(uid, {}).get('pin', "No PIN")
            if uid not in state['team_claims']: state['team_claims'][uid] = {'team': 'Unassigned'}
            state['team_claims'][uid]['pin'] = new_value
            new_val_parsed = new_value
        
        save_state(state)
        log_admin_action(interaction.user.display_name, "System", f"Edited {target_user.display_name}'s {setting.name} to {new_val_parsed}")
        
        embed = discord.Embed(title="✅ State Updated Internally", color=0x32D74B)
        embed.add_field(name="Target User", value=target_user.mention, inline=False)
        embed.add_field(name="Setting Changed", value=setting.name, inline=False)
        embed.add_field(name="Old Value", value=f"`{old_value}`", inline=True)
        embed.add_field(name="New Value", value=f"`{new_val_parsed}`", inline=True)
        
        await interaction.response.send_message(embed=embed, ephemeral=True)
        
    except ValueError:
        await interaction.response.send_message("❌ **Error:** If changing Bank Balance, new_value must be a number! (e.g. 50000)", ephemeral=True)
    except Exception as e:
        await interaction.response.send_message(f"❌ **Error:** `{e}`", ephemeral=True)

@admin_group.command(name="upload", description="[ADMIN] Bulk upload up to 7 files. The bot will auto-sort them into folders.")
@app_commands.describe(
    pin="Your Master Admin PIN",
    file1="First file", file2="Second file", file3="Third file", 
    file4="Fourth file", file5="Fifth file", file6="Sixth file", file7="Seventh file"
)
async def admin_upload(interaction: discord.Interaction, pin: str, 
                       file1: discord.Attachment, 
                       file2: discord.Attachment = None, 
                       file3: discord.Attachment = None, 
                       file4: discord.Attachment = None, 
                       file5: discord.Attachment = None,
                       file6: discord.Attachment = None,
                       file7: discord.Attachment = None):
    
    # Defer so Discord doesn't timeout while downloading large files
    await interaction.response.defer(ephemeral=True)
    
    if not admin_pin_matches(pin, interaction):
        return await interaction.followup.send("🚫 **Access Denied.** Invalid PIN.")
        
    # The master directory where all folders will be built
    base_path = r"E:\AI Helper\New folder"
    
    # Collect all the files you actually attached
    files_to_process = [f for f in [file1, file2, file3, file4, file5, file6, file7] if f is not None]
    success_msgs = []
    
    for file in files_to_process:
        # Check the file extension to see what kind of file it is
        ext = file.filename.split('.')[-1].lower() if '.' in file.filename else 'unknown'
        
        # --- THE AUTO-SORTING ENGINE ---
        if ext in ['png', 'jpg', 'jpeg', 'gif', 'webp']: subfolder = "Graphics"
        elif ext in ['mp4', 'mov', 'avi', 'webm', 'mkv']: subfolder = "Videos"
        elif ext in ['pdf']: subfolder = "PDFs"
        elif ext in ['csv', 'xlsx']: subfolder = "Spreadsheets"
        elif ext in ['txt', 'docx', 'md', 'json']: subfolder = "Documents"
        elif ext in ['mp3', 'wav', 'ogg']: subfolder = "Audio"
        else: subfolder = "Misc_Files" # Catches anything weird
        
        # Create the specific folder if it doesn't exist yet
        target_dir = os.path.join(base_path, subfolder)
        if not os.path.exists(target_dir):
            os.makedirs(target_dir)
            
        file_path = os.path.join(target_dir, file.filename)
        
        try:
            # Save the file to your PC
            await file.save(file_path)
            
            # If it's a PDF, keep the AI Brain injection feature!
            if ext == 'pdf':
                def _upload_to_brain():
                    return ai_client.files.upload(file=file_path)
                
                uploaded_gemini = await asyncio.to_thread(_upload_to_brain)
                uploaded_gemini_files[file.filename] = uploaded_gemini
                success_msgs.append(f"🧠 `{file.filename}` sorted to `PDFs` & injected into AI Brain.")
            else:
                # Standard success message for everything else
                success_msgs.append(f"📁 `{file.filename}` auto-sorted into `{subfolder}`.")
                
        except Exception as e:
            success_msgs.append(f"❌ Failed to upload `{file.filename}`: {e}")
            
    # Send a clean report of everything the bot sorted for you
    report = "\n".join(success_msgs)
    await interaction.followup.send(f"**Bulk Upload Report:**\n{report}")

