# --- AUTOCOMPLETE FOR LOCKED GAMES ---
async def locked_game_autocomplete(interaction: discord.Interaction, current: str):
    state = load_state()
    games = list(state.get('locked_games', {}).keys())
    matches = [g for g in games if current.lower() in g.lower()][:25]
    return [app_commands.Choice(name=m, value=m) for m in matches]

# --- MANAGE LOCKED GAME COMMAND ---
@admin_group.command(name="manage_game", description="[Admin] Mark a locked game as Played, Cancelled, or Removed.")
@app_commands.describe(pin="Master Admin PIN", game_key="Select the matchup", action="What to do with this game board")
@app_commands.autocomplete(game_key=locked_game_autocomplete)
@app_commands.choices(action=[
    app_commands.Choice(name="🛑 Close Betting (Game Played/Started)", value="played"),
    app_commands.Choice(name="🗑️ Remove (Delete from Board)", value="removed"),
    app_commands.Choice(name="❌ Cancelled (Delete & Need to Refund)", value="cancelled")
])
async def admin_manage_game(interaction: discord.Interaction, pin: str, game_key: str, action: app_commands.Choice[str]):
    if not admin_pin_matches(pin, interaction): 
        return await interaction.response.send_message("🚫 **Access Denied.**", ephemeral=True)
    
    state = load_state()
    
    if 'locked_games' in state and game_key in state['locked_games']:
        del state['locked_games'][game_key]
        save_state(state)
        
        act_val = action.value
        if act_val == "played":
            msg = f"🛑 **Betting Closed:** **{game_key}** has started/played. It is no longer taking bets on the Vegas board."
            log_act = f"Closed action on {game_key}"
        elif act_val == "removed":
            msg = f"🗑️ **Removed:** **{game_key}** was removed from the Vegas board."
            log_act = f"Removed {game_key}"
        else:
            msg = f"❌ **Cancelled:** **{game_key}** has been cancelled and removed from the board. *(Note: You will need to manually nullify/refund any pending slips in the Vegas Vault!)*"
            log_act = f"Cancelled {game_key}"
            
        log_admin_action(interaction.user.display_name, "Vegas", log_act)
        await interaction.response.send_message(msg, ephemeral=True)
    else:
        await interaction.response.send_message(f"⚠️ **Not Found:** `{game_key}` is not currently on the board.", ephemeral=True)

