@bot.tree.command(name="cupmuse", description="Ask the AI anything about QCL Stats (Powered by Gemini 2.5 Flash)")
async def cupmuse(interaction: discord.Interaction, question: str):
    # 1. Safely defer to prevent the 10062 crash from blowing up the console
    try:
        await interaction.response.defer(thinking=True)
    except Exception:
        print("Discord timed out the request before the bot could answer.")
        return 
        
    df = _cached_df
    if df is None: return await interaction.followup.send("⚠️ Stat Engine is warming up! Try again in 10s.")
    
    try:
        p_df = df[df['Type'].str.lower() == 'player']
        t_df = df[df['Type'].str.lower() == 'team']
        
        # 2. Grab GP and explicitly rename it so the AI doesn't get confused
        p_stats = p_df.groupby('Player/Team').agg({'GP':'first', 'PTS':'mean', 'REB':'mean', 'AST':'mean', 'STL':'mean', 'BLK':'mean'}).round(1)
        p_stats.rename(columns={'GP': 'Games_Played'}, inplace=True)
        top_p = p_stats.sort_values('PTS', ascending=False).head(40).to_csv()
        
        # Team stats with explicit Losses + pre-formatted W-L Record (so the AI
        # never reports Games Played as losses — 18 wins in 27 GP is 18-9, not 18-27).
        t_grp = t_df.groupby('Team Name').agg({'GP':'first', 'PTS':'mean', 'Win':'sum'}).round(1).reset_index()
        t_grp['GP'] = t_grp['GP'].astype(int)
        t_grp['Win'] = t_grp['Win'].astype(int)
        t_grp['Loss'] = (t_grp['GP'] - t_grp['Win']).clip(lower=0)
        t_grp['Record'] = t_grp['Win'].astype(str) + '-' + t_grp['Loss'].astype(str)
        t_stats = t_grp[['Team Name', 'Record', 'Win', 'Loss', 'GP', 'PTS']].to_csv(index=False)
        
        # 3. Update the prompt to force the AI to recognize the Games Played column
        prompt = f"You are 'CupMuse', the official AI statistician for the QCL.\n{QCL_LORE}\nAnswer the user's question clearly, like StatMuse would, using ONLY the following data context. Keep it under 1500 characters.\n\nCRITICAL RULE: The column 'Games_Played' represents exactly how many games a player has played. You MUST use this column if someone asks about games played. A team's win-loss record is the 'Record' column (Wins-Losses), e.g. '18-9' — NEVER use Games Played (GP) as the loss count.\n\n--- PLAYER STATS ---\n{top_p}\n\n--- TEAM STATS ---\n{t_stats}\n\nUser Question: {question}"
        
        def _fetch_cupmuse():
            return ai_client.models.generate_content(
                model='gemini-3.6-flash',
                contents=prompt
            )
            
        response = await asyncio.to_thread(_fetch_cupmuse)
        
        return await interaction.followup.send(f"🧠 **CupMuse (Gemini AI):**\n\n{response.text[:1800]}")
    except Exception as e:
        pass # If Gemini fails, we fall back to the hardcoded math below
        
    p_df = df[df['Type'].str.lower() == 'player']
    q = question.lower()
    
    response = f"🧠 **CupMuse Analysis for:** *\"{question}\"*\n\n"
    
    match = re.search(r'(\d+)\s*point games', q)
    if match:
        pts_target = int(match.group(1))
        counts = p_df[p_df['PTS'] >= pts_target].groupby('Player/Team').size().sort_values(ascending=False).head(5)
        if counts.empty: response += f"No player has recorded a {pts_target}+ point game."
        else:
            response += f"**Most {pts_target}+ Point Games:**\n"
            for p, c in counts.items(): response += f"• {p}: {c} games\n"
        return await interaction.followup.send(response)
        
    if "most" in q and "in a game" in q:
        if "rebounds" in q or "boards" in q: stat, label = "REB", "Rebounds"
        elif "assists" in q or "dimes" in q: stat, label = "AST", "Assists"
        elif "steals" in q: stat, label = "STL", "Steals"
        elif "blocks" in q: stat, label = "BLK", "Blocks"
        elif "3" in q: stat, label = "3PM", "3-Pointers"
        else: stat, label = "PTS", "Points"
        
        top = p_df.sort_values(stat, ascending=False).head(3)
        response += f"**Highest Single-Game {label}:**\n"
        for _, r in top.iterrows(): response += f"• {r['Player/Team']} - {int(r[stat])} {label} (Game {int(r['Game_ID'])})\n"
        return await interaction.followup.send(response)
        
    if "most" in q or "all time" in q or "highest" in q:
        if "rebounds" in q or "boards" in q: stat, label = "REB", "Rebounds"
        elif "assists" in q or "dimes" in q: stat, label = "AST", "Assists"
        elif "steals" in q: stat, label = "STL", "Steals"
        elif "blocks" in q: stat, label = "BLK", "Blocks"
        elif "3" in q: stat, label = "3PM", "3-Pointers"
        else: stat, label = "PTS", "Points"
        
        tots = p_df.groupby('Player/Team')[stat].sum().sort_values(ascending=False).head(5)
        response += f"**All-Time {label} Leaders:**\n"
        for p, v in tots.items(): response += f"• {p}: {int(v)} {label}\n"
        return await interaction.followup.send(response)
        
    response += "I'm still learning! Try asking about 'most 30 point games', 'highest single game points', or 'most all time assists'."
    await interaction.followup.send(response)

@bot.tree.command(name="season", description="Show the current season and full season history the bot is tracking.")
async def season_info(interaction: discord.Interaction):
    df = _cached_df
    if df is None or df.empty:
        return await interaction.response.send_message("⚠️ Stat database is loading. Try again in a moment.", ephemeral=True)

    all_seasons = sorted([int(s) for s in df['Season'].dropna().unique()])
    current = max(all_seasons) if all_seasons else 1

    # Per-season game counts
    lines = []
    for szn in sorted(all_seasons, reverse=True):
        szn_games = df[df['Season'] == szn]['Game_ID'].nunique()
        marker = " ⬅️ **CURRENT**" if szn == current else ""
        lines.append(f"**Season {szn}** — {szn_games} games{marker}")

    embed = discord.Embed(
        title="📅 Qwik's Cup League — Season Tracker",
        description=f"The bot recognizes **Season {current}** as the current season (auto-detected from the highest season number in the data).\n\n" + "\n".join(lines),
        color=0x0A84FF
    )
    embed.add_field(name="Total Seasons", value=f"{len(all_seasons)}", inline=True)
    embed.add_field(name="Total Games", value=f"{df['Game_ID'].nunique()}", inline=True)
    embed.set_footer(text="Season detection is automatic. Submit games with the right Season number to advance it.")
    await interaction.response.send_message(embed=embed)


