@bot.tree.command(name="mystats", description="Instantly pull your own Graphic Player Card.")
async def mystats(interaction: discord.Interaction):
    await interaction.response.defer()
    discord_id = str(interaction.user.id)
    registry = get_universal_registry()
    
    player_name = next((name for name, tag in registry.items() if discord_id in tag), None)
    if not player_name: return await interaction.followup.send("⚠️ Your Discord ID isn't in the Registry! You can also type `/scout YourName`")
    
    await build_scout_card(interaction, player_name, "Career", discord_id)

# ═══════════════════════════════════════════════════════════════════════
# 🔎 STAT SEARCH — PBR-style query builder
# ═══════════════════════════════════════════════════════════════════════
# Lets users find specific stat lines across the entire league history.
# Examples:
#   /stat_search query: 40+ points
#   /stat_search query: triple-double
#   /stat_search query: 30 points 10 assists
#   /stat_search query: Trifecta 30+ points
#   /stat_search query: 5+ blocks
# ═══════════════════════════════════════════════════════════════════════

def parse_stat_query(q: str) -> dict:
    """Turn a natural-language query into structured filters.
    Keys: player, team, season, thresholds {stat:min}, flags, sort_by, sort_dir, limit, resolved_mention."""
    q_lower = q.lower().strip()
    filters = {"player": None, "team": None, "season": None, "thresholds": {},
               "flags": set(), "sort_by": "PTS", "sort_dir": "desc",
               "limit": 10, "resolved_mention": None}

    # --- Resolve a Discord mention (<@id> / <@!id>) to a gamertag ---
    mention = re.search(r'<@!?(\d+)>', q)
    if mention:
        _uid = mention.group(1)
        try:
            _users = load_state().get('users', {})
            _gt = (_users.get(_uid, {}) or {}).get('gamertag')
            if _gt and not str(_gt).startswith('<@'):
                filters["player"] = _gt
                filters["resolved_mention"] = _gt
        except Exception:
            pass
        q_lower = re.sub(r'<@!?\d+>', ' ', q_lower)

    # --- Flag keywords ---
    if "triple-double" in q_lower or "triple double" in q_lower:
        filters["flags"].add("triple_double")
    if "double-double" in q_lower or "double double" in q_lower:
        filters["flags"].add("double_double")
    if "50+" in q_lower or "50 points" in q_lower:
        filters["thresholds"]["PTS"] = max(filters["thresholds"].get("PTS", 0), 50)
    if "40+" in q_lower:
        filters["thresholds"]["PTS"] = max(filters["thresholds"].get("PTS", 0), 40)

    stat_aliases = {
        "point": "PTS", "points": "PTS", "pts": "PTS", "scoring": "PTS",
        "rebound": "REB", "rebounds": "REB", "reb": "REB", "boards": "REB", "rebounding": "REB",
        "assist": "AST", "assists": "AST", "ast": "AST", "dimes": "AST", "passing": "AST",
        "steal": "STL", "steals": "STL", "stl": "STL",
        "block": "BLK", "blocks": "BLK", "blk": "BLK",
        "turnover": "TO", "turnovers": "TO", "to": "TO",
        "efficiency": "EFF", "eff": "EFF",
    }
    # Match "30+ points", "10 assists", "5+ blocks"
    for m in re.finditer(r'(\d+)\+?\s+([a-z]+)', q_lower):
        n = int(m.group(1)); word = m.group(2)
        if word in stat_aliases:
            col = stat_aliases[word]
            if col in ("PTS", "REB", "AST", "STL", "BLK", "TO", "EFF"):
                filters["thresholds"][col] = max(filters["thresholds"].get(col, 0), n)

    # Season filter: "season 6", "s5"
    sm = re.search(r'season\s+(\d+)|\bs(\d+)\b', q_lower)
    if sm:
        filters["season"] = int(sm.group(1) or sm.group(2))

    # Sort direction: "most/best/highest/top" (desc) vs "fewest/lowest/least/worst" (asc)
    if any(w in q_lower for w in ("fewest", "lowest", "least", "worst")):
        filters["sort_dir"] = "asc"
    elif any(w in q_lower for w in ("most", "highest", "best", "top", "career-high", "career high")):
        filters["sort_dir"] = "desc"
    # Sort column: first whole-word stat keyword in the query
    for word, col in stat_aliases.items():
        if re.search(r'\b' + re.escape(word) + r'\b', q_lower):
            filters["sort_by"] = col
            break

    # Limit: "best 5", "top 10", "first 3"
    lm = re.search(r'(?:best|top|first)\s+(\d+)', q_lower)
    if lm:
        filters["limit"] = max(1, min(25, int(lm.group(1))))

    # Team match — longest known team name contained in the query
    try:
        for t_name in sorted(_cached_teams or [], key=len, reverse=True):
            if t_name and t_name.lower() in q_lower:
                filters["team"] = t_name
                break
    except Exception:
        pass

    # Player match — longest known gamertag contained in the query wins (mention already wins if set)
    if not filters["player"] and _cached_players:
        best = None
        for p_name in _cached_players:
            if p_name and p_name.lower() in q_lower:
                if best is None or len(p_name) > len(best):
                    best = p_name
        filters["player"] = best

    return filters


class StatEraView(discord.ui.View):
    """Era-only switcher for /compare and /stat_search (no season splits)."""
    def __init__(self, kind, era=None, a=None, b=None):
        super().__init__(timeout=300)
        self.kind, self.a, self.b = kind, a, b
        self.era = era or _active_era()
        for k in ("QCL", "SPAM", "ALL"):
            style = discord.ButtonStyle.primary if k == self.era else discord.ButtonStyle.secondary
            btn = discord.ui.Button(label=_ERA_BTN_LABELS[k], style=style)
            btn.callback = self._cb(k)
            self.add_item(btn)

    def _cb(self, era_val):
        async def callback(interaction: discord.Interaction):
            await interaction.response.defer()
            if self.kind == "compare":
                await build_compare(interaction, self.a, self.b, era=era_val, is_edit=True)
            else:
                await build_stat_search(interaction, self.a, era=era_val, is_edit=True)
        return callback


@bot.tree.command(name="stat_search", description="Search games by stat (e.g. '40+ points', 'triple-double', '@player'). Switch eras.")
async def stat_search(interaction: discord.Interaction, query: str):
    df = _cached_df
    if df is None or df.empty:
        return await interaction.response.send_message("⚠️ Stat database is loading. Try again in a moment.", ephemeral=True)
    await interaction.response.defer(thinking=True)
    await build_stat_search(interaction, query)


async def build_stat_search(interaction, query, era=None, is_edit=False):
    df = _cached_df
    if df is None or df.empty:
        msg = "⚠️ Stat database is loading. Try again in a moment."
        if is_edit:
            return await interaction.edit_original_response(content=msg, embed=None, attachments=[], view=None)
        return await interaction.followup.send(msg)

    if era is None:
        era = _active_era()
    p_df = df[df['Type'].astype(str).str.lower() == 'player'].copy()
    if era in ('QCL', 'SPAM') and 'Era' in p_df.columns:
        p_df = p_df[p_df['Era'] == era]
    _elabel = {"SPAM": "SPAM", "QCL": "QCL"}.get(era, "All-Time")
    view = StatEraView("search", era=era, a=query)

    filters = parse_stat_query(query)
    result = p_df.copy()
    if filters["player"]:
        result = result[result['Player/Team'].astype(str).str.lower() == str(filters["player"]).lower()]
    if filters["team"]:
        result = result[result['Team Name'].astype(str).str.lower() == str(filters["team"]).lower()]
    if filters["season"] is not None:
        result = result[pd.to_numeric(result['Season'], errors='coerce') == filters["season"]]
    for stat, threshold in filters["thresholds"].items():
        if stat in result.columns:
            result = result[pd.to_numeric(result[stat], errors='coerce') >= threshold]
    if "triple_double" in filters["flags"]:
        result = result[(result['PTS'] >= 10) & (result['REB'] >= 10) & (result['AST'] >= 10)]
    if "double_double" in filters["flags"]:
        result = result[((result['PTS'] >= 10).astype(int) + (result['REB'] >= 10).astype(int) + (result['AST'] >= 10).astype(int)) >= 2]

    result = result.drop_duplicates(subset=['Player/Team', 'Team Name', 'Game_ID', 'Season'], keep='first')

    parsed_txt = (f"Era: `{_elabel}` • Player: `{filters['player'] or 'any'}` • Team: `{filters['team'] or 'any'}` • "
                  f"Season: `{filters['season'] or 'any'}`\nThresholds: `{filters['thresholds'] or 'none'}` • "
                  f"Flags: `{', '.join(filters['flags']) or 'none'}` • Sort: `{filters['sort_by']} {filters['sort_dir']}`")

    if result.empty:
        embed = discord.Embed(title=f"🔎 Stat Search: `{query}`",
                              description=f"**No {_elabel} games match those criteria.**\n*Try another era below.*", color=0xFF453A)
        embed.add_field(name="🧐 Parsed Query", value=parsed_txt, inline=False)
        if is_edit:
            return await interaction.edit_original_response(content=None, embed=embed, attachments=[], view=view)
        return await interaction.followup.send(embed=embed, view=view)

    sort_col = filters["sort_by"] if filters["sort_by"] in result.columns else "PTS"
    result = result.sort_values(sort_col, ascending=(filters["sort_dir"] == "asc"))
    total = len(result)
    show_n = min(filters["limit"], 15, total)

    def _g(row, col, default=0):
        try:
            v = row.get(col, default)
            return default if pd.isna(v) else v
        except Exception:
            return default

    lines = []
    _om = get_onboarded_map()
    for _, row in result.head(show_n).iterrows():
        game = int(row['Game_ID']) if not pd.isna(row['Game_ID']) else '?'
        season = int(row['Season']) if not pd.isna(row['Season']) else '?'
        team = row.get('Team Name', '?')
        core = f"{int(_g(row,'PTS'))}p / {int(_g(row,'REB'))}r / {int(_g(row,'AST'))}a / {int(_g(row,'STL'))}s / {int(_g(row,'BLK'))}b"
        adv_bits = []
        if 'eFG%' in row and not pd.isna(row.get('eFG%')):
            adv_bits.append(f"{_g(row,'eFG%'):.0f}% eFG")
        if 'Game_Score' in row and not pd.isna(row.get('Game_Score')):
            adv_bits.append(f"{_g(row,'Game_Score'):.1f} GmSc")
        if 'USG%' in row and not pd.isna(row.get('USG%')):
            adv_bits.append(f"{_g(row,'USG%'):.0f}% USG")
        adv = ("  ·  " + " / ".join(adv_bits)) if adv_bits else ""
        who = resolve_stat_identity(row['Player/Team'], onboarded_map=_om)
        lines.append(f"**{who}** ({team}) — `{core}`{adv} · S{season} G{game}")

    head = f"**{total}** matching {_elabel} game{'s' if total != 1 else ''} found."
    if filters["resolved_mention"]:
        head += f"\n*Resolved mention → **{filters['resolved_mention']}***"
    embed = discord.Embed(title=f"🔎 Stat Search: `{query}`",
                          description=head + "\n\n" + "\n".join(lines), color=0x0A84FF)
    if total > show_n:
        embed.set_footer(text=f"Showing {show_n} of {total} ({_elabel}), sorted by {sort_col} {filters['sort_dir']}. /boxscore <id> for full splits.")
    else:
        embed.set_footer(text=f"All {total} shown ({_elabel}). /boxscore <id> for full splits.")
    if is_edit:
        await interaction.edit_original_response(content=None, embed=embed, attachments=[], view=view)
    else:
        await interaction.followup.send(embed=embed, view=view)

