# 🛎️ HELP CONCIERGE — AI "Ask Jeeves" for the bot itself
# ═══════════════════════════════════════════════════════════════════════
# Players get careful, guiding answers. Admins (with the admin role) get
# full technical access. The AI knows the entire command set as context.
# ═══════════════════════════════════════════════════════════════════════

ADMIN_ROLE_ID = 1504667050298048613  # Admins with this role get full bot knowledge


def is_admin_user(interaction: discord.Interaction) -> bool:
    """True if the user has the admin role OR Discord administrator permission."""
    if interaction.guild and interaction.user:
        # Server administrator permission
        try:
            if interaction.user.guild_permissions.administrator:
                return True
        except Exception:
            pass
        # The designated admin role
        try:
            role_ids = [r.id for r in interaction.user.roles]
            if ADMIN_ROLE_ID in role_ids:
                return True
        except Exception:
            pass
    return False


# ==========================================
# --- ROLE SYSTEM: Player <-> Coach (admin-approved) ---
# ==========================================
def get_user_role(uid, state=None):
    """Return 'coach' or 'player' for a user. A user is a coach if their profile
    role is explicitly 'coach', or (legacy) if they already hold a team claim."""
    if state is None:
        state = load_state()
    uid = str(uid)
    r = state.get('users', {}).get(uid, {}).get('role')
    if r in ('coach', 'player'):
        return r
    if uid in state.get('team_claims', {}):
        return 'coach'
    return 'player'


def user_is_coach(uid, state=None):
    if state is None:
        state = load_state()
    uid = str(uid)
    return get_user_role(uid, state) == 'coach' or uid in state.get('team_claims', {})


def file_role_request(state, uid, display_name, direction, team=None):
    """Queue an admin-approval ticket to switch a user between player and coach.
    direction is 'to_coach' or 'to_player'. Replaces any prior pending request from
    the same user so the queue never stacks duplicates. Returns the ticket id."""
    import uuid as _uuid
    uid = str(uid)
    state.setdefault('admin_inbox', [])
    state['admin_inbox'] = [
        t for t in state['admin_inbox']
        if not (t.get('type') == 'role_request' and str(t.get('uid')) == uid)
    ]
    ticket = {
        "id": str(_uuid.uuid4())[:8],
        "uid": uid,
        "type": "role_request",
        "direction": direction,
        "display_name": display_name,
        "team": team,
        "timestamp": time.time(),
    }
    state['admin_inbox'].append(ticket)
    return ticket["id"]


async def require_coach_access(interaction) -> bool:
    """Gate for coach-only commands. Admins always pass. If the user isn't a coach,
    send an ephemeral explainer and return False."""
    if is_admin_user(interaction) or user_is_coach(interaction.user.id):
        return True
    msg = (
        "🚫 **Coaches only.** This is a Coach Desk command.\n"
        "To coach a team, run `/become_coach team:<your team>` and an admin will approve it. "
        "Run `/coach help` to see everything coaches can do."
    )
    try:
        await interaction.response.send_message(msg, ephemeral=True)
    except Exception:
        await interaction.followup.send(msg, ephemeral=True)
    return False


