@bot.tree.command(name="vcboard", description="View the QCL VC Wealth Leaderboard.")
async def vcboard(interaction: discord.Interaction):
    state = load_state()
    bals = state.get("balances", {})
    
    if not isinstance(bals, dict):
        bals = {}
        state['balances'] = bals
        save_state(state)
        
    if not bals: return await interaction.response.send_message("The QCL Bank is empty!")
    
    reg = get_universal_registry()
    id_to_name = {v.replace("<@","").replace(">","").replace("!",""): k.title() for k, v in reg.items()}
    
    safe_bals = {k: int(v) for k, v in bals.items() if str(v).isdigit() or isinstance(v, int)}
    sorted_bals = sorted(safe_bals.items(), key=lambda x: x[1], reverse=True)
    
    embed = discord.Embed(title="🤑 QCL Bank Leaderboard", color=0x32D74B)
    for i, (did, bal) in enumerate(sorted_bals[:15]):
        mention = f"<@{did}>" if did.isdigit() else id_to_name.get(did, did.title())
        embed.add_field(name=f"{i+1}. Wealth Rank", value=f"{mention}\n**{bal:,} VC**", inline=False)
        
    await interaction.response.send_message(embed=embed)

