@admin_group.command(name="deduct_vc", description="[ADMIN ONLY] Deduct VC from a player's wallet.")
@app_commands.checks.has_permissions(administrator=True)
async def deductvc(interaction: discord.Interaction, user: discord.Member, amount: int):
    state = load_state()
    discord_id = str(user.id)
    current_balance = state['balances'].get(discord_id, 0)
    state['balances'][discord_id] = max(0, current_balance - amount)
    save_state(state)
    log_admin_action(interaction.user.display_name, "Economy", f"Deducted {amount:,} VC from {user.display_name}")
    await interaction.response.send_message(f"📉 Successfully deducted **{amount:,} VC** from {user.mention}.")

