@app_commands.checks.has_permissions(administrator=True)
@app_commands.autocomplete(award=award_autocomplete)
async def removeaward(interaction: discord.Interaction, user: discord.Member, award: str):
    state = load_state()
    uid = str(user.id)
    
    if uid in state['awards'] and award in state['awards'][uid]:
        state['awards'][uid].remove(award)
        if not state['awards'][uid]: del state['awards'][uid] # cleanup
        save_state(state)
        log_admin_action(interaction.user.display_name, "Awards", f"Removed '{award}' from {user.display_name}")
        await interaction.response.send_message(f"🗑️ Successfully removed **{award}** from {user.mention}.")
    else:
        await interaction.response.send_message(f"⚠️ Award '{award}' not found for {user.display_name}.")


