# MULTI-SELECT ADMIN TOOLS — award many players, remove teams/games in bulk
# ══════════════════════════════════════════════════════════════════════

class _BulkAwardView(discord.ui.View):
    """Native Discord member multi-picker → award one banner to everyone chosen."""
    def __init__(self, award_text, opener_id):
        super().__init__(timeout=300)
        self.award_text = award_text
        self.opener_id = opener_id
        self.us = discord.ui.UserSelect(placeholder="Select players to award…", min_values=1, max_values=25)
        self.us.callback = self._on_pick
        self.add_item(self.us)

    async def _on_pick(self, interaction: discord.Interaction):
        if interaction.user.id != self.opener_id:
            return await interaction.response.send_message("Only the admin who opened this can pick.", ephemeral=True)
        state = load_state()
        done = []
        for m in self.us.values:
            uid = str(m.id)
            state.setdefault('awards', {}).setdefault(uid, [])
            entry = f"🏅 {self.award_text}"
            if entry not in state['awards'][uid]:
                state['awards'][uid].append(entry)
            done.append(m.mention)
        save_state(state)
        log_admin_action(interaction.user.display_name, "Awards", f"Bulk-awarded '{self.award_text}' to {len(done)}")
        await interaction.response.edit_message(
            content=f"🏆 Awarded **{self.award_text}** to **{len(done)}** player(s): " + ", ".join(done[:40]),
            view=None)


@award_group.command(name="give_bulk", description="[ADMIN] Give one award to MULTIPLE players at once.")
@app_commands.checks.has_permissions(administrator=True)
async def giveaward_bulk(interaction: discord.Interaction, award: str):
    await interaction.response.send_message(
        f"Select every player who should receive **{award}**:",
        view=_BulkAwardView(award, interaction.user.id), ephemeral=True)


class _RemoveTeamConfirm(discord.ui.View):
    def __init__(self, teams, opener_id):
        super().__init__(timeout=120)
        self.teams = teams
        self.opener_id = opener_id

    @discord.ui.button(label="✅ Confirm Remove", style=discord.ButtonStyle.danger)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.opener_id:
            return await interaction.response.send_message("Not your panel.", ephemeral=True)
        state = load_state()
        removed = []
        for t in self.teams:
            for bucket in ('coach_rosters', 'rosters', 'team_logos'):
                if bucket in state and t in state[bucket]:
                    del state[bucket][t]
            removed.append(t)
        save_state(state)
        log_admin_action(interaction.user.display_name, "Teams", f"Removed team(s): {', '.join(removed)}")
        await interaction.response.edit_message(
            content=f"🗑️ Removed **{len(removed)}** team(s): {', '.join(removed)}", view=None)

    @discord.ui.button(label="Cancel", style=discord.ButtonStyle.secondary)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.edit_message(content="Cancelled — no teams removed.", view=None)


class _RemoveTeamView(discord.ui.View):
    def __init__(self, teams, opener_id):
        super().__init__(timeout=300)
        self.opener_id = opener_id
        opts = [discord.SelectOption(label=t[:100], value=t) for t in teams[:25]]
        self.sel = discord.ui.Select(placeholder="Select team(s) to remove…", options=opts,
                                     min_values=1, max_values=min(25, len(opts)))
        self.sel.callback = self._pick
        self.add_item(self.sel)

    async def _pick(self, interaction: discord.Interaction):
        if interaction.user.id != self.opener_id:
            return await interaction.response.send_message("Not your panel.", ephemeral=True)
        chosen = list(self.sel.values)
        await interaction.response.edit_message(
            content=(f"⚠️ Remove **{len(chosen)}** team(s): **{', '.join(chosen)}**?\n"
                     f"This deletes each team's roster, logo, and coach entry. This can't be undone."),
            view=_RemoveTeamConfirm(chosen, self.opener_id))


@admin_group.command(name="remove_team", description="[ADMIN] Remove one or more teams (roster, logo, coach entry).")
@app_commands.checks.has_permissions(administrator=True)
async def admin_remove_team(interaction: discord.Interaction):
    state = init_coach_rosters(load_state())
    teams = sorted(set(list(state.get('coach_rosters', {}).keys()) + list(state.get('rosters', {}).keys())))
    if not teams:
        return await interaction.response.send_message("No teams found to remove.", ephemeral=True)
    await interaction.response.send_message(
        "Select the team(s) to remove:", view=_RemoveTeamView(teams, interaction.user.id), ephemeral=True)


class _RemoveGamesView(discord.ui.View):
    def __init__(self, keys, opener_id):
        super().__init__(timeout=300)
        self.opener_id = opener_id
        opts = [discord.SelectOption(label=k[:100], value=k) for k in keys[:25]]
        self.sel = discord.ui.Select(placeholder="Select locked game(s) to remove…", options=opts,
                                     min_values=1, max_values=min(25, len(opts)))
        self.sel.callback = self._pick
        self.add_item(self.sel)

    async def _pick(self, interaction: discord.Interaction):
        if interaction.user.id != self.opener_id:
            return await interaction.response.send_message("Not your panel.", ephemeral=True)
        chosen = list(self.sel.values)
        state = load_state()
        removed = []
        for k in chosen:
            if k in state.get('locked_games', {}):
                del state['locked_games'][k]
                removed.append(k)
        save_state(state)
        log_admin_action(interaction.user.display_name, "Vegas", f"Removed {len(removed)} locked game(s)")
        await interaction.response.edit_message(
            content=f"🗑️ Removed **{len(removed)}** locked game(s):\n" + "\n".join(removed), view=None)


@admin_group.command(name="remove_games", description="[ADMIN] Remove MULTIPLE locked games from the board at once.")
@app_commands.checks.has_permissions(administrator=True)
async def admin_remove_games(interaction: discord.Interaction):
    state = load_state()
    lg = state.get('locked_games', {})
    if not lg:
        return await interaction.response.send_message("No locked games on the board right now.", ephemeral=True)
    await interaction.response.send_message(
        "Select the locked game(s) to remove:", view=_RemoveGamesView(list(lg.keys()), interaction.user.id), ephemeral=True)

@bot.tree.command(name="legacy", description="Generate an epic QSPN documentary story based on a player's championship roles and stats.")
@app_commands.autocomplete(player_name=player_autocomplete)
async def legacy(interaction: discord.Interaction, player_name: str):
    await interaction.response.defer()
    
    # 1. Fetch Stats from the Live CSV Engine
    df = _cached_df
    if df is None: return await interaction.followup.send("⚠️ Stat Engine is warming up! Try again in 10s.")
    
    # We match the name directly from the dropdown
    p_df = df[(df['Type'].astype(str).str.lower() == 'player') & (df['Player/Team'].astype(str).str.lower() == player_name.lower())]
    if p_df.empty: return await interaction.followup.send(f"⚠️ Player '{player_name}' not found in the stats database.")
    
    # --- ADVANCED STAT EXTRACTION ---
    actual_name = p_df['Player/Team'].iloc[0]
    
    # Career Totals
    career_pts = int(p_df['PTS'].sum())
    career_ast = int(p_df['AST'].sum())
    career_reb = int(p_df['REB'].sum())
    career_stl = int(p_df['STL'].sum())
    career_blk = int(p_df['BLK'].sum())
    games_played = p_df['Game_ID'].nunique()
    
    # Career Averages & Impact
    ppg = p_df['PTS'].mean()
    apg = p_df['AST'].mean()
    rpg = p_df['REB'].mean()
    pie = p_df['PIE_Raw'].mean()
    
    # True Shooting Percentage (Efficiency)
    fga_sum = p_df['FGA'].sum()
    fta_sum = p_df['FTA'].sum()
    ts_pct = (career_pts / (2 * (fga_sum + 0.44 * fta_sum))) * 100 if (fga_sum + fta_sum) > 0 else 0
    
    # All-Time Single Game Highs
    high_pts = int(p_df['PTS'].max())
    high_reb = int(p_df['REB'].max())
    high_ast = int(p_df['AST'].max())
    high_stl = int(p_df['STL'].max())
    high_blk = int(p_df['BLK'].max())
    # --------------------------------
    
    # 2. Fetch Roles (Championships) & Awards
    tag = get_tag(actual_name)
    roles = get_user_roles(tag) if tag else []
    
    state = load_state()
    did_clean = tag.replace("<@", "").replace(">", "").replace("!", "").replace("&", "") if tag else None
    custom_awards = state['awards'].get(did_clean, []) if did_clean else state['awards'].get(actual_name.lower(), [])
    
    # Clean up the award names (removing emojis so the AI reads them naturally)
    clean_awards = [a.replace("🏅 ", "").replace("🏆 ", "").replace("💍 ", "") for a in custom_awards]
    
    all_hardware = roles + clean_awards
    hardware_text = ", ".join(all_hardware) if all_hardware else "No official hardware yet, still chasing their first taste of greatness."
    
    # 3. The QSPN Director Prompt
    prompt = f"""
    You are the Emmy-award-winning head writer and sports analyst for the 'QSPN Broadcaster' documentary series, similar to ESPN's 30 for 30.
    
    Write a dramatic, epic 2-paragraph legacy story about the QCL legend: {actual_name}.
    
    Here is their official hardware (Championship Rings, Trophies, and Honors): {hardware_text}
    
    Here is their complete statistical resume across {games_played} career games:
    - Career Totals: {career_pts} PTS, {career_reb} REB, {career_ast} AST, {career_stl} STL, {career_blk} BLK.
    - Career Averages: {ppg:.1f} PPG, {rpg:.1f} RPG, {apg:.1f} APG.
    - Advanced Impact: {pie:.1f} Player Impact Estimate (PIE) and a {ts_pct:.1f}% True Shooting Percentage.
    - All-Time Single Game Highs: {high_pts} PTS, {high_reb} REB, {high_ast} AST, {high_stl} STL, {high_blk} BLK.
    
    Instructions:
    - Weave their specific awards and championship roles into the narrative as historic, legendary accomplishments.
    - Highlight their most insane single-game highs (e.g., if they dropped a massive amount of points or rebounds in one game, hype it up).
    - Mention their advanced stats (like their True Shooting efficiency or PIE) to validate their dominance.
    - Write it like a dramatic, awe-inspiring voiceover for a sports documentary promo.
    - End the story with a powerful one-liner summarizing their legacy in the QCL league.
    """
    
    try:
        def _fetch_lore():
            return ai_client.models.generate_content(
                model='gemini-3.6-flash',
                contents=prompt
            )
            
        ai_response = await asyncio.to_thread(_fetch_lore)
        
        # Discord crashes if an embed description is over 4096 characters. This prevents that.
        story_text = ai_response.text
        if len(story_text) > 4000:
            story_text = story_text[:4000] + "..."
        
        embed = discord.Embed(title=f"🎬 QSPN 30 for 30: The Legend of {actual_name}", description=story_text, color=0xFFD60A)
        embed.set_footer(text="QSPN Original Documentary Series | Powered by Oracle Analytics")
        
        await interaction.followup.send(embed=embed)
        
    except Exception as e:
        await interaction.followup.send(f"❌ Writer's block error: `{str(e)[:900]}`")

