# ══════════════════════════════════════════════════════════════════════
# 🏛️ THE AWARDS ROOM — live server-role trophy browser (dropdown-driven)
# Reads roles straight off the Discord server, groups Champions / MVPs /
# All-QCL 1st & 2nd Team / All-Team honors, and lets you drill into a
# champion or MVP to see their run + stats + an AI documentary story.
#
# TUNE THIS to your exact role names. First matching rule wins (top-down),
# so more specific categories (Finals MVP) sit above broader ones (MVP).
# ══════════════════════════════════════════════════════════════════════
# MATCH ORDER = specificity (first match wins). In-Season / Preseason / Finals
# MVP must sit ABOVE the broad Champion / MVP buckets so they don't get
# swallowed. Keywords are matched against the space-padded, lowercased role
# name, so emojis in the role (☀️, 💍, 🐕…) never interfere. Tune freely.
AWARD_ROLE_RULES = [
    ("FINALS_MVP",  ["finals mvp", "fmvp", "series mvp", "championship mvp"]),
    ("INSEASON",    ["inseason", "in-season", "in season", "inseasons"]),
    ("PRESEASON",   ["preseason", "pre-season", "pre season"]),
    ("CHAMPION",    ["champ", "champion", "champions", "champs", "cup winner", "cup champ", "title"]),
    ("MVP",         ["mvp", "most valuable"]),
    ("FIRST_TEAM",  ["1st team", "first team"]),
    ("SECOND_TEAM", ["2nd team", "second team"]),
    ("ALL_TEAM",    ["all rookie", "rookie team", "all-defensive", "defensive team", "def team",
                     "all spam", "all-team", "all team", "all-qcl", "all qcl", "all-star",
                     "all star", "all-league"]),
    ("DPOY",        ["dpoy", "defensive player"]),
    ("OPOY",        ["opoy", "offensive player"]),
    ("BMOY",        ["bmoty", "bmoy", "big man"]),
    ("ROY",         ["roty", "rookie of", " roy "]),
    ("MIP",         ["most improved", " mip ", "breakout"]),
    ("GMOY",        ["gmoty", "gm of the year", "gm of"]),
    ("RANKING",     ["legend", "top 10", "top 25", "top 50", "top 100"]),
    ("CLUB",        ["pt club", "point club", " club", "point game", " points", "rebounds",
                     "scoringleader", "scoring leader", "assistking", "assist king", "fgm",
                     "dirty 30", "30 club", "scoring leader", "assist king"]),
]
AWARD_CATEGORY_META = {
    "CHAMPION":    ("🏆", "Champions"),
    "FINALS_MVP":  ("💍", "Finals MVP"),
    "MVP":         ("🔥", "Season MVP"),
    "INSEASON":    ("🔶", "In-Season Champions"),
    "PRESEASON":   ("🔷", "Preseason Champions"),
    "FIRST_TEAM":  ("🥇", "1st Team (All-League)"),
    "SECOND_TEAM": ("🥈", "2nd Team (All-League)"),
    "ALL_TEAM":    ("🏅", "All-Team (Rookie/Def)"),
    "DPOY":        ("🛡️", "Defensive POY"),
    "OPOY":        ("🎯", "Offensive POY"),
    "BMOY":        ("🗿", "Big Man of the Year"),
    "ROY":         ("🐣", "Rookie of the Year"),
    "MIP":         ("🚀", "Most Improved / Breakout"),
    "GMOY":        ("🧠", "GM of the Year"),
    "RANKING":     ("👑", "Rankings & Tiers"),
    "CLUB":        ("📊", "Stat Clubs & Milestones"),
    "CUSTOM":      ("📜", "Custom Awards"),
}
# Categories that get the "special" run/story drill-down.
_AWARD_SPECIAL = ("CHAMPION", "FINALS_MVP", "MVP", "INSEASON", "PRESEASON")
# DISPLAY order = prestige (independent of match order above).
_AWARD_CATEGORY_ORDER = [
    "CHAMPION", "FINALS_MVP", "MVP", "INSEASON", "PRESEASON",
    "FIRST_TEAM", "SECOND_TEAM", "ALL_TEAM",
    "DPOY", "OPOY", "BMOY", "ROY", "MIP", "GMOY",
    "RANKING", "CLUB",
]


def _classify_award_role(role_name):
    n = f" {str(role_name).lower()} "
    for cat, kws in AWARD_ROLE_RULES:
        if any(k in n for k in kws):
            return cat
    return None


def _scan_award_roles(guild):
    """{category: [(role, sorted_members)]} pulled LIVE from the server roles."""
    out = {}
    if guild is None:
        return out
    try:
        for role in guild.roles:
            if role.name == "@everyone":
                continue
            cat = _classify_award_role(role.name)
            if not cat:
                continue
            members = sorted(role.members, key=lambda m: m.display_name.lower())
            if not members:
                continue
            out.setdefault(cat, []).append((role, members))
        for cat in out:
            out[cat].sort(key=lambda rm: rm[0].name.lower())
    except Exception as e:
        print(f"[AwardsRoom] scan error: {e}")
    return out


def _uid_to_gamertag(uid):
    try:
        u = load_state().get('users', {}).get(str(uid), {})
        return u.get('gamertag')
    except Exception:
        return None


def _custom_awards_pairs():
    """(display, [awards]) list from state['awards'] (the /award-granted hardware)."""
    try:
        aw = load_state().get('awards', {}) or {}
    except Exception:
        aw = {}
    out = []
    for key, lst in aw.items():
        if not lst:
            continue
        who = f"<@{key}>" if str(key).isdigit() else str(key).title()
        out.append((who, list(lst)))
    return out


def _awards_overview_embed(guild, scan):
    e = discord.Embed(
        title="🏛️ THE QCL AWARDS ROOM",
        description=(f"Live from **{guild.name}**'s role board. Pick a category below to see "
                     f"every winner — champions and MVPs open up their run.\n\u200b"),
        color=0xFFD60A)
    any_line = False
    for cat in _AWARD_CATEGORY_ORDER:
        entries = scan.get(cat)
        if not entries:
            continue
        emoji, label = AWARD_CATEGORY_META[cat]
        total = len({m.id for _, members in entries for m in members})
        roles_txt = ", ".join(r.name for r, _ in entries[:6])
        e.add_field(name=f"{emoji} {label} — {total} holder(s)", value=roles_txt[:1024] or "—", inline=False)
        any_line = True
    cust = _custom_awards_pairs()
    if cust:
        e.add_field(name=f"📜 Custom Awards — {len(cust)} recipient(s)",
                    value="Individually granted hardware. Open the category to browse.", inline=False)
        any_line = True
    if not any_line:
        e.description = (f"No award/championship roles detected on **{guild.name}** yet.\n\n"
                         f"The room matches role names by keyword (champion, MVP, 1st/2nd team, "
                         f"all-team…). If your roles use different wording, tell the commissioner "
                         f"to tune `AWARD_ROLE_RULES`.")
    e.set_footer(text="QCL Trophy Room · reads live server roles every time it opens")
    return e


def _awards_category_embed(guild, scan, cat):
    emoji, label = AWARD_CATEGORY_META.get(cat, ("🏅", cat))
    e = discord.Embed(title=f"{emoji} {label}", color=0xFFD60A)
    if cat == "CUSTOM":
        cust = _custom_awards_pairs()
        if not cust:
            e.description = "No custom awards have been granted yet."
            return e
        e.description = "Individually granted hardware across the league."
        for who, lst in cust[:24]:
            e.add_field(name="Recipient", value=f"{who}\n" + "\n".join(lst)[:1000], inline=True)
        return e
    entries = scan.get(cat, [])
    if not entries:
        e.description = f"No **{label}** roles found on the server yet."
        return e
    e.description = f"Everyone holding a **{label}** role on the server."
    for role, members in entries[:24]:
        names = ", ".join(m.mention for m in members[:40])
        e.add_field(name=f"{role.name} · {len(members)}", value=names or "*none*", inline=False)
    if cat in _AWARD_SPECIAL:
        e.set_footer(text="⬇️ Pick a name below to open their run, stats & story")
    else:
        e.set_footer(text="QCL Trophy Room · live server roles")
    return e


async def _awards_winner_card(guild, scan, member, cat):
    emoji, label = AWARD_CATEGORY_META.get(cat, ("🏅", cat))
    # Every award role this member holds, across all categories.
    my_roles = []
    for c in _AWARD_CATEGORY_ORDER:
        for role, members in scan.get(c, []):
            if any(mm.id == member.id for mm in members):
                em2, _ = AWARD_CATEGORY_META.get(c, ("🏅", c))
                my_roles.append(f"{em2} {role.name}")
    e = discord.Embed(title=f"{emoji} {member.display_name}", color=0xFFD700,
                      description=f"**{label}**")
    e.add_field(name="🎖️ Hardware (server roles)",
                value="\n".join(dict.fromkeys(my_roles))[:1024] or "—", inline=False)
    gt = _uid_to_gamertag(member.id)
    df = _cached_df
    if gt and df is not None:
        try:
            p = df[(df['Type'].astype(str).str.lower() == 'player')
                   & (df['Player/Team'].apply(lambda x: _id_key(x) == _id_key(gt)))]
        except Exception:
            p = None
        if p is not None and not p.empty:
            gp = int(p['Game_ID'].nunique()) if 'Game_ID' in p.columns else len(p)
            e.add_field(
                name="📊 Career Line",
                value=(f"`{p['PTS'].mean():.1f}` PPG · `{p['REB'].mean():.1f}` RPG · "
                       f"`{p['AST'].mean():.1f}` APG · `{p['STL'].mean():.1f}` SPG · "
                       f"`{p['BLK'].mean():.1f}` BPG  ({gp} GP)"),
                inline=False)
            e.add_field(
                name="🚀 Career Highs",
                value=f"{int(p['PTS'].max())} PTS · {int(p['REB'].max())} REB · {int(p['AST'].max())} AST",
                inline=False)
            e.set_footer(text=f"Gamertag: {gt} · tap “📖 The Run” for the story")
        else:
            e.set_footer(text="No stat lines on the sheet under this gamertag yet — the run still stands.")
    else:
        e.set_footer(text="Not onboarded / no gamertag linked — stats unavailable.")
    return e


class _RunStoryButton(discord.ui.Button):
    """Generates the epic QSPN documentary of a champion/MVP's run on demand."""
    def __init__(self, member_id, cat):
        emoji, label = AWARD_CATEGORY_META.get(cat, ("🏅", cat))
        super().__init__(label="📖 The Run", style=discord.ButtonStyle.success, row=2)
        self.member_id = member_id
        self.cat = cat

    async def callback(self, interaction: discord.Interaction):
        await interaction.response.defer()
        member = interaction.guild.get_member(self.member_id)
        if member is None:
            return await interaction.followup.send("Couldn't find that member anymore.", ephemeral=True)
        _, label = AWARD_CATEGORY_META.get(self.cat, ("🏅", "Award"))
        # hardware
        hardware = []
        scan = _scan_award_roles(interaction.guild)
        for c in _AWARD_CATEGORY_ORDER:
            for role, members in scan.get(c, []):
                if any(mm.id == member.id for mm in members):
                    hardware.append(role.name)
        hardware_text = ", ".join(dict.fromkeys(hardware)) or label
        # stats
        stat_line, highs = "limited stats on record", ""
        gt = _uid_to_gamertag(member.id)
        df = _cached_df
        if gt and df is not None:
            try:
                p = df[(df['Type'].astype(str).str.lower() == 'player')
                       & (df['Player/Team'].apply(lambda x: _id_key(x) == _id_key(gt)))]
                if not p.empty:
                    gp = int(p['Game_ID'].nunique()) if 'Game_ID' in p.columns else len(p)
                    stat_line = (f"{p['PTS'].mean():.1f} PPG, {p['REB'].mean():.1f} RPG, "
                                 f"{p['AST'].mean():.1f} APG, {p['STL'].mean():.1f} SPG, "
                                 f"{p['BLK'].mean():.1f} BPG over {gp} games")
                    highs = f"{int(p['PTS'].max())} PTS, {int(p['REB'].max())} REB, {int(p['AST'].max())} AST"
            except Exception:
                pass
        name = member.display_name
        prompt = f"""You are the lead writer for QSPN, a 30-for-30-style documentary series for the Qwik's Cup League (an NBA 2K Pro-Am league).

Tell the story of {name}'s {label} run.
Hardware / roles earned: {hardware_text}.
Statistical resume: {stat_line}. Career single-game highs: {highs or 'n/a'}.

INSTRUCTIONS:
- Write 2 tight paragraphs (~180 words total). Epic and cinematic, but grounded in these real numbers.
- If this is a CHAMPIONSHIP or FINALS MVP: frame the postseason run and the moment they hoisted the Cup.
- If this is an MVP: frame a season-long stretch of dominance.
- No fabricated quotes and no invented stats — use only what's given.
- End on a single-line legacy stamp."""
        story = None
        try:
            def _fetch():
                return ai_client.models.generate_content(model='gemini-3.6-flash', contents=prompt)
            resp = await asyncio.to_thread(_fetch)
            story = resp.text
        except Exception as e:
            print(f"[AwardsRoom] run story failed: {e}")
        if not story:
            story = (f"**{name}** earned it the hard way: {hardware_text}. "
                     f"The tape backs it up — {stat_line}. A run the league won't forget.")
        emoji, _lab = AWARD_CATEGORY_META.get(self.cat, ("🏆", "Award"))
        se = discord.Embed(title=f"{emoji} THE RUN — {name}", description=story[:4000], color=0xFFD700)
        se.set_footer(text="QSPN Films · grounded in the stat sheet")
        await interaction.followup.send(embed=se)


class AwardsRoomView(discord.ui.View):
    """Dropdown-driven trophy browser. Category select up top; for champions
    and MVPs, a second select drills into a winner's run + stats + story."""
    def __init__(self, guild, scan, cat=None, opener_id=None):
        super().__init__(timeout=600)
        self.guild = guild
        self.scan = scan
        self.cat = cat
        self.opener_id = opener_id

        # Row 0 — category selector
        cats_present = [c for c in _AWARD_CATEGORY_ORDER if self.scan.get(c)]
        opts = []
        for c in cats_present:
            emoji, label = AWARD_CATEGORY_META[c]
            total = len({m.id for _, members in self.scan.get(c, []) for m in members})
            opts.append(discord.SelectOption(label=f"{label} ({total})", value=c,
                                             emoji=emoji, default=(c == self.cat)))
        if _custom_awards_pairs():
            opts.append(discord.SelectOption(label="Custom Awards", value="CUSTOM",
                                             emoji="📜", default=(self.cat == "CUSTOM")))
        if opts:
            csel = discord.ui.Select(placeholder="🏛️ Pick an award category…", options=opts[:25], row=0)
            csel.callback = self._cat_cb
            self.add_item(csel)

        # Row 1 — winner drill-down (only for the special categories)
        if self.cat in _AWARD_SPECIAL and self.scan.get(self.cat):
            winners, seen = [], set()
            for role, members in self.scan[self.cat]:
                for m in members:
                    if m.id in seen:
                        continue
                    seen.add(m.id)
                    winners.append((m, role))
            wopts = [discord.SelectOption(label=w[0].display_name[:100], value=str(w[0].id),
                                          description=w[1].name[:100]) for w in winners[:25]]
            if wopts:
                wsel = discord.ui.Select(placeholder="🔎 Open a winner's run & stats…", options=wopts, row=1)
                wsel.callback = self._winner_cb
                self.add_item(wsel)

    async def _cat_cb(self, interaction: discord.Interaction):
        cat = interaction.data['values'][0]
        view = AwardsRoomView(self.guild, self.scan, cat=cat, opener_id=self.opener_id)
        await interaction.response.edit_message(embed=_awards_category_embed(self.guild, self.scan, cat), view=view)

    async def _winner_cb(self, interaction: discord.Interaction):
        await interaction.response.defer()
        mid = int(interaction.data['values'][0])
        member = self.guild.get_member(mid)
        if member is None:
            return await interaction.followup.send("Couldn't find that member anymore.", ephemeral=True)
        embed = await _awards_winner_card(self.guild, self.scan, member, self.cat)
        view = AwardsRoomView(self.guild, self.scan, cat=self.cat, opener_id=self.opener_id)
        view.add_item(_RunStoryButton(member.id, self.cat))
        await interaction.edit_original_response(embed=embed, view=view)


