@bot.tree.command(name="compare", description="Head-to-head Tale of the Tape between two players. Switch eras with the buttons.")
@app_commands.autocomplete(player1=player_autocomplete, player2=player_autocomplete)
async def compare(interaction: discord.Interaction, player1: str, player2: str):
    await interaction.response.defer()
    await build_compare(interaction, player1, player2)


async def build_compare(interaction, player1, player2, era=None, is_edit=False):
    df = _cached_df
    if df is None:
        msg = "⚠️ Stat Engine is warming up! Try again in 10s."
        if is_edit:
            return await interaction.edit_original_response(content=msg, embed=None, attachments=[], view=None)
        return await interaction.followup.send(msg)

    if era is None:
        era = _active_era()
    p_all = df[df['Type'].str.lower() == 'player']

    def _present(name, e):
        d = p_all
        if e in ('QCL', 'SPAM') and 'Era' in d.columns:
            d = d[d['Era'] == e]
        return not d[d['Player/Team'].str.lower() == str(name).lower()].empty

    # Cross-era safety: if either player has no games in the chosen era, widen to
    # All-Time so the comparison still resolves (e.g. a SPAM legend vs a QCL rookie).
    if era in ('QCL', 'SPAM') and not (_present(player1, era) and _present(player2, era)):
        era = 'ALL'

    p_df = p_all
    if era in ('QCL', 'SPAM') and 'Era' in p_df.columns:
        p_df = p_df[p_df['Era'] == era]
    _elabel = {"SPAM": "SPAM", "QCL": "QCL"}.get(era, "All-Time")

    p1_data = p_df[p_df['Player/Team'].str.lower() == player1.lower()]
    p2_data = p_df[p_df['Player/Team'].str.lower() == player2.lower()]
    if p1_data.empty or p2_data.empty:
        msg = "⚠️ Could not find one or both players."
        view = StatEraView("compare", era=era, a=player1, b=player2)
        if is_edit:
            return await interaction.edit_original_response(content=msg, embed=None, attachments=[], view=view)
        return await interaction.followup.send(msg, view=view)

    def get_stats(data):
        return {
            'PTS': data['PTS'].mean(), 'REB': data['REB'].mean(), 'AST': data['AST'].mean(),
            'DEF': data['STL'].mean() + data['BLK'].mean(), 'PIE': data['PIE_Raw'].mean(),
            'TS%': (data['PTS'].sum() / (2 * (data['FGA'].sum() + 0.44 * (data['FGA'].sum()*0.2)))) * 100 if data['FGA'].sum() > 0 else 0
        }

    p1_s, p2_s = get_stats(p1_data), get_stats(p2_data)
    n1, n2 = p1_data['Player/Team'].iloc[0], p2_data['Player/Team'].iloc[0]

    img_buf = draw_radar_chart(n1, p1_s, None, "", p2_name=n2, p2_stats=p2_s)
    file = discord.File(img_buf, filename="h2h.png")

    embed = discord.Embed(title=f"⚖️ TALE OF THE TAPE: {n1} vs {n2}",
                          description=f"Comparing {_elabel} statistical profiles.", color=0xFFD60A)
    embed.add_field(name=f"🥇 {n1}", value=f"**PIE:** {p1_s['PIE']:.1f}\n**PTS:** {p1_s['PTS']:.1f}\n**AST:** {p1_s['AST']:.1f}\n**REB:** {p1_s['REB']:.1f}\n**TS%:** {p1_s['TS%']:.1f}%", inline=True)
    embed.add_field(name="vs", value="⚡\n🏀\n🎯\n🦍\n🔥", inline=True)
    embed.add_field(name=f"🥈 {n2}", value=f"**PIE:** {p2_s['PIE']:.1f}\n**PTS:** {p2_s['PTS']:.1f}\n**AST:** {p2_s['AST']:.1f}\n**REB:** {p2_s['REB']:.1f}\n**TS%:** {p2_s['TS%']:.1f}%", inline=True)
    embed.set_image(url="attachment://h2h.png")

    view = StatEraView("compare", era=era, a=player1, b=player2)
    if is_edit:
        await interaction.edit_original_response(content="", embed=embed, attachments=[file], view=view)
    else:
        await interaction.followup.send(embed=embed, file=file, view=view)

