@bot.tree.command(name="buy", description="Buy an item from the shop using VC.")
@app_commands.autocomplete(item=shop_item_autocomplete)
async def buy(interaction: discord.Interaction, item: str):
    state = load_state()
    uid = str(interaction.user.id)
    prices = {"shoe": 5000, "badge": 10000}
    
    item_choice = item.lower().strip()
    if item_choice not in prices: return await interaction.response.send_message("❌ Item not found. Try 'shoe' or 'badge'.", ephemeral=True)
    if state['balances'].get(uid, 0) < prices[item_choice]: return await interaction.response.send_message(f"🚫 Not enough VC.", ephemeral=True)
    
    state['balances'][uid] -= prices[item_choice]
    state.setdefault('inventory', {}).setdefault(uid, []).append(item_choice)
    save_state(state)
    await interaction.response.send_message(f"✅ Purchased **{item_choice}**! New Balance: {state['balances'][uid]:,} VC")

