@bot.tree.command(name="trashtalk", description="Generate a statistically accurate roast.")
@app_commands.autocomplete(target=team_autocomplete)
async def trashtalk(interaction: discord.Interaction, target: str):
    await interaction.response.defer()
    df = _cached_df
    if df is None: return await interaction.followup.send("⚠️ Stat Engine is warming up! Try again in 10s.")
    t_df = df[(df['Type'] == 'Team') & (df['Team Name'].str.lower() == target.lower())]
    if t_df.empty: return await interaction.followup.send("Team not found.")
    
    avg_to = t_df['TO'].mean()
    avg_fg = (t_df['FGM'].sum() / t_df['FGA'].sum()) * 100 if t_df['FGA'].sum() > 0 else 0
    
    roasts = []
    if avg_to > 12: roasts.append(f"**{target}** turns the ball over {avg_to:.1f} times a game. They're basically playing dodgeball.")
    if avg_fg < 45: roasts.append(f"**{target}** is shooting a miserable {avg_fg:.1f}% from the field. Might need to build a brick house.")
    roasts.append(f"**{target}** thinks they are contenders, but the math says otherwise.")
    
    await interaction.followup.send(f"🗣️ {random.choice(roasts)}")

