@bot.tree.command(name="rivalry", description="View the history and story between two teams.")
@app_commands.autocomplete(team1=team_autocomplete, team2=team_autocomplete)
async def rivalry(interaction: discord.Interaction, team1: str, team2: str):
    await interaction.response.defer()
    df = _cached_df
    if df is None: return await interaction.followup.send("⚠️ Stat Engine is warming up! Try again in 10s.")
    
    t1, t2 = team1.title(), team2.title()
    max_szn = df['Season'].max()
    recent_szns = [max_szn, max_szn - 1]
    
    matchups = df[(df['Type'] == 'Team') & (df['Team Name'] == t1) & (df['Opp_Name'] == t2)].copy()
    if len(matchups) == 0: return await interaction.followup.send(f"No history found between **{t1}** and **{t2}**.")

    t1_wins = len(matchups[matchups['Win'] == 1])
    t2_wins = len(matchups) - t1_wins

    story = "A classic QCL matchup."
    recent_matchups = matchups[matchups['Season'].isin(recent_szns)]
    if len(recent_matchups) >= 4:
        story = random.choice([
            f"📖 **The Story:** A bitter blood feud. Having met {len(recent_matchups)} times in just the last two seasons, these two squads know each other's playbooks inside out.",
            f"📖 **The Story:** Familiar foes. The animosity is palpable after clashing {len(recent_matchups)} times recently. Every possession matters in this heated rivalry."
        ])

    embed = discord.Embed(title=f"⚔️ RIVALRY CORNER: {t1} vs {t2}", description=story, color=0xFF453A)
    embed.add_field(name=f"{t1} All-Time Wins", value=str(t1_wins), inline=True)
    embed.add_field(name=f"{t2} All-Time Wins", value=str(t2_wins), inline=True)
    
    recent_games = matchups.sort_values('Game_ID', ascending=False).head(3)
    history_text = ""
    for _, r in recent_games.iterrows():
        t1_pts = int(r['PTS'])
        t2_pts = int(r['PTS_Opp'])
        winner = t1 if t1_pts > t2_pts else t2
        history_text += f"**Game {int(r['Game_ID'])} (S{int(r['Season'])}):** {t1} ({t1_pts}) - {t2} ({t2_pts}) | *{winner} W*\n"
    
    if history_text: embed.add_field(name="Recent Matchups", value=history_text, inline=False)
    tag1, tag2 = get_tag(t1), get_tag(t2)
    tags = f"{tag1} {tag2}" if tag1 and tag2 else ""
    await interaction.followup.send(content=tags, embed=embed)


# ==========================================
# --- ALL-ERA TOP 50 (composite, all factors) ---
# ==========================================
def _compute_eternal_rankings(df, min_games=5, top_n=50):
    """Career composite ranking using advanced RATE stats, not per-game averages.
    Because the box scores have no minutes, each rate is computed as the player's
    share of their TEAM (and OPPONENT) totals across the games they played — the
    standard box-score approximation when minutes aren't tracked.

      USG%  = player poss / team poss            (scoring volume / load)
      TS%   = pts / (2*(FGA + 0.44*FTA))         (scoring efficiency)
      eFG%  = (FGM + 0.5*3PM) / FGA              (shooting, 3s weighted)
      AST%  = AST / (team FGM - own FGM)         (playmaking)
      TOV%  = TO / poss            (ball security; lower is better — inverted)
      TRB%  = REB / (team REB + opp REB)         (rebounding share of available)
      STL%  = STL / opponent poss                (perimeter defense)
      BLK%  = BLK / opponent 2PA                 (interior defense)

    Games played is weighted as the single LARGEST factor, and min_games filters
    out small-sample flukes entirely (no 2-game wonders). Returns ranked dicts."""
    import numpy as np

    def _safe(num, den):
        den = den.replace(0, np.nan)
        return (num / den * 100).replace([np.inf, -np.inf], np.nan).fillna(0)

    pr = df[df['Type'].astype(str).str.lower() == 'player'].copy()
    tr = df[df['Type'].astype(str).str.lower() == 'team'].copy()
    if pr.empty or tr.empty:
        return []

    # Team totals per (game, team)
    tt = tr.groupby(['Game_ID', 'Team Name']).agg(
        tmFGM=('FGM', 'sum'), tmREB=('REB', 'sum'), tmPoss=('Poss_Raw', 'sum'),
    ).reset_index()
    # Opponent totals per (game, team) via self-merge of team rows on Game_ID
    opp = tr[['Game_ID', 'Team Name', 'FGA', '3PA', 'REB', 'Poss_Raw']].copy()
    mm = opp.merge(opp, on='Game_ID', suffixes=('', '_o'))
    mm = mm[mm['Team Name'] != mm['Team Name_o']]
    oppt = mm.groupby(['Game_ID', 'Team Name']).agg(
        opFGA=('FGA_o', 'sum'), op3PA=('3PA_o', 'sum'),
        opREB=('REB_o', 'sum'), opPoss=('Poss_Raw_o', 'sum'),
    ).reset_index()

    pr = pr.merge(tt, on=['Game_ID', 'Team Name'], how='left')
    pr = pr.merge(oppt, on=['Game_ID', 'Team Name'], how='left')

    g = pr.groupby('Player/Team')
    a = g.agg(
        GP=('Game_ID', 'nunique'),
        pPTS=('PTS', 'sum'), pREB=('REB', 'sum'), pAST=('AST', 'sum'),
        pSTL=('STL', 'sum'), pBLK=('BLK', 'sum'), pTO=('TO', 'sum'),
        pFGA=('FGA', 'sum'), pFGM=('FGM', 'sum'), p3PM=('3PM', 'sum'), pFTA=('FTA', 'sum'),
        pPoss=('Poss_Raw', 'sum'),
        tmFGM=('tmFGM', 'sum'), tmREB=('tmREB', 'sum'), tmPoss=('tmPoss', 'sum'),
        opFGA=('opFGA', 'sum'), op3PA=('op3PA', 'sum'),
        opREB=('opREB', 'sum'), opPoss=('opPoss', 'sum'),
        TeamName=('Team Name', 'last'),
    )
    a = a[a['GP'] >= max(1, int(min_games))]
    if a.empty:
        return []

    a['USG'] = _safe(a['pPoss'], a['tmPoss']).clip(0, 100)
    a['TS']  = _safe(a['pPTS'], 2 * (a['pFGA'] + 0.44 * a['pFTA']))
    a['EFG'] = _safe(a['pFGM'] + 0.5 * a['p3PM'], a['pFGA'])
    a['AST'] = _safe(a['pAST'], (a['tmFGM'] - a['pFGM'])).clip(0, 100)
    a['TOV'] = _safe(a['pTO'], a['pPoss']).clip(0, 100)
    a['TRB'] = _safe(a['pREB'], (a['tmREB'] + a['opREB'])).clip(0, 100)
    a['STL'] = _safe(a['pSTL'], a['opPoss']).clip(0, 100)
    a['BLK'] = _safe(a['pBLK'], (a['opFGA'] - a['op3PA'])).clip(0, 100)

    def _norm(col, invert=False):
        c = a[col].astype(float)
        lo, hi = c.min(), c.max()
        n = c * 0 + 50.0 if (hi - lo) < 1e-9 else (c - lo) / (hi - lo) * 100.0
        return (100 - n) if invert else n

    # Games played = the single biggest weight; the rest are the rate stats above.
    weights = {'GP': 0.28, 'USG': 0.12, 'TS': 0.11, 'EFG': 0.05,
               'AST': 0.12, 'TRB': 0.10, 'STL': 0.08, 'BLK': 0.08}
    score = sum(_norm(k) * w for k, w in weights.items())
    score = score + _norm('TOV', invert=True) * 0.06  # ball security (lower TOV% better)
    a['SCORE'] = score
    a = a.sort_values('SCORE', ascending=False).head(top_n)
    return [{
        'rank': i, 'name': str(n), 'score': float(r['SCORE']),
        'usg': float(r['USG']), 'ts': float(r['TS']), 'efg': float(r['EFG']),
        'ast': float(r['AST']), 'tov': float(r['TOV']), 'trb': float(r['TRB']),
        'stl': float(r['STL']), 'blk': float(r['BLK']), 'gp': int(r['GP']),
    } for i, (n, r) in enumerate(a.iterrows(), 1)]


@bot.tree.command(name="top50", description="All-Era Top 50 — ranked by advanced rate stats (USG/TS/AST/TRB/STL/BLK) + games played.")
@app_commands.describe(count="How many to show (10-50, default 50)", min_games="Min games to qualify (default 5 — filters 2-game flukes)")
async def top50(interaction: discord.Interaction, count: int = 50, min_games: int = 5):
    await interaction.response.defer()
    df = _cached_df
    if df is None:
        return await interaction.followup.send("⚠️ Stat Engine is warming up! Try again in 10s.")
    count = max(10, min(50, count))
    min_games = max(1, min(40, min_games))
    ranks = _compute_eternal_rankings(df, min_games=min_games, top_n=count)
    if not ranks:
        return await interaction.followup.send(f"⚠️ No players meet the {min_games}-game minimum yet. Try a lower `min_games`.")
    header = " #  Player          Score USG%  TS% AST% TRB% STL% BLK%  GP"
    lines = [header, "─" * len(header)]
    for r in ranks:
        nm = (r['name'][:15]).ljust(15)
        lines.append(f"{r['rank']:>2}  {nm}{r['score']:>5.1f}{r['usg']:>5.1f}{r['ts']:>5.1f}{r['ast']:>5.1f}{r['trb']:>5.1f}{r['stl']:>5.1f}{r['blk']:>5.1f}{r['gp']:>4}")
    table = "```\n" + "\n".join(lines) + "\n```"
    embed = discord.Embed(
        title=f"🏆 QCL ALL-ERA TOP {count} — ETERNAL RECORD",
        description=table, color=0xFFD60A,
    )
    embed.set_footer(text=f"Composite of advanced rate stats — usage, efficiency (TS%/eFG%), playmaking (AST%), rebounding (TRB%), defense (STL%/BLK%), ball security (TOV%) — with games played as the heaviest factor. Min {min_games} games.")
    await interaction.followup.send(embed=embed)


# ==========================================
# --- LEAGUE RIVALRY BOARD (the rival section) ---
# ==========================================
def _riv_label(total, diff):
    if total >= 6:
        base = "🔥 Blood Feud"
    elif total >= 4:
        base = "⚔️ Bitter Rivals"
    elif total >= 3:
        base = "😤 Heated"
    else:
        base = "🆚 Budding Rivalry"
    if diff == 0:
        base += " · dead even"
    elif diff <= 1:
        base += " · razor thin"
    return base


def _compute_rivalries(df, count=10):
    """League-wide head-to-head series, de-duplicated per team pair, ranked by
    intensity (total meetings, with closeness as a tiebreaker)."""
    t = df[df['Type'].str.lower() == 'team'].copy()
    if t.empty or 'Opp_Name' not in t.columns:
        return []
    series = {}
    for _, row in t.iterrows():
        a = str(row.get('Team Name') or '').title()
        b = str(row.get('Opp_Name') or '').title()
        if not a or not b or a == b:
            continue
        key = tuple(sorted([a, b]))
        d = series.setdefault(key, {key[0]: 0, key[1]: 0})
        if row.get('Win') == 1:
            d[a] += 1
    rivs = []
    for (x, y), d in series.items():
        xw, yw = d[x], d[y]
        total = xw + yw
        if total < 2:
            continue
        rivs.append((total * 2 - abs(xw - yw), total, x, y, xw, yw))
    rivs.sort(reverse=True)
    return rivs[:count]


@bot.tree.command(name="rivalries", description="The League Rivalry Board — the QCL's biggest blood feuds, ranked by intensity.")
@app_commands.describe(count="How many rivalries to show (5-20, default 10)")
async def rivalries(interaction: discord.Interaction, count: int = 10):
    await interaction.response.defer()
    df = _cached_df
    if df is None:
        return await interaction.followup.send("⚠️ Stat Engine is warming up! Try again in 10s.")
    count = max(5, min(20, count))
    rivs = _compute_rivalries(df, count=count)
    if not rivs:
        return await interaction.followup.send("⚠️ Not enough head-to-head data to build the rivalry board yet.")
    lines = []
    for i, (inten, total, x, y, xw, yw) in enumerate(rivs, 1):
        diff = abs(xw - yw)
        if xw > yw:
            tag = f"{x} leads {xw}–{yw}"
        elif yw > xw:
            tag = f"{y} leads {yw}–{xw}"
        else:
            tag = f"tied {xw}–{yw}"
        lines.append(f"**{i}. {x} vs {y}**\n   {total} meetings · {tag} · {_riv_label(total, diff)}")
    embed = discord.Embed(
        title="⚔️ QCL RIVALRY BOARD — BLOOD FEUDS",
        description="\n".join(lines), color=0xFF453A,
    )
    embed.set_footer(text="Ranked by total meetings, with closeness breaking ties. Use /rivalry <team> <team> for a single head-to-head.")
    await interaction.followup.send(embed=embed)


@bot.tree.command(name="oracle", description="Simulates a 4-Quarter 20-minute Game between two teams.")
@app_commands.autocomplete(team1=team_autocomplete, team2=team_autocomplete)
async def oracle(interaction: discord.Interaction, team1: str, team2: str):
    await interaction.response.defer()

    df = _cached_df
    if df is None:
        return await interaction.followup.send("⚠️ Stat Engine is warming up! Try again in 10s.")

    state = load_state()

    # ---------------------------------------------------------------
    # STEP 1: Validate both teams exist in the stat database
    # ---------------------------------------------------------------
    t_df = df[df['Type'].astype(str).str.lower() == 'team']
    t_stats = t_df.groupby('Team Name').agg(
        GP=('Game_ID', 'nunique'),
        PPG=('PTS', 'mean'),
        Opp_PPP=('Opp_PPP', 'mean'),
        SOS=('SOS_Game', 'mean')
    ).reset_index()

    if team1 not in t_stats['Team Name'].values or team2 not in t_stats['Team Name'].values:
        return await interaction.followup.send("⚠️ One of those teams is not in the active database.")

    # ---------------------------------------------------------------
    # STEP 2: Build the active 5-man roster for each team
    #         Priority: registered active roster → top 5 by career PPG
    # ---------------------------------------------------------------
    p_logs = df[df['Type'].astype(str).str.lower() == 'player'].copy()

    def get_sim_roster(team_name):
        """
        Returns a DataFrame of exactly 5 players to simulate with.
        Uses the registered active roster first. Falls back to top-5
        career scorers for that team if no roster is registered.
        Each row contains L5-weighted PTS/REB/AST means and std devs.
        """
        active_tags = state.get('rosters', {}).get(team_name, {}).get('active', [])

        # Pull all player logs for this team
        team_logs = p_logs[p_logs['Team Name'] == team_name]

        if active_tags:
            # Filter to only active roster players (case-insensitive match)
            active_lower = [t.lower() for t in active_tags]
            team_logs = team_logs[team_logs['Player/Team'].str.lower().isin(active_lower)]

        if team_logs.empty:
            return []

        # Group per player and compute L5-weighted averages (same formula as Monte Carlo)
        sim_roster = []
        all_players = team_logs['Player/Team'].unique()

        for player in all_players:
            logs = team_logs[team_logs['Player/Team'] == player].sort_values('Game_ID', ascending=False)
            if logs.empty:
                continue
            l5 = logs.head(5)

            pts_mean = (l5['PTS'].mean() * 0.6) + (logs['PTS'].mean() * 0.4)
            reb_mean = (l5['REB'].mean() * 0.6) + (logs['REB'].mean() * 0.4)
            ast_mean = (l5['AST'].mean() * 0.6) + (logs['AST'].mean() * 0.4)
            pts_std  = logs['PTS'].std() if len(logs) > 2 else 3.5
            reb_std  = logs['REB'].std() if len(logs) > 2 else 2.0
            ast_std  = logs['AST'].std() if len(logs) > 2 else 1.5

            sim_roster.append({
                'Player': str(player),
                'pts_mean': pts_mean,
                'reb_mean': reb_mean,
                'ast_mean': ast_mean,
                'pts_std':  max(pts_std, 1.5),
                'reb_std':  max(reb_std, 0.5),
                'ast_std':  max(ast_std, 0.5),
            })

        # Sort by projected scoring and hard-cap at 5 — no more ghost players
        sim_roster = sorted(sim_roster, key=lambda x: x['pts_mean'], reverse=True)[:5]
        return sim_roster

    roster1 = get_sim_roster(team1)
    roster2 = get_sim_roster(team2)

    if not roster1 or not roster2:
        return await interaction.followup.send("⚠️ Could not build a valid roster for one or both teams. Make sure rosters are registered with `/coachdesk`.")

    # ---------------------------------------------------------------
    # STEP 3: Team-level score projection using SOS + Opp_PPP
    # ---------------------------------------------------------------
    d1 = t_stats[t_stats['Team Name'] == team1].iloc[0]
    d2 = t_stats[t_stats['Team Name'] == team2].iloc[0]
    lg_opp_ppp = t_stats['Opp_PPP'].mean() if t_stats['Opp_PPP'].mean() > 0 else 1.0

    t1_exp = d1['PPG'] * (d2['Opp_PPP'] / lg_opp_ppp) * (1 + (d1['SOS'] - 0.5))
    t2_exp = d2['PPG'] * (d1['Opp_PPP'] / lg_opp_ppp) * (1 + (d2['SOS'] - 0.5))

    # Simulate 4 quarters with realistic variance — 20-minute game pacing
    def sim_quarters(team_exp):
        quarters = []
        for _ in range(4):
            q = max(10, int(np.random.normal(team_exp / 4, 4)))
            quarters.append(q)
        return quarters

    q1 = sim_quarters(t1_exp)
    q2 = sim_quarters(t2_exp)
    s1, s2 = sum(q1), sum(q2)

    # No ties — give the winner a 1-point edge
    if s1 == s2:
        s1 += 1

    winner = team1 if s1 > s2 else team2
    loser  = team2 if s1 > s2 else team1
    win_score = max(s1, s2)
    loss_score = min(s1, s2)

    # ---------------------------------------------------------------
    # STEP 4: Simulate individual player box scores
    #         Points are distributed proportionally, then fuzzed with
    #         each player's personal std dev so it feels real.
    # ---------------------------------------------------------------
    def generate_sim_box(roster, total_pts):
        total_proj = sum(p['pts_mean'] for p in roster) or 1
        sim_box = []
        pts_pool = total_pts

        for i, p in enumerate(roster):
            share = p['pts_mean'] / total_proj
            raw_pts = int(np.random.normal(total_pts * share, p['pts_std'] * 0.5))
            raw_pts = max(0, raw_pts)

            raw_reb = max(0, int(np.random.normal(p['reb_mean'], p['reb_std'])))
            raw_ast = max(0, int(np.random.normal(p['ast_mean'], p['ast_std'])))

            sim_box.append({
                'Player': p['Player'][:13],
                'PTS': raw_pts,
                'REB': raw_reb,
                'AST': raw_ast,
            })

        # Reconcile team total: scale individual PTS so they add up to total_pts
        sim_total = sum(p['PTS'] for p in sim_box) or 1
        for p in sim_box:
            p['PTS'] = max(0, round(p['PTS'] * (total_pts / sim_total)))

        # Fix any rounding gap on the leading scorer
        diff = total_pts - sum(p['PTS'] for p in sim_box)
        if sim_box:
            sim_box[0]['PTS'] = max(0, sim_box[0]['PTS'] + diff)

        return sorted(sim_box, key=lambda x: x['PTS'], reverse=True)

    box1 = generate_sim_box(roster1, s1)
    box2 = generate_sim_box(roster2, s2)

    # ---------------------------------------------------------------
    # STEP 5: Format box score block (matches real QCL game format)
    # ---------------------------------------------------------------
    def format_box_block(box_data, team_name, score):
        header = f"**{team_name} Box Score** — {score} PTS\n"
        header += "```\n"
        header += f"{'Player':<14}| {'PTS':>3} | {'REB':>3} | {'AST':>3}\n"
        header += "-" * 34 + "\n"
        for p in box_data:
            header += f"{p['Player']:<14}| {p['PTS']:>3} | {p['REB']:>3} | {p['AST']:>3}\n"
        header += "```"
        return header

    # ---------------------------------------------------------------
    # STEP 6: Pick the simulated POTG (highest PTS, tiebreak by AST)
    # ---------------------------------------------------------------
    all_players_sim = [(p, team1) for p in box1] + [(p, team2) for p in box2]
    potg_entry = max(all_players_sim, key=lambda x: (x[0]['PTS'], x[0]['AST']))
    potg, potg_team = potg_entry

    # ---------------------------------------------------------------
    # STEP 7: Quarter-by-quarter score line
    # ---------------------------------------------------------------
    q1_line = f"Q1: {q1[0]}-{q2[0]}  |  Q2: {q1[1]}-{q2[1]}  |  Q3: {q1[2]}-{q2[2]}  |  Q4: {q1[3]}-{q2[3]}"

    # ---------------------------------------------------------------
    # STEP 8: Dynamic narrative based on actual sim result
    # ---------------------------------------------------------------
    margin = abs(s1 - s2)
    if margin <= 5:
        narrative = f"A NAIL-BITER. **{winner}** survived a late push from **{loser}** and escaped with the W by just {margin}. The Oracle had it this close all along."
    elif margin <= 15:
        narrative = f"**{winner}** controlled the pace and pulled away in the second half to handle **{loser}** by {margin}. Balanced scoring sealed the deal."
    else:
        narrative = f"No contest. **{winner}** put the clamps on **{loser}** early and never looked back, winning by {margin}. A statement game from jump."

    # ---------------------------------------------------------------
    # STEP 9: Build and send the embed + box scores
    # ---------------------------------------------------------------
    embed = discord.Embed(
        title=f"🔮 QCL Oracle Simulation: {team1} vs {team2}",
        description=narrative,
        color=0x32D74B
    )
    embed.add_field(
        name="🏆 Final Score",
        value=f"**{team1}:** {s1}\n**{team2}:** {s2}",
        inline=True
    )
    embed.add_field(
        name="⭐ Sim MVP",
        value=f"**{potg['Player']}** ({potg_team})\n{potg['PTS']} PTS | {potg['REB']} REB | {potg['AST']} AST",
        inline=True
    )
    embed.add_field(
        name="📊 Quarter Breakdown",
        value=f"`{team1[:10]}:` {q1[0]} | {q1[1]} | {q1[2]} | {q1[3]}\n`{team2[:10]}:` {q2[0]} | {q2[1]} | {q2[2]} | {q2[3]}",
        inline=False
    )
    embed.set_footer(text="QSPN Oracle Engine | Active Roster Simulation | 20-Min Game Pacing")

    await interaction.followup.send(embed=embed)
    await interaction.channel.send(
        format_box_block(box1, team1, s1) + "\n" +
        format_box_block(box2, team2, s2)
    )

def _quarter_flow(t1, t2):
    """Game Flow + Turning Point readout from two teams' Q1-Q4 scores. None if absent."""
    def _q(row, key):
        try:
            return int(float(row.get(key, 0) or 0))
        except Exception:
            return 0
    a = [_q(t1, c) for c in ['Q1', 'Q2', 'Q3', 'Q4']]
    b = [_q(t2, c) for c in ['Q1', 'Q2', 'Q3', 'Q4']]
    if sum(a) == 0 and sum(b) == 0:
        return None
    na, nb = str(t1['Team Name']), str(t2['Team Name'])
    lines, margins, ca, cb = [], [], 0, 0
    for i in range(4):
        ca += a[i]; cb += b[i]
        margins.append(ca - cb)
        lead = na[:14] if ca > cb else (nb[:14] if cb > ca else "Tied")
        lines.append(f"Q{i+1}: {a[i]:>3}-{b[i]:<3} | run {ca:>3}-{cb:<3} | {lead}")
    swings = [(a[i] - b[i], i) for i in range(4)]
    big = max(swings, key=lambda x: abs(x[0]))
    runner = na if big[0] > 0 else nb
    hi, lo = max(a[big[1]], b[big[1]]), min(a[big[1]], b[big[1]])
    flips, prev_sign = [], 0
    for i in range(4):
        s = 1 if margins[i] > 0 else (-1 if margins[i] < 0 else 0)
        if s != 0 and prev_sign != 0 and s != prev_sign:
            flips.append(i)
        if s != 0:
            prev_sign = s
    final = margins[3]
    winner = na if final > 0 else (nb if final < 0 else "Nobody")
    turning = flips[-1] if flips else big[1]
    head = "```\n" + "\n".join(lines) + "\n```"
    run_line = f"💥 **Biggest run:** {runner} took Q{big[1]+1} {hi}-{lo}"
    if flips:
        turn_line = f"🔑 **Turning point:** Q{turning+1} — the lead flipped and {winner} pulled ahead to stay"
    else:
        turn_line = f"🔑 **Turning point:** Q{turning+1} — {runner}'s decisive push (led wire-to-wire)"
    return head + "\n" + run_line + "\n" + turn_line


@bot.tree.command(name="boxscore", description="Pull the official Box Score for a specific Game ID.")
@app_commands.autocomplete(game_id=game_id_autocomplete)
async def boxscore(interaction: discord.Interaction, game_id: int):
    await interaction.response.defer()
    df = _cached_df
    if df is None: return await interaction.followup.send("⚠️ Stat Engine is warming up! Try again in 10s.")

    game_df = df[df['Game_ID'] == game_id].copy()
    if game_df.empty: return await interaction.followup.send(f"⚠️ Could not find Game ID: {game_id}.")

    # Game_IDs repeat across seasons — disambiguate to one season (latest with a full 2-team game).
    seasons_here = sorted(game_df['Season'].dropna().unique(), reverse=True)
    for s in seasons_here:
        if len(game_df[(game_df['Season'] == s) & (game_df['Type'] == 'Team')]) == 2:
            game_df = game_df[game_df['Season'] == s].copy()
            break

    teams = game_df[game_df['Type'] == 'Team']
    if len(teams) != 2: return await interaction.followup.send("⚠️ Game data is incomplete.")

    t1, t2 = teams.iloc[0], teams.iloc[1]
    szn_lbl = f" · S{int(t1['Season'])}" if not pd.isna(t1.get('Season')) else ""

    def _av(row, k, d=0):
        try:
            v = row.get(k, d)
            return d if pd.isna(v) else v
        except Exception:
            return d

    embed = discord.Embed(title=f"📓 Official Box Score: Game {game_id}{szn_lbl}", color=0xFFD60A)
    embed.add_field(name="Final Score", value=f"**{t1['Team Name']}**: {int(t1['PTS'])}\n**{t2['Team Name']}**: {int(t2['PTS'])}", inline=False)

    # --- Quarter-by-quarter scoreboard ---
    q1 = [int(_av(t1, c)) for c in ['Q1', 'Q2', 'Q3', 'Q4']]
    q2 = [int(_av(t2, c)) for c in ['Q1', 'Q2', 'Q3', 'Q4']]
    if sum(q1) + sum(q2) > 0:
        def _qrow(name, qs, tot):
            return f"{str(name)[:14]:<14} {qs[0]:>3} {qs[1]:>3} {qs[2]:>3} {qs[3]:>3} | {tot:>3}"
        sb = ("```\n"
              f"{'TEAM':<14} {'Q1':>3} {'Q2':>3} {'Q3':>3} {'Q4':>3} | {'TOT':>3}\n"
              + "-" * 38 + "\n"
              + _qrow(t1['Team Name'], q1, int(t1['PTS'])) + "\n"
              + _qrow(t2['Team Name'], q2, int(t2['PTS'])) + "\n```")
        embed.add_field(name="🗓️ Quarter-by-Quarter", value=sb, inline=False)

    players = game_df[game_df['Type'] == 'Player'].sort_values('PTS', ascending=False)
    if not players.empty and 'PIE_Raw' in players.columns:
        potg = players.loc[players['PIE_Raw'].idxmax()]
        embed.add_field(name="Player of the Game", value=f"⭐ **{potg['Player/Team']}** ({int(potg['PTS'])}P, {int(potg['REB'])}R, {int(_av(potg,'AST'))}A · {_av(potg,'PIE_Raw'):.1f} PIE)", inline=False)

    try:
        _flow = _quarter_flow(t1, t2)
        if _flow:
            embed.add_field(name="📈 Game Flow & Turning Point", value=_flow, inline=False)
    except Exception as _fe:
        print(f"[FLOW] {_fe}")

    # --- Team advanced comparison (modeled ratings) ---
    if any(k in t1.index for k in ('ORtg', 'Pace', 'eFG%')):
        n1, n2 = str(t1['Team Name'])[:8], str(t2['Team Name'])[:8]
        adv = ("```\n"
               f"{'':<8}{n1:>9}{n2:>9}\n"
               f"{'ORtg':<8}{_av(t1,'ORtg'):>9}{_av(t2,'ORtg'):>9}\n"
               f"{'DRtg':<8}{_av(t1,'DRtg'):>9}{_av(t2,'DRtg'):>9}\n"
               f"{'Pace':<8}{_av(t1,'Pace'):>9}{_av(t2,'Pace'):>9}\n"
               f"{'eFG%':<8}{_av(t1,'eFG%'):>9}{_av(t2,'eFG%'):>9}\n"
               f"{'TOV%':<8}{_av(t1,'TOV%'):>9}{_av(t2,'TOV%'):>9}\n```")
        embed.add_field(name="📊 Team Advanced", value=adv, inline=False)

    # --- Player box with advanced columns (MIN, OREB/DREB, BLK, eFG%, GmSc) ---
    def build_text_box(team_name):
        roster = players[players['Team Name'] == team_name]
        head = f"{'PLAYER':<12} {'MIN':>3} {'PTS':>3} {'REB':>3} {'OR':>2} {'DR':>2} {'AST':>3} {'STL':>3} {'BLK':>3} {'eFG':>4} {'GmSc':>5}"
        txt = f"**{team_name}**\n```\n{head}\n" + "-" * len(head) + "\n"
        for _, p in roster.iterrows():
            mn = _av(p, 'MIN')
            mn = f"{int(mn):>3}" if mn and mn > 0 else "  ·"
            oreb, dreb = _av(p, 'OREB'), _av(p, 'DREB')
            if (oreb + dreb) <= 0:
                oreb, dreb = _av(p, 'OREB_est'), _av(p, 'DREB_est')
            efg = _av(p, 'eFG%')
            efg = f"{efg:>4.0f}" if efg else "   ·"
            gmsc = "    ·"
            if 'Game_Score' in p.index and not pd.isna(p.get('Game_Score')):
                gmsc = f"{_av(p,'Game_Score'):>5.1f}"
            txt += (f"{str(p['Player/Team'])[:12]:<12} {mn} {int(_av(p,'PTS')):>3} {int(_av(p,'REB')):>3} "
                    f"{int(oreb):>2} {int(dreb):>2} {int(_av(p,'AST')):>3} {int(_av(p,'STL')):>3} {int(_av(p,'BLK')):>3} {efg} {gmsc}\n")
        return txt + "```"

    await interaction.followup.send(embed=embed)
    box1, box2 = build_text_box(t1['Team Name']), build_text_box(t2['Team Name'])
    if len(box1) + len(box2) > 1900:
        await interaction.channel.send(box1)
        await interaction.channel.send(box2)
    else:
        await interaction.channel.send(box1 + "\n" + box2)

@bot.tree.command(name="writeup", description="AI matchup write-up — reads the live sheet, keeps each game separate, scores verbatim.")
@app_commands.autocomplete(game_id=game_id_autocomplete)
@app_commands.describe(game_id="Any game in the matchup to write up", angle="Optional angle/focus for the story")
async def writeup(interaction: discord.Interaction, game_id: int, angle: str = None):
    await interaction.response.defer()
    if claude_client is None and ai_client is None:
        return await interaction.followup.send("⚠️ The AI writer isn't configured (no API key).")

    # ── SOURCE OF TRUTH: the live Google Sheet, read fresh on every call. ──
    # No cache, no SPAM archive, no recomputed team totals. The sheet's own
    # TOTAL rows are the final score and are used verbatim — 2K box scores can
    # look weird and we keep them exactly as logged. If a game hasn't hit the
    # sheet, it doesn't get a write-up.
    try:
        raw = await asyncio.to_thread(lambda: pd.read_csv(URL))
    except Exception as e:
        return await interaction.followup.send(f"⚠️ Couldn't reach the live sheet: `{str(e)[:200]}`")

    raw.columns = raw.columns.str.strip()
    raw = raw[raw['Player/Team'].notna() & (raw['Player/Team'].astype(str).str.strip() != '')]
    raw = raw[raw['Player/Team'].astype(str) != 'Player/Team']
    raw = raw[raw['Team Name'].notna() & (raw['Team Name'].astype(str).str.strip() != '') & (raw['Team Name'].astype(str) != '0')]
    if raw.empty:
        return await interaction.followup.send("⚠️ The live sheet is empty right now.")

    _numc = ['PTS', 'REB', 'AST', 'STL', 'BLK', 'FOULS', 'TO', 'FGM', 'FGA', '3PM', '3PA',
             'FTM', 'FTA', 'OREB', 'DREB', 'MIN', 'Q1', 'Q2', 'Q3', 'Q4', 'Game_ID', 'Win', 'Season']
    for c in _numc:
        if c not in raw.columns:
            raw[c] = 0
        raw[c] = pd.to_numeric(raw[c], errors='coerce').fillna(0)
    raw['Type'] = raw['Type'].astype(str).str.strip()
    raw['Team Name'] = raw['Team Name'].astype(str).str.strip()
    raw.loc[raw['Team Name'] == 'ChosenOne', 'Team Name'] = 'Smoke Chasers'

    _tl = raw['Type'].str.lower()
    raw['_is_total'] = _tl.isin(['total', 'team'])
    raw['_is_player'] = _tl == 'player'

    sel = raw[raw['Game_ID'] == game_id]
    if sel.empty:
        _avail = ", ".join(str(int(x)) for x in sorted(raw['Game_ID'].dropna().unique())[-10:])
        return await interaction.followup.send(
            f"⚠️ Game **{game_id}** hasn't hit the sheet yet — no write-up until it's logged.\n"
            f"Most recent Game IDs on the sheet: `{_avail or 'none'}`")

    # Lock to one season (latest that actually carries this game_id).
    _seasons = sorted(sel['Season'].dropna().unique(), reverse=True)
    season = _seasons[0] if _seasons else 0
    sdf = raw[raw['Season'] == season].copy()

    req_teams = sorted(set(sdf[sdf['Game_ID'] == game_id]['Team Name'].unique()))
    if len(req_teams) < 2:
        return await interaction.followup.send(
            f"⚠️ Game **{game_id}** only has one team logged so far ({', '.join(req_teams) or 'none'}). "
            f"Both teams need to be on the sheet before a write-up.")

    # ── Find the full matchup: same two teams, contiguous Game_IDs (a 2K set is
    # usually a 2-game series — Game 1 & Game 2 sit on adjacent IDs). ──
    cands = []
    for gid, grp in sdf.groupby('Game_ID'):
        if sorted(set(grp['Team Name'].unique())) == req_teams:
            cands.append(int(gid))
    cands = sorted(cands)
    _groups, _cur = [], [cands[0]]
    for g in cands[1:]:
        if g - _cur[-1] <= 4:
            _cur.append(g)
        else:
            _groups.append(_cur)
            _cur = [g]
    _groups.append(_cur)
    matchup_ids = next((grp for grp in _groups if game_id in grp), [game_id])

    def _num(v, d=0):
        try:
            return d if pd.isna(v) else v
        except Exception:
            return d

    def _adv(p):
        fga, fgm, tpm = _num(p['FGA']), _num(p['FGM']), _num(p['3PM'])
        fta, ftm, pts = _num(p['FTA']), _num(p['FTM']), _num(p['PTS'])
        efg = (fgm + 0.5 * tpm) / fga if fga > 0 else 0.0
        ts = pts / (2 * (fga + 0.44 * fta)) if (fga + 0.44 * fta) > 0 else 0.0
        gmsc = (pts + 0.4 * fgm - 0.7 * fga - 0.4 * (fta - ftm)
                + 0.7 * _num(p['OREB']) + 0.3 * _num(p['DREB'])
                + _num(p['STL']) + 0.7 * _num(p['AST']) + 0.7 * _num(p['BLK'])
                - 0.4 * _num(p['FOULS']) - _num(p['TO']))
        return efg, ts, gmsc

    def _classify(margin, wname, lname):
        if margin == 0:
            return f"DEAD HEAT — {wname} and {lname} tied at the buzzer; write it as a final-seconds dogfight."
        if margin <= 3:
            return (f"NAIL-BITER — {wname} edged {lname} by {margin}. Decided on the final possession(s). "
                    f"Do NOT call this a blowout or comfortable.")
        if margin <= 7:
            return (f"CLOSE GAME — {wname} held off {lname} by {margin}. Competitive to the wire; earned late. "
                    f"Do NOT frame it as dominant, a runaway, or a blowout.")
        if margin <= 14:
            return f"SOLID WIN — {wname} beat {lname} by {margin}. Controlled without a true runaway."
        return f"BLOWOUT — {wname} routed {lname} by {margin}. In command; a statement/dominant showing."

    A, B = req_teams[0], req_teams[1]
    series = {A: 0, B: 0}
    game_blocks = []      # AI payload, one per game
    score_lines = []      # verbatim final scores for the embed
    all_top = []          # (gmsc, player_name) across the matchup

    for _i, gid in enumerate(matchup_ids, start=1):
        g = sdf[sdf['Game_ID'] == gid]
        totals = g[g['_is_total']]
        players = g[g['_is_player']]
        team_stat = {}
        for tname in req_teams:
            trow = totals[totals['Team Name'] == tname]
            if not trow.empty:
                r = trow.iloc[0]
                pts = int(round(_num(r['PTS'])))
                q = [int(round(_num(r[c]))) for c in ['Q1', 'Q2', 'Q3', 'Q4']]
                fgm, fga = int(_num(r['FGM'])), int(_num(r['FGA']))
                tpm, tpa = int(_num(r['3PM'])), int(_num(r['3PA']))
                reb, ast, to = int(_num(r['REB'])), int(_num(r['AST'])), int(_num(r['TO']))
            else:
                # No TOTAL row logged → single un-doubled player sum (never re-summed on top of a total).
                pr = players[players['Team Name'] == tname]
                pts = int(round(pr['PTS'].sum()))
                q = [0, 0, 0, 0]
                fgm = int(pr['FGM'].sum()); fga = int(pr['FGA'].sum())
                tpm = int(pr['3PM'].sum()); tpa = int(pr['3PA'].sum())
                reb = int(pr['REB'].sum()); ast = int(pr['AST'].sum()); to = int(pr['TO'].sum())
            efg = (fgm + 0.5 * tpm) / fga if fga > 0 else 0.0
            team_stat[tname] = dict(pts=pts, q=q, fgm=fgm, fga=fga, tpm=tpm, tpa=tpa,
                                    reb=reb, ast=ast, to=to, efg=efg)
        pa, pb = team_stat[A]['pts'], team_stat[B]['pts']
        wname, lname = (A, B) if pa >= pb else (B, A)
        if pa != pb:
            series[wname] += 1
        margin = abs(pa - pb)
        shape = _classify(margin, wname, lname)

        qa, qb = team_stat[A]['q'], team_stat[B]['q']
        if sum(qa) + sum(qb) > 0:
            ca = cb = 0
            worst = 0
            w_is_a = pa >= pb
            for k in range(4):
                ca += qa[k]; cb += qb[k]
                wl = (ca - cb) if w_is_a else (cb - ca)
                if wl < worst:
                    worst = wl
            if worst <= -8:
                shape += f" COMEBACK: {wname} trailed by as many as {abs(worst)} before winning."

        score_lines.append(f"Game {_i} (ID {gid}): {A} {pa}, {B} {pb}")

        pl = players.copy()
        pl['_gmsc'] = pl.apply(lambda r: _adv(r)[2], axis=1)
        ptxt = []
        for _, p in pl.sort_values('_gmsc', ascending=False).head(5).iterrows():
            efg, ts, gmsc = _adv(p)
            ptxt.append(f"  {p['Player/Team']} ({p['Team Name']}): "
                        f"{int(_num(p['PTS']))}p/{int(_num(p['REB']))}r/{int(_num(p['AST']))}a, "
                        f"{int(_num(p['STL']))}stl {int(_num(p['BLK']))}blk, "
                        f"{int(_num(p['FGM']))}/{int(_num(p['FGA']))} FG, "
                        f"{int(_num(p['3PM']))}/{int(_num(p['3PA']))} 3PT, "
                        f"GmSc {gmsc:.1f}, eFG {efg*100:.0f}%, TS {ts*100:.0f}%")
            all_top.append((gmsc, p['Player/Team']))

        def _tline(t):
            s = team_stat[t]
            return (f"  {t}: {s['pts']} pts | Q {'-'.join(map(str, s['q'])) if sum(s['q'])>0 else 'n/a'} | "
                    f"{s['fgm']}/{s['fga']} FG, {s['tpm']}/{s['tpa']} 3PT, {s['ast']} AST, {s['reb']} REB, "
                    f"{s['to']} TO, eFG {s['efg']*100:.0f}%")

        block = (f"=== GAME {_i} of the matchup (Sheet ID {gid}) — FINAL: {A} {pa}, {B} {pb} ===\n"
                 f"GAME SHAPE (authoritative — honor this angle exactly): {shape}\n"
                 f"TEAM LINES:\n{_tline(A)}\n{_tline(B)}\n"
                 f"TOP PERFORMERS (by Game Score):\n" + "\n".join(ptxt))
        game_blocks.append(block)

    if not game_blocks:
        return await interaction.followup.send("⚠️ Couldn't assemble team totals from the sheet for this matchup.")

    n_games = len(game_blocks)
    if n_games > 1:
        if series[A] == series[B]:
            series_line = f"SERIES: {A} and {B} split the {n_games}-game set {series[A]}-{series[B]}."
        else:
            sw = A if series[A] > series[B] else B
            series_line = f"SERIES: {sw} took the {n_games}-game set {max(series.values())}-{min(series.values())}."
    else:
        series_line = "SINGLE GAME (no series)."

    data = (f"MATCHUP: {A} vs {B} — Season {int(season)}, {n_games}-game set.\n"
            f"{series_line}\n\n"
            + "\n\n".join(game_blocks))
    if angle:
        data += f"\n\nREQUESTED ANGLE: {angle}"

    if n_games > 1:
        system_prompt = f"""You are the lead writer and broadcaster for QCL (Qwik's Cup League), an NBA 2K Pro-Am league. Write a matchup recap covering all {n_games} games below.

HARD RULES:
- Cover EACH GAME SEPARATELY, in order (Game 1, then Game 2, ...). Give each game its own paragraph with its own final score and story. NEVER merge, average, or combine scores or stats across games.
- Use the final scores EXACTLY as given — do not adjust, round, or "correct" them. 2K box scores can look unusual; keep them verbatim.
- MATCH THE MARGIN per game: honor each game's GAME SHAPE line. A game decided by 7 or fewer points is a CLOSE game / nail-biter — lead with late-game tension. NEVER call a single-digit game a blowout or runaway; reserve "blowout/dominant/statement" for double-digit margins.
- Open with a one-line series frame, then Game 1, then Game 2 (and so on), then a short closing line on the series result.
- Spotlight 2-3 standout performances per game with real stats (points, shooting splits, Game Score, eFG/TS).
- ~130-170 words per game. Invent nothing; no fabricated quotes."""
    else:
        system_prompt = """You are the lead writer and broadcaster for QCL (Qwik's Cup League), an NBA 2K Pro-Am league. Turn the single game below into a sharp recap.

HARD RULES:
- 220-300 words. Broadcast/blog voice: vivid but grounded in the actual numbers.
- Use the final score EXACTLY as given — do not adjust or round it. 2K box scores can look unusual; keep them verbatim.
- MATCH THE MARGIN: honor the GAME SHAPE line. A game decided by 7 or fewer points is a CLOSE game / nail-biter — lead with the late-game tension. NEVER call a single-digit game a blowout or runaway; reserve "blowout/dominant/statement" for double-digit margins.
- LEAD with the result and the decisive run; walk the quarters naturally.
- Spotlight 2-3 standout performances with real stats (points, splits, Game Score, eFG/TS).
- Invent nothing; no fabricated quotes. End on a short, punchy line."""

    try:
        story, _src = await ask_ai(system_prompt, data, max_tokens=1400)
        _kind = "Matchup" if n_games > 1 else "Game"
        embed = discord.Embed(
            title=f"📝 {A} vs {B} — {_kind} Write-Up",
            description=story[:4000], color=0xFFD60A)
        # Verbatim scores straight from the sheet — the un-adjusted source of truth,
        # each game shown separately.
        embed.add_field(name="🏀 Final Scores (from the sheet)",
                        value="\n".join(score_lines), inline=False)
        if n_games > 1:
            embed.add_field(name="📊 Series", value=series_line.replace('SERIES: ', ''), inline=False)
        # QCL law: prose stays gamertag-based; onboarded featured players get a
        # ping. Resolve EXACT gamertag first (case-insensitive), then fall back to
        # the collision-safe normalized map — never tag an ambiguous/wrong user.
        _st = load_state()
        _removed = {str(x) for x in _st.get('removed_users', []) or []}
        _exact = {}
        for _uid, _u in (_st.get('users', {}) or {}).items():
            if str(_uid) in _removed:
                continue
            _gt = (_u or {}).get('gamertag')
            if _gt:
                _exact.setdefault(str(_gt).strip().lower(), str(_uid))
        _om = get_onboarded_map(_st)
        def _resolve_featured(_name):
            u = _exact.get(str(_name).strip().lower())   # exact gamertag match = safe
            return u or _om.get(_id_key(_name))           # else unambiguous normalized match
        _seen, _featured = set(), []
        for _gmsc, _pname in sorted(all_top, key=lambda x: x[0], reverse=True):
            _u = _resolve_featured(_pname)
            if _u and _u not in _seen:
                _seen.add(_u)
                _featured.append((_pname, _u))
        if _featured:
            embed.add_field(
                name="🪪 Featured (onboarded)",
                value=" · ".join(f"<@{u}> (`{u}`)" for _n, u in _featured[:6]),
                inline=False)
        embed.set_footer(text=f"S{int(season)} • {n_games}-game set • live-sheet recap, scores logged verbatim")
        await interaction.followup.send(embed=embed)
    except Exception as e:
        await interaction.followup.send(f"❌ Write-up error: `{str(e)[:300]}`")

@office_group.command(name="coach_desk", description="[Coach] Access the Coach Hub to manage roster, logos, and fines.")
async def coachdesk(interaction: discord.Interaction, pin: str):
    state = load_state()
    uid = str(interaction.user.id)
    claim = state.get('team_claims', {}).get(uid)
    
    if not claim or claim.get('pin') != pin:
        return await interaction.response.send_message("🚫 **Access Denied.** Invalid PIN or you are not a registered Coach.", ephemeral=True)
        
    team_name = claim.get('team', 'Unknown Team')
    embed = discord.Embed(title=f"👔 COACH DESK: {team_name}", description="Welcome to the front office. Manage your franchise operations below.", color=0x2c2f33)
    logo = state.get('team_logos', {}).get(team_name)
    if logo: embed.set_thumbnail(url=logo)
    
    await interaction.response.send_message(embed=embed, view=CoachDeskView(uid, team_name), ephemeral=True)

@office_group.command(name="propose_game", description="[Public] Propose a locked matchup for the Mayor's Office to approve.")
@app_commands.autocomplete(team1=roster_team_autocomplete, team2=roster_team_autocomplete)
async def propose_game(interaction: discord.Interaction, team1: str, team2: str, time_est: str = "TBD"):
    await interaction.response.defer()
    state = load_state()
    uid = str(interaction.user.id)
        
    bets, readout = run_1287_monte_carlo(team1, team2)
    if not bets: return await interaction.followup.send(readout)
    
    # Package the game into an inbox ticket instead of locking it immediately
    import uuid
    ticket = {
        "id": str(uuid.uuid4())[:8],
        "uid": uid,
        "type": "lockgame",
        "team1": team1,
        "team2": team2,
        "time_est": time_est,
        "bets": bets,
        "readout": readout,
        "timestamp": time.time()
    }
    
    # Send it to the Mayor's Office Inbox
    if 'admin_inbox' not in state: state['admin_inbox'] = []
    state['admin_inbox'].append(ticket)
    save_state(state)
    
    embed = discord.Embed(title="📨 Proposal Sent to the Mayor's Office", description=f"**{team1} vs {team2}**\n\nThe AI Oracle generated 50 sharp props for this matchup. It is sitting on the Mayor's desk waiting for approval to be put on the Vegas Board.", color=0x0A84FF)
    await interaction.followup.send(embed=embed)

# ==========================================
# --- QCL RPG: CORE FOUNDATION ---
# ==========================================

def init_rpg_profile(uid, state):
    uid = str(uid)
    if 'rpg' not in state: state['rpg'] = {}
    if 'balances' not in state: state['balances'] = {}
    if uid not in state['balances']: state['balances'][uid] = 0

    if uid not in state['rpg']:
        state['rpg'][uid] = {
            "energy": 100,
            "heat": 0,
            "injury": "Healthy",
            "rep": "Walk-On",
            "rep_points": 0,
            "juice_active": False,
            "cupbucks": 0,
            "jail_time": 0,
            "last_checkin": "",
            "streak": 0,
            "quests": [],
            "activity_score": 0 # <-- NEW: TRACKS WEEKLY DISCORD CHAT LEVEL
        }    
    # Failsafe for older profiles that don't have the quest tracker yet
    if "quests" not in state['rpg'][uid]:
        state['rpg'][uid]["last_checkin"] = ""
        state['rpg'][uid]["streak"] = 0
        state['rpg'][uid]["quests"] = []
    if "rep_points" not in state['rpg'][uid]:
        state['rpg'][uid]["rep_points"] = 0
        
    return state

# ════════════════════════════════════════════════════════════════════
#  RPG IMMERSION ENGINE
#  Every meaningful league action routes through _rpg_award(), moving
#  rep / heat / energy. Heat & Energy carry real stakes (jail risk,
#  action gating) and each event fires a short popup.
# ════════════════════════════════════════════════════════════════════
REP_TIERS = [
    (0,    "Walk-On"),
    (150,  "Rotation"),
    (400,  "Starter"),
    (800,  "Franchise"),
    (1500, "All-Star"),
    (2500, "Superstar"),
    (4000, "Legend"),
]


def _rep_title(points):
    title = REP_TIERS[0][1]
    for threshold, name in REP_TIERS:
        if points >= threshold:
            title = name
        else:
            break
    return title


def _rpg_clamp(v, lo, hi):
    return max(lo, min(hi, v))


def _rpg_award(state, uid, rep=0, heat=0, energy=0, cupbucks=0, reason=""):
    """Apply RPG stat changes in place (caller saves). Returns the deltas applied
    plus context for the popup. Crime/jail titles are preserved while jailed."""
    uid = str(uid)
    init_rpg_profile(uid, state)
    rpg = state['rpg'][uid]
    rpg.setdefault('rep_points', 0)
    before_title = _rep_title(int(rpg.get('rep_points', 0)))
    if rep:
        rpg['rep_points'] = max(0, int(rpg.get('rep_points', 0)) + rep)
    if heat:
        rpg['heat'] = _rpg_clamp(int(rpg.get('heat', 0)) + heat, 0, 100)
    if energy:
        rpg['energy'] = _rpg_clamp(int(rpg.get('energy', 0)) + energy, 0, 100)
    if cupbucks:
        rpg['cupbucks'] = max(0, int(rpg.get('cupbucks', 0)) + cupbucks)
    after_title = _rep_title(int(rpg.get('rep_points', 0)))
    # only refresh the visible title from rep when they're not locked in a crime/jail state
    if int(rpg.get('jail_time', 0)) <= 0:
        rpg['rep'] = after_title
    return {
        'uid': uid, 'reason': reason,
        'rep': rep, 'heat': heat, 'energy': energy, 'cupbucks': cupbucks,
        'rep_points': int(rpg.get('rep_points', 0)),
        'heat_now': int(rpg.get('heat', 0)), 'energy_now': int(rpg.get('energy', 0)),
        'title': after_title,
        'promoted': (after_title != before_title and rep > 0),
        'demoted': (after_title != before_title and rep < 0),
    }


def award_rpg(uid, rep=0, heat=0, energy=0, cupbucks=0, reason=""):
    """Standalone load+save version for callers without state in hand."""
    state = load_state()
    d = _rpg_award(state, uid, rep=rep, heat=heat, energy=energy, cupbucks=cupbucks, reason=reason)
    save_state(state)
    return d


def _rpg_energy_ok(state, uid, cost):
    """True if the user has at least `cost` energy (used to gate crime/casino games)."""
    init_rpg_profile(str(uid), state)
    return int(state['rpg'][str(uid)].get('energy', 0)) >= cost


def _rpg_jail_risk(state, uid):
    """High heat = the law may catch up. Returns True if they should be busted now."""
    uid = str(uid)
    init_rpg_profile(uid, state)
    if int(state['rpg'][uid].get('jail_time', 0)) > 0:
        return False
    heat = int(state['rpg'][uid].get('heat', 0))
    if heat < 60:
        return False
    chance = (heat - 60) / 100.0 + 0.10   # 60 heat ~10% ... 100 heat ~50%
    return random.random() < chance


def _rpg_ping_embed(uid, d, member=None):
    bits = []
    if d.get('rep'):
        bits.append(f"🎖️ Rep {'+' if d['rep'] > 0 else ''}{d['rep']}")
    if d.get('heat'):
        bits.append(f"🚓 Heat {'+' if d['heat'] > 0 else ''}{d['heat']}")
    if d.get('energy'):
        bits.append(f"🔋 Energy {'+' if d['energy'] > 0 else ''}{d['energy']}")
    if d.get('cupbucks'):
        bits.append(f"💰 {'+' if d['cupbucks'] > 0 else ''}{d['cupbucks']} SB")
    who = member.display_name if member else f"<@{uid}>"
    color = 0x32D74B if d.get('rep', 0) >= 0 else 0xFF453A
    e = discord.Embed(color=color, description=f"**{who}** — {d.get('reason', 'Activity')}\n" + "  •  ".join(bits))
    e.set_footer(text=f"{d.get('title', 'Walk-On')} · {d.get('rep_points', 0):,} rep · 🚓 {d.get('heat_now', 0)}/100 · 🔋 {d.get('energy_now', 0)}/100")
    if d.get('promoted'):
        e.title = f"⬆️ PROMOTED TO {d['title'].upper()}!"
    elif d.get('demoted'):
        e.title = f"⬇️ Dropped to {d['title']}"
    return e


async def _rpg_ping(channel, uid, d, member=None):
    """Post a single-player RPG popup. Silent-safe; skips if nothing changed."""
    try:
        if not d or not any([d.get('rep'), d.get('heat'), d.get('energy'), d.get('cupbucks')]):
            return
        await channel.send(embed=_rpg_ping_embed(uid, d, member))
    except Exception as ex:
        print(f"[RPG] ping error: {ex}")


async def _rpg_ping_group(channel, deltas, title="🎮 Night Results — Rep Update"):
    """One combined popup for a multi-player event (e.g. a game result)."""
    try:
        deltas = [d for d in deltas if d and (d.get('rep') or d.get('heat') or d.get('energy'))]
        if not deltas:
            return
        e = discord.Embed(title=title, color=0xFFD60A)
        lines = []
        for d in deltas[:25]:
            chg = []
            if d.get('rep'):
                chg.append(f"🎖️{'+' if d['rep'] > 0 else ''}{d['rep']}")
            if d.get('heat'):
                chg.append(f"🚓{'+' if d['heat'] > 0 else ''}{d['heat']}")
            if d.get('energy'):
                chg.append(f"🔋{'+' if d['energy'] > 0 else ''}{d['energy']}")
            tag = " ⬆️" if d.get('promoted') else (" ⬇️" if d.get('demoted') else "")
            lines.append(f"<@{d['uid']}> — {'  '.join(chg)}  ·  {d.get('title', '')}{tag}")
        e.description = "\n".join(lines)
        await channel.send(embed=e)
    except Exception as ex:
        print(f"[RPG] group ping error: {ex}")


# ==========================================
# --- THE ULTIMATE QCL ID CARD (v3) ---
# ==========================================

@bot.tree.command(name="my_life", description="[RPG] View your QCL ID, Bank, Stats, Record, and Bio.")
async def my_life(interaction: discord.Interaction):
    await interaction.response.defer()
    
    state = load_state()
    uid = str(interaction.user.id)
    state = init_rpg_profile(uid, state)
    rpg = state['rpg'][uid]
    
    # Grab their User Data
    user_data = state.setdefault('users', {}).get(uid, {})
    gamertag = user_data.get('gamertag', 'Unknown (Run /onboard)')
    team = user_data.get('team', 'Free Agent')
    quote = user_data.get('quote', "I let my game speak for itself.")
    vc_balance = state['balances'].get(uid, 0)
    
    # Check for Admin Record Overrides
    manual_w = user_data.get('manual_wins')
    manual_l = user_data.get('manual_losses')
    
    global _cached_df
    df = _cached_df
    
    record_text = "0-0"
    stat_text = "No games played yet."
    
    # --- ORACLE STATS ENGINE ---
    if df is not None and gamertag != 'Unknown (Run /onboard)':
        p_df = df[(df['Type'].astype(str).str.lower() == 'player') & (df['Player/Team'].astype(str).str.lower() == gamertag.lower())]
        
        if not p_df.empty:
            # Check if Admin Overrode the record. If not, calculate it.
            if manual_w is not None and manual_l is not None:
                record_text = f"**{manual_w} - {manual_l}** *(League Verified)*"
            else:
                games_played = p_df['Game_ID'].nunique()
                wins = int(p_df['Win'].sum())
                losses = games_played - wins
                record_text = f"**{wins} - {losses}**"
            
            # Calculate Averages
            ppg = p_df['PTS'].mean()
            apg = p_df['AST'].mean()
            rpg_stat = p_df['REB'].mean()
            pie = p_df['PIE_Raw'].mean()
            stat_text = f"**{ppg:.1f}** PPG | **{apg:.1f}** APG | **{rpg_stat:.1f}** RPG | **{pie:.1f}** PIE"
            
    # If the database is completely empty but the admin overrode the record anyway:
    elif manual_w is not None and manual_l is not None:
        record_text = f"**{manual_w} - {manual_l}** *(League Verified)*"
    
    # --- BUILD THE ID CARD ---
    # We put the quote right at the top in italics
    _is_onboarded = gamertag != 'Unknown (Run /onboard)' and uid in state.get('users', {})
    _identity_line = f"\n<@{uid}> (`{uid}`)" if _is_onboarded else ""   # QCL law: onboarded -> ping + ID
    embed = discord.Embed(title=f"🪪 QCL ID: {gamertag}", description=f"*{quote}*{_identity_line}", color=0x2b2d31)
    
    # Basketball Profile
    embed.add_field(name="Franchise", value=f"🏢 {team}", inline=True)
    embed.add_field(name="Season Record", value=f"🏆 {record_text}", inline=True)
    embed.add_field(name="Live Stats", value=stat_text, inline=False)
    
    # Street Profile
    embed.add_field(name="💰 Bank (VC)", value=f"{vc_balance:,}", inline=True)
    embed.add_field(name="💵 Black Market", value=f"{rpg['cupbucks']:,} SB", inline=True)
    embed.add_field(name="🏷️ Street Rep", value=f"{rpg['rep']}\n{rpg.get('rep_points', 0):,} rep", inline=True)
    
    # Vitals
    embed.add_field(name="🔋 Energy", value=f"{rpg['energy']}/100", inline=True)
    embed.add_field(name="🚓 League Heat", value=f"{rpg['heat']}/100", inline=True)
    
    # Active Effects
    effects = []
    if rpg['juice_active']: effects.append("💉 Juiced Up")
    if rpg['jail_time'] > 0: effects.append(f"⛓️ In Jail ({rpg['jail_time']} hours left)")
    
    if effects: embed.add_field(name="Active Status Effects", value=" | ".join(effects), inline=False)
        
    embed.set_thumbnail(url=interaction.user.display_avatar.url)
    await interaction.followup.send(embed=embed)

