def init_central_bank(state):
    """Ensures the Central Reserve exists and is funded."""
    if 'central_bank' not in state:
        state['central_bank'] = {
            "vc_vault": 500000000 # The starting 500 Million VC
        }
    return state

@bot.tree.command(name="the_bank", description="[Public] View the current holdings of the QCL Central Reserve.")
async def the_bank(interaction: discord.Interaction):
    state = load_state()
    state = init_central_bank(state)
    
    vault_balance = state['central_bank']['vc_vault']
    
    embed = discord.Embed(title="🏦 QCL Central Reserve", color=0xFFD60A)
    embed.description = "The Federal Vault collects all league taxes, fines, and casino losses. If you are crazy enough to plan a heist, this is what you are stealing."
    embed.add_field(name="Current Vault Balance", value=f"**{vault_balance:,} VC**", inline=False)
    
    # Add a little flavor warning
    embed.set_footer(text="Security Level: Maximum | Monitored by the Commissioner")
    await interaction.response.send_message(embed=embed)

@admin_group.command(name="mint", description="[Admin] Print money directly into a player's wallet.")
@app_commands.describe(
    pin="Master Admin PIN",
    target="The player receiving the funds",
    amount="How much money to print",
    currency="VC or CUPBUCKS"
)
@app_commands.choices(currency=[
    app_commands.Choice(name="💰 VC", value="vc"),
    app_commands.Choice(name="💵 CUPBUCKS", value="cupbucks")
])
async def admin_mint(interaction: discord.Interaction, pin: str, target: discord.Member, amount: int, currency: app_commands.Choice[str]):
    if not admin_pin_matches(pin, interaction):
        return await interaction.response.send_message("🚫 **Access Denied.** Invalid PIN.", ephemeral=True)
        
    if amount <= 0:
        return await interaction.response.send_message("❌ Amount must be greater than 0.", ephemeral=True)

    state = load_state()
    t_uid = str(target.id)
    state = init_rpg_profile(t_uid, state) # Ensure they have a profile first
    
    if currency.value == "vc":
        state['balances'][t_uid] += amount
        icon = "💰"
        currency_name = "VC"
    else:
        state['rpg'][t_uid]['cupbucks'] += amount
        icon = "💵"
        currency_name = "CUPBUCKS"
        
    save_state(state)
    await interaction.response.send_message(f"✅ **Money Printer Goes Brrr:** Minted {icon} **{amount:,} {currency_name}** into {target.mention}'s account.")

@admin_group.command(name="tax", description="[Admin] Seize funds from a player and return it to the Bank.")
@app_commands.describe(
    pin="Master Admin PIN",
    target="The player getting taxed",
    amount="How much money to seize",
    currency="VC or CUPBUCKS"
)
@app_commands.choices(currency=[
    app_commands.Choice(name="💰 VC", value="vc"),
    app_commands.Choice(name="💵 CUPBUCKS", value="cupbucks")
])
async def admin_tax(interaction: discord.Interaction, pin: str, target: discord.Member, amount: int, currency: app_commands.Choice[str]):
    if not admin_pin_matches(pin, interaction):
        return await interaction.response.send_message("🚫 **Access Denied.** Invalid PIN.", ephemeral=True)
        
    if amount <= 0:
        return await interaction.response.send_message("❌ Amount must be greater than 0.", ephemeral=True)

    state = load_state()
    t_uid = str(target.id)
    state = init_rpg_profile(t_uid, state)
    state = init_central_bank(state)
    
    if currency.value == "vc":
        # Make sure we don't tax more than they have
        actual_tax = min(amount, state['balances'][t_uid])
        state['balances'][t_uid] -= actual_tax
        # Seized VC goes back to the Bank
        state['central_bank']['vc_vault'] += actual_tax
        icon = "💰"
        currency_name = "VC"
    else:
        actual_tax = min(amount, state['rpg'][t_uid]['cupbucks'])
        state['rpg'][t_uid]['cupbucks'] -= actual_tax
        # Seized CUPBUCKS are black market money, they just get destroyed/burned
        icon = "💵"
        currency_name = "CUPBUCKS"
        
    save_state(state)
    
    embed = discord.Embed(title="🚨 IRS Seizure", color=0xFF453A)
    embed.description = f"The League has seized {icon} **{actual_tax:,} {currency_name}** from {target.mention}."
    if currency.value == "vc":
        embed.set_footer(text="These funds have been deposited into the Central Reserve.")
        
    await interaction.response.send_message(embed=embed)

