@casino_group.command(name="kings", description="[Underground] View the richest players in the CUPBUCKS black market.")
async def underground_kings(interaction: discord.Interaction):
    state = load_state()
    
    # Failsafe if nobody has played yet
    if 'rpg' not in state or not state['rpg']:
        return await interaction.response.send_message("🌃 The streets are empty. No one has any CUPBUCKS yet.", ephemeral=True)
        
    # Sort the RPG profiles by whoever has the most CUPBUCKS
    sorted_hustlers = sorted(
        state['rpg'].items(), 
        key=lambda item: item[1].get('cupbucks', 0), 
        reverse=True
    )
    
    embed = discord.Embed(title="🌃 The Underground Kings", description="The richest players in the the QCL Black Market.", color=0x2b2d31)
    
    board_text = ""
    rank = 1
    
    # Loop through the sorted list and build the text
    for uid, data in sorted_hustlers:
        sb = data.get('cupbucks', 0)
        if sb > 0: # Only show people who actually have money
            board_text += f"**{rank}.** <@{uid}> - 💵 **{sb:,}** SB\n"
            rank += 1
        
        # Stop after the Top 10
        if rank > 10: 
            break
            
    if not board_text:
        board_text = "Everyone is completely broke."
        
    embed.add_field(name="Top 10 Hustlers", value=board_text)
    embed.set_footer(text="Untraceable Currency | Black Market Rankings")
    
    await interaction.response.send_message(embed=embed)

