class ShotMeterView(discord.ui.View):
    def __init__(self, user_id, wager):
        super().__init__(timeout=15)
        self.user_id = str(user_id)
        self.wager = wager
        self.start_time = time.time()

    @discord.ui.button(label="SHOOT 🏀", style=discord.ButtonStyle.success)
    async def shoot(self, interaction: discord.Interaction, button: discord.ui.Button):
        if str(interaction.user.id) != self.user_id: return await interaction.response.send_message("🚫 Get off the court!", ephemeral=True)
            
        elapsed = time.time() - self.start_time
        for child in self.children: child.disabled = True
            
        state = load_state()
        uid = self.user_id
        
        # Green window is exactly between 2.0 and 2.4 seconds
        if 2.0 <= elapsed <= 2.4:
            winnings = self.wager * 2
            state['rpg'][uid]['cupbucks'] += winnings
            embed = discord.Embed(title="🟢 GREEN BEAN!", description=f"Perfect release! ({elapsed:.2f}s)\nYou won 💵 **{winnings:,} CUPBUCKS**.", color=0x32D74B)
        elif 1.8 <= elapsed < 2.0 or 2.4 < elapsed <= 2.6:
            state['rpg'][uid]['cupbucks'] += self.wager # Push
            embed = discord.Embed(title="⚪ FULL WHITE...", description=f"Slightly off timing ({elapsed:.2f}s). Rimmed out, got your 💵 **{self.wager:,} CUPBUCKS** back.", color=0xFF9F0A)
        else:
            embed = discord.Embed(title="🧱 BRICK!", description=f"Terrible release ({elapsed:.2f}s). You lost 💵 **{self.wager:,} CUPBUCKS**.", color=0xFF453A)
            
        save_state(state)
        await interaction.response.edit_message(embed=embed, view=self)
        self.stop()

@yard_group.command(name="shot_meter", description="[Underground Casino] Bet CUPBUCKS and try to green the shot meter!")
async def shot_meter(interaction: discord.Interaction, wager: int):
    if wager <= 0: return await interaction.response.send_message("❌ Wager must be greater than 0.", ephemeral=True)
        
    state = load_state()
    uid = str(interaction.user.id)
    state = init_rpg_profile(uid, state)
    
    if state['rpg'][uid]['cupbucks'] < wager: return await interaction.response.send_message(f"🚫 **Insufficient Funds.**", ephemeral=True)
        
    state['rpg'][uid]['cupbucks'] -= wager
    save_state(state)
    
    embed = discord.Embed(title="🏀 The Underground Shot Meter", description=f"Betting 💵 **{wager:,} CUPBUCKS**...\n\n**INSTRUCTIONS:** Click the SHOOT button exactly between **2.0 and 2.4 seconds** after this message appears to hit the Green Window!", color=0x2b2d31)
    await interaction.response.send_message(embed=embed, view=ShotMeterView(uid, wager))

