# --- GAME 1: THE SPEED BAG (REACTION) ---
# ==========================================
import asyncio
import random
import time

class SpeedBagView(discord.ui.View):
    def __init__(self, user_id, wager, multiplier):
        super().__init__(timeout=20)
        self.user_id = str(user_id)
        self.wager = wager
        self.multiplier = multiplier
        self.start_time = 0
        self.clicked = False
        self.early_clicked = False

    @discord.ui.button(label="⏳ WAIT FOR IT...", style=discord.ButtonStyle.danger, disabled=True, custom_id="hit_btn")
    async def hit(self, interaction: discord.Interaction, button: discord.ui.Button):
        if str(interaction.user.id) != self.user_id:
            return await interaction.response.send_message("🚫 Not your bag, back up.", ephemeral=True)

        self.clicked = True
        reaction_ms = (time.time() - self.start_time) * 1000  # work in milliseconds — Discord latency is real

        state = load_state()
        uid = self.user_id

        # Tiered windows — accounts for Discord's ~100-250ms average interaction latency
        # Sub-250ms = elite | 250-450ms = clean | 450-700ms = slow | 700ms+ = dead
        if reaction_ms <= 250:
            winnings = int(self.wager * 2.5 * self.multiplier)
            tier_title = "🥊 HANDS OF GOD!"
            tier_desc = f"**{reaction_ms:.0f}ms** — That's ELITE reflexes. Nobody moving like you."
            color = 0xffd700
        elif reaction_ms <= 450:
            winnings = self.wager * self.multiplier
            tier_title = "🥊 CLEAN HIT!"
            tier_desc = f"**{reaction_ms:.0f}ms** — Solid reaction. You got paid."
            color = 0x00ff00
        elif reaction_ms <= 700:
            winnings = self.wager // 2  # get half back
            tier_title = "🥊 GRAZED IT..."
            tier_desc = f"**{reaction_ms:.0f}ms** — A little slow. Got half your SB back."
            color = 0xffaa00
        else:
            winnings = 0
            tier_title = "🥊 THE BAG HIT BACK!"
            tier_desc = f"**{reaction_ms:.0f}ms** — You froze up. SB gone."
            color = 0xff0000

        state['rpg'][uid]['cupbucks'] += winnings
        save_state(state)

        result_line = f"Won 💵 **{winnings:,} CUPBUCKS**!" if winnings > 0 else f"Lost 💵 **{self.wager:,} CUPBUCKS**."
        embed = discord.Embed(title=tier_title, description=f"{tier_desc}\n{result_line}", color=color)
        for child in self.children: child.disabled = True
        await interaction.response.edit_message(embed=embed, view=self)
        self.stop()

    @discord.ui.button(label="🔴 JUMP EARLY", style=discord.ButtonStyle.secondary, custom_id="early_btn")
    async def early_hit(self, interaction: discord.Interaction, button: discord.ui.Button):
        """Clicking the red button before it goes green = false start, lose your wager."""
        if str(interaction.user.id) != self.user_id:
            return await interaction.response.send_message("🚫 Back up.", ephemeral=True)
        if self.clicked or self.early_clicked:
            return
        self.early_clicked = True
        embed = discord.Embed(
            title="🚨 FALSE START!",
            description=f"You jumped early and got flagged. Lost 💵 **{self.wager:,} CUPBUCKS**.\nWait for the green next time.",
            color=0xFF453A
        )
        for child in self.children: child.disabled = True
        await interaction.response.edit_message(embed=embed, view=self)
        self.stop()

@yard_group.command(name="speed_bag", description="[Universal] Test your reflexes. Hit the green button — but don't jump early!")
async def speed_bag(interaction: discord.Interaction, wager: int):
    if wager <= 0: return await interaction.response.send_message("❌ Bet real CUPBUCKS.", ephemeral=True)

    state = load_state()
    uid = str(interaction.user.id)
    state = init_rpg_profile(uid, state)
    rpg = state['rpg'][uid]

    if rpg['cupbucks'] < wager:
        return await interaction.response.send_message("🚫 Insufficient CUPBUCKS.", ephemeral=True)

    rpg['cupbucks'] -= wager
    save_state(state)

    multiplier = 2 if rpg.get('jail_time', 0) > 0 else 1
    loc_text = "⛓️ THE YARD (2x Payout)" if multiplier == 2 else "🌃 THE UNDERGROUND"
    wait_secs = random.uniform(2.5, 6.5)  # unpredictable delay — harder to game

    view = SpeedBagView(uid, wager, multiplier)
    embed = discord.Embed(
        title=f"🥊 The Speed Bag | {loc_text}",
        description=(
            f"Wager: 💵 **{wager:,} CUPBUCKS**\n\n"
            "The bag is spinning... **wait for it to turn green.**\n"
            "🟢 Sub-250ms → **2.5x payout**\n"
            "🟡 250–450ms → **1x payout**\n"
            "🟠 450–700ms → **half back**\n"
            "🔴 700ms+ → **L**\n\n"
            "⚠️ Click **JUMP EARLY** before it goes green and you lose instantly."
        ),
        color=0x2b2d31
    )

    await interaction.response.send_message(embed=embed, view=view)
    msg = await interaction.original_response()
    await asyncio.sleep(wait_secs)

    if not view.clicked and not view.early_clicked:
        view.start_time = time.time()
        view.children[0].label = "🟢 SWING NOW! 💥"
        view.children[0].style = discord.ButtonStyle.success
        view.children[0].disabled = False
        view.children[1].disabled = True  # lock the false-start button once it's go time
        await msg.edit(view=view)

