# --- GAME 2: THE DRIBBLE DRILL (MEMORY) ---
# ==========================================

# Move pool — 5 unique moves with labels and emojis
DRIBBLE_MOVES = [
    ("⚡", "Crossover"),
    ("🔙", "Behind Back"),
    ("🌪️", "Spin Move"),
    ("↕️", "Hesitation"),
    ("🔀", "Ankle Breaker"),
]

# Combo names that display based on difficulty
COMBO_NAMES = {
    4: ["The Starter Pack", "Freshman Drills", "Baby Steps"],
    5: ["Pro Handles", "Mid-Level Magic", "The Chef Special"],
    6: ["Street King Combo", "Curry Dribbles", "The Signature"],
}

class DribbleView(discord.ui.View):
    def __init__(self, user_id, wager, multiplier, sequence, combo_name):
        super().__init__(timeout=30)
        self.user_id = str(user_id)
        self.wager = wager
        self.multiplier = multiplier
        self.sequence = sequence          # list of emoji strings in order
        self.combo_name = combo_name
        self.player_input = []

        # Dynamically add one button per unique move in the pool
        for emoji, label in DRIBBLE_MOVES:
            button = discord.ui.Button(label=label, emoji=emoji, style=discord.ButtonStyle.primary)
            button.callback = self._make_callback(emoji)
            self.add_item(button)

    def _make_callback(self, move_emoji):
        async def callback(interaction: discord.Interaction):
            await self.handle_input(interaction, move_emoji)
        return callback

    async def handle_input(self, interaction: discord.Interaction, move: str):
        if str(interaction.user.id) != self.user_id:
            return await interaction.response.send_message("🚫 Not your drill.", ephemeral=True)

        step = len(self.player_input)
        self.player_input.append(move)

        if move != self.sequence[step]:
            # Wrong move — ankles broken
            correct_chain = " → ".join(self.sequence)
            embed = discord.Embed(
                title="🤕 ANKLES BROKEN!",
                description=(
                    f"You lost the handle on step **{step + 1}** of {len(self.sequence)}.\n"
                    f"The full combo was: {correct_chain}\n\n"
                    f"Lost 💵 **{self.wager:,} CUPBUCKS**."
                ),
                color=0xFF453A
            )
            for child in self.children: child.disabled = True
            await interaction.response.edit_message(embed=embed, view=self)
            return self.stop()

        if len(self.player_input) == len(self.sequence):
            # Full combo hit — pay out
            state = load_state()
            uid = self.user_id
            winnings = self.wager * self.multiplier
            state['rpg'][uid]['cupbucks'] += winnings
            save_state(state)

            embed = discord.Embed(
                title="🔥 HIGHLIGHT REEL!",
                description=(
                    f"**{self.combo_name}** — flawless execution!\n"
                    f"{' → '.join(self.player_input)}\n\n"
                    f"Won 💵 **{winnings:,} CUPBUCKS**!"
                ),
                color=0x32D74B
            )
            for child in self.children: child.disabled = True
            await interaction.response.edit_message(embed=embed, view=self)
            self.stop()
        else:
            # Good so far — update progress bar
            progress = " → ".join(self.player_input) + f" → **({len(self.sequence) - len(self.player_input)} left)**"
            embed = interaction.message.embeds[0]
            embed.description = (
                f"✅ Step {len(self.player_input)}/{len(self.sequence)} correct!\n"
                f"Progress: {progress}\n\n"
                f"Keep going — what's the next move?"
            )
            await interaction.response.edit_message(embed=embed, view=self)

@yard_group.command(name="dribble_drill", description="[Universal] Memorize the dribble combo and execute it perfectly.")
async def dribble_drill(interaction: discord.Interaction, wager: int):
    if wager <= 0: return await interaction.response.send_message("❌ Minimum bet is 1.", ephemeral=True)

    state = load_state()
    uid = str(interaction.user.id)
    state = init_rpg_profile(uid, state)
    rpg = state['rpg'][uid]

    if rpg['cupbucks'] < wager:
        return await interaction.response.send_message("🚫 You're broke.", ephemeral=True)

    rpg['cupbucks'] -= wager
    save_state(state)

    multiplier = 2 if rpg.get('jail_time', 0) > 0 else 1
    loc_text = "⛓️ THE YARD (2x Payout)" if multiplier == 2 else "🌃 THE UNDERGROUND"

    # Difficulty scales with wager — bigger bet = longer combo
    if wager >= 5000:
        seq_len = 6
    elif wager >= 1000:
        seq_len = 5
    else:
        seq_len = 4

    all_emojis = [m[0] for m in DRIBBLE_MOVES]
    sequence = [random.choice(all_emojis) for _ in range(seq_len)]
    combo_name = random.choice(COMBO_NAMES[seq_len])

    # Display the sequence with move names for clarity
    emoji_to_name = {e: l for e, l in DRIBBLE_MOVES}
    named_seq = " → ".join(f"{e} {emoji_to_name[e]}" for e in sequence)

    embed = discord.Embed(
        title=f"🏀 Dribble Drill | {loc_text}",
        description=(
            f"**Combo: {combo_name}** ({seq_len} moves)\n\n"
            f"{named_seq}\n\n"
            f"Memorize it. You have **4 seconds.**"
        ),
        color=0x2b2d31
    )
    embed.set_footer(text=f"Wager: {wager:,} SB | Payout: {wager * multiplier:,} SB if perfect | Difficulty scales with your bet.")

    await interaction.response.send_message(embed=embed)
    msg = await interaction.original_response()
    await asyncio.sleep(4.0)

    # Wipe the sequence from view and show the input buttons
    view = DribbleView(uid, wager, multiplier, sequence, combo_name)
    embed.description = (
        f"**Combo: {combo_name}** — the sequence is gone. Execute from memory.\n\n"
        f"Step **1** of {seq_len}: What's the first move?"
    )
    await msg.edit(embed=embed, view=view)

