@admin_group.command(name="arrest", description="[Admin] Lock a player in the Penitentiary.")
@app_commands.describe(
    pin="Master Admin PIN",
    target="The player going to jail",
    hours="How many hours is their sentence? (Max 96)"
)
async def arrest(interaction: discord.Interaction, pin: str, target: discord.Member, hours: int):
    if not admin_pin_matches(pin, interaction): 
        return await interaction.response.send_message("🚫 **Access Denied.**", ephemeral=True)
        
    state = load_state()
    uid = str(target.id)
    state = init_rpg_profile(uid, state)
    
    # Update the JSON File
    state['rpg'][uid]['jail_time'] = min(hours, 96) 
    state['rpg'][uid]['rep'] = "Fresh Meat" 
    save_state(state)
    
    embed = discord.Embed(title="🚨 BUSTED!", description=f"{target.mention} has been arrested and sent to the QCL Penitentiary for **{hours} hours**.", color=0xFF453A)
    embed.set_footer(text="Their the QCL ID now marks them as an Inmate.")
    
    await interaction.response.send_message(embed=embed)

@admin_group.command(name="release", description="[Admin] Grant a player early parole.")
@app_commands.describe(pin="Master Admin PIN", target="The inmate to release")
async def release(interaction: discord.Interaction, pin: str, target: discord.Member):
    if not admin_pin_matches(pin, interaction): 
        return await interaction.response.send_message("🚫 **Access Denied.**", ephemeral=True)
        
    state = load_state()
    uid = str(target.id)
    state = init_rpg_profile(uid, state)
    
    if state['rpg'][uid]['jail_time'] <= 0:
        return await interaction.response.send_message(f"🤷 {target.display_name} is already a free man.", ephemeral=True)
        
    # Wipe their record clean
    state['rpg'][uid]['jail_time'] = 0 
    state['rpg'][uid]['rep'] = "Walk-On"
    save_state(state)
    
    embed = discord.Embed(title="🕊️ PAROLED!", description=f"{target.mention} has been released from the Penitentiary.", color=0x32D74B)
    await interaction.response.send_message(embed=embed)

