@bot.tree.command(name="checkin", description="Start your day, claim your quests, and build your streak.")
async def checkin(interaction: discord.Interaction):
    state = load_state()
    uid = str(interaction.user.id)
    state = init_rpg_profile(uid, state)
    rpg = state['rpg'][uid]
    
    today_str = datetime.now().strftime("%Y-%m-%d")
    
    # 1. Check if they already checked in today
    if rpg['last_checkin'] == today_str:
        embed = discord.Embed(title="📅 Daily Itinerary", description="You already checked in today! Here are your active quests:", color=0x2b2d31)
        for i, q in enumerate(rpg['quests']):
            status = "✅ Done" if q['completed'] else "⏳ Pending"
            embed.add_field(name=f"Quest {i+1} ({status})", value=f"{q['desc']}\n*Reward: {q['reward']} VC*", inline=False)
        return await interaction.response.send_message(embed=embed)

    # 2. Calculate their Streak
    yesterday_str = (datetime.now() - timedelta(days=1)).strftime("%Y-%m-%d")
    if rpg['last_checkin'] == yesterday_str:
        rpg['streak'] += 1
    else:
        rpg['streak'] = 1 # Reset if they missed a day
        
    rpg['last_checkin'] = today_str
    
   # 3. Generate 3 New Quests from the Vault
    vault = load_quest_vault()
    
    # Failsafe: Make sure there are actually quests in the vault before picking
    social_q = random.choice(vault["social"]) if vault["social"] else {"desc": "Talk in chat.", "reward": 250}
    econ_q = random.choice(vault["econ"]) if vault["econ"] else {"desc": "Spend some VC.", "reward": 500}
    stat_q = random.choice(vault["stat"]) if vault["stat"] else {"desc": "Play your game tonight.", "reward": 1000}

    rpg['quests'] = [
        {"desc": social_q["desc"], "reward": social_q["reward"], "completed": False},
        {"desc": econ_q["desc"], "reward": econ_q["reward"], "completed": False},
        {"desc": stat_q["desc"], "reward": stat_q["reward"], "completed": False}
    ]
    _ci = _rpg_award(state, uid, energy=40, heat=-8, rep=5, reason="Daily check-in")
    _busted = _rpg_jail_risk(state, uid)
    if _busted:
        state['rpg'][uid]['jail_time'] = 24
        state['rpg'][uid]['rep'] = "Busted (Heat Caught Up)"
    save_state(state)
    embed = discord.Embed(title="📅 Daily Check-In", color=0x32D74B,
        description=f"🔥 **{rpg['streak']}-day streak!** Your day resets.")
    embed.add_field(name="Recovery",
        value=f"🔋 Energy → {rpg['energy']}/100  •  🚓 Heat → {rpg['heat']}/100  •  🎖️ +5 Rep ({_ci['title']})",
        inline=False)
    if _busted:
        embed.add_field(name="🚨 BUSTED",
            value="Your heat finally caught up — the law picked you up. **24h jail.** Lay low and let it cool off.",
            inline=False)
    for i, q in enumerate(rpg['quests']):
        embed.add_field(name=f"Quest {i+1}", value=f"{q['desc']}\n*Reward: {q['reward']} VC*", inline=False)
    await interaction.response.send_message(embed=embed)

