@bot.tree.command(name="reroll_quests", description="Pay 100 CUPBUCKS to wipe your slate and get 3 new quests.")
async def reroll_quests(interaction: discord.Interaction):
    state = load_state()
    uid = str(interaction.user.id)
    state = init_rpg_profile(uid, state)
    rpg = state['rpg'][uid]
    
    if rpg['cupbucks'] < 100:
        return await interaction.response.send_message("🚫 **You're short.** It costs 💵 100 CUPBUCKS to bribe the informant for new quests.", ephemeral=True)
        
    if not rpg.get('quests'):
        return await interaction.response.send_message("❌ You haven't checked in today yet.", ephemeral=True)

    # Check if they already finished any today (can't reroll if they already got paid)
    for q in rpg['quests']:
        if q.get('completed'):
            return await interaction.response.send_message("❌ You already completed a quest today. Wait until tomorrow for a fresh slate.", ephemeral=True)

    # Deduct the 100 SB (Black market money is just burned/removed from economy)
    rpg['cupbucks'] -= 100
    
    # Pull 3 fresh quests from the Vault
    vault = load_quest_vault()
    social_q = random.choice(vault["social"]) if vault.get("social") else {"desc": "Talk in chat.", "reward": 250}
    econ_q = random.choice(vault["econ"]) if vault.get("econ") else {"desc": "Spend some VC.", "reward": 500}
    stat_q = random.choice(vault["stat"]) if vault.get("stat") else {"desc": "Play your game tonight.", "reward": 1000}

    rpg['quests'] = [
        {"desc": social_q["desc"], "reward": social_q["reward"], "completed": False},
        {"desc": econ_q["desc"], "reward": econ_q["reward"], "completed": False},
        {"desc": stat_q["desc"], "reward": stat_q["reward"], "completed": False}
    ]
    
    save_state(state)
    
    embed = discord.Embed(title="🎲 Quests Rerolled!", description="You paid 💵 **100 CUPBUCKS**. Here is your new daily itinerary:", color=0x0A84FF)
    for i, q in enumerate(rpg['quests']):
        embed.add_field(name=f"Quest {i+1}", value=f"{q['desc']}\n*Reward: {q['reward']} VC*", inline=False)
        
    await interaction.response.send_message(embed=embed)

@bot.tree.command(name="submit_quest", description="Submit proof for your daily quest.")
@app_commands.describe(
    quest_number="Which quest are you turning in (1, 2, or 3)?",
    proof_text="Explain what you did (e.g., 'Got 8 assists')",
    image="Upload screenshot of box score or chat"
)
async def submit_quest(interaction: discord.Interaction, quest_number: int, proof_text: str, image: discord.Attachment = None):
    state = load_state()
    uid = str(interaction.user.id)
    state = init_rpg_profile(uid, state)
    
    if not state['rpg'][uid]['quests']:
        return await interaction.response.send_message("❌ You haven't checked in today.", ephemeral=True)
        
    idx = quest_number - 1
    if state['rpg'][uid]['quests'][idx]['completed']:
        return await interaction.response.send_message("✅ You already got paid for this one.", ephemeral=True)

    # Package the digital file for the inbox
    ticket = {
        "id": str(uuid.uuid4())[:8],
        "uid": uid,
        "type": "quest",
        "quest_number": quest_number,
        "quest_desc": state['rpg'][uid]['quests'][idx]['desc'],
        "proof_text": proof_text,
        "image_url": image.url if image else None,
        "timestamp": time.time()
    }
    
    # Shove it into the bot's internal inbox
    state.setdefault('admin_inbox', []).append(ticket)
    save_state(state)
    
    await interaction.response.send_message("✅ **Quest securely submitted to the Commissioner's desk.** Wait for grading.", ephemeral=True)

@admin_group.command(name="approve_quest", description="[Admin] Approve a quest and pay the player.")
@app_commands.describe(
    pin="Master Admin PIN",
    target="The player who submitted the quest",
    quest_number="Which quest to approve (1, 2, or 3)"
)
async def approve_quest(interaction: discord.Interaction, pin: str, target: discord.Member, quest_number: int):
    if not admin_pin_matches(pin, interaction): return await interaction.response.send_message("🚫 Access Denied.", ephemeral=True)
    
    state = load_state()
    t_uid = str(target.id)
    state = init_rpg_profile(t_uid, state)
    
    if not state['rpg'][t_uid]['quests']:
        return await interaction.response.send_message("❌ They don't have active quests.", ephemeral=True)
        
    idx = quest_number - 1
    if state['rpg'][t_uid]['quests'][idx]['completed']:
        return await interaction.response.send_message("❌ Already paid out.", ephemeral=True)
        
    # Mark as complete
    state['rpg'][t_uid]['quests'][idx]['completed'] = True
    
    # Calculate payout with their streak multiplier
    base_reward = state['rpg'][t_uid]['quests'][idx]['reward']
    streak_mult = 1.0 + (state['rpg'][t_uid]['streak'] * 0.1)
    final_payout = int(base_reward * streak_mult)
    
    # Pay them from Central Bank
    state['balances'][t_uid] += final_payout
    if 'central_bank' not in state: state['central_bank'] = {"vc_vault": 500000000}
    state['central_bank']['vc_vault'] -= final_payout
    
    save_state(state)
    
    await interaction.response.send_message(f"✅ **Approved!** {target.mention} completed Quest {quest_number}.\nWith their {state['rpg'][t_uid]['streak']}-day streak multiplier, they earned 💰 **{final_payout:,} VC** from the Central Reserve.")

