import uuid

class ExactTargetModal(discord.ui.Modal, title='Enter Exact Target Number'):
    target_num = discord.ui.TextInput(label='Target Number', placeholder='e.g., 25', max_length=3)

    def __init__(self, parent_view):
        super().__init__()
        self.parent_view = parent_view

    async def on_submit(self, interaction: discord.Interaction):
        try:
            target = int(self.target_num.value)
        except ValueError:
            return await interaction.response.send_message("❌ You must enter a valid number.", ephemeral=True)

        if target <= 0: return await interaction.response.send_message("❌ Target must be higher than 0.", ephemeral=True)

        # Calculate Dynamic Multiplier
        stat = self.parent_view.stat_choice
        if stat == "Points": multiplier = max(1.1, target / 10.0)
        elif stat == "Assists": multiplier = max(1.1, target / 4.0)
        elif stat == "Rebounds": multiplier = max(1.1, target / 5.0)
        else: multiplier = max(1.1, target / 2.0) # Defense

        self.parent_view.target_number = target
        self.parent_view.multiplier = round(multiplier, 2)
        
        await interaction.response.edit_message(content=f"🎯 Target set to **{target}+ {stat}** (Payout: {self.parent_view.multiplier}x). Click Lock In when ready!", view=self.parent_view)

class HustleSlipView(discord.ui.View):
    def __init__(self, user_id, wager):
        super().__init__(timeout=120)
        self.user_id = str(user_id)
        self.wager = wager
        self.stat_choice = None
        self.target_number = None
        self.multiplier = 0.0

    @discord.ui.select(
        placeholder="1. Select your Stat...",
        options=[
            discord.SelectOption(label="Points", emoji="🏀"),
            discord.SelectOption(label="Assists", emoji="🤝"),
            discord.SelectOption(label="Rebounds", emoji="🛡️"),
            discord.SelectOption(label="Steals/Blocks", emoji="🧤")
        ],
        custom_id="stat_select"
    )
    async def select_stat(self, interaction: discord.Interaction, select: discord.ui.Select):
        if str(interaction.user.id) != self.user_id: return await interaction.response.send_message("Not your slip.", ephemeral=True)
        self.stat_choice = select.values[0]
        await interaction.response.edit_message(content=f"📊 Stat selected: **{self.stat_choice}**. Now click 'Set Exact Target' below.", view=self)

    @discord.ui.button(label="2. Set Exact Target", style=discord.ButtonStyle.primary, row=2)
    async def set_target(self, interaction: discord.Interaction, button: discord.ui.Button):
        if str(interaction.user.id) != self.user_id: return await interaction.response.send_message("Not your slip.", ephemeral=True)
        if not self.stat_choice: return await interaction.response.send_message("❌ Select a stat from the dropdown first!", ephemeral=True)
        await interaction.response.send_modal(ExactTargetModal(self))

    @discord.ui.button(label="3. LOCK IN SLIP 🔒", style=discord.ButtonStyle.success, row=2)
    async def lock_in(self, interaction: discord.Interaction, button: discord.ui.Button):
        if str(interaction.user.id) != self.user_id: return
        
        if not self.stat_choice or not self.target_number:
            return await interaction.response.send_message("❌ You must select a stat and set a target number first.", ephemeral=True)

        state = load_state()
        uid = self.user_id
        
        if state['rpg'][uid]['cupbucks'] < self.wager:
            return await interaction.response.send_message("🚫 Insufficient CUPBUCKS.", ephemeral=True)

        # Deduct wager and lock slip
        state['rpg'][uid]['cupbucks'] -= self.wager
        potential_payout = int(self.wager * self.multiplier)
        
        state['rpg'][uid]['active_hustle'] = {
            "stat": self.stat_choice,
            "difficulty": f"{self.target_number}+", # We save the exact number here!
            "wager": self.wager,
            "payout": potential_payout
        }
        save_state(state)

        for child in self.children: child.disabled = True
        
        embed = discord.Embed(title="🧾 HUSTLE LOCKED", color=0x32D74B)
        embed.description = f"{interaction.user.mention} just locked in a Custom Hustle!"
        embed.add_field(name="The Bet", value=f"**Stat:** {self.stat_choice}\n**Target:** {self.target_number}+", inline=False)
        embed.add_field(name="The Money", value=f"**Risked:** 💵 {self.wager:,} SB\n**Odds:** {self.multiplier}x\n**To Win:** 💰 {potential_payout:,} VC", inline=False)
        
        await interaction.response.edit_message(content=None, embed=embed, view=self)
        self.stop()

@casino_group.command(name="hustle", description="Bet CUPBUCKS on your own performance to win VC.")
@app_commands.describe(wager="How many CUPBUCKS are you risking?")
async def custom_hustle(interaction: discord.Interaction, wager: int):
    if wager < 50: return await interaction.response.send_message("❌ Minimum bet is 50 CUPBUCKS.", ephemeral=True)
        
    state = load_state()
    uid = str(interaction.user.id)
    state = init_rpg_profile(uid, state)

    if state['rpg'][uid].get('active_hustle'):
        return await interaction.response.send_message("❌ You already have an active hustle.", ephemeral=True)

    if state['rpg'][uid]['cupbucks'] < wager:
        return await interaction.response.send_message(f"🚫 **Insufficient Funds.** You only have 💵 {state['rpg'][uid]['cupbucks']:,} CUPBUCKS.", ephemeral=True)

    view = HustleSlipView(uid, wager)
    embed = discord.Embed(title="📝 Create Custom Hustle", description=f"You are risking 💵 **{wager:,} CUPBUCKS**.\n\nSelect your stat, then enter the exact number you want to hit.", color=0xFFD60A)
    await interaction.response.send_message(embed=embed, view=view)

