class AdminDeskView(discord.ui.View):
    def __init__(self, admin_id):
        super().__init__(timeout=600) # Desk stays open for 10 minutes
        self.admin_id = str(admin_id)

    async def render_next_ticket(self, interaction: discord.Interaction):
        state = load_state()
        inbox = state.get('admin_inbox', [])
        
        if not inbox:
            embed = discord.Embed(title="📭 Desk is Clear", description="There are no pending submissions in the queue.", color=0x2b2d31)
            for child in self.children: child.disabled = True
            return await interaction.response.edit_message(embed=embed, view=self)

        # Grab the oldest ticket in the inbox
        ticket = inbox[0] 
        uid = ticket['uid']
        
        # --- RENDER HUSTLE ---
        if ticket.get('type') == 'hustle':
            hustle = ticket['hustle_data']
            embed = discord.Embed(title="🚨 REVIEW: Custom Hustle", color=0xFFD60A)
            embed.add_field(name="Player UID", value=f"<@{uid}>", inline=True)
            embed.add_field(name="The Bet", value=f"**{hustle['difficulty']} {hustle['stat']}**", inline=True)
            embed.add_field(name="Potential Payout", value=f"💰 {hustle['payout']:,} VC", inline=False)
            embed.add_field(name="Player's Proof", value=ticket['proof_text'], inline=False)
            if ticket.get('image_url'):
                embed.set_image(url=ticket['image_url'])
                
        # --- RENDER QUEST ---
        elif ticket.get('type') == 'quest':
            embed = discord.Embed(title="🚨 REVIEW: Daily Quest", color=0x0A84FF)
            embed.add_field(name="Player UID", value=f"<@{uid}>", inline=True)
            embed.add_field(name="Quest #", value=str(ticket['quest_number']), inline=True)
            embed.add_field(name="Task", value=ticket['quest_desc'], inline=False)
            embed.add_field(name="Player's Proof", value=ticket['proof_text'], inline=False)
            if ticket.get('image_url'):
                embed.set_image(url=ticket['image_url'])
                
        # --- RENDER GAME PROPOSAL ---
        elif ticket.get('type') == 'lockgame':
            embed = discord.Embed(title="🚨 REVIEW: Game Lock Proposal", color=0x0A84FF)
            embed.add_field(name="Proposed By", value=f"<@{uid}>", inline=False)
            embed.add_field(name="Matchup", value=f"**{ticket['team1']} vs {ticket['team2']}**", inline=True)
            embed.add_field(name="Tip-Off", value=ticket['time_est'], inline=True)
            embed.add_field(name="Props Generated", value=f"{len(ticket['bets'])} Sharp Bets", inline=False)

        # --- RENDER ROLE REQUEST (Player <-> Coach) ---
        elif ticket.get('type') == 'role_request':
            to_coach = ticket.get('direction') == 'to_coach'
            embed = discord.Embed(
                title="🔁 REVIEW: Role Change Request",
                color=0x30D158 if to_coach else 0xFF9F0A,
            )
            embed.add_field(name="Member", value=f"<@{uid}>", inline=True)
            embed.add_field(
                name="Requested Change",
                value="🏀 Player → 👔 **Coach**" if to_coach else "👔 Coach → 🏀 **Player**",
                inline=True,
            )
            if ticket.get('team'):
                embed.add_field(name="Team", value=f"🏢 {ticket['team']}", inline=False)
            embed.add_field(
                name="On Approve",
                value=("Grants Coach Desk + all `/coach` commands for this team."
                       if to_coach else "Steps them down to a regular player and releases their team claim."),
                inline=False,
            )

        # --- NEW SAFETY FALLBACK ---
        else:
            embed = discord.Embed(title="⚠️ Wrong Desk", description=f"This is a `{ticket.get('type')}` ticket. It belongs to another desk (like the Payroll Desk). Click **Skip for Now** to push it to the back of the line.", color=0xFF9F0A)
            
        embed.set_footer(text=f"Ticket ID: {ticket['id']} | Tickets Remaining: {len(inbox)}")
        try:
            await interaction.response.edit_message(embed=embed, view=self)
        except Exception:
            # If we deferred the button to buy time, we edit the message this way
            await interaction.message.edit(embed=embed, view=self)

    @discord.ui.button(label="✅ APPROVE", style=discord.ButtonStyle.success)
    async def btn_approve(self, interaction: discord.Interaction, button: discord.ui.Button):
        if str(interaction.user.id) != self.admin_id: return
        
        # ADD THIS LINE RIGHT HERE:
        await interaction.response.defer()
        
        state = load_state()

        if not state.get('admin_inbox'): return
        ticket = state['admin_inbox'].pop(0) # Remove from inbox
        uid = ticket['uid']
        
        # -- APPROVE HUSTLE --
        if ticket.get('type') == 'hustle':
            payout = ticket['hustle_data']['payout']
            state = init_rpg_profile(uid, state)
            state['balances'][uid] = state['balances'].get(uid, 0) + payout
            if 'central_bank' not in state: state['central_bank'] = {"vc_vault": 500000000}
            state['central_bank']['vc_vault'] -= payout
            state['rpg'][uid]['active_hustle'] = None
            save_state(state)
            await interaction.channel.send(f"🤑 **HUSTLE CASHED!** <@{uid}> hit their target and the Commissioner wired them **{payout:,} VC**!")
            
        # -- APPROVE QUEST --
        elif ticket.get('type') == 'quest':
            q_idx = ticket['quest_number'] - 1
            state = init_rpg_profile(uid, state)
            
            if not state['rpg'][uid]['quests'][q_idx]['completed']:
                state['rpg'][uid]['quests'][q_idx]['completed'] = True
                
                # Apply streak multiplier automatically
                base_reward = state['rpg'][uid]['quests'][q_idx]['reward']
                streak_mult = 1.0 + (state['rpg'][uid].get('streak', 0) * 0.1)
                final_payout = int(base_reward * streak_mult)
                
                state['balances'][uid] = state['balances'].get(uid, 0) + final_payout
                if 'central_bank' not in state: state['central_bank'] = {"vc_vault": 500000000}
                state['central_bank']['vc_vault'] -= final_payout
                
                save_state(state)
                await interaction.channel.send(f"✅ **QUEST APPROVED!** <@{uid}> completed Quest {ticket['quest_number']}.\nWith their {state['rpg'][uid].get('streak', 0)}-day streak multiplier, they earned 💰 **{final_payout:,} VC**!")
            else:
                save_state(state)
                await interaction.channel.send(f"⚠️ <@{uid}>'s Quest {ticket['quest_number']} was already paid out previously.")
            
        # -- APPROVE GAME PROPOSAL --
        elif ticket.get('type') == 'lockgame':
            t1, t2 = ticket['team1'], ticket['team2']
            game_key = f"{t1} vs {t2}"
            
            df = _cached_df
            is_playoffs = "Playoffs" in ticket.get('game_type', '')
            is_tourney = "Event" in ticket.get('game_type', '')
            
            sim_data = simulate_granular_matchup(t1, t2, df, is_playoffs=is_playoffs, is_tournament=is_tourney)
            
            prompt = f"""
            You are the lead QSPN analyst. The Commissioner just approved the betting slate for {t1} vs {t2}.
            Here is the 2,500 iteration Monte Carlo simulation data (Neutral Court 2K Matchmaking):
            {json.dumps(sim_data, default=str)}
            
            INSTRUCTIONS:
            1. HYPE THE MATCHUP: Read the "Matchup_Context". If it is a Blood Feud or Playoffs, amplify the pressure in your commentary.
            2. Break down the clash of Defensive Schemes and identify which Archetypes will thrive or choke.
            3. Give your official Oracle prediction based on the simulation numbers.
            4. End the broadcast by screaming that FLASH BETTING is open for the next 2 minutes. Keep it under 1500 characters.
            """
            
            def _fetch_preview():
                return ai_client.models.generate_content(model='gemini-3.6-flash', contents=prompt)
            
            try:
                ai_response = await asyncio.to_thread(_fetch_preview)
                preview_text = ai_response.text
                embed = discord.Embed(title=f"🚨 OFFICIAL SLATE LOCKED: {t1} vs {t2}", description=preview_text, color=0xFF453A)
                embed.set_footer(text="Flash Betting Window: 2 Minutes | 50% Off VC Wager")
                
                await interaction.channel.send(content=f"📢 <@{uid}>'s slate is live! @everyone", embed=embed, view=FlashBetView(ticket['bets'], time.time()))
            except Exception as e:
                preview_text = f"**Tip-off:** {ticket['time_est']}\n*50 Sharp Props generated and posted to the Shack.*"
                embed = discord.Embed(title=f"🔒 GAME LOCKED: {t1} vs {t2} 🔒", description=preview_text, color=0xFF453A)
                await interaction.channel.send(content=f"📢 <@{uid}>'s game proposal was approved!\n\n" + ticket['readout'], embed=embed, view=FlashBetView(ticket['bets'], time.time()))

            # Save the locked game and the preview text to the state
            state.setdefault('locked_games', {})[game_key] = {
                "bets": ticket['bets'], 
                "timestamp": time.time(),
                "preview": preview_text  
            }
            save_state(state)

        # -- APPROVE ROLE CHANGE (Player <-> Coach) --
        elif ticket.get('type') == 'role_request':
            r_uid = str(uid)
            user_rec = state.setdefault('users', {}).setdefault(r_uid, {})
            if ticket.get('direction') == 'to_coach':
                team = ticket.get('team') or user_rec.get('team') or 'Unassigned'
                user_rec['role'] = 'coach'
                # Coach Desk reads team_claims[uid] = {'team', 'pin'}; reuse their personal PIN.
                desk_pin = user_rec.get('pin', '0000')
                state.setdefault('team_claims', {})[r_uid] = {'team': team, 'pin': desk_pin}
                save_state(state)
                await interaction.channel.send(
                    f"👔 **COACH APPROVED!** <@{r_uid}> is now the Coach of **{team}**.\n"
                    f"Coach Desk + all `/coach` commands are unlocked. Open your hub with `/office coach_desk` "
                    f"(your PIN), and run `/coach help` for the full playbook."
                )
            else:  # to_player
                user_rec['role'] = 'player'
                state.setdefault('team_claims', {}).pop(r_uid, None)
                save_state(state)
                await interaction.channel.send(
                    f"🔄 **STEP-DOWN APPROVED.** <@{r_uid}> is back to a regular Player. "
                    f"Coach access has been released."
                )

        # Load the next file
        await self.render_next_ticket(interaction)

    @discord.ui.button(label="❌ DENY / FAIL", style=discord.ButtonStyle.danger)
    async def btn_deny(self, interaction: discord.Interaction, button: discord.ui.Button):
        if str(interaction.user.id) != self.admin_id: return
        
        state = load_state()
        if not state.get('admin_inbox'): return
        ticket = state['admin_inbox'].pop(0)
        uid = ticket['uid']
        
        # -- FAIL HUSTLE --
        if ticket.get('type') == 'hustle':
            state = init_rpg_profile(uid, state)
            state['rpg'][uid]['active_hustle'] = None
            save_state(state)
            await interaction.channel.send(f"🥶 **HUSTLE FAILED.** The Commissioner reviewed the tape. <@{uid}> choked.")
            
        # -- DENY QUEST --
        elif ticket.get('type') == 'quest':
            save_state(state)
            await interaction.channel.send(f"❌ <@{uid}>'s Quest {ticket['quest_number']} submission was **DENIED**.")
            
        # -- DENY GAME PROPOSAL --
        elif ticket.get('type') == 'lockgame':
            save_state(state) 
            await interaction.channel.send(f"❌ <@{uid}>'s game proposal for **{ticket['team1']} vs {ticket['team2']}** was denied.")

        # -- DENY ROLE CHANGE --
        elif ticket.get('type') == 'role_request':
            save_state(state)
            want = "Coach" if ticket.get('direction') == 'to_coach' else "Player"
            await interaction.channel.send(
                f"❌ <@{uid}>'s request to switch to **{want}** was declined by an admin."
            )

        await self.render_next_ticket(interaction)

    @discord.ui.button(label="⏭️ Skip for Now", style=discord.ButtonStyle.secondary)
    async def btn_skip(self, interaction: discord.Interaction, button: discord.ui.Button):
        if str(interaction.user.id) != self.admin_id: return
        
        state = load_state()
        if not state.get('admin_inbox'): return
        ticket = state['admin_inbox'].pop(0)
        state['admin_inbox'].append(ticket)
        save_state(state)
        
        await self.render_next_ticket(interaction)

