@admin_group.command(name="roster", description="[Admin] View all the QCL RPG profiles at once.")
@app_commands.describe(pin="Master Admin PIN")
async def admin_roster(interaction: discord.Interaction, pin: str):
    if not admin_pin_matches(pin, interaction):
        return await interaction.response.send_message("🚫 **Access Denied.**", ephemeral=True)

    state = load_state()
    
    if 'rpg' not in state or not state['rpg']:
        return await interaction.response.send_message("📂 The city is empty. No RPG profiles exist yet.", ephemeral=True)

    embed = discord.Embed(title="🏙️ the QCL: Master RPG Roster", color=0x2b2d31)
    
    roster_count = 0
    desc = ""
    
    # Loop through everyone's profile
    for uid, rpg in state['rpg'].items():
        vc_bal = state['balances'].get(uid, 0)
        sb_bal = rpg.get('cupbucks', 0)
        heat = rpg.get('heat', 0)
        jail = rpg.get('jail_time', 0)
        
        # Format the status
        status = "🟢 Healthy"
        if jail > 0: status = f"⛓️ In Jail ({jail}h)"
        elif heat > 50: status = "🔥 Wanted"
        
        # Build the dossier line
        # Mentions <@uid> so you know exactly who it is
        desc += f"👤 <@{uid}>\n"
        desc += f"┣ 💰 **Bank:** {vc_bal:,} VC | 💵 **Market:** {sb_bal:,} SB\n"
        desc += f"┗ 🏷️ **Rep:** {rpg.get('rep', 'Walk-On')} | 📊 **Status:** {status}\n\n"
        
        roster_count += 1
        
        # Discord embeds cap at 4096 characters in the description. 
        # If you have a massive league, this stops it from crashing.
        if len(desc) > 3800:
            desc += "*...list truncated due to size limits. Use /admin_edit to view specific users.*"
            break

    embed.description = desc
    embed.set_footer(text=f"Total Registered Citizens: {roster_count}")
    
    await interaction.response.send_message(embed=embed, ephemeral=True)

