@admin_group.command(name="move", description="[Admin] Move a player to a new team. Updates roles and bot brain instantly.")
@app_commands.autocomplete(new_team=team_autocomplete)
@app_commands.describe(
    pin="Master Admin PIN",
    target="The Discord member being moved",
    new_team="The exact name of the team they are joining",
    gamertag="Their official Gamertag (for the stats engine)"
)
async def admin_move(interaction: discord.Interaction, pin: str, target: discord.Member, new_team: str, gamertag: str):
    if not admin_pin_matches(pin, interaction):
        return await interaction.response.send_message("🚫 **Access Denied.**", ephemeral=True)
        
    await interaction.response.defer(ephemeral=True)
    
    state = load_state()
    uid = str(target.id)
    state = init_rpg_profile(uid, state)
    
    # 1. Update the User's Personal File
    old_team = state.setdefault('users', {}).setdefault(uid, {}).get('team', 'Free Agent')
    state['users'][uid]['team'] = new_team
    state['users'][uid]['gamertag'] = gamertag
    
    # 2. Update the Team Rosters in the JSON Brain
    # Remove from old team if they had one
    if old_team != 'Free Agent' and old_team in state.get('rosters', {}):
        if gamertag in state['rosters'][old_team]['active']:
            state['rosters'][old_team]['active'].remove(gamertag)
            
    # Add to new team
    roster_data = state.setdefault('rosters', {}).setdefault(new_team, {'active': [], 'inactive': []})
    if gamertag not in roster_data['active']:
        roster_data['active'].append(gamertag)
        
    save_state(state)
    
    # 3. Physically swap the Discord Roles
    # (Assuming your team roles are named exactly like the team names in the database)
    roles_removed = []
    role_added = False
    
    try:
        # Strip old team roles (we assume any role that matches a team in your cached list is a team role)
        global _cached_teams
        team_names_lower = [t.lower() for t in _cached_teams] if _cached_teams else []
        
        for role in target.roles:
            if role.name.lower() in team_names_lower and role.name.lower() != new_team.lower():
                await target.remove_roles(role)
                roles_removed.append(role.name)
                
        # Find the new team role in the server and add it
        new_role = discord.utils.get(interaction.guild.roles, name=new_team)
        if new_role:
            await target.add_roles(new_role)
            role_added = True
    except discord.Forbidden:
        return await interaction.followup.send("⚠️ **Role Error:** The bot brain updated perfectly, but I don't have Discord permissions to change their roles. Move my bot role higher in the server settings!")

    # 4. Report Success
    embed = discord.Embed(title="🔄 BLOCKBUSTER MOVE", color=0x32D74B)
    embed.description = f"**{target.mention}** (`{gamertag}`) has been officially moved to the **{new_team}**."
    if roles_removed:
        embed.add_field(name="Stripped Jerseys", value=", ".join(roles_removed), inline=False)
    if role_added:
        embed.add_field(name="New Jersey Assigned", value=f"Assigned Discord Role: @{new_team}", inline=False)
        
    await interaction.followup.send(embed=embed)

