import io

class MayorEconomyModal(discord.ui.Modal):
    action = discord.ui.TextInput(label='Action (Type MINT or SEIZE)', placeholder='MINT', required=True)
    amount = discord.ui.TextInput(label='Amount', placeholder='e.g. 5000', required=True)
    currency = discord.ui.TextInput(label='Currency (Type VC or SB)', placeholder='VC', required=True)

    def __init__(self, uid, gt):
        super().__init__(title=f"Funds: {gt[:15]}")
        self.uid = uid
        self.gt = gt

    async def on_submit(self, interaction: discord.Interaction):
        state = load_state()
        try: amt = int(self.amount.value)
        except ValueError: return await interaction.response.send_message("❌ Amount must be a number.", ephemeral=True)

        state = init_rpg_profile(self.uid, state)
        act = self.action.value.strip().upper()
        curr = self.currency.value.strip().upper()
        
        if curr == "VC":
            if act == "MINT": state['balances'][self.uid] = state['balances'].get(self.uid, 0) + amt
            elif act == "SEIZE": state['balances'][self.uid] = max(0, state['balances'].get(self.uid, 0) - amt)
        else:
            if act == "MINT": state['rpg'][self.uid]['cupbucks'] += amt
            elif act == "SEIZE": state['rpg'][self.uid]['cupbucks'] = max(0, state['rpg'][self.uid]['cupbucks'] - amt)
            
        save_state(state)
        log_admin_action(interaction.user.display_name, "Economy", f"{act} {amt} {curr} for {self.gt}")
        await interaction.response.send_message(f"✅ **Economy Updated:** {act}ED **{amt:,} {curr}** for <@{self.uid}>.", ephemeral=True)

class MayorAwardsModal(discord.ui.Modal):
    action = discord.ui.TextInput(label='Action (Type GIVE or REMOVE)', placeholder='GIVE', required=True)
    award_name = discord.ui.TextInput(label='Award Name', placeholder='e.g. Season 5 MVP', required=True)

    def __init__(self, uid, gt):
        super().__init__(title=f"Awards: {gt[:15]}")
        self.uid = uid
        self.gt = gt

    async def on_submit(self, interaction: discord.Interaction):
        state = load_state()
        act = self.action.value.strip().upper()
        award = self.award_name.value.strip()
        
        if act == "GIVE":
            state.setdefault('awards', {}).setdefault(self.uid, []).append(f"🏅 {award}")
        elif act == "REMOVE":
            if self.uid in state.get('awards', {}):
                state['awards'][self.uid] = [a for a in state['awards'][self.uid] if award.lower() not in a.lower()]
                
        save_state(state)
        log_admin_action(interaction.user.display_name, "Awards", f"{act} '{award}' to {self.gt}")
        await interaction.response.send_message(f"✅ **Trophy Cabinet Updated:** {act} '{award}' for <@{self.uid}>.", ephemeral=True)

class MayorJusticeModal(discord.ui.Modal):
    action = discord.ui.TextInput(label='Action (Type ARREST or PAROLE)', placeholder='ARREST', required=True)
    hours = discord.ui.TextInput(label='Jail Hours (If Arresting)', placeholder='e.g. 24', required=False)

    def __init__(self, uid, gt):
        super().__init__(title=f"Justice: {gt[:15]}")
        self.uid = uid
        self.gt = gt

    async def on_submit(self, interaction: discord.Interaction):
        state = load_state()
        state = init_rpg_profile(self.uid, state)
        act = self.action.value.strip().upper()
        
        if act == "ARREST":
            try: h = min(int(self.hours.value), 96)
            except: h = 24
            state['rpg'][self.uid]['jail_time'] = h
            state['rpg'][self.uid]['rep'] = "Fresh Meat"
            msg = f"🚨 **Busted:** <@{self.uid}> sent to Penitentiary for {h} hours."
        else:
            state['rpg'][self.uid]['jail_time'] = 0
            state['rpg'][self.uid]['rep'] = "Walk-On"
            msg = f"🕊️ **Paroled:** <@{self.uid}> released from jail."
            
        save_state(state)
        await interaction.response.send_message(msg, ephemeral=True)

