# --- THE 2-STEP TARGETING MENU ---
# ==========================================

class MayorUserSelect(discord.ui.UserSelect):
    def __init__(self, action):
        super().__init__(placeholder="Select a Citizen from the server...")
        self.action = action

    async def callback(self, interaction: discord.Interaction):
        uid = str(self.values[0].id)
        state = load_state()
        gt = state.get('users', {}).get(uid, {}).get('gamertag', 'Unknown Citizen')

        # Pop the specific modal now that we know exactly who we are targeting
        if self.action == "mint_vc": await interaction.response.send_modal(MayorEconomyModal(uid, gt))
        elif self.action == "give_award": await interaction.response.send_modal(MayorAwardsModal(uid, gt))
        elif self.action == "arrest": await interaction.response.send_modal(MayorJusticeModal(uid, gt))
        elif self.action == "force_move": await interaction.response.send_modal(MayorForceMoveModal(uid, gt))
        elif self.action == "edit_profile": await interaction.response.send_modal(MayorEditPlayerModal(uid, gt))
        elif self.action == "override_record": await interaction.response.send_modal(MayorRecordModal(uid, gt))
