# ==========================================
# --- MAYOR'S ROLE COMMAND CENTER ---
# Strip any/all roles from players or coaches (including self):
# internal QCL coach status + team claim, AND Discord server roles.
# ==========================================
async def _purge_discord_roles(member, role_ids=None):
    """Remove Discord roles from a member. If role_ids is None, remove ALL removable
    roles. Skips @everyone, managed/integration roles, and roles at/above the bot's
    top role (Discord won't let the bot touch those). Returns (removed, skipped)."""
    guild = member.guild
    me = guild.me
    removed, skipped = [], []
    if role_ids is None:
        targets = [r for r in member.roles if not r.is_default() and not r.managed]
    else:
        targets = []
        for rid in role_ids:
            r = guild.get_role(int(rid))
            if r and r in member.roles and not r.is_default() and not r.managed:
                targets.append(r)
    for r in targets:
        if r >= me.top_role:
            skipped.append(f"{r.name} (above bot)")
            continue
        try:
            await member.remove_roles(r, reason="Mayor's Hub: role purge")
            removed.append(r.name)
        except Exception:
            skipped.append(f"{r.name} (failed)")
    return removed, skipped


def _clear_internal_coach(state, uid):
    """Demote a user to player in QCL state: role=player, release team claim."""
    uid = str(uid)
    changed = False
    u = state.get('users', {}).get(uid)
    if u is not None and u.get('role') == 'coach':
        u['role'] = 'player'; changed = True
    if uid in state.get('team_claims', {}):
        state['team_claims'].pop(uid, None); changed = True
    return changed


class RoleTargetUserSelect(discord.ui.UserSelect):
    def __init__(self):
        super().__init__(placeholder="① Select a member (you can pick yourself)...",
                         min_values=1, max_values=1)

