class RoleManagerView(discord.ui.View):
    def __init__(self, admin_id):
        super().__init__(timeout=600)
        self.admin_id = str(admin_id)
        self.target_id = None
        self.selected_role_ids = []
        self.add_item(RoleTargetUserSelect())
        self.add_item(DiscordRoleRemoveSelect())

    def _target_member(self, interaction):
        if not self.target_id or not interaction.guild:
            return None
        return interaction.guild.get_member(int(self.target_id))

    async def render(self, interaction: discord.Interaction):
        member = self._target_member(interaction)
        if member is None:
            embed = discord.Embed(title="🧹 Role Command Center",
                                  description="① Select a member below to load their roles.",
                                  color=0x2b2d31)
            return await interaction.response.edit_message(embed=embed, view=self)

        state = load_state()
        uid = str(member.id)
        qcl_role = get_user_role(uid, state)
        claim = state.get('team_claims', {}).get(uid, {})
        d_roles = [r for r in member.roles if not r.is_default() and not r.managed]

        embed = discord.Embed(
            title=f"🧹 Role Command Center — {member.display_name}",
            description="Choose roles in the second dropdown then **Remove Selected**, or use **Strip ALL** to nuke everything. Works on yourself too.",
            color=0x2b2d31,
        )
        embed.add_field(name="QCL Role", value=("👔 Coach" if qcl_role == 'coach' else "🏀 Player"), inline=True)
        embed.add_field(name="Team Claim", value=(f"🏢 {claim.get('team')}" if claim else "—"), inline=True)
        if member.id == member.guild.owner_id:
            embed.add_field(name="⚠️ Server Owner",
                            value="Discord blocks bots from removing the owner's Discord roles. Internal coach/claim removal still works.",
                            inline=False)
        role_list = ", ".join(r.name for r in d_roles[:30]) if d_roles else "*(none)*"
        embed.add_field(name=f"Discord Roles ({len(d_roles)})", value=role_list[:1024], inline=False)
        embed.set_footer(text="The bot can only remove roles below its own highest role.")
        await interaction.response.edit_message(embed=embed, view=self)

    async def _guard(self, interaction):
        if str(interaction.user.id) != self.admin_id:
            await interaction.response.send_message("🚫 Not your panel.", ephemeral=True)
            return None
        member = self._target_member(interaction)
        if member is None:
            await interaction.response.send_message("⚠️ Select a member first (dropdown ①).", ephemeral=True)
            return None
        if not interaction.guild.me.guild_permissions.manage_roles:
            await interaction.response.send_message("🚫 I need the **Manage Roles** permission to do that.", ephemeral=True)
            return None
        return member

    @discord.ui.button(label="🗑️ Remove Selected Roles", style=discord.ButtonStyle.danger, row=2)
    async def remove_selected(self, interaction: discord.Interaction, button: discord.ui.Button):
        member = await self._guard(interaction)
        if member is None:
            return
        if not self.selected_role_ids:
            return await interaction.response.send_message("⚠️ Pick at least one role in dropdown ②, or use **Strip ALL**.", ephemeral=True)
        await interaction.response.defer(ephemeral=True)
        removed, skipped = await _purge_discord_roles(member, self.selected_role_ids)
        log_admin_action(interaction.user.display_name, "Roles", f"Removed {len(removed)} role(s) from {member.display_name}")
        msg = f"✅ Removed from **{member.display_name}**: {', '.join(removed) if removed else 'nothing'}"
        if skipped:
            msg += f"\n⏭️ Skipped: {', '.join(skipped)}"
        await interaction.followup.send(msg, ephemeral=True)

    @discord.ui.button(label="👔→🏀 Demote to Player", style=discord.ButtonStyle.secondary, row=2)
    async def demote(self, interaction: discord.Interaction, button: discord.ui.Button):
        if str(interaction.user.id) != self.admin_id:
            return await interaction.response.send_message("🚫 Not your panel.", ephemeral=True)
        member = self._target_member(interaction)
        if member is None:
            return await interaction.response.send_message("⚠️ Select a member first (dropdown ①).", ephemeral=True)
        state = load_state()
        changed = _clear_internal_coach(state, member.id)
        save_state(state)
        log_admin_action(interaction.user.display_name, "Roles", f"Demoted {member.display_name} to Player")
        note = "released coach status + team claim" if changed else "was already a player"
        await interaction.response.send_message(f"🏀 **{member.display_name}** {note}.", ephemeral=True)

    @discord.ui.button(label="💥 Strip ALL Roles", style=discord.ButtonStyle.danger, row=3)
    async def strip_all(self, interaction: discord.Interaction, button: discord.ui.Button):
        member = await self._guard(interaction)
        if member is None:
            return
        await interaction.response.defer(ephemeral=True)
        removed, skipped = await _purge_discord_roles(member, None)  # all removable
        state = load_state()
        _clear_internal_coach(state, member.id)
        save_state(state)
        log_admin_action(interaction.user.display_name, "Roles", f"STRIPPED ALL roles from {member.display_name}")
        msg = (f"💥 **{member.display_name}** stripped.\n"
               f"Discord roles removed ({len(removed)}): {', '.join(removed) if removed else 'none'}\n"
               f"QCL: demoted to Player, team claim released.")
        if skipped:
            msg += f"\n⏭️ Could not remove: {', '.join(skipped)}"
        await interaction.followup.send(msg, ephemeral=True)


