                csv += f"{uid},{u.get('gamertag','Unknown')},{u.get('team','Free Agent')},{u.get('quote','None').replace(',','')},{state.get('balances',{}).get(uid,0)},{state.get('rpg',{}).get(uid,{}).get('cupbucks',0)}\n"
