# --- 📸 RETROACTIVE SCRAPER COMMAND ---
@brain_group.command(name="scrape_photos", description="[Admin] Look back through the 4 target channels and download old photos.")
@app_commands.describe(
    pin="Master Admin PIN", 
    limit="How many past messages to check per channel (e.g. 100)"
)
async def scrape_old_photos(interaction: discord.Interaction, pin: str, limit: int = 100):
    if not admin_pin_matches(pin, interaction): 
        return await interaction.response.send_message("🚫 **Access Denied.**", ephemeral=True)
        
    # We must "defer" the response because downloading old files takes time, 
    # and Discord will crash the command if it takes longer than 3 seconds to reply.
    await interaction.response.defer(ephemeral=True)
    
    save_folder = r"E:\AI Helper\New folder\Downloaded_Photos"
    if not os.path.exists(save_folder):
        os.makedirs(save_folder)

    downloaded_count = 0
    
    # Loop through the 4 channels you saved in the bot's brain
    for channel_id in bot.target_channels:
        channel = bot.get_channel(channel_id)
        if not channel:
            continue # Skip if the bot somehow can't see the channel
            
        try:
            # Scroll up through the history
            async for message in channel.history(limit=limit):
                if message.attachments:
                    for attachment in message.attachments:
                        valid_extensions = ('.png', '.jpg', '.jpeg', '.gif', '.webp')
                        if attachment.filename.lower().endswith(valid_extensions):
                            
                            save_path = os.path.join(save_folder, attachment.filename)
                            
                            # Check if we already downloaded this exact file so we don't duplicate
                            if not os.path.exists(save_path):
                                try:
                                    await attachment.save(save_path)
                                    downloaded_count += 1
                                except Exception as e:
                                    print(f"Failed to download old image {attachment.filename}: {e}")
        except discord.Forbidden:
            print(f"Bot lacks 'Read Message History' permission for channel {channel_id}")

    await interaction.followup.send(f"✅ **Time Travel Complete!**\nScanned the last {limit} messages in your target channels and found **{downloaded_count}** old images.")

@brain_group.command(name="reboot", description="[Admin] Restart the bot instantly to apply code changes.")
async def reboot(interaction: discord.Interaction, pin: str):
    if not admin_pin_matches(pin, interaction): 
        return await interaction.response.send_message("🚫 **Access Denied.**", ephemeral=True)
        
    await interaction.response.send_message("🔄 **Rebooting system... I'll be back in a few seconds.**", ephemeral=True)
    
    import sys
    import os
    import asyncio
    
    # Leave the sticky note so it knows where to announce it's back
    state = load_state()
    state['pending_reboot_channel'] = interaction.channel_id
    save_state(state)
    
    # Give Discord exactly 1 second to finish sending the message above
    await asyncio.sleep(1)
    
    # --- THE WINDOWS SPACE FIX ---
    # We loop through the system arguments and wrap any paths with spaces in quotation marks
    safe_args = [f'"{arg}"' if ' ' in arg else arg for arg in sys.argv]
    
    # Instantly replace the current process with a fresh one
    os.execv(sys.executable, [sys.executable] + safe_args)

@brain_group.command(name="feed", description="[Admin] Upload a file from your phone/Discord straight into CupMuse's brain.")
@app_commands.describe(pin="Master Admin PIN", file="Attach a Document, Image, Audio, or Video file")
async def feed_brain(interaction: discord.Interaction, pin: str, file: discord.Attachment):
    if not admin_pin_matches(pin, interaction): 
        return await interaction.response.send_message("🚫 **Access Denied.**", ephemeral=True)
        
    # Defer because downloading from Discord and uploading to Gemini takes a few seconds
    await interaction.response.defer(ephemeral=True)
    
    # Check if the file type is something CupMuse can actually read
    valid_extensions = (
        '.pdf', '.txt', '.csv', '.md', '.json', '.docx', '.rtf',
        '.png', '.jpg', '.jpeg', '.webp',
        '.mp3', '.wav', '.mp4', '.mov'
    )
    
    if not file.filename.lower().endswith(valid_extensions):
        return await interaction.followup.send(f"❌ **Invalid file type.** CupMuse can only eat these formats:\n`{', '.join(valid_extensions)}`")

    # Make sure the folder exists on your PC
    if not os.path.exists(KNOWLEDGE_VAULT_PATH):
        os.makedirs(KNOWLEDGE_VAULT_PATH)

    file_path = os.path.join(KNOWLEDGE_VAULT_PATH, file.filename)

    try:
        # 1. Download the file from Discord directly to your E: Drive
        await file.save(file_path)
        
        # 2. Upload it straight into Gemini's memory
        def _upload():
            return ai_client.files.upload(file=file_path)
        
        uploaded_file = await asyncio.to_thread(_upload)
        uploaded_gemini_files[file.filename] = uploaded_file
        
        await interaction.followup.send(f"🧠 **Yum!** Successfully downloaded `{file.filename}` to the Knowledge Vault and injected it directly into CupMuse's brain.")
        
    except Exception as e:
        await interaction.followup.send(f"❌ **Error feeding the brain:** `{str(e)[:900]}`")

@award_group.command(name="give_team", description="[ADMIN ONLY] Give a championship ring to an entire active roster at once.")
@app_commands.checks.has_permissions(administrator=True)
@app_commands.autocomplete(team=team_autocomplete)
async def give_team_award(interaction: discord.Interaction, team: str, award: str):
    state = load_state()
    
    # 1. Hang the banner for the Franchise itself (shows in /teamreport)
    team_key = team.lower()
    if team_key not in state.setdefault('awards', {}): 
        state['awards'][team_key] = []
    state['awards'][team_key].append(f"🏆 {award}")
    
    # 2. Distribute rings to every player on the active roster
    roster = state.get('rosters', {}).get(team, {}).get('active', [])
    awarded_players = []
    
    for gamertag in roster:
        # Find the player's Discord ID in your JSON registry
        uid = next((k for k, v in state.get('users', {}).items() if v.get('gamertag', '').lower() == gamertag.lower()), None)
        
        # If we have their ID, use it. Otherwise, fallback to their Gamertag
        target_key = uid if uid else gamertag.lower()
        
        if target_key not in state['awards']: 
            state['awards'][target_key] = []
        state['awards'][target_key].append(f"💍 {award}")
        awarded_players.append(gamertag)
        
    save_state(state)
    
    log_admin_action(interaction.user.display_name, "Awards", f"Gave team award '{award}' to {team}")
    
    # Print the receipt
    embed = discord.Embed(title="🏆 CHAMPIONSHIP HARDWARE DELIVERED", color=0xFFD60A)
    embed.description = f"The **{award}** banner has been hung in the rafters for the **{team}**!\n\n**Rings were distributed to:**\n" 
    
    if awarded_players:
        embed.description += "\n".join([f"↳ {p}" for p in awarded_players])
    else:
        embed.description += "*No active players found on this roster.*"
        
    await interaction.response.send_message(embed=embed)

@brain_group.command(name="sync", description="[Admin] Scan the Knowledge Vault for new files and inject them into CupMuse.")
@app_commands.describe(pin="Master Admin PIN")
async def sync_brain(interaction: discord.Interaction, pin: str):
    if not admin_pin_matches(pin, interaction): 
        return await interaction.response.send_message("🚫 **Access Denied.**", ephemeral=True)
        
    # Defer because uploading large files (like videos or PDFs) might take a few seconds
    await interaction.response.defer(ephemeral=True)
    
    if not os.path.exists(KNOWLEDGE_VAULT_PATH):
        os.makedirs(KNOWLEDGE_VAULT_PATH)
        return await interaction.followup.send("⚠️ The Knowledge Vault folder didn't exist, so I created it. Drop some files in there first!")
        
    valid_extensions = (
        '.pdf', '.txt', '.csv', '.md', '.json', '.docx', '.rtf',
        '.png', '.jpg', '.jpeg', '.webp',
        '.mp3', '.wav', '.mp4', '.mov'
    )
        
    vault_files = [f for f in os.listdir(KNOWLEDGE_VAULT_PATH) if f.lower().endswith(valid_extensions)]
    
    new_files_count = 0
    error_count = 0
    
    for file_name in vault_files:
        # The Smart Check: Only upload if it's not already in the bot's memory dict
        if file_name not in uploaded_gemini_files:
            full_path = os.path.join(KNOWLEDGE_VAULT_PATH, file_name)
            def _upload():
                return ai_client.files.upload(file=full_path)
            try:
                uploaded_file = await asyncio.to_thread(_upload)
                uploaded_gemini_files[file_name] = uploaded_file
                new_files_count += 1
                print(f"✅ Live Sync: Uploaded {file_name}")
            except Exception as e:
                print(f"❌ Live Sync Error for {file_name}: {e}")
                error_count += 1
                
    if new_files_count > 0:
        await interaction.followup.send(f"🧠 **Brain Synced!** Successfully injected `{new_files_count}` new file(s) into CupMuse's memory. *(Errors: {error_count})*")
    else:
        await interaction.followup.send("🤷 **No new files found.** Everything in the folder is already in my brain!")

@office_group.command(name="previews_alt", description="[Public] Read the QSPN Analyst Previews for all upcoming locked games.")
async def game_previews(interaction: discord.Interaction):
    state = load_state()
    games = state.get('locked_games', {})
    
    if not games: 
        return await interaction.response.send_message("No locked games are currently on the board.", ephemeral=True)
    
    # Create dropdown options for all active games
    options = [discord.SelectOption(label=g) for g in list(games.keys())[:25]]
    select = discord.ui.Select(placeholder="Select a Matchup to read the Preview...", options=options)
    
    async def select_callback(i: discord.Interaction):
        game_key = select.values[0]
        game_data = state['locked_games'][game_key]
        
        preview_text = game_data.get('preview', "No preview article was saved for this matchup.")
        
        embed = discord.Embed(title=f"📰 QSPN PREVIEW: {game_key}", description=preview_text, color=0x0A84FF)
        embed.set_footer(text="QSPN Oracle Analytics Team")
        
        # Public response so everyone can see it
        await i.response.send_message(embed=embed)
        
    select.callback = select_callback
    view = discord.ui.View()
    view.add_item(select)
    
    # Public dropdown menu
    await interaction.response.send_message("📰 **QSPN Game Previews**\nSelect an upcoming matchup to read the analyst breakdown:", view=view)


