class FantasyAuctionView(discord.ui.View):
    """Live auction view. Bid buttons reset a 30-second countdown.
    Admin closes the auction; highest bidder wins."""

    def __init__(self, auction_id, player_name, starting_bid, channel_id):
        super().__init__(timeout=600)
        self.auction_id = auction_id
        self.player_name = player_name
        self.current_bid = starting_bid
        self.current_bidder = None
        self.channel_id = channel_id
        self.last_bid_time = time.time()
        self.closed = False

    async def place_bid(self, interaction: discord.Interaction, increment: int):
        if self.closed:
            return await interaction.response.send_message("🔒 Auction closed.", ephemeral=True)
        state = load_state()
        state = init_fantasy(state)
        uid = str(interaction.user.id)
        if uid not in state['fantasy']['managers']:
            return await interaction.response.send_message("❌ You're not a fantasy manager. Run `/fantasy_join` first.", ephemeral=True)

        mgr = state['fantasy']['managers'][uid]
        new_bid = self.current_bid + increment

        if mgr['budget_remaining'] < new_bid:
            return await interaction.response.send_message(f"❌ Insufficient budget. You have **{mgr['budget_remaining']:,} VC**.", ephemeral=True)

        if len(mgr['roster']) >= FANTASY_ROSTER_SIZE:
            return await interaction.response.send_message(f"❌ Your roster is full ({FANTASY_ROSTER_SIZE} players).", ephemeral=True)

        self.current_bid = new_bid
        self.current_bidder = uid
        self.last_bid_time = time.time()

        embed = interaction.message.embeds[0]
        embed.set_field_at(0, name="💰 Current Bid", value=f"**{self.current_bid:,} VC** by <@{uid}>", inline=False)
        embed.set_footer(text="Admin closes the auction. Highest bidder when it closes wins.")
        await interaction.response.edit_message(embed=embed, view=self)

    @discord.ui.button(label="Bid +100", style=discord.ButtonStyle.primary)
    async def bid_100(self, interaction, button): await self.place_bid(interaction, 100)

    @discord.ui.button(label="Bid +500", style=discord.ButtonStyle.primary)
    async def bid_500(self, interaction, button): await self.place_bid(interaction, 500)

    @discord.ui.button(label="Bid +1000", style=discord.ButtonStyle.success)
    async def bid_1000(self, interaction, button): await self.place_bid(interaction, 1000)

    @discord.ui.button(label="🔨 Close Auction (Admin)", style=discord.ButtonStyle.danger, row=1)
    async def close_auction(self, interaction, button):
        if not interaction.user.guild_permissions.administrator:
            return await interaction.response.send_message("❌ Admins only.", ephemeral=True)
        self.closed = True
        state = load_state()
        state = init_fantasy(state)

        if self.current_bidder:
            mgr = state['fantasy']['managers'][self.current_bidder]
            mgr['budget_remaining'] -= self.current_bid
            mgr['roster'].append(self.player_name)
            save_state(state)
            for child in self.children: child.disabled = True
            result_embed = discord.Embed(
                title=f"🔨 SOLD: {self.player_name}",
                description=f"Sold to <@{self.current_bidder}> for **{self.current_bid:,} VC**!\n*Budget remaining: {mgr['budget_remaining']:,} VC | Roster: {len(mgr['roster'])}/{FANTASY_ROSTER_SIZE}*",
                color=0xFFD700
            )
            await interaction.response.edit_message(embed=result_embed, view=self)
        else:
            for child in self.children: child.disabled = True
            await interaction.response.edit_message(content=f"⚠️ No bids placed on **{self.player_name}**. Auction void.", view=self)


