@fantasy_group.command(name="set_lineup", description="Set your 5-player starting lineup for the week (comma-separated names).")
async def fantasy_set_lineup(interaction: discord.Interaction, starters: str):
    state = load_state()
    state = init_fantasy(state)
    uid = str(interaction.user.id)
    if uid not in state['fantasy']['managers']:
        return await interaction.response.send_message("❌ You're not a fantasy manager.", ephemeral=True)

    mgr = state['fantasy']['managers'][uid]
    picked = [s.strip() for s in starters.split(',') if s.strip()]

    if len(picked) != FANTASY_LINEUP_SIZE:
        return await interaction.response.send_message(f"❌ You must pick exactly {FANTASY_LINEUP_SIZE} starters (you gave {len(picked)}).", ephemeral=True)

    invalid = [p for p in picked if p not in mgr['roster']]
    if invalid:
        return await interaction.response.send_message(f"❌ These aren't on your roster: {', '.join(invalid)}", ephemeral=True)

    week_key = _security_datetime.datetime.now().strftime("%Y-W%U")
    mgr['lineup'] = picked
    mgr['lineup_week'] = week_key
    save_state(state)
    embed = discord.Embed(title="⭐ Lineup Locked In", description=f"**Week {week_key}** starters:\n" + "\n".join([f"• {p}" for p in picked]), color=0x30D158)
    await interaction.response.send_message(embed=embed, ephemeral=True)


@fantasy_group.command(name="leaderboard", description="View the current fantasy points standings.")
async def fantasy_leaderboard(interaction: discord.Interaction):
    state = load_state()
    state = init_fantasy(state)
    if not state['fantasy']['managers']:
        return await interaction.response.send_message("📊 No fantasy managers yet.", ephemeral=True)

    df = _cached_df
    if df is None or df.empty:
        return await interaction.response.send_message("⚠️ Stat database is loading. Try again in a moment.", ephemeral=True)

    week_key = _security_datetime.datetime.now().strftime("%Y-W%U")
    p_df = df[df['Type'].astype(str).str.lower() == 'player'].copy()
    p_df['FP'] = p_df.apply(lambda r: calc_fantasy_points(r['PTS'], r['REB'], r['AST'], r['STL'], r['BLK'], r['TO']), axis=1)

    standings = []
    for uid, mgr in state['fantasy']['managers'].items():
        if mgr['lineup_week'] != week_key or not mgr['lineup']:
            standings.append((uid, mgr['name'], 0.0, "No lineup set"))
            continue
        lineup_df = p_df[p_df['Player/Team'].isin(mgr['lineup'])]
        total_fp = lineup_df['FP'].sum()
        standings.append((uid, mgr['name'], float(total_fp), f"{len(lineup_df)} games counted"))

    standings.sort(key=lambda x: -x[2])

    lines = []
    for rank, (uid, name, fp, note) in enumerate(standings, 1):
        medal = ["🥇","🥈","🥉"][rank-1] if rank <= 3 else f"`{rank}.`"
        lines.append(f"{medal} **{name}** — `{fp:.1f}` FP  *({note})*")

    embed = discord.Embed(
        title=f"📊 QCL Fantasy Leaderboard — Week {week_key}",
        description="\n".join(lines)[:4000],
        color=0xFFD700
    )
    embed.set_footer(text="Scoring: PTS + 1.2·REB + 1.5·AST + 3·STL + 3·BLK - TO")
    await interaction.response.send_message(embed=embed)


