class FantasyResetView(discord.ui.View):
    """Confirm-or-cancel for resetting a manager's roster (or the whole league)."""
    def __init__(self, admin_id, target_uid=None):
        super().__init__(timeout=30)
        self.admin_id = admin_id
        self.target_uid = target_uid  # None = full league reset

    @discord.ui.button(label="✅ Confirm Reset", style=discord.ButtonStyle.danger)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.admin_id:
            return await interaction.response.send_message("🚫 Only the admin who ran this can confirm.", ephemeral=True)
        state = load_state(); state = init_fantasy(state)
        budget = state['fantasy']['budget']

        if self.target_uid:
            # Reset one manager — refund budget, clear roster + lineup
            if self.target_uid in state['fantasy']['managers']:
                mgr = state['fantasy']['managers'][self.target_uid]
                mgr['budget_remaining'] = budget
                mgr['roster'] = []
                mgr['lineup'] = []
                mgr['lineup_week'] = None
                save_state(state)
                msg = f"✅ Reset <@{self.target_uid}>'s roster. Budget restored to {budget:,} VC."
            else:
                msg = "❌ That manager no longer exists."
        else:
            # Full league reset — every manager back to square one
            for uid, mgr in state['fantasy']['managers'].items():
                mgr['budget_remaining'] = budget
                mgr['roster'] = []
                mgr['lineup'] = []
                mgr['lineup_week'] = None
            save_state(state)
            msg = f"✅ Reset ALL {len(state['fantasy']['managers'])} managers. Everyone back to {budget:,} VC."

        for child in self.children: child.disabled = True
        await interaction.response.edit_message(content=msg, embed=None, view=self)

    @discord.ui.button(label="❌ Cancel", style=discord.ButtonStyle.secondary)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.admin_id:
            return await interaction.response.send_message("🚫 Only the admin who ran this can cancel.", ephemeral=True)
        for child in self.children: child.disabled = True
        await interaction.response.edit_message(content="🚫 Reset cancelled.", embed=None, view=self)


