@fantasy_group.command(name="drop_player", description="Drop a player from your roster (refunds nothing, frees a spot).")
async def fantasy_drop_player(interaction: discord.Interaction, player_name: str):
    state = load_state(); state = init_fantasy(state)
    uid = str(interaction.user.id)
    if uid not in state['fantasy']['managers']:
        return await interaction.response.send_message("❌ You're not a fantasy manager.", ephemeral=True)
    mgr = state['fantasy']['managers'][uid]
    # Case-insensitive match
    match = next((p for p in mgr['roster'] if p.lower() == player_name.lower()), None)
    if not match:
        return await interaction.response.send_message(f"❌ `{player_name}` isn't on your roster.", ephemeral=True)
    mgr['roster'].remove(match)
    if match in mgr['lineup']:
        mgr['lineup'].remove(match)
    save_state(state)
    await interaction.response.send_message(f"🗑️ Dropped **{match}** from your roster. ({len(mgr['roster'])}/{FANTASY_ROSTER_SIZE} spots used)", ephemeral=True)


