@admin_group.command(name="reset_economy", description="[ADMIN] DANGER: Wipe all wallets. Auto-backup, PIN-locked, confirmation required.")
@app_commands.checks.has_permissions(administrator=True)
@app_commands.choices(scope=[
    app_commands.Choice(name="VC only", value="vc"),
    app_commands.Choice(name="CUPBUCKS only", value="cupbucks"),
    app_commands.Choice(name="BOTH (nuclear option)", value="both"),
])
async def admin_reset_economy(interaction: discord.Interaction, pin: str, scope: app_commands.Choice[str]):
    """Resets all player wallets to zero after a full backup + confirmation step."""
    if not admin_pin_matches(pin, interaction, "admin_reset_economy"):
        return await interaction.response.send_message("🚫 Wrong PIN. Owner has been alerted.", ephemeral=True)

    # ── Step 1: Take a timestamped backup BEFORE we even ask for confirmation
    try:
        os.makedirs(BACKUP_PATH, exist_ok=True)
        ts = time.strftime("%Y%m%d_%H%M%S")
        backup_filename = f"qcl_state.PRE_RESET_{scope.value}.{ts}.json"
        backup_full = os.path.join(BACKUP_PATH, backup_filename)
        shutil.copy2(STATE_FILE, backup_full)
    except Exception as e:
        return await interaction.response.send_message(
            f"❌ Backup failed (aborting for safety): `{str(e)[:300]}`",
            ephemeral=True
        )

    # ── Step 2: Read current state and calculate what would be wiped
    state = load_state()
    total_vc = sum(bal for bal in state.get('balances', {}).values() if bal > 0)
    total_sb = sum(p.get('cupbucks', 0) for p in state.get('rpg', {}).values() if p.get('cupbucks', 0) > 0)
    vc_accounts = sum(1 for bal in state.get('balances', {}).values() if bal > 0)
    sb_accounts = sum(1 for p in state.get('rpg', {}).values() if p.get('cupbucks', 0) > 0)

    # ── Step 3: Build a vivid preview embed
    embed = discord.Embed(
        title="⚠️ ECONOMY RESET — CONFIRMATION REQUIRED",
        description=(
            f"You're about to **PERMANENTLY WIPE** the Qwik's Cup League economy.\n\n"
            f"**Scope:** `{scope.value.upper()}`\n"
            f"**Backup already saved** at `{backup_filename}` — you can restore from this file.\n\n"
            f"This is the last warning. Click ✅ within 30 seconds to commit."
        ),
        color=0xFF453A
    )

    if scope.value in ('vc', 'both'):
        embed.add_field(name="💰 VC About to Vanish", value=f"`{total_vc:,} VC` across `{vc_accounts}` accounts", inline=False)
    if scope.value in ('cupbucks', 'both'):
        embed.add_field(name="🎟️ CUPBUCKS About to Vanish", value=f"`{total_sb:,} SB` across `{sb_accounts}` accounts", inline=False)

    embed.add_field(
        name="✅ Preserved (not touched)",
        value="• Quests progress\n• Fantasy rosters\n• Pick'Em records\n• Streaks\n• Trophies & awards\n• Rep / archetype data",
        inline=False
    )
    embed.set_footer(text=f"Backup: {backup_filename}")

    view = EconomyResetConfirmView(interaction.user.id, scope.value, backup_filename, {})
    await interaction.response.send_message(embed=embed, view=view, ephemeral=True)


@security_group.command(name="rotate_pin", description="[ADMIN] Change the admin PIN. Requires the CURRENT pin to authorize.")
@app_commands.checks.has_permissions(administrator=True)
async def admin_rotate_pin(interaction: discord.Interaction, current_pin: str, new_pin: str):
    """Rotate the admin PIN safely. Triggers an alert to the bot owner regardless of outcome."""
    if not admin_pin_matches(current_pin, interaction, "admin_rotate_pin (verify current)"):
        return await interaction.response.send_message("🚫 Wrong current PIN. Owner has been alerted.", ephemeral=True)

    if len(new_pin) < 4:
        return await interaction.response.send_message("⚠️ New PIN must be at least 4 characters.", ephemeral=True)
    if new_pin == current_pin:
        return await interaction.response.send_message("⚠️ New PIN must be different from the current one.", ephemeral=True)

    global _PIN_HASH, ADMIN_PIN
    ADMIN_PIN = new_pin
    _PIN_HASH = _hash_pin(new_pin)

    # Notify the owner of the rotation
    if BOT_OWNER_ID:
        try:
            owner = await bot.fetch_user(BOT_OWNER_ID)
            embed = discord.Embed(
                title="🔐 ADMIN PIN ROTATED",
                description=f"PIN was changed by {interaction.user.mention} (`{interaction.user}`).",
                color=0xFF9F0A,
                timestamp=_security_datetime.datetime.utcnow()
            )
            embed.add_field(name="⚠️ Important", value=f"**You must update your `.env` file** with the new PIN, or it will revert on next restart.\n\n`ADMIN_PIN={new_pin}`", inline=False)
            await owner.send(embed=embed)
        except Exception as e:
            print(f"[Security] Failed to DM owner about PIN rotation: {e}")

    await interaction.response.send_message(
        "✅ **PIN rotated successfully.**\n\n"
        f"⚠️ **CRITICAL:** Update your `.env` file now with `ADMIN_PIN={new_pin}` or the change will be lost on restart!\n\n"
        "The bot owner has been notified by DM.",
        ephemeral=True
    )


@security_group.command(name="status", description="[OWNER ONLY] View current PIN-attempt audit log & lockouts.")
async def security_status(interaction: discord.Interaction):
    """Shows who's currently locked out, recent failure counts, and configured alert routing."""
    if interaction.user.id != BOT_OWNER_ID:
        return await interaction.response.send_message("🚫 Owner only.", ephemeral=True)

    now = time.time()

    embed = discord.Embed(title="🔐 Security Audit", color=0x5E5CE6, timestamp=_security_datetime.datetime.utcnow())

    # Configured routing
    owner_status = f"<@{BOT_OWNER_ID}>" if BOT_OWNER_ID else "❌ Not set"
    chan_status = f"<#{SECURITY_LOG_CHANNEL_ID}>" if SECURITY_LOG_CHANNEL_ID else "Not configured"
    embed.add_field(name="📨 Alert Routing", value=f"**Owner DM:** {owner_status}\n**Log Channel:** {chan_status}", inline=False)

    # Active lockouts
    active = [(uid, ts) for uid, ts in _lockouts.items() if ts > now]
    if active:
        lock_lines = [f"<@{uid}> — unlocks in **{int((ts-now)/60)+1}m**" for uid, ts in active]
        embed.add_field(name="🔒 Active Lockouts", value="\n".join(lock_lines), inline=False)
    else:
        embed.add_field(name="🔒 Active Lockouts", value="*None*", inline=False)

    # Recent failures (in window)
    recent_failures = []
    for uid, attempts in _failed_attempts.items():
        live = [t for t in attempts if (now - t) < LOCKOUT_WINDOW]
        if live:
            recent_failures.append((uid, len(live)))
    if recent_failures:
        f_lines = [f"<@{uid}> — **{count}**/{LOCKOUT_THRESHOLD} strikes" for uid, count in recent_failures]
        embed.add_field(name="⚠️ Users on Warning", value="\n".join(f_lines), inline=False)
    else:
        embed.add_field(name="⚠️ Users on Warning", value="*Nobody on watch*", inline=False)

    embed.set_footer(text=f"Rules: {LOCKOUT_THRESHOLD} wrong PINs in {LOCKOUT_WINDOW//60}min = {LOCKOUT_DURATION//60}min lockout")
    await interaction.response.send_message(embed=embed, ephemeral=True)


@security_group.command(name="unlock", description="[OWNER ONLY] Clear a user's lockout / failure record.")
async def security_unlock(interaction: discord.Interaction, user: discord.Member):
    if interaction.user.id != BOT_OWNER_ID:
        return await interaction.response.send_message("🚫 Owner only.", ephemeral=True)

    uid = str(user.id)
    cleared = False
    if uid in _lockouts:
        del _lockouts[uid]
        cleared = True
    if uid in _failed_attempts:
        _failed_attempts[uid].clear()
        cleared = True

    msg = f"✅ Cleared lockout/failures for {user.mention}." if cleared else f"ℹ️ {user.mention} had no lockout or warning."
    await interaction.response.send_message(msg, ephemeral=True)


@bot.tree.command(name="player_of_the_series", description="Open a community vote for Player of the Series across a Game ID range.")
@app_commands.describe(
    start_game_id="The FIRST Game ID in the series (inclusive)",
    end_game_id="The LAST Game ID in the series (inclusive)",
    series_label="What to call this series (e.g. 'S6 Finals: Krashout vs Low Ego')"
)
async def player_of_the_series(interaction: discord.Interaction, start_game_id: int, end_game_id: int, series_label: str):
    if not interaction.user.guild_permissions.administrator:
        return await interaction.response.send_message("❌ Admins only.", ephemeral=True)
    if start_game_id > end_game_id:
        return await interaction.response.send_message("❌ Start Game ID must be ≤ End Game ID.", ephemeral=True)

    await interaction.response.defer()

    # Make sure stats are fresh
    await refresh_stats_and_vault()
    df = _cached_df
    if df is None or df.empty:
        return await interaction.followup.send("❌ Stat database isn't loaded yet. Try again in a moment.")

    # LIVE SHEET ONLY — the daily-updated sheet is the sole source here.
    # (Excludes the folded SPAM archive, whose Game_IDs overlap QCL's.)
    if 'Era' in df.columns:
        df = df[df['Era'] == 'QCL']
    p_df = df[df['Type'].astype(str).str.lower() == 'player'].copy()
    p_df['Game_ID'] = pd.to_numeric(p_df['Game_ID'], errors='coerce')
    series_df = p_df[(p_df['Game_ID'] >= start_game_id) & (p_df['Game_ID'] <= end_game_id)].copy()

    if series_df.empty:
        return await interaction.followup.send(f"❌ No player stats found for Game IDs `{start_game_id}` through `{end_game_id}`.")

    # Compute TS% per row
    series_df['TS%'] = np.where(
        (series_df['FGA'] + 0.44 * series_df['FTA']) > 0,
        series_df['PTS'] / (2 * (series_df['FGA'] + 0.44 * series_df['FTA'])) * 100,
        0
    )

    # Aggregate per player: averages + series highs
    agg = series_df.groupby(['Player/Team', 'Team Name']).agg(
        GP=('Game_ID', 'nunique'),
        PPG=('PTS', 'mean'),
        RPG=('REB', 'mean'),
        APG=('AST', 'mean'),
        SPG=('STL', 'mean'),
        BPG=('BLK', 'mean'),
        TOPG=('TO', 'mean'),
        FPG=('FOULS', 'mean'),
        TS_pct=('TS%', 'mean'),
        PIE_avg=('PIE_Raw', 'mean'),
        Tipped_avg=('Tipped_Passes', 'mean'),
        Affected_avg=('Shots_Affected', 'mean'),
        FB_avg=('FB_Points', 'mean'),
        PTS_HIGH=('PTS', 'max'),
        REB_HIGH=('REB', 'max'),
        AST_HIGH=('AST', 'max'),
        STL_HIGH=('STL', 'max'),
        BLK_HIGH=('BLK', 'max'),
        TIPPED_HIGH=('Tipped_Passes', 'max'),
        AFFECTED_HIGH=('Shots_Affected', 'max'),
        FB_HIGH=('FB_Points', 'max'),
    ).round(2).reset_index()

    # Rank candidates by PIE average and take top 5
    agg = agg.sort_values('PIE_avg', ascending=False).head(5)

    if agg.empty:
        return await interaction.followup.send("❌ Couldn't compute any candidates from this range.")

    # Build candidates list for the view
    candidates = []
    for _, row in agg.iterrows():
        stats = {
            'GP': int(row['GP']),
            'PPG': float(row['PPG']), 'RPG': float(row['RPG']), 'APG': float(row['APG']),
            'SPG': float(row['SPG']), 'BPG': float(row['BPG']),
            'TOPG': float(row['TOPG']), 'FPG': float(row['FPG']),
            'TS_pct': float(row['TS_pct']), 'PIE': float(row['PIE_avg']),
            'TIPPED': float(row['Tipped_avg']), 'AFFECTED': float(row['Affected_avg']), 'FB': float(row['FB_avg']),
            'PTS_HIGH': int(row['PTS_HIGH']), 'REB_HIGH': int(row['REB_HIGH']),
            'AST_HIGH': int(row['AST_HIGH']), 'STL_HIGH': int(row['STL_HIGH']),
            'BLK_HIGH': int(row['BLK_HIGH']),
            'TIPPED_HIGH': int(row['TIPPED_HIGH']), 'AFFECTED_HIGH': int(row['AFFECTED_HIGH']),
            'FB_HIGH': int(row['FB_HIGH']),
        }
        candidates.append((row['Player/Team'], row['Team Name'], stats))

    # Build the announcement embed
    embed = discord.Embed(
        title=f"🏆 VOTE: Player of the Series — {series_label}",
        description=(
            f"**Series:** Games `{start_game_id}` → `{end_game_id}`  •  **{len(series_df['Game_ID'].unique())} games**\n"
            f"Tap a button below to vote. You can change your vote anytime before the admin closes voting.\n"
        ),
        color=0xFFD700
    )

    for idx, (player, team, s) in enumerate(candidates):
        medal = ["1️⃣", "2️⃣", "3️⃣", "4️⃣", "5️⃣"][idx]
        # Series averages line
        avg_line = (
            f"**Avg:** {s['PPG']:.1f} PPG / {s['RPG']:.1f} RPG / {s['APG']:.1f} APG\n"
            f"**D:** {s['SPG']:.1f} SPG / {s['BPG']:.1f} BPG  •  **TS:** {s['TS_pct']:.1f}%\n"
            f"**Hustle Avg:** {s['TIPPED']:.1f} Tipped / {s['AFFECTED']:.1f} Affected / {s['FB']:.1f} FB Pts\n"
            f"**Series Highs:** {s['PTS_HIGH']} PTS, {s['REB_HIGH']} REB, {s['AST_HIGH']} AST, "
            f"{s['STL_HIGH']} STL, {s['BLK_HIGH']} BLK\n"
            f"**Hustle Highs:** {s['TIPPED_HIGH']} Tipped, {s['AFFECTED_HIGH']} Affected, {s['FB_HIGH']} FB\n"
            f"**PIE:** `{s['PIE']:.2f}`  •  **GP:** {s['GP']}"
        )
        embed.add_field(name=f"{medal} {player} ({team})", value=avg_line, inline=False)

    embed.add_field(name="🗳️ Live Tally", value="*No votes yet.*", inline=False)
    embed.set_footer(text=f"Voting opened by {interaction.user.display_name} • Auto-closes in 24h or manually by admin")

    # Persist the poll to state so votes survive a crash/restart, then attach a
    # persistent view (re-registered on startup) to the announcement message.
    state = load_state()
    polls = _pots_state(state)
    pid = f"pots_{int(_eastern_now().timestamp())}"
    poll = {
        'series_label': series_label,
        'game_ids': list(range(start_game_id, end_game_id + 1)),
        'opened_by_id': interaction.user.id,
        'candidates': [{'player': p, 'team': t, 'stats': s} for (p, t, s) in candidates],
        'votes': {}, 'status': 'open',
        'channel_id': interaction.channel.id,
        'opened_at': _eastern_now().isoformat(),
        'closes_at': (_eastern_now() + _security_datetime.timedelta(hours=24)).isoformat(),
    }
    polls[pid] = poll
    view = PlayerOfSeriesView(pid, poll)
    msg = await interaction.followup.send(embed=embed, view=view)
    poll['message_id'] = str(msg.id)
    save_state(state)


@bot.tree.command(name="ask_claude", description="Ask Claude (Anthropic AI) a question about the Qwik's Cup League.")
async def ask_claude(interaction: discord.Interaction, question: str):
    """Uses Anthropic's Claude as the AI brain for Qwik's Cup League analysis.
    Refreshes live stats AND reads every file in the KnowledgeVault on each call."""
    if not claude_client and not ai_client and not _ollama_available():
        return await interaction.response.send_message(embed=_faq_reply_embed(question))

    await interaction.response.defer(thinking=True)

    # 0. ALWAYS refresh live stats + re-scan the KnowledgeVault before answering
    await refresh_stats_and_vault()

    # 1. Build live stats context from the freshly-refreshed cache
    df = _cached_df
    stats_context = ""
    if df is not None:
        registry = get_universal_registry()

        def apply_discord_tag(player_name):
            clean_name = re.sub(r'[^a-zA-Z0-9]', '', str(player_name)).lower()
            return registry.get(clean_name, player_name)

        p_df = df[df['Type'].str.lower() == 'player'].copy()
        p_df['Discord_Ping'] = p_df['Player/Team'].apply(apply_discord_tag)

        p_df['TS%'] = np.where(
            (p_df['FGA'] + 0.44 * p_df['FTA']) > 0,
            p_df['PTS'] / (2 * (p_df['FGA'] + 0.44 * p_df['FTA'])),
            0
        )

        player_stats = p_df.groupby(['Discord_Ping', 'Team Name']).agg(
            GP=('Game_ID', 'nunique'),
            PTS=('PTS', 'mean'),
            REB=('REB', 'mean'),
            AST=('AST', 'mean'),
            STL=('STL', 'mean'),
            BLK=('BLK', 'mean'),
            PIE=('PIE_Raw', 'mean'),
            TS_pct=('TS%', 'mean'),
        ).round(1).reset_index()

        t_df = df[df['Type'].str.lower() == 'team'].copy()
        team_stats = t_df.groupby('Team Name').agg(
            GP=('Game_ID', 'nunique'),
            Wins=('Win', 'sum'),
            PPG=('PTS', 'mean'),
            Opp_PPP=('Opp_PPP', 'mean'),
        ).round(1).reset_index()
        # Provide explicit Losses + a pre-formatted W-L Record so the AI never
        # mistakes Games Played for losses (18 wins in 27 GP is 18-9, NOT 18-27).
        team_stats['GP'] = team_stats['GP'].astype(int)
        team_stats['Wins'] = team_stats['Wins'].astype(int)
        team_stats['Losses'] = (team_stats['GP'] - team_stats['Wins']).clip(lower=0)
        team_stats['Record'] = team_stats['Wins'].astype(str) + '-' + team_stats['Losses'].astype(str)
        team_stats = team_stats[['Team Name', 'Record', 'Wins', 'Losses', 'GP', 'PPG', 'Opp_PPP']]

        stats_context = (
            "--- LIVE PLAYER CAREER AVERAGES ---\n"
            + player_stats.to_csv(index=False)
            + "\n--- LIVE TEAM RECORDS & STATS (the 'Record' column is the official Wins-Losses) ---\n"
            + team_stats.to_csv(index=False)
        )
    else:
        stats_context = "[Warning: Stat database is warming up. No data available yet.]"

    # 2. Pull text content from the KnowledgeVault for Claude to read
    vault_text = read_vault_as_text()
    vault_section = (
        f"\n--- KNOWLEDGE VAULT (Rules, Lore, Recent Notes) ---\n{vault_text}\n"
        if vault_text
        else "\n[Knowledge Vault: No readable text files found.]\n"
    )

    # Pull the derived intelligence file (player history, lore, rivalries)
    intel = load_intelligence()
    if intel and intel.get('players'):
        meta = intel.get('league_meta', {})
        intel_section = (
            f"\n--- DERIVED LEAGUE INTELLIGENCE (rebuilt: {meta.get('last_rebuilt','?')}) ---\n"
            f"League scope: {meta.get('total_games',0)} games, {meta.get('total_players',0)} players, "
            f"{meta.get('total_teams',0)} teams, {meta.get('total_seasons',1)} seasons.\n\n"
            f"Use this to know who's a veteran (status='active_legend'/'active_veteran'), "
            f"who's a rookie (status='active_rookie'), and who's no longer playing (status='inactive'). "
            f"Each player has a 'signature' archetype, career averages/highs, and 'lore_moments' to reference.\n\n"
            f"PLAYERS:\n{json.dumps(intel.get('players', {}), indent=2)[:6000]}\n\n"
            f"RIVALRIES:\n{json.dumps(intel.get('rivalries', {}), indent=2)[:1500]}\n\n"
            f"LEAGUE RECORDS:\n{json.dumps(intel.get('records', {}), indent=2)}\n"
        )
    else:
        intel_section = "\n[Intelligence file not built yet. Tell the user to run /intel_rebuild for richer context.]\n"

    system_prompt = f"""You are CupMuse-C, the Claude-powered AI analyst for the QCL.

{QCL_LORE}

You have THREE sources of truth:
1. The Knowledge Vault below (rules, lore, recent notes, any .txt/.md/.csv/.json files).
2. The Derived League Intelligence (player history, archetypes, rivalries, records).
3. The Live League Stats (current-game averages).

CRITICAL INTELLIGENCE RULES:
- Always prioritize information from the Knowledge Vault's 'recent.txt' (if present) for the most current context.
- Use the Derived Intelligence to know WHO each player is — their status (legend, veteran, regular, rookie, inactive), their signature archetype, and their lore moments. This is your character-knowledge layer.
- When asked about someone's history or whether they've been around before, use the 'first_seen' and 'seasons_active' fields from intelligence.
- When referencing a player, use the exact string from the 'Discord_Ping' column (e.g., <@123456789>) to tag them.
- TEAM RECORDS: a team's win-loss record is the 'Record' column (Wins-Losses) in the Live Team Stats — e.g. New Vision is "18-9". NEVER report Games Played (GP) as the loss count; losses = GP minus Wins. Re-read the Record column before stating any team's record.
- Limit player tags to a maximum of 1-2 key players per response. Never spam tags.
- Be concise, analytical, and use Qwik's Cup League terminology.
- Keep responses under 1800 characters so they fit cleanly in a Discord embed.
- ALWAYS end by asking if the user has another question.

{vault_section}

{intel_section}

{stats_context}"""

    try:
        answer, _src = await ask_ai(system_prompt, question, max_tokens=700)
        embed = discord.Embed(
            title=("🧠 CupMuse-C (Claude Brain)" if _src == "claude" else "🧠 CupMuse (Local Brain)" if _src == "local" else "🧠 CupMuse (Gemini Fallback)"),
            description=answer[:4000],
            color=0x5E5CE6
        )
        _brain = _ai_label(_src)
        embed.set_footer(text=f"Powered by {_brain} + KnowledgeVault | Q: {question[:80]}")
        await interaction.followup.send(embed=embed)

    except Exception as e:
        print(f"[ask_claude] AI failed, using FAQ fallback: {e}")
        await interaction.followup.send(embed=_faq_reply_embed(question))




# ==== QCL :: THE HUNT + CUP ECONOMY (Cash App) — appended ====
# ════════════════════════════════════════════════════════════════════
#  THE HUNT + CUP ECONOMY  (QCL) — with Cash App real-cash flow
#  SB pots: CUPBUCKS, split across the winning roster (automatic).
#  Real cash: ante / challenge / buy-in via Cash App. Receipts print
#  in-channel; commissioner taps Confirm to make funds live; payouts
#  print a card with the winner's $cashtag. Cup pool is never touched.
# ════════════════════════════════════════════════════════════════════

# ---- TUNABLES ----
HUNT_MARK_THRESHOLD = 3
HUNT_SB_START       = 500
HUNT_SB_STEP        = 500
SB_PER_DOLLAR       = 500          # $1 = 500 SB (display only)
HUNT_GOLD           = 0xFFD60A
CASHAPP_LINK        = "https://cash.app/$QWIKSCL"   # add /AMOUNT to prefill
APPLE_PAY_ID        = "jessicazbusinezz@yahoo.com"  # Apple Cash — sent in Messages app; iPhone senders only
REG_FEE_DEFAULT     = 0             # registration fee ($). 0 = off until set via /bounty setfee
PAYMENTS_CHANNEL_DEFAULT = 1518748013139591229     # cards post here unless /bounty setchannel overrides

CUP_BUYIN_DEFAULT   = 50
CUP_CHAMPION_PCT    = 0.75
CUP_RUNNERUP_PCT    = 0.25
SUSPENDED_ROLE_NAME = "Suspended"   # role applied while a player owes a fine


def _now_str():
    return time.strftime("%Y-%m-%d %H:%M")

def _pay_link(amount):
    """Cash App deep link that opens with the dollar amount prefilled."""
    return f"{CASHAPP_LINK}/{int(amount)}"


def _hunt(state):
    h = state.setdefault('hunt', {})
    h.setdefault('streaks', {})
    h.setdefault('marked', {})
    h.setdefault('processed_games', [])
    h.setdefault('ledger', [])
    h.setdefault('cashtags', {})       # uid -> "$tag"
    h.setdefault('config', {})         # payments_channel_id, reg_fee
    h.setdefault('reg', {})            # uid -> {fee, paid}
    h.setdefault('cup', {"id": None, "status": "closed", "buyin": CUP_BUYIN_DEFAULT,
                         "entrants": {}, "opened_at": None})
    return h


def _get_cashtag(uid):
    return _hunt(load_state()).get('cashtags', {}).get(str(uid))


def _resolve_pay_channel(fallback):
    """The configured payments channel, the baked-in default, or the fallback."""
    cid = _hunt(load_state()).get('config', {}).get('payments_channel_id') or PAYMENTS_CHANNEL_DEFAULT
    if cid:
        ch = bot.get_channel(int(cid))
        if ch:
            return ch
    return fallback


async def _maybe_invoice_registration(interaction):
    """Charge the registration fee once per player, posting a Cash App card
    to the payments channel. No-op until a fee is set via /bounty setfee."""
    state = load_state(); h = _hunt(state); uid = str(interaction.user.id)
    if uid in h.get('reg', {}):           # already invoiced
        return
    fee = int(h.get('config', {}).get('reg_fee', REG_FEE_DEFAULT))
    if fee <= 0:
        return
    h.setdefault('reg', {})[uid] = {"fee": fee, "paid": False}
    save_state(state)
    ch = _resolve_pay_channel(interaction.channel)
    await ch.send(embed=_invoice_embed(
        f"📝 Registration — {interaction.user.display_name}", interaction.user.mention, fee,
        f"{interaction.user.mention} is registering for the QCL. Pay your registration fee to lock your spot."))


def _roster_uids(team):
    state = load_state()
    names = state.get('rosters', {}).get(team, {}).get('active', [])
    reg = get_universal_registry()
    uids = []
    for n in names:
        key = re.sub(r'[^a-zA-Z0-9]', '', str(n)).lower()
        ping = reg.get(key)
        if ping:
            m = re.search(r'\d+', ping)
            if m and m.group() not in uids:
                uids.append(m.group())
    return uids


def _ledger_add(h, entries):
    import uuid
    for e in entries:
        e.setdefault('id', uuid.uuid4().hex[:8])
        e.setdefault('when', _now_str())
        e.setdefault('settled', False)
        h['ledger'].append(e)
    h['ledger'] = h['ledger'][-500:]


def _fund_user(uid):
    """Mark every pending ante/challenge/buy-in for a user as funded.
    Used by /bounty fund and the receipt Confirm button."""
    uid = str(uid)
    state = load_state(); h = _hunt(state); funded = []
    for team, m in h.get('marked', {}).items():
        for u, d in m.get('antes', {}).items():
            if u == uid and not d.get('funded'):
                d['funded'] = True; funded.append(f"${d['amount']} ante on {team}")
        for ct, d in m.get('challenges', {}).items():
            if d.get('uid') == uid and not d.get('funded'):
                d['funded'] = True; funded.append(f"${d['amount']} challenge ({ct} vs {team})")
    ent = h['cup'].get('entrants', {}).get(uid)
    if ent and not ent.get('paid'):
        _tn = _propagate_cup_team_paid(state, h, uid)
        _rpg_award(state, uid, rep=30, heat=-10, reason="Paid Cup buy-in")
        _lbl = f"${h['cup'].get('buyin', CUP_BUYIN_DEFAULT)} Cup buy-in"
        if _tn: _lbl += f" — whole {_tn} roster marked paid"
        _lbl += " · 🎖️ +30 rep, 🚓 -10 heat"
        funded.append(_lbl)
    reg = h.get('reg', {}).get(uid)
    if reg and not reg.get('paid'):
        reg['paid'] = True; funded.append(f"${reg['fee']} registration")
    save_state(state)
    return funded


def hunt_on_game_result(winner_team, loser_team, game_id=None):
    state = load_state(); h = _hunt(state)
    if game_id is not None:
        if game_id in h['processed_games']:
            return None
        h['processed_games'].append(game_id)
        h['processed_games'] = h['processed_games'][-500:]

    ev = {'marked': None, 'broken': None, 'sb_split': None, 'cash': []}
    sb_payouts = []

    h['streaks'][loser_team] = 0

    marked = h['marked'].pop(loser_team, None)
    if marked:
        sb_pot = int(marked.get('sb_pot', 0))
        broken = int(marked.get('streak', 0))
        antes  = {u: d for u, d in marked.get('antes', {}).items() if d.get('funded')}
        chals  = marked.get('challenges', {})
        cash   = []
        cash_pot = int(marked.get('cash_pot', 0))
        if cash_pot > 0:
            cash.append({'to_team': winner_team, 'amount': cash_pot, 'kind': 'bounty_payout',
                         'note': f"Anytime cash bounty on {loser_team} claimed by {winner_team}"})
        if sb_pot > 0:
            sb_payouts.append((winner_team, sb_pot))
        win_ch = chals.pop(winner_team, None)
        if win_ch and win_ch.get('funded'):
            pile = sum(d['amount'] for d in antes.values())
            cash.append({'to_team': winner_team, 'to_uid': win_ch['uid'],
                         'amount': pile + win_ch['amount'], 'kind': 'bounty_claim',
                         'note': f"Ended {loser_team}'s streak"})
        else:
            for uid, d in antes.items():
                cash.append({'to_uid': uid, 'amount': d['amount'], 'kind': 'ante_refund',
                             'note': f"{loser_team}'s streak ended"})
        for ct, d in chals.items():
            if d.get('funded'):
                cash.append({'to_uid': d['uid'], 'amount': d['amount'], 'kind': 'challenge_refund',
                             'note': f"{loser_team}'s streak ended before your game"})
        ev['broken'] = {'team': loser_team, 'by': winner_team, 'streak': broken, 'sb_pot': sb_pot}
        ev['cash'].extend(cash); _ledger_add(h, cash)

    s = h['streaks'].get(winner_team, 0) + 1
    h['streaks'][winner_team] = s

    defender = h['marked'].get(winner_team)
    if defender:
        ch = defender.get('challenges', {}).pop(loser_team, None)
        if ch and ch.get('funded'):
            rew = [{'to_team': winner_team, 'amount': ch['amount'], 'kind': 'defense_reward',
                    'note': f"Defended the streak vs {loser_team}"}]
            ev['cash'].extend(rew); _ledger_add(h, rew)

    if s >= HUNT_MARK_THRESHOLD:
        m = h['marked'].get(winner_team)
        if m:
            m['streak'] = s
            m['sb_pot'] = int(m.get('sb_pot', HUNT_SB_START)) + HUNT_SB_STEP
        else:
            h['marked'][winner_team] = {'streak': s, 'sb_pot': HUNT_SB_START,
                                        'antes': {}, 'challenges': {}, 'marked_at': _now_str()}
        ev['marked'] = {'team': winner_team, 'streak': s, 'sb_pot': h['marked'][winner_team]['sb_pot']}

    win_rep = 25 + (60 if ev.get('broken') else 0)
    win_reason = f"Collected the bounty on {loser_team}" if ev.get('broken') else f"Won vs {loser_team}"
    ev['rpg'] = []
    for _u in _roster_uids(winner_team):
        ev['rpg'].append(_rpg_award(state, _u, rep=win_rep, heat=-5, reason=win_reason))
    for _u in _roster_uids(loser_team):
        ev['rpg'].append(_rpg_award(state, _u, rep=8, reason=f"Battled {winner_team}"))
    save_state(state)

    for team, pot in sb_payouts:
        uids = _roster_uids(team)
        if uids:
            share = pot // len(uids); rem = pot - share * len(uids)
            for i, uid in enumerate(uids):
                amt = share + (rem if i == 0 else 0)
                if amt > 0:
                    process_payout(uid, amt, "cupbucks", f"Bounty: {team} ended a streak")
            ev['sb_split'] = {'team': team, 'total': pot, 'each': share, 'players': len(uids)}
        else:
            ev['sb_split'] = {'team': team, 'total': pot, 'each': 0, 'players': 0, 'unclaimed': True}

    if not (ev['marked'] or ev['broken'] or ev['sb_split'] or ev['cash']):
        return None
    return ev


# ---- broadcast: main event embed + per-payout Cash App cards ----
def hunt_event_embed(ev):
    e = discord.Embed(color=HUNT_GOLD); title = []
    if ev.get('broken'):
        b = ev['broken']; title.append("💥 BOUNTY COLLECTED")
        sp = ev.get('sb_split') or {}; split = ""
        if sp.get('players'):
            split = f"\n💎 **{sp['total']:,} SB** split across **{b['by']}** ({sp['each']:,} each)"
        elif sp.get('unclaimed'):
            split = f"\n💎 **{sp['total']:,} SB** pending (no roster mapped for {b['by']})"
        e.add_field(name=f"🏴 {b['by']} ended {b['team']}'s {b['streak']}-game streak",
                    value=f"The Hunt is over.{split}", inline=False)
    if ev.get('marked'):
        m = ev['marked']; title.append("🎯 MARKED")
        e.add_field(name=f"🔥 {m['team']} — {m['streak']} in a row",
                    value=f"Bounty on their head: **{m['sb_pot']:,} SB** (~${m['sb_pot']//SB_PER_DOLLAR}). "
                          f"End the streak to take it.", inline=False)
    e.title = "  •  ".join(title) if title else "🏀 The Hunt"
    e.set_footer(text="SB paid automatically • cash payouts below")
    return e


def _payout_card(entry):
    labels = {'bounty_claim': '💵 CASH BOUNTY', 'defense_reward': '🛡️ DEFENSE REWARD',
              'ante_refund': '↩️ ANTE REFUND', 'challenge_refund': '↩️ CHALLENGE REFUND',
              'bounty_payout': '🎯 ANYTIME BOUNTY'}
    amt = entry['amount']
    e = discord.Embed(title=f"{labels.get(entry['kind'], '💸 PAYOUT')} — ${amt}",
                      color=HUNT_GOLD, description=entry.get('note', ''))
    uid = entry.get('to_uid'); tag = _get_cashtag(uid) if uid else None
    if uid:
        who = f"<@{uid}>" + (f"  ({tag})" if tag else "  — no $cashtag on file, ask them to `/bounty cashtag`")
        e.add_field(name="Pay to", value=who, inline=False)
        if tag:
            link = f"https://cash.app/{tag}/{int(amt)}"
            e.add_field(name="Send", value=f"[Tap to pay {tag} ${amt}]({link})", inline=False)
    else:
        e.add_field(name="Pay to", value=f"**{entry.get('to_team','?')}** — send to your team rep", inline=False)
    e.set_footer(text="Commissioner: send via Cash App, then tap Mark Sent.")
    return e, PayoutCardView(entry['id'])


async def post_hunt_result(channel, ev):
    """Called from the submit_boxscore hook: post the event + payout cards
    to the configured payments channel (falls back to where the game posted)."""
    try:
        ch = _resolve_pay_channel(channel)
        if ev.get('marked') or ev.get('broken'):
            await channel.send(embed=hunt_event_embed(ev))
        for c in ev.get('cash', []):
            emb, view = _payout_card(c)
            await ch.send(embed=emb, view=view)
        await _rpg_ping_group(channel, ev.get('rpg', []))
    except Exception as e:
        print(f"[HUNT] post error: {e}")


