#  VIEWS
# ════════════════════════════════════════════════════════════════════
class CashConfirmView(discord.ui.View):
    def __init__(self, target_uid):
        super().__init__(timeout=86400)
        self.target_uid = str(target_uid)

    @discord.ui.button(label="Confirm Payment ✅", style=discord.ButtonStyle.success)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not interaction.user.guild_permissions.administrator:
            return await interaction.response.send_message("🔒 Admins only.", ephemeral=True)
        funded = _fund_user(self.target_uid)
        for c in self.children: c.disabled = True
        await interaction.response.edit_message(view=self)
        if funded:
            await interaction.channel.send(
                f"✅ **Payment confirmed** for <@{self.target_uid}> — now live: " + "; ".join(funded))
        else:
            await interaction.followup.send(
                f"Nothing pending for <@{self.target_uid}> (already funded or nothing owed).", ephemeral=True)


class PayoutCardView(discord.ui.View):
    def __init__(self, ledger_id):
        super().__init__(timeout=86400)
        self.ledger_id = ledger_id

    @discord.ui.button(label="Mark Sent ✅", style=discord.ButtonStyle.success)
    async def sent(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not interaction.user.guild_permissions.administrator:
            return await interaction.response.send_message("🔒 Admins only.", ephemeral=True)
        state = load_state(); h = _hunt(state)
        for c in h['ledger']:
            if c.get('id') == self.ledger_id:
                c['settled'] = True
        save_state(state)
        for c in self.children: c.disabled = True
        await interaction.response.edit_message(view=self)


