@bounty_group.command(name="board", description="See Marked teams and their live bounty pots")
async def bounty_board(interaction: discord.Interaction):
    h = _hunt(load_state())
    e = discord.Embed(title="🎯 The Hunt — Bounty Board", color=HUNT_GOLD)
    marked = h.get('marked', {})
    if not marked:
        e.description = "No teams Marked yet. Win 3 straight to get Marked — or an admin can drop one with `/bounty set`."
        return await interaction.response.send_message(embed=e)
    for team, m in sorted(marked.items(), key=lambda kv: kv[1].get('streak', 0), reverse=True):
        antes = sum(d['amount'] for d in m.get('antes', {}).values() if d.get('funded'))
        chals = sum(d['amount'] for d in m.get('challenges', {}).values() if d.get('funded'))
        sb = int(m.get('sb_pot', 0)); cashp = int(m.get('cash_pot', 0))
        bits = []
        if sb: bits.append(f"💎 {sb:,} SB (~${sb//SB_PER_DOLLAR})")
        if cashp: bits.append(f"💵 ${cashp} cash")
        if antes: bits.append(f"💵 ${antes} antes")
        if chals: bits.append(f"🥊 ${chals} challenges")
        pot_line = " • ".join(bits) if bits else "*(open — add antes/challenges)*"
        if m.get('manual') and not m.get('streak'):
            header = f"🎯 {team} — OPEN BOUNTY"
        else:
            header = f"🔥 {team} — {m.get('streak', 0)} wins"
