# ── Anytime bounties: drop a bounty on any team on demand (no streak) ──
@bounty_group.command(name="set", description="[ADMIN] Drop a bounty on ANY team, anytime — no streak needed.")
@app_commands.checks.has_permissions(administrator=True)
@app_commands.autocomplete(team=team_autocomplete)
@app_commands.describe(team="Team to put a bounty on", amount="Bounty size (SB or dollars)",
                       currency="CUPBUCKS (default) or real cash")
@app_commands.choices(currency=[
    app_commands.Choice(name="CUPBUCKS (SB)", value="sb"),
    app_commands.Choice(name="Real Cash ($)", value="cash"),
])
async def bounty_set(interaction: discord.Interaction, team: str, amount: int,
                     currency: app_commands.Choice[str] = None):
    if amount <= 0:
        return await interaction.response.send_message("❌ Amount must be positive.", ephemeral=True)
    cur = currency.value if currency else "sb"
    team = team.strip()
    state = load_state(); h = _hunt(state)
    m = h['marked'].get(team)
    newly = m is None
    if newly:
        m = {'streak': 0, 'sb_pot': 0, 'cash_pot': 0, 'antes': {}, 'challenges': {},
             'marked_at': _now_str(), 'manual': True, 'placed_by': interaction.user.display_name}
        h['marked'][team] = m
    if cur == "cash":
        m['cash_pot'] = int(m.get('cash_pot', 0)) + amount
    else:
        m['sb_pot'] = int(m.get('sb_pot', 0)) + amount
    save_state(state)
    sb = int(m.get('sb_pot', 0)); cashp = int(m.get('cash_pot', 0))
    bits = []
    if sb:
        bits.append(f"💎 {sb:,} SB (~${sb // SB_PER_DOLLAR})")
    if cashp:
        bits.append(f"💵 ${cashp} cash")
    e = discord.Embed(title=("🎯 BOUNTY PLACED" if newly else "🎯 BOUNTY STACKED"), color=HUNT_GOLD,
        description=(f"A bounty is on **{team}**'s head — beat them in a logged game to claim it.\n\n"
                    f"**On their head:** {' • '.join(bits)}"))
    if cur == "cash":
        e.set_footer(text="Cash bounty: you settle via Cash App when it's claimed (shows in /bounty ledger).")
    else:
        e.set_footer(text="SB bounty: paid automatically to the winning roster when claimed.")
    await interaction.response.send_message(embed=e)


@bounty_group.command(name="unset", description="[ADMIN] Cancel a team's bounty and refund any paid antes/challenges.")
@app_commands.checks.has_permissions(administrator=True)
@app_commands.autocomplete(team=team_autocomplete)
@app_commands.describe(team="Team whose bounty to cancel")
async def bounty_unset(interaction: discord.Interaction, team: str):
    team = team.strip()
    state = load_state(); h = _hunt(state)
    m = h['marked'].get(team)
    if not m:
        return await interaction.response.send_message(f"❌ **{team}** has no active bounty.", ephemeral=True)
    refunds = []
    for uid, d in m.get('antes', {}).items():
        if d.get('funded') and int(d.get('amount', 0)) > 0:
            refunds.append({'to_uid': uid, 'amount': d['amount'], 'kind': 'ante_refund',
                            'note': f"Bounty on {team} cancelled"})
    for ct, d in m.get('challenges', {}).items():
        if d.get('funded') and int(d.get('amount', 0)) > 0:
            refunds.append({'to_uid': d.get('uid'), 'amount': d['amount'], 'kind': 'challenge_refund',
                            'note': f"Bounty on {team} cancelled"})
    sb = int(m.get('sb_pot', 0)); cashp = int(m.get('cash_pot', 0))
    h['marked'].pop(team, None)
    if refunds:
        _ledger_add(h, refunds)
    save_state(state)
    removed = []
    if sb:
        removed.append(f"💎 {sb:,} SB")
    if cashp:
        removed.append(f"💵 ${cashp}")
    e = discord.Embed(title="🚫 Bounty Cancelled", color=0xFF2D55,
        description=(f"The bounty on **{team}** is off."
                    + (f"\nRemoved pot: {' • '.join(removed)}" if removed else "")
                    + (f"\nRefunding **{len(refunds)}** paid stake(s) — cards below." if refunds else "")))
    await interaction.response.send_message(embed=e)
    if refunds:
        ch = _resolve_pay_channel(interaction.channel)
        for c in refunds:
            emb, view = _payout_card(c)
            await ch.send(embed=emb, view=view)


def _invoice_embed(title, who, amount, note, pay_cmd="/bounty paid"):
    e = discord.Embed(title=title, color=HUNT_GOLD, description=note)
    e.add_field(name="Amount", value=f"**${amount}**", inline=True)
    e.add_field(name="💚 Cash App", value=f"[Tap to pay ${amount}]({_pay_link(amount)})", inline=True)
    e.add_field(name="🍎 Apple Pay", value=f"Send **${amount}** to `{APPLE_PAY_ID}` in the **Messages** app (iPhone).", inline=True)
    e.add_field(name="Then", value=f"Upload your receipt with `{pay_cmd}` to lock it in.", inline=False)
    e.set_footer(text=f"{who} • Cash App {CASHAPP_LINK} • Apple Pay {APPLE_PAY_ID}")
    return e


