def _cup_numbers(h):
    cup = h['cup']; buyin = cup.get('buyin', CUP_BUYIN_DEFAULT); ent = cup.get('entrants', {})
    teams_paid = set(cup.get('teams_paid', []))
    entered_teams = set(e.get('team') for e in ent.values() if e.get('team')) | teams_paid
    paid = len(teams_paid); pool = paid * buyin
    return {"buyin": buyin, "entries": len(entered_teams), "paid": paid, "pool": pool,
            "champion": int(pool * CUP_CHAMPION_PCT), "runner_up": int(pool * CUP_RUNNERUP_PCT)}


