# ════════════════════════════════════════════════════════════════════
#  TEAM REGISTRY (roles), COACH-LINKED CUP PAYMENTS, FINES & SUSPENSIONS
#  /team add|rename|remove  •  /fine issue|pay|clear|board
#  Cup payment by any roster member marks the whole coach roster paid.
#  Fines apply a "Suspended" role; clearing a fine lifts it automatically.
# ════════════════════════════════════════════════════════════════════

def _unpaid_fines(state, uid):
    """All not-yet-paid fines for a user id."""
    return [f for f in state.get('fines', {}).get(str(uid), []) if not f.get('paid')]


def _propagate_cup_team_paid(state, h, uid):
    """Mark a uid's Cup buy-in paid and extend 'paid' to their whole coach roster.
    Returns the resolved team name (or None). Mutates state/h in place; caller saves."""
    uid = str(uid)
    ent = h['cup'].get('entrants', {}).get(uid)
    if not ent:
        return None
    ent['paid'] = True
    team_name = ent.get('team')
    if not team_name:
        return None
    tp = h['cup'].setdefault('teams_paid', [])
    if team_name not in tp:
        tp.append(team_name)
    roster = state.get('coach_rosters', {}).get(team_name, {}).get('players', {})
    for tuid in roster:
        te = h['cup'].setdefault('entrants', {}).setdefault(str(tuid), {'team': team_name, 'paid': False})
        te['team'] = team_name
        te['paid'] = True
    return team_name


async def _get_or_create_suspended_role(guild):
    """Fetch the Suspended role, creating it if missing. May raise discord.Forbidden."""
    role = discord.utils.get(guild.roles, name=SUSPENDED_ROLE_NAME)
    if role is None:
        role = await guild.create_role(
            name=SUSPENDED_ROLE_NAME, colour=discord.Colour.dark_red(),
            mentionable=False, reason="QCL suspension")
    return role


