class AddTeamView(discord.ui.View):
    def __init__(self, name, existing_role_id, author_id):
        super().__init__(timeout=120)
        self.name = name
        self.existing_role_id = existing_role_id
        self.author_id = author_id
        confirm = discord.ui.Button(
            label=("🔗 Link to existing @role" if existing_role_id else "✨ Create role & register"),
            style=discord.ButtonStyle.success)
        confirm.callback = self._confirm
        self.add_item(confirm)
        cancel = discord.ui.Button(label="Cancel", style=discord.ButtonStyle.secondary)
        cancel.callback = self._cancel
        self.add_item(cancel)

    async def _confirm(self, interaction: discord.Interaction):
        if interaction.user.id != self.author_id:
            return await interaction.response.send_message("🚫 Not your command.", ephemeral=True)
        role = interaction.guild.get_role(self.existing_role_id) if self.existing_role_id else None
        created = False
        if role is None:
            try:
                role = await interaction.guild.create_role(
                    name=self.name, mentionable=True, reason="QCL /team add")
                created = True
            except discord.Forbidden:
                return await interaction.response.edit_message(
                    content="⚠️ I can't create roles. Grant **Manage Roles** and move my bot role above the team roles, then run `/team add` again.",
                    embed=None, view=None)
        state = load_state()
        state.setdefault('teams', {})[self.name] = {'role_id': role.id, 'created': _now_str()}
        save_state(state)
        for c in self.children:
            c.disabled = True
        e = discord.Embed(title="✅ Team Registered", colour=0x32D74B,
            description=(f"**{self.name}** is live and {'created with' if created else 'linked to'} role {role.mention}.\n"
                        "It now appears in `/move`, `/coach`, `/cup`, and fine autocomplete."))
        await interaction.response.edit_message(content=None, embed=e, view=self)

    async def _cancel(self, interaction: discord.Interaction):
        if interaction.user.id != self.author_id:
            return await interaction.response.send_message("🚫 Not your command.", ephemeral=True)
        await interaction.response.edit_message(content="🚫 Cancelled.", embed=None, view=None)


class RemoveTeamView(discord.ui.View):
    def __init__(self, name, author_id):
        super().__init__(timeout=60)
        self.name = name
        self.author_id = author_id
        keep = discord.ui.Button(label="Remove (keep role)", style=discord.ButtonStyle.danger)
        keep.callback = self._make(False)
        self.add_item(keep)
        dele = discord.ui.Button(label="Remove + delete role", style=discord.ButtonStyle.danger)
        dele.callback = self._make(True)
        self.add_item(dele)
        cancel = discord.ui.Button(label="Cancel", style=discord.ButtonStyle.secondary)
        cancel.callback = self._cancel
        self.add_item(cancel)

    def _make(self, delete_role):
        async def cb(interaction: discord.Interaction):
            if interaction.user.id != self.author_id:
                return await interaction.response.send_message("🚫 Not your command.", ephemeral=True)
            state = load_state()
            role_id = state.get('teams', {}).get(self.name, {}).get('role_id')
            state.get('teams', {}).pop(self.name, None)
            state.get('coach_rosters', {}).pop(self.name, None)
            state.get('rosters', {}).pop(self.name, None)
            freed = 0
            for d in state.get('users', {}).values():
                if d.get('team') == self.name:
                    d['team'] = 'Free Agent'
                    freed += 1
            save_state(state)
            role_note = ""
            if delete_role:
                role = interaction.guild.get_role(role_id) if role_id else discord.utils.get(interaction.guild.roles, name=self.name)
                if role:
                    try:
                        await role.delete(reason="QCL /team remove")
                        role_note = " Discord role deleted."
                    except discord.Forbidden:
                        role_note = " (Couldn't delete the role — check my permissions.)"
            for c in self.children:
                c.disabled = True
            await interaction.response.edit_message(
                content=f"🗑️ **{self.name}** removed. {freed} player(s) set to Free Agent.{role_note}",
                embed=None, view=self)
        return cb

    async def _cancel(self, interaction: discord.Interaction):
        if interaction.user.id != self.author_id:
            return await interaction.response.send_message("🚫 Not your command.", ephemeral=True)
        await interaction.response.edit_message(content="🚫 Cancelled.", embed=None, view=None)


class FineConfirmView(discord.ui.View):
    def __init__(self, target_uid):
        super().__init__(timeout=86400)
        self.target_uid = str(target_uid)

    @discord.ui.button(label="Confirm & Lift Suspension ✅", style=discord.ButtonStyle.success)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not interaction.user.guild_permissions.administrator:
            return await interaction.response.send_message("🔒 Admins only.", ephemeral=True)
        state = load_state()
        fines = state.get('fines', {}).get(self.target_uid, [])
        cleared = 0
        total = 0
        for fr in fines:
            if not fr.get('paid'):
                fr['paid'] = True
                fr['paid_at'] = _now_str()
                cleared += 1
                total += int(fr.get('amount', 0))
        _paid_d = _rpg_award(state, self.target_uid, heat=-25, reason="Paid off a fine") if cleared else None
        save_state(state)
        note = ""
        if not _unpaid_fines(state, self.target_uid):
            member = interaction.guild.get_member(int(self.target_uid)) if interaction.guild else None
            role = discord.utils.get(interaction.guild.roles, name=SUSPENDED_ROLE_NAME) if interaction.guild else None
            if member and role and role in member.roles:
                try:
                    await member.remove_roles(role, reason="Fine paid")
                    note = " 🟢 Suspension lifted."
                except discord.Forbidden:
                    note = " (Couldn't remove the Suspended role — check my permissions.)"
        for c in self.children:
            c.disabled = True
        await interaction.response.edit_message(view=self)
        if cleared:
            await interaction.channel.send(
                f"✅ **Fine(s) cleared** for <@{self.target_uid}> — ${total} across {cleared}.{note}")
            if _paid_d:
                await _rpg_ping(interaction.channel, self.target_uid, _paid_d,
                                interaction.guild.get_member(int(self.target_uid)) if interaction.guild else None)
        else:
            await interaction.followup.send(
                f"Nothing outstanding for <@{self.target_uid}>.", ephemeral=True)


