@fine_group.command(name="issue", description="[Admin] Fine a player — suspends them until it's paid.")
@app_commands.checks.has_permissions(administrator=True)
@app_commands.describe(member="Player to fine", amount="Fine amount in dollars", reason="What the fine is for")
async def fine_issue(interaction: discord.Interaction, member: discord.Member, amount: int, reason: str):
    if not interaction.guild:
        return await interaction.response.send_message("❌ Use this in a server.", ephemeral=True)
    if amount <= 0:
        return await interaction.response.send_message("❌ Amount must be positive.", ephemeral=True)
    await interaction.response.defer()
    state = load_state()
    rec = {'id': int(time.time() * 1000), 'amount': amount, 'reason': reason,
           'paid': False, 'issued': _now_str(), 'issued_by': interaction.user.display_name}
    state.setdefault('fines', {}).setdefault(str(member.id), []).append(rec)
    _fine_d = _rpg_award(state, member.id, heat=20, rep=-40, reason="Hit with a league fine")
    save_state(state)
    role_note = ""
    try:
        role = await _get_or_create_suspended_role(interaction.guild)
        await member.add_roles(role, reason=f"Fined ${amount}: {reason}")
        role_note = f"🔴 {role.mention} applied."
    except discord.Forbidden:
        role_note = "⚠️ Couldn't apply the Suspended role — grant **Manage Roles** and move my bot role higher."
    ch = _resolve_pay_channel(interaction.channel)
    card = _invoice_embed(f"🚫 FINE — {member.display_name}", member.mention, amount,
                          f"**Reason:** {reason}\nPay to lift your suspension, then run `/fine pay` with your receipt.",
                          pay_cmd="/fine pay")
    await ch.send(content=member.mention, embed=card, view=FineConfirmView(str(member.id)))
    e = discord.Embed(title="🚫 Player Fined & Suspended", colour=0xFF2D55,
        description=(f"{member.mention} fined **${amount}**.\n**Reason:** {reason}\n\n"
                    f"{role_note}\nPay card posted in {ch.mention}. Suspension lifts automatically when it's confirmed."))
    await interaction.followup.send(embed=e)
    await _rpg_ping(interaction.channel, member.id, _fine_d, member)


