# ════════════════════════════════════════════════════════════════════
#  📅 SEASON SCHEDULER — hidden schedule, morning-of reveal (Eastern)
# ════════════════════════════════════════════════════════════════════
#  • Full season schedule is generated up front but NEVER shown to teams.
#    Each day's matchups auto-post at the reveal hour (default 9 AM ET).
#  • Teams can be added/removed ANY time — every day that hasn't been
#    revealed yet is instantly regenerated around the new team list.
#    Days already played/revealed are frozen and never touched.
#  • Every change writes the complete printable schedule to
#    schedule_backup.txt on disk AND DMs it to the bot owner — so the
#    commissioner always holds the whole thing even if the bot dies.
#    (Deliberately kept OUT of the Knowledge Vault so the AI can't leak
#    tomorrow's matchups in chat.)
# ════════════════════════════════════════════════════════════════════

SCHED_BACKUP_TXT = os.path.join(_BASE_DIR, "schedule_backup.txt")
SCHED_DEFAULT_REVEAL_HOUR = int(os.getenv("SCHED_REVEAL_HOUR_ET", "9"))   # 9 AM ET
# Default channel for daily matchup drops (used if the season has none set)
SCHED_DEFAULT_CHANNEL_ID = int(os.getenv("SCHED_CHANNEL_ID", "1522353133160763422"))
# Game of the Night: after each drop, the commissioner gets a DM picker;
# the chosen game gets hyped in this channel.
GOTN_CHANNEL_ID = int(os.getenv("GOTN_CHANNEL_ID", "1520228857603555461"))


_EASTERN_TZ_OK = None


def _us_eastern_offset(utc_dt):
    """DST-aware US Eastern offset without tzdata: EDT (UTC-4) from the
    second Sunday of March 2AM to the first Sunday of November 2AM,
    else EST (UTC-5)."""
    y = utc_dt.year
    mar = _security_datetime.datetime(y, 3, 1)
    dst_start = mar + _security_datetime.timedelta(days=(6 - mar.weekday()) % 7 + 7, hours=7)   # 2AM ET = 7AM UTC (EST)
    nov = _security_datetime.datetime(y, 11, 1)
    dst_end = nov + _security_datetime.timedelta(days=(6 - nov.weekday()) % 7, hours=6)         # 2AM ET = 6AM UTC (EDT)
    return 4 if dst_start <= utc_dt < dst_end else 5


def _eastern_now():
    """League clock = US Eastern. Uses zoneinfo when available; otherwise a
    DST-aware manual offset (so Windows without tzdata still keeps EDT)."""
    global _EASTERN_TZ_OK
    try:
        from zoneinfo import ZoneInfo
        now = _security_datetime.datetime.now(ZoneInfo("America/New_York"))
        if _EASTERN_TZ_OK is not True:
            _EASTERN_TZ_OK = True
        return now
    except Exception:
        if _EASTERN_TZ_OK is not False:
            _EASTERN_TZ_OK = False
            print("[Clock] \u26A0\uFE0F zoneinfo unavailable \u2014 using manual DST-aware Eastern offset. "
                  "Run `pip install tzdata` for exact timekeeping.")
        utc = _security_datetime.datetime.utcnow()
        return utc - _security_datetime.timedelta(hours=_us_eastern_offset(utc))



def _sched(state):
    return state.setdefault('season_schedule', {})


def _sched_day_date(sched, day_idx):
    start = _security_datetime.date.fromisoformat(sched['start_date'])
    return start + _security_datetime.timedelta(days=int(day_idx))


def _sched_today_index(sched):
    """Today's day index on the league (Eastern) clock. Can be negative
    (season hasn't started) or >= days (season over)."""
    start = _security_datetime.date.fromisoformat(sched['start_date'])
    return (_eastern_now().date() - start).days


def _round_robin_rounds(teams):
    """Circle-method round robin. Returns a list of rounds; each round is a
    list of (home, away) pairs. Odd team counts get a rotating bye."""
    ts = [t for t in teams if t]
    if len(ts) < 2:
        return []
    if len(ts) % 2:
        ts.append(None)  # bye slot
    n = len(ts)
    arr = ts[:]
    rounds = []
    for r in range(n - 1):
        pairs = []
        for i in range(n // 2):
            a, b = arr[i], arr[n - 1 - i]
            if a is None or b is None:
                continue
            pairs.append((a, b) if r % 2 == 0 else (b, a))
        rounds.append(pairs)
        arr = [arr[0]] + [arr[-1]] + arr[1:-1]
    return rounds


def _sched_rebuild_point(sched):
    """First day index that is safe to regenerate: never a past day, and
    never today if today's matchups already dropped."""
    idx = _sched_today_index(sched)
    if idx < 0:
        return 0
    revealed = set(sched.get('revealed_days', []))
    return idx + 1 if str(idx) in revealed else idx


def _sched_rebuild_future(sched, force_from=None):
    """Regenerate every unrevealed, non-past day around the current team
    list. Frozen (played/revealed) days are left exactly as they were.
    Makeup weekdays (e.g. Fri/Sat) get NO new matchups and do not consume
    a round-robin round \u2014 they exist to replay missed games.
    force_from=0 rebuilds everything (used on create)."""
    teams = sched.get('teams', [])
    rounds = _round_robin_rounds(teams)
    schedule = sched.setdefault('schedule', {})
    byes = sched.setdefault('byes', {})
    start = _sched_rebuild_point(sched) if force_from is None else int(force_from)
    # Round counter = how many GAME days (non-makeup) exist before `start`
    ord_count = sum(1 for d in range(0, start) if not _sched_is_makeup(sched, d))
    for d in range(start, int(sched.get('days', 0))):
        key = str(d)
        if _sched_is_makeup(sched, d):
            schedule[key] = []
            byes[key] = []
            continue
        if not rounds:
            schedule[key] = []
            byes[key] = []
            ord_count += 1
            continue
        rnd = rounds[ord_count % len(rounds)]
        ord_count += 1
        playing = set()
        games = []
        for h, a in rnd:
            games.append({'home': h, 'away': a})
            playing.update((h, a))
        schedule[key] = games
        byes[key] = [t for t in teams if t not in playing]
    return start


_SCHED_WEEKDAYS = {'mon': 0, 'tue': 1, 'wed': 2, 'thu': 3, 'fri': 4, 'sat': 5, 'sun': 6}


def _sched_parse_makeup(s):
    """'fri,sat' -> [4, 5]. Unknown tokens ignored; 'none' -> []."""
    if not s or s.strip().lower() in ('none', 'off', '-'):
        return []
    out = set()
    for tok in s.split(','):
        wd = _SCHED_WEEKDAYS.get(tok.strip()[:3].lower())
        if wd is not None:
            out.add(wd)
    return sorted(out)


def _sched_is_makeup(sched, day_idx):
    """A day is a makeup day if its weekday is reserved (e.g. fri,sat) OR
    its exact date was flagged (e.g. 2026-07-11,2026-07-12)."""
    d = _sched_day_date(sched, day_idx)
    if d.weekday() in sched.get('makeup_weekdays', []):
        return True
    return d.isoformat() in sched.get('makeup_dates', [])


def _sched_parse_dates(s):
    """'2026-07-11, 2026-07-12' -> validated ISO date list ([] on none/off)."""
    if not s or s.strip().lower() in ('none', 'off', '-'):
        return []
    out = []
    for tok in s.split(','):
        tok = tok.strip()
        if not tok:
            continue
        _security_datetime.date.fromisoformat(tok)   # raises on garbage
        out.append(tok)
    return sorted(set(out))


def _sched_deadline(sched, day_idx):
    """Reveal moment + game window = the play-by deadline (ET)."""
    hour = int(sched.get('reveal_hour', SCHED_DEFAULT_REVEAL_HOUR))
    window = int(sched.get('window_hours', 36))
    reveal_dt = _security_datetime.datetime.combine(
        _sched_day_date(sched, day_idx), _security_datetime.time(hour=hour))
    return reveal_dt + _security_datetime.timedelta(hours=window)


def _schedule_full_text(sched):
    """The whole season, human-readable \u2014 the commissioner's crash backup."""
    now = _eastern_now()
    revealed = set(sched.get('revealed_days', []))
    today_idx = _sched_today_index(sched)
    window = int(sched.get('window_hours', 36))
    mk = sched.get('makeup_weekdays', [])
    mk_names = ", ".join([k.capitalize() for k, v in _SCHED_WEEKDAYS.items() if v in mk]
                         + sched.get('makeup_dates', [])) or "none"
    lines = []
    lines.append("QCL SEASON SCHEDULE \u2014 " + str(sched.get('name', 'Season')))
    lines.append(f"Generated: {now.strftime('%a %m/%d/%Y %I:%M %p')} ET")
    lines.append(f"Teams ({len(sched.get('teams', []))}): " + ", ".join(sched.get('teams', [])))
    lines.append(f"Daily reveal: {sched.get('reveal_hour', SCHED_DEFAULT_REVEAL_HOUR)}:00 ET"
                 + (f" in channel {sched.get('channel_id')}" if sched.get('channel_id') else ""))
    lines.append(f"Game window: {window} hours from reveal | Makeup days: {mk_names}")
    lines.append("=" * 52)
    for d in range(int(sched.get('days', 0))):
        key = str(d)
        date = _sched_day_date(sched, d)
        if d < today_idx:
            tag = "PAST"
        elif key in revealed:
            tag = "REVEALED"
        else:
            tag = "HIDDEN"
        lines.append("")
        if _sched_is_makeup(sched, d):
            lines.append(f"DAY {d + 1} \u2014 {date.strftime('%a %m/%d/%Y')}  [MAKEUP DAY \u00b7 {tag}]")
            lines.append("   (no new matchups \u2014 missed games run back here)")
            continue
        lines.append(f"DAY {d + 1} \u2014 {date.strftime('%a %m/%d/%Y')}  [{tag}]")
        dl = _sched_deadline(sched, d)
        lines.append(f"   window closes {dl.strftime('%a %m/%d %I:%M %p')} ET")
        games = sched.get('schedule', {}).get(key, [])
        if not games:
            lines.append("   (no games \u2014 not enough teams)")
        for g in games:
            lines.append(f"   {g['home']}  vs  {g['away']}")
        for b in sched.get('byes', {}).get(key, []):
            lines.append(f"   BYE: {b}")
    lines.append("")
    lines.append("=" * 52)
    lines.append("Hidden days are subject to regeneration if teams are added/removed.")
    return "\n".join(lines)


def _write_schedule_backup(sched):
    """Write the full printout to disk (NOT the Knowledge Vault — the AI
    must never see unrevealed matchups)."""
    try:
        with open(SCHED_BACKUP_TXT, "w", encoding="utf-8") as f:
            f.write(_schedule_full_text(sched))
    except Exception as e:
        print(f"[Sched] Backup write failed: {e}")


async def _dm_schedule_to_owner(sched, reason=""):
    """DM the complete schedule file to the bot owner after every change."""
    if not BOT_OWNER_ID:
        return
    try:
        import io as _io
        owner = await bot.fetch_user(BOT_OWNER_ID)
        buf = _io.BytesIO(_schedule_full_text(sched).encode("utf-8"))
        fname = f"schedule_{_eastern_now().strftime('%m-%d_%I%M%p')}.txt"
        await owner.send(
            content=f"📅 **Full schedule backup**{(' — ' + reason) if reason else ''} (keep this in case the bot crashes)",
            file=discord.File(buf, filename=fname))
    except Exception as e:
        print(f"[Sched] Owner DM failed: {e}")


def _sched_day_embed(sched, day_idx):
    date = _sched_day_date(sched, day_idx)
    if _sched_is_makeup(sched, day_idx):
        e = discord.Embed(
            title=f"\U0001F6E0\uFE0F MAKEUP DAY \u2014 Day {int(day_idx) + 1}",
            color=discord.Color.orange(),
            description=f"**{date.strftime('%A, %B %d')}** \u2014 no new matchups today.\n"
                        "Any game that slipped its window this week gets **run back today**. "
                        "Coordinate with your opponent and get it in.")
        e.set_footer(text="Win the Cup. Own the Month. Build the Legacy.")
        return e
    games = sched.get('schedule', {}).get(str(day_idx), [])
    e = discord.Embed(
        title=f"\U0001F4C5 TODAY'S MATCHUPS \u2014 Day {int(day_idx) + 1}",
        color=HUNT_GOLD,
        description=f"**{date.strftime('%A, %B %d')}** \u2014 locked in. Handle your business.")
    if games:
        e.add_field(name="\U0001F3C0 Games",
                    value="\n".join(f"**{g['home']}**  vs  **{g['away']}**" for g in games),
                    inline=False)
    else:
        e.add_field(name="\U0001F3C0 Games", value="*No games scheduled today.*", inline=False)
    byes = sched.get('byes', {}).get(str(day_idx), [])
    if byes:
        e.add_field(name="\U0001F634 Bye", value=", ".join(f"**{b}**" for b in byes), inline=False)
    window = int(sched.get('window_hours', 36))
    dl = _sched_deadline(sched, day_idx)
    e.add_field(name="\u23F1\uFE0F Game Window",
                value=f"**{window} hours** \u2014 wrap it up by **{dl.strftime('%A %I:%M %p')} ET**. "
                      "Need the extra day? That's what the window is for. Miss it entirely and "
                      "the game moves to the next **makeup day**.",
                inline=False)
    e.set_footer(text="Win the Cup. Own the Month. Build the Legacy.")
    return e


@tasks.loop(minutes=5)
async def schedule_reveal_loop():
    """Every 5 min: if it's game day and the reveal hour (ET) has hit and
    today hasn't dropped yet — post today's matchups."""
    try:
        state = load_state()
        sched = state.get('season_schedule') or {}
        if sched.get('status') != 'active':
            return
        idx = _sched_today_index(sched)
        if not (0 <= idx < int(sched.get('days', 0))):
            return
        if str(idx) in sched.get('revealed_days', []):
            return
        now = _eastern_now()
        if now.hour < int(sched.get('reveal_hour', SCHED_DEFAULT_REVEAL_HOUR)):
            return
        ch = bot.get_channel(int(sched.get('channel_id') or 0)) or bot.get_channel(SCHED_DEFAULT_CHANNEL_ID)
        if ch is None:
            return
        await ch.send(content="@everyone Today's slate just dropped \U0001F447",
                      embed=_sched_day_embed(sched, idx))
        try:
            await _ask_gotn(sched, idx)
        except Exception as e:
            print(f"[Sched] GOTN ask failed: {e}")
        sched.setdefault('revealed_days', []).append(str(idx))
        save_state(state)
        _write_schedule_backup(sched)
        print(f"[Sched] Revealed day {idx + 1}.")
    except Exception as e:
        print(f"[Sched] Reveal loop error: {e}")


@schedule_reveal_loop.before_loop
async def _sched_wait_ready():
    await bot.wait_until_ready()


@tasks.loop(minutes=10)
async def roster_sweep_loop():
    """Every morning at 9 AM ET: sweep the OFFICIAL Roster & Roles channel
    (and the community channel for reference) and rebuild the snapshot."""
    try:
        now = _eastern_now()
        if now.hour < 9:
            return
        state = load_state()
        today = now.date().isoformat()
        if state.get('last_roster_sweep') == today:
            return
        state['last_roster_sweep'] = today
        save_state(state)
        roster = await build_discord_roster()
        await asyncio.to_thread(write_roster_to_disk, roster)
        src = roster.get('meta', {}).get('roster_source', '?')
        print(f"[Roster] 9AM sweep complete \u2014 source: {src}, "
              f"{len(roster.get('team_pages', {}))} team pages.")
    except Exception as e:
        print(f"[Roster] 9AM sweep failed: {e}")


@roster_sweep_loop.before_loop
async def _roster_sweep_wait_ready():
    await bot.wait_until_ready()


