@awards_group.command(name="open", description="[ADMIN] Open a preset award poll for voting")
@app_commands.describe(award="Which preset award", candidates="Comma-separated candidates (max 25)",
                       duration_hours="Voting window in hours \u2014 default 48",
                       channel="Where the poll posts \u2014 default here", pin="Admin PIN")
@app_commands.choices(award=_AWARD_CHOICES)
async def awards_open(interaction: discord.Interaction, award: app_commands.Choice[str],
                      candidates: str, duration_hours: int = 48,
                      channel: discord.TextChannel = None, pin: str = None):
    if not pin or not await verify_admin_pin(interaction, pin, "awards_open"):
        return
    label, stage, multi, blurb = AWARD_CATALOG[award.value]
    cands = list(dict.fromkeys(c.strip() for c in candidates.split(",") if c.strip()))
    if len(cands) < 2:
        return await interaction.response.send_message("\u274C Need at least 2 candidates.", ephemeral=True)
    trunc = ""
    if len(cands) > 25:
        cands = cands[:25]
        trunc = " (\u26A0\uFE0F truncated to the first 25 \u2014 Discord menu limit)"
    if multi > len(cands):
        return await interaction.response.send_message(
            f"\u274C **{label}** needs {multi} picks \u2014 give me at least {multi} candidates.", ephemeral=True)
    if not (1 <= duration_hours <= 336):
        return await interaction.response.send_message("\u274C duration_hours must be 1-336.", ephemeral=True)

    state = load_state()
    polls = _awards_state(state)
    for p in polls.values():
        if p.get('award') == award.value and p.get('status') == 'open':
            return await interaction.response.send_message(
                f"\u274C **{label}** already has an open poll \u2014 close it first.", ephemeral=True)

    ch = channel or interaction.channel
    pid = f"{award.value}_{int(_eastern_now().timestamp())}"
    poll = {'award': award.value, 'label': label, 'stage': stage, 'multi': multi, 'blurb': blurb,
            'candidates': cands, 'votes': {}, 'status': 'open', 'channel_id': ch.id,
            'opened_at': _eastern_now().isoformat(),
            'closes_at': (_eastern_now() + _security_datetime.timedelta(hours=duration_hours)).isoformat()}
    polls[pid] = poll
    msg = await ch.send(content=f"@everyone \U0001F5F3\uFE0F **{label}** voting is OPEN!",
                        embed=_award_poll_embed(poll), view=AwardVoteView(pid, poll))
    poll['message_id'] = str(msg.id)
    save_state(state)
    await interaction.response.send_message(
        f"\u2705 **{label}** is live in {ch.mention} \u2014 closes in **{duration_hours}h**. "
        f"{len(cands)} candidates{trunc}. The watcher will auto-close it and post results.",
        ephemeral=True)


@awards_group.command(name="status", description="Live tallies for every open award poll")
async def awards_status(interaction: discord.Interaction):
    polls = _awards_state(load_state())
    open_polls = {k: v for k, v in polls.items() if v.get('status') == 'open'}
    if not open_polls:
        return await interaction.response.send_message("\U0001F5F3\uFE0F No polls open right now.", ephemeral=True)
    e = discord.Embed(title="\U0001F440 POLL WATCHER \u2014 live tallies", color=discord.Color.blurple())
    for pid, p in list(open_polls.items())[:10]:
        tally = _award_tally(p)
        top = "\n".join(f"`{ct}` {cand}" for cand, ct in tally[:5]) or "*no votes yet*"
        try:
            closes = _security_datetime.datetime.fromisoformat(p['closes_at']).strftime("%a %I:%M %p ET")
        except Exception:
            closes = "?"
        e.add_field(name=f"{p['label']} \u2014 {len(p.get('votes', {}))} ballot(s), closes {closes}",
                    value=top, inline=False)
    await interaction.response.send_message(embed=e)


@awards_group.command(name="close", description="[ADMIN] Close an award poll now and post results")
@app_commands.describe(award="Which award's open poll to close", pin="Admin PIN")
@app_commands.choices(award=_AWARD_CHOICES)
async def awards_close(interaction: discord.Interaction, award: app_commands.Choice[str], pin: str):
    if not await verify_admin_pin(interaction, pin, "awards_close"):
        return
    state = load_state()
    polls = _awards_state(state)
    target = None
    for pid, p in polls.items():
        if p.get('award') == award.value and p.get('status') == 'open':
            target = p
            break
    if target is None:
        return await interaction.response.send_message(
            f"\u274C No open poll for **{AWARD_CATALOG[award.value][0]}**.", ephemeral=True)
    target['status'] = 'closed'
    save_state(state)
    ch = bot.get_channel(int(target.get('channel_id') or 0)) or interaction.channel
    await ch.send(content=f"\U0001F514 **{target['label']}** voting is CLOSED \u2014 results:",
                  embed=_award_poll_embed(target, closed=True))
    await interaction.response.send_message("\u2705 Closed and announced.", ephemeral=True)




# ════════════════════════════════════════════════════════════════════
#  🧬 QCL FANTASY LEAGUE — pool · big board · draft · auction · scoring
# ════════════════════════════════════════════════════════════════════
#  Season-1 valuation: no fantasy history needed. Ratings come from the
#  full SPAM/QCL stat archive — fantasy points per game, recency-weighted
#  (current season x1.5, older seasons decay x0.85/yr), regressed by games
#  played so small samples don't inflate. Tiers S/A/B/C + R (rookie, no
#  data, baseline value). Suggested auction $ derive from rating share.
# ════════════════════════════════════════════════════════════════════

FANTASY_FP = {'PTS': 1.0, 'REB': 1.2, 'AST': 1.5, 'STL': 3.0, 'BLK': 3.0, 'TO': -1.0}
FANTASY_LOT_SECONDS = 120        # auction lot clock
FANTASY_BID_EXTEND = 45          # every bid guarantees at least this much clock


def _fantasy(state):
    return state.setdefault('fantasy', {'status': 'setup'})


def _fan_fp_series(df):
    fp = None
    for col, w in FANTASY_FP.items():
        part = df[col] * w
        fp = part if fp is None else fp + part
    return fp


def _fantasy_ratings():
    """{player: {'rating', 'gp', 'fppg'}} from the whole stat archive.
    Recency-weighted, then Bayesian-shrunk toward the league mean with
    K=6 phantom games so a 2-game heater can't top a 40-game vet."""
    if _cached_df is None or _cached_df.empty:
        return {}
    df = _cached_df[_cached_df['Type'].astype(str).str.lower() == 'player'].copy()
    if df.empty:
        return {}
    df['FP'] = _fan_fp_series(df)
    cur = int(pd.to_numeric(df['Season'], errors='coerce').fillna(0).max())
    agg = {}
    for (player, season), grp in df.groupby(['Player/Team', 'Season']):
        s = int(pd.to_numeric(pd.Series([season]), errors='coerce').fillna(0).iloc[0])
        g = int(grp['Game_ID'].nunique()) or len(grp)
        fppg = float(grp['FP'].sum()) / max(g, 1)
        w = 1.5 if s == cur else (0.85 ** max(cur - s, 1))
        rec = agg.setdefault(str(player), {'num': 0.0, 'den': 0.0, 'gp': 0})
        rec['num'] += w * fppg * g
        rec['den'] += w * g
        rec['gp'] += g
    raws = {p: (r['num'] / r['den'] if r['den'] else 0.0) for p, r in agg.items()}
    tot_g = sum(r['gp'] for r in agg.values()) or 1
    league_mean = sum(raws[p] * agg[p]['gp'] for p in raws) / tot_g
    K = 6.0
    ratings = {}
    for p, r in agg.items():
        shrunk = (raws[p] * r['gp'] + league_mean * K) / (r['gp'] + K)
        ratings[p] = {'rating': round(shrunk, 2), 'fppg': round(raws[p], 2), 'gp': r['gp']}
    return ratings



def _fantasy_board(fan):
    """Ordered big board over the current pool+taken: [(player, rating,
    tier, suggested $, gp)]. No-data players = R tier at baseline."""
    if fan.get('even'):
        # Season-1 even playing field: every player identical on the board.
        pool = sorted(set(list(fan.get('pool', [])) + list(fan.get('taken', {}).keys())))
        budget_pool = int(fan.get('budget', 200)) * max(len(fan.get('managers', {})), 6)
        flat = max(1, round(budget_pool * 0.85 / max(len(pool), 1)))
        return [{'player': p, 'rating': 50.0, 'tier': 'EV', 'value': flat, 'gp': 0} for p in pool]
    ratings = _fantasy_ratings()
    pool = list(fan.get('pool', [])) + list(fan.get('taken', {}).keys())
    known = sorted((ratings[p]['rating'] for p in pool if p in ratings), reverse=True)
    baseline = known[int(len(known) * 0.65)] if known else 10.0   # ~35th percentile
    rows = []
    for p in pool:
        r = ratings.get(p)
        rows.append((p, r['rating'] if r else baseline, r['gp'] if r else 0, r is None))
    rows.sort(key=lambda x: (-x[1], x[0]))
    n = len(rows)
    budget_pool = int(fan.get('budget', 200)) * max(len(fan.get('managers', {})), 6)
    power = sum(x[1] ** 1.6 for x in rows) or 1.0
    board = []
    for i, (p, rating, gp, rookie) in enumerate(rows):
        if rookie:
            tier = 'R'
        elif i < max(1, n // 10):
            tier = 'S'
        elif i < max(2, int(n * 0.30)):
            tier = 'A'
        elif i < max(3, int(n * 0.60)):
            tier = 'B'
        else:
            tier = 'C'
        # Proof gates: small samples can't claim top tiers in season 1
        if tier == 'S' and gp < 8:
            tier = 'A'
        if tier == 'A' and gp < 5:
            tier = 'B'
        cap = max(1, int(int(fan.get('budget', 200)) * 0.6))
        dollars = min(cap, max(1, round(budget_pool * 0.85 * (rating ** 1.6) / power)))
        board.append({'player': p, 'rating': rating, 'tier': tier, 'value': dollars, 'gp': gp})
    return board


def _fan_find(fan, name, pool_only=True):
    """Fuzzy-match a player in the pool (or anywhere) via normalized names."""
    key = _normalize_for_match(name)
    space = fan.get('pool', []) if pool_only else list(fan.get('pool', [])) + list(fan.get('taken', {}).keys())
    exact = [p for p in space if _normalize_for_match(p) == key]
    if exact:
        return exact[0]
    part = [p for p in space if key and key in _normalize_for_match(p)]
    return part[0] if len(part) == 1 else None


def _fan_max_bid(fan, uid):
    m = fan['managers'][uid]
    slots_left = int(fan.get('roster_size', 5)) - len(m['players'])
    return int(fan.get('budget', 200)) - int(m.get('spent', 0)) - max(0, slots_left - 1)


def _fan_all_full(fan):
    rs = int(fan.get('roster_size', 5))
    return fan['managers'] and all(len(m['players']) >= rs for m in fan['managers'].values())


def _fan_on_clock(fan):
    order = fan.get('order', [])
    if not order:
        return None
    if fan['status'] == 'draft':
        i = fan.get('pick_index', 0)
        rnd, pos = divmod(i, len(order))
        return order[pos] if rnd % 2 == 0 else order[len(order) - 1 - pos]   # snake
    return order[fan.get('pick_index', 0) % len(order)]                      # auction rotation


def _fan_advance(fan):
    """Move the clock to the next manager who still has roster space."""
    for _ in range(len(fan.get('order', [])) * int(fan.get('roster_size', 5)) + 1):
        fan['pick_index'] = fan.get('pick_index', 0) + 1
        uid = _fan_on_clock(fan)
        if uid is None:
            return None
        if len(fan['managers'][uid]['players']) < int(fan.get('roster_size', 5)):
            return uid
    return None


def _fan_assign(fan, uid, player, price=0):
    fan['pool'].remove(player)
    fan.setdefault('taken', {})[player] = uid
    m = fan['managers'][uid]
    m['players'].append(player)
    m['spent'] = int(m.get('spent', 0)) + int(price)


def _fan_tier_of(fan, player):
    for row in _fantasy_board(fan):
        if row['player'] == player:
            return row
    return {'tier': '?', 'rating': 0, 'value': 0, 'gp': 0}


def _fan_clock_embed(fan):
    if fan.get('status') == 'active':
        e = discord.Embed(title="\U0001F9EC FANTASY ROSTERS LOCKED", color=HUNT_GOLD,
                          description="Every squad is full. Scoring is LIVE \u2014 `/fantasy scores` any time.")
        return e
    uid = _fan_on_clock(fan)
    name = fan['managers'].get(uid, {}).get('name', '?') if uid else '?'
    if fan['status'] == 'draft':
        i = fan.get('pick_index', 0)
        rnd = i // max(len(fan.get('order', [1])), 1) + 1
        e = discord.Embed(title=f"\U0001F3AF ON THE CLOCK \u2014 Round {rnd}",
                          color=discord.Color.blue(),
                          description=f"**{name}**, you're up. `/fantasy pick player:<name>`")
    else:
        e = discord.Embed(title="\U0001F528 AUCTION \u2014 NOMINATION",
                          color=discord.Color.blue(),
                          description=f"**{name}** nominates next. `/fantasy nominate player:<name> bid:<$>`")
    top = [r for r in _fantasy_board(fan) if r['player'] in fan.get('pool', [])][:8]
    if top:
        e.add_field(name="\U0001F4CB Best available",
                    value="\n".join(f"`{r['tier']}` **{r['player']}** \u2014 {r['rating']} rtg \u00b7 ~${r['value']}"
                                     for r in top), inline=False)
    return e


@tasks.loop(seconds=20)
async def fantasy_lot_loop():
    """Auction watcher: hammer down any lot past its clock."""
    try:
        state = load_state()
        fan = _fantasy(state)
        lot = fan.get('lot')
        if fan.get('status') != 'auction' or not lot:
            return
        closes = _security_datetime.datetime.fromisoformat(lot['closes_at'])
        if _eastern_now() < closes:
            return
        ch = bot.get_channel(int(fan.get('channel_id') or 0))
        player = lot['player']
        if lot.get('high_bidder'):
            uid = lot['high_bidder']
            price = int(lot['high_bid'])
            _fan_assign(fan, uid, player, price)
            row = _fan_tier_of(fan, player)
            msg = (f"\U0001F528 **SOLD!** `{row['tier']}`-tier **{player}** to "
                   f"**{fan['managers'][uid]['name']}** for **${price}** (board value ~${row['value']}).")
        else:
            msg = f"\U0001F528 No bids \u2014 **{player}** returns to the pool."
        fan['lot'] = None
        if _fan_all_full(fan):
            fan['status'] = 'active'
        else:
            _fan_advance(fan)
        save_state(state)
        if ch:
            await ch.send(content=msg, embed=_fan_clock_embed(fan))
    except Exception as e:
        print(f"[Fantasy] Lot loop error: {e}")


@fantasy_lot_loop.before_loop
async def _fan_wait_ready():
    await bot.wait_until_ready()


