@fantasy_group.command(name="setup", description="[ADMIN] Configure the fantasy league")
@app_commands.describe(mode="draft = snake draft \u00b7 auction = live bidding", roster_size="Players per squad (default 5)",
                       budget="Auction budget per manager (default $200)",
                       even="Season-1 even playing field: everyone rated equal (default ON)", pin="Admin PIN")
@app_commands.choices(mode=[app_commands.Choice(name="Snake Draft", value="draft"),
                            app_commands.Choice(name="Auction", value="auction")])
async def fantasy_setup(interaction: discord.Interaction, mode: app_commands.Choice[str],
                        roster_size: int = 5, budget: int = 200, even: bool = True, pin: str = None):
    if not pin or not await verify_admin_pin(interaction, pin, "fantasy_setup"):
        return
    if not (1 <= roster_size <= 10) or not (10 <= budget <= 10000):
        return await interaction.response.send_message("\u274C roster_size 1-10, budget 10-10000.", ephemeral=True)
    state = load_state()
    state['fantasy'] = {'status': 'setup', 'mode': mode.value, 'roster_size': roster_size,
                        'budget': budget, 'even': bool(even), 'managers': {}, 'order': [], 'pick_index': 0,
                        'pool': [], 'taken': {}, 'lot': None, 'channel_id': interaction.channel_id}
    save_state(state)
    await interaction.response.send_message(
        f"\u2705 Fantasy league configured: **{mode.name}**, {roster_size}-player squads"
        + (f", ${budget} budgets" if mode.value == 'auction' else "")
        + (" \u00b7 \u2696\uFE0F **even playing field ON** \u2014 everyone starts rated equal" if even else "")
        + ". Managers register with `/fantasy register`, then `/fantasy pool`, then `/fantasy start`.")


