@fantasy_group.command(name="pool", description="[ADMIN] Set the active player pool")
@app_commands.describe(players="Comma-separated player names, or 'auto' to pull every active rostered/current-season player",
                       pin="Admin PIN")
async def fantasy_pool(interaction: discord.Interaction, players: str, pin: str):
    if not await verify_admin_pin(interaction, pin, "fantasy_pool"):
        return
    state = load_state()
    fan = _fantasy(state)
    if fan.get('status') not in ('setup',):
        return await interaction.response.send_message("\u274C Pool locks once the league starts.", ephemeral=True)
    names = []
    _pool_src = "manual list"
    if players.strip().lower() == 'auto':
        # OFFICIAL Roster & Roles channel is the ONLY source of truth.
        cid = _official_roster_channel_id(state)
        try:
            pages = await parse_roster_channel(state, channel_id=cid or None)
            guild = interaction.guild
            for page in pages.values():
                for entry in page.get('combined', []):
                    mem = guild.get_member(int(entry['uid'])) if guild else None
                    if mem is not None and not mem.bot:
                        names.append(mem.display_name)
            _pool_src = (f"OFFICIAL roster channel \u2014 {len(pages)} teams" if cid
                         else f"community roster channel \u2014 {len(pages)} teams")
        except Exception as e:
            print(f"[Fantasy] pool pull: {e}")
        if not cid and not names:
            # Last resort only when no official channel is set: current-season stat names
            try:
                if _cached_df is not None and not _cached_df.empty:
                    d = _cached_df[_cached_df['Type'].astype(str).str.lower() == 'player']
                    cur = int(pd.to_numeric(d['Season'], errors='coerce').fillna(0).max())
                    names.extend(d[d['Season'] == cur]['Player/Team'].astype(str).unique().tolist())
                    _pool_src = "current-season stat sheet (no roster channels readable)"
            except Exception as e:
                print(f"[Fantasy] stat pool fallback: {e}")
    else:
        names = [p.strip() for p in players.split(',') if p.strip()]
    pool = sorted(dict.fromkeys(names))
    if len(pool) < 2:
        return await interaction.response.send_message("\u274C Pool needs at least 2 players.", ephemeral=True)
    fan['pool'] = pool
    fan['taken'] = {}
    save_state(state)
    await interaction.response.send_message(
        f"\u2705 Player pool set: **{len(pool)}** active players \u2014 source: {_pool_src}. "
        f"`/fantasy board` for the rankings.")


@fantasy_group.command(name="board", description="The big board \u2014 compact rankings by tier")
async def fantasy_board_cmd(interaction: discord.Interaction):
    fan = _fantasy(load_state())
    if not fan.get('pool') and not fan.get('taken'):
        return await interaction.response.send_message("\u274C No pool yet \u2014 `/fantasy pool` first.", ephemeral=True)
    board = _fantasy_board(fan)
    taken = fan.get('taken', {})
    if fan.get('even'):
        avail = [r['player'] for r in board if r['player'] not in taken]
        gone = [(r['player'], fan['managers'].get(taken.get(r['player']), {}).get('name', '?'))
                for r in board if r['player'] in taken]
        e = discord.Embed(title=f"\U0001F9EC BIG BOARD \u2014 EVEN FIELD \u00b7 {len(board)} PLAYERS",
                          color=HUNT_GOLD,
                          description="Season 1: everyone starts equal. No tiers, no history \u2014 "
                                      "reputations get made on the court.")
        third = max(1, -(-len(avail) // 3))
        cols = [avail[k:k + third] for k in range(0, len(avail), third)][:3]
        for n, chunk in enumerate(cols, 1):
            e.add_field(name=f"Available ({len(avail)})" if n == 1 else "\u200b",
                        value="\n".join(chunk) or "\u2014", inline=True)
        if gone:
            e.add_field(name=f"\U0001F512 Taken ({len(gone)})",
                        value="\n".join(f"{p} \u2192 {m}" for p, m in gone[:20]), inline=False)
        return await interaction.response.send_message(embed=e)
    e = discord.Embed(title="\U0001F9EC FANTASY BIG BOARD", color=HUNT_GOLD,
                      description="Rating = fantasy pts/game, recency-weighted + shrunk. "
                                  "`R` = rookie/no data.")
    tiers = {}
    for r in board:
        tiers.setdefault(r['tier'], []).append(r)
    for tier in ("S", "A", "B", "C", "R", "EV"):
        rows = tiers.get(tier)
        if not rows:
            continue
        bits = []
        for r in rows[:20]:
            tag = " \U0001F512" if taken.get(r['player']) else ""
            bits.append(f"**{r['player']}** {r['rating']} \u00b7 ~${r['value']}{tag}")
        e.add_field(name=f"`{tier}` tier ({len(rows)})", value="  \u00b7  ".join(bits), inline=False)
    await interaction.response.send_message(embed=e)



@fantasy_group.command(name="start", description="[ADMIN] Lock managers and start the draft/auction")
@app_commands.describe(pin="Admin PIN")
async def fantasy_start(interaction: discord.Interaction, pin: str):
    if not await verify_admin_pin(interaction, pin, "fantasy_start"):
        return
    state = load_state()
    fan = _fantasy(state)
    if fan.get('status') != 'setup':
        return await interaction.response.send_message("\u274C Already started.", ephemeral=True)
    if len(fan.get('managers', {})) < 2:
        return await interaction.response.send_message("\u274C Need at least 2 managers.", ephemeral=True)
    need = len(fan['managers']) * int(fan.get('roster_size', 5))
    if len(fan.get('pool', [])) < need:
        return await interaction.response.send_message(
            f"\u274C Pool too small: {len(fan.get('pool', []))} players for {need} roster slots.", ephemeral=True)
    order = list(fan['managers'].keys())
    random.shuffle(order)
    fan['order'] = order
    fan['pick_index'] = 0
    fan['status'] = fan.get('mode', 'draft')
    fan['channel_id'] = interaction.channel_id
    save_state(state)
    names = " \u2192 ".join(fan['managers'][u]['name'] for u in order)
    await interaction.response.send_message(
        content=f"\U0001F9EC **FANTASY {fan['status'].upper()} IS LIVE!** Order: {names}",
        embed=_fan_clock_embed(fan))


@fantasy_group.command(name="pick", description="Draft: make your pick when you're on the clock")
@app_commands.describe(player="Player name (fuzzy match against the pool)")
async def fantasy_pick(interaction: discord.Interaction, player: str):
    state = load_state()
    fan = _fantasy(state)
    if fan.get('status') != 'draft':
        return await interaction.response.send_message("\u274C No draft in progress.", ephemeral=True)
    uid = str(interaction.user.id)
    on = _fan_on_clock(fan)
    is_admin = getattr(interaction.user.guild_permissions, "administrator", False)
    if uid != on and not is_admin:
        return await interaction.response.send_message(
            f"\u23F3 Not your pick \u2014 **{fan['managers'][on]['name']}** is on the clock.", ephemeral=True)
    target = on if is_admin and uid != on else uid
    p = _fan_find(fan, player)
    if p is None:
        return await interaction.response.send_message(
            f"\u274C Can't find an available player matching **{player}**.", ephemeral=True)
    row = _fan_tier_of(fan, p)
    _fan_assign(fan, target, p)
    if _fan_all_full(fan):
        fan['status'] = 'active'
    else:
        _fan_advance(fan)
    save_state(state)
    await interaction.response.send_message(
        content=f"\U0001F3AF **{fan['managers'][target]['name']}** selects `{row['tier']}`-tier **{p}** "
                f"({row['rating']} rtg, {row['gp']} gp).",
        embed=_fan_clock_embed(fan))


@fantasy_group.command(name="nominate", description="Auction: nominate a player (when you're up)")
@app_commands.describe(player="Player to put on the block", bid="Your opening bid ($1 minimum)")
async def fantasy_nominate(interaction: discord.Interaction, player: str, bid: int = 1):
    state = load_state()
    fan = _fantasy(state)
    if fan.get('status') != 'auction':
        return await interaction.response.send_message("\u274C No auction in progress.", ephemeral=True)
    if fan.get('lot'):
        return await interaction.response.send_message("\u274C A lot is already on the block \u2014 `/fantasy bid`.", ephemeral=True)
    uid = str(interaction.user.id)
    on = _fan_on_clock(fan)
    is_admin = getattr(interaction.user.guild_permissions, "administrator", False)
    if uid != on and not is_admin:
        return await interaction.response.send_message(
            f"\u23F3 **{fan['managers'][on]['name']}** nominates next.", ephemeral=True)
    nominator = uid if uid in fan['managers'] else on
    p = _fan_find(fan, player)
    if p is None:
        return await interaction.response.send_message(f"\u274C No available player matching **{player}**.", ephemeral=True)
    if bid < 1 or bid > _fan_max_bid(fan, nominator):
        return await interaction.response.send_message(
            f"\u274C Bid must be $1\u2013${_fan_max_bid(fan, nominator)} for you.", ephemeral=True)
    closes = _eastern_now() + _security_datetime.timedelta(seconds=FANTASY_LOT_SECONDS)
    fan['lot'] = {'player': p, 'high_bid': int(bid), 'high_bidder': nominator,
                  'closes_at': closes.isoformat()}
    save_state(state)
    row = _fan_tier_of(fan, p)
    await interaction.response.send_message(
        f"\U0001F528 **ON THE BLOCK:** `{row['tier']}`-tier **{p}** (board ~${row['value']}) \u2014 "
        f"opening bid **${bid}** by **{fan['managers'][nominator]['name']}**. "
        f"\u23F1\uFE0F {FANTASY_LOT_SECONDS}s clock \u2014 `/fantasy bid amount:<$>`")


@fantasy_group.command(name="bid", description="Auction: raise the bid on the current lot")
@app_commands.describe(amount="Your bid in dollars")
async def fantasy_bid(interaction: discord.Interaction, amount: int):
    state = load_state()
    fan = _fantasy(state)
    lot = fan.get('lot')
    if fan.get('status') != 'auction' or not lot:
        return await interaction.response.send_message("\u274C Nothing on the block.", ephemeral=True)
    uid = str(interaction.user.id)
    if uid not in fan['managers']:
        return await interaction.response.send_message("\u274C Managers only.", ephemeral=True)
    if len(fan['managers'][uid]['players']) >= int(fan.get('roster_size', 5)):
        return await interaction.response.send_message("\u274C Your squad is full.", ephemeral=True)
    if amount <= int(lot['high_bid']):
        return await interaction.response.send_message(f"\u274C Beat ${lot['high_bid']} or sit down.", ephemeral=True)
    if amount > _fan_max_bid(fan, uid):
        return await interaction.response.send_message(
            f"\u274C Your max is **${_fan_max_bid(fan, uid)}** (must keep $1 per open slot).", ephemeral=True)
    lot['high_bid'] = int(amount)
    lot['high_bidder'] = uid
    closes = _security_datetime.datetime.fromisoformat(lot['closes_at'])
    floor = _eastern_now() + _security_datetime.timedelta(seconds=FANTASY_BID_EXTEND)
    if closes < floor:
        lot['closes_at'] = floor.isoformat()
    save_state(state)
    await interaction.response.send_message(
        f"\U0001F4B0 **${amount}** \u2014 **{fan['managers'][uid]['name']}** leads on **{lot['player']}**.")


