@fantasy_group.command(name="scores", description="Fantasy standings \u2014 season fantasy points per squad")
async def fantasy_scores(interaction: discord.Interaction):
    fan = _fantasy(load_state())
    if not fan.get('managers') or not fan.get('taken'):
        return await interaction.response.send_message("\u274C No rosters to score yet.", ephemeral=True)
    if _cached_df is None or _cached_df.empty:
        return await interaction.response.send_message("\u274C Stat sheet not loaded yet \u2014 try again shortly.", ephemeral=True)
    d = _cached_df[_cached_df['Type'].astype(str).str.lower() == 'player'].copy()
    cur = int(pd.to_numeric(d['Season'], errors='coerce').fillna(0).max())
    d = d[d['Season'] == cur].copy()
    d['FP'] = _fan_fp_series(d)
    totals = d.groupby('Player/Team')['FP'].sum()
    rows = []
    for uid, m in fan['managers'].items():
        pts = sum(float(totals.get(p, 0.0)) for p in m['players'])
        best = max(m['players'], key=lambda p: float(totals.get(p, 0.0)), default=None)
        rows.append((m['name'], pts, best, float(totals.get(best, 0.0)) if best else 0.0))
    rows.sort(key=lambda r: -r[1])
    medals = ["\U0001F947", "\U0001F948", "\U0001F949"]
    e = discord.Embed(title=f"\U0001F9EC FANTASY STANDINGS \u2014 Season {cur}", color=HUNT_GOLD,
                      description="Fantasy points: PTS +1.2 REB +1.5 AST +3 STL +3 BLK \u22121 TO")
    lines = []
    for i, (name, pts, best, bp) in enumerate(rows):
        pre = medals[i] if i < 3 else f"`{i + 1}.`"
        lines.append(f"{pre} **{name}** \u2014 **{pts:.1f}** FP" + (f" (top: {best}, {bp:.1f})" if best else ""))
    e.add_field(name="Standings", value="\n".join(lines), inline=False)
    await interaction.response.send_message(embed=e)


# ── FANTASY CONTESTS: daily + weekly pick'em ─────────────────────────
#  Anyone (not just league managers) enters a lineup. Scoring counts only
#  box scores pushed AFTER the contest opened (Game_ID snapshot), so it
#  needs no dates. Daily = 24h window. Weekly = 7 days, and weekly is
#  LOCKED until the season is 2 days old.

def _fan_contests(fan):
    return fan.setdefault('contests', {})


def _fan_gid_floor():
    """Max Game_ID currently on the sheet — new games score above this."""
    try:
        if _cached_df is None or _cached_df.empty:
            return 0
        d = _cached_df[_cached_df['Type'].astype(str).str.lower() == 'player']
        cur = int(pd.to_numeric(d['Season'], errors='coerce').fillna(0).max())
        return int(pd.to_numeric(d[d['Season'] == cur]['Game_ID'], errors='coerce').fillna(0).max())
    except Exception:
        return 0


def _fan_contest_scores(con):
    """{uid: total FP} for a contest, from games newer than its snapshot."""
    if _cached_df is None or _cached_df.empty:
        return {}
    d = _cached_df[_cached_df['Type'].astype(str).str.lower() == 'player'].copy()
    cur = int(pd.to_numeric(d['Season'], errors='coerce').fillna(0).max())
    d = d[(d['Season'] == cur) & (pd.to_numeric(d['Game_ID'], errors='coerce').fillna(0) > int(con.get('gid_floor', 0)))]
    if d.empty:
        return {u: 0.0 for u in con.get('entries', {})}
    d['FP'] = _fan_fp_series(d)
    totals = d.groupby('Player/Team')['FP'].sum()
    return {uid: round(sum(float(totals.get(p, 0.0)) for p in picks), 1)
            for uid, picks in con.get('entries', {}).items()}


CONTEST_KINDS = {'daily': (24, 3), 'weekly': (168, 5)}   # hours, default picks


@tasks.loop(minutes=5)
async def fantasy_contest_loop():
    """Auto-close contests at their deadline and crown the winner."""
    try:
        state = load_state()
        fan = _fantasy(state)
        cons = _fan_contests(fan)
        dirty = False
        for key, con in cons.items():
            if con.get('status') != 'open':
                continue
            try:
                closes = _security_datetime.datetime.fromisoformat(con['closes_at'])
            except Exception:
                continue
            if _eastern_now() < closes:
                continue
            con['status'] = 'closed'
            con['final'] = _fan_contest_scores(con)
            dirty = True
            ch = bot.get_channel(int(fan.get('channel_id') or 0))
            if ch:
                board = sorted(con['final'].items(), key=lambda kv: -kv[1])
                e = discord.Embed(title=f"\U0001F3C1 {key.upper()} CONTEST \u2014 FINAL", color=HUNT_GOLD)
                medals = ["\U0001F947", "\U0001F948", "\U0001F949"]
                lines = []
                for i, (uid, pts) in enumerate(board[:10]):
                    nm = con.get('names', {}).get(uid, f"<@{uid}>")
                    lines.append(f"{medals[i] if i < 3 else f'`{i+1}.`'} **{nm}** \u2014 {pts} FP")
                e.add_field(name="Results", value="\n".join(lines) or "*No entries.*", inline=False)
                if board:
                    wname = con.get('names', {}).get(board[0][0], f"<@{board[0][0]}>")
                    e.description = f"\U0001F451 **{wname}** takes the {key} crown!"
                await ch.send(embed=e)
            print(f"[Fantasy] Closed {key} contest.")
        if dirty:
            save_state(state)
    except Exception as e:
        print(f"[Fantasy] Contest loop error: {e}")


@fantasy_contest_loop.before_loop
async def _fan_contest_wait_ready():
    await bot.wait_until_ready()


@fantasy_group.command(name="contest", description="[ADMIN] Open a daily or weekly fantasy contest")
@app_commands.describe(kind="daily = 24h \u00b7 weekly = 7 days (unlocks after day 2 of the season)",
                       picks="Lineup size \u2014 default 3 daily / 5 weekly", pin="Admin PIN")
@app_commands.choices(kind=[app_commands.Choice(name="Daily (24h)", value="daily"),
                            app_commands.Choice(name="Weekly (7 days)", value="weekly")])
async def fantasy_contest(interaction: discord.Interaction, kind: app_commands.Choice[str],
                          picks: int = 0, pin: str = None):
    if not pin or not await verify_admin_pin(interaction, pin, "fantasy_contest"):
        return
    state = load_state()
    fan = _fantasy(state)
    if not fan.get('pool') and not fan.get('taken'):
        return await interaction.response.send_message("\u274C Set the player pool first \u2014 `/fantasy pool`.", ephemeral=True)
    sched = state.get('season_schedule') or {}
    idx = _sched_today_index(sched) if sched.get('status') == 'active' else None
    if idx is None or idx < 0:
        return await interaction.response.send_message(
            "\u274C Contests open once the season has started.", ephemeral=True)
    if kind.value == 'weekly' and idx < 2:
        d0 = _sched_day_date(sched, 2)
        return await interaction.response.send_message(
            f"\U0001F512 Weekly contests unlock after the first 2 days of the season \u2014 "
            f"available **{d0.strftime('%A %m/%d')}**.", ephemeral=True)
    cons = _fan_contests(fan)
    if cons.get(kind.value, {}).get('status') == 'open':
        return await interaction.response.send_message(f"\u274C A {kind.value} contest is already open.", ephemeral=True)
    hours, default_picks = CONTEST_KINDS[kind.value]
    n = picks or default_picks
    if not (1 <= n <= 10):
        return await interaction.response.send_message("\u274C picks must be 1-10.", ephemeral=True)
    closes = _eastern_now() + _security_datetime.timedelta(hours=hours)
    cons[kind.value] = {'status': 'open', 'picks': n, 'gid_floor': _fan_gid_floor(),
                        'opened_at': _eastern_now().isoformat(), 'closes_at': closes.isoformat(),
                        'entries': {}, 'names': {}}
    fan.setdefault('channel_id', interaction.channel_id)
    save_state(state)
    await interaction.response.send_message(
        f"@everyone \U0001F3AF **{kind.value.upper()} FANTASY CONTEST IS OPEN!**\n"
        f"Pick **{n}** players with `/fantasy lineup kind:{kind.value} players:name1,name2,...` \u2014 "
        f"anyone can enter, edit until close.\n"
        f"\u23F0 Closes **{closes.strftime('%A %I:%M %p ET')}**. Only games played after this moment count. "
        f"Highest total fantasy points takes the crown.")


@fantasy_group.command(name="lineup", description="Enter or update your lineup in an open contest")
@app_commands.describe(kind="Which contest", players="Comma-separated player names (fuzzy match)")
@app_commands.choices(kind=[app_commands.Choice(name="Daily", value="daily"),
                            app_commands.Choice(name="Weekly", value="weekly")])
async def fantasy_lineup(interaction: discord.Interaction, kind: app_commands.Choice[str], players: str):
    state = load_state()
    fan = _fantasy(state)
    con = _fan_contests(fan).get(kind.value)
    if not con or con.get('status') != 'open':
        return await interaction.response.send_message(f"\u274C No open {kind.value} contest.", ephemeral=True)
    names = [p.strip() for p in players.split(',') if p.strip()]
    matched, missing = [], []
    for nm in names:
        m = _fan_find(fan, nm, pool_only=False)
        (matched if m else missing).append(m or nm)
    matched = list(dict.fromkeys(matched))
    if missing:
        return await interaction.response.send_message(
            "\u274C Couldn't match: " + ", ".join(f"**{m}**" for m in missing), ephemeral=True)
    if len(matched) != int(con['picks']):
        return await interaction.response.send_message(
            f"\u274C This contest needs exactly **{con['picks']}** unique players (you gave {len(matched)}).",
            ephemeral=True)
    uid = str(interaction.user.id)
    con['entries'][uid] = matched
    con.setdefault('names', {})[uid] = interaction.user.display_name
    save_state(state)
    await interaction.response.send_message(
        "\u2705 Lineup locked: " + ", ".join(f"**{p}**" for p in matched)
        + f" \u2014 {len(con['entries'])} entr{'ies' if len(con['entries']) != 1 else 'y'} in. "
          "You can edit until close.", ephemeral=True)


@fantasy_group.command(name="live", description="Live leaderboard for open contests")
async def fantasy_live(interaction: discord.Interaction):
    fan = _fantasy(load_state())
    cons = {k: v for k, v in _fan_contests(fan).items() if v.get('status') == 'open'}
    if not cons:
        return await interaction.response.send_message("\U0001F3AF No contests open right now.", ephemeral=True)
    e = discord.Embed(title="\U0001F3AF LIVE CONTESTS", color=discord.Color.blurple())
    for key, con in cons.items():
        scores = _fan_contest_scores(con)
        board = sorted(scores.items(), key=lambda kv: -kv[1])[:8]
        try:
            closes = _security_datetime.datetime.fromisoformat(con['closes_at']).strftime("%a %I:%M %p ET")
        except Exception:
            closes = "?"
        lines = [f"`{pts:>6.1f}` {con.get('names', {}).get(uid, uid)}" for uid, pts in board] or ["*no entries yet*"]
        e.add_field(name=f"{key.capitalize()} \u2014 {len(con.get('entries', {}))} entries, closes {closes}",
                    value="\n".join(lines), inline=False)
    await interaction.response.send_message(embed=e)


