# ═══════════════════════════════════════════════════════════════════════════
#  .resetseason  —  standalone PREFIX command (no slash sync, can't be cached)
#
#  PASTE: at the very END of QCL2K.py.
#
#  Usage in Discord:  .resetseason
#  Then the bot displays an interactive View with a multi-selector.
#  Select any additional roles you want to KEEP, then click Confirm.
#
#  WHAT IT DOES
#   1. Archives every data file first (timestamped, restorable).
#   2. Prints an END-OF-SEASON REPORT (champions, stats, pot).
#   3. Folds champions into the record (titles.json).
#   4. Deletes ALL roles EXCEPT ones whose name contains "champion" or "top 50",
#      (plus @everyone, bot roles, roles above the bot, and your SELECTIONS).
#   5. Soft-resets: coins/cards/PINs survive; season + rankings reset.
# ═══════════════════════════════════════════════════════════════════════════

import shutil as _rss_shutil
import datetime as _rss_dt
import discord

# Role names containing ANY of these (case-insensitive) are ALWAYS kept.
_RSS_KEEP_SUBSTR = ["champion", "top 50", "top50"]
_RSS_ARCHIVE_DIR = _tvt_os.path.join(TVT_DATA_DIR, "archives")

def _rss_stamp():
    return _rss_dt.datetime.now().strftime("%Y%m%d_%H%M%S")

def _rss_archive():
    dest = _tvt_os.path.join(_RSS_ARCHIVE_DIR, f"{_rss_stamp()}_resetseason")
    _tvt_os.makedirs(dest, exist_ok=True)
    copied = []
    for root, _dirs, files in _tvt_os.walk(TVT_DATA_DIR):
        if "archives" in root:
            continue
        for fn in files:
            if fn.endswith(".json"):
                rel = _tvt_os.path.relpath(_tvt_os.path.join(root, fn), TVT_DATA_DIR)
                out = _tvt_os.path.join(dest, rel)
                _tvt_os.makedirs(_tvt_os.path.dirname(out), exist_ok=True)
                try:
                    _rss_shutil.copy2(_tvt_os.path.join(root, fn), out)
                    copied.append(rel)
                except Exception as e:
                    print(f"[resetseason] archive {rel}: {e}")
    return dest, copied

def _rss_report(save):
    s = save.get("season", {"num": "?", "roster": {}})
    roster = s.get("roster", {})
    board = sorted(({"player": k, "score": v.get("score", 0)} for k, v in roster.items()),
                   key=lambda x: -x["score"])
    for i, r in enumerate(board):
        r["rank"] = i + 1
    econ = save.get("economy", {})
    mkt = save.get("market", {})
    return {"season": s.get("num"), "players": len(roster), "champions": board[:3],
            "moments": len(mkt.get("moments", {})),
            "trades": sum(len(v) for v in mkt.get("trades", {}).values()),
            "pot": econ.get("pot", {}).get("coins", 0),
            "treasury": econ.get("treasury", 0)}

def _rss_fold_lore(save, report):
    path = _tvt_os.path.join(TVT_DATA_DIR, "titles.json")
    titles = {}
    if _tvt_os.path.exists(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                titles = _tvt_json.load(f) or {}
        except Exception:
            titles = {}
    for i, c in enumerate(report.get("champions", [])):
        p = c.get("player")
        if not p:
            continue
        rec = dict(titles.get(p, {}))
        if i == 0:
            rec["championship"] = int(rec.get("championship", 0)) + 1
        key = ("all_league_1st", "all_league_2nd", "all_league_3rd")[i]
        rec[key] = int(rec.get(key, 0)) + 1
        titles[p] = rec
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        _tvt_json.dump(titles, f, indent=2, ensure_ascii=False)
    _tvt_os.replace(tmp, path)
    try:
        _LGD_CACHE["t"] = 0.0
    except Exception:
        pass

def _rss_soft_reset(save):
    cleared = []
    for k in ("season", "prices"):
        if k in save:
            save.pop(k, None)
            cleared.append(k)
    tpath = _tvt_os.path.join(TVT_DATA_DIR, "tuning.json")
    if _tvt_os.path.exists(tpath):
        try:
            _tvt_os.remove(tpath)
            cleared.append("tuning.json")
        except Exception:
            pass
    return cleared

def _rss_role_kept(role):
    n = role.name.lower()
    return any(sub in n for sub in _RSS_KEEP_SUBSTR)

async def _rss_wipe_roles(guild, extra_keep_ids=None):
    extra_keep_ids = extra_keep_ids or set()
    deleted, kept, failed = [], [], []
    me = guild.me
    for role in list(guild.roles):
        if role.is_default() or role.managed or role >= me.top_role:
            kept.append(role.name)
            continue
        # Keep if it matches substring OR was manually selected in the UI
        if _rss_role_kept(role) or role.id in extra_keep_ids:
            kept.append(role.name)
            continue
        try:
            await role.delete(reason="resetseason")
            deleted.append(role.name)
        except Exception as e:
            failed.append(f"{role.name} ({type(e).__name__})")
    return deleted, kept, failed

def _rss_is_admin(ctx):
    """Owner or server-admin. Prefix commands use ctx, not interaction."""
    try:
        if ctx.guild and ctx.author.id == ctx.guild.owner_id:
            return True
        return ctx.author.guild_permissions.administrator
    except Exception:
        return False


class ResetSeasonView(discord.ui.View):
    def __init__(self, ctx, save, report):
        super().__init__(timeout=300)
        self.ctx = ctx
        self.save = save
        self.report = report
        self.extra_keep_roles = set()

    @discord.ui.select(
        cls=discord.ui.RoleSelect,
        placeholder="Select any extra roles to KEEP...",
        min_values=0,
        max_values=25,
        row=0
    )
    async def select_roles(self, interaction: discord.Interaction, select: discord.ui.RoleSelect):
        if interaction.user.id != self.ctx.author.id:
            return await interaction.response.send_message("Only the command author can use this.", ephemeral=True)
        self.extra_keep_roles = {r.id for r in select.values}
        await interaction.response.defer()

    @discord.ui.button(label="Confirm & Execute Reset", style=discord.ButtonStyle.danger, row=1)
    async def confirm_reset(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.ctx.author.id:
            return await interaction.response.send_message("Only the command author can confirm this.", ephemeral=True)
        
        # Disable the view so it can't be clicked again
        for child in self.children:
            child.disabled = True
        await interaction.response.edit_message(content="**\u23f3 Executing End of Season Reset...**", view=self)
        
        # Execute Reset Logic
        arch, copied = _rss_archive()
        _rss_fold_lore(self.save, self.report)
        cleared = _rss_soft_reset(self.save)
        _tvt_write_save(self.save)
        deleted, kept, failed = await _rss_wipe_roles(self.ctx.guild, self.extra_keep_roles)
        
        try:
            global _tvt_market_dirty
            _tvt_market_dirty = True
        except Exception:
            pass

        champs = "\n".join(f"\U0001f3c5 #{i+1} **{c['player']}** — {c['score']:.1f}"
                           for i, c in enumerate(self.report["champions"])) or "(none)"
        out = (
            f"**\U0001f3c1 Season {self.report['season']} closed — reset complete**\n\n"
            f"{champs}\n\n"
            f"\U0001f4be Archived {len(copied)} files to `{_tvt_os.path.basename(arch)}` "
            f"(nothing lost)\n"
            f"\U0001f5d1\ufe0f Roles deleted: **{len(deleted)}**  \u00b7  "
            f"\U0001f512 kept: **{len(kept)}**\n"
            f"\u267b\ufe0f Reset: {', '.join(cleared) or 'season state'}\n"
            f"\U0001f4b0 Kept: coins, cards, PINs, all lore\n"
            + (f"\u26a0\ufe0f Couldn't delete: {', '.join(failed[:6])}\n" if failed else "")
            + "\nStart the next season with `/qtcg season start`.")
        
        await interaction.followup.send(out[:1990])
        self.stop()


@bot.command(name="resetseason")
async def resetseason(ctx):
    if not ctx.guild:
        return await ctx.send("Run this in your server, not a DM.")
    if not _rss_is_admin(ctx):
        return await ctx.send("\U0001f512 Only the server owner or an admin can reset the season.")

    me = ctx.guild.me
    to_delete, to_keep = [], []
    for r in ctx.guild.roles:
        if r.is_default() or r.managed or r >= me.top_role:
            continue
        (to_keep if _rss_role_kept(r) else to_delete).append(r.name)
    
    save = _tvt_load_save()
    rep = _rss_report(save)
    champs = "\n".join(f"\U0001f3c5 #{i+1} {c['player']} — {c['score']:.1f}"
                       for i, c in enumerate(rep["champions"])) or "(no ranked players)"
    
    msg = (
        "**\u26a0\ufe0f END OF SEASON — Review before confirming**\n\n"
        f"__Season {rep['season']} champions__\n{champs}\n\n"
        f"__Roles Automatically KEPT__ ({len(to_keep)}): "
        + (", ".join(to_keep) if to_keep else "none matched 'champion' or 'top 50'") + "\n\n"
        f"__Roles Pending DELETION__ ({len(to_delete)}): "
        + (", ".join(to_delete[:30]) + (" …" if len(to_delete) > 30 else "")
           if to_delete else "none") + "\n\n"
        "__Kept:__ coins, cards, PINs, all lore. __Reset:__ season, rankings.\n"
        "Everything is archived first — nothing is lost.\n\n"
        "**Use the selector below to choose ANY ADDITIONAL ROLES you want to KEEP, then click Confirm.**")
    
    view = ResetSeasonView(ctx, save, rep)
    await ctx.send(msg[:1990], view=view)


