# ── resolve the helpers we need, whatever they're named in your file ───────
def _addon_data_dir():
    for name in ("TVT_DATA_DIR", "FANTASY_DIR", "DATA_DIR"):
        if name in globals():
            return globals()[name]
    d = _addon_os.path.join(_addon_os.path.dirname(_addon_os.path.abspath(__file__)),
                            "fantasy_data")
    _addon_os.makedirs(d, exist_ok=True)
    return d


_ADDON_DIR = _addon_data_dir()
_REG_PATH = _addon_os.path.join(_ADDON_DIR, "registrations.json")


def _reg_load():
    if _addon_os.path.exists(_REG_PATH):
        try:
            with open(_REG_PATH, "r", encoding="utf-8") as f:
                return _addon_json.load(f) or {}
        except Exception:
            pass
    return {}


def _reg_save(d):
    tmp = _REG_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        _addon_json.dump(d, f, indent=2, ensure_ascii=False)
    _addon_os.replace(tmp, _REG_PATH)


def _reg_publish():
    """Push registrations to the Hub repo if the GitHub pipe exists."""
    try:
        if "_tvt_gh_put_json" in globals() and globals().get("TVT_GH_TOKEN"):
            import asyncio as _a
            _a.get_event_loop().create_task(
                _tvt_gh_put_json("registrations.json", _reg_load(),
                                 "QCL: registrations update"))
    except Exception as e:
        print(f"[addon reg] publish skipped: {e}")


