# ═══════════════════════════════════════════════════════════════════════════
#  PUBLISH PLAYER STATS  →  player_stats.json in the repo
#
#  PASTE: BEFORE bot.run(TOKEN) in QCL2K.py.
#
#  Computes real per-player stats from the SAME dataframe the bot uses
#  (load_data) and writes player_stats.json to the repo. The pull-server /
#  Activity then reads it so cards show REAL, LOCKED PPG/REB/AST/FP.
#
#  Run once (and after new games) with:  !publishstats
#  Stats are keyed by the player's canonical name so they lock to that player.
# ═══════════════════════════════════════════════════════════════════════════

import json as _ps_json


def _ps_compute_all():
    """Return {player_name: {ppg,rpg,apg,spg,bpg,fp,gp}} from the sheet df.
    load_data() returns (p_df, t_df); p_df is already player-only with the
    name column renamed to 'PlayerName'."""
    try:
        p_df, _t_df = load_data()
    except Exception as e:
        print(f"[publishstats] load_data failed: {e}")
        return {}
    if p_df is None or len(p_df) == 0:
        return {}
    # find the name column (renamed to PlayerName in load_data, but be tolerant)
    name_col = None
    for c in ("PlayerName", "Player/Team", "Player", "Name"):
        if c in p_df.columns:
            name_col = c
            break
    if not name_col:
        print(f"[publishstats] no name column in {list(p_df.columns)[:8]}")
        return {}
    out = {}
    try:
        for name, g in p_df.groupby(name_col):
            def avg(col):
                try:
                    return round(float(g[col].mean()), 1) if col in g.columns and len(g) else 0.0
                except Exception:
                    return 0.0
            out[str(name)] = {
                "ppg": avg("PTS"), "rpg": avg("REB"), "apg": avg("AST"),
                "spg": avg("STL"), "bpg": avg("BLK"), "fp": avg("FP"),
                "gp": int(len(g)),
            }
    except Exception as e:
        print(f"[publishstats] groupby failed ({name_col}): {e}")
    return out


@bot.command(name="publishstats")
async def _ps_publish(ctx):
    try:
        admin = (ctx.guild and (ctx.author.id == ctx.guild.owner_id
                 or ctx.author.guild_permissions.administrator))
    except Exception:
        admin = False
    if not admin:
        return await ctx.send("🔒 Owner/admin only.")
    await ctx.send("📊 Computing player stats…")
    stats = _ps_compute_all()
    if not stats:
        return await ctx.send("⚠️ No stats computed (sheet not loaded?).")
    # publish to the repo via the bot's existing GitHub pipe
    try:
        ok = False
        if "_tvt_gh_put_json" in globals():
            await _tvt_gh_put_json("player_stats.json", stats,
                                   f"stats: {len(stats)} players")
            ok = True
        if ok:
            await ctx.send(f"✅ Published **{len(stats)}** players' stats to "
                           f"`player_stats.json`. Cards now show real numbers.")
        else:
            await ctx.send("⚠️ GitHub publish helper not found.")
    except Exception as e:
        await ctx.send(f"❌ Publish failed: `{type(e).__name__}: {e}`")


# ══════════════════════════════════════════════════════════════════════
#  !sweepboxscores  — channel sweeper -> parse -> DM editor -> push -> ✅
#  --------------------------------------------------------------------
#  Sweeps a channel for box-score images that have NOT yet been approved,
#  parses each one with the SAME dual-extraction engine as /submit_boxscore,
#  and DMs YOU an interactive editor so the channel never floods.
#
#  Markers on the ORIGINAL image message:
#     👀  = queued to your DMs, awaiting your review  (skipped on re-sweep)
#     ✅  = approved + pushed to the sheet             (skipped on re-sweep)
#
#  Re-running the command only picks up messages that have NEITHER marker,
#  so it is safe to run over and over.
#
#  INSERT ANYWHERE before the `# --- START THE BOT ---` line.
#  Relies on globals already defined above: claude_client, ai_client,
#  draw_extracted_table, safe_int, admin_pin_matches, APPS_SCRIPT_URL.
# ══════════════════════════════════════════════════════════════════════

_SWEEP_DONE   = "\u2705"   # ✅ approved + pushed
_SWEEP_QUEUED = "\U0001F440"  # 👀 sitting in your DMs
_SWEEP_IMG_EXT = (".png", ".jpg", ".jpeg", ".webp", ".gif")


def _sweep_is_admin(ctx):
    """Owner or server-admin. Mirrors _rss_is_admin / publishstats gating."""
    try:
        if ctx.guild and ctx.author.id == ctx.guild.owner_id:
            return True
        return ctx.author.guild_permissions.administrator
    except Exception:
        return False


def _sweep_msg_has_my_reaction(message, emoji):
    """True if THIS bot has already put `emoji` on the message."""
    for r in message.reactions:
        try:
            if str(r.emoji) == emoji and r.me:
                return True
        except Exception:
            pass
    return False


def _sweep_first_image(message):
    """Return the first image attachment on a message, or None."""
    for a in message.attachments:
        ct = (getattr(a, "content_type", None) or "").lower()
        fn = (a.filename or "").lower()
        if ct.startswith("image") or fn.endswith(_SWEEP_IMG_EXT):
            return a
    return None


async def _sweep_parse_image(img_bytes):
    """
    Blind parse (no roster context) — extract team names AS SHOWN.
    Returns (parsed_data:list, source_name:str) or raises on total failure.
    Reuses the exact schema /submit_boxscore produces so the table drawer
    and the sheet-push logic work unchanged.
    """
    image = PIL.Image.open(BytesIO(img_bytes))

    prompt = """You are a sports stat extraction specialist. Extract the COMPLETE box score from this NBA 2K Pro-Am image.

MANDATORY STRUCTURE — every 2K Pro-Am game has EXACTLY:
  • 5 players on Team 1 (top block) + 1 TOTAL row for Team 1
  • 5 players on Team 2 (bottom block) + 1 TOTAL row for Team 2
  = 12 rows total. NEVER more, NEVER fewer. If you see fewer than 5 player
  rows for a team you are MISSING ROWS — scroll your eyes top-to-bottom.
  Yellow-highlighted, faded, and bottom rows are all valid.

TEAM NAMES: This is a blind sweep — no roster is provided. Read each team's
name EXACTLY as printed on the scoreboard / team headers in the image and put
it in every row's "Team Name" field. The top block is Team 1, the bottom
block is Team 2. Extract player gamertags exactly as written.

QUARTER SCOREBOARD: The left/top panel shows Q1|Q2|Q3|Q4 per team. Put those
numbers ONLY on each team's TOTAL row (a dash "-" = 0). On every PLAYER row set
Q1=Q2=Q3=Q4=0. The four quarters on a TOTAL row must sum to that team's PTS.

VALIDATION BEFORE RETURNING:
  1. Exactly 5 player rows per team.
  2. Sum of the 5 players' PTS must equal that team's TOTAL PTS. Same for
     REB, OREB, DREB, AST, STL, BLK, TO, FGM, FGA, 3PM, 3PA, FTM, FTA, MIN.

EXTRA STATS if visible (else 0, never guess): MIN, OREB, DREB (OREB+DREB=REB).

OUTPUT: Return ONLY a valid JSON array. No prose, no markdown fences.
Each object MUST have these exact keys:
"Player/Team", "Team Name", "Type", "GRD", "MIN",
"PTS", "REB", "OREB", "DREB", "AST", "STL", "BLK", "FOULS", "TO",
"FGM", "FGA", "3PM", "3PA", "FTM", "FTA", "Q1", "Q2", "Q3", "Q4"
"Type" is "Player" or "Total". Order: Team 1's 5 players, Team 1 Total,
then Team 2's 5 players, Team 2 Total."""

    png_buf = BytesIO()
    image.save(png_buf, format="PNG")
    b64_image = base64.standard_b64encode(png_buf.getvalue()).decode("utf-8")

    def _extract_json(text):
        cleaned = text.replace("```json", "").replace("```", "").strip()
        start = cleaned.find("[")
        end = cleaned.rfind("]")
        if start >= 0 and end > start:
            cleaned = cleaned[start:end + 1]
        return json.loads(cleaned)

    def _score(data):
        """Lower = better. Penalizes wrong player counts + sum mismatches."""
        if not isinstance(data, list) or not data:
            return 999
        issues = 0
        teams = {}
        for r in data:
            teams.setdefault(str(r.get("Team Name", "")).strip().lower(), []).append(r)
        for rows in teams.values():
            players = [r for r in rows if str(r.get("Type", "")).strip().lower() == "player"]
            totals = [r for r in rows if str(r.get("Type", "")).strip().lower() == "total"]
            if len(players) != 5:
                issues += abs(5 - len(players)) * 10
            if totals and players:
                for stat in ["PTS", "REB", "AST", "STL", "BLK", "TO", "FGM", "FGA", "3PM", "3PA", "FTM", "FTA"]:
                    try:
                        ps = sum(int(r.get(stat, 0) or 0) for r in players)
                        tv = int(totals[0].get(stat, 0) or 0)
                        if ps != tv:
                            issues += 1
                    except Exception:
                        pass
        return issues

    def _fetch_gemini():
        return ai_client.models.generate_content(model="gemini-2.5-pro", contents=[prompt, image])

    def _fetch_claude():
        return claude_client.messages.create(
            model="claude-opus-4-7", max_tokens=4000,
            messages=[{"role": "user", "content": [
                {"type": "image", "source": {"type": "base64", "media_type": "image/png", "data": b64_image}},
                {"type": "text", "text": prompt}]}])

    gemini_task = asyncio.to_thread(_fetch_gemini) if ai_client else None
    claude_task = asyncio.to_thread(_fetch_claude) if claude_client else None

    gemini_data = claude_data = None
    if gemini_task:
        try:
            gemini_data = _extract_json((await gemini_task).text)
        except Exception as ge:
            print(f"[Sweep] Gemini failed: {ge}")
    if claude_task:
        try:
            claude_data = _extract_json((await claude_task).content[0].text)
        except Exception as ce:
            print(f"[Sweep] Claude failed: {ce}")

    candidates = []
    if gemini_data:
        candidates.append(("Gemini 2.5 Pro", gemini_data, _score(gemini_data)))
    if claude_data:
        candidates.append(("Claude Opus 4.7", claude_data, _score(claude_data)))
    if not candidates:
        raise ValueError("Both AI models failed to extract any data from the image.")
    candidates.sort(key=lambda x: x[2])
    return candidates[0][1], candidates[0][0]


class SweepInfoModal(discord.ui.Modal, title="Set Season & Game ID"):
    season_in = discord.ui.TextInput(label="Season #", placeholder="e.g. 1", max_length=4)
    gameid_in = discord.ui.TextInput(label="Game ID", placeholder="Regs 101-999 · Event 8001-8999 · Offs 9001-9999", max_length=6)

    def __init__(self, parent_view):
        super().__init__()
        self.parent_view = parent_view

    async def on_submit(self, interaction: discord.Interaction):
        try:
            self.parent_view.season = int(str(self.season_in.value).strip())
            self.parent_view.game_id = int(str(self.gameid_in.value).strip())
        except ValueError:
            return await interaction.response.send_message("❌ Season and Game ID must be numbers.", ephemeral=True)
        await interaction.response.send_message(
            f"✅ Set to **S{self.parent_view.season} · ID {self.parent_view.game_id}**.", ephemeral=True)
        await self.parent_view._refresh(interaction.message)


