class SweepPushModal(discord.ui.Modal, title="Admin PIN to Push"):
    pin = discord.ui.TextInput(label="Enter Admin PIN", min_length=4, max_length=4)

    def __init__(self, parent_view):
        super().__init__()
        self.parent_view = parent_view

    async def on_submit(self, interaction: discord.Interaction):
        pv = self.parent_view
        if not admin_pin_matches(self.pin.value):
            return await interaction.response.send_message("❌ Invalid PIN. Push cancelled.", ephemeral=True)
        await interaction.response.send_message("🔐 PIN accepted. Pushing to Google Sheets...", ephemeral=True)

        rows_to_push = []
        for r in pv.data:
            team_name = str(r.get("Team Name", pv.your_team or "Unknown"))
            is_winner = bool(pv.your_team) and team_name.lower() == pv.your_team.lower()
            row_win_val = int(pv.win_val) if is_winner else (1 - int(pv.win_val))
            rows_to_push.append([
                str(r.get("Player/Team", "Unknown")), str(r.get("Type", "Player")), str(r.get("GRD", "N/A")),
                int(safe_int(r.get("PTS", 0))), int(safe_int(r.get("REB", 0))), int(safe_int(r.get("AST", 0))),
                int(safe_int(r.get("STL", 0))), int(safe_int(r.get("BLK", 0))), int(safe_int(r.get("FOULS", 0))),
                int(safe_int(r.get("TO", 0))), int(safe_int(r.get("FGM", 0))), int(safe_int(r.get("FGA", 0))),
                int(safe_int(r.get("3PM", 0))), int(safe_int(r.get("3PA", 0))), int(safe_int(r.get("FTM", 0))),
                int(safe_int(r.get("FTA", 0))), int(pv.game_id), team_name, row_win_val, int(pv.season),
                int(safe_int(r.get("OREB", 0))), int(safe_int(r.get("DREB", 0))), int(safe_int(r.get("MIN", 0))),
                int(safe_int(r.get("Q1", 0))), int(safe_int(r.get("Q2", 0))), int(safe_int(r.get("Q3", 0))),
                int(safe_int(r.get("Q4", 0))),
            ])

        payload = {"secret": "SPAM_BOT_SECRET_123", "sheet": "Raw Data",
                   "action": "append_multiple", "data": rows_to_push}
        try:
            def _post():
                return requests.post(APPS_SCRIPT_URL, data=json.dumps(payload),
                                     headers={"Content-Type": "application/json"}, allow_redirects=True)
            resp = await asyncio.to_thread(_post)
            head = resp.text[:300].lstrip().lower()
            if head.startswith("<!doctype") or "<html" in head:
                return await interaction.followup.send("❌ Apps Script URL is dead (Google returned an HTML 404). "
                                                       "Redeploy the web app and update APPS_SCRIPT_URL.")
            if resp.status_code == 200 and "Error" not in resp.text:
                # Flip the marker on the ORIGINAL channel image: 👀 -> ✅
                try:
                    if pv.source_message:
                        await pv.source_message.add_reaction(_SWEEP_DONE)
                        try:
                            await pv.source_message.remove_reaction(_SWEEP_QUEUED, interaction.client.user)
                        except Exception:
                            pass
                except Exception as re_:
                    print(f"[Sweep] could not mark source message: {re_}")
                for c in pv.children:
                    c.disabled = True
                try:
                    await interaction.message.edit(view=pv)
                except Exception:
                    pass
                pv.stop()
                await interaction.followup.send(
                    f"✅ Pushed **S{pv.season} · ID {pv.game_id}** to the sheet. "
                    f"Marked the original image with ✅.")
            else:
                await interaction.followup.send(f"⚠️ AppScript error:\n```{str(resp.text)[:900]}```")
        except Exception as e:
            await interaction.followup.send(f"❌ Push failed:\n```{str(e)[:900]}```")


class SweepBoxView(discord.ui.View):
    """DM-side interactive editor. Compatible with the existing
    PlayerSelect / StatSelect / EditSpecificStatModal editor machinery."""
    def __init__(self, data, team_names, image_url, source_message, source_name):
        super().__init__(timeout=None)
        self.data = data
        self.team_names = team_names
        self.image_url = image_url
        self.source_message = source_message
        self.source_name = source_name
        # metadata the user fills in from the DM
        self.your_team = None
        self.win_val = 1
        self.season = "?"
        self.game_type = "Regular"
        self.game_id = "?"
        # required by EditSpecificStatModal
        self.selected_player = None
        self.selected_stat = None
        # editor selects (rows 0/1) reuse the exact classes from /submit_boxscore
        self.add_item(PlayerSelect(self.data))
        self.add_item(StatSelect())
        # sweep-specific selects (rows 2/3)
        self.add_item(SweepWinnerSelect(team_names))
        self.add_item(SweepGameTypeSelect())

    async def _refresh(self, message):
        """Redraw the parsed table image after any edit / info change."""
        try:
            buf = draw_extracted_table(self.data, f"Swept: S{self.season} {self.game_type} (ID: {self.game_id})")
            img_file = discord.File(buf, filename="parsed_box.png")
            embed = self._embed()
            await message.edit(embed=embed, attachments=[img_file], view=self)
        except Exception as e:
            print(f"[Sweep] refresh failed: {e}")

    def _embed(self):
        winner = self.your_team or "— not set —"
        e = discord.Embed(
            title="📸 Swept Box Score — Review & Push",
            description=(f"From **#{getattr(self.source_message.channel, 'name', 'channel')}** "
                         f"(posted by {self.source_name}).\n\n"
                         f"**Winner:** {winner}\n**Season/ID:** S{self.season} · {self.game_id} · {self.game_type}\n\n"
                         "1. Fix any stats with the two dropdowns + **Apply Edit**.\n"
                         "2. Pick the **winning team** + **game type**, then **Set Season & ID**.\n"
                         "3. **Approve & Push** — the original image gets a ✅."),
            color=0x00A2FF)
        e.set_image(url="attachment://parsed_box.png")
        return e

    @discord.ui.button(label="Apply Edit", style=discord.ButtonStyle.primary, row=4)
    async def apply_edit(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not self.selected_player or not self.selected_stat:
            return await interaction.response.send_message("❌ Pick a player and a stat first.", ephemeral=True)
        await interaction.response.send_modal(EditSpecificStatModal(self))

    @discord.ui.button(label="Set Season & ID", style=discord.ButtonStyle.secondary, row=4)
    async def set_info(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(SweepInfoModal(self))

    @discord.ui.button(label="Approve & Push", style=discord.ButtonStyle.success, row=4)
    async def approve(self, interaction: discord.Interaction, button: discord.ui.Button):
        missing = []
        if not self.your_team:
            missing.append("winning team")
        if not isinstance(self.season, int):
            missing.append("season")
        if not isinstance(self.game_id, int):
            missing.append("game ID")
        if missing:
            return await interaction.response.send_message(
                f"❌ Set the {', '.join(missing)} first (use the dropdowns + **Set Season & ID**).", ephemeral=True)
        await interaction.response.send_modal(SweepPushModal(self))


async def _do_sweep(author, channel, limit):
    # Core sweep: scan a channel for unhandled box-score images, parse each,
    # and DM the author an interactive editor. Returns a small status dict.
    limit = max(1, min(int(limit), 300))
    try:
        dm = author.dm_channel or await author.create_dm()
        probe = await dm.send(f"🧹 Sweeping **#{channel.name}** (last {limit} messages)… I will send each box score here.")
    except Exception:
        return {"ok": False, "reason": "nodm"}

    scanned = queued = 0
    async for msg in channel.history(limit=limit, oldest_first=True):
        if msg.author.bot:
            continue
        img = _sweep_first_image(msg)
        if not img:
            continue
        scanned += 1
        if _sweep_msg_has_my_reaction(msg, _SWEEP_DONE) or _sweep_msg_has_my_reaction(msg, _SWEEP_QUEUED):
            continue
        try:
            img_bytes = await img.read()
            data, source_name = await _sweep_parse_image(img_bytes)
        except Exception as e:
            print(f"[Sweep] parse failed on msg {msg.id}: {e}")
            continue
        team_names, seen = [], set()
        for r in data:
            tn = str(r.get("Team Name", "")).strip()
            if tn and tn.lower() not in seen:
                seen.add(tn.lower())
                team_names.append(tn)
        team_names = team_names[:2]
        view = SweepBoxView(data, team_names, msg.jump_url, msg, msg.author.display_name)
        try:
            buf = draw_extracted_table(data, f"Swept: S? {view.game_type} (ID: ?)")
            img_file = discord.File(buf, filename="parsed_box.png")
            await dm.send(embed=view._embed(), file=img_file, view=view)
            await msg.add_reaction(_SWEEP_QUEUED)
            queued += 1
            await asyncio.sleep(1.0)
        except Exception as e:
            print(f"[Sweep] DM/send failed on msg {msg.id}: {e}")
    try:
        await probe.edit(content=f"🧹 Sweep complete — **{queued}** new box score(s) queued to your DMs "
                                 f"out of **{scanned}** image message(s) scanned in #{channel.name}. "
                                 f"Approve each below; the original gets a ✅ when it lands in the sheet.")
    except Exception:
        pass
    return {"ok": True, "scanned": scanned, "queued": queued}


class SweepChannelPicker(discord.ui.View):
    # Dropdown of the server channels so an admin can sweep ANY channel from
    # wherever the command is run (e.g. the admin channel).
    def __init__(self, author_id, limit):
        super().__init__(timeout=120)
        self.author_id = int(author_id)
        self.limit = limit

    @discord.ui.select(cls=discord.ui.ChannelSelect,
                       channel_types=[discord.ChannelType.text],
                       placeholder="Pick a channel to sweep…",
                       min_values=1, max_values=1)
    async def _pick(self, interaction, select):
        if interaction.user.id != self.author_id:
            return await interaction.response.send_message("That picker is not yours.", ephemeral=True)
        picked = select.values[0]
        channel = interaction.guild.get_channel(picked.id) if interaction.guild else None
        if channel is None:
            return await interaction.response.edit_message(content="⚠️ Could not resolve that channel.", view=None)
        await interaction.response.edit_message(
            content=f"🧹 Sweeping **#{channel.name}** — check your DMs. (👀 = queued · ✅ = approved & pushed)",
            view=None)
        res = await _do_sweep(interaction.user, channel, self.limit)
        if not res.get("ok") and res.get("reason") == "nodm":
            await interaction.followup.send(
                "❌ I could not DM you. Enable **Direct Messages** for this server and try again.", ephemeral=True)


@bot.command(name="sweepboxscores")
async def sweepboxscores(ctx, channel: discord.TextChannel = None, limit: int = 50):
    """
    !sweepboxscores [#channel] [limit]
    Run it in your admin channel. With no #channel you get a dropdown of every
    channel to pick which one to sweep. Parses each box-score image and DMs you
    an interactive editor; approving pushes to the sheet and drops a ✅.
    """
    if not ctx.guild:
        return await ctx.send("Run this in your server, not a DM.")
    if not _sweep_is_admin(ctx):
        return await ctx.send("🔒 Owner/admin only.")

    if channel is None:
        # No channel typed -> show the dropdown of all channels.
        return await ctx.send("📋 **Pick a channel to sweep:**",
                              view=SweepChannelPicker(ctx.author.id, limit))

    await ctx.send(f"🧹 Sweeping **#{channel.name}** — check your DMs. "
                   f"(👀 = queued to you · ✅ = approved & pushed)")
    res = await _do_sweep(ctx.author, channel, limit)
    if not res.get("ok") and res.get("reason") == "nodm":
        await ctx.send("❌ I could not DM you. Enable **Direct Messages** for this server and try again.")

# ═══════════════════════════════════════════════════════════════════════════
#  QTCG ADMIN + SYNC  —  owner-only control over the whole ecosystem
#
#  PASTE: BEFORE bot.run(TOKEN) in QCL2K.py.
#
#  Fixes the "74 in Activity / 71 in bot" drift: the Activity writes
#  fantasy_save.json to the GITHUB REPO, but the bot reads a LOCAL file.
#  These commands read/write the SAME repo file, so both sides align.
#
#  Owner-only. Set BOT_OWNER_ID env (your Discord user id).
#
#  Commands (prefix !):
#    !synccards            pull the repo save -> show what the bot vs repo have
#    !pullsave             overwrite local save FROM the repo (repo = truth)
#    !pushsave             overwrite the repo save FROM local (bot = truth)
#    !givecoins @user N     grant N coins to a user
#    !takecoins @user N     remove N coins
#    !givecard @user Name   grant a card
#    !takecard @user Name   remove one copy of a card
#    !setmint Name N        set a card's mint count
#    !resetlineup @user     force-unlock someone's lineup
#    !userinfo @user        show a user's coins + card count + lineup
# ═══════════════════════════════════════════════════════════════════════════

_AS_OWNER_ID = int(_tvt_os.environ.get("BOT_OWNER_ID", "0"))


def _as_is_owner(ctx):
    return _AS_OWNER_ID and ctx.author.id == _AS_OWNER_ID


async def _as_gh_get_json(path):
    """Read a JSON file from the repo. Returns (obj, sha) or ({}, None)."""
    if not TVT_GH_TOKEN:
        return {}, None
    hdr = {"Authorization": f"Bearer {TVT_GH_TOKEN}", "Accept": "application/vnd.github+json",
           "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "QSPN-QTCG"}
    url = f"https://api.github.com/repos/{TVT_GH_REPO}/contents/{path}"
    try:
        async with _tvt_aiohttp.ClientSession() as s:
            async with s.get(url, params={"ref": TVT_GH_BRANCH}, headers=hdr) as r:
                if r.status == 200:
                    j = await r.json()
                    content = _tvt_base64.b64decode(j["content"]).decode("utf-8")
                    return _tvt_json.loads(content), j.get("sha")
    except Exception as e:
        print(f"[admin] gh_get {path}: {e}")
    return {}, None


def _as_user(save, uid):
    """Get-or-create a user entry with the full schema."""
    uid = str(uid)
    users = save.setdefault("users", {})
    return users.setdefault(uid, {
        "name": "", "coins": 0, "cards": [],
        "roster": {"G": None, "F": None, "C": None, "B1": None, "B2": None},
        "serials": {}, "cumulative_fp": 0.0, "history": []})


async def _as_load_repo_save():
    obj, sha = await _as_gh_get_json("fantasy_save.json")
    if not isinstance(obj, dict):
        obj = {"users": {}}
    obj.setdefault("users", {})
    return obj, sha


async def _as_save_repo(save, msg):
    return await _tvt_gh_put_json("fantasy_save.json", save, msg)


# ── SYNC ───────────────────────────────────────────────────────────────────
@bot.command(name="synccards")
async def _as_synccards(ctx):
    if not _as_is_owner(ctx):
        return await ctx.send("🔒 Owner only.")
    repo, _ = await _as_load_repo_save()
    local = _tvt_load_save()
    def total_cards(s):
        return sum(len(u.get("cards", [])) for u in s.get("users", {}).values())
    def uniq_cards(s):
        st = set()
        for u in s.get("users", {}).values():
            st.update(u.get("cards", []))
        return len(st)
    e = _tvt_discord.Embed(title="🔄 Save Sync Check", color=0xD4AF37)
    e.add_field(name="Repo (Activity)",
                value=f"users: {len(repo.get('users',{}))}\ntotal: {total_cards(repo)}\nunique: {uniq_cards(repo)}")
    e.add_field(name="Local (Bot)",
                value=f"users: {len(local.get('users',{}))}\ntotal: {total_cards(local)}\nunique: {uniq_cards(local)}")
    diff = total_cards(repo) - total_cards(local)
    e.add_field(name="Difference", value=f"{'+' if diff>=0 else ''}{diff} cards\n"
                f"`!pullsave` = use repo\n`!pushsave` = use bot", inline=False)
    await ctx.send(embed=e)


@bot.command(name="pullsave")
async def _as_pullsave(ctx):
    if not _as_is_owner(ctx):
        return await ctx.send("🔒 Owner only.")
    repo, _ = await _as_load_repo_save()
    if not repo.get("users"):
        return await ctx.send("⚠️ Repo save is empty — aborting to avoid data loss.")
    _tvt_write_save(repo)
    await ctx.send(f"✅ Local save overwritten from repo. "
                   f"{len(repo.get('users',{}))} users now in sync.")


@bot.command(name="pushsave")
async def _as_pushsave(ctx):
    if not _as_is_owner(ctx):
        return await ctx.send("🔒 Owner only.")
    local = _tvt_load_save()
    ok = await _as_save_repo(local, f"admin pushsave by {ctx.author}")
    await ctx.send("✅ Repo save overwritten from local." if ok else "❌ Push failed.")


# ── ECONOMY ADMIN ──────────────────────────────────────────────────────────
async def _as_edit_repo_user(ctx, member, mutate, msg):
    """Load repo save, mutate the target user, save back."""
    save, sha = await _as_load_repo_save()
    u = _as_user(save, member.id)
    if not u.get("name"):
        u["name"] = member.display_name
    result = mutate(u)
    ok = await _as_save_repo(save, msg)
    if not ok:
        await ctx.send("❌ Save failed (retry).")
        return None
    return result


@bot.command(name="givecoins")
async def _as_givecoins(ctx, member: _tvt_discord.Member, amount: int):
    if not _as_is_owner(ctx):
        return await ctx.send("🔒 Owner only.")
    def m(u): u["coins"] = int(u.get("coins", 0)) + amount; return u["coins"]
    bal = await _as_edit_repo_user(ctx, member, m, f"admin +{amount}c to {member}")
    if bal is not None:
        await ctx.send(f"💰 Gave **{amount}** coins to {member.mention}. Balance: **{bal}**.")


@bot.command(name="takecoins")
async def _as_takecoins(ctx, member: _tvt_discord.Member, amount: int):
    if not _as_is_owner(ctx):
        return await ctx.send("🔒 Owner only.")
    def m(u): u["coins"] = max(0, int(u.get("coins", 0)) - amount); return u["coins"]
    bal = await _as_edit_repo_user(ctx, member, m, f"admin -{amount}c from {member}")
    if bal is not None:
        await ctx.send(f"💰 Took **{amount}** coins from {member.mention}. Balance: **{bal}**.")


@bot.command(name="givecard")
async def _as_givecard(ctx, member: _tvt_discord.Member, *, card: str):
    if not _as_is_owner(ctx):
        return await ctx.send("🔒 Owner only.")
    def m(u): u.setdefault("cards", []).append(card); return len(u["cards"])
    n = await _as_edit_repo_user(ctx, member, m, f"admin +card '{card}' to {member}")
    if n is not None:
        await ctx.send(f"🃏 Gave **{card}** to {member.mention}. They now own {n} cards.")


@bot.command(name="takecard")
async def _as_takecard(ctx, member: _tvt_discord.Member, *, card: str):
    if not _as_is_owner(ctx):
        return await ctx.send("🔒 Owner only.")
    def m(u):
        cards = u.setdefault("cards", [])
        if card in cards:
            cards.remove(card); return True
        return False
    removed = await _as_edit_repo_user(ctx, member, m, f"admin -card '{card}' from {member}")
    if removed:
        await ctx.send(f"🗑️ Removed **{card}** from {member.mention}.")
    elif removed is False:
        await ctx.send(f"⚠️ {member.mention} doesn't own '{card}'.")


@bot.command(name="setmint")
async def _as_setmint(ctx, card: str, count: int):
    if not _as_is_owner(ctx):
        return await ctx.send("🔒 Owner only.")
    save, sha = await _as_load_repo_save()
    mint = save.setdefault("mint", {})
    mint[card] = count
    ok = await _as_save_repo(save, f"admin setmint {card}={count}")
    await ctx.send(f"🔢 Mint for **{card}** set to **{count}**." if ok else "❌ Save failed.")


@bot.command(name="resetlineup")
async def _as_resetlineup(ctx, member: _tvt_discord.Member):
    if not _as_is_owner(ctx):
        return await ctx.send("🔒 Owner only.")
    def m(u):
        u["roster_locked_at"] = 0
        return True
    await _as_edit_repo_user(ctx, member, m, f"admin reset lineup for {member}")
    await ctx.send(f"🔓 Unlocked {member.mention}'s lineup.")


@bot.command(name="userinfo")
async def _as_userinfo(ctx, member: _tvt_discord.Member):
    if not _as_is_owner(ctx):
        return await ctx.send("🔒 Owner only.")
    save, _ = await _as_load_repo_save()
    u = (save.get("users", {}) or {}).get(str(member.id))
    if not u:
        return await ctx.send(f"{member.mention} has no QTCG data yet.")
    cards = u.get("cards", [])
    roster = u.get("roster", {})
    filled = sum(1 for v in roster.values() if v)
    locked = u.get("roster_locked_at", 0)
    import time as _t
    lock_txt = "unlocked"
    if locked:
        rem = (locked + 48*3600) - _t.time()
        lock_txt = f"locked {rem/3600:.1f}h left" if rem > 0 else "unlocked (expired)"
    e = _tvt_discord.Embed(title=f"📇 {member.display_name}", color=0xD4AF37)
    e.add_field(name="Coins", value=str(u.get("coins", 0)))
    e.add_field(name="Cards", value=f"{len(cards)} ({len(set(cards))} unique)")
    e.add_field(name="Lineup", value=f"{filled}/5 · {lock_txt}", inline=False)
    await ctx.send(embed=e)


# ============================================================================
#  QCL COMMAND CENTER  --  one button-driven front door (additive; safe)
#  Pattern: buttons call a CTX-FREE service, never the command wrapper. That
#  seam is what lets a future web dashboard reuse the exact same backend.
# ============================================================================

async def qcl_svc_adjust_coins(uid, display_name, delta):
    """CTX-FREE economy service. Mirrors !givecoins with zero Discord coupling,
    so a command, a button, or a web route can all call it.
    Returns (ok, new_balance)."""
    save, _sha = await _as_load_repo_save()
    u = _as_user(save, uid)
    if display_name and not u.get("name"):
        u["name"] = display_name
    u["coins"] = max(0, int(u.get("coins", 0)) + int(delta))
    tag = ("+" if int(delta) >= 0 else "") + str(int(delta))
    ok = await _as_save_repo(save, f"panel: {tag}c -> {uid}")
    return (True, u["coins"]) if ok else (False, None)


