class _QCLUserPick(_tvt_discord.ui.UserSelect):
    def __init__(self, parent):
        super().__init__(placeholder="Pick a player…", min_values=1, max_values=1)
        self.parent_view = parent

    async def callback(self, interaction):
        self.parent_view.target = self.values[0]
        await interaction.response.send_message(
            f"🎯 Target set: {self.values[0].mention}", ephemeral=True
        )


class QCLCoinModal(_tvt_discord.ui.Modal):
    def __init__(self, target, sign):
        super().__init__(title=("Give Coins" if sign > 0 else "Take Coins"))
        self.target = target
        self.sign = sign
        self.amount = _tvt_discord.ui.TextInput(
            label="Amount", placeholder="e.g. 500", required=True, max_length=12
        )
        self.add_item(self.amount)

    async def on_submit(self, interaction):
        try:
            amt = abs(int(str(self.amount.value).strip()))
        except Exception:
            return await interaction.response.send_message(
                "❌ Amount must be a whole number.", ephemeral=True
            )
        ok, bal = await qcl_svc_adjust_coins(self.target.id, self.target.display_name, self.sign * amt)
        if not ok:
            return await interaction.response.send_message("❌ Save failed (retry).", ephemeral=True)
        verb, prep = ("Gave", "to") if self.sign > 0 else ("Took", "from")
        await interaction.response.send_message(
            f"💰 {verb} **{amt}** coins {prep} {self.target.mention}. Balance: **{bal}**.",
            ephemeral=True,
        )


class QCLAdminView(_tvt_discord.ui.View):
    def __init__(self, opener_id):
        super().__init__(timeout=180)
        self.opener_id = opener_id
        self.target = None
        self.add_item(_QCLUserPick(self))

    async def interaction_check(self, interaction):
        if interaction.user.id != _AS_OWNER_ID:
            await interaction.response.send_message("🔒 Owner only.", ephemeral=True)
            return False
        return True

    @_tvt_discord.ui.button(label="➕ Give Coins", style=_tvt_discord.ButtonStyle.success, row=1)
    async def _give(self, interaction, button):
        if not self.target:
            return await interaction.response.send_message("Pick a player first.", ephemeral=True)
        await interaction.response.send_modal(QCLCoinModal(self.target, +1))

    @_tvt_discord.ui.button(label="➖ Take Coins", style=_tvt_discord.ButtonStyle.danger, row=1)
    async def _take(self, interaction, button):
        if not self.target:
            return await interaction.response.send_message("Pick a player first.", ephemeral=True)
        await interaction.response.send_modal(QCLCoinModal(self.target, -1))

    @_tvt_discord.ui.button(label="⬅ Back", style=_tvt_discord.ButtonStyle.secondary, row=2)
    async def _back(self, interaction, button):
        await interaction.response.edit_message(embed=_qcl_home_embed(), view=QCLHomeView(self.opener_id))


