class QCLJoinModal(_tvt_discord.ui.Modal, title="Join QCL"):
    def __init__(self, default_name=""):
        super().__init__(timeout=300)
        self.f_name = _tvt_discord.ui.TextInput(label="Display name", default=default_name,
                                                max_length=32, required=True)
        self.f_gt = _tvt_discord.ui.TextInput(label="PSN / Xbox gamertag", max_length=40, required=True)
        self.f_team = _tvt_discord.ui.TextInput(label="Team / school (optional)", required=False, max_length=40)
        self.f_pos = _tvt_discord.ui.TextInput(label="Position — PG/SG/SF/PF/C (optional)",
                                               required=False, max_length=2)
        for it in (self.f_name, self.f_gt, self.f_team, self.f_pos):
            self.add_item(it)

    async def on_submit(self, interaction):
        import time as _t
        d = _reg_load()
        uid = str(interaction.user.id)
        ex = d.get(uid, {})
        d[uid] = {
            "discord_id": uid, "discord_tag": interaction.user.name,
            "display_name": (self.f_name.value or interaction.user.display_name).strip(),
            "gamertag": self.f_gt.value.strip(),
            "position": (self.f_pos.value or ex.get("position", "")).strip().upper(),
            "team": (self.f_team.value or ex.get("team", "")).strip(),
            "twitter": ex.get("twitter", ""), "twitch": ex.get("twitch", ""),
            "psn": ex.get("psn", ""), "xbox": ex.get("xbox", ""), "youtube": ex.get("youtube", ""),
            "registered_by": ex.get("registered_by", uid),
            "registered_at": ex.get("registered_at", int(_t.time())),
        }
        _reg_save(d)
        _reg_publish()
        await interaction.response.edit_message(
            embed=_qcl_onboard_socials_embed(d[uid]), view=QCLSocialsView()
        )


class QCLSocialsModal(_tvt_discord.ui.Modal, title="Link your socials"):
    def __init__(self, rec=None):
        super().__init__(timeout=300)
        rec = rec or {}
        self.f_tw = _tvt_discord.ui.TextInput(label="Twitter/X (no @)", default=rec.get("twitter", ""),
                                              required=False, max_length=40)
        self.f_tv = _tvt_discord.ui.TextInput(label="Twitch", default=rec.get("twitch", ""),
                                              required=False, max_length=40)
        self.f_yt = _tvt_discord.ui.TextInput(label="YouTube", default=rec.get("youtube", ""),
                                              required=False, max_length=60)
        self.f_psn = _tvt_discord.ui.TextInput(label="PSN ID", default=rec.get("psn", ""),
                                               required=False, max_length=40)
        self.f_xb = _tvt_discord.ui.TextInput(label="Xbox Gamertag", default=rec.get("xbox", ""),
                                              required=False, max_length=40)
        for it in (self.f_tw, self.f_tv, self.f_yt, self.f_psn, self.f_xb):
            self.add_item(it)

    async def on_submit(self, interaction):
        d = _reg_load()
        uid = str(interaction.user.id)
        if uid not in d:
            return await interaction.response.send_message(
                "You're not registered yet — tap **Join QCL** first.", ephemeral=True)
        for field, val in (("twitter", self.f_tw.value), ("twitch", self.f_tv.value),
                           ("youtube", self.f_yt.value), ("psn", self.f_psn.value),
                           ("xbox", self.f_xb.value)):
            d[uid][field] = val.strip().lstrip("@")
        _reg_save(d)
        _reg_publish()
        await interaction.response.edit_message(
            embed=_qcl_profile_embed(d[uid]), view=QCLProfileView()
        )


