@bot.tree.command(name="draft_close", description="[ADMIN] Close the active draft without deleting its results.")
async def draft_close(interaction: discord.Interaction):
    if not _draft_admin(interaction):
        return await interaction.response.send_message(
            "🔒 Admins or league managers only.", ephemeral=True
        )
    state, draft = _draft_data()
    if draft.get("status") != "active":
        return await interaction.response.send_message(
            "There is no active draft to close.", ephemeral=True
        )
    draft["status"] = "closed"
    draft["closed_at"] = _now_str()
    draft["deadline_at"] = None
    save_state(state)
    channel = (
        interaction.guild.get_channel(int(draft.get("draft_channel_id", 0)))
        if interaction.guild else None
    )
    if channel:
        await channel.send(
            "🛑 **Draft paused by league administration.** "
            "Results already recorded are preserved."
        )
    await interaction.response.send_message(
        "✅ Draft closed safely. Existing picks were preserved.",
        ephemeral=True,
    )


@tasks.loop(seconds=15)
async def draft_clock_loop():
    """Enforce pick deadlines and advance forfeited turns."""
    try:
        state, draft = _draft_data()
        if (
            draft.get("status") != "active"
            or time.time() < float(draft.get("deadline_at") or 0)
        ):
            return
        turn = _draft_turn(draft)
        if not turn:
            draft["status"] = "complete"
            save_state(state)
            return
        _draft_advance(draft)
        save_state(state)
        for guild in bot.guilds:
            if guild.id not in ALLOWED_GUILD_IDS:
                continue
            channel = guild.get_channel(int(draft.get("draft_channel_id", 0)))
            if channel is None:
                continue
            message = (
                f"⏰ **{turn['team']}** timed out on pick **#{turn['pick']}**; "
                "the pick was forfeited."
            )
            next_turn = _draft_turn(draft)
            if next_turn:
                message += (
                    f"\n**{next_turn['team']}** is now on the clock for "
                    f"pick **#{next_turn['pick']}**."
                )
            else:
                message += "\n🏆 **The draft is complete.**"
            await channel.send(message)
            break
    except Exception as exc:
        print(f"[Draft] Clock error: {exc}")


@draft_clock_loop.before_loop
async def _draft_clock_wait_ready():
    await bot.wait_until_ready()


@bot.listen("on_ready")
async def _qcl_registry_sync_on_startup():
    # Publish existing registrations too; do not wait for a new signup.
    _qcl_export_public_registrations(load_state())


# ═══════════════════════════════════════════════════════════════════════════
#  SAFE SEASON LIFECYCLE
#  Creates, restarts, and removes schedule seasons without the role deletion
#  performed by the legacy !resetseason command. Every replacement is archived.
# ═══════════════════════════════════════════════════════════════════════════

season_admin_group = app_commands.Group(
    name="season_admin",
    description="Admin season lifecycle: create, restart, archive, and remove",
)
bot.tree.add_command(season_admin_group)


def _season_admin_archive(state, schedule, action, actor_id):
    if not schedule:
        return None
    stamp = _security_datetime.datetime.now(
        _security_datetime.timezone.utc
    ).strftime("%Y%m%dT%H%M%SZ")
    archive_id = f"{stamp}-{action}"
    archive = state.setdefault("season_schedule_archive", {})
    archive[archive_id] = {
        "action": action,
        "actor_id": str(actor_id),
        "archived_at": _security_datetime.datetime.now(
            _security_datetime.timezone.utc
        ).isoformat(),
        "schedule": json.loads(json.dumps(schedule)),
    }
    # Keep the state file bounded while retaining the most recent recoveries.
    for old_id in sorted(archive)[:-25]:
        archive.pop(old_id, None)
    return archive_id


def _season_admin_make_schedule(
    name, days, start_date, reveal_hour, channel_id, window_hours, teams
):
    schedule = {
        "name": name,
        "status": "active",
        "days": days,
        "start_date": start_date,
        "reveal_hour": reveal_hour,
        "channel_id": channel_id,
        "window_hours": window_hours,
        "makeup_weekdays": [4, 5],
        "makeup_dates": [],
        "teams": teams,
        "schedule": {},
        "byes": {},
        "revealed_days": [],
        "created_at": _eastern_now().isoformat(),
    }
    _sched_rebuild_future(schedule, force_from=0)
    return schedule


@season_admin_group.command(
    name="create",
    description="[ADMIN] Create and activate a season with automatic scheduling",
)
@app_commands.describe(
    name="Season name",
    days="Calendar days in the season (1-120)",
    start_date="First day in YYYY-MM-DD format",
    channel="Channel for automatic daily matchup reveals",
    teams="Optional comma-separated teams; defaults to active league teams",
    reveal_hour="Eastern hour for daily reveal (0-23)",
    window_hours="Hours teams have to complete a revealed matchup",
    pin="Admin PIN",
)
async def season_admin_create(
    interaction: discord.Interaction,
    name: str,
    days: int,
    start_date: str,
    channel: discord.TextChannel,
    pin: str,
    teams: str = None,
    reveal_hour: int = SCHED_DEFAULT_REVEAL_HOUR,
    window_hours: int = 36,
):
    if not await verify_admin_pin(interaction, pin, "season_admin_create"):
        return
    try:
        _security_datetime.date.fromisoformat(start_date)
    except ValueError:
        return await interaction.response.send_message(
            "❌ start_date must be `YYYY-MM-DD`.", ephemeral=True
        )
    if not 1 <= days <= 120 or not 0 <= reveal_hour <= 23 or not 1 <= window_hours <= 96:
        return await interaction.response.send_message(
            "❌ Use 1-120 days, reveal hour 0-23, and window 1-96 hours.",
            ephemeral=True,
        )

    state = load_state()
    if teams:
        team_list = list(dict.fromkeys(t.strip() for t in teams.split(",") if t.strip()))
    else:
        team_list = [
            team["name"]
            for team in get_league_teams(state, interaction.guild)
            if team["status"] == "active"
        ]
    if len(team_list) < 2:
        return await interaction.response.send_message(
            "❌ A season needs at least two teams.", ephemeral=True
        )

    previous = state.get("season_schedule") or {}
    archive_id = _season_admin_archive(
        state, previous, "replaced-by-create", interaction.user.id
    )
    schedule = _season_admin_make_schedule(
        name,
        days,
        start_date,
        reveal_hour,
        channel.id,
        window_hours,
        team_list,
    )
    state["season_schedule"] = schedule
    save_state(state)
    _write_schedule_backup(schedule)
    await _dm_schedule_to_owner(schedule, reason=f"season created: {name}")
    archived = f"\nPrevious schedule archived as `{archive_id}`." if archive_id else ""
    await interaction.response.send_message(
        f"✅ **{name}** is active with **{len(team_list)} teams** across "
        f"**{days} days**. Daily reveals will post in {channel.mention} at "
        f"**{reveal_hour}:00 ET**.{archived}",
        ephemeral=True,
    )


@season_admin_group.command(
    name="restart",
    description="[ADMIN] Archive and rebuild the active season from day one",
)
@app_commands.describe(
    start_date="New first day in YYYY-MM-DD format",
    pin="Admin PIN",
    clear_results="Also clear schedule-linked result and reveal markers",
)
async def season_admin_restart(
    interaction: discord.Interaction,
    start_date: str,
    pin: str,
    clear_results: bool = True,
):
    if not await verify_admin_pin(interaction, pin, "season_admin_restart"):
        return
    try:
        _security_datetime.date.fromisoformat(start_date)
    except ValueError:
        return await interaction.response.send_message(
            "❌ start_date must be `YYYY-MM-DD`.", ephemeral=True
        )
    state = load_state()
    current = state.get("season_schedule") or {}
    if not current:
        return await interaction.response.send_message(
            "❌ There is no season to restart. Use `/season_admin create`.",
            ephemeral=True,
        )

    archive_id = _season_admin_archive(
        state, current, "restart", interaction.user.id
    )
    restarted = _season_admin_make_schedule(
        current.get("name", "QCL Season"),
        int(current.get("days", 14)),
        start_date,
        int(current.get("reveal_hour", SCHED_DEFAULT_REVEAL_HOUR)),
        int(current.get("channel_id") or interaction.channel_id),
        int(current.get("window_hours", 36)),
        list(current.get("teams", [])),
    )
    restarted["makeup_weekdays"] = list(current.get("makeup_weekdays", [4, 5]))
    restarted["makeup_dates"] = []
    restarted["restart_of"] = archive_id
    if not clear_results:
        restarted["results"] = json.loads(json.dumps(current.get("results", {})))
    _sched_rebuild_future(restarted, force_from=0)
    state["season_schedule"] = restarted
    save_state(state)
    _write_schedule_backup(restarted)
    await _dm_schedule_to_owner(restarted, reason="season restarted")
    await interaction.response.send_message(
        f"✅ **{restarted['name']}** restarted for **{start_date}**. The prior "
        f"season is recoverable from archive `{archive_id}`.",
        ephemeral=True,
    )


@season_admin_group.command(
    name="delete",
    description="[ADMIN] Archive and remove the active season schedule",
)
@app_commands.describe(
    confirmation="Type DELETE to confirm",
    pin="Admin PIN",
)
async def season_admin_delete(
    interaction: discord.Interaction, confirmation: str, pin: str
):
    if not await verify_admin_pin(interaction, pin, "season_admin_delete"):
        return
    if confirmation != "DELETE":
        return await interaction.response.send_message(
            "❌ Nothing changed. Type `DELETE` exactly to confirm.", ephemeral=True
        )
    state = load_state()
    current = state.get("season_schedule") or {}
    if not current:
        return await interaction.response.send_message(
            "No active season schedule exists.", ephemeral=True
        )
    archive_id = _season_admin_archive(
        state, current, "delete", interaction.user.id
    )
    state.pop("season_schedule", None)
    save_state(state)
    await interaction.response.send_message(
        f"✅ Season **{current.get('name', 'Unnamed')}** was removed and archived "
        f"as `{archive_id}`. Player registrations and historical stats were not deleted.",
        ephemeral=True,
    )


@season_admin_group.command(
    name="status",
    description="Show the active season and available recovery archives",
)
async def season_admin_status(interaction: discord.Interaction):
    state = load_state()
    current = state.get("season_schedule") or {}
    archives = state.get("season_schedule_archive") or {}
    if not current:
        return await interaction.response.send_message(
            f"No active schedule. **{len(archives)}** archived season version(s) are retained.",
            ephemeral=True,
        )
    await interaction.response.send_message(
        f"**{current.get('name', 'QCL Season')}** · {current.get('status', 'active')}\n"
        f"Starts: **{current.get('start_date', '?')}** · Days: **{current.get('days', '?')}** · "
        f"Teams: **{len(current.get('teams', []))}**\n"
        f"Recovery archives retained: **{len(archives)}**",
        ephemeral=True,
    )


